method check_matches_at(haystack: seq<int>, needle: seq<int>, start_index: int) returns (res: bool)
    ensures res == matches_at(haystack, needle, start_index)
{
    if start_index < 0 || start_index + |needle| > |haystack| {
        return false;
    }
    var i := 0;
    while i < |needle|
        invariant 0 <= i <= |needle|
        invariant forall j :: 0 <= j < i ==> haystack[start_index + j] == needle[j]
    {
        if haystack[start_index + i] != needle[i] {
            return false;
        }
        i := i + 1;
    }
    return true;
}

