predicate ResultsSound(
    haystack: seq<int>,
    patterns: seq<seq<int>>,
    results: seq<(int, int)>)
{
    forall k :: 0 <= k < |results| ==>
        var (pid, idx) := results[k];
        pid >= 0 && idx >= 0
        && 0 <= pid < |patterns|
        && matches_at(haystack, patterns[pid], idx)
}

predicate CoveredPids(
    haystack: seq<int>,
    patterns: seq<seq<int>>,
    upto: int,
    results: seq<(int, int)>)
    requires 0 <= upto <= |patterns|
{
    forall pid, idx ::
        0 <= pid < upto
        && matches_at(haystack, patterns[pid], idx)
        ==> (pid, idx) in results
}

predicate CoveredStarts(
    haystack: seq<int>,
    pattern: seq<int>,
    pid: int,
    upto: int,
    results: seq<(int, int)>)
{
    forall idx ::
        0 <= idx < upto
        && matches_at(haystack, pattern, idx)
        ==> (pid, idx) in results
}

lemma PairMemberAppend(
    s: seq<(int, int)>,
    x: (int, int),
    y: (int, int))
    requires x in s
    ensures x in s + [y]
{
    var k :| 0 <= k < |s| && s[k] == x;
    assert (s + [y])[k] == s[k];
}

lemma PairMemberHasIndex(s: seq<(int, int)>, x: (int, int))
    requires x in s
    ensures exists k :: 0 <= k < |s| && s[k] == x
{
    var k :| 0 <= k < |s| && s[k] == x;
}

lemma ExtendSound(
    haystack: seq<int>,
    patterns: seq<seq<int>>,
    results: seq<(int, int)>,
    pid: int,
    idx: int)
    requires ResultsSound(haystack, patterns, results)
    requires 0 <= pid < |patterns|
    requires 0 <= idx
    requires matches_at(haystack, patterns[pid], idx)
    ensures ResultsSound(
        haystack, patterns, results + [(pid, idx)])
{
    forall k | 0 <= k < |results + [(pid, idx)]|
        ensures
            var (p, start) := (results + [(pid, idx)])[k];
            p >= 0 && start >= 0
            && 0 <= p < |patterns|
            && matches_at(haystack, patterns[p], start)
    {
        if k < |results| {
            assert (results + [(pid, idx)])[k] == results[k];
        } else {
            assert k == |results|;
            assert (results + [(pid, idx)])[k] == (pid, idx);
        }
    }
}

