method ac_automata_search(
    haystack: seq<int>,
    patterns: seq<seq<int>>)
    returns (results: seq<(int, int)>)
    requires |patterns| > 0
    requires |haystack| < 1000000
    requires |patterns| < 1000000
    requires forall i :: 0 <= i < |patterns| ==> |patterns[i]| < 1000000
    ensures
        forall i :: 0 <= i < |results| ==>
            var (pid, idx) := results[i];

            && pid >= 0 && idx >= 0
            && 0 <= pid < |patterns|
            && matches_at(haystack, patterns[pid], idx)
    ensures
        forall pid, idx ::
            0 <= pid < |patterns|
            && matches_at(haystack, patterns[pid], idx) ==>
            exists k ::
                0 <= k < |results|
                && results[k] == (pid, idx)
{
    results := [];
    var pid := 0;

    while pid < |patterns|
        invariant 0 <= pid <= |patterns|
        invariant ResultsSound(haystack, patterns, results)
        invariant CoveredPids(haystack, patterns, pid, results)
        decreases |patterns| - pid
    {
        var idx := 0;

        while idx <= |haystack|
            invariant 0 <= idx <= |haystack| + 1
            invariant ResultsSound(haystack, patterns, results)
            invariant CoveredPids(haystack, patterns, pid, results)
            invariant CoveredStarts(
                haystack, patterns[pid], pid, idx, results)
            decreases |haystack| + 1 - idx
        {
            if matches_at(haystack, patterns[pid], idx) {
                var previous := results;
                results := previous + [(pid, idx)];

                ExtendSound(
                    haystack, patterns, previous, pid, idx);
                ExtendCoveredPids(
                    haystack, patterns, pid,
                    previous, (pid, idx));
                ExtendCoveredStarts(
                    haystack, patterns[pid], pid, idx,
                    previous, (pid, idx));

                assert results[|previous|] == (pid, idx);
                assert (pid, idx) in results;
            }

            assert matches_at(haystack, patterns[pid], idx)
                   ==> (pid, idx) in results;

            AdvanceCoveredStarts(
                haystack, patterns[pid], pid, idx, results);
            idx := idx + 1;
        }

        assert idx == |haystack| + 1;
        AddFinishedPid(haystack, patterns, pid, results);
        pid := pid + 1;
    }

    forall p, idx |
        0 <= p < |patterns|
        && matches_at(haystack, patterns[p], idx)
        ensures exists k ::
            0 <= k < |results|
            && results[k] == (p, idx)
    {
        assert (p, idx) in results;
        PairMemberHasIndex(results, (p, idx));
    }
}

