ghost predicate bfs_within(g: Graph, start: int, v: int, k: int)
{
  0 <= k &&
  exists p: seq<int> {:trigger is_path(g, p)} ::
    is_path(g, p) &&
    p[0] == start &&
    p[|p| - 1] == v &&
    |p| <= k + 1
}

ghost predicate bfs_one_step(g: Graph, start: int, v: int, k: int)
{
  exists u: int ::
    0 <= u < size(g) &&
    bfs_within(g, start, u, k) &&
    has_edge(g, u, v)
}

ghost predicate bfs_closed(g: Graph, seen: seq<bool>)
{
  |seen| == size(g) &&
  forall u: int, v: int ::
    0 <= u < size(g) &&
    0 <= v < size(g) &&
    seen[u] &&
    has_edge(g, u, v)
    ==> seen[v]
}

ghost function bfs_missing(seen: seq<bool>): set<int>
{
  set i: int | 0 <= i < |seen| && !seen[i]
}

lemma bfs_edge_bounds(g: Graph, u: int, v: int)
  requires well_formed(g)
  requires has_edge(g, u, v)
  ensures 0 <= u < size(g)
  ensures 0 <= v < size(g)
{
  var i :| 0 <= u < |g.adj| &&
           0 <= i < |g.adj[u]| &&
           g.adj[u][i] == v;
  assert 0 <= g.adj[u][i] < |g.adj|;
}

lemma bfs_path_prefix(g: Graph, p: seq<int>, n: int)
  requires is_path(g, p)
  requires 1 <= n <= |p|
  ensures is_path(g, p[..n])
{
  assert |p[..n]| == n;
  forall i: int | 0 <= i < n - 1
    ensures has_edge(g, p[..n][i], p[..n][i + 1])
  {
    assert p[..n][i] == p[i];
    assert p[..n][i + 1] == p[i + 1];
  }
}

lemma bfs_path_append(g: Graph, p: seq<int>, v: int)
  requires is_path(g, p)
  requires has_edge(g, p[|p| - 1], v)
  ensures is_path(g, p + [v])
{
  assert |p + [v]| == |p| + 1;
  forall i: int | 0 <= i < |p + [v]| - 1
    ensures has_edge(g, (p + [v])[i], (p + [v])[i + 1])
  {
    if i < |p| - 1 {
      assert (p + [v])[i] == p[i];
      assert (p + [v])[i + 1] == p[i + 1];
    } else {
      assert i == |p| - 1;
      assert (p + [v])[i] == p[|p| - 1];
      assert (p + [v])[i + 1] == v;
    }
  }
}

lemma bfs_within_zero(g: Graph, start: int, v: int)
  ensures bfs_within(g, start, v, 0) <==> v == start
{
  if v == start {
    var p := [start];
    assert is_path(g, p);
    assert bfs_within(g, start, v, 0);
  }

  if bfs_within(g, start, v, 0) {
    var p :| is_path(g, p) &&
             p[0] == start &&
             p[|p| - 1] == v &&
             |p| <= 1;
    assert |p| > 0;
    assert |p| == 1;
    assert p[0] == p[|p| - 1];
  }
}

lemma bfs_within_step(g: Graph, start: int, v: int, k: int)
  requires well_formed(g)
  requires 0 <= k
  requires 0 <= start < size(g)
  requires 0 <= v < size(g)
  ensures bfs_within(g, start, v, k + 1) <==>
          bfs_within(g, start, v, k) ||
          bfs_one_step(g, start, v, k)
{
  if bfs_within(g, start, v, k + 1) {
    var p :| is_path(g, p) &&
             p[0] == start &&
             p[|p| - 1] == v &&
             |p| <= k + 2;

    if |p| <= k + 1 {
      assert bfs_within(g, start, v, k);
    } else {
      assert |p| == k + 2;
      assert |p| >= 2;

      var u := p[|p| - 2];
      var q := p[..|p| - 1];

      bfs_path_prefix(g, p, |p| - 1);
      assert is_path(g, q);
      assert q[0] == start;
      assert q[|q| - 1] == u;
      assert |q| == k + 1;
      assert has_edge(g, u, v);

      bfs_edge_bounds(g, u, v);
      assert bfs_within(g, start, u, k);
      assert bfs_one_step(g, start, v, k);
    }
  }

  if bfs_within(g, start, v, k) {
    var p :| is_path(g, p) &&
             p[0] == start &&
             p[|p| - 1] == v &&
             |p| <= k + 1;
    assert |p| <= k + 2;
    assert bfs_within(g, start, v, k + 1);
  }

  if bfs_one_step(g, start, v, k) {
    var u :| 0 <= u < size(g) &&
              bfs_within(g, start, u, k) &&
              has_edge(g, u, v);
    var p :| is_path(g, p) &&
             p[0] == start &&
             p[|p| - 1] == u &&
             |p| <= k + 1;

    bfs_path_append(g, p, v);
    var q := p + [v];
    assert is_path(g, q);
    assert q[0] == start;
    assert q[|q| - 1] == v;
    assert |q| <= k + 2;
    assert bfs_within(g, start, v, k + 1);
  }
}

lemma bfs_minimal_is_shortest(
  g: Graph, start: int, target: int, k: int)
  requires 0 <= k
  requires bfs_within(g, start, target, k)
  requires !bfs_within(g, start, target, k - 1)
  ensures is_shortest_distance(g, start, target, k)
{
  var p :| is_path(g, p) &&
           p[0] == start &&
           p[|p| - 1] == target &&
           |p| <= k + 1;

  if |p| < k + 1 {
    assert |p| <= k;
    assert 0 <= k - 1;
    assert bfs_within(g, start, target, k - 1);
  }
  assert |p| == k + 1;

