      }
      assert bfs_closed(graph, next);
    }

    assert !oldSeen[target];
    assert !bfs_within(graph, start, target, round);

    seen := next;
    round := round + 1;
  }

  if seen[target] {
    assert bfs_within(graph, start, target, round);
    assert !bfs_within(graph, start, target, round - 1);
    bfs_minimal_is_shortest(graph, start, target, round);
    res := Some(round);
  } else {
    assert !changed;
    assert bfs_closed(graph, seen);
    assert seen[start];
    bfs_closed_not_reachable(
      graph, seen, start, target);
    res := None;
  }
