lemma UniqueEdgeWeight(
    graph: WeightedGraph,
    u: int,
    v: int,
    w1: int,
    w2: int
)
    requires well_formed(graph)
    requires has_edge(view(graph), u, v, w1)
    requires has_edge(view(graph), u, v, w2)
    ensures w1 == w2
{
    var i :| 0 <= u < |graph.adj| &&
             0 <= i < |graph.adj[u]| &&
             graph.adj[u][i].0 == v &&
             graph.adj[u][i].1 == w1;
    var j :| 0 <= u < |graph.adj| &&
             0 <= j < |graph.adj[u]| &&
             graph.adj[u][j].0 == v &&
             graph.adj[u][j].1 == w2;
    if i != j {
        assert graph.adj[u][i].0 != graph.adj[u][j].0;
        assert false;
    }
}

lemma GetEdgeWeightLemma(
