    assert forall i: int :: 0 <= i < |p[..n]| - 1 ==>
        connected(g, p[..n][i], p[..n][i + 1]) by {
        forall i: int | 0 <= i < |p[..n]| - 1
            ensures connected(g, p[..n][i], p[..n][i + 1])
        {
            assert p[..n][i] == p[i];
            assert p[..n][i + 1] == p[i + 1];
        }
    }
}

lemma PathSlice(g: seq<seq<(int, int)>>, p: seq<int>, lo: int, hi: int)
    requires is_path(g, p)
    requires 0 <= lo < hi <= |p|
    ensures is_path(g, p[lo..hi])
{
