                    view(graph), start, v,
                    size(graph) - 1, witness) &&
                path_weight(view(graph), witness) == d;

            assert forall p: seq<int>
                {:trigger is_path(view(graph), p)} ::
                is_path(view(graph), p) &&
                p[0] == start &&
                p[|p| - 1] == v ==>
                path_weight(view(graph), p) >= d by {
                forall p: seq<int>
                    {:trigger is_path(view(graph), p)}
