method bfs_edge_from_seen(
  g: Graph, seen: seq<bool>, v: int) returns (found: bool)
  requires |seen| == size(g)
  requires 0 <= v < size(g)
  ensures found <==>
    exists u: int ::
      0 <= u < size(g) &&
      seen[u] &&
      has_edge(g, u, v)
{
  found := false;
  var u := 0;

  while u < |g.adj|
    invariant 0 <= u <= |g.adj|
    invariant found <==> bfs_edge_prefix(g, seen, v, u, 0)
    decreases |g.adj| - u
  {
    var i := 0;

    while i < |g.adj[u]|
      invariant 0 <= i <= |g.adj[u]|
      invariant found <==> bfs_edge_prefix(g, seen, v, u, i)
      decreases |g.adj[u]| - i
    {
      if seen[u] && g.adj[u][i] == v {
        found := true;
      }

      i := i + 1;
    }

    bfs_prefix_next(g, seen, v, u);
    u := u + 1;
  }

  if found {
    ghost var x, j :| 0 <= x < size(g) &&
                          0 <= j < |g.adj[x]| &&
                          seen[x] &&
                          g.adj[x][j] == v &&
                          (x < size(g) ||
                           (x == size(g) && j < 0));
    assert has_edge(g, x, v);
  }

  if exists x: int ::
       0 <= x < size(g) &&
       seen[x] &&
       has_edge(g, x, v)
  {
    ghost var x :| 0 <= x < size(g) &&
                   seen[x] &&
                   has_edge(g, x, v);
    ghost var j :| 0 <= x < |g.adj| &&
                   0 <= j < |g.adj[x]| &&
                   g.adj[x][j] == v;
    assert bfs_edge_prefix(g, seen, v, size(g), 0);
    assert found;
  }
}

method bfs_expand(g: Graph, seen: seq<bool>)
    returns (next: seq<bool>)
  requires |seen| == size(g)
  ensures |next| == size(g)
  ensures forall v: int ::
    0 <= v < size(g) ==>
      (next[v] <==>
        seen[v] ||
        (exists u: int ::
          0 <= u < size(g) &&
          seen[u] &&
          has_edge(g, u, v)))
  ensures forall v: int ::
    0 <= v < size(g) && seen[v] ==> next[v]
{
  next := seen;
  var v := 0;

  while v < |g.adj|
    invariant 0 <= v <= |g.adj|
    invariant |next| == |g.adj|
    invariant forall x: int ::
      0 <= x < v ==>
        (next[x] <==>
          seen[x] ||
          (exists u: int ::
            0 <= u < size(g) &&
            seen[u] &&
            has_edge(g, u, x)))
    invariant forall x: int ::
      v <= x < |g.adj| ==> next[x] == seen[x]
    decreases |g.adj| - v
  {
    var found := bfs_edge_from_seen(g, seen, v);
    next := next[v := seen[v] || found];
    v := v + 1;
  }
}

lemma bfs_expand_semantics(
  g: Graph, start: int, seen: seq<bool>,
  next: seq<bool>, round: int)
  requires well_formed(g)
  requires 0 <= start < size(g)
  requires 0 <= round
  requires |seen| == size(g)
  requires |next| == size(g)
  requires forall v: int ::
    0 <= v < size(g) ==>
      (seen[v] <==> bfs_within(g, start, v, round))
  requires forall v: int ::
    0 <= v < size(g) ==>
      (next[v] <==>
        seen[v] ||
        (exists u: int ::
          0 <= u < size(g) &&
          seen[u] &&
          has_edge(g, u, v)))
  ensures forall v: int ::
    0 <= v < size(g) ==>
      (next[v] <==> bfs_within(g, start, v, round + 1))
{
  forall v: int | 0 <= v < size(g)
    ensures next[v] <==>
            bfs_within(g, start, v, round + 1)
  {
    bfs_within_step(g, start, v, round);
    assert
