    assert p[0] == p[|p| - 1];
  }
}

lemma bfs_within_step(g: Graph, start: int, v: int, k: int)
  requires well_formed(g)
  requires 0 <= k
  requires 0 <= start < size(g)
  requires 0 <= v < size(g)
  ensures bfs_within(g, start, v, k + 1) <==>
          bfs_within(g, start, v, k) ||
          bfs_one_step(g, start, v, k)
{
  if bfs_within(g, start, v, k + 1) {
    var p :| is_path(g, p) &&
             p[0] == start &&
             p[|p| - 1] == v &&
             |p| <= k + 2;

    if |p| <= k + 1 {
      assert bfs_within(g, start, v, k);
    } else {
      assert |p| == k + 2;
      assert |p| >= 2;

      var u := p[|p| - 2];
      var q := p[..|p| - 1];

      bfs_path_prefix(g, p, |p| - 1);
      assert is_path(g, q);
      assert q[0] == start;
      assert q[|q| - 1] == u;
      assert |q| == k + 1;
      assert has_edge(g, u, v);

      bfs_edge_bounds(g, u, v);
      assert bfs_within(g, start, u, k);
      assert bfs_one_step(g, start, v, k);
    }
  }

  if bfs_within(g, start, v, k) {
    var p :| is_path(g, p) &&
             p[0] == start &&
             p[|p| - 1] == v &&
             |p| <= k + 1;
    assert |p| <= k + 2;
    assert bfs_within(g, start, v, k + 1);
  }

  if bfs_one_step(g, start, v, k) {
    var u :| 0 <= u < size(g) &&
              bfs_within(g, start, u, k) &&
              has_edge(g, u, v);
    var p :| is_path(g, p) &&
             p[0] == start &&
             p[|p| - 1] == u &&
             |p| <= k + 1;

    bfs_path_append(g, p, v);
    var q := p + [v];
    assert is_path(g, q);
    assert q[0] == start;
    assert q[|q| - 1] == v;
    assert |q| <= k + 2;
    assert bfs_within(g, start, v, k + 1);
  }
}

lemma bfs_minimal_is_shortest(
  g: Graph, start: int, target: int, k: int)
  requires 0 <= k
  requires bfs_within(g, start, target, k)
  requires !bfs_within(g, start, target, k - 1)
  ensures is_shortest_distance(g, start, target, k)
{
  var p :| is_path(g, p) &&
           p[0] == start &&
           p[|p| - 1] == target &&
           |p| <= k + 1;

  if |p| < k + 1 {
    assert |p| <= k;
    assert 0 <= k - 1;
    assert bfs_within(g, start, target, k - 1);
  }
  assert |p| == k + 1;

  assert exists q: seq<int> {:trigger is_path(g, q)} ::
    is_path(g, q) &&
    q[0] == start &&
    q[|q| - 1] == target &&
    |q| == k + 1;

  forall q: seq<int> |
    is_path(g, q) &&
    q[0] == start &&
    q[|q| - 1] == target
    ensures |q| >= k + 1
  {
    if |q| < k + 1 {
      assert |q| <= k;
      assert |q| > 0;
      assert 0 <= k - 1;
      assert bfs_within(g, start, target, k - 1);
    }
  }
}

ghost predicate bfs_edge_prefix(
  g: Graph, seen: seq<bool>, v: int, u: int, i: int)
{
  exists x: int, j: int ::
    0 <= x < size(g) &&
    0 <= x < |seen| &&
    0 <= j < |g.adj[x]| &&
    seen[x] &&
    g.adj[x][j] == v &&
    (x < u || (x == u && j < i))
}

lemma bfs_prefix_next(
  g: Graph, seen: seq<bool>, v: int, u: int)
  requires |seen| == size(g)
  requires 0 <= u < size(g)
  ensures bfs_edge_prefix(g, seen, v, u, |g.adj[u]|) <==>
          bfs_edge_prefix(g, seen, v, u + 1, 0)
{
  if bfs_edge_prefix(g, seen, v, u, |g.adj[u]|) {
    var x, j :| 0 <= x < size(g) &&
                    0 <= x < |seen| &&
                    0 <= j < |g.adj[x]| &&
                    seen[x] &&
                    g.adj[x][j] == v &&
                    (x < u || (x == u && j < |g.adj[u]|));
    assert x < u + 1;
    assert bfs_edge_prefix(g, seen, v, u + 1, 0);
  }

  if bfs_edge_prefix(g, seen, v, u + 1, 0) {
    var x, j :| 0 <= x < size(g) &&
                    0 <= x < |seen| &&
                    0 <= j < |g.adj[x]| &&
                    seen[x] &&
                    g.adj[x][j] == v &&
                    (x < u + 1 || (x == u + 1 && j < 0));
    assert x <= u;
    assert x < u || x == u;
    assert bfs_edge_prefix(g, seen, v, u, |g.adj[u]|);
  }
}

method bfs_edge_from_seen(
  g: Graph, seen: seq<bool>, v: int) returns (found: bool)
  requires |seen| == size(g)
  requires 0 <= v < size(g)
  ensures found <==>
    exists u: int ::
      0 <= u < size(g) &&
      seen[u] &&
      has_edge(g, u, v)
{
  found := false;
  var u := 0;

  while u < |g.adj|
    invariant 0 <= u <= |g.adj|
    invariant found <==> bfs_edge_prefix(g, seen, v, u, 0)
    decreases |g.adj| - u
  {
    var i := 0;

    while i < |g.adj[u]|
      invariant 0 <= i <= |g.adj[u]|
      invariant found <==> bfs_edge_prefix(g, seen, v, u, i)
      decreases |g.adj[u]| - i
    {
      if seen[u] && g.adj[u][i] == v {
        found := true;
      }

      i := i + 1;
    }

    bfs_prefix_next(g, seen, v, u);
    u := u + 1;
  }

  if found {
    ghost var x, j :| 0 <= x < size(g) &&
                          0 <= x < |seen| &&
                          0 <= j < |g.adj[x]| &&
                          seen[x] &&
                          g.adj[x][j] == v &&
                          (x < size(g) ||
                           (x == size(g) && j < 0));
    assert has_edge(g, x, v);
  }

  if exists x: int ::
       0 <= x < size(g) &&
       seen[x] &&
       has_edge(g, x, v)
  {
    ghost var x :| 0 <= x < size(g) &&
                   seen[x] &&
                   has_edge(g, x, v);
    ghost var j :| 0 <= x < |g.adj| &&
                   0 <= j < |g.adj[x]| &&
                   g.adj[x][j] == v;
    assert 0 <= x < |seen|;
    assert bfs_edge_prefix(g, seen, v, size(g), 0);
    assert found;
  }
}

method bfs_expand(g: Graph, seen: seq<bool>)
    returns (next: seq<bool>)
  requires |seen| == size(g)
  ensures |next| == size(g)
  ensures forall v: int ::
    0 <= v < size(g) ==>
      (next[v] <==>
        seen[v] ||
        (exists u: int ::
          0 <= u < size(g) &&
          seen[u] &&
          has_edge(g, u, v)))
  ensures forall v: int ::
    0 <= v < size(g) && seen[v] ==> next[v]
{
  next := seen;
  var v := 0;

  while v < |g.adj|
    invariant 0 <= v <= |g.adj|
    invariant |next| == |g.adj|
    invariant forall x: int ::
      0 <= x < v ==>
        (next[x] <==>
          seen[x] ||
          (exists u: int ::
            0 <= u < size(g) &&
            seen[u] &&
            has_edge(g, u, x)))
    invariant forall x: int ::
      v <= x < |g.adj| ==> next[x] == seen[x]
    decreases |g.adj| - v
  {
    var found := bfs_edge_from_seen(g, seen, v);
    next := next[v := seen[v] || found];
    v := v + 1;
  }
}

lemma bfs_expand_semantics(
  g: Graph, start: int, seen: seq<bool>,
  next: seq<bool>, round: int)
  requires well_formed(g)
  requires 0 <= start < size(g)
  requires 0 <= round
  requires |seen| == size(g)
  requires |next| == size(g)
  requires forall v: int ::
    0 <= v < size(g) ==>
      (seen[v] <==> bfs_within(g, start, v, round))
  requires forall v: int ::
    0 <= v < size(g) ==>
      (next[v] <==>
        seen[v] ||
        (exists u: int ::
          0 <= u < size(g) &&
          seen[u] &&
          has_edge(g, u, v)))
  ensures forall v: int ::
    0 <= v < size(g) ==>
      (next[v] <==> bfs_within(g, start, v, round + 1))
{
  forall v: int | 0 <= v < size(g)
    ensures next[v] <==>
            bfs_within(g, start, v, round + 1)
  {
    bfs_within_step(g, start, v, round);
    assert
      (exists u: int ::
        0 <= u < size(g) &&
        seen[u] &&
        has_edge(g, u, v))
      <==>
      bfs_one_step(g, start, v, round);
  }
}

lemma bfs_missing_decreases(
  oldSeen: seq<bool>, newSeen: seq<bool>)
  requires |oldSeen| == |newSeen|
  requires forall i: int ::
    0 <= i < |oldSeen| && oldSeen[i] ==> newSeen[i]
  requires oldSeen != newSeen
  ensures bfs_missing(newSeen) < bfs_missing(oldSeen)
{
  forall i: int | i in bfs_missing(newSeen)
    ensures i in bfs_missing(oldSeen)
  {
    assert 0 <= i < |newSeen|;
    if oldSeen[i] {
      assert newSeen[i];
    }
  }

  if !(exists i: int ::
         0 <= i < |oldSeen| &&
         oldSeen[i] != newSeen[i])
  {
    assert oldSeen == newSeen;
  }

  var i :| 0 <= i < |oldSeen| &&
           oldSeen[i] != newSeen[i];

  if oldSeen[i] {
    assert newSeen[i];
  }

  assert !oldSeen[i] && newSeen[i];
  assert i in bfs_missing(oldSeen);
  assert i !in bfs_missing(newSeen);
}

lemma bfs_closed_path(
  g: Graph, seen: seq<bool>, p: seq<int>)
  requires well_formed(g)
  requires bfs_closed(g, seen)
  requires is_path(g, p)
  requires |p| > 0
  requires 0 <= p[0] < size(g)
  requires 0 <= p[|p| - 1] < |seen|
  requires seen[p[0]]
  ensures seen[p[|p| - 1]]
{
  var i := 0;

  while i < |p| - 1
    invariant 0 <= i < |p|
    invariant 0 <= p[i] < size(g)
    invariant seen[p[i]]
    decreases |p| - 1 - i
  {
    assert has_edge(g, p[i], p[i + 1]);
    bfs_edge_bounds(g, p[i], p[i + 1]);
    assert seen[p[i + 1]];
    i := i + 1;
  }

  assert i == |p| - 1;
}

lemma bfs_closed_not_reachable(
  g: Graph, seen: seq<bool>, start: int, target: int)
  requires well_formed(g)
  requires bfs_closed(g, seen)
  requires 0 <= start < size(g)
  requires 0 <= target < size(g)
  requires seen[start]
  requires !seen[target]
  ensures !reachable(g, start, target)
{
  if reachable(g, start, target) {
    var p :| is_path(g, p) &&
             p[0] == start &&
             p[|p| - 1] == target;
    assert |p| > 0;
    assert |seen| == size(g);
    assert p[|p| - 1] == target;
    assert 0 <= p[|p| - 1] < |seen|;
    bfs_closed_path(g, seen, p);
    assert seen[target];
  }
}

method bfs_shortest_path(
  graph: Graph, start: int, target: int)
    returns (res: Option<int>)
  requires well_formed(graph)
  requires size(graph) <= 10000
  requires 0 <= start < size(graph)
  requires 0 <= target < size(graph)
  ensures match res {
    case Some(dist) =>
      is_shortest_distance(graph, start, target, dist)
    case None =>
      !reachable(graph, start, target)
  }
{
  var n := |graph.adj|;
  var seen := seq(n, i => i == start);
  var round := 0;

  bfs_within_zero(graph, start, target);

  if start == target {
    assert bfs_within(graph, start, target, 0);
    assert !bfs_within(graph, start, target, -1);
    bfs_minimal_is_shortest(
      graph, start, target, 0);
    res := Some(0);
    return;
  }

  assert !seen[target];
  assert forall v: int ::
    0 <= v < size(graph) ==>
      (seen[v] <==>
       bfs_within(graph, start, v, 0)) by
  {
    forall v: int | 0 <= v < size(graph)
      ensures seen[v] <==>
              bfs_within(graph, start, v, 0)
    {
      bfs_within_zero(graph, start, v);
    }
  }

  var changed := true;

  while !seen[target] && changed
    invariant |seen| == size(graph)
    invariant 0 <= round
    invariant seen[start]
    invariant forall v: int ::
      0 <= v < size(graph) ==>
        (seen[v] <==>
         bfs_within(graph, start, v, round))
    invariant seen[target] ==>
      !bfs_within(
        graph, start, target, round - 1)
    invariant !changed ==> bfs_closed(graph, seen)
    decreases bfs_missing(seen),
              if changed then 1 else 0
  {
    var oldSeen := seen;
    var next := bfs_expand(graph, oldSeen);

    bfs_expand_semantics(
      graph, start, oldSeen, next, round);

    changed := next != oldSeen;

    if changed {
      bfs_missing_decreases(oldSeen, next);
    } else {
      assert next == oldSeen;
      assert forall u: int, v: int ::
        0 <= u < size(graph) &&
        0 <= v < size(graph) &&
        next[u] &&
        has_edge(graph, u, v)
        ==> next[v] by
      {
        forall u: int, v: int |
          0 <= u < size(graph) &&
          0 <= v < size(graph) &&
          next[u] &&
          has_edge(graph, u, v)
          ensures next[v]
        {
          assert oldSeen[u];
          assert
            oldSeen[v] ||
            (exists x: int ::
              0 <= x < size(graph) &&
              oldSeen[x] &&
              has_edge(graph, x, v));
        }
      }
      assert bfs_closed(graph, next);
    }

    assert !oldSeen[target];
    assert !bfs_within(
      graph, start, target, round);

    seen := next;
    round := round + 1;
  }

  if seen[target] {
    assert bfs_within(
      graph, start, target, round);
    assert !bfs_within(
      graph, start, target, round - 1);
    bfs_minimal_is_shortest(
      graph, start, target, round);
    res := Some(round);
  } else {
    assert !changed;
    assert bfs_closed(graph, seen);
    assert seen[start];
    bfs_closed_not_reachable(
      graph, seen, start, target);
    res := None;
  }
}
