ghost predicate valid_witnesses(g: seq<seq<(int, int)>>, start: int, dists: seq<Option<int>>, paths: seq<seq<int>>) {
    |dists| == |g| &&
    |paths| == |g| &&
    0 <= start < |g| &&
    dists[start].Some? && dists[start].value <= 0 &&
    forall v: int :: 0 <= v < |g| ==> (
        match dists[v] {
            case Some(d) =>
                is_path(g, paths[v]) &&
                paths[v][0] == start &&
                paths[v][|paths[v]| - 1] == v &&
                path_weight(g, paths[v]) == d
            case None => true
        }
    )
}

ghost predicate dists_leq(d1: seq<Option<int>>, d2: seq<Option<int>>) {
    |d1| == |d2| &&
    forall v: int :: 0 <= v < |d1| ==> (
        d2[v].Some? ==> (d1[v].Some? && d1[v].value <= d2[v].value)
    )
}

ghost predicate bounded_for_len(g: seq<seq<(int, int)>>, start: int, dists: seq<Option<int>>, max_len: int) {
    |dists| == |g| &&
    forall p: seq<int> {:trigger is_path(g, p)} ::
        is_path(g, p) && p[0] == start && |p| <= max_len
        ==> 0 <= p[|p| - 1] < |g| && dists[p[|p| - 1]].Some? && dists[p[|p| - 1]].value <= path_weight(g, p)
}

ghost predicate edges_relaxed_up_to(
    g: seq<seq<(int, int)>>,
    old_dists: seq<Option<int>>,
    dists: seq<Option<int>>,
    u_bound: int,
    idx_bound: int
) {
    |old_dists| == |g| && |dists| == |g| &&
    (forall u: int, idx: int ::
        0 <= u < u_bound && 0 <= u < |g| && 0 <= idx < |g[u]| && old_dists[u].Some?
        ==> 0 <= g[u][idx].0 < |g| && dists[g[u][idx].0].Some? && dists[g[u][idx].0].value <= old_dists[u].value + g[u][idx].1)
    &&
    (0 <= u_bound < |g| ==>
        forall idx: int ::
