lemma lemma_edge_weight_unique(g: seq<seq<(int, int)>>, u: int, idx: int)
    requires well_formed(WeightedGraph(g))
    requires 0 <= u < |g| && 0 <= idx < |g[u]|
    ensures 0 <= g[u][idx].0 < |g|
    ensures has_edge(g, u, g[u][idx].0, g[u][idx].1)
    ensures connected(g, u, g[u][idx].0)
    ensures get_edge_weight(g, u, g[u][idx].0) == g[u][idx].1
{
    var v := g[u][idx].0;
    var w := g[u][idx].1;
    assert has_edge(g, u, v, w);
    assert connected(g, u, v);
    var w' := get_edge_weight(g, u, v);
    assert has_edge(g, u, v, w');
    var j: int :| 0 <= j < |g[u]| && g[u][j].0 == v && g[u][j].1 == w';
    if j != idx {
        assert g[u][idx].0 != g[u][j].0;
    }
}

lemma lemma_connected_has_index(g: seq<seq<(int, int)>>, u: int, v: int) returns (idx: int)
    requires well_formed(WeightedGraph(g))
    requires connected(g, u, v)
    ensures 0 <= u < |g| && 0 <= idx < |g[u]| && 0 <= v < |g|
    ensures g[u][idx].0 == v
    ensures g[u][idx].1 == get_edge_weight(g, u, v)
{
    var w := get_edge_weight(g, u, v);
    assert has_edge(g, u, v, w);
    idx :| 0 <= u < |g| && 0 <= idx < |g[u]| && g[u][idx].0 == v && g[u][idx].1 == w;
}

lemma lemma_extend_path(g: seq<seq<(int, int)>>, p: seq<int>, u: int, idx: int)
    requires well_formed(WeightedGraph(g))
    requires is_path(g, p)
    requires p[|p| - 1] == u
    requires 0 <= u < |g| && 0 <= idx < |g[u]|
    ensures is_path(g, p + [g[u][idx].0])
    ensures (p + [g[u][idx].0])[0] == p[0]
    ensures (p + [g[u][idx].0])[|p + [g[u][idx].0]| - 1] == g[u][idx].0
    ensures path_weight(g, p + [g[u][idx].0]) == path_weight(g, p) + g[u][idx].1
{
    lemma_edge_weight_unique(g, u, idx);
    var v := g[u][idx].0;
    var w := g[u][idx].1;
    var pv := p + [v];
    assert |pv| == |p| + 1 >= 2;
    assert pv[..|pv| - 1] == p;
    assert pv[|pv| - 2] == u;
    assert pv[|pv| - 1] == v;
    forall i: int | 0 <= i < |pv| - 1
        ensures connected(g, pv[i], pv[i + 1])
    {
        if i < |p| - 1 {
            assert pv[i] == p[i] && pv[i + 1] == p[i + 1];
            assert connected(g, p[i], p[i + 1]);
        } else {
            assert i == |p| - 1;
            assert pv[i] == u && pv[i + 1] == v;
        }
    }
}

lemma lemma_subpath(g: seq<seq<(int, int)>>, p: seq<int>, a: int, b: int)
    requires is_path(g, p)
    requires 0 <= a <= b < |p|
    ensures is_path(g, p[a .. b + 1])
{
    var sub := p[a .. b + 1];
    assert |sub| == b - a + 1 > 0;
    forall k: int | 0 <= k < |sub| - 1
        ensures connected(g, sub[k], sub[k + 1])
    {
        assert sub[k] == p[a + k];
        assert sub[k + 1] == p[a + k + 1];
        assert 0 <= a + k < |p| - 1;
