}

lemma lemma_join_paths(g: seq<seq<(int, int)>>, p1: seq<int>, p2: seq<int>)
    requires is_path(g, p1)
    requires is_path(g, p2)
    requires p1[|p1| - 1] == p2[0]
    ensures is_path(g, p1 + p2[1..])
    ensures path_weight(g, p1 + p2[1..]) == path_weight(g, p1) + path_weight(g, p2)
    decreases |p2|
{
    var joined := p1 + p2[1..];
    assert |joined| == |p1| + |p2| - 1 > 0;
    forall k: int | 0 <= k < |joined| - 1
        ensures connected(g, joined[k], joined[k + 1])
    {
        if k < |p1| - 1 {
            assert joined[k] == p1[k] && joined[k + 1] == p1[k + 1];
            assert connected(g, p1[k], p1[k + 1]);
        } else if k == |p1| - 1 {
            assert joined[k] == p1[|p1| - 1] == p2[0];
            assert joined[k + 1] == p2[1];
            assert connected(g, p2[0], p2[1]);
        } else {
            var m := k - |p1| + 1;
            assert 1 <= m < |p2| - 1;
            assert joined[k] == p2[m];
            assert joined[k + 1] == p2[m + 1];
            assert connected(g, p2[m], p2[m + 1]);
        }
    }
    if |p2| == 1 {
        assert p2[1..] == [];
        assert joined == p1;
        assert path_weight(g, p2) == 0;
    } else {
        var p2_pref := p2[..|p2| - 1];
        lemma_subpath(g, p2, 0, |p2| - 2);
        assert p2[0 .. |p2| - 1] == p2_pref;
        lemma_join_paths(g, p1, p2_pref);
        assert joined[..|joined| - 1] == p1 + p2_pref[1..];
        assert joined[|joined| - 2] == p2[|p2| - 2];
        assert joined[|joined| - 1] == p2[|p2| - 1];
    }
}

lemma lemma_split_path(g: seq<seq<(int, int)>>, p: seq<int>, k: int)
    requires is_path(g, p)
    requires 0 <= k < |p|
    ensures is_path(g, p[.. k + 1])
    ensures is_path(g, p[k ..])
    ensures path_weight(g, p) == path_weight(g, p[.. k + 1]) + path_weight(g, p[k ..])
{
    lemma_subpath(g, p, 0, k);
    lemma_subpath(g, p, k, |p| - 1);
    assert p[0 .. k + 1] == p[.. k + 1];
    assert p[k .. |p|] == p[k ..];
    var p1 := p[.. k + 1];
    var p2 := p[k ..];
    lemma_join_paths(g, p1, p2);
    assert p1 + p2[1..] == p[.. k + 1] + p[k + 1 ..] == p;
}

lemma lemma_excise_cycle(g: seq<seq<(int, int)>>, p: seq<int>, i: int, j: int)
    returns (c: seq<int>, p_short: seq<int>)
    requires is_path(g, p)
    requires 0 <= i < j < |p|
    requires p[i] == p[j]
    ensures is_path(g, c) && |c| > 1 && c[0] == c[|c| - 1]
    ensures is_path(g, p_short) && |p_short| < |p|
    ensures p_short[0] == p[0] && p_short[|p_short| - 1] == p[|p| - 1]
    ensures path_weight(g, p) == path_weight(g, p_short) + path_weight(g, c)
{
    lemma_split_path(g, p, j);
    var pj := p[.. j + 1];
    var p_tail := p[j ..];
    lemma_split_path(g, pj, i);
    assert pj[.. i + 1] == p[.. i + 1];
    assert pj[i ..] == p[i .. j + 1];
    var p_head := p[.. i + 1];
    c := p[i .. j + 1];
    assert |c| == j - i + 1 > 1;
    assert c[0] == p[i] && c[|c| - 1] == p[j];
    assert p_head[|p_head| - 1] == p[i] == p[j] == p_tail[0];
    lemma_join_paths(g, p_head, p_tail);
    p_short := p_head + p_tail[1..];
    assert |p_short| == (i + 1) + (|p| - j) - 1 == |p| - (j - i) < |p|;
    assert p_short[0] == p_head[0] == p[0];
    assert p_short[|p_short| - 1] == p_tail[|p_tail| - 1] == p[|p| - 1];
}

lemma lemma_path_vertices_bounded(g: seq<seq<(int, int)>>, p: seq<int>)
