lemma lemma_pigeonhole(s: seq<int>, n: int) returns (i: int, j: int)
    requires n >= 0
    requires |s| > n
    requires forall k: int :: 0 <= k < |s| ==> 0 <= s[k] < n
    ensures 0 <= i < j < |s| && s[i] == s[j]
    decreases n
{
    if n == 0 {
        assert 0 <= s[0] < 0;
    } else if !(exists k: int :: 0 <= k < |s| && s[k] == n - 1) {
        forall k: int | 0 <= k < |s|
            ensures 0 <= s[k] < n - 1
        {
            assert s[k] != n - 1;
        }
        i, j := lemma_pigeonhole(s, n - 1);
    } else {
        var pos: int :| 0 <= pos < |s| && s[pos] == n - 1;
        if exists k: int :: 0 <= k < |s| && k != pos && s[k] == n - 1 {
            var k: int :| 0 <= k < |s| && k != pos && s[k] == n - 1;
            if k < pos {
                i, j := k, pos;
            } else {
                i, j := pos, k;
            }
        } else {
            var s' := s[..pos] + s[pos + 1..];
            assert |s'| == |s| - 1 > n - 1;
            forall m: int | 0 <= m < |s'|
                ensures 0 <= s'[m] < n - 1
            {
                if m < pos {
                    assert s'[m] == s[m];
                    assert s[m] != n - 1;
                } else {
                    assert s'[m] == s[m + 1];
                    assert s[m + 1] != n - 1;
                }
            }
            var i', j' := lemma_pigeonhole(s', n - 1);
            i := if i' < pos then i' else i' + 1;
            j := if j' < pos then j' else j' + 1;
            assert s[i] == s'[i'];
            assert s[j] == s'[j'];
        }
    }
}

lemma lemma_shorter_than_short_paths_neg_cycle(g: seq<seq<(int, int)>>, start: int, p: seq<int>)
    requires well_formed(WeightedGraph(g))
    requires 0 <= start < |g|
    requires is_path(g, p)
    requires p[0] == start
    requires forall q: seq<int> {:trigger is_path(g, q)} ::
        is_path(g, q) && q[0] == start && q[|q| - 1] == p[|p| - 1] && |q| <= |g|
        ==> path_weight(g, q) > path_weight(g, p)
    ensures has_negative_cycle(g)
    decreases |p|
{
    if |p| <= |g| {
        assert is_path(g, p) && p[0] == start && p[|p| - 1] == p[|p| - 1] && |p| <= |g|;
        assert path_weight(g, p) > path_weight(g, p);
    } else {
        lemma_path_vertices_bounded(g, p);
        var i, j := lemma_pigeonhole(p, |g|);
        var c, p_short := lemma_excise_cycle(g, p, i, j);
        if path_weight(g, c) < 0 {
            assert is_path(g, c) && |c| > 1 && c[0] == c[|c| - 1] && path_weight(g, c) < 0;
        } else {
            assert path_weight(g, p_short) <= path_weight(g, p);
            forall q: seq<int> {:trigger is_path(g, q)} |
                is_path(g, q) && q[0] == start && q[|q| - 1] == p_short[|p_short| - 1] && |q| <= |g|
                ensures path_weight(g, q) > path_weight(g, p_short)
            {
                assert q[|q| - 1] == p[|p| - 1];
                assert path_weight(g, q) > path_weight(g, p);
            }
            lemma_shorter_than_short_paths_neg_cycle(g, start, p_short);
        }
    }
}

lemma lemma_relax_edge_step(
    g: seq<seq<(int, int)>>,
    start: int,
    old_dists: seq<Option<int>>,
    dists: seq<Option<int>>,
    paths: seq<seq<int>>,
    new_dists: seq<Option<int>>,
    new_paths: seq<seq<int>>,
    u: int,
    idx: int
)
    requires well_formed(WeightedGraph(g))
    requires 0 <= start < |g|
    requires valid_witnesses(g, start, dists, paths)
    requires dists_leq(dists, old_dists)
    requires edges_relaxed_up_to(g, old_dists, dists, u, idx)
    requires 0 <= u < |g| && 0 <= idx < |g[u]|
    requires var v := g[u][idx].0; var w := g[u][idx].1;
        if dists[u].Some? && (dists[v].None? || dists[u].value + w < dists[v].value) then
            new_dists == dists[v := Some(dists[u].value + w)] &&
            new_paths == paths[v := paths[u] + [v]]
        else
            new_dists == dists &&
            new_paths == paths
    ensures valid_witnesses(g, start, new_dists, new_paths)
    ensures dists_leq(new_dists, old_dists)
    ensures edges_relaxed_up_to(g, old_dists, new_dists, u, idx + 1)
{
    var v := g[u][idx].0;
    var w := g[u][idx].1;
    assert 0 <= v < |g|;
    if dists[u].Some? && (dists[v].None? || dists[u].value + w < dists[v].value) {
        lemma_extend_path(g, paths[u], u, idx);
        assert dists_leq(new_dists, dists);
    } else {
        assert dists_leq(new_dists, dists);
    }
}

lemma lemma_round_step(
    g: seq<seq<(int, int)>>,
    start: int,
    old_dists: seq<Option<int>>,
    dists: seq<Option<int>>,
    max_len: int
)
    requires well_formed(WeightedGraph(g))
    requires 0 <= start < |g|
    requires max_len >= 1
    requires bounded_for_len(g, start, old_dists, max_len)
    requires dists_leq(dists, old_dists)
    requires edges_relaxed_up_to(g, old_dists, dists, |g|, 0)
    ensures bounded_for_len(g, start, dists, max_len + 1)
{
    forall p: seq<int> {:trigger is_path(g, p)} |
        is_path(g, p) && p[0] == start && |p| <= max_len + 1
        ensures 0 <= p[|p| - 1] < |g| && dists[p[|p| - 1]].Some? && dists[p[|p| - 1]].value <= path_weight(g, p)
    {
        if |p| <= max_len {
            assert old_dists[p[|p| - 1]].Some? && old_dists[p[|p| - 1]].value <= path_weight(g, p);
        } else {
            assert |p| == max_len + 1 >= 2;
            var p_pref := p[..|p| - 1];
            lemma_subpath(g, p, 0, |p| - 2);
            assert p[0 .. |p| - 1] == p_pref;
            assert is_path(g, p_pref) && p_pref[0] == start && |p_pref| <= max_len;
            var u := p[|p| - 2];
            var v := p[|p| - 1];
            assert p_pref[|p_pref| - 1] == u;
            assert 0 <= u < |g| && old_dists[u].Some? && old_dists[u].value <= path_weight(g, p_pref);
            assert connected(g, u, v);
            var idx := lemma_connected_has_index(g, u, v);
            assert g[u][idx].0 == v && g[u][idx].1 == get_edge_weight(g, u, v);
            assert dists[v].Some? && dists[v].value <= old_dists[u].value + g[u][idx].1;
            assert path_weight(g, p) == path_weight(g, p_pref) + get_edge_weight(g, u, v);
        }
    }
}

lemma lemma_detect_neg_cycle(
    g: seq<seq<(int, int)>>,
    start: int,
    dists: seq<Option<int>>,
    paths: seq<seq<int>>,
    u: int,
    idx: int
)
    requires well_formed(WeightedGraph(g))
    requires 0 <= start < |g|
    requires valid_witnesses(g, start, dists, paths)
    requires bounded_for_len(g, start, dists, |g|)
    requires 0 <= u < |g| && 0 <= idx < |g[u]|
    requires dists[u].Some?
    requires dists[g[u][idx].0].None? || dists[u].value + g[u][idx].1 < dists[g[u][idx].0].value
    ensures has_negative_cycle(g)
{
    var v := g[u][idx].0;
    var w := g[u][idx].1;
    var pu := paths[u];
    var pv := pu + [v];
    lemma_extend_path(g, pu, u, idx);
    assert is_path(g, pv) && pv[0] == start && pv[|pv| - 1] == v;
    assert path_weight(g, pv) == dists[u].value + w;
    forall q: seq<int> {:trigger is_path(g, q)} |
        is_path(g, q) && q[0] == start && q[|q| - 1] == v && |q| <= |g|
        ensures path_weight(g, q) > path_weight(g, pv)
    {
        assert dists[v].Some? && dists[v].value <= path_weight(g, q);
    }
    lemma_shorter_than_short_paths_neg_cycle(g, start, pv);
}

lemma lemma_no_relax_implies_lower_bound(
    g: seq<seq<(int, int)>>,
    start: int,
    dists: seq<Option<int>>,
    p: seq<int>
)
    requires well_formed(WeightedGraph(g))
    requires 0 <= start < |g|
    requires |dists| == |g|
    requires dists[start].Some? && dists[start].value <= 0
    requires edges_relaxed_up_to(g, dists, dists, |g|, 0)
    requires is_path(g, p) && p[0] == start
    ensures 0 <= p[|p| - 1] < |g|
    ensures dists[p[|p| - 1]].Some? && dists[p[|p| - 1]].value <= path_weight(g, p)
    decreases |p|
{
    if |p| == 1 {
        assert p[|p| - 1] == start;
        assert path_weight(g, p) == 0;
    } else {
        var p_pref := p[..|p| - 1];
        lemma_subpath(g, p, 0, |p| - 2);
        assert p[0 .. |p| - 1] == p_pref;
        lemma_no_relax_implies_lower_bound(g, start, dists, p_pref);
        var u := p[|p| - 2];
        var v := p[|p| - 1];
        assert p_pref[|p_pref| - 1] == u;
        assert connected(g, u, v);
        var idx := lemma_connected_has_index(g, u, v);
        assert g[u][idx].0 == v && g[u][idx].1 == get_edge_weight(g, u, v);
        assert dists[v].Some? && dists[v].value <= dists[u].value + g[u][idx].1;
        assert path_weight(g, p) == path_weight(g, p_pref) + get_edge_weight(g, u, v);
    }
}

lemma lemma_all_shortest_dists(
    g: seq<seq<(int, int)>>,
    start: int,
    dists: seq<Option<int>>,
    paths: seq<seq<int>>
)
    requires well_formed(WeightedGraph(g))
    requires 0 <= start < |g|
