            case Some(d) => is_shortest_dist(g, start, v, d)
            case None => forall p: seq<int> {:trigger is_path(g, p)} ::
                            is_path(g, p) && p[0] == start && p[|p| - 1] == v ==> false
        }
    )
{
    forall v: int | 0 <= v < |g|
        ensures match dists[v] {
            case Some(d) => is_shortest_dist(g, start, v, d)
            case None => forall p: seq<int> {:trigger is_path(g, p)} ::
                            is_path(g, p) && p[0] == start && p[|p| - 1] == v ==> false
        }
