        k := k + 1;
    }

    var u := 0;
    while u < n
        invariant 0 <= u <= n
        invariant valid_witnesses(graph.adj, start, dists, paths)
        invariant bounded_for_len(graph.adj, start, dists, n)
        invariant edges_relaxed_up_to(graph.adj, dists, dists, u, 0)
