) {
    |old_dists| == |g| && |dists| == |g| &&
    (forall u: int, idx: int ::
        0 <= u < u_bound && 0 <= u < |g| && 0 <= idx < |g[u]| && old_dists[u].Some?
        ==> 0 <= g[u][idx].0 < |g| && dists[g[u][idx].0].Some? && dists[g[u][idx].0].value <= old_dists[u].value + g[u][idx].1)
    &&
    (0 <= u_bound < |g| ==>
        forall idx: int ::
            0 <= idx < idx_bound && 0 <= idx < |g[u_bound]| && old_dists[u_bound].Some?
            ==> 0 <= g[u_bound][idx].0 < |g| && dists[g[u_bound][idx].0].Some? && dists[g[u_bound][idx].0].value <= old_dists[u_bound].value + g[u_bound][idx].1)
}

lemma lemma_edge_weight_unique(g: seq<seq<(int, int)>>, u: int, idx: int)
    requires well_formed(WeightedGraph(g))
    requires 0 <= u < |g| && 0 <= idx < |g[u]|
    ensures 0 <= g[u][idx].0 < |g|
    ensures has_edge(g, u, g[u][idx].0, g[u][idx].1)
    ensures connected(g, u, g[u][idx].0)
    ensures get_edge_weight(g, u, g[u][idx].0) == g[u][idx].1
{
    var v := g[u][idx].0;
    var w := g[u][idx].1;
    assert has_edge(g, u, v, w);
    assert connected(g, u, v);
    var w' := get_edge_weight(g, u, v);
    assert has_edge(g, u, v, w');
    var j: int :| 0 <= j < |g[u]| && g[u][j].0 == v && g[u][j].1 == w';
    if j != idx {
        assert g[u][idx].0 != g[u][j].0;
    }
}

lemma lemma_connected_has_index(g: seq<seq<(int, int)>>, u: int, v: int) returns (idx: int)
    requires well_formed(WeightedGraph(g))
    requires connected(g, u, v)
    ensures 0 <= u < |g| && 0 <= idx < |g[u]| && 0 <= v < |g|
    ensures g[u][idx].0 == v
    ensures g[u][idx].1 == get_edge_weight(g, u, v)
{
    var w := get_edge_weight(g, u, v);
    assert has_edge(g, u, v, w);
    idx :| 0 <= u < |g| && 0 <= idx < |g[u]| && g[u][idx].0 == v && g[u][idx].1 == w;
}

lemma lemma_extend_path(g: seq<seq<(int, int)>>, p: seq<int>, u: int, idx: int)
    requires well_formed(WeightedGraph(g))
    requires is_path(g, p)
    requires p[|p| - 1] == u
    requires 0 <= u < |g| && 0 <= idx < |g[u]|
    ensures is_path(g, p + [g[u][idx].0])
    ensures (p + [g[u][idx].0])[0] == p[0]
    ensures (p + [g[u][idx].0])[|p + [g[u][idx].0]| - 1] == g[u][idx].0
    ensures path_weight(g, p + [g[u][idx].0]) == path_weight(g, p) + g[u][idx].1
{
    lemma_edge_weight_unique(g, u, idx);
    var v := g[u][idx].0;
    var w := g[u][idx].1;
    var pv := p + [v];
    assert |pv| == |p| + 1 >= 2;
    assert pv[..|pv| - 1] == p;
    assert pv[|pv| - 2] == u;
    assert pv[|pv| - 1] == v;
    forall i: int | 0 <= i < |pv| - 1
        ensures connected(g, pv[i], pv[i + 1])
    {
        if i < |p| - 1 {
            assert pv[i] == p[i] && pv[i + 1] == p[i + 1];
            assert connected(g, p[i], p[i + 1]);
        } else {
            assert i == |p| - 1;
            assert pv[i] == u && pv[i + 1] == v;
        }
    }
}

lemma lemma_subpath(g: seq<seq<(int, int)>>, p: seq<int>, a: int, b: int)
    requires is_path(g, p)
    requires 0 <= a <= b < |p|
    ensures is_path(g, p[a .. b + 1])
{
    var sub := p[a .. b + 1];
    assert |sub| == b - a + 1 > 0;
    forall k: int | 0 <= k < |sub| - 1
        ensures connected(g, sub[k], sub[k + 1])
    {
        assert sub[k] == p[a + k];
        assert sub[k + 1] == p[a + k + 1];
        assert 0 <= a + k < |p| - 1;
        assert connected(g, p[a + k], p[a + k + 1]);
    }
}

lemma lemma_join_paths(g: seq<seq<(int, int)>>, p1: seq<int>, p2: seq<int>)
    requires is_path(g, p1)
    requires is_path(g, p2)
    requires p1[|p1| - 1] == p2[0]
    ensures is_path(g, p1 + p2[1..])
    ensures path_weight(g, p1 + p2[1..]) == path_weight(g, p1) + path_weight(g, p2)
    decreases |p2|
{
    var joined := p1 + p2[1..];
    assert |joined| == |p1| + |p2| - 1 > 0;
    forall k: int | 0 <= k < |joined| - 1
        ensures connected(g, joined[k], joined[k + 1])
    {
        if k < |p1| - 1 {
            assert joined[k] == p1[k] && joined[k + 1] == p1[k + 1];
            assert connected(g, p1[k], p1[k + 1]);
        } else if k == |p1| - 1 {
            assert joined[k] == p1[|p1| - 1] == p2[0];
            assert joined[k + 1] == p2[1];
            assert connected(g, p2[0], p2[1]);
        } else {
            var m := k - |p1| + 1;
            assert 1 <= m < |p2| - 1;
            assert joined[k] == p2[m];
            assert joined[k + 1] == p2[m + 1];
            assert connected(g, p2[m], p2[m + 1]);
        }
    }
    if |p2| == 1 {
        assert p2[1..] == [];
        assert joined == p1;
        assert path_weight(g, p2) == 0;
    } else {
        var p2_pref := p2[..|p2| - 1];
        lemma_subpath(g, p2, 0, |p2| - 2);
        assert p2[0 .. |p2| - 1] == p2_pref;
        lemma_join_paths(g, p1, p2_pref);
        assert joined[..|joined| - 1] == p1 + p2_pref[1..];
        assert joined[|joined| - 2] == p2[|p2| - 2];
        assert joined[|joined| - 1] == p2[|p2| - 1];
    }
}

lemma lemma_split_path(g: seq<seq<(int, int)>>, p: seq<int>, k: int)
    requires is_path(g, p)
    requires 0 <= k < |p|
    ensures is_path(g, p[.. k + 1])
    ensures is_path(g, p[k ..])
    ensures path_weight(g, p) == path_weight(g, p[.. k + 1]) + path_weight(g, p[k ..])
{
    lemma_subpath(g, p, 0, k);
    lemma_subpath(g, p, k, |p| - 1);
    assert p[0 .. k + 1] == p[.. k + 1];
    assert p[k .. |p|] == p[k ..];
    var p1 := p[.. k + 1];
    var p2 := p[k ..];
    lemma_join_paths(g, p1, p2);
    assert p1 + p2[1..] == p[.. k + 1] + p[k + 1 ..] == p;
}

lemma lemma_excise_cycle(g: seq<seq<(int, int)>>, p: seq<int>, i: int, j: int)
    returns (c: seq<int>, p_short: seq<int>)
    requires is_path(g, p)
    requires 0 <= i < j < |p|
    requires p[i] == p[j]
    ensures is_path(g, c) && |c| > 1 && c[0] == c[|c| - 1]
    ensures is_path(g, p_short) && |p_short| < |p|
    ensures p_short[0] == p[0] && p_short[|p_short| - 1] == p[|p| - 1]
    ensures path_weight(g, p) == path_weight(g, p_short) + path_weight(g, c)
{
    lemma_split_path(g, p, j);
    var pj := p[.. j + 1];
    var p_tail := p[j ..];
    lemma_split_path(g, pj, i);
    assert pj[.. i + 1] == p[.. i + 1];
    assert pj[i ..] == p[i .. j + 1];
    var p_head := p[.. i + 1];
    c := p[i .. j + 1];
    assert |c| == j - i + 1 > 1;
    assert c[0] == p[i] && c[|c| - 1] == p[j];
    assert p_head[|p_head| - 1] == p[i] == p[j] == p_tail[0];
    lemma_join_paths(g, p_head, p_tail);
    p_short := p_head + p_tail[1..];
    assert |p_short| == (i + 1) + (|p| - j) - 1 == |p| - (j - i) < |p|;
    assert p_short[0] == p_head[0] == p[0];
    assert p_short[|p_short| - 1] == p_tail[|p_tail| - 1] == p[|p| - 1];
}

lemma lemma_path_vertices_bounded(g: seq<seq<(int, int)>>, p: seq<int>)
    requires well_formed(WeightedGraph(g))
    requires is_path(g, p)
    requires 0 <= p[0] < |g|
    ensures forall k: int :: 0 <= k < |p| ==> 0 <= p[k] < |g|
{
    forall k: int | 0 <= k < |p|
        ensures 0 <= p[k] < |g|
    {
        if k > 0 {
            assert connected(g, p[k - 1], p[k]);
            var _ := lemma_connected_has_index(g, p[k - 1], p[k]);
        }
    }
}

lemma lemma_pigeonhole(s: seq<int>, n: int) returns (i: int, j: int)
    requires n >= 0
    requires |s| > n
    requires forall k: int :: 0 <= k < |s| ==> 0 <= s[k] < n
    ensures 0 <= i < j < |s| && s[i] == s[j]
    decreases n
{
    if n == 0 {
        assert 0 <= s[0] < 0;
    } else if !(exists k: int :: 0 <= k < |s| && s[k] == n - 1) {
        forall k: int | 0 <= k < |s|
            ensures 0 <= s[k] < n - 1
        {
            assert s[k] != n - 1;
        }
        i, j := lemma_pigeonhole(s, n - 1);
    } else {
        var pos: int :| 0 <= pos < |s| && s[pos] == n - 1;
        if exists k: int :: 0 <= k < |s| && k != pos && s[k] == n - 1 {
            var k: int :| 0 <= k < |s| && k != pos && s[k] == n - 1;
            if k < pos {
                i, j := k, pos;
            } else {
                i, j := pos, k;
            }
        } else {
            var s' := s[..pos] + s[pos + 1..];
            assert |s'| == |s| - 1 > n - 1;
            forall m: int | 0 <= m < |s'|
                ensures 0 <= s'[m] < n - 1
            {
                if m < pos {
                    assert s'[m] == s[m];
                    assert s[m] != n - 1;
                } else {
                    assert s'[m] == s[m + 1];
                    assert s[m + 1] != n - 1;
                }
            }
            var i', j' := lemma_pigeonhole(s', n - 1);
            i := if i' < pos then i' else i' + 1;
            j := if j' < pos then j' else j' + 1;
            assert s[i] == s'[i'];
            assert s[j] == s'[j'];
        }
    }
}

lemma lemma_shorter_than_short_paths_neg_cycle(g: seq<seq<(int, int)>>, start: int, p: seq<int>)
    requires well_formed(WeightedGraph(g))
    requires 0 <= start < |g|
    requires is_path(g, p)
    requires p[0] == start
    requires forall q: seq<int> {:trigger is_path(g, q)} ::
        is_path(g, q) && q[0] == start && q[|q| - 1] == p[|p| - 1] && |q| <= |g|
        ==> path_weight(g, q) > path_weight(g, p)
    ensures has_negative_cycle(g)
    decreases |p|
{
    if |p| <= |g| {
        assert is_path(g, p) && p[0] == start && p[|p| - 1] == p[|p| - 1] && |p| <= |g|;
        assert path_weight(g, p) > path_weight(g, p);
    } else {
        lemma_path_vertices_bounded(g, p);
        var i, j := lemma_pigeonhole(p, |g|);
        var c, p_short := lemma_excise_cycle(g, p, i, j);
        if path_weight(g, c) < 0 {
            assert is_path(g, c) && |c| > 1 && c[0] == c[|c| - 1] && path_weight(g, c) < 0;
        } else {
            assert path_weight(g, p_short) <= path_weight(g, p);
            forall q: seq<int> {:trigger is_path(g, q)} |
                is_path(g, q) && q[0] == start && q[|q| - 1] == p_short[|p_short| - 1] && |q| <= |g|
                ensures path_weight(g, q) > path_weight(g, p_short)
            {
                assert q[|q| - 1] == p[|p| - 1];
                assert path_weight(g, q) > path_weight(g, p);
            }
            lemma_shorter_than_short_paths_neg_cycle(g, start, p_short);
        }
    }
}

lemma lemma_relax_edge_step(
    g: seq<seq<(int, int)>>,
    start: int,
    old_dists: seq<Option<int>>,
    dists: seq<Option<int>>,
    paths: seq<seq<int>>,
    new_dists: seq<Option<int>>,
    new_paths: seq<seq<int>>,
    u: int,
    idx: int
)
    requires well_formed(WeightedGraph(g))
    requires 0 <= start < |g|
    requires valid_witnesses(g, start, dists, paths)
    requires dists_leq(dists, old_dists)
    requires edges_relaxed_up_to(g, old_dists, dists, u, idx)
    requires 0 <= u < |g| && 0 <= idx < |g[u]|
    requires var v := g[u][idx].0; var w := g[u][idx].1;
        if dists[u].Some? && (dists[v].None? || dists[u].value + w < dists[v].value) then
            new_dists == dists[v := Some(dists[u].value + w)] &&
            new_paths == paths[v := paths[u] + [v]]
        else
            new_dists == dists &&
            new_paths == paths
    ensures valid_witnesses(g, start, new_dists, new_paths)
    ensures dists_leq(new_dists, old_dists)
    ensures edges_relaxed_up_to(g, old_dists, new_dists, u, idx + 1)
{
    var v := g[u][idx].0;
    var w := g[u][idx].1;
    assert 0 <= v < |g|;
    if dists[u].Some? && (dists[v].None? || dists[u].value + w < dists[v].value) {
        lemma_extend_path(g, paths[u], u, idx);
        assert dists_leq(new_dists, dists);
    } else {
        assert dists_leq(new_dists, dists);
    }
}

lemma lemma_round_step(
    g: seq<seq<(int, int)>>,
    start: int,
    old_dists: seq<Option<int>>,
    dists: seq<Option<int>>,
    max_len: int
)
    requires well_formed(WeightedGraph(g))
    requires 0 <= start < |g|
    requires max_len >= 1
    requires bounded_for_len(g, start, old_dists, max_len)
    requires dists_leq(dists, old_dists)
    requires edges_relaxed_up_to(g, old_dists, dists, |g|, 0)
    ensures bounded_for_len(g, start, dists, max_len + 1)
{
    forall p: seq<int> {:trigger is_path(g, p)} |
        is_path(g, p) && p[0] == start && |p| <= max_len + 1
        ensures 0 <= p[|p| - 1] < |g| && dists[p[|p| - 1]].Some? && dists[p[|p| - 1]].value <= path_weight(g, p)
    {
        if |p| <= max_len {
            assert old_dists[p[|p| - 1]].Some? && old_dists[p[|p| - 1]].value <= path_weight(g, p);
        } else {
            assert |p| == max_len + 1 >= 2;
            var p_pref := p[..|p| - 1];
            lemma_subpath(g, p, 0, |p| - 2);
            assert p[0 .. |p| - 1] == p_pref;
            assert is_path(g, p_pref) && p_pref[0] == start && |p_pref| <= max_len;
            var u := p[|p| - 2];
            var v := p[|p| - 1];
            assert p_pref[|p_pref| - 1] == u;
            assert 0 <= u < |g| && old_dists[u].Some? && old_dists[u].value <= path_weight(g, p_pref);
            assert connected(g, u, v);
            var idx := lemma_connected_has_index(g, u, v);
            assert g[u][idx].0 == v && g[u][idx].1 == get_edge_weight(g, u, v);
            assert dists[v].Some? && dists[v].value <= old_dists[u].value + g[u][idx].1;
            assert path_weight(g, p) == path_weight(g, p_pref) + get_edge_weight(g, u, v);
        }
    }
}

lemma lemma_detect_neg_cycle(
    g: seq<seq<(int, int)>>,
    start: int,
    dists: seq<Option<int>>,
    paths: seq<seq<int>>,
    u: int,
    idx: int
)
    requires well_formed(WeightedGraph(g))
    requires 0 <= start < |g|
    requires valid_witnesses(g, start, dists, paths)
    requires bounded_for_len(g, start, dists, |g|)
    requires 0 <= u < |g| && 0 <= idx < |g[u]|
    requires dists[u].Some?
    requires dists[g[u][idx].0].None? || dists[u].value + g[u][idx].1 < dists[g[u][idx].0].value
    ensures has_negative_cycle(g)
{
    var v := g[u][idx].0;
    var w := g[u][idx].1;
    var pu := paths[u];
    var pv := pu + [v];
    lemma_extend_path(g, pu, u, idx);
    assert is_path(g, pv) && pv[0] == start && pv[|pv| - 1] == v;
    assert path_weight(g, pv) == dists[u].value + w;
    forall q: seq<int> {:trigger is_path(g, q)} |
        is_path(g, q) && q[0] == start && q[|q| - 1] == v && |q| <= |g|
        ensures path_weight(g, q) > path_weight(g, pv)
    {
        assert dists[v].Some? && dists[v].value <= path_weight(g, q);
    }
    lemma_shorter_than_short_paths_neg_cycle(g, start, pv);
}

lemma lemma_no_relax_implies_lower_bound(
    g: seq<seq<(int, int)>>,
    start: int,
    dists: seq<Option<int>>,
    p: seq<int>
)
    requires well_formed(WeightedGraph(g))
    requires 0 <= start < |g|
    requires |dists| == |g|
    requires dists[start].Some? && dists[start].value <= 0
    requires edges_relaxed_up_to(g, dists, dists, |g|, 0)
    requires is_path(g, p) && p[0] == start
    ensures 0 <= p[|p| - 1] < |g|
    ensures dists[p[|p| - 1]].Some? && dists[p[|p| - 1]].value <= path_weight(g, p)
    decreases |p|
{
    if |p| == 1 {
        assert p[|p| - 1] == start;
        assert path_weight(g, p) == 0;
    } else {
        var p_pref := p[..|p| - 1];
        lemma_subpath(g, p, 0, |p| - 2);
        assert p[0 .. |p| - 1] == p_pref;
        lemma_no_relax_implies_lower_bound(g, start, dists, p_pref);
        var u := p[|p| - 2];
        var v := p[|p| - 1];
        assert p_pref[|p_pref| - 1] == u;
        assert connected(g, u, v);
        var idx := lemma_connected_has_index(g, u, v);
        assert g[u][idx].0 == v && g[u][idx].1 == get_edge_weight(g, u, v);
        assert dists[v].Some? && dists[v].value <= dists[u].value + g[u][idx].1;
        assert path_weight(g, p) == path_weight(g, p_pref) + get_edge_weight(g, u, v);
    }
}

lemma lemma_all_shortest_dists(
    g: seq<seq<(int, int)>>,
    start: int,
    dists: seq<Option<int>>,
    paths: seq<seq<int>>
)
    requires well_formed(WeightedGraph(g))
    requires 0 <= start < |g|
    requires valid_witnesses(g, start, dists, paths)
    requires edges_relaxed_up_to(g, dists, dists, |g|, 0)
    ensures |dists| == |g|
    ensures forall v: int :: 0 <= v < |g| ==> (
        match dists[v] {
            case Some(d) => is_shortest_dist(g, start, v, d)
            case None => forall p: seq<int> {:trigger is_path(g, p)} ::
                            is_path(g, p) && p[0] == start && p[|p| - 1] == v ==> false
        }
    )
{
    forall v: int | 0 <= v < |g|
        ensures match dists[v] {
            case Some(d) => is_shortest_dist(g, start, v, d)
            case None => forall p: seq<int> {:trigger is_path(g, p)} ::
                            is_path(g, p) && p[0] == start && p[|p| - 1] == v ==> false
        }
    {
        match dists[v] {
            case Some(d) =>
                var pv := paths[v];
                assert is_path(g, pv) && pv[0] == start && pv[|pv| - 1] == v && path_weight(g, pv) == d;
                forall p: seq<int> {:trigger is_path(g, p)} |
                    is_path(g, p) && p[0] == start && p[|p| - 1] == v
                    ensures path_weight(g, p) >= d
                {
                    lemma_no_relax_implies_lower_bound(g, start, dists, p);
                }
            case None =>
                forall p: seq<int> {:trigger is_path(g, p)} |
                    is_path(g, p) && p[0] == start && p[|p| - 1] == v
                    ensures false
                {
                    lemma_no_relax_implies_lower_bound(g, start, dists, p);
                }
        }
    }
}

method bellman_ford(graph: WeightedGraph, start: int) returns (res: Option<seq<Option<int>>>)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    requires weights_and_size_bounded(view(graph))
    ensures match res {
        case Some(dists) => 
            |dists| == size(graph) &&
            forall v: int :: 0 <= v < size(graph) ==> (
                match dists[v] {
                    case Some(d) => is_shortest_dist(view(graph), start, v, d)
                    case None => forall p: seq<int> {:trigger is_path(view(graph), p)} :: 
                                    is_path(view(graph), p) && p[0] == start && p[|p| - 1] == v ==> false
                }
            )
        case None => 
            has_negative_cycle(view(graph))
    }
{
    var n := |graph.adj|;
    var dists: seq<Option<int>> := seq(n, (i: int) => if i == start then Some(0) else None);
    ghost var paths: seq<seq<int>> := seq(n, (i: int) => [start]);

    assert is_path(graph.adj, [start]);
    assert path_weight(graph.adj, [start]) == 0;
    assert valid_witnesses(graph.adj, start, dists, paths);
    assert bounded_for_len(graph.adj, start, dists, 1);

    var k := 0;
    while k < n - 1
        invariant 0 <= k <= n - 1
        invariant valid_witnesses(graph.adj, start, dists, paths)
        invariant bounded_for_len(graph.adj, start, dists, k + 1)
        decreases n - 1 - k
    {
        ghost var old_dists := dists;
        var u := 0;
        while u < n
            invariant 0 <= u <= n
            invariant valid_witnesses(graph.adj, start, dists, paths)
            invariant dists_leq(dists, old_dists)
            invariant edges_relaxed_up_to(graph.adj, old_dists, dists, u, 0)
            decreases n - u
        {
            var edges := graph.adj[u];
            var idx := 0;
