lemma LemmaExtendReachableLe(g: Graph, start: int, u: int, i: int, v: int, d: int)
  requires reachable_le(g, start, u, d)
  requires 0 <= u < |g.adj|
  requires 0 <= i < |g.adj[u]|
  requires g.adj[u][i] == v
  ensures reachable_le(g, start, v, d + 1)
{
  var p: seq<int> :| is_path(g, p) && p[0] == start && p[|p| - 1] == u && |p| <= d + 1;
  var p' := p + [v];
  assert has_edge(g, u, v);
  forall k: int | 0 <= k < |p'| - 1
    ensures has_edge(g, p'[k], p'[k + 1])
  {
    if k < |p| - 1 {
      assert p'[k] == p[k] && p'[k + 1] == p[k + 1];
      assert has_edge(g, p[k], p[k + 1]);
    } else {
      assert k == |p| - 1;
      assert p'[k] == u && p'[k + 1] == v;
    }
  }
  assert is_path(g, p');
  assert p'[0] == start && p'[|p'| - 1] == v && |p'| <= d + 2;
}

lemma LemmaUpdateSoundLe(g: Graph, start: int, nr: seq<bool>, v: int, d: int)
  requires |nr| == size(g)
  requires 0 <= v < size(g)
  requires sound_le(g, start, nr, d)
  requires reachable_le(g, start, v, d)
  ensures sound_le(g, start, nr[v := true], d)
{
