lemma LemmaPathPrefix(g: Graph, p: seq<int>)
  requires is_path(g, p)
  requires |p| >= 2
  ensures is_path(g, p[..|p| - 1])
  ensures has_edge(g, p[|p| - 2], p[|p| - 1])
{
  var p' := p[..|p| - 1];
  forall i: int | 0 <= i < |p'| - 1
    ensures has_edge(g, p'[i], p'[i + 1])
  {
    assert p'[i] == p[i] && p'[i + 1] == p[i + 1];
    assert has_edge(g, p[i], p[i + 1]);
  }
  var last_idx := |p| - 2;
  assert 0 <= last_idx < |p| - 1;
  assert has_edge(g, p[last_idx], p[last_idx + 1]);
}

lemma LemmaInitSound(g: Graph, start: int, reached: seq<bool>)
  requires 0 <= start < size(g)
  requires |reached| == size(g)
  requires forall v: int :: 0 <= v < size(g) ==> (reached[v] <==> v == start)
  ensures sound_le(g, start, reached, 0)
{
  LemmaReachableLeZero(g, start);
}

lemma LemmaInitComplete(g: Graph, start: int, reached: seq<bool>)
  requires 0 <= start < size(g)
  requires |reached| == size(g)
  requires forall v: int :: 0 <= v < size(g) ==> (reached[v] <==> v == start)
  ensures complete_le(g, start, reached, 0)
{
  forall p: seq<int> | is_path(g, p) && p[0] == start && |p| <= 1
    ensures 0 <= p[|p| - 1] < size(g) && reached[p[|p| - 1]]
  {
    assert |p| == 1;
    assert p[|p| - 1] == p[0] == start;
  }
}

lemma LemmaInitNoShorter(g: Graph, start: int, target: int)
  ensures no_path_shorter(g, start, target, 0)
