lemma LemmaFoundShortest(g: Graph, start: int, target: int, reached: seq<bool>, d: int)
  requires 0 <= target < size(g)
  requires |reached| == size(g)
  requires sound_le(g, start, reached, d)
  requires no_path_shorter(g, start, target, d)
  requires reached[target]
  ensures is_shortest_distance(g, start, target, d)
{
  assert reachable_le(g, start, target, d);
  var p: seq<int> :| is_path(g, p) && p[0] == start && p[|p| - 1] == target && |p| <= d + 1;
  assert |p| >= d + 1;
  assert |p| == d + 1;
  forall q: seq<int> | is_path(g, q) && q[0] == start && q[|q| - 1] == target
    ensures |q| >= d + 1
  {
    assert |q| >= d + 1;
  }
}

lemma LemmaStepNoShorter(g: Graph, start: int, target: int, reached: seq<bool>, d: int)
  requires 0 <= target < size(g)
  requires |reached| == size(g)
  requires complete_le(g, start, reached, d)
  requires !reached[target]
  ensures no_path_shorter(g, start, target, d + 1)
{
  forall p: seq<int> | is_path(g, p) && p[0] == start && p[|p| - 1] == target
    ensures |p| >= d + 2
  {
    if |p| <= d + 1 {
      assert reached[p[|p| - 1]];
      assert false;
    }
  }
}

lemma LemmaStepComplete(g: Graph, start: int, reached: seq<bool>, next_reached: seq<bool>, d: int)
  requires well_formed(g)
  requires 0 <= d
  requires |reached| == size(g) && |next_reached| == size(g)
  requires complete_le(g, start, reached, d)
  requires step_closed(g, reached, next_reached)
  ensures complete_le(g, start, next_reached, d + 1)
{
  forall p: seq<int> | is_path(g, p) && p[0] == start && |p| <= d + 2
    ensures 0 <= p[|p| - 1] < size(g) && next_reached[p[|p| - 1]]
  {
    if |p| <= d + 1 {
      assert 0 <= p[|p| - 1] < size(g) && reached[p[|p| - 1]];
    } else {
      assert |p| == d + 2;
      assert |p| >= 2;
      LemmaPathPrefix(g, p);
      var p' := p[..|p| - 1];
      assert is_path(g, p') && p'[0] == start && |p'| == d + 1;
      var u := p'[|p'| - 1];
      assert u == p[|p| - 2];
      assert 0 <= u < size(g) && reached[u];
      assert has_edge(g, u, p[|p| - 1]);
      var i: int :| 0 <= i < |g.adj[u]| && g.adj[u][i] == p[|p| - 1];
      assert 0 <= p[|p| - 1] < size(g);
      assert next_reached[g.adj[u][i]];
    }
  }
}

lemma LemmaClosedContainsPath(g: Graph, start: int, reached: seq<bool>, p: seq<int>)
  requires well_formed(g)
  requires 0 <= start < size(g)
  requires |reached| == size(g)
  requires reached[start]
  requires step_closed(g, reached, reached)
  requires is_path(g, p) && p[0] == start
  ensures 0 <= p[|p| - 1] < size(g) && reached[p[|p| - 1]]
  decreases |p|
{
  if |p| == 1 {
    assert p[|p| - 1] == start;
  } else {
    assert |p| >= 2;
    LemmaPathPrefix(g, p);
    var p' := p[..|p| - 1];
    LemmaClosedContainsPath(g, start, reached, p');
    var u := p'[|p'| - 1];
    assert u == p[|p| - 2];
    assert 0 <= u < size(g) && reached[u];
    assert has_edge(g, u, p[|p| - 1]);
    var i: int :| 0 <= i < |g.adj[u]| && g.adj[u][i] == p[|p| - 1];
    assert 0 <= g.adj[u][i] < size(g);
    assert reached[g.adj[u][i]];
  }
}

lemma LemmaUnreachable(g: Graph, start: int, target: int, reached: seq<bool>)
  requires well_formed(g)
  requires 0 <= start < size(g)
  requires 0 <= target < size(g)
  requires |reached| == size(g)
  requires reached[start]
  requires step_closed(g, reached, reached)
  requires !reached[target]
  ensures !reachable(g, start, target)
{
  if reachable(g, start, target) {
    var p: seq<int> :| is_path(g, p) && p[0] == start && p[|p| - 1] == target;
    LemmaClosedContainsPath(g, start, reached, p);
    assert false;
  }
}

method step_layer(graph: Graph, start: int, reached: seq<bool>, ghost d: int)
  returns (next_reached: seq<bool>, changed: bool, ghost changed_w: int)
  requires well_formed(graph)
  requires 0 <= start < size(graph)
  requires 0 <= d
  requires |reached| == size(graph)
  requires sound_le(graph, start, reached, d)
  ensures |next_reached| == size(graph)
  ensures step_closed(graph, reached, next_reached)
  ensures sound_le(graph, start, next_reached, d + 1)
  ensures changed ==> 0 <= changed_w < size(graph) && !reached[changed_w] && next_reached[changed_w]
  ensures !changed ==> next_reached == reached
{
  var n := |graph.adj|;
  next_reached := reached;
  changed := false;
  changed_w := 0;
  LemmaSoundLeMono(graph, start, reached, d);

  var u := 0;
  while u < n
    invariant 0 <= u <= n
    invariant |next_reached| == n
    invariant forall v: int :: 0 <= v < n && reached[v] ==> next_reached[v]
    invariant sound_le(graph, start, next_reached, d + 1)
    invariant forall u0: int, i0: int ::
      0 <= u0 < u && reached[u0] && 0 <= i0 < |graph.adj[u0]|
      ==> next_reached[graph.adj[u0][i0]]
    invariant changed ==> 0 <= changed_w < n && !reached[changed_w] && next_reached[changed_w]
    invariant !changed ==> next_reached == reached
  {
    if reached[u] {
      var adj_u := graph.adj[u];
      var i := 0;
      while i < |adj_u|
        invariant 0 <= i <= |adj_u|
        invariant |next_reached| == n
        invariant forall v: int :: 0 <= v < n && reached[v] ==> next_reached[v]
        invariant sound_le(graph, start, next_reached, d + 1)
        invariant forall u0: int, i0: int ::
          0 <= u0 < u && reached[u0] && 0 <= i0 < |graph.adj[u0]|
          ==> next_reached[graph.adj[u0][i0]]
        invariant forall i0: int ::
          0 <= i0 < i ==> next_reached[graph.adj[u][i0]]
        invariant changed ==> 0 <= changed_w < n && !reached[changed_w] && next_reached[changed_w]
        invariant !changed ==> next_reached == reached
      {
        var v := adj_u[i];
        assert 0 <= v < n;
        if !next_reached[v] {
          assert !reached[v];
          assert reachable_le(graph, start, u, d);
          LemmaExtendReachableLe(graph, start, u, i, v, d);
          LemmaUpdateSoundLe(graph, start, next_reached, v, d + 1);
          next_reached := next_reached[v := true];
          if !changed {
            changed := true;
            changed_w := v;
          }
        }
        i := i + 1;
      }
    }
    u := u + 1;
  }
}

method bfs_shortest_path(graph: Graph, start: int, target: int) returns (res: Option<int>)
  requires well_formed(graph)
  requires size(graph) <= 10000
  requires 0 <= start < size(graph)
  requires 0 <= target < size(graph)
  ensures match res {
    case Some(dist) => is_shortest_distance(graph, start, target, dist)
    case None => !reachable(graph, start, target)
  }
{
  var n := |graph.adj|;
  var reached: seq<bool> := [];
  var idx := 0;
  while idx < n
    invariant 0 <= idx <= n
    invariant |reached| == idx
    invariant forall v: int :: 0 <= v < idx ==> (reached[v] <==> v == start)
  {
    reached := reached + [idx == start];
    idx := idx + 1;
  }

  LemmaInitSound(graph, start, reached);
  LemmaInitComplete(graph, start, reached);
  LemmaInitNoShorter(graph, start, target);

  var d := 0;
  while true
    invariant 0 <= d
    invariant |reached| == n
    invariant reached[start]
    invariant sound_le(graph, start, reached, d)
    invariant complete_le(graph, start, reached, d)
    invariant no_path_shorter(graph, start, target, d)
    decreases count_false(reached)
  {
    if reached[target] {
      LemmaFoundShortest(graph, start, target, reached, d);
      return Some(d);
    }

    LemmaStepNoShorter(graph, start, target, reached, d);
    var next_reached, changed, changed_w := step_layer(graph, start, reached, d);

    if !changed {
      assert next_reached == reached;
      LemmaUnreachable(graph, start, target, reached);
      return None;
    }

    LemmaCountFalseDecreases(reached, next_reached, changed_w);
    LemmaStepComplete(graph, start, reached, next_reached, d);
    reached := next_reached;
    d := d + 1;
  }
}
