function OptSeq(o: Option<int>): seq<int> {
    match o
    case Some(x) => [x]
    case None => []
}

function RowCosts(row: seq<(int, int)>, du: Option<int>, v: int, i: int): seq<int>
    requires 0 <= i <= |row|
    decreases |row| - i
{
    if i == |row| then []
    else
        (if row[i].0 == v then
            match du
            case Some(d) => [d + row[i].1]
            case None => []
         else [])
        + RowCosts(row, du, v, i + 1)
}

function EdgeCosts(
    g: seq<seq<(int, int)>>,
    prev: seq<Option<int>>,
    v: int,
    u: int
): seq<int>
    requires |prev| == |g|
    requires 0 <= u <= |g|
    decreases |g| - u
{
    if u == |g| then []
    else
        RowCosts(g[u], prev[u], v, 0)
        + EdgeCosts(g, prev, v, u + 1)
}

function MinOpt(xs: seq<int>): Option<int>
    decreases |xs|
{
    if |xs| == 0 then None
    else if |xs| == 1 then Some(xs[0])
    else
        match MinOpt(xs[1..])
        case None => Some(xs[0])
        case Some(m) => Some(if xs[0] <= m then xs[0] else m)
}

lemma MinOptSpec(xs: seq<int>)
    ensures match MinOpt(xs)
        case None => |xs| == 0
        case Some(m) =>
            m in xs &&
            forall x: int :: x in xs ==> m <= x
    decreases |xs|
{
    if |xs| > 1 {
        MinOptSpec(xs[1..]);
    }
}

function RelaxValue(
    g: seq<seq<(int, int)>>,
    prev: seq<Option<int>>,
    v: int
): Option<int>
    requires |prev| == |g|
    requires 0 <= v < |g|
{
    MinOpt(OptSeq(prev[v]) + EdgeCosts(g, prev, v, 0))
}

function Relax(
    g: seq<seq<(int, int)>>,
    prev: seq<Option<int>>
): seq<Option<int>>
    requires |prev| == |g|
{
    seq(|g|, v => RelaxValue(g, prev, v))
}

function Initial(g: seq<seq<(int, int)>>, start: int): seq<Option<int>>
    requires 0 <= start < |g|
{
    seq(|g|, v => if v == start then Some(0) else None)
}

function Run(
    g: seq<seq<(int, int)>>,
    start: int,
    rounds: nat
): seq<Option<int>>
    requires 0 <= start < |g|
    ensures |Run(g, start, rounds)| == |g|
    decreases rounds
{
    if rounds == 0 then Initial(g, start)
    else Relax(g, Run(g, start, rounds - 1))
}

ghost predicate Candidate(
    g: seq<seq<(int, int)>>,
    start: int,
    v: int,
    rounds: nat,
    p: seq<int>
) {
    is_path(g, p) &&
    p[0] == start &&
    p[|p| - 1] == v &&
    |p| - 1 <= rounds
}

ghost predicate VertexOptimal(
    g: seq<seq<(int, int)>>,
    start: int,
    v: int,
    rounds: nat,
    o: Option<int>
) {
    match o
    case Some(d) =>
        (exists p: seq<int> {:trigger is_path(g, p)} ::
            Candidate(g, start, v, rounds, p) &&
            path_weight(g, p) == d)
        &&
        (forall p: seq<int> {:trigger is_path(g, p)} ::
            Candidate(g, start, v, rounds, p) ==>
            d <= path_weight(g, p))
    case None =>
        forall p: seq<int> {:trigger is_path(g, p)} ::
            Candidate(g, start, v, rounds, p) ==> false
}

ghost predicate BoundedOptimal(
    g: seq<seq<(int, int)>>,
    start: int,
    rounds: nat,
    d: seq<Option<int>>
) {
    |d| == |g| &&
    forall v: int :: 0 <= v < |g| ==>
        VertexOptimal(g, start, v, rounds, d[v])
}

lemma UniqueEdgeWeight(
    graph: WeightedGraph,
    u: int,
    v: int,
    w1: int,
    w2: int
)
    requires well_formed(graph)
    requires has_edge(view(graph), u, v, w1)
    requires has_edge(view(graph), u, v, w2)
    ensures w1 == w2
{
    var i :| 0 <= u < |graph.adj| &&
             0 <= i < |graph.adj[u]| &&
             graph.adj[u][i].0 == v &&
             graph.adj[u][i].1 == w1;
    var j :| 0 <= u < |graph.adj| &&
             0 <= j < |graph.adj[u]| &&
             graph.adj[u][j].0 == v &&
             graph.adj[u][j].1 == w2;
    if i != j {
        assert graph.adj[u][i].0 != graph.adj[u][j].0;
        assert false;
    }
}

lemma GetEdgeWeightLemma(
    graph: WeightedGraph,
    u: int,
    v: int,
    w: int
)
    requires well_formed(graph)
    requires has_edge(view(graph), u, v, w)
    ensures get_edge_weight(view(graph), u, v) == w
{
    assert exists x: int :: has_edge(view(graph), u, v, x);
    assert has_edge(
        view(graph), u, v,
        get_edge_weight(view(graph), u, v));
    UniqueEdgeWeight(
        graph, u, v, w,
        get_edge_weight(view(graph), u, v));
}

lemma RowCostSound(
    row: seq<(int, int)>,
    du: Option<int>,
    v: int,
    i: int,
    c: int
)
    requires 0 <= i <= |row|
    requires c in RowCosts(row, du, v, i)
    ensures exists j: int, d: int ::
        i <= j < |row| &&
        row[j].0 == v &&
        du == Some(d) &&
        c == d + row[j].1
    decreases |row| - i
{
    assert i < |row|;
    var head :=
        if row[i].0 == v then
            match du
            case Some(d) => [d + row[i].1]
            case None => []
        else [];

    if c in head {
        match du
        case Some(d) => {
            assert c == d + row[i].1;
        }
        case None => {
            assert |head| == 0;
            assert false;
        }
    } else {
        assert c in RowCosts(row, du, v, i + 1);
        RowCostSound(row, du, v, i + 1, c);
    }
}

lemma RowCostComplete(
    row: seq<(int, int)>,
    du: int,
    v: int,
    i: int,
    j: int
)
    requires 0 <= i <= j < |row|
    requires row[j].0 == v
    ensures du + row[j].1 in RowCosts(row, Some(du), v, i)
    decreases j - i
{
    if i < j {
        RowCostComplete(row, du, v, i + 1, j);
    }
}

lemma EdgeCostSound(
    g: seq<seq<(int, int)>>,
    prev: seq<Option<int>>,
    v: int,
    first: int,
    c: int
)
    requires |prev| == |g|
    requires 0 <= first <= |g|
    requires c in EdgeCosts(g, prev, v, first)
    ensures exists u: int, j: int, du: int ::
        first <= u < |g| &&
        0 <= j < |g[u]| &&
        g[u][j].0 == v &&
        prev[u] == Some(du) &&
        c == du + g[u][j].1
    decreases |g| - first
{
    assert first < |g|;
    if c in RowCosts(g[first], prev[first], v, 0) {
        RowCostSound(g[first], prev[first], v, 0, c);
    } else {
        assert c in EdgeCosts(g, prev, v, first + 1);
        EdgeCostSound(g, prev, v, first + 1, c);
    }
}

lemma EdgeCostComplete(
    g: seq<seq<(int, int)>>,
    prev: seq<Option<int>>,
    v: int,
    first: int,
    u: int,
    j: int,
    du: int
)
    requires |prev| == |g|
    requires 0 <= first <= u < |g|
    requires 0 <= j < |g[u]|
    requires g[u][j].0 == v
    requires prev[u] == Some(du)
    ensures du + g[u][j].1 in EdgeCosts(g, prev, v, first)
    decreases u - first
{
    if first == u {
        RowCostComplete(g[u], du, v, 0, j);
    } else {
        EdgeCostComplete(g, prev, v, first + 1, u, j, du);
    }
}

lemma PathPrefix(g: seq<seq<(int, int)>>, p: seq<int>, n: int)
    requires is_path(g, p)
    requires 1 <= n <= |p|
    ensures is_path(g, p[..n])
{
    assert |p[..n]| > 0;
    assert forall i: int :: 0 <= i < |p[..n]| - 1 ==>
        connected(g, p[..n][i], p[..n][i + 1]) by {
        forall i: int | 0 <= i < |p[..n]| - 1
            ensures connected(g, p[..n][i], p[..n][i + 1])
        {
            assert p[..n][i] == p[i];
            assert p[..n][i + 1] == p[i + 1];
        }
    }
}

lemma PathSlice(g: seq<seq<(int, int)>>, p: seq<int>, lo: int, hi: int)
    requires is_path(g, p)
    requires 0 <= lo < hi <= |p|
    ensures is_path(g, p[lo..hi])
{
    assert |p[lo..hi]| > 0;
    assert forall i: int :: 0 <= i < |p[lo..hi]| - 1 ==>
        connected(g, p[lo..hi][i], p[lo..hi][i + 1]) by {
        forall i: int | 0 <= i < |p[lo..hi]| - 1
            ensures connected(g, p[lo..hi][i], p[lo..hi][i + 1])
        {
            assert p[lo..hi][i] == p[lo + i];
            assert p[lo..hi][i + 1] == p[lo + i + 1];
        }
    }
}

lemma ExtendPath(
    graph: WeightedGraph,
    p: seq<int>,
    v: int,
    w: int
)
    requires well_formed(graph)
    requires is_path(view(graph), p)
    requires has_edge(view(graph), p[|p| - 1], v, w)
    ensures is_path(view(graph), p + [v])
    ensures path_weight(view(graph), p + [v])
            == path_weight(view(graph), p) + w
{
    assert connected(view(graph), p[|p| - 1], v);
    assert forall i: int :: 0 <= i < |p + [v]| - 1 ==>
        connected(view(graph), (p + [v])[i], (p + [v])[i + 1]) by {
        forall i: int | 0 <= i < |p + [v]| - 1
            ensures connected(
                view(graph), (p + [v])[i], (p + [v])[i + 1])
        {
            if i < |p| - 1 {
                assert (p + [v])[i] == p[i];
                assert (p + [v])[i + 1] == p[i + 1];
            } else {
                assert i == |p| - 1;
            }
        }
    }
    GetEdgeWeightLemma(graph, p[|p| - 1], v, w);
    assert (p + [v])[..|p + [v]| - 1] == p;
}

lemma InitialOptimal(graph: WeightedGraph, start: int)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    ensures BoundedOptimal(view(graph), start, 0,
                           Initial(view(graph), start))
{
    assert |Initial(view(graph), start)| == size(graph);
    forall v: int | 0 <= v < size(graph)
        ensures VertexOptimal(
            view(graph), start, v, 0,
            Initial(view(graph), start)[v])
    {
        if v == start {
            assert Candidate(view(graph), start, v, 0, [start]);
            assert path_weight(view(graph), [start]) == 0;

            assert forall p: seq<int> {:trigger is_path(view(graph), p)} ::
                Candidate(view(graph), start, v, 0, p) ==>
                path_weight(view(graph), p) == 0 by {
                forall p: seq<int> {:trigger is_path(view(graph), p)}
                    | Candidate(view(graph), start, v, 0, p)
                    ensures path_weight(view(graph), p) == 0
                {
                    assert |p| == 1;
                }
            }
        } else {
            assert forall p: seq<int> {:trigger is_path(view(graph), p)} ::
                Candidate(view(graph), start, v, 0, p) ==> false by {
                forall p: seq<int> {:trigger is_path(view(graph), p)}
                    | Candidate(view(graph), start, v, 0, p)
                    ensures false
                {
                    assert |p| == 1;
                    assert p[0] == p[|p| - 1];
                }
            }
        }
    }
}

lemma CostHasCandidate(
    graph: WeightedGraph,
    start: int,
    rounds: nat,
    prev: seq<Option<int>>,
    v: int,
    c: int
)
    requires well_formed(graph)
    requires BoundedOptimal(view(graph), start, rounds, prev)
    requires 0 <= v < size(graph)
    requires c in OptSeq(prev[v]) + EdgeCosts(view(graph), prev, v, 0)
    ensures exists p: seq<int> {:trigger is_path(view(graph), p)} ::
        Candidate(view(graph), start, v, rounds + 1, p) &&
        path_weight(view(graph), p) == c
{
    if c in OptSeq(prev[v]) {
        match prev[v]
        case Some(d) => {
            assert c == d;
            assert VertexOptimal(
                view(graph), start, v, rounds, prev[v]);
            var p :| Candidate(view(graph), start, v, rounds, p)
                      && path_weight(view(graph), p) == d;
            assert Candidate(
                view(graph), start, v, rounds + 1, p);
        }
        case None => {
            assert |OptSeq(prev[v])| == 0;
            assert false;
        }
    } else {
        assert c in EdgeCosts(view(graph), prev, v, 0);
        EdgeCostSound(view(graph), prev, v, 0, c);
        var u, j, du :|
            0 <= u < size(graph) &&
            0 <= j < |graph.adj[u]| &&
            graph.adj[u][j].0 == v &&
            prev[u] == Some(du) &&
            c == du + graph.adj[u][j].1;

        assert VertexOptimal(
            view(graph), start, u, rounds, prev[u]);
        var p :| Candidate(view(graph), start, u, rounds, p)
                  && path_weight(view(graph), p) == du;

        assert has_edge(
            view(graph), u, v, graph.adj[u][j].1);
        ExtendPath(graph, p, v, graph.adj[u][j].1);
        assert Candidate(
            view(graph), start, v, rounds + 1, p + [v]);
    }
}

lemma CandidateHasLowerCost(
    graph: WeightedGraph,
    start: int,
    rounds: nat,
    prev: seq<Option<int>>,
    v: int,
    p: seq<int>
)
    requires well_formed(graph)
    requires BoundedOptimal(view(graph), start, rounds, prev)
    requires 0 <= v < size(graph)
    requires Candidate(view(graph), start, v, rounds + 1, p)
    ensures exists c: int ::
        c in OptSeq(prev[v]) + EdgeCosts(view(graph), prev, v, 0) &&
        c <= path_weight(view(graph), p)
{
    if |p| - 1 <= rounds {
        assert VertexOptimal(
            view(graph), start, v, rounds, prev[v]);
        match prev[v]
        case Some(d) => {
            assert d in OptSeq(prev[v]);
            assert d <= path_weight(view(graph), p);
        }
        case None => {
            assert false;
        }
    } else {
        assert |p| - 1 == rounds + 1;
        var q := p[..|p| - 1];
        var u := p[|p| - 2];

        PathPrefix(view(graph), p, |p| - 1);
        assert Candidate(view(graph), start, u, rounds, q);
        assert connected(view(graph), u, v);

        var w :| has_edge(view(graph), u, v, w);
        GetEdgeWeightLemma(graph, u, v, w);

        assert VertexOptimal(
            view(graph), start, u, rounds, prev[u]);
        match prev[u]
        case Some(du) => {
            assert du <= path_weight(view(graph), q);
            var j :| 0 <= j < |graph.adj[u]| &&
                      graph.adj[u][j].0 == v &&
                      graph.adj[u][j].1 == w;
            EdgeCostComplete(
                view(graph), prev, v, 0, u, j, du);
            assert path_weight(view(graph), p)
                == path_weight(view(graph), q) + w;
        }
        case None => {
            assert false;
        }
    }
}

lemma RelaxVertexOptimal(
    graph: WeightedGraph,
    start: int,
    rounds: nat,
    prev: seq<Option<int>>,
    v: int
)
    requires well_formed(graph)
    requires BoundedOptimal(view(graph), start, rounds, prev)
    requires 0 <= v < size(graph)
    ensures VertexOptimal(
        view(graph), start, v, rounds + 1,
        RelaxValue(view(graph), prev, v))
{
    var xs := OptSeq(prev[v]) + EdgeCosts(view(graph), prev, v, 0);
    MinOptSpec(xs);

    match MinOpt(xs)
    case Some(m) => {
        assert m in xs;
        CostHasCandidate(graph, start, rounds, prev, v, m);

        assert forall p: seq<int> {:trigger is_path(view(graph), p)} ::
            Candidate(view(graph), start, v, rounds + 1, p) ==>
            m <= path_weight(view(graph), p) by {
            forall p: seq<int> {:trigger is_path(view(graph), p)}
                | Candidate(view(graph), start, v, rounds + 1, p)
                ensures m <= path_weight(view(graph), p)
            {
                CandidateHasLowerCost(
                    graph, start, rounds, prev, v, p);
                var c :| c in xs &&
                          c <= path_weight(view(graph), p);
                assert m <= c;
            }
        }
    }
    case None => {
        assert |xs| == 0;
        assert forall p: seq<int> {:trigger is_path(view(graph), p)} ::
            Candidate(view(graph), start, v, rounds + 1, p) ==>
            false by {
            forall p: seq<int> {:trigger is_path(view(graph), p)}
                | Candidate(view(graph), start, v, rounds + 1, p)
                ensures false
            {
                CandidateHasLowerCost(
                    graph, start, rounds, prev, v, p);
                var c :| c in xs &&
                          c <= path_weight(view(graph), p);
                assert false;
            }
        }
    }
}

lemma RelaxOptimal(
    graph: WeightedGraph,
    start: int,
    rounds: nat,
    prev: seq<Option<int>>
)
    requires well_formed(graph)
    requires BoundedOptimal(view(graph), start, rounds, prev)
    ensures BoundedOptimal(
        view(graph), start, rounds + 1,
        Relax(view(graph), prev))
{
    assert |Relax(view(graph), prev)| == size(graph);
    forall v: int | 0 <= v < size(graph)
        ensures VertexOptimal(
            view(graph), start, v, rounds + 1,
            Relax(view(graph), prev)[v])
    {
        RelaxVertexOptimal(graph, start, rounds, prev, v);
    }
}

lemma RunOptimal(
    graph: WeightedGraph,
    start: int,
    rounds: nat
)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    ensures BoundedOptimal(
        view(graph), start, rounds,
        Run(view(graph), start, rounds))
    decreases rounds
{
    if rounds == 0 {
        InitialOptimal(graph, start);
    } else {
        RunOptimal(graph, start, rounds - 1);
        RelaxOptimal(
            graph, start, rounds - 1,
            Run(view(graph), start, rounds - 1));
    }
}

lemma PathVerticesBound(graph: WeightedGraph, p: seq<int>)
    requires well_formed(graph)
    requires is_path(view(graph), p)
    requires |p| >= 2
    ensures forall i: int :: 0 <= i < |p| ==>
        0 <= p[i] < size(graph)
{
    forall i: int | 0 <= i < |p|
        ensures 0 <= p[i] < size(graph)
    {
        if i < |p| - 1 {
            assert connected(view(graph), p[i], p[i + 1]);
            var w :| has_edge(view(graph), p[i], p[i + 1], w);
        } else {
            assert connected(
                view(graph), p[i - 1], p[i]);
            var w :| has_edge(view(graph), p[i - 1], p[i], w);
        }
    }
}

lemma Pigeonhole(p: seq<int>, n: nat)
    requires |p| > n
    requires forall i: int :: 0 <= i < |p| ==> 0 <= p[i] < n
    ensures exists i: int, j: int ::
        0 <= i < j < |p| && p[i] == p[j]
    decreases n
{
    if n == 0 {
        assert |p| > 0;
        assert 0 <= p[0] < 0;
        assert false;
    } else {
        var last := |p| - 1;
        var x := p[last];
        var q := p[..last];

        if exists i: int :: 0 <= i < |q| && q[i] == x {
            var i :| 0 <= i < |q| && q[i] == x;
            assert p[i] == p[last];
        } else {
            var r := seq(|q|, i =>
                if q[i] < x then q[i] else q[i] - 1);

            assert |r| > n - 1;
            assert forall i: int :: 0 <= i < |r| ==>
                0 <= r[i] < n - 1 by {
                forall i: int | 0 <= i < |r|
                    ensures 0 <= r[i] < n - 1
                {
                    assert q[i] != x;
                    if q[i] < x {
                        assert q[i] <= x - 1;
                    } else {
                        assert q[i] >= x + 1;
                    }
                }
            }

            Pigeonhole(r, n - 1);
            var i, j :| 0 <= i < j < |r| && r[i] == r[j];

            if q[i] < x {
                if q[j] >= x {
                    assert q[j] != x;
                    assert q[j] >= x + 1;
                    assert r[i] <= x - 1;
                    assert r[j] >= x;
                    assert false;
                }
            } else {
                assert q[i] != x;
                assert q[i] >= x + 1;
                if q[j] < x {
                    assert r[j] <= x - 1;
                    assert r[i] >= x;
                    assert false;
                }
            }
            assert q[i] == q[j];
            assert p[i] == p[j];
        }
    }
}

lemma ConcatPaths(
    g: seq<seq<(int, int)>>,
    a: seq<int>,
    b: seq<int>
)
    requires is_path(g, a)
    requires is_path(g, b)
    requires a[|a| - 1] == b[0]
    ensures is_path(g, a + b[1..])
    ensures path_weight(g, a + b[1..])
        == path_weight(g, a) + path_weight(g, b)
    decreases |b|
{
    if |b| == 1 {
        assert b[1..] == [];
        assert path_weight(g, b) == 0;
    } else {
        var b0 := b[..|b| - 1];
        PathPrefix(g, b, |b| - 1);
        ConcatPaths(g, a, b0);

        var c := a + b0[1..];
        assert c[|c| - 1] == b[|b| - 2];
        assert connected(g, b[|b| - 2], b[|b| - 1]);
        assert is_path(g, c + [b[|b| - 1]]);
        assert a + b[1..] == c + [b[|b| - 1]];
        assert (c + [b[|b| - 1]])[..|c|] == c;
    }
}

lemma SplicePath(
    g: seq<seq<(int, int)>>,
    p: seq<int>,
    i: int,
    j: int
) returns (cycle: seq<int>, rest: seq<int>)
    requires is_path(g, p)
    requires 0 <= i < j < |p|
    requires p[i] == p[j]
    ensures cycle == p[i..j + 1]
    ensures rest == p[..i + 1] + p[j + 1..]
    ensures is_path(g, cycle)
    ensures cycle[0] == cycle[|cycle| - 1]
    ensures is_path(g, rest)
    ensures rest[0] == p[0]
    ensures rest[|rest| - 1] == p[|p| - 1]
    ensures path_weight(g, p)
        == path_weight(g, rest) + path_weight(g, cycle)
    ensures |rest| < |p|
{
    cycle := p[i..j + 1];
    var left := p[..i + 1];
    var right := p[j..];
    rest := left + right[1..];

    PathSlice(g, p, i, j + 1);
    PathPrefix(g, p, i + 1);
    PathSlice(g, p, j, |p|);

    ConcatPaths(g, left, cycle);
    var throughCycle := left + cycle[1..];
    assert throughCycle == p[..j + 1];

    ConcatPaths(g, throughCycle, right);
    assert throughCycle + right[1..] == p;

    ConcatPaths(g, left, right);
    assert path_weight(g, throughCycle)
        == path_weight(g, left) + path_weight(g, cycle);
    assert path_weight(g, p)
        == path_weight(g, throughCycle) + path_weight(g, right);
    assert path_weight(g, rest)
        == path_weight(g, left) + path_weight(g, right);
}

lemma SimplifyPath(
    graph: WeightedGraph,
    p: seq<int>
) returns (q: seq<int>)
    requires well_formed(graph)
    requires !has_negative_cycle(view(graph))
    requires is_path(view(graph), p)
    requires 0 <= p[0] < size(graph)
    requires 0 <= p[|p| - 1] < size(graph)
    ensures is_path(view(graph), q)
    ensures q[0] == p[0]
    ensures q[|q| - 1] == p[|p| - 1]
    ensures |q| <= size(graph)
    ensures path_weight(view(graph), q)
        <= path_weight(view(graph), p)
    decreases |p|
{
    if |p| <= size(graph) {
        q := p;
    } else {
        PathVerticesBound(graph, p);
        Pigeonhole(p, size(graph));
        var i, j :| 0 <= i < j < |p| && p[i] == p[j];

        var cycle, rest := SplicePath(view(graph), p, i, j);
        assert |cycle| > 1;
        assert cycle[0] == cycle[|cycle| - 1];
        assert path_weight(view(graph), cycle) >= 0;
        q := SimplifyPath(graph, rest);
    }
}

lemma ShortNegativeCycle(
    graph: WeightedGraph,
    p: seq<int>
) returns (q: seq<int>)
    requires well_formed(graph)
    requires is_path(view(graph), p)
    requires |p| > 1
    requires p[0] == p[|p| - 1]
    requires path_weight(view(graph), p) < 0
    ensures is_path(view(graph), q)
    ensures |q| > 1
    ensures q[0] == q[|q| - 1]
    ensures path_weight(view(graph), q) < 0
    ensures |q| <= size(graph) + 1
    decreases |p|
{
    if |p| <= size(graph) + 1 {
        q := p;
    } else {
        PathVerticesBound(graph, p);
        var prefix := p[..|p| - 1];
        assert |prefix| > size(graph);
        assert forall i: int :: 0 <= i < |prefix| ==>
            0 <= prefix[i] < size(graph);
        Pigeonhole(prefix, size(graph));

        var i, j :|
            0 <= i < j < |prefix| && prefix[i] == prefix[j];
        var cycle, rest := SplicePath(view(graph), p, i, j);

        assert |cycle| > 1;
        assert cycle[0] == cycle[|cycle| - 1];
        assert |rest| > 1;
        assert rest[0] == rest[|rest| - 1];

        if path_weight(view(graph), cycle) < 0 {
            q := ShortNegativeCycle(graph, cycle);
        } else {
            assert path_weight(view(graph), rest) < 0;
            q := ShortNegativeCycle(graph, rest);
        }
    }
}

function NegativeSource(
    g: seq<seq<(int, int)>>,
    first: int
): Option<int>
    requires 0 <= first <= |g|
    decreases |g| - first
{
    if first == |g| then None
    else
        match Run(g, first, |g|)[first]
        case Some(d) =>
            if d < 0 then Some(first)
            else NegativeSource(g, first + 1)
        case None =>
            NegativeSource(g, first + 1)
}

lemma NegativeSourceSpec(
    graph: WeightedGraph,
    first: int
)
    requires well_formed(graph)
    requires 0 <= first <= size(graph)
    ensures match NegativeSource(view(graph), first)
        case Some(s) =>
            first <= s < size(graph) &&
            (match Run(view(graph), s, size(graph))[s]
             case Some(d) => d < 0
             case None => false)
        case None =>
            forall s: int :: first <= s < size(graph) ==>
                (match Run(view(graph), s, size(graph))[s]
                 case Some(d) => d >= 0
                 case None => true)
    decreases size(graph) - first
{
    if first < size(graph) {
        match Run(view(graph), first, size(graph))[first]
        case Some(d) => {
            if d >= 0 {
                NegativeSourceSpec(graph, first + 1);
            }
        }
        case None => {
            NegativeSourceSpec(graph, first + 1);
        }
    }
}

lemma NoNegativeCycle(
    graph: WeightedGraph
)
    requires well_formed(graph)
    requires size(graph) > 0
    requires NegativeSource(view(graph), 0) == None
    ensures !has_negative_cycle(view(graph))
{
    NegativeSourceSpec(graph, 0);

    if has_negative_cycle(view(graph)) {
        var p :| is_path(view(graph), p) &&
                  |p| > 1 &&
                  p[0] == p[|p| - 1] &&
                  path_weight(view(graph), p) < 0;

        var q := ShortNegativeCycle(graph, p);
        PathVerticesBound(graph, q);
        var s := q[0];
        assert 0 <= s < size(graph);
        assert Candidate(
            view(graph), s, s, size(graph), q);

        RunOptimal(graph, s, size(graph));
        assert VertexOptimal(
            view(graph), s, s, size(graph),
            Run(view(graph), s, size(graph))[s]);

        match Run(view(graph), s, size(graph))[s]
        case Some(d) => {
            assert d <= path_weight(view(graph), q);
            assert d < 0;
            assert false;
        }
        case None => {
            assert false;
        }
    }
}

lemma FinalDistances(
    graph: WeightedGraph,
    start: int
)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    requires !has_negative_cycle(view(graph))
    ensures |Run(view(graph), start, size(graph) - 1)|
        == size(graph)
    ensures forall v: int :: 0 <= v < size(graph) ==>
        (match Run(view(graph), start, size(graph) - 1)[v]
         case Some(d) =>
            is_shortest_dist(view(graph), start, v, d)
         case None =>
            forall p: seq<int> {:trigger is_path(view(graph), p)} ::
                (is_path(view(graph), p) &&
