        match Run(view(graph), s, size(graph))[s]
        case Some(d) => {
            assert d <= path_weight(view(graph), q);
            assert d < 0;
            assert false;
        }
        case None => {
            assert false;
        }
    }
}

lemma FinalDistances(
    graph: WeightedGraph,
    start: int
)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    requires !has_negative_cycle(view(graph))
    ensures |Run(view(graph), start, size(graph) - 1)|
        == size(graph)
    ensures forall v: int :: 0 <= v < size(graph) ==>
        (match Run(view(graph), start, size(graph) - 1)[v]
         case Some(d) =>
            is_shortest_dist(view(graph), start, v, d)
         case None =>
            forall p: seq<int> {:trigger is_path(view(graph), p)} ::
                (is_path(view(graph), p) &&
                 p[0] == start &&
                 p[|p| - 1] == v) ==> false)
{
    RunOptimal(graph, start, size(graph) - 1);
    var ds := Run(view(graph), start, size(graph) - 1);

    forall v: int | 0 <= v < size(graph)
        ensures
            match ds[v]
            case Some(d) =>
                is_shortest_dist(view(graph), start, v, d)
            case None =>
                forall p: seq<int> {:trigger is_path(view(graph), p)} ::
                    (is_path(view(graph), p) &&
                     p[0] == start &&
                     p[|p| - 1] == v) ==> false
    {
        assert VertexOptimal(
            view(graph), start, v, size(graph) - 1, ds[v]);

        match ds[v]
        case Some(d) => {
            var wp :|
                Candidate(
                    view(graph), start, v,
                    size(graph) - 1, wp) &&
                path_weight(view(graph), wp) == d;

            assert forall p: seq<int>
                {:trigger is_path(view(graph), p)} ::
                is_path(view(graph), p) &&
                p[0] == start &&
                p[|p| - 1] == v ==>
                path_weight(view(graph), p) >= d by {
                forall p: seq<int>
                    {:trigger is_path(view(graph), p)}
                    | is_path(view(graph), p) &&
                      p[0] == start &&
                      p[|p| - 1] == v
                    ensures path_weight(view(graph), p) >= d
                {
                    var q := SimplifyPath(graph, p);
                    assert Candidate(
                        view(graph), start, v,
                        size(graph) - 1, q);
                    assert d <= path_weight(view(graph), q);
                }
            }
        }
        case None => {
            assert forall p: seq<int>
                {:trigger is_path(view(graph), p)} ::
                (is_path(view(graph), p) &&
                 p[0] == start &&
                 p[|p| - 1] == v) ==> false by {
                forall p: seq<int>
                    {:trigger is_path(view(graph), p)}
                    | is_path(view(graph), p) &&
                      p[0] == start &&
                      p[|p| - 1] == v
                    ensures false
                {
                    var q := SimplifyPath(graph, p);
                    assert Candidate(
                        view(graph), start, v,
                        size(graph) - 1, q);
                    assert false;
                }
            }
        }
    }
}

method bellman_ford(graph: WeightedGraph, start: int) returns (res: Option<seq<Option<int>>>)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    requires weights_and_size_bounded(view(graph))
    ensures match res {
        case Some(dists) => 
            |dists| == size(graph) &&
            forall v: int :: 0 <= v < size(graph) ==> (
                match dists[v] {
                    case Some(d) => is_shortest_dist(view(graph), start, v, d)
                    case None => forall p: seq<int> {:trigger is_path(view(graph), p)} :: 
                                    is_path(view(graph), p) && p[0] == start && p[|p| - 1] == v ==> false
                }
            )
        case None => 
            has_negative_cycle(view(graph))
    }
{
    var bad := NegativeSource(graph.adj, 0);
    NegativeSourceSpec(graph, 0);

    match bad
    case Some(s) => {
        RunOptimal(graph, s, |graph.adj|);
        var ds := Run(graph.adj, s, |graph.adj|);

        match ds[s]
        case Some(d) => {
            assert d < 0;
            assert VertexOptimal(
                view(graph), s, s, size(graph), ds[s]);
            var p :|
                Candidate(view(graph), s, s, size(graph), p) &&
                path_weight(view(graph), p) == d;
            assert |p| > 1;
            assert p[0] == p[|p| - 1];
            assert has_negative_cycle(view(graph));
        }
        case None => {
            assert false;
        }

        res := None;
    }
    case None => {
        NoNegativeCycle(graph);
        FinalDistances(graph, start);
        res := Some(
            Run(graph.adj, start, |graph.adj| - 1));
    }
}
