ghost predicate LowerBound(g: Graph, s: int, D: seq<int>, k: int) {
  forall p: seq<int> {:trigger is_path(g, p)} ::
    is_path(g, p) && p[0] == s && |p| <= k + 1 ==>
      0 <= p[|p| - 1] < |D| && 0 <= D[p[|p| - 1]] <= |p| - 1
}

ghost predicate ClosedUpTo(g: Graph, D: seq<int>, k: int) {
  forall u: int, j: int ::
    0 <= u < |D| && 0 <= D[u] < k && 0 <= u < |g.adj| && 0 <= j < |g.adj[u]| ==>
      0 <= g.adj[u][j] < |D| && 0 <= D[g.adj[u][j]] <= D[u] + 1
}

ghost predicate Bounds(D: seq<int>, k: int) {
