method ProcessLevel(graph: Graph, ghost start: int, dist: seq<int>, frontier: seq<int>, k: int)
  returns (dist': seq<int>, next: seq<int>)
  requires well_formed(graph)
  requires |dist| == |graph.adj|
  requires k >= 0
  requires Bounds(dist, k)
  requires InRange(frontier, |dist|)
  requires LevelSet(dist, k, frontier)
  requires Reached(graph, start, dist)
  requires LowerBound(graph, start, dist, k)
  requires ClosedUpTo(graph, dist, k)
  ensures |dist'| == |dist|
  ensures Bounds(dist', k + 1)
  ensures InRange(next, |dist|)
  ensures LevelSet(dist', k + 1, next)
  ensures Reached(graph, start, dist')
  ensures LowerBound(graph, start, dist', k + 1)
  ensures ClosedUpTo(graph, dist', k + 1)
  ensures forall v :: 0 <= v < |dist| && dist[v] >= 0 ==> dist'[v] == dist[v]
  ensures Unvisited(dist') <= Unvisited(dist)
  ensures |next| == 0 ==> Unvisited(dist') == Unvisited(dist)
  ensures |next| > 0 ==> Unvisited(dist') < Unvisited(dist)
{
  dist' := dist;
  next := [];
  var i := 0;
  while i < |frontier|
    invariant 0 <= i <= |frontier|
    invariant |dist'| == |dist|
    invariant Bounds(dist', k + 1)
    invariant LevelSet(dist', k, frontier)
    invariant InRange(next, |dist|)
    invariant LevelSet(dist', k + 1, next)
    invariant Reached(graph, start, dist')
    invariant LowerBound(graph, start, dist', k)
    invariant ClosedUpTo(graph, dist', k)
    invariant forall v :: 0 <= v < |dist| && dist[v] >= 0 ==> dist'[v] == dist[v]
    invariant forall ii, j :: 0 <= ii < i && 0 <= j < |graph.adj[frontier[ii]]| ==>
                0 <= dist'[graph.adj[frontier[ii]][j]] <= k + 1
    invariant Unvisited(dist') <= Unvisited(dist)
    invariant |next| == 0 ==> Unvisited(dist') == Unvisited(dist)
    invariant |next| > 0 ==> Unvisited(dist') < Unvisited(dist)
  {
    var u := frontier[i];
    assert u in frontier;
    assert 0 <= u < |dist'|;
    assert dist'[u] == k;
    ghost var dOld := dist';
    ghost var nOld := next;
    dist', next := ProcessVertex(graph, start, dist', next, k, u, frontier);
    assert forall ii, j :: 0 <= ii < i && 0 <= j < |graph.adj[frontier[ii]]| ==>
             0 <= dOld[graph.adj[frontier[ii]][j]] <= k + 1;
    assert forall ii, j :: 0 <= ii < i + 1 && 0 <= j < |graph.adj[frontier[ii]]| ==>
             0 <= dist'[graph.adj[frontier[ii]][j]] <= k + 1 by {
      forall ii, j | 0 <= ii < i + 1 && 0 <= j < |graph.adj[frontier[ii]]|
        ensures 0 <= dist'[graph.adj[frontier[ii]][j]] <= k + 1
      {
