  }

  assert ClosedUpTo(graph, dist', k + 1) by {
    forall u: int, j: int |
      0 <= u < |dist'| && 0 <= dist'[u] < k + 1 && 0 <= u < |graph.adj| && 0 <= j < |graph.adj[u]|
      ensures 0 <= graph.adj[u][j] < |dist'| && 0 <= dist'[graph.adj[u][j]] <= dist'[u] + 1
    {
      if dist'[u] < k {
      } else {
        assert dist'[u] == k;
        assert u in frontier;
        var ii :| 0 <= ii < |frontier| && frontier[ii] == u;
        assert graph.adj[frontier[ii]][j] == graph.adj[u][j];
        assert 0 <= dist'[graph.adj[frontier[ii]][j]] <= k + 1;
      }
    }
  }
