}

method bfs_shortest_path(graph: Graph, start: int, target: int) returns (res: Option<int>)
  requires well_formed(graph)
  requires size(graph) <= 10000
  requires 0 <= start < size(graph)
  requires 0 <= target < size(graph)
  ensures match res {
    case Some(dist) => is_shortest_distance(graph, start, target, dist)
    case None => !reachable(graph, start, target)
  }
{
  var n := |graph.adj|;
  var dist: seq<int> := seq(n, _ => -1);
  dist := dist[start := 0];
  var frontier: seq<int> := [start];
  var k := 0;

  assert PathTo(graph, start, start, 1) by {
    var p := [start];
    assert is_path(graph, p) && p[0] == start && p[|p| - 1] == start && |p| == 1;
  }
  assert Reached(graph, start, dist) by {
    forall v | 0 <= v < |dist| && dist[v] >= 0
      ensures PathTo(graph, start, v, dist[v] + 1)
    {
      assert v == start;
    }
  }
  assert LowerBound(graph, start, dist, 0) by {
    forall p: seq<int> | is_path(graph, p) && p[0] == start && |p| <= 1
      ensures 0 <= p[|p| - 1] < |dist| && 0 <= dist[p[|p| - 1]] <= |p| - 1
    {
      assert |p| == 1;
      assert p[|p| - 1] == start;
    }
  }
  assert ClosedUpTo(graph, dist, 0);
  assert LevelSet(dist, 0, frontier);
  assert Bounds(dist, 0);
  assert InRange(frontier, n);

  while |frontier| > 0
    invariant |dist| == n
    invariant k >= 0
    invariant Bounds(dist, k)
    invariant dist[start] == 0
    invariant InRange(frontier, n)
    invariant LevelSet(dist, k, frontier)
    invariant Reached(graph, start, dist)
    invariant LowerBound(graph, start, dist, k)
    invariant ClosedUpTo(graph, dist, k)
    decreases Unvisited(dist), |frontier|
  {
    var next;
    dist, next := ProcessLevel(graph, start, dist, frontier, k);
    frontier := next;
    k := k + 1;
  }

  assert forall v :: 0 <= v < n ==> dist[v] < k by {
    forall v | 0 <= v < n
      ensures dist[v] < k
    {
      assert v !in frontier;
    }
  }

  if dist[target] >= 0 {
    res := Some(dist[target]);
    assert PathTo(graph, start, target, dist[target] + 1);
    forall p: seq<int> | is_path(graph, p) && p[0] == start && p[|p| - 1] == target
      ensures |p| >= dist[target] + 1
    {
      if |p| < dist[target] + 1 {
        assert |p| <= k + 1;
        assert dist[p[|p| - 1]] <= |p| - 1;
        assert false;
      }
    }
  } else {
    res := None;
    NotReachable(graph, start, target, dist, k);
  }
}

