ghost predicate PathTo(g: Graph, s: int, v: int, len: int) {
  exists p: seq<int> {:trigger is_path(g, p)} ::
    is_path(g, p) && p[0] == s && p[|p| - 1] == v && |p| == len
}

ghost predicate LowerBound(g: Graph, s: int, D: seq<int>, k: int) {
  forall p: seq<int> {:trigger is_path(g, p)} ::
    is_path(g, p) && p[0] == s && |p| <= k + 1 ==>
      0 <= p[|p| - 1] < |D| && 0 <= D[p[|p| - 1]] <= |p| - 1
}

ghost predicate ClosedUpTo(g: Graph, D: seq<int>, k: int) {
  forall u: int, j: int ::
    0 <= u < |D| && 0 <= D[u] < k && 0 <= u < |g.adj| && 0 <= j < |g.adj[u]| ==>
      0 <= g.adj[u][j] < |D| && 0 <= D[g.adj[u][j]] <= D[u] + 1
}

ghost predicate Bounds(D: seq<int>, k: int) {
  forall v :: 0 <= v < |D| ==> -1 <= D[v] <= k
}

ghost predicate Reached(g: Graph, s: int, D: seq<int>) {
  forall v :: 0 <= v < |D| && D[v] >= 0 ==> PathTo(g, s, v, D[v] + 1)
}

ghost predicate LevelSet(D: seq<int>, k: int, fr: seq<int>) {
  forall v :: 0 <= v < |D| ==> (D[v] == k <==> v in fr)
}

ghost predicate InRange(fr: seq<int>, n: int) {
  forall i :: 0 <= i < |fr| ==> 0 <= fr[i] < n
}

ghost function Unvisited(D: seq<int>): set<int> {
  set v | 0 <= v < |D| && D[v] == -1
}

