lemma ExtendPath(g: Graph, s: int, u: int, v: int, len: int)
  requires PathTo(g, s, u, len)
  requires has_edge(g, u, v)
  ensures PathTo(g, s, v, len + 1)
{
  var p :| is_path(g, p) && p[0] == s && p[|p| - 1] == u && |p| == len;
  var q := p + [v];
