lemma NegCycle(graph: WeightedGraph, start: int, D: seq<Option<int>>, u: int, i: int)
  requires well_formed(graph)
  requires 0 <= start < |graph.adj|
  requires |D| == |graph.adj|
  requires Witnessed(graph.adj, start, D, |graph.adj|)
  requires Bounded(graph.adj, start, D, |graph.adj|)
  requires 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]|
  requires D[u].Some?
  requires D[graph.adj[u][i].0].None? || D[u].value + graph.adj[u][i].1 < D[graph.adj[u][i].0].value
  ensures has_negative_cycle(graph.adj)
{
  var g := graph.adj;
  var n := |g|;
  var v := g[u][i].0;
  var w := g[u][i].1;
  assert HasWitness(g, start, u, n, D[u].value);
  var pu :| is_path(g, pu) && pu[0] == start && pu[|pu| - 1] == u && |pu| <= n && path_weight(g, pu) == D[u].value;
  AppendEdge(graph, pu, u, i);
  var q := pu + [v];
  assert is_path(g, q);
  assert q[0] == start && q[|q| - 1] == v;
  assert path_weight(g, q) == D[u].value + w;
  if |q| <= n {
    assert D[v].Some? && D[v].value <= path_weight(g, q);
    assert false;
  }
  PathInRange(graph, q);
  Pigeonhole(q, n);
  var a, b :| 0 <= a < b < |q| && q[a] == q[b];
  CycleSplit(g, q, a, b);
  var c := q[a..b + 1];
  var q' := q[..a] + q[b..];
  assert is_path(g, q');
  assert q'[0] == start;
  assert |q'| <= n;
  assert q'[|q'| - 1] == v;
  assert D[v].Some? && D[v].value <= path_weight(g, q');
  assert path_weight(g, q) == path_weight(g, q') + path_weight(g, c);
  assert path_weight(g, c) < 0;
  assert is_path(g, c) && |c| > 1 && c[0] == c[|c| - 1];
}

lemma FixedPointBound(graph: WeightedGraph, start: int, D: seq<Option<int>>, p: seq<int>)
  requires well_formed(graph)
  requires 0 <= start < |graph.adj|
  requires |D| == |graph.adj|
  requires D[start].Some? && D[start].value <= 0
  requires Fixed(graph.adj, D)
  requires is_path(graph.adj, p) && p[0] == start
  ensures 0 <= p[|p| - 1] < |D| && D[p[|p| - 1]].Some? && D[p[|p| - 1]].value <= path_weight(graph.adj, p)
  decreases |p|
{
  var g := graph.adj;
  if |p| == 1 {
    assert p[|p| - 1] == start;
  } else {
    var p' := p[..|p| - 1];
    PrefixPath(g, p, |p| - 1);
    assert p'[0] == start;
    FixedPointBound(graph, start, D, p');
    var j := |p| - 2;
    var x := p[j];
    var y := p[j + 1];
    assert y == p[|p| - 1];
    assert p'[|p'| - 1] == x;
    assert connected(g, x, y);
    var w :| has_edge(g, x, y, w);
    var e :| 0 <= x < |g| && 0 <= e < |g[x]| && g[x][e].0 == y && g[x][e].1 == w;
    EdgeWeight(graph, x, e);
    assert path_weight(g, p) == path_weight(g, p') + get_edge_weight(g, p[|p| - 2], p[|p| - 1]);
  }
}

lemma FinalCorrect(graph: WeightedGraph, start: int, D: seq<Option<int>>)
  requires well_formed(graph)
  requires 0 <= start < |graph.adj|
  requires |D| == |graph.adj|
  requires Witnessed(graph.adj, start, D, |graph.adj|)
  requires Bounded(graph.adj, start, D, |graph.adj|)
  requires Fixed(graph.adj, D)
  ensures forall v: int :: 0 <= v < size(graph) ==> (
    match D[v] {
      case Some(d) => is_shortest_dist(view(graph), start, v, d)
      case None => forall p: seq<int> {:trigger is_path(view(graph), p)} ::
                     is_path(view(graph), p) && p[0] == start && p[|p| - 1] == v ==> false
    })
{
  var g := graph.adj;
  var n := |g|;
  assert view(graph) == g;
  assert size(graph) == n;
  var p0 := [start];
  assert is_path(g, p0);
  assert p0[0] == start && p0[|p0| - 1] == start && |p0| <= n;
  assert D[start].Some? && D[start].value <= path_weight(g, p0);
  assert path_weight(g, p0) == 0;
  forall v | 0 <= v < size(graph)
    ensures (match D[v] {
      case Some(d) => is_shortest_dist(view(graph), start, v, d)
      case None => forall p: seq<int> {:trigger is_path(view(graph), p)} ::
                     is_path(view(graph), p) && p[0] == start && p[|p| - 1] == v ==> false
    })
  {
    match D[v] {
      case Some(d) =>
        assert HasWitness(g, start, v, n, d);
        var pw0 :| is_path(g, pw0) && pw0[0] == start && pw0[|pw0| - 1] == v && |pw0| <= n && path_weight(g, pw0) == d;
        forall p | is_path(g, p) && p[0] == start && p[|p| - 1] == v
          ensures path_weight(g, p) >= d
        {
