        }
    }
  }
}

method Relax(graph: WeightedGraph, start: int, D: seq<Option<int>>, L: int) returns (newD: seq<Option<int>>)
  requires well_formed(graph)
  requires 0 <= start < |graph.adj|
  requires |D| == |graph.adj|
  requires L >= 1
  requires Witnessed(graph.adj, start, D, L)
  requires Bounded(graph.adj, start, D, L)
  ensures |newD| == |graph.adj|
  ensures Witnessed(graph.adj, start, newD, L + 1)
  ensures Bounded(graph.adj, start, newD, L + 1)
{
  var n := |graph.adj|;
  WitnessedMono(graph.adj, start, D, L);
  newD := D;
  var u := 0;
  while u < n
    invariant 0 <= u <= n
    invariant |newD| == n
    invariant Witnessed(graph.adj, start, newD, L + 1)
    invariant forall v :: 0 <= v < n && D[v].Some? ==> newD[v].Some? && newD[v].value <= D[v].value
    invariant forall u', i' :: 0 <= u' < u && 0 <= i' < |graph.adj[u']| && D[u'].Some? ==>
      0 <= graph.adj[u'][i'].0 < n && newD[graph.adj[u'][i'].0].Some? && newD[graph.adj[u'][i'].0].value <= D[u'].value + graph.adj[u'][i'].1
  {
    if D[u].Some? {
      var i := 0;
      while i < |graph.adj[u]|
        invariant 0 <= i <= |graph.adj[u]|
        invariant |newD| == n
        invariant Witnessed(graph.adj, start, newD, L + 1)
        invariant forall v :: 0 <= v < n && D[v].Some? ==> newD[v].Some? && newD[v].value <= D[v].value
        invariant forall u', i' :: 0 <= u' < u && 0 <= i' < |graph.adj[u']| && D[u'].Some? ==>
          0 <= graph.adj[u'][i'].0 < n && newD[graph.adj[u'][i'].0].Some? && newD[graph.adj[u'][i'].0].value <= D[u'].value + graph.adj[u'][i'].1
        invariant forall i' :: 0 <= i' < i ==>
          0 <= graph.adj[u][i'].0 < n && newD[graph.adj[u][i'].0].Some? && newD[graph.adj[u][i'].0].value <= D[u].value + graph.adj[u][i'].1
      {
        var v := graph.adj[u][i].0;
        var w := graph.adj[u][i].1;
        var cand := D[u].value + w;
        if newD[v].None? || cand < newD[v].value {
          ExtendWitness(graph, start, D, L, u, i);
          WitnessedUpdate(graph.adj, start, newD, L + 1, v, cand);
          newD := newD[v := Some(cand)];
        }
        i := i + 1;
      }
    }
    u := u + 1;
  }
  RelaxBounded(graph, start, D, newD, L);
}

method bellman_ford(graph: WeightedGraph, start: int) returns (res: Option<seq<Option<int>>>)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    requires weights_and_size_bounded(view(graph))
    ensures match res {
        case Some(dists) => 
            |dists| == size(graph) &&
            forall v: int :: 0 <= v < size(graph) ==> (
                match dists[v] {
                    case Some(d) => is_shortest_dist(view(graph), start, v, d)
                    case None => forall p: seq<int> {:trigger is_path(view(graph), p)} :: 
                                    is_path(view(graph), p) && p[0] == start && p[|p| - 1] == v ==> false
                }
            )
        case None => 
            has_negative_cycle(view(graph))
    }
{
  var n := |graph.adj|;
  var D: seq<Option<int>> := seq(n, k => if k == start then Some(0) else None);
  InitInv(graph, start, D);
  var round := 1;
  while round < n
    invariant 1 <= round <= n
    invariant |D| == n
    invariant Witnessed(graph.adj, start, D, round)
    invariant Bounded(graph.adj, start, D, round)
    decreases n - round
  {
    D := Relax(graph, start, D, round);
    round := round + 1;
  }
  var u := 0;
  while u < n
    invariant 0 <= u <= n
    invariant forall u', i' :: 0 <= u' < u && 0 <= i' < |graph.adj[u']| && D[u'].Some? ==>
      0 <= graph.adj[u'][i'].0 < n && D[graph.adj[u'][i'].0].Some? && D[graph.adj[u'][i'].0].value <= D[u'].value + graph.adj[u'][i'].1
  {
    if D[u].Some? {
      var i := 0;
      while i < |graph.adj[u]|
        invariant 0 <= i <= |graph.adj[u]|
        invariant forall u', i' :: 0 <= u' < u && 0 <= i' < |graph.adj[u']| && D[u'].Some? ==>
          0 <= graph.adj[u'][i'].0 < n && D[graph.adj[u'][i'].0].Some? && D[graph.adj[u'][i'].0].value <= D[u'].value + graph.adj[u'][i'].1
        invariant forall i' :: 0 <= i' < i ==>
          0 <= graph.adj[u][i'].0 < n && D[graph.adj[u][i'].0].Some? && D[graph.adj[u][i'].0].value <= D[u].value + graph.adj[u][i'].1
      {
        var v := graph.adj[u][i].0;
        var w := graph.adj[u][i].1;
        if D[v].None? || D[u].value + w < D[v].value {
          NegCycle(graph, start, D, u, i);
          return None;
        }
        i := i + 1;
      }
    }
    u := u + 1;
  }
  assert Fixed(graph.adj, D);
  FinalCorrect(graph, start, D);
  return Some(D);
}
