  if i < |g.adj[u]| {
    RowCheckSpec(g, colors, u, i + 1);

    if RowCheck(g, colors, u, i) {
      assert colors[u] != colors[g.adj[u][i]];
      assert RowCheck(g, colors, u, i + 1);

      forall j: int | i <= j < |g.adj[u]|
        ensures colors[u] != colors[g.adj[u][j]]
      {
        if j != i {
          assert i + 1 <= j;
        }
      }
    }

    if forall j: int ::
         i <= j < |g.adj[u]| ==>
         colors[u] != colors[g.adj[u][j]]
    {
      assert colors[u] != colors[g.adj[u][i]];
      assert forall j: int ::
        i + 1 <= j < |g.adj[u]| ==>
        colors[u] != colors[g.adj[u][j]];
      assert RowCheck(g, colors, u, i + 1);
    }
  }
}

function RowsCheck(g: Graph, colors: seq<bool>, u: int): bool
  requires well_formed(g)
  requires |colors| == size(g)
  requires 0 <= u <= size(g)
  decreases size(g) - u
{
  if u == size(g) then
    true
  else
    RowCheck(g, colors, u, 0)
    && RowsCheck(g, colors, u + 1)
}

lemma RowsCheckSpec(g: Graph, colors: seq<bool>, u: int)
  requires well_formed(g)
  requires |colors| == size(g)
  requires 0 <= u <= size(g)
  ensures RowsCheck(g, colors, u) ==>
    (forall x: int, i: int ::
      u <= x < size(g) && 0 <= i < |g.adj[x]| ==>
      colors[x] != colors[g.adj[x][i]])
  ensures
    (forall x: int, i: int ::
      u <= x < size(g) && 0 <= i < |g.adj[x]| ==>
      colors[x] != colors[g.adj[x][i]])
    ==> RowsCheck(g, colors, u)
  decreases size(g) - u
{
  if u < size(g) {
    RowCheckSpec(g, colors, u, 0);
    RowsCheckSpec(g, colors, u + 1);

    if RowsCheck(g, colors, u) {
      assert RowCheck(g, colors, u, 0);
      assert RowsCheck(g, colors, u + 1);

      forall x: int, i: int |
        u <= x < size(g) && 0 <= i < |g.adj[x]|
        ensures colors[x] != colors[g.adj[x][i]]
      {
        if x == u {
          assert colors[u] != colors[g.adj[u][i]];
        } else {
          assert u + 1 <= x;
        }
      }
    }

    if forall x: int, i: int ::
         u <= x < size(g) && 0 <= i < |g.adj[x]| ==>
         colors[x] != colors[g.adj[x][i]]
    {
      assert forall i: int ::
        0 <= i < |g.adj[u]| ==>
        colors[u] != colors[g.adj[u][i]];
      assert RowCheck(g, colors, u, 0);

      assert forall x: int, i: int ::
        u + 1 <= x < size(g) && 0 <= i < |g.adj[x]| ==>
        colors[x] != colors[g.adj[x][i]];
      assert RowsCheck(g, colors, u + 1);
    }
  }
}

lemma RowsCheckIsValid(g: Graph, colors: seq<bool>)
  requires well_formed(g)
  requires |colors| == size(g)
  ensures RowsCheck(g, colors, 0) <==> is_valid_coloring(g, colors)
{
  RowsCheckSpec(g, colors, 0);

  if RowsCheck(g, colors, 0) {
    assert forall u: int, i: int ::
      0 <= u < size(g) && 0 <= i < |g.adj[u]| ==>
      colors[u] != colors[g.adj[u][i]];

    forall u: int, v: int | has_edge(g, u, v)
      ensures
        0 <= u < |colors|
        && 0 <= v < |colors|
        && colors[u] != colors[v]
    {
      assert exists i: int ::
        0 <= u < |g.adj|
        && 0 <= i < |g.adj[u]|
        && g.adj[u][i] == v;

      var i: int :|
        0 <= u < |g.adj|
        && 0 <= i < |g.adj[u]|
        && g.adj[u][i] == v;

      assert 0 <= g.adj[u][i] < |g.adj|;
      assert 0 <= u < |colors|;
      assert 0 <= v < |colors|;
      assert colors[u] != colors[g.adj[u][i]];
    }
  }

  if is_valid_coloring(g, colors) {
    forall u: int, i: int |
      0 <= u < size(g) && 0 <= i < |g.adj[u]|
      ensures colors[u] != colors[g.adj[u][i]]
    {
      var v := g.adj[u][i];
      assert 0 <= v < |g.adj|;

      assert has_edge(g, u, v) by {
        assert exists j: int ::
          0 <= u < |g.adj|
          && 0 <= j < |g.adj[u]|
          && g.adj[u][j] == v;
      }

      assert colors[u] != colors[v];
    }

    assert forall u: int, i: int ::
      0 <= u < size(g) && 0 <= i < |g.adj[u]| ==>
      colors[u] != colors[g.adj[u][i]];
    assert RowsCheck(g, colors, 0);
  }
}

