function OptSeq(o: Option<int>): seq<int> {
    match o
    case Some(x) => [x]
    case None => []
}

function RowCosts(row: seq<(int, int)>, du: Option<int>, v: int, i: int): seq<int>
    requires 0 <= i <= |row|
    decreases |row| - i
{
    if i == |row| then []
    else
        (if row[i].0 == v then
            match du
            case Some(d) => [d + row[i].1]
            case None => []
         else [])
        + RowCosts(row, du, v, i + 1)
}

function EdgeCosts(
    g: seq<seq<(int, int)>>,
    prev: seq<Option<int>>,
    v: int,
    u: int
): seq<int>
    requires |prev| == |g|
    requires 0 <= u <= |g|
    decreases |g| - u
{
    if u == |g| then []
    else
        RowCosts(g[u], prev[u], v, 0)
        + EdgeCosts(g, prev, v, u + 1)
}

function MinOpt(xs: seq<int>): Option<int>
    decreases |xs|
{
    if |xs| == 0 then None
    else if |xs| == 1 then Some(xs[0])
    else
        match MinOpt(xs[1..])
        case None => Some(xs[0])
        case Some(m) => Some(if xs[0] <= m then xs[0] else m)
}

lemma MinOptSpec(xs: seq<int>)
    ensures match MinOpt(xs)
        case None => |xs| == 0
        case Some(m) =>
            m in xs &&
            forall x: int :: x in xs ==> m <= x
    decreases |xs|
{
    if |xs| > 1 {
        MinOptSpec(xs[1..]);
    }
}

