    requires has_edge(view(graph), u, v, w1)
    requires has_edge(view(graph), u, v, w2)
    ensures w1 == w2
{
    var i :| 0 <= u < |graph.adj| &&
             0 <= i < |graph.adj[u]| &&
             graph.adj[u][i].0 == v &&
             graph.adj[u][i].1 == w1;
    var j :| 0 <= u < |graph.adj| &&
