lemma RowCostSound(
    row: seq<(int, int)>,
    du: Option<int>,
    v: int,
    i: int,
    c: int
)
    requires 0 <= i <= |row|
    requires c in RowCosts(row, du, v, i)
    ensures exists j: int, d: int ::
        i <= j < |row| &&
        row[j].0 == v &&
        du == Some(d) &&
        c == d + row[j].1
    decreases |row| - i
{
    assert i < |row|;
    var head :=
        if row[i].0 == v then
            match du
            case Some(d) => [d + row[i].1]
            case None => []
        else [];

    if c in head {
        match du
        case Some(d) => {
            assert c == d + row[i].1;
        }
        case None => {
            assert |head| == 0;
            assert false;
        }
    } else {
        assert c in RowCosts(row, du, v, i + 1);
        RowCostSound(row, du, v, i + 1, c);
    }
}

