            graph.adj[u][j].0 == v &&
            prev[u] == Some(du) &&
            c == du + graph.adj[u][j].1;

        assert VertexOptimal(
            view(graph), start, u, rounds, prev[u]);
        var p :| Candidate(view(graph), start, u, rounds, p)
                  && path_weight(view(graph), p) == du;

        assert has_edge(
            view(graph), u, v, graph.adj[u][j].1);
        ExtendPath(graph, p, v, graph.adj[u][j].1);
        assert Candidate(
            view(graph), start, v, rounds + 1, p + [v]);
    }
}

