lemma PathVerticesBound(graph: WeightedGraph, p: seq<int>)
    requires well_formed(graph)
    requires is_path(view(graph), p)
    requires |p| >= 2
    ensures forall i: int :: 0 <= i < |p| ==>
        0 <= p[i] < size(graph)
{
    forall i: int | 0 <= i < |p|
        ensures 0 <= p[i] < size(graph)
    {
        if i < |p| - 1 {
            assert connected(view(graph), p[i], p[i + 1]);
            var w :| has_edge(view(graph), p[i], p[i + 1], w);
        } else {
            assert connected(
                view(graph), p[i - 1], p[i]);
            var w :| has_edge(view(graph), p[i - 1], p[i], w);
        }
    }
}

lemma Pigeonhole(p: seq<int>, n: nat)
    requires |p| > n
    requires forall i: int :: 0 <= i < |p| ==> 0 <= p[i] < n
    ensures exists i: int, j: int ::
        0 <= i < j < |p| && p[i] == p[j]
    decreases n
{
    if n == 0 {
        assert |p| > 0;
        assert 0 <= p[0] < 0;
        assert false;
    } else {
        var last := |p| - 1;
        var x := p[last];
        var q := p[..last];

        if exists i: int :: 0 <= i < |q| && q[i] == x {
            var i :| 0 <= i < |q| && q[i] == x;
            assert p[i] == p[last];
        } else {
            var r := seq(|q|, i =>
                if q[i] < x then q[i] else q[i] - 1);

            assert |r| > n - 1;
            assert forall i: int :: 0 <= i < |r| ==>
                0 <= r[i] < n - 1 by {
                forall i: int | 0 <= i < |r|
                    ensures 0 <= r[i] < n - 1
                {
                    assert q[i] != x;
                    if q[i] < x {
                        assert q[i] <= x - 1;
                    } else {
                        assert q[i] >= x + 1;
                    }
                }
            }

            Pigeonhole(r, n - 1);
            var i, j :| 0 <= i < j < |r| && r[i] == r[j];

            if q[i] < x {
                if q[j] >= x {
                    assert q[j] != x;
                    assert q[j] >= x + 1;
                    assert r[i] <= x - 1;
                    assert r[j] >= x;
                    assert false;
                }
            } else {
                assert q[i] != x;
                assert q[i] >= x + 1;
                if q[j] < x {
                    assert r[j] <= x - 1;
                    assert r[i] >= x;
                    assert false;
                }
            }
            assert q[i] == q[j];
            assert p[i] == p[j];
        }
    }
}

lemma ConcatPaths(
    g: seq<seq<(int, int)>>,
    a: seq<int>,
    b: seq<int>
)
    requires is_path(g, a)
    requires is_path(g, b)
    requires a[|a| - 1] == b[0]
    ensures is_path(g, a + b[1..])
    ensures path_weight(g, a + b[1..])
        == path_weight(g, a) + path_weight(g, b)
    decreases |b|
{
    if |b| == 1 {
        assert b[1..] == [];
        assert path_weight(g, b) == 0;
    } else {
        var b0 := b[..|b| - 1];
        PathPrefix(g, b, |b| - 1);
        ConcatPaths(g, a, b0);

        var c := a + b0[1..];
        assert c[|c| - 1] == b[|b| - 2];
        assert connected(g, b[|b| - 2], b[|b| - 1]);
        assert is_path(g, c + [b[|b| - 1]]);
        assert a + b[1..] == c + [b[|b| - 1]];
        assert (c + [b[|b| - 1]])[..|c|] == c;
    }
}

lemma SplicePath(
    g: seq<seq<(int, int)>>,
    p: seq<int>,
    i: int,
    j: int
) returns (cycle: seq<int>, rest: seq<int>)
    requires is_path(g, p)
    requires 0 <= i < j < |p|
    requires p[i] == p[j]
    ensures cycle == p[i..j + 1]
    ensures rest == p[..i + 1] + p[j + 1..]
    ensures is_path(g, cycle)
    ensures cycle[0] == cycle[|cycle| - 1]
    ensures is_path(g, rest)
    ensures rest[0] == p[0]
    ensures rest[|rest| - 1] == p[|p| - 1]
    ensures path_weight(g, p)
        == path_weight(g, rest) + path_weight(g, cycle)
    ensures |rest| < |p|
{
    cycle := p[i..j + 1];
    var left := p[..i + 1];
    var right := p[j..];
    rest := left + right[1..];

    PathSlice(g, p, i, j + 1);
    PathPrefix(g, p, i + 1);
    PathSlice(g, p, j, |p|);

    ConcatPaths(g, left, cycle);
    var throughCycle := left + cycle[1..];
    assert throughCycle == p[..j + 1];

    ConcatPaths(g, throughCycle, right);
    assert throughCycle + right[1..] == p;

    ConcatPaths(g, left, right);
    assert path_weight(g, throughCycle)
        == path_weight(g, left) + path_weight(g, cycle);
    assert path_weight(g, p)
        == path_weight(g, throughCycle) + path_weight(g, right);
    assert path_weight(g, rest)
        == path_weight(g, left) + path_weight(g, right);
}

lemma SimplifyPath(
    graph: WeightedGraph,
    p: seq<int>
) returns (q: seq<int>)
    requires well_formed(graph)
    requires !has_negative_cycle(view(graph))
    requires is_path(view(graph), p)
    requires 0 <= p[0] < size(graph)
    requires 0 <= p[|p| - 1] < size(graph)
    ensures is_path(view(graph), q)
    ensures q[0] == p[0]
    ensures q[|q| - 1] == p[|p| - 1]
    ensures |q| <= size(graph)
    ensures path_weight(view(graph), q)
        <= path_weight(view(graph), p)
    decreases |p|
{
    if |p| <= size(graph) {
        q := p;
    } else {
        PathVerticesBound(graph, p);
        Pigeonhole(p, size(graph));
        var i, j :| 0 <= i < j < |p| && p[i] == p[j];

        var cycle, rest := SplicePath(view(graph), p, i, j);
        assert |cycle| > 1;
        assert cycle[0] == cycle[|cycle| - 1];
        assert path_weight(view(graph), cycle) >= 0;
        q := SimplifyPath(graph, rest);
    }
}

lemma ShortNegativeCycle(
    graph: WeightedGraph,
    p: seq<int>
) returns (q: seq<int>)
    requires well_formed(graph)
    requires is_path(view(graph), p)
    requires |p| > 1
    requires p[0] == p[|p| - 1]
    requires path_weight(view(graph), p) < 0
    ensures is_path(view(graph), q)
    ensures |q| > 1
    ensures q[0] == q[|q| - 1]
    ensures path_weight(view(graph), q) < 0
    ensures |q| <= size(graph) + 1
    decreases |p|
{
    if |p| <= size(graph) + 1 {
        q := p;
    } else {
        PathVerticesBound(graph, p);
        var prefix := p[..|p| - 1];
        assert |prefix| > size(graph);
        assert forall i: int :: 0 <= i < |prefix| ==>
            0 <= prefix[i] < size(graph);
        Pigeonhole(prefix, size(graph));

        var i, j :|
            0 <= i < j < |prefix| && prefix[i] == prefix[j];
        var cycle, rest := SplicePath(view(graph), p, i, j);

        assert |cycle| > 1;
        assert cycle[0] == cycle[|cycle| - 1];
        assert |rest| > 1;
        assert rest[0] == rest[|rest| - 1];

        if path_weight(view(graph), cycle) < 0 {
            q := ShortNegativeCycle(graph, cycle);
        } else {
            assert path_weight(view(graph), rest) < 0;
            q := ShortNegativeCycle(graph, rest);
        }
    }
}

function NegativeSource(
    g: seq<seq<(int, int)>>,
    first: int
): Option<int>
    requires 0 <= first <= |g|
    decreases |g| - first
{
    if first == |g| then None
    else
        match Run(g, first, |g|)[first]
        case Some(d) =>
            if d < 0 then Some(first)
            else NegativeSource(g, first + 1)
        case None =>
            NegativeSource(g, first + 1)
}

lemma NegativeSourceSpec(
    graph: WeightedGraph,
    first: int
)
    requires well_formed(graph)
    requires 0 <= first <= size(graph)
    ensures match NegativeSource(view(graph), first)
        case Some(s) =>
            first <= s < size(graph) &&
            (match Run(view(graph), s, size(graph))[s]
             case Some(d) => d < 0
             case None => false)
        case None =>
            forall s: int :: first <= s < size(graph) ==>
                (match Run(view(graph), s, size(graph))[s]
                 case Some(d) => d >= 0
                 case None => true)
    decreases size(graph) - first
{
    if first < size(graph) {
        match Run(view(graph), first, size(graph))[first]
        case Some(d) => {
            if d >= 0 {
                NegativeSourceSpec(graph, first + 1);
            }
        }
        case None => {
            NegativeSourceSpec(graph, first + 1);
        }
    }
}

lemma NoNegativeCycle(
    graph: WeightedGraph
)
    requires well_formed(graph)
    requires size(graph) > 0
    requires NegativeSource(view(graph), 0) == None
    ensures !has_negative_cycle(view(graph))
{
    NegativeSourceSpec(graph, 0);

    if has_negative_cycle(view(graph)) {
        var p :| is_path(view(graph), p) &&
                  |p| > 1 &&
                  p[0] == p[|p| - 1] &&
                  path_weight(view(graph), p) < 0;

        var q := ShortNegativeCycle(graph, p);
        PathVerticesBound(graph, q);
        var s := q[0];
        assert 0 <= s < size(graph);
        assert Candidate(
            view(graph), s, s, size(graph), q);

        RunOptimal(graph, s, size(graph));
        assert VertexOptimal(
            view(graph), s, s, size(graph),
            Run(view(graph), s, size(graph))[s]);

        match Run(view(graph), s, size(graph))[s]
        case Some(d) => {
            assert d <= path_weight(view(graph), q);
            assert d < 0;
            assert false;
        }
        case None => {
            assert false;
        }
    }
}

lemma FinalDistances(
    graph: WeightedGraph,
    start: int
)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    requires !has_negative_cycle(view(graph))
    ensures |Run(view(graph), start, size(graph) - 1)|
        == size(graph)
    ensures forall v: int :: 0 <= v < size(graph) ==>
        (match Run(view(graph), start, size(graph) - 1)[v]
         case Some(d) =>
            is_shortest_dist(view(graph), start, v, d)
         case None =>
            forall p: seq<int> {:trigger is_path(view(graph), p)} ::
                (is_path(view(graph), p) &&
                 p[0] == start &&
                 p[|p| - 1] == v) ==> false)
