                {:trigger is_path(view(graph), p)} ::
                (is_path(view(graph), p) &&
                 p[0] == start &&
                 p[|p| - 1] == v) ==> false by {
                forall p: seq<int>
                    {:trigger is_path(view(graph), p)}
                    | is_path(view(graph), p) &&
                      p[0] == start &&
                      p[|p| - 1] == v
                    ensures false
                {
                    var q := SimplifyPath(graph, p);
                    assert Candidate(
