      colors[u] != colors[g.adj[u][i]];
    assert RowsCheck(g, colors, 0);
  }
}

ghost predicate Extends(colors: seq<bool>, prefix: seq<bool>)
{
  |prefix| <= |colors| && colors[..|prefix|] == prefix
}

lemma ExtendOne(
    colors: seq<bool>,
    prefix: seq<bool>,
    color: bool)
  requires Extends(colors, prefix)
  requires |prefix| < |colors|
  requires colors[|prefix|] == color
  ensures Extends(colors, prefix + [color])
{
  assert |prefix + [color]| == |prefix| + 1;

  assert colors[..|prefix| + 1] == prefix + [color] by {
    forall i: int | 0 <= i < |prefix| + 1
      ensures colors[i] == (prefix + [color])[i]
    {
      if i < |prefix| {
        assert colors[i] == colors[..|prefix|][i];
        assert colors[i] == prefix[i];
        assert (prefix + [color])[i] == prefix[i];
      } else {
        assert i == |prefix|;
        assert (prefix + [color])[i] == color;
      }
    }
  }
}

lemma ExtendEither(colors: seq<bool>, prefix: seq<bool>)
  requires Extends(colors, prefix)
  requires |prefix| < |colors|
  ensures
    Extends(colors, prefix + [false])
    || Extends(colors, prefix + [true])
{
  if colors[|prefix|] {
    ExtendOne(colors, prefix, true);
  } else {
    ExtendOne(colors, prefix, false);
  }
}

lemma DropLastExtension(
    colors: seq<bool>,
    prefix: seq<bool>,
    color: bool)
  requires Extends(colors, prefix + [color])
  ensures Extends(colors, prefix)
{
  assert |prefix| <= |colors|;

  assert colors[..|prefix|] == prefix by {
    forall i: int | 0 <= i < |prefix|
      ensures colors[i] == prefix[i]
    {
      assert i < |prefix + [color]|;
      assert colors[i] == colors[..|prefix + [color]|][i];
      assert colors[i] == (prefix + [color])[i];
      assert (prefix + [color])[i] == prefix[i];
    }
  }
}

lemma EqualLengthExtension(colors: seq<bool>, prefix: seq<bool>)
  requires Extends(colors, prefix)
  requires |colors| == |prefix|
  ensures colors == prefix
{
  assert colors[..|colors|] == colors;
  assert colors[..|prefix|] == prefix;
}

method SearchColorings(
    graph: Graph,
    prefix: seq<bool>)
    returns (res: Option<seq<bool>>)
  requires well_formed(graph)
  requires |prefix| <= |graph.adj|
  ensures match res
    case Some(colors) =>
      is_valid_coloring(graph, colors)
      && Extends(colors, prefix)
    case None =>
      forall colors: seq<bool> ::
        is_valid_coloring(graph, colors) ==>
        !Extends(colors, prefix)
  decreases |graph.adj| - |prefix|
{
  if |prefix| == |graph.adj| {
    if RowsCheck(graph, prefix, 0) {
      RowsCheckIsValid(graph, prefix);
      assert is_valid_coloring(graph, prefix);
      assert Extends(prefix, prefix);
      res := Some(prefix);
    } else {
      RowsCheckIsValid(graph, prefix);
      assert !is_valid_coloring(graph, prefix);

      forall colors: seq<bool> |
        is_valid_coloring(graph, colors) && Extends(colors, prefix)
        ensures false
      {
        assert |colors| == |graph.adj|;
        EqualLengthExtension(colors, prefix);
        assert colors == prefix;
      }

      assert forall colors: seq<bool> ::
        is_valid_coloring(graph, colors) ==>
        !Extends(colors, prefix);
      res := None;
    }
  } else {
    var first := SearchColorings(graph, prefix + [false]);

    match first
    case Some(colors) =>
      DropLastExtension(colors, prefix, false);
      res := Some(colors);

    case None =>
      var second := SearchColorings(graph, prefix + [true]);

      match second
      case Some(colors) =>
        DropLastExtension(colors, prefix, true);
        res := Some(colors);

      case None =>
        forall colors: seq<bool> |
          is_valid_coloring(graph, colors) && Extends(colors, prefix)
          ensures false
        {
          assert |colors| == |graph.adj|;
          assert |prefix| < |colors|;
          ExtendEither(colors, prefix);

          if Extends(colors, prefix + [false]) {
            assert is_valid_coloring(graph, colors) ==>
              !Extends(colors, prefix + [false]);
            assert !Extends(colors, prefix + [false]);
          } else {
            assert Extends(colors, prefix + [true]);
            assert is_valid_coloring(graph, colors) ==>
              !Extends(colors, prefix + [true]);
            assert !Extends(colors, prefix + [true]);
          }
        }

        assert forall colors: seq<bool> ::
          is_valid_coloring(graph, colors) ==>
          !Extends(colors, prefix);
        res := None;
  }
}

method check_bipartite(graph: Graph) returns (res: Option<seq<bool>>)
  requires well_formed(graph)
  ensures match res {
    case Some(colors) => is_valid_coloring(graph, colors)
    case None => !is_bipartite(graph)
  }
{
  var found := SearchColorings(graph, []);

  match found
  case Some(colors) =>
    res := Some(colors);

  case None =>
    assert !is_bipartite(graph) by {
      if is_bipartite(graph) {
        var colors: seq<bool> :| is_valid_coloring(graph, colors);
        assert Extends(colors, []);
        assert is_valid_coloring(graph, colors) ==> !Extends(colors, []);
        assert false;
      }
    }
    res := None;
}
