lemma TotalWeightConcat(a: seq<int>, b: seq<int>)
    ensures total_weight(a + b) == total_weight(a) + total_weight(b)
    decreases |a|
{
    if |a| == 0 {
        assert a == [];
    } else {
        assert (a + b)[0] == a[0];
        assert (a + b)[1..] == a[1..] + b;
        TotalWeightConcat(a[1..], b);
        calc {
            total_weight(a + b);
            == char_weight(a[0]) + total_weight(a[1..] + b);
            == char_weight(a[0]) + total_weight(a[1..]) + total_weight(b);
            == total_weight(a) + total_weight(b);
        }
    }
}

lemma PrefixWeightStep(s: seq<int>, i: int)
    requires 0 <= i < |s|
    ensures total_weight(s[0..i + 1])
         == total_weight(s[0..i]) + char_weight(s[i])
{
    assert s[0..i + 1] == s[0..i] + [s[i]];
    TotalWeightConcat(s[0..i], [s[i]]);
    assert total_weight([s[i]]) == char_weight(s[i]);
}

lemma ExtendNonnegativePrefixes(s: seq<int>, i: int)
    requires 0 <= i < |s|
    requires forall j :: 0 <= j <= i ==>
        total_weight(s[0..j]) >= 0
    requires total_weight(s[0..i + 1]) >= 0
    ensures forall j :: 0 <= j <= i + 1 ==>
        total_weight(s[0..j]) >= 0
{
    forall j | 0 <= j <= i + 1
        ensures total_weight(s[0..j]) >= 0
    {
        if j > i {
            assert j == i + 1;
        }
    }
}

lemma NegativePrefixIsInvalid(s: seq<int>, i: int)
    requires 0 <= i <= |s|
    requires total_weight(s[0..i]) < 0
    ensures !valid_prefix_weights(s)
{
    if valid_prefix_weights(s) {
        assert total_weight(s[0..i]) >= 0;
    }
}

method bracket_match(s: seq<int>) returns (res: bool)
    requires
        // CONSTRAINT: Hard limit of 1,000,000 ensures no integer overflow
        // when counting or indexing.
        |s| <= 1000000
    ensures
        res == is_matched(s)
{
    var i: int := 0;
    var balance: int := 0;

    while i < |s|
        invariant 0 <= i <= |s|
        invariant balance == total_weight(s[0..i])
        invariant forall j :: 0 <= j <= i ==>
            total_weight(s[0..j]) >= 0
        decreases |s| - i
    {
        PrefixWeightStep(s, i);

        var nextBalance := balance + char_weight(s[i]);
        assert nextBalance == total_weight(s[0..i + 1]);

        if nextBalance < 0 {
            NegativePrefixIsInvalid(s, i + 1);
            assert !valid_prefix_weights(s);
            assert !is_matched(s);
            res := false;
            return;
        }

        ExtendNonnegativePrefixes(s, i);
        i := i + 1;
        balance := nextBalance;
    }

    assert i == |s|;
    assert s[0..|s|] == s;
    assert balance == total_weight(s);
    assert valid_prefix_weights(s);

    res := balance == 0;

    if res {
        assert total_weight(s) == 0;
        assert is_matched(s);
    } else {
        assert total_weight(s) != 0;
        assert !is_matched(s);
    }
}

