method removeMin(t: Tree) returns (m: int, res: Tree)
    requires t != Empty
    requires is_bst(t)
    ensures is_bst(res)
    ensures m in view(t)
    ensures view(res) == view(t) - {m}
    ensures forall x :: x in view(res) ==> x > m
    decreases t
{
    match t
    case Node(val, l, r) =>
        if l == Empty {
            m := val;
            res := r;
        } else {
            var nl;
            m, nl := removeMin(l);
            assert m < val;
            res := Node(val, nl, r);
            assert forall x :: x in view(r) ==> x > m;
            assert forall x :: x in view(nl) ==> x < val;
        }
}

method delete(tree: Tree, v: int) returns (res: Tree)
    requires v >= 0
    requires is_bst(tree)
    ensures is_bst(res)
    ensures view(res) == view(tree) - {v}
    decreases tree
{
    match tree
    case Empty =>
        res := Empty;
    case Node(val, l, r) =>
        if v < val {
            var nl := delete(l, v);
            assert v !in view(r);
            res := Node(val, nl, r);
        } else if v > val {
            var nr := delete(r, v);
            assert v !in view(l);
            res := Node(val, l, nr);
        } else {
            assert val !in view(l);
            assert val !in view(r);
            if l == Empty {
                res := r;
            } else if r == Empty {
                res := l;
            } else {
                var m, nr := removeMin(r);
                assert m > val;
                assert forall x :: x in view(l) ==> x < m;
                res := Node(m, l, nr);
                assert view(res) == view(l) + view(r);
            }
        }
}

