    ensures total_weight(s + [x]) == total_weight(s) + char_weight(x)
    decreases |s|
{
    if |s| == 0 {
        assert s + [x] == [x];
        assert [x][1..] == [];
    } else {
        assert (s + [x])[0] == s[0];
        assert (s + [x])[1..] == s[1..] + [x];
        total_weight_append(s[1..], x);
    }
}

method bracket_match(s: seq<int>) returns (res: bool)
    requires
        // CONSTRAINT: Hard limit of 1,000,000 ensures no integer overflow
        // when counting or indexing.
        |s| <= 1000000
    ensures
        res == is_matched(s)
{
    var idx := 0;
    var balance := 0;
    assert s[0..0] == [];

    while idx < |s|
        invariant 0 <= idx <= |s|
        invariant balance == total_weight(s[0..idx])
        invariant forall i :: 0 <= i <= idx ==> total_weight(s[0..i]) >= 0
        decreases |s| - idx
    {
        assert s[0..idx + 1] == s[0..idx] + [s[idx]];
        total_weight_append(s[0..idx], s[idx]);

        balance := balance + char_weight(s[idx]);
        idx := idx + 1;

        if balance < 0 {
            assert total_weight(s[0..idx]) < 0;
            assert !valid_prefix_weights(s);
            return false;
        }
    }

    assert s[0..|s|] == s;
    assert valid_prefix_weights(s);
    return balance == 0;
}
