lemma EdgeWeight(graph: WeightedGraph, u: int, i: int)
  requires well_formed(graph)
  requires 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]|
  ensures get_edge_weight(graph.adj, u, graph.adj[u][i].0) == graph.adj[u][i].1
{
  var g: seq<seq<(int, int)>> := graph.adj;
  var v: int := g[u][i].0;
  var w: int := g[u][i].1;
  assert has_edge(g, u, v, w);
  forall w' | has_edge(g, u, v, w') ensures w' == w {
    var i': int :| 0 <= u < |g| && 0 <= i' < |g[u]| && g[u][i'].0 == v && g[u][i'].1 == w';
    if i' != i {
      assert g[u][i'].0 != g[u][i].0;
    }
  }
  assert exists w0 :: has_edge(g, u, v, w0);
}

lemma PrefixPath(g: seq<seq<(int, int)>>, p: seq<int>, k: int)
  requires is_path(g, p)
  requires 1 <= k <= |p|
  ensures is_path(g, p[..k])
{
  var s := p[..k];
  forall j | 0 <= j < |s| - 1 ensures connected(g, s[j], s[j + 1]) {
    assert s[j] == p[j] && s[j + 1] == p[j + 1];
    assert connected(g, p[j], p[j + 1]);
  }
}

lemma SubPath(g: seq<seq<(int, int)>>, p: seq<int>, a: int, b: int)
  requires is_path(g, p)
  requires 0 <= a < b <= |p|
  ensures is_path(g, p[a..b])
{
  var s := p[a..b];
  forall k | 0 <= k < |s| - 1 ensures connected(g, s[k], s[k + 1]) {
    var j := a + k;
    assert s[k] == p[j] && s[k + 1] == p[j + 1];
    assert connected(g, p[j], p[j + 1]);
  }
}

lemma AppendEdge(graph: WeightedGraph, p: seq<int>, u: int, i: int)
  requires well_formed(graph)
  requires is_path(graph.adj, p)
  requires p[|p| - 1] == u
  requires 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]|
  ensures is_path(graph.adj, p + [graph.adj[u][i].0])
  ensures path_weight(graph.adj, p + [graph.adj[u][i].0]) == path_weight(graph.adj, p) + graph.adj[u][i].1
{
  var g: seq<seq<(int, int)>> := graph.adj;
  var v: int := g[u][i].0;
  var w: int := g[u][i].1;
  var q := p + [v];
  assert has_edge(g, u, v, w);
  assert connected(g, u, v);
  forall k | 0 <= k < |q| - 1 ensures connected(g, q[k], q[k + 1]) {
    if k < |p| - 1 {
      assert q[k] == p[k] && q[k + 1] == p[k + 1];
      assert connected(g, p[k], p[k + 1]);
    } else {
      assert q[k] == u && q[k + 1] == v;
    }
  }
  assert is_path(g, q);
  assert q[..|q| - 1] == p;
  assert q[|q| - 2] == u && q[|q| - 1] == v;
  EdgeWeight(graph, u, i);
  assert path_weight(g, q) == path_weight(g, q[..|q| - 1]) + get_edge_weight(g, q[|q| - 2], q[|q| - 1]);
}

lemma PathInRange(graph: WeightedGraph, p: seq<int>)
  requires well_formed(graph)
  requires is_path(graph.adj, p)
  requires 0 <= p[0] < |graph.adj|
  ensures forall k :: 0 <= k < |p| ==> 0 <= p[k] < |graph.adj|
{
  var g: seq<seq<(int, int)>> := graph.adj;
  forall k | 0 <= k < |p| ensures 0 <= p[k] < |g| {
    if k > 0 {
      var j := k - 1;
      assert connected(g, p[j], p[j + 1]);
      var w: int :| has_edge(g, p[j], p[j + 1], w);
      var e: int :| 0 <= p[j] < |g| && 0 <= e < |g[p[j]]| && g[p[j]][e].0 == p[j + 1] && g[p[j]][e].1 == w;
      assert p[j + 1] == p[k];
    }
  }
}

lemma Split(g: seq<seq<(int, int)>>, p: seq<int>, i: int)
  requires 0 <= i < |p|
  ensures path_weight(g, p) == path_weight(g, p[..i + 1]) + path_weight(g, p[i..])
  decreases |p|
{
  if i == |p| - 1 {
    assert p[..i + 1] == p;
    assert |p[i..]| == 1;
  } else {
    var p' := p[..|p| - 1];
    Split(g, p', i);
    assert p'[..i + 1] == p[..i + 1];
    var s := p[i..];
    assert |s| >= 2;
    assert s[..|s| - 1] == p'[i..];
    assert s[|s| - 2] == p[|p| - 2] && s[|s| - 1] == p[|p| - 1];
    assert path_weight(g, s) == path_weight(g, s[..|s| - 1]) + get_edge_weight(g, s[|s| - 2], s[|s| - 1]);
    assert path_weight(g, p) == path_weight(g, p') + get_edge_weight(g, p[|p| - 2], p[|p| - 1]);
  }
}

lemma CycleSplit(g: seq<seq<(int, int)>>, q: seq<int>, a: int, b: int)
  requires is_path(g, q)
  requires 0 <= a < b < |q| && q[a] == q[b]
  ensures is_path(g, q[a..b + 1])
  ensures is_path(g, q[..a] + q[b..])
  ensures |q[..a] + q[b..]| == |q| - (b - a)
  ensures (q[..a] + q[b..])[0] == q[0]
  ensures (q[..a] + q[b..])[|q[..a] + q[b..]| - 1] == q[|q| - 1]
  ensures path_weight(g, q) == path_weight(g, q[..a] + q[b..]) + path_weight(g, q[a..b + 1])
{
  var q' := q[..a] + q[b..];
  SubPath(g, q, a, b + 1);
  forall k | 0 <= k < |q'| - 1 ensures connected(g, q'[k], q'[k + 1]) {
    if k + 1 < a {
      assert q'[k] == q[k] && q'[k + 1] == q[k + 1];
      assert connected(g, q[k], q[k + 1]);
    } else if k + 1 == a {
      assert q'[k] == q[k];
      assert q'[k + 1] == q[b];
      assert q[k + 1] == q[a];
      assert connected(g, q[k], q[k + 1]);
    } else {
      var j := k - a + b;
      assert q'[k] == q[j] && q'[k + 1] == q[j + 1];
      assert connected(g, q[j], q[j + 1]);
    }
  }
  assert is_path(g, q');
  if a == 0 {
    assert q'[0] == q[b];
  } else {
    assert q'[0] == q[0];
  }
  assert q'[|q'| - 1] == q[|q| - 1];
  Split(g, q, a);
  Split(g, q[a..], b - a);
  assert q[a..][..b - a + 1] == q[a..b + 1];
  assert q[a..][b - a..] == q[b..];
  Split(g, q', a);
  assert q'[..a + 1] == q[..a + 1];
  assert q'[a..] == q[b..];
}

lemma RangeCard(n: int)
  requires n >= 0
  ensures |set k: int | 0 <= k < n| == n
  decreases n
{
  if n > 0 {
    RangeCard(n - 1);
    var A := set k: int | 0 <= k < n - 1;
    var B := set k: int | 0 <= k < n;
    assert B == A + {n - 1};
    assert n - 1 !in A;
  }
}

lemma NoDupBound(q: seq<int>, S: set<int>)
  requires forall k :: 0 <= k < |q| ==> q[k] in S
  requires forall i, j :: 0 <= i < j < |q| ==> q[i] != q[j]
  ensures |q| <= |S|
  decreases |q|
{
  if |q| > 0 {
    var S' := S - {q[0]};
    var r := q[1..];
    forall k | 0 <= k < |r| ensures r[k] in S' {
      assert r[k] == q[k + 1];
      assert q[0] != q[k + 1];
    }
    forall i, j | 0 <= i < j < |r| ensures r[i] != r[j] {
      assert r[i] == q[i + 1] && r[j] == q[j + 1];
    }
    NoDupBound(r, S');
    assert |S'| == |S| - 1;
  }
}

lemma Pigeonhole(q: seq<int>, n: int)
  requires n >= 0
  requires forall k :: 0 <= k < |q| ==> 0 <= q[k] < n
  requires |q| > n
  ensures exists a, b :: 0 <= a < b < |q| && q[a] == q[b]
{
  if forall a, b :: 0 <= a < b < |q| ==> q[a] != q[b] {
    var S := set k: int | 0 <= k < n;
    RangeCard(n);
    NoDupBound(q, S);
    assert false;
  }
}

lemma InitInv(graph: WeightedGraph, start: int, D: seq<Option<int>>)
  requires 0 <= start < |graph.adj|
  requires |D| == |graph.adj|
  requires forall k :: 0 <= k < |D| ==> D[k] == (if k == start then Some(0) else None)
  ensures Witnessed(graph.adj, start, D, 1)
  ensures Bounded(graph.adj, start, D, 1)
{
  var g: seq<seq<(int, int)>> := graph.adj;
  var p0 := [start];
  assert is_path(g, p0);
  assert path_weight(g, p0) == 0;
  assert p0[0] == start && p0[|p0| - 1] == start;
  assert HasWitness(g, start, start, 1, 0);
  forall v | 0 <= v < |D| && D[v].Some? ensures HasWitness(g, start, v, 1, D[v].value) {
    assert v == start;
  }
  forall p | is_path(g, p) && p[0] == start && |p| <= 1 && 0 <= p[|p| - 1] < |D|
    ensures D[p[|p| - 1]].Some? && D[p[|p| - 1]].value <= path_weight(g, p)
  {
    assert |p| == 1;
    assert p[|p| - 1] == start;
  }
}

lemma WitnessedMono(g: seq<seq<(int, int)>>, start: int, D: seq<Option<int>>, L: int)
  requires Witnessed(g, start, D, L)
  ensures Witnessed(g, start, D, L + 1)
{
  forall v | 0 <= v < |D| && D[v].Some? ensures HasWitness(g, start, v, L + 1, D[v].value) {
    assert HasWitness(g, start, v, L, D[v].value);
    var p: seq<int> :| is_path(g, p) && p[0] == start && p[|p| - 1] == v && |p| <= L && path_weight(g, p) == D[v].value;
    assert is_path(g, p);
  }
}

lemma WitnessedUpdate(g: seq<seq<(int, int)>>, start: int, D: seq<Option<int>>, L: int, v: int, c: int)
  requires Witnessed(g, start, D, L)
  requires 0 <= v < |D|
  requires HasWitness(g, start, v, L, c)
  ensures Witnessed(g, start, D[v := Some(c)], L)
{
  var D' := D[v := Some(c)];
  forall x | 0 <= x < |D'| && D'[x].Some? ensures HasWitness(g, start, x, L, D'[x].value) {
    if x != v {
      assert D'[x] == D[x];
    }
  }
}

lemma ExtendWitness(graph: WeightedGraph, start: int, D: seq<Option<int>>, L: int, u: int, i: int)
  requires well_formed(graph)
  requires |D| == |graph.adj|
  requires 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]|
  requires D[u].Some?
  requires Witnessed(graph.adj, start, D, L)
  ensures HasWitness(graph.adj, start, graph.adj[u][i].0, L + 1, D[u].value + graph.adj[u][i].1)
{
  var g: seq<seq<(int, int)>> := graph.adj;
  assert HasWitness(g, start, u, L, D[u].value);
  var p: seq<int> :| is_path(g, p) && p[0] == start && p[|p| - 1] == u && |p| <= L && path_weight(g, p) == D[u].value;
  AppendEdge(graph, p, u, i);
  var q := p + [g[u][i].0];
  assert q[0] == start && q[|q| - 1] == g[u][i].0 && |q| <= L + 1;
  assert is_path(g, q);
}

lemma RelaxBounded(graph: WeightedGraph, start: int, D: seq<Option<int>>, newD: seq<Option<int>>, L: int)
  requires well_formed(graph)
  requires 0 <= start < |graph.adj|
  requires |D| == |graph.adj| && |newD| == |graph.adj|
  requires L >= 1
  requires Bounded(graph.adj, start, D, L)
  requires forall v :: 0 <= v < |D| && D[v].Some? ==> newD[v].Some? && newD[v].value <= D[v].value
  requires forall u, i :: 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]| && D[u].Some? ==>
    0 <= graph.adj[u][i].0 < |newD| && newD[graph.adj[u][i].0].Some? && newD[graph.adj[u][i].0].value <= D[u].value + graph.adj[u][i].1
  ensures Bounded(graph.adj, start, newD, L + 1)
{
  var g: seq<seq<(int, int)>> := graph.adj;
  forall p | is_path(g, p) && p[0] == start && |p| <= L + 1 && 0 <= p[|p| - 1] < |newD|
    ensures newD[p[|p| - 1]].Some? && newD[p[|p| - 1]].value <= path_weight(g, p)
  {
    if |p| <= L {
      assert D[p[|p| - 1]].Some? && D[p[|p| - 1]].value <= path_weight(g, p);
    } else {
      var p' := p[..|p| - 1];
      PrefixPath(g, p, |p| - 1);
      var j := |p| - 2;
      var x := p[j];
      var y := p[j + 1];
      assert y == p[|p| - 1];
      assert p'[|p'| - 1] == x;
      assert p'[0] == start;
      assert connected(g, x, y);
      var w: int :| has_edge(g, x, y, w);
      var e: int :| 0 <= x < |g| && 0 <= e < |g[x]| && g[x][e].0 == y && g[x][e].1 == w;
      assert D[x].Some? && D[x].value <= path_weight(g, p');
      EdgeWeight(graph, x, e);
      assert path_weight(g, p) == path_weight(g, p') + get_edge_weight(g, p[|p| - 2], p[|p| - 1]);
    }
  }
}

lemma NegCycle(graph: WeightedGraph, start: int, D: seq<Option<int>>, u: int, i: int)
  requires well_formed(graph)
  requires 0 <= start < |graph.adj|
  requires |D| == |graph.adj|
  requires Witnessed(graph.adj, start, D, |graph.adj|)
  requires Bounded(graph.adj, start, D, |graph.adj|)
  requires 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]|
  requires D[u].Some?
  requires D[graph.adj[u][i].0].None? || D[u].value + graph.adj[u][i].1 < D[graph.adj[u][i].0].value
  ensures has_negative_cycle(graph.adj)
{
  var g: seq<seq<(int, int)>> := graph.adj;
  var n := |g|;
  var v: int := g[u][i].0;
  var w: int := g[u][i].1;
  assert HasWitness(g, start, u, n, D[u].value);
  var pu: seq<int> :| is_path(g, pu) && pu[0] == start && pu[|pu| - 1] == u && |pu| <= n && path_weight(g, pu) == D[u].value;
  AppendEdge(graph, pu, u, i);
  var q := pu + [v];
  assert is_path(g, q);
  assert q[0] == start && q[|q| - 1] == v;
  assert path_weight(g, q) == D[u].value + w;
  if |q| <= n {
    assert D[v].Some? && D[v].value <= path_weight(g, q);
    assert false;
  }
  PathInRange(graph, q);
  Pigeonhole(q, n);
  var a: int, b: int :| 0 <= a < b < |q| && q[a] == q[b];
  CycleSplit(g, q, a, b);
  var c := q[a..b + 1];
  var q' := q[..a] + q[b..];
  assert is_path(g, q');
  assert q'[0] == start;
  assert |q'| <= n;
  assert q'[|q'| - 1] == v;
  assert D[v].Some? && D[v].value <= path_weight(g, q');
  assert path_weight(g, q) == path_weight(g, q') + path_weight(g, c);
  assert path_weight(g, c) < 0;
  assert is_path(g, c) && |c| > 1 && c[0] == c[|c| - 1];
}

lemma FixedPointBound(graph: WeightedGraph, start: int, D: seq<Option<int>>, p: seq<int>)
  requires well_formed(graph)
  requires 0 <= start < |graph.adj|
  requires |D| == |graph.adj|
  requires D[start].Some? && D[start].value <= 0
  requires Fixed(graph.adj, D)
  requires is_path(graph.adj, p) && p[0] == start
  ensures 0 <= p[|p| - 1] < |D| && D[p[|p| - 1]].Some? && D[p[|p| - 1]].value <= path_weight(graph.adj, p)
  decreases |p|
{
  var g: seq<seq<(int, int)>> := graph.adj;
  if |p| == 1 {
    assert p[|p| - 1] == start;
  } else {
    var p' := p[..|p| - 1];
    PrefixPath(g, p, |p| - 1);
    assert p'[0] == start;
    FixedPointBound(graph, start, D, p');
    var j := |p| - 2;
    var x := p[j];
    var y := p[j + 1];
    assert y == p[|p| - 1];
    assert p'[|p'| - 1] == x;
    assert connected(g, x, y);
    var w: int :| has_edge(g, x, y, w);
    var e: int :| 0 <= x < |g| && 0 <= e < |g[x]| && g[x][e].0 == y && g[x][e].1 == w;
    EdgeWeight(graph, x, e);
    assert path_weight(g, p) == path_weight(g, p') + get_edge_weight(g, p[|p| - 2], p[|p| - 1]);
  }
}

lemma FinalCorrect(graph: WeightedGraph, start: int, D: seq<Option<int>>)
  requires well_formed(graph)
  requires 0 <= start < |graph.adj|
  requires |D| == |graph.adj|
  requires Witnessed(graph.adj, start, D, |graph.adj|)
  requires Bounded(graph.adj, start, D, |graph.adj|)
  requires Fixed(graph.adj, D)
  ensures forall v: int :: 0 <= v < size(graph) ==> (
    match D[v] {
      case Some(d) => is_shortest_dist(view(graph), start, v, d)
      case None => forall p: seq<int> {:trigger is_path(view(graph), p)} ::
                     is_path(view(graph), p) && p[0] == start && p[|p| - 1] == v ==> false
    })
{
  var g: seq<seq<(int, int)>> := graph.adj;
  var n := |g|;
  assert view(graph) == g;
  assert size(graph) == n;
  var p0 := [start];
  assert is_path(g, p0);
  assert p0[0] == start && p0[|p0| - 1] == start && |p0| <= n;
  assert D[start].Some? && D[start].value <= path_weight(g, p0);
  assert path_weight(g, p0) == 0;
  forall v | 0 <= v < size(graph)
    ensures (match D[v] {
      case Some(d) => is_shortest_dist(view(graph), start, v, d)
      case None => forall p: seq<int> {:trigger is_path(view(graph), p)} ::
                     is_path(view(graph), p) && p[0] == start && p[|p| - 1] == v ==> false
    })
  {
    match D[v] {
      case Some(d) =>
        assert HasWitness(g, start, v, n, d);
        var pw0: seq<int> :| is_path(g, pw0) && pw0[0] == start && pw0[|pw0| - 1] == v && |pw0| <= n && path_weight(g, pw0) == d;
        forall p | is_path(g, p) && p[0] == start && p[|p| - 1] == v
          ensures path_weight(g, p) >= d
        {
          FixedPointBound(graph, start, D, p);
        }
        assert is_shortest_dist(g, start, v, d);
      case None =>
        forall p | is_path(g, p) && p[0] == start && p[|p| - 1] == v
          ensures false
        {
          FixedPointBound(graph, start, D, p);
        }
    }
  }
}

method Relax(graph: WeightedGraph, start: int, D: seq<Option<int>>, L: int) returns (newD: seq<Option<int>>)
  requires well_formed(graph)
  requires 0 <= start < |graph.adj|
  requires |D| == |graph.adj|
  requires L >= 1
  requires Witnessed(graph.adj, start, D, L)
  requires Bounded(graph.adj, start, D, L)
  ensures |newD| == |graph.adj|
  ensures Witnessed(graph.adj, start, newD, L + 1)
  ensures Bounded(graph.adj, start, newD, L + 1)
{
  var n := |graph.adj|;
  WitnessedMono(graph.adj, start, D, L);
  newD := D;
  var u := 0;
  while u < n
    invariant 0 <= u <= n
    invariant |newD| == n
    invariant Witnessed(graph.adj, start, newD, L + 1)
    invariant forall v :: 0 <= v < n && D[v].Some? ==> newD[v].Some? && newD[v].value <= D[v].value
    invariant forall u', i' :: 0 <= u' < u && 0 <= i' < |graph.adj[u']| && D[u'].Some? ==>
      0 <= graph.adj[u'][i'].0 < n && newD[graph.adj[u'][i'].0].Some? && newD[graph.adj[u'][i'].0].value <= D[u'].value + graph.adj[u'][i'].1
  {
    if D[u].Some? {
      var i := 0;
      while i < |graph.adj[u]|
        invariant 0 <= i <= |graph.adj[u]|
        invariant |newD| == n
        invariant Witnessed(graph.adj, start, newD, L + 1)
        invariant forall v :: 0 <= v < n && D[v].Some? ==> newD[v].Some? && newD[v].value <= D[v].value
        invariant forall u', i' :: 0 <= u' < u && 0 <= i' < |graph.adj[u']| && D[u'].Some? ==>
          0 <= graph.adj[u'][i'].0 < n && newD[graph.adj[u'][i'].0].Some? && newD[graph.adj[u'][i'].0].value <= D[u'].value + graph.adj[u'][i'].1
        invariant forall i' :: 0 <= i' < i ==>
          0 <= graph.adj[u][i'].0 < n && newD[graph.adj[u][i'].0].Some? && newD[graph.adj[u][i'].0].value <= D[u].value + graph.adj[u][i'].1
      {
        var v: int := graph.adj[u][i].0;
        var w: int := graph.adj[u][i].1;
        var cand := D[u].value + w;
        if newD[v].None? || cand < newD[v].value {
          ExtendWitness(graph, start, D, L, u, i);
          WitnessedUpdate(graph.adj, start, newD, L + 1, v, cand);
          newD := newD[v := Some(cand)];
        }
        i := i + 1;
      }
    }
    u := u + 1;
  }
  RelaxBounded(graph, start, D, newD, L);
}

method bellman_ford(graph: WeightedGraph, start: int) returns (res: Option<seq<Option<int>>>)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    requires weights_and_size_bounded(view(graph))
    ensures match res {
        case Some(dists) => 
            |dists| == size(graph) &&
            forall v: int :: 0 <= v < size(graph) ==> (
                match dists[v] {
                    case Some(d) => is_shortest_dist(view(graph), start, v, d)
                    case None => forall p: seq<int> {:trigger is_path(view(graph), p)} :: 
                                    is_path(view(graph), p) && p[0] == start && p[|p| - 1] == v ==> false
                }
            )
        case None => 
            has_negative_cycle(view(graph))
    }
{
  var n := |graph.adj|;
  var D: seq<Option<int>> := seq(n, k => if k == start then Some(0) else None);
  InitInv(graph, start, D);
  var round := 1;
  while round < n
    invariant 1 <= round <= n
    invariant |D| == n
    invariant Witnessed(graph.adj, start, D, round)
    invariant Bounded(graph.adj, start, D, round)
    decreases n - round
  {
    D := Relax(graph, start, D, round);
    round := round + 1;
  }
  var u := 0;
  while u < n
    invariant 0 <= u <= n
    invariant forall u', i' :: 0 <= u' < u && 0 <= i' < |graph.adj[u']| && D[u'].Some? ==>
      0 <= graph.adj[u'][i'].0 < n && D[graph.adj[u'][i'].0].Some? && D[graph.adj[u'][i'].0].value <= D[u'].value + graph.adj[u'][i'].1
  {
    if D[u].Some? {
      var i := 0;
      while i < |graph.adj[u]|
        invariant 0 <= i <= |graph.adj[u]|
        invariant forall u', i' :: 0 <= u' < u && 0 <= i' < |graph.adj[u']| && D[u'].Some? ==>
          0 <= graph.adj[u'][i'].0 < n && D[graph.adj[u'][i'].0].Some? && D[graph.adj[u'][i'].0].value <= D[u'].value + graph.adj[u'][i'].1
        invariant forall i' :: 0 <= i' < i ==>
          0 <= graph.adj[u][i'].0 < n && D[graph.adj[u][i'].0].Some? && D[graph.adj[u][i'].0].value <= D[u].value + graph.adj[u][i'].1
      {
        var v: int := graph.adj[u][i].0;
        var w: int := graph.adj[u][i].1;
        if D[v].None? || D[u].value + w < D[v].value {
          NegCycle(graph, start, D, u, i);
          return None;
        }
        i := i + 1;
      }
    }
    u := u + 1;
  }
  assert Fixed(graph.adj, D);
  FinalCorrect(graph, start, D);
  return Some(D);
}
