method remove_min(tree: Tree) returns (min_v: int, res: Tree)
    requires tree != Empty
    requires is_bst(tree)
    ensures is_bst(res)
    ensures min_v in view(tree)
    ensures view(res) == view(tree) - {min_v}
    ensures forall x :: x in view(tree) ==> min_v <= x
    ensures forall x :: x in view(res) ==> min_v < x
    decreases tree
{
    match tree
    case Node(val, left, right) =>
        if left == Empty {
            min_v := val;
            res := right;
            assert view(left) == {};
            if val in view(right) {
                assert val > val;
            }
            assert val !in view(right);
        } else {
            var l_min, new_left := remove_min(left);
            min_v := l_min;
            res := Node(val, new_left, right);
            assert min_v < val;
            if min_v in view(right) {
                assert min_v > val;
            }
            assert min_v !in view(right);
            forall x | x in view(tree)
                ensures min_v <= x
            {
                if x in view(left) {
                    assert min_v <= x;
                } else if x in view(right) {
                    assert x > val;
                } else {
                    assert x == val;
                }
            }
            forall x | x in view(res)
                ensures min_v < x
            {
                if x in view(new_left) {
                    assert min_v < x;
                } else if x in view(right) {
                    assert x > val;
                } else {
                    assert x == val;
                }
            }
        }
}

method delete(tree: Tree, v: int) returns (res: Tree)
    requires v >= 0
    requires is_bst(tree)
    ensures is_bst(res)
    ensures view(res) == view(tree) - {v}
    decreases tree
{
    match tree
    case Empty =>
        res := Empty;
    case Node(val, left, right) =>
        if v < val {
            var new_left := delete(left, v);
            res := Node(val, new_left, right);
            if v in view(right) {
                assert v > val;
            }
            assert v !in view(right);
        } else if v > val {
            var new_right := delete(right, v);
            res := Node(val, left, new_right);
            if v in view(left) {
                assert v < val;
            }
            assert v !in view(left);
        } else {
            if v in view(left) {
                assert v < val;
            }
            assert v !in view(left);
            if v in view(right) {
                assert v > val;
            }
            assert v !in view(right);

            if left == Empty {
                assert view(left) == {};
                res := right;
            } else if right == Empty {
                assert view(right) == {};
                res := left;
            } else {
                var min_r, new_right := remove_min(right);
                res := Node(min_r, left, new_right);
                assert min_r > val;
                assert view(new_right) + {min_r} == view(right);
                assert view(res) == view(left) + view(right);
                assert view(tree) - {v} == view(left) + view(right);
            }
        }
}

