code:
ghost predicate IsEdge(g: Graph, u: int, i: int) {
  0 <= u < |g.adj| && 0 <= i < |g.adj[u]|
}

ghost predicate OK(g: Graph, colored: seq<bool>, color: seq<bool>, u: int, i: int)
  requires well_formed(g) && |colored| == |g.adj| && |color| == |g.adj| && IsEdge(g, u, i)
{
  (colored[u] <==> colored[g.adj[u][i]]) && (colored[u] ==> color[u] != color[g.adj[u][i]])
}

ghost predicate AllOK(g: Graph, colored: seq<bool>, color: seq<bool>)
  requires well_formed(g) && |colored| == |g.adj| && |color| == |g.adj|
{
  forall u, i :: IsEdge(g, u, i) ==> OK(g, colored, color, u, i)
}

ghost predicate RelC(g: Graph, colored: seq<bool>, color: seq<bool>, root: seq<int>, c: seq<bool>)
  requires |colored| == |g.adj| && |color| == |g.adj| && |root| == |g.adj| && |c| == |g.adj|
{
  forall v, w :: 0 <= v < |g.adj| && 0 <= w < |g.adj| && colored[v] && colored[w] && root[v] == root[w]
    ==> ((c[v] == c[w]) <==> (color[v] == color[w]))
}

ghost predicate Rel(g: Graph, colored: seq<bool>, color: seq<bool>, root: seq<int>)
  requires |colored| == |g.adj| && |color| == |g.adj| && |root| == |g.adj|
{
  forall c: seq<bool> :: is_valid_coloring(g, c) ==> RelC(g, colored, color, root, c)
}

ghost predicate SameRoot(g: Graph, colored: seq<bool>, root: seq<int>)
  requires well_formed(g) && |colored| == |g.adj| && |root| == |g.adj|
{
  forall u, i :: IsEdge(g, u, i) && colored[u] && colored[g.adj[u][i]] ==> root[u] == root[g.adj[u][i]]
}

ghost predicate FinishedClosed(g: Graph, colored: seq<bool>, root: seq<int>, s: int)
  requires well_formed(g) && |colored| == |g.adj| && |root| == |g.adj|
{
  forall u, i :: IsEdge(g, u, i) ==>
    (colored[u] && root[u] < s ==> colored[g.adj[u][i]]) &&
    (colored[g.adj[u][i]] && root[g.adj[u][i]] < s ==> colored[u])
}

ghost predicate RootBound(colored: seq<bool>, root: seq<int>, s: int)
  requires |colored| == |root|
{
  forall v :: 0 <= v < |colored| && colored[v] ==> root[v] <= s
}

ghost function CountTrue(s: seq<bool>): nat
  decreases |s|
{
  if |s| == 0 then 0 else (if s[0] then 1 else 0) + CountTrue(s[1..])
}

lemma CountBound(s: seq<bool>)
  ensures CountTrue(s) <= |s|
  decreases |s|
{
  if |s| > 0 { CountBound(s[1..]); }
}

lemma CountUpdate(s: seq<bool>, i: int)
  requires 0 <= i < |s| && !s[i]
  ensures CountTrue(s[i := true]) == CountTrue(s) + 1
  decreases |s|
{
  if i == 0 {
    assert s[i := true][1..] == s[1..];
  } else {
    assert s[i := true][1..] == s[1..][i - 1 := true];
    CountUpdate(s[1..], i - 1);
  }
}

lemma StartComponent(g: Graph, colored: seq<bool>, color: seq<bool>, root: seq<int>, s: int)
  requires well_formed(g)
  requires |colored| == |g.adj| && |color| == |g.adj| && |root| == |g.adj|
  requires 0 <= s < |g.adj| && !colored[s]
  requires forall v :: 0 <= v < |g.adj| && colored[v] ==> root[v] < s
  requires Rel(g, colored, color, root)
  requires SameRoot(g, colored, root)
  requires AllOK(g, colored, color)
  ensures Rel(g, colored[s := true], color[s := false], root[s := s])
  ensures SameRoot(g, colored[s := true], root[s := s])
  ensures FinishedClosed(g, colored[s := true], root[s := s], s)
  ensures RootBound(colored[s := true], root[s := s], s)
{
  var nc := colored[s := true];
  var ncol := color[s := false];
  var nr := root[s := s];
  forall c | is_valid_coloring(g, c) ensures RelC(g, nc, ncol, nr, c) {
    assert RelC(g, colored, color, root, c);
    forall v, w | 0 <= v < |g.adj| && 0 <= w < |g.adj| && nc[v] && nc[w] && nr[v] == nr[w]
      ensures (c[v] == c[w]) <==> (ncol[v] == ncol[w])
    {
      if v == s || w == s {
        assert v == w;
      } else {
        assert colored[v] && colored[w] && root[v] == root[w];
      }
    }
  }
  forall u, i | IsEdge(g, u, i) && nc[u] && nc[g.adj[u][i]] ensures nr[u] == nr[g.adj[u][i]] {
    assert OK(g, colored, color, u, i);
  }
  forall u, i | IsEdge(g, u, i)
    ensures (nc[u] && nr[u] < s ==> nc[g.adj[u][i]]) && (nc[g.adj[u][i]] && nr[g.adj[u][i]] < s ==> nc[u])
  {
    assert OK(g, colored, color, u, i);
  }
}

lemma ColorStep(g: Graph, colored: seq<bool>, color: seq<bool>, root: seq<int>, s: int, x: int, y: int)
  requires well_formed(g)
  requires |colored| == |g.adj| && |color| == |g.adj| && |root| == |g.adj|
  requires 0 <= x < |g.adj| && 0 <= y < |g.adj|
  requires colored[y] && !colored[x]
  requires has_edge(g, y, x) || has_edge(g, x, y)
  requires Rel(g, colored, color, root)
  requires SameRoot(g, colored, root)
  requires FinishedClosed(g, colored, root, s)
  requires RootBound(colored, root, s)
  ensures Rel(g, colored[x := true], color[x := !color[y]], root[x := s])
  ensures SameRoot(g, colored[x := true], root[x := s])
  ensures FinishedClosed(g, colored[x := true], root[x := s], s)
  ensures RootBound(colored[x := true], root[x := s], s)
{
  var nc := colored[x := true];
  var ncol := color[x := !color[y]];
  var nr := root[x := s];
  assert root[y] <= s;
  if has_edge(g, y, x) {
    var i :| 0 <= y < |g.adj| && 0 <= i < |g.adj[y]| && g.adj[y][i] == x;
    assert IsEdge(g, y, i);
    assert root[y] == s;
  } else {
    var i :| 0 <= x < |g.adj| && 0 <= i < |g.adj[x]| && g.adj[x][i] == y;
    assert IsEdge(g, x, i);
    assert root[y] == s;
  }
