    case Empty =>
        assert false;
        maximum := 0;
        rest := Empty;

    case Node(root, left, right) =>
        if right == Empty {
            maximum := root;
            rest := left;

            assert is_bst(rest);
            assert maximum in view(tree);
            assert view(tree) == view(rest) + {maximum};

            assert forall x :: x in view(rest) ==> x < maximum by {
                forall x | x in view(rest)
                    ensures x < maximum
                {
                    assert x in view(left);
                    assert x < root;
                }
            }
        } else {
            var rightMaximum, newRight := RemoveMaximum(right);
            maximum := rightMaximum;
            rest := Node(root, left, newRight);

            assert maximum in view(right);
            assert maximum > root;

            assert forall x :: x in view(newRight) ==> x in view(right) by {
                forall x | x in view(newRight)
                    ensures x in view(right)
                {
                    assert x in view(newRight) + {maximum};
                }
            }

            assert forall x :: x in view(newRight) ==> x > root by {
                forall x | x in view(newRight)
                    ensures x > root
