                        assert x < maximum;
                    } else {
                        assert x == root;
                        assert root < maximum;
                    }
                }
            }

            assert view(tree) == view(rest) + {maximum} by {
                forall x
                    ensures
                        x in view(tree)
                        <==>
                        x in view(rest) + {maximum}
                {
                    assert
                        x in view(right)
                        <==>
                        x in view(newRight) + {maximum};
                }
            }

            assert maximum in view(tree);
        }
