method zig(tree: Tree) returns (res: Tree)
    // tree corresponds to Box<Node>, so it cannot be Empty
    requires tree.Node? 
    // tree.left corresponds to node.left.is_some()
    requires tree.left.Node? 
    requires is_bst(tree)
    ensures is_bst(res)
    ensures view(res) == view(tree)
    // The left child is now the root
    ensures res.val == tree.left.val 
    // Old root is now right child
    ensures res.right.Node? && res.right.val == tree.val
{
    var l := tree.left;
    assert is_bst(l);
    assert l.val in view(l);
    assert l.val < tree.val;
    assert forall x :: x in view(l.right) ==> x in view(l);
    assert forall x :: x in view(l.right) ==> x < tree.val;
    assert forall x :: x in view(l.right) ==> x > l.val;
    assert forall x :: x in view(tree.right) ==> x > tree.val;
    var newRight := Node(tree.val, l.right, tree.right);
    assert is_bst(newRight);
    assert view(newRight) == view(l.right) + view(tree.right) + {tree.val};
    assert forall x :: x in view(newRight) ==> x > l.val;
    res := Node(l.val, l.left, newRight);
    assert view(res) == view(l.left) + view(newRight) + {l.val};
    assert view(tree) == view(l) + view(tree.right) + {tree.val};
    assert view(l) == view(l.left) + view(l.right) + {l.val};
}

