    assert view(newRight) == view(l.right) + view(tree.right) + {tree.val};
    assert forall x :: x in view(newRight) ==> x > l.val;
    res := Node(l.val, l.left, newRight);
    assert view(res) == view(l.left) + view(newRight) + {l.val};
    assert view(tree) == view(l) + view(tree.right) + {tree.val};
    assert view(l) == view(l.left) + view(l.right) + {l.val};
}
