function OptSeq(o: Option<int>): seq<int> {
    match o
    case Some(x) => [x]
    case None => []
}

function RowCosts(
    row: seq<(int, int)>,
    du: Option<int>,
    v: int,
    i: int
): seq<int>
    requires 0 <= i <= |row|
    decreases |row| - i
{
    if i == |row| then []
    else
        (if row[i].0 == v then
            match du
            case Some(d) => [d + row[i].1]
            case None => []
         else [])
        + RowCosts(row, du, v, i + 1)
}

function EdgeCosts(
    g: seq<seq<(int, int)>>,
    prev: seq<Option<int>>,
    v: int,
    u: int
): seq<int>
    requires |prev| == |g|
    requires 0 <= u <= |g|
    decreases |g| - u
{
    if u == |g| then []
    else
        RowCosts(g[u], prev[u], v, 0)
        + EdgeCosts(g, prev, v, u + 1)
}

function SeqMin(xs: seq<int>): int
    requires |xs| > 0
    decreases |xs|
{
    if |xs| == 1 then
        xs[0]
    else
        var m := SeqMin(xs[1..]);
        if xs[0] <= m then xs[0] else m
}

function MinOpt(xs: seq<int>): Option<int> {
    if |xs| == 0 then None else Some(SeqMin(xs))
}

lemma SeqMinSpec(xs: seq<int>)
    requires |xs| > 0
    ensures SeqMin(xs) in xs
    ensures forall x: int {:trigger x in xs} ::
        x in xs ==> SeqMin(xs) <= x
    decreases |xs|
{
    if |xs| == 1 {
        assert SeqMin(xs) == xs[0];
    } else {
        var tail := xs[1..];
        SeqMinSpec(tail);
        var tm := SeqMin(tail);

        assert tm in tail;
        assert tm in xs;

        assert forall x: int {:trigger x in xs} ::
            x in xs ==> x == xs[0] || x in tail by {
            forall x: int {:trigger x in xs}
                | x in xs
                ensures x == xs[0] || x in tail
            {
                var i :| 0 <= i < |xs| && xs[i] == x;
                if i > 0 {
                    assert tail[i - 1] == x;
                }
            }
        }

        if xs[0] <= tm {
            assert SeqMin(xs) == xs[0];
            assert forall x: int {:trigger x in xs} ::
                x in xs ==> SeqMin(xs) <= x by {
                forall x: int {:trigger x in xs}
                    | x in xs
                    ensures SeqMin(xs) <= x
                {
                    if x != xs[0] {
                        assert x in tail;
                        assert tm <= x;
                    }
                }
            }
        } else {
            assert SeqMin(xs) == tm;
            assert forall x: int {:trigger x in xs} ::
                x in xs ==> SeqMin(xs) <= x by {
                forall x: int {:trigger x in xs}
                    | x in xs
                    ensures SeqMin(xs) <= x
                {
                    if x == xs[0] {
                        assert tm < xs[0];
                    } else {
                        assert x in tail;
                        assert tm <= x;
                    }
                }
            }
        }
    }
}

lemma MinOptSpec(xs: seq<int>)
    ensures match MinOpt(xs)
        case None => |xs| == 0
        case Some(m) =>
            m in xs &&
            forall x: int {:trigger x in xs} ::
                x in xs ==> m <= x
{
