}

function RelaxValue(
    g: seq<seq<(int, int)>>,
    prev: seq<Option<int>>,
    v: int
): Option<int>
    requires |prev| == |g|
    requires 0 <= v < |g|
{
    MinOpt(OptSeq(prev[v]) + EdgeCosts(g, prev, v, 0))
}

function Relax(
    g: seq<seq<(int, int)>>,
    prev: seq<Option<int>>
): seq<Option<int>>
    requires |prev| == |g|
{
    seq(|g|,
        v requires 0 <= v < |g| =>
