}

function Initial(
    g: seq<seq<(int, int)>>,
    start: int
): seq<Option<int>>
    requires 0 <= start < |g|
{
    seq(|g|,
        v requires 0 <= v < |g| =>
            if v == start then Some(0) else None)
}

function Run(
    g: seq<seq<(int, int)>>,
    start: int,
    rounds: nat
): seq<Option<int>>
    requires 0 <= start < |g|
    ensures |Run(g, start, rounds)| == |g|
    decreases rounds
{
    if rounds == 0 then
        Initial(g, start)
    else
        Relax(g, Run(g, start, rounds - 1))
}

ghost predicate Candidate(
