lemma RowCostSound(
    row: seq<(int, int)>,
    du: Option<int>,
    v: int,
    i: int,
    c: int
)
    requires 0 <= i <= |row|
    requires c in RowCosts(row, du, v, i)
    ensures exists j: int, d: int ::
        i <= j < |row| &&
        row[j].0 == v &&
        du == Some(d) &&
        c == d + row[j].1
    decreases |row| - i
{
    assert i < |row|;

    var head :=
        if row[i].0 == v then
            match du
            case Some(d) => [d + row[i].1]
            case None => []
        else [];

    if c in head {
        match du
        case Some(d) => {
            assert row[i].0 == v;
            assert c == d + row[i].1;
            assert exists j: int, x: int ::
                i <= j < |row| &&
                row[j].0 == v &&
                du == Some(x) &&
                c == x + row[j].1 by {
                assert i <= i < |row|;
            }
        }
        case None => {
            assert |head| == 0;
            assert false;
        }
    } else {
        assert c in RowCosts(row, du, v, i + 1);
        RowCostSound(row, du, v, i + 1, c);
    }
}

lemma RowCostComplete(
    row: seq<(int, int)>,
    du: int,
    v: int,
    i: int,
    j: int
)
    requires 0 <= i <= j < |row|
    requires row[j].0 == v
    ensures du + row[j].1 in
        RowCosts(row, Some(du), v, i)
    decreases j - i
{
    if i == j {
        assert du + row[j].1 in
            [du + row[i].1];
    } else {
        RowCostComplete(row, du, v, i + 1, j);
        assert du + row[j].1 in
            RowCosts(row, Some(du), v, i + 1);
    }
}

lemma EdgeCostSound(
    g: seq<seq<(int, int)>>,
    prev: seq<Option<int>>,
    v: int,
    first: int,
    c: int
)
    requires |prev| == |g|
    requires 0 <= first <= |g|
    requires c in EdgeCosts(g, prev, v, first)
    ensures exists u: int, j: int, du: int ::
        first <= u < |g| &&
        0 <= j < |g[u]| &&
        g[u][j].0 == v &&
        prev[u] == Some(du) &&
        c == du + g[u][j].1
    decreases |g| - first
{
    assert first < |g|;

    if c in RowCosts(g[first], prev[first], v, 0) {
        RowCostSound(g[first], prev[first], v, 0, c);
        var j, du :|
            0 <= j < |g[first]| &&
            g[first][j].0 == v &&
            prev[first] == Some(du) &&
            c == du + g[first][j].1;
        assert exists u: int, k: int, d: int ::
            first <= u < |g| &&
            0 <= k < |g[u]| &&
            g[u][k].0 == v &&
            prev[u] == Some(d) &&
            c == d + g[u][k].1 by {
            assert first <= first < |g|;
        }
    } else {
        assert c in EdgeCosts(g, prev, v, first + 1);
        EdgeCostSound(g, prev, v, first + 1, c);
    }
}

lemma EdgeCostComplete(
    g: seq<seq<(int, int)>>,
    prev: seq<Option<int>>,
    v: int,
    first: int,
    u: int,
    j: int,
    du: int
)
    requires |prev| == |g|
    requires 0 <= first <= u < |g|
    requires 0 <= j < |g[u]|
    requires g[u][j].0 == v
    requires prev[u] == Some(du)
    ensures du + g[u][j].1 in
        EdgeCosts(g, prev, v, first)
    decreases u - first
{
    if first == u {
        RowCostComplete(g[u], du, v, 0, j);
    } else {
        EdgeCostComplete(
            g, prev, v, first + 1, u, j, du);
    }
}

lemma PathPrefix(
    g: seq<seq<(int, int)>>,
    p: seq<int>,
    n: int
)
    requires is_path(g, p)
    requires 1 <= n <= |p|
    ensures is_path(g, p[..n])
{
    assert |p[..n]| > 0;
    assert forall i: int ::
        0 <= i < |p[..n]| - 1 ==>
        connected(g, p[..n][i], p[..n][i + 1]) by {
        forall i: int | 0 <= i < |p[..n]| - 1
            ensures connected(
                g, p[..n][i], p[..n][i + 1])
        {
            assert p[..n][i] == p[i];
            assert p[..n][i + 1] == p[i + 1];
        }
    }
}

lemma PathSlice(
    g: seq<seq<(int, int)>>,
    p: seq<int>,
    lo: int,
    hi: int
)
    requires is_path(g, p)
    requires 0 <= lo < hi <= |p|
    ensures is_path(g, p[lo..hi])
{
