    assert forall i: int ::
        0 <= i < |p[lo..hi]| - 1 ==>
        connected(
            g, p[lo..hi][i], p[lo..hi][i + 1]) by {
        forall i: int | 0 <= i < |p[lo..hi]| - 1
            ensures connected(
                g, p[lo..hi][i], p[lo..hi][i + 1])
        {
            assert p[lo..hi][i] == p[lo + i];
            assert p[lo..hi][i + 1] == p[lo + i + 1];
        }
    }
}

lemma AppendPath(
    g: seq<seq<(int, int)>>,
    p: seq<int>,
    v: int
)
    requires is_path(g, p)
    requires connected(g, p[|p| - 1], v)
    ensures is_path(g, p + [v])
    ensures path_weight(g, p + [v]) ==
        path_weight(g, p) +
        get_edge_weight(g, p[|p| - 1], v)
{
    assert |p + [v]| > 0;
    assert forall i: int ::
        0 <= i < |p + [v]| - 1 ==>
        connected(
            g, (p + [v])[i], (p + [v])[i + 1]) by {
        forall i: int | 0 <= i < |p + [v]| - 1
            ensures connected(
                g, (p + [v])[i], (p + [v])[i + 1])
        {
            if i < |p| - 1 {
                assert (p + [v])[i] == p[i];
                assert (p + [v])[i + 1] == p[i + 1];
            } else {
                assert i == |p| - 1;
                assert (p + [v])[i] == p[|p| - 1];
                assert (p + [v])[i + 1] == v;
            }
        }
    }
    assert (p + [v])[..|p + [v]| - 1] == p;
}

lemma ExtendPath(
    graph: WeightedGraph,
    p: seq<int>,
    v: int,
    w: int
)
    requires well_formed(graph)
    requires is_path(view(graph), p)
    requires has_edge(
        view(graph), p[|p| - 1], v, w)
    ensures is_path(view(graph), p + [v])
    ensures path_weight(view(graph), p + [v]) ==
        path_weight(view(graph), p) + w
{
    assert connected(view(graph), p[|p| - 1], v);
    AppendPath(view(graph), p, v);
    GetEdgeWeightLemma(
        graph, p[|p| - 1], v, w);
}

lemma InitialOptimal(
    graph: WeightedGraph,
    start: int
)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    ensures BoundedOptimal(
        view(graph), start, 0,
        Initial(view(graph), start))
{
    var ds := Initial(view(graph), start);
    assert |ds| == size(graph);

    forall v: int | 0 <= v < size(graph)
        ensures VertexOptimal(
            view(graph), start, v, 0, ds[v])
    {
        if v == start {
            assert Candidate(
                view(graph), start, v, 0, [start]);
            assert path_weight(view(graph), [start]) == 0;

            assert exists p: seq<int>
                {:trigger Candidate(
                    view(graph), start, v, 0, p)} ::
                Candidate(
                    view(graph), start, v, 0, p) &&
                path_weight(view(graph), p) == 0 by {
                assert Candidate(
                    view(graph), start, v, 0, [start]);
            }

            assert forall p: seq<int>
                {:trigger Candidate(
                    view(graph), start, v, 0, p)} ::
                Candidate(
                    view(graph), start, v, 0, p) ==>
                0 <= path_weight(view(graph), p) by {
                forall p: seq<int>
                    {:trigger Candidate(
                        view(graph), start, v, 0, p)}
                    | Candidate(
                        view(graph), start, v, 0, p)
                    ensures 0 <= path_weight(view(graph), p)
                {
                    assert |p| - 1 <= 0;
                    assert |p| > 0;
                    assert |p| == 1;
                    assert path_weight(view(graph), p) == 0;
                }
            }
            assert ds[v] == Some(0);
        } else {
            assert forall p: seq<int>
                {:trigger Candidate(
                    view(graph), start, v, 0, p)} ::
                Candidate(
                    view(graph), start, v, 0, p) ==>
                false by {
                forall p: seq<int>
                    {:trigger Candidate(
                        view(graph), start, v, 0, p)}
                    | Candidate(
                        view(graph), start, v, 0, p)
                    ensures false
                {
                    assert |p| > 0;
                    assert |p| - 1 <= 0;
                    assert |p| == 1;
                    assert p[0] == start;
                    assert p[|p| - 1] == v;
                    assert start == v;
                }
            }
            assert ds[v] == None;
        }
    }

    assert forall v: int {:trigger ds[v]} ::
        0 <= v < size(graph) ==>
        VertexOptimal(view(graph), start, v, 0, ds[v]);
}

lemma CostHasCandidate(
    graph: WeightedGraph,
    start: int,
    rounds: nat,
    prev: seq<Option<int>>,
    v: int,
    c: int
)
    requires well_formed(graph)
    requires BoundedOptimal(
        view(graph), start, rounds, prev)
    requires 0 <= v < size(graph)
    requires c in
        OptSeq(prev[v]) +
        EdgeCosts(view(graph), prev, v, 0)
    ensures exists p: seq<int>
        {:trigger Candidate(
            view(graph), start, v, rounds + 1, p)} ::
        Candidate(
            view(graph), start, v, rounds + 1, p) &&
        path_weight(view(graph), p) == c
{
    var xs :=
        OptSeq(prev[v]) +
        EdgeCosts(view(graph), prev, v, 0);

    if c in OptSeq(prev[v]) {
        match prev[v]
        case Some(d) => {
            assert c == d;
            assert VertexOptimal(
                view(graph), start, v, rounds, prev[v]);

            var p :|
                Candidate(
                    view(graph), start, v, rounds, p) &&
                path_weight(view(graph), p) == d;

            assert Candidate(
                view(graph), start, v, rounds + 1, p);

            assert exists q: seq<int>
                {:trigger Candidate(
                    view(graph), start, v,
                    rounds + 1, q)} ::
                Candidate(
                    view(graph), start, v,
                    rounds + 1, q) &&
                path_weight(view(graph), q) == c by {
                assert Candidate(
                    view(graph), start, v,
                    rounds + 1, p);
            }
        }
        case None => {
            assert |OptSeq(prev[v])| == 0;
            assert false;
        }
    } else {
        assert c in EdgeCosts(
            view(graph), prev, v, 0);
        EdgeCostSound(
            view(graph), prev, v, 0, c);

        var u, j, du :|
            0 <= u < size(graph) &&
            0 <= j < |graph.adj[u]| &&
            graph.adj[u][j].0 == v &&
            prev[u] == Some(du) &&
            c == du + graph.adj[u][j].1;

        assert VertexOptimal(
            view(graph), start, u, rounds, prev[u]);

        var p :|
            Candidate(
                view(graph), start, u, rounds, p) &&
            path_weight(view(graph), p) == du;

        assert has_edge(
            view(graph), u, v, graph.adj[u][j].1);
        assert p[|p| - 1] == u;

        ExtendPath(
            graph, p, v, graph.adj[u][j].1);

        assert Candidate(
            view(graph), start, v,
            rounds + 1, p + [v]);

        assert path_weight(
            view(graph), p + [v]) == c;

        assert exists q: seq<int>
            {:trigger Candidate(
                view(graph), start, v,
                rounds + 1, q)} ::
            Candidate(
                view(graph), start, v,
                rounds + 1, q) &&
            path_weight(view(graph), q) == c by {
            assert Candidate(
                view(graph), start, v,
                rounds + 1, p + [v]);
        }
    }
}

lemma PathVerticesBound(
    graph: WeightedGraph,
    p: seq<int>
)
    requires well_formed(graph)
    requires is_path(view(graph), p)
    requires |p| >= 2
    ensures forall i: int :: 0 <= i < |p| ==>
        0 <= p[i] < size(graph)
{
    forall i: int | 0 <= i < |p|
        ensures 0 <= p[i] < size(graph)
    {
        if i < |p| - 1 {
            assert connected(
                view(graph), p[i], p[i + 1]);
            var w :|
                has_edge(
                    view(graph), p[i], p[i + 1], w);
            var j :|
                0 <= p[i] < |graph.adj| &&
                0 <= j < |graph.adj[p[i]]| &&
                graph.adj[p[i]][j].0 == p[i + 1] &&
                graph.adj[p[i]][j].1 == w;
            assert 0 <= p[i] < size(graph);
        } else {
            assert i > 0;
            assert connected(
                view(graph), p[i - 1], p[i]);
            var w :|
                has_edge(
                    view(graph), p[i - 1], p[i], w);
            var j :|
                0 <= p[i - 1] < |graph.adj| &&
                0 <= j < |graph.adj[p[i - 1]]| &&
                graph.adj[p[i - 1]][j].0 == p[i] &&
                graph.adj[p[i - 1]][j].1 == w;
            assert 0 <= graph.adj[p[i - 1]][j].0
                < |graph.adj|;
        }
    }
}

lemma CandidateHasLowerCost(
    graph: WeightedGraph,
    start: int,
    rounds: nat,
    prev: seq<Option<int>>,
    v: int,
    p: seq<int>
)
    requires well_formed(graph)
    requires BoundedOptimal(
        view(graph), start, rounds, prev)
    requires 0 <= v < size(graph)
    requires Candidate(
        view(graph), start, v, rounds + 1, p)
    ensures exists c: int ::
        c in
            OptSeq(prev[v]) +
            EdgeCosts(view(graph), prev, v, 0) &&
        c <= path_weight(view(graph), p)
{
    var xs :=
        OptSeq(prev[v]) +
        EdgeCosts(view(graph), prev, v, 0);

    if |p| - 1 <= rounds {
        assert Candidate(
            view(graph), start, v, rounds, p);
        assert VertexOptimal(
            view(graph), start, v, rounds, prev[v]);

        match prev[v]
        case Some(d) => {
            assert d in OptSeq(prev[v]);
            assert d in xs;
            assert d <= path_weight(view(graph), p);
            assert exists c: int ::
                c in xs &&
                c <= path_weight(view(graph), p) by {
                assert d in xs;
            }
        }
        case None => {
            assert Candidate(
                view(graph), start, v, rounds, p);
            assert false;
        }
    } else {
        assert |p| - 1 <= rounds + 1;
        assert |p| - 1 == rounds + 1;
        assert |p| >= 2;

        PathVerticesBound(graph, p);

        var q := p[..|p| - 1];
        var u := p[|p| - 2];

        PathPrefix(view(graph), p, |p| - 1);
        assert q[0] == start;
        assert q[|q| - 1] == u;
        assert |q| - 1 == rounds;
        assert Candidate(
            view(graph), start, u, rounds, q);

        assert connected(view(graph), u, v);
        var w :| has_edge(view(graph), u, v, w);
        GetEdgeWeightLemma(graph, u, v, w);

        assert 0 <= u < size(graph);
        assert VertexOptimal(
            view(graph), start, u, rounds, prev[u]);

        match prev[u]
        case Some(du) => {
            assert du <= path_weight(view(graph), q);

            var j :|
                0 <= u < |graph.adj| &&
                0 <= j < |graph.adj[u]| &&
                graph.adj[u][j].0 == v &&
                graph.adj[u][j].1 == w;

            EdgeCostComplete(
                view(graph), prev, v, 0, u, j, du);

            assert du + w in
                EdgeCosts(view(graph), prev, v, 0);
            assert du + w in xs;

            assert p[..|p| - 1] == q;
            assert path_weight(view(graph), p) ==
                path_weight(view(graph), q) +
                get_edge_weight(view(graph), u, v);
            assert path_weight(view(graph), p) ==
                path_weight(view(graph), q) + w;
            assert du + w <= path_weight(view(graph), p);

            assert exists c: int ::
                c in xs &&
                c <= path_weight(view(graph), p) by {
                assert du + w in xs;
            }
        }
        case None => {
            assert Candidate(
                view(graph), start, u, rounds, q);
            assert false;
        }
    }
}

lemma RelaxVertexOptimal(
    graph: WeightedGraph,
    start: int,
    rounds: nat,
    prev: seq<Option<int>>,
    v: int
)
    requires well_formed(graph)
    requires BoundedOptimal(
        view(graph), start, rounds, prev)
    requires 0 <= v < size(graph)
    ensures VertexOptimal(
        view(graph), start, v, rounds + 1,
        RelaxValue(view(graph), prev, v))
{
    var xs :=
        OptSeq(prev[v]) +
        EdgeCosts(view(graph), prev, v, 0);

    MinOptSpec(xs);
    assert RelaxValue(view(graph), prev, v) ==
        MinOpt(xs);

    match MinOpt(xs)
    case Some(m) => {
        assert m in xs;
        CostHasCandidate(
            graph, start, rounds, prev, v, m);

        var wp :|
            Candidate(
                view(graph), start, v,
                rounds + 1, wp) &&
            path_weight(view(graph), wp) == m;

        assert exists p: seq<int>
            {:trigger Candidate(
                view(graph), start, v,
                rounds + 1, p)} ::
            Candidate(
                view(graph), start, v,
                rounds + 1, p) &&
            path_weight(view(graph), p) == m by {
            assert Candidate(
                view(graph), start, v,
                rounds + 1, wp);
        }

        assert forall p: seq<int>
            {:trigger Candidate(
                view(graph), start, v,
                rounds + 1, p)} ::
            Candidate(
                view(graph), start, v,
                rounds + 1, p) ==>
            m <= path_weight(view(graph), p) by {
            forall p: seq<int>
                {:trigger Candidate(
                    view(graph), start, v,
                    rounds + 1, p)}
                | Candidate(
                    view(graph), start, v,
                    rounds + 1, p)
                ensures m <= path_weight(view(graph), p)
            {
                CandidateHasLowerCost(
                    graph, start, rounds, prev, v, p);

                var c :|
                    c in xs &&
                    c <= path_weight(view(graph), p);

                assert m <= c;
            }
        }

        assert VertexOptimal(
            view(graph), start, v, rounds + 1,
            Some(m));
    }
    case None => {
        assert |xs| == 0;

        assert forall p: seq<int>
            {:trigger Candidate(
                view(graph), start, v,
                rounds + 1, p)} ::
            Candidate(
                view(graph), start, v,
                rounds + 1, p) ==>
            false by {
            forall p: seq<int>
                {:trigger Candidate(
                    view(graph), start, v,
                    rounds + 1, p)}
                | Candidate(
                    view(graph), start, v,
                    rounds + 1, p)
                ensures false
            {
                CandidateHasLowerCost(
                    graph, start, rounds, prev, v, p);
                var c :|
                    c in xs &&
                    c <= path_weight(view(graph), p);
                assert false;
            }
        }

        assert VertexOptimal(
            view(graph), start, v, rounds + 1,
            None);
    }
}

lemma RelaxOptimal(
    graph: WeightedGraph,
    start: int,
    rounds: nat,
    prev: seq<Option<int>>
)
    requires well_formed(graph)
    requires BoundedOptimal(
        view(graph), start, rounds, prev)
    ensures BoundedOptimal(
        view(graph), start, rounds + 1,
        Relax(view(graph), prev))
{
    var next := Relax(view(graph), prev);
    assert |next| == size(graph);

    forall v: int | 0 <= v < size(graph)
        ensures VertexOptimal(
            view(graph), start, v,
            rounds + 1, next[v])
    {
        RelaxVertexOptimal(
            graph, start, rounds, prev, v);
        assert next[v] ==
            RelaxValue(view(graph), prev, v);
    }

    assert forall v: int {:trigger next[v]} ::
        0 <= v < size(graph) ==>
        VertexOptimal(
            view(graph), start, v,
            rounds + 1, next[v]);
}

lemma RunOptimal(
    graph: WeightedGraph,
    start: int,
    rounds: nat
)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    ensures BoundedOptimal(
        view(graph), start, rounds,
        Run(view(graph), start, rounds))
    decreases rounds
{
    if rounds == 0 {
        InitialOptimal(graph, start);
    } else {
        RunOptimal(graph, start, rounds - 1);
        RelaxOptimal(
            graph, start, rounds - 1,
            Run(view(graph), start, rounds - 1));
    }
}

lemma Pigeonhole(p: seq<int>, n: nat)
    requires |p| > n
    requires forall i: int :: 0 <= i < |p| ==>
        0 <= p[i] < n
    ensures exists i: int, j: int ::
        0 <= i < j < |p| && p[i] == p[j]
    decreases n
{
    if n == 0 {
        assert |p| > 0;
        assert 0 <= p[0] < 0;
        assert false;
    } else {
        var last := |p| - 1;
        var x := p[last];
        var q := p[..last];

        if exists i: int ::
            0 <= i < |q| && q[i] == x
        {
            var i :|
                0 <= i < |q| && q[i] == x;
            assert p[i] == p[last];
            assert 0 <= i < last < |p|;
        } else {
            var r := seq(
                |q|,
                k requires 0 <= k < |q| =>
                    if q[k] < x then q[k]
                    else q[k] - 1);

            assert |r| == |q|;
            assert |r| > n - 1;

            assert forall k: int ::
                0 <= k < |r| ==>
                0 <= r[k] < n - 1 by {
                forall k: int | 0 <= k < |r|
                    ensures 0 <= r[k] < n - 1
                {
                    assert k < |q|;
                    assert q[k] != x;
                    assert 0 <= q[k] < n;
                    assert 0 <= x < n;

                    if q[k] < x {
                        assert q[k] <= x - 1;
                        assert q[k] < n - 1;
                        assert r[k] == q[k];
                    } else {
                        assert q[k] > x;
                        assert q[k] >= 1;
                        assert r[k] == q[k] - 1;
                        assert r[k] < n - 1;
                    }
                }
            }

            Pigeonhole(r, n - 1);
            var i, j :|
                0 <= i < j < |r| &&
                r[i] == r[j];

            assert i < |q| && j < |q|;

            if q[i] < x {
                assert r[i] == q[i];
                if q[j] >= x {
                    assert q[j] != x;
                    assert q[j] > x;
                    assert r[j] == q[j] - 1;
                    assert r[i] < x;
                    assert r[j] >= x;
                    assert false;
                }
                assert r[j] == q[j];
            } else {
                assert q[i] != x;
                assert q[i] > x;
                assert r[i] == q[i] - 1;

                if q[j] < x {
                    assert r[j] == q[j];
                    assert r[j] < x;
                    assert r[i] >= x;
                    assert false;
                }

                assert q[j] != x;
                assert q[j] > x;
                assert r[j] == q[j] - 1;
            }

            assert q[i] == q[j];
            assert p[i] == p[j];
            assert 0 <= i < j < |p|;
        }
    }
}

lemma ConcatPaths(
    g: seq<seq<(int, int)>>,
    a: seq<int>,
    b: seq<int>
)
    requires is_path(g, a)
    requires is_path(g, b)
    requires a[|a| - 1] == b[0]
    ensures is_path(g, a + b[1..])
    ensures path_weight(g, a + b[1..]) ==
        path_weight(g, a) + path_weight(g, b)
    decreases |b|
{
    if |b| == 1 {
        assert b[1..] == [];
        assert a + b[1..] == a;
        assert path_weight(g, b) == 0;
        assert path_weight(g, a + b[1..]) ==
            path_weight(g, a);
    } else {
        var b0 := b[..|b| - 1];
        PathPrefix(g, b, |b| - 1);
        ConcatPaths(g, a, b0);

        var c := a + b0[1..];
        assert is_path(g, c);
        assert c[|c| - 1] == b[|b| - 2];

        assert connected(
            g, b[|b| - 2], b[|b| - 1]);
        AppendPath(g, c, b[|b| - 1]);

        assert b[1..] ==
            b0[1..] + [b[|b| - 1]];
        assert a + b[1..] ==
            c + [b[|b| - 1]];

        assert path_weight(g, b) ==
            path_weight(g, b0) +
            get_edge_weight(
                g, b[|b| - 2], b[|b| - 1]);

        assert path_weight(
            g, c + [b[|b| - 1]]) ==
            path_weight(g, c) +
            get_edge_weight(
                g, b[|b| - 2], b[|b| - 1]);

        assert path_weight(g, c) ==
            path_weight(g, a) +
            path_weight(g, b0);
    }
}

lemma SplicePath(
    g: seq<seq<(int, int)>>,
    p: seq<int>,
    i: int,
    j: int
) returns (cycle: seq<int>, rest: seq<int>)
    requires is_path(g, p)
    requires 0 <= i < j < |p|
    requires p[i] == p[j]
    ensures cycle == p[i..j + 1]
    ensures rest == p[..i + 1] + p[j + 1..]
    ensures is_path(g, cycle)
    ensures cycle[0] == cycle[|cycle| - 1]
    ensures is_path(g, rest)
    ensures rest[0] == p[0]
    ensures rest[|rest| - 1] == p[|p| - 1]
    ensures path_weight(g, p) ==
        path_weight(g, rest) +
        path_weight(g, cycle)
    ensures |rest| < |p|
{
    cycle := p[i..j + 1];

    var left := p[..i + 1];
    var right := p[j..];
    rest := left + right[1..];

    PathSlice(g, p, i, j + 1);
    PathPrefix(g, p, i + 1);
    PathSlice(g, p, j, |p|);

    assert cycle[0] == p[i];
    assert cycle[|cycle| - 1] == p[j];

    ConcatPaths(g, left, cycle);
    var throughCycle := left + cycle[1..];
    assert throughCycle == p[..j + 1];

    ConcatPaths(g, throughCycle, right);
    assert throughCycle + right[1..] == p;

    ConcatPaths(g, left, right);

    assert rest == left + right[1..];
    assert path_weight(g, throughCycle) ==
        path_weight(g, left) +
        path_weight(g, cycle);
    assert path_weight(g, p) ==
        path_weight(g, throughCycle) +
        path_weight(g, right);
    assert path_weight(g, rest) ==
        path_weight(g, left) +
        path_weight(g, right);

    assert |rest| ==
        |left| + |right| - 1;
    assert |left| == i + 1;
    assert |right| == |p| - j;
    assert j > i;
}

lemma SimplifyPath(
    graph: WeightedGraph,
    p: seq<int>
) returns (q: seq<int>)
    requires well_formed(graph)
    requires !has_negative_cycle(view(graph))
    requires is_path(view(graph), p)
    requires 0 <= p[0] < size(graph)
    requires 0 <= p[|p| - 1] < size(graph)
    ensures is_path(view(graph), q)
    ensures q[0] == p[0]
    ensures q[|q| - 1] == p[|p| - 1]
    ensures |q| <= size(graph)
    ensures path_weight(view(graph), q) <=
        path_weight(view(graph), p)
    decreases |p|
{
    if |p| <= size(graph) {
        q := p;
    } else {
        assert |p| >= 2;
        PathVerticesBound(graph, p);
        Pigeonhole(p, size(graph));

        var i, j :|
            0 <= i < j < |p| &&
            p[i] == p[j];

        var cycle, rest :=
            SplicePath(view(graph), p, i, j);

        assert |cycle| > 1;
        assert cycle[0] == cycle[|cycle| - 1];
        assert path_weight(view(graph), cycle) >= 0
            by {
                if path_weight(view(graph), cycle) < 0 {
                    assert has_negative_cycle(view(graph));
                    assert false;
                }
            }

        assert 0 <= rest[0] < size(graph);
        assert 0 <= rest[|rest| - 1] < size(graph);

        q := SimplifyPath(graph, rest);

        assert path_weight(view(graph), rest) <=
            path_weight(view(graph), p);
    }
}

lemma ShortNegativeCycle(
    graph: WeightedGraph,
    p: seq<int>
) returns (q: seq<int>)
    requires well_formed(graph)
    requires is_path(view(graph), p)
    requires |p| > 1
    requires p[0] == p[|p| - 1]
    requires path_weight(view(graph), p) < 0
    ensures is_path(view(graph), q)
    ensures |q| > 1
    ensures q[0] == q[|q| - 1]
    ensures path_weight(view(graph), q) < 0
    ensures |q| <= size(graph) + 1
    decreases |p|
{
    if |p| <= size(graph) + 1 {
        q := p;
    } else {
        PathVerticesBound(graph, p);

        var prefix := p[..|p| - 1];
        assert |prefix| > size(graph);
        assert forall i: int ::
            0 <= i < |prefix| ==>
            0 <= prefix[i] < size(graph);

        Pigeonhole(prefix, size(graph));

        var i, j :|
            0 <= i < j < |prefix| &&
            prefix[i] == prefix[j];

        assert p[i] == p[j];

        var cycle, rest :=
            SplicePath(view(graph), p, i, j);

        assert |cycle| > 1;
        assert cycle[0] == cycle[|cycle| - 1];

        assert |rest| > 1 by {
            if |rest| == 1 {
                assert rest[0] == p[0];
                assert rest[|rest| - 1] ==
                    p[|p| - 1];
                assert path_weight(view(graph), rest) == 0;
                assert p[0] == p[|p| - 1];
                assert cycle == p[i..j + 1];
            }
        }

        assert rest[0] == rest[|rest| - 1];

        if path_weight(view(graph), cycle) < 0 {
            q := ShortNegativeCycle(graph, cycle);
        } else {
            assert path_weight(view(graph), rest) < 0;
            q := ShortNegativeCycle(graph, rest);
        }
    }
}

function NegativeSource(
    g: seq<seq<(int, int)>>,
    first: int
): Option<int>
    requires 0 <= first <= |g|
    decreases |g| - first
{
    if first == |g| then
        None
    else
        match Run(g, first, |g|)[first]
        case Some(d) =>
            if d < 0 then Some(first)
            else NegativeSource(g, first + 1)
        case None =>
            NegativeSource(g, first + 1)
}

lemma NegativeSourceSpec(
    graph: WeightedGraph,
    first: int
)
    requires well_formed(graph)
    requires 0 <= first <= size(graph)
    ensures match NegativeSource(view(graph), first)
        case Some(s) =>
            first <= s < size(graph) &&
            (match Run(
                view(graph), s, size(graph))[s]
             case Some(d) => d < 0
             case None => false)
        case None =>
            forall s: int ::
                first <= s < size(graph) ==>
                (match Run(
                    view(graph), s, size(graph))[s]
                 case Some(d) => d >= 0
                 case None => true)
    decreases size(graph) - first
{
    if first < size(graph) {
        match Run(
            view(graph), first, size(graph))[first]
        case Some(d) => {
            if d >= 0 {
                NegativeSourceSpec(graph, first + 1);
            }
        }
        case None => {
            NegativeSourceSpec(graph, first + 1);
        }
    }
}

lemma NoNegativeCycle(
    graph: WeightedGraph
)
    requires well_formed(graph)
    requires size(graph) > 0
    requires NegativeSource(
        view(graph), 0) == None
    ensures !has_negative_cycle(view(graph))
{
    NegativeSourceSpec(graph, 0);

    if has_negative_cycle(view(graph)) {
        var p :|
            is_path(view(graph), p) &&
            |p| > 1 &&
            p[0] == p[|p| - 1] &&
            path_weight(view(graph), p) < 0;

        var q := ShortNegativeCycle(graph, p);
        PathVerticesBound(graph, q);

        var s := q[0];
        assert 0 <= s < size(graph);
        assert q[|q| - 1] == s;
        assert |q| - 1 <= size(graph);
        assert Candidate(
            view(graph), s, s, size(graph), q);

        RunOptimal(graph, s, size(graph));
        var ds := Run(
            view(graph), s, size(graph));

        assert VertexOptimal(
            view(graph), s, s, size(graph), ds[s]);

        assert match ds[s]
            case Some(d) => d >= 0
            case None => true;

        match ds[s]
        case Some(d) => {
            assert d <= path_weight(view(graph), q);
            assert d < 0;
            assert d >= 0;
            assert false;
        }
        case None => {
            assert Candidate(
                view(graph), s, s, size(graph), q);
            assert false;
        }
    }
}

lemma FinalDistances(
    graph: WeightedGraph,
    start: int
)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    requires !has_negative_cycle(view(graph))
    ensures |Run(
        view(graph), start, size(graph) - 1)| ==
        size(graph)
    ensures forall v: int
        {:trigger Run(
            view(graph), start,
            size(graph) - 1)[v]} ::
        0 <= v < size(graph) ==>
        (match Run(
            view(graph), start,
            size(graph) - 1)[v]
         case Some(d) =>
            is_shortest_dist(
                view(graph), start, v, d)
         case None =>
            forall p: seq<int>
                {:trigger is_path(view(graph), p)} ::
                is_path(view(graph), p) &&
                p[0] == start &&
                p[|p| - 1] == v ==> false)
{
    RunOptimal(
        graph, start, size(graph) - 1);

    var ds := Run(
        view(graph), start, size(graph) - 1);

    assert |ds| == size(graph);

    forall v: int | 0 <= v < size(graph)
        ensures
            match ds[v]
            case Some(d) =>
                is_shortest_dist(
                    view(graph), start, v, d)
            case None =>
                forall p: seq<int>
                    {:trigger is_path(view(graph), p)} ::
                    is_path(view(graph), p) &&
                    p[0] == start &&
                    p[|p| - 1] == v ==> false
    {
        assert VertexOptimal(
            view(graph), start, v,
            size(graph) - 1, ds[v]);

        match ds[v]
        case Some(d) => {
            var wp :|
                Candidate(
                    view(graph), start, v,
                    size(graph) - 1, wp) &&
                path_weight(view(graph), wp) == d;

            assert is_path(view(graph), wp);
            assert wp[0] == start;
            assert wp[|wp| - 1] == v;

            assert exists p: seq<int>
                {:trigger is_path(view(graph), p)} ::
                is_path(view(graph), p) &&
                p[0] == start &&
                p[|p| - 1] == v &&
                path_weight(view(graph), p) == d by {
                assert is_path(view(graph), wp);
            }

            assert forall p: seq<int>
                {:trigger is_path(view(graph), p)} ::
                is_path(view(graph), p) &&
                p[0] == start &&
                p[|p| - 1] == v ==>
                path_weight(view(graph), p) >= d by {
                forall p: seq<int>
                    {:trigger is_path(view(graph), p)}
                    | is_path(view(graph), p) &&
                      p[0] == start &&
                      p[|p| - 1] == v
                    ensures path_weight(view(graph), p) >= d
                {
                    if |p| == 1 {
                        assert p[0] == start;
                        assert p[|p| - 1] == v;
                        assert start == v;
                        assert 0 <= start < size(graph);
                    } else {
                        PathVerticesBound(graph, p);
                    }

                    assert 0 <= p[0] < size(graph);
                    assert 0 <= p[|p| - 1] < size(graph);

                    var q := SimplifyPath(graph, p);
                    assert |q| - 1 <= size(graph) - 1;
                    assert Candidate(
                        view(graph), start, v,
                        size(graph) - 1, q);
                    assert d <= path_weight(view(graph), q);
                    assert path_weight(view(graph), q) <=
                        path_weight(view(graph), p);
                }
            }

            assert is_shortest_dist(
                view(graph), start, v, d);
        }
        case None => {
            assert forall p: seq<int>
                {:trigger is_path(view(graph), p)} ::
                is_path(view(graph), p) &&
                p[0] == start &&
                p[|p| - 1] == v ==> false by {
                forall p: seq<int>
                    {:trigger is_path(view(graph), p)}
                    | is_path(view(graph), p) &&
                      p[0] == start &&
                      p[|p| - 1] == v
                    ensures false
                {
                    if |p| == 1 {
                        assert p[0] == start;
                        assert p[|p| - 1] == v;
                        assert start == v;
                        assert 0 <= start < size(graph);
                    } else {
                        PathVerticesBound(graph, p);
                    }

                    assert 0 <= p[0] < size(graph);
                    assert 0 <= p[|p| - 1] < size(graph);

                    var q := SimplifyPath(graph, p);
                    assert |q| - 1 <= size(graph) - 1;
                    assert Candidate(
                        view(graph), start, v,
                        size(graph) - 1, q);
                    assert false;
                }
            }
        }
    }

    assert forall v: int {:trigger ds[v]} ::
        0 <= v < size(graph) ==>
        (match ds[v]
         case Some(d) =>
            is_shortest_dist(
                view(graph), start, v, d)
         case None =>
            forall p: seq<int>
                {:trigger is_path(view(graph), p)} ::
                is_path(view(graph), p) &&
                p[0] == start &&
                p[|p| - 1] == v ==> false);
}

method bellman_ford(
    graph: WeightedGraph,
    start: int
) returns (res: Option<seq<Option<int>>>)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    requires weights_and_size_bounded(view(graph))
    ensures match res {
        case Some(dists) => 
            |dists| == size(graph) &&
            forall v: int :: 0 <= v < size(graph) ==> (
                match dists[v] {
                    case Some(d) => is_shortest_dist(view(graph), start, v, d)
                    case None => forall p: seq<int> {:trigger is_path(view(graph), p)} :: 
                                    is_path(view(graph), p) && p[0] == start && p[|p| - 1] == v ==> false
                }
            )
        case None => 
            has_negative_cycle(view(graph))
    }
{
    var bad := NegativeSource(graph.adj, 0);
    NegativeSourceSpec(graph, 0);

    match bad
    case Some(s) => {
        assert 0 <= s < size(graph);
        assert match Run(
            view(graph), s, size(graph))[s]
            case Some(d) => d < 0
            case None => false;

        RunOptimal(graph, s, size(graph));
        var ds := Run(
            graph.adj, s, size(graph));

