lemma ExtendLess(s: set<int>, v: int, bound: int)
    requires (forall x: int :: x in s ==> x < bound)
    requires v < bound
    ensures forall x: int :: x in s + {v} ==> x < bound
{
    forall x: int | x in s + {v}
        ensures x < bound
    {
        if x in s {
            assert x < bound;
        } else {
            assert x in {v};
            assert x == v;
        }
    }
}

lemma ExtendGreater(s: set<int>, v: int, bound: int)
    requires (forall x: int :: x in s ==> x > bound)
    requires v > bound
    ensures forall x: int :: x in s + {v} ==> x > bound
{
    forall x: int | x in s + {v}
        ensures x > bound
    {
        if x in s {
            assert x > bound;
        } else {
            assert x in {v};
            assert x == v;
        }
    }
}

method insert(tree: Tree, v: int) returns (res: Tree)
    requires v >= 0
    requires is_bst(tree)
    ensures is_bst(res)
    ensures view(res) == view(tree) + {v}
    decreases tree
{
    match tree
    case Empty =>
        res := Node(v, Empty, Empty);
        assert is_bst(res);
        calc {
            view(res);
            == ({v});
            == view(tree) + {v};
        }

    case Node(root, left, right) =>
        assert is_bst(left);
        assert is_bst(right);
        assert forall x: int :: x in view(left) ==> x < root;
        assert forall x: int :: x in view(right) ==> x > root;

        if v < root {
            var newLeft := insert(left, v);
            ExtendLess(view(left), v, root);
            assert view(newLeft) == view(left) + {v};
            assert forall x: int :: x in view(newLeft) ==> x < root;

            res := Node(root, newLeft, right);
            assert is_bst(res);

            calc {
                view(res);
                == view(newLeft) + view(right) + {root};
                == (view(left) + {v}) + view(right) + {root};
                == (view(left) + view(right) + {root}) + {v};
                == view(tree) + {v};
            }
        } else if v > root {
            var newRight := insert(right, v);
            ExtendGreater(view(right), v, root);
            assert view(newRight) == view(right) + {v};
            assert forall x: int :: x in view(newRight) ==> x > root;

            res := Node(root, left, newRight);
            assert is_bst(res);

            calc {
                view(res);
                == view(left) + view(newRight) + {root};
                == view(left) + (view(right) + {v}) + {root};
                == (view(left) + view(right) + {root}) + {v};
                == view(tree) + {v};
            }
        } else {
            assert v == root;
            res := tree;
            assert root in view(tree);
            assert v in view(tree);
            calc {
                view(res);
                == view(tree);
                == view(tree) + {v};
            }
        }
}

