method zig_zag(g: Tree) returns (res: Tree)
    // g corresponds to Box<Node>, so it is non-Empty
    requires g.Node?
    // g.left is Some (P exists)
    requires g.left.Node?
    // g.left.right is Some (X exists - the 'Zig-Zag' shape)
    requires g.left.right.Node?
    requires is_bst(g)
    ensures is_bst(res)
    ensures view(res) == view(g)
    // X (the original grandchild) is now the root
    ensures res.val == g.left.right.val
{
    var p := g.left;
    var x := p.right;
    var a := p.left;
    var b := x.left;
    var c := x.right;
    var d := g.right;

    assert is_bst(p);
    assert is_bst(x);
    assert view(g) == view(p) + view(d) + {g.val};
    assert view(p) == view(a) + view(x) + {p.val};
    assert view(x) == view(b) + view(c) + {x.val};

    assert forall y :: y in view(x) ==> y > p.val;
    assert forall y :: y in view(x) ==> y < g.val;
    assert x.val in view(x);
    assert p.val < x.val < g.val;

    var newP := Node(p.val, a, b);
    var newG := Node(g.val, c, d);

    assert forall y :: y in view(b) ==> y > p.val;
    assert is_bst(newP);
    assert forall y :: y in view(c) ==> y < g.val;
    assert is_bst(newG);

    assert view(newP) == view(a) + view(b) + {p.val};
    assert view(newG) == view(c) + view(d) + {g.val};
    assert forall y :: y in view(newP) ==> y < x.val;
    assert forall y :: y in view(newG) ==> y > x.val;

    res := Node(x.val, newP, newG);
    assert view(res) == view(newP) + view(newG) + {x.val};
}

