ghost predicate forced(g: Graph, r: int, u: int, same: bool)
  requires 0 <= r < size(g) && 0 <= u < size(g)
{
  forall vc: seq<bool> :: is_valid_coloring(g, vc) ==> (vc[u] == (if same then vc[r] else !vc[r]))
}

ghost predicate edge_ok(g: Graph, c: seq<Option<bool>>, u: int, i: int)
  requires well_formed(g)
  requires |c| == size(g)
  requires 0 <= u < |g.adj| && 0 <= i < |g.adj[u]|
{
  var v := g.adj[u][i];
  (c[u].Some? <==> c[v].Some?) &&
  (c[u].Some? && c[v].Some? ==> c[u].value != c[v].value)
}

ghost predicate partial_valid(g: Graph, c: seq<Option<bool>>) {
  && |c| == size(g)
  && (forall u: int, v: int :: has_edge(g, u, v) ==> 0 <= u < |c| && 0 <= v < |c| && (c[u].Some? <==> c[v].Some?))
  && (forall u: int, v: int :: has_edge(g, u, v) && 0 <= u < |c| && 0 <= v < |c| && c[u].Some? && c[v].Some? ==> c[u].value != c[v].value)
}

ghost predicate component_inv(g: Graph, c0: seq<Option<bool>>, c: seq<Option<bool>>, r: int)
  requires well_formed(g)
{
  && partial_valid(g, c0)
  && 0 <= r < size(g)
  && c0[r].None?
  && |c| == size(g)
  && c[r].Some?
  && (forall u: int :: 0 <= u < size(g) && c0[u].Some? ==> c[u] == c0[u])
  && (forall u: int :: 0 <= u < size(g) && c[u].Some? && c0[u].None? ==> forced(g, r, u, c[u].value))
}

ghost function count_none(c: seq<Option<bool>>): nat
  decreases |c|
{
  if |c| == 0 then 0
  else (if c[|c| - 1].None? then 1 else 0) + count_none(c[..|c| - 1])
}

lemma lemma_count_none_update(c: seq<Option<bool>>, idx: int, b: bool)
  requires 0 <= idx < |c|
  requires c[idx].None?
  ensures count_none(c) >= 1
  ensures count_none(c[idx := Some(b)]) == count_none(c) - 1
  decreases |c|
{
  var c' := c[idx := Some(b)];
  assert |c'| == |c|;
  if idx == |c| - 1 {
    assert c'[..|c'| - 1] == c[..|c| - 1];
  } else {
    assert c'[..|c'| - 1] == c[..|c| - 1][idx := Some(b)];
    lemma_count_none_update(c[..|c| - 1], idx, b);
  }
}

