  requires forced(g, r, v, same)
  requires has_edge(g, u, v)
  ensures forced(g, r, u, !same)
{
  forall vc: seq<bool> | is_valid_coloring(g, vc)
    ensures vc[u] == (if !same then vc[r] else !vc[r])
  {
    assert vc[u] != vc[v];
