lemma lemma_forced_conflict(g: Graph, r: int, u: int, v: int, same: bool)
  requires 0 <= r < size(g) && 0 <= u < size(g) && 0 <= v < size(g)
  requires forced(g, r, u, same)
  requires forced(g, r, v, same)
  requires has_edge(g, u, v)
  ensures !is_bipartite(g)
{
  forall vc: seq<bool>
    ensures !is_valid_coloring(g, vc)
  {
    if is_valid_coloring(g, vc) {
      assert vc[u] == (if same then vc[r] else !vc[r]);
      assert vc[v] == (if same then vc[r] else !vc[r]);
      assert vc[u] != vc[v];
