lemma lemma_component_conflict(g: Graph, c0: seq<Option<bool>>, c: seq<Option<bool>>, r: int, u: int, v: int)
  requires well_formed(g)
  requires component_inv(g, c0, c, r)
  requires 0 <= u < size(g) && 0 <= v < size(g)
  requires has_edge(g, u, v)
  requires c[u].Some? && c[v].Some? && c[u].value == c[v].value
  ensures !is_bipartite(g)
{
  if c0[u].Some? {
    assert c0[v].Some?;
    assert c[u] == c0[u] && c[v] == c0[v];
    assert c0[u].value != c0[v].value;
    assert false;
  }
  assert c0[u].None?;
  if c0[v].Some? {
    assert c0[u].Some?;
    assert false;
  }
  assert c0[v].None?;
  assert forced(g, r, u, c[u].value);
  assert forced(g, r, v, c[v].value);
  lemma_forced_conflict(g, r, u, v, c[u].value);
}

lemma lemma_component_propagate(g: Graph, c0: seq<Option<bool>>, c: seq<Option<bool>>, r: int, target: int, new_color: bool, src: int)
  requires well_formed(g)
  requires component_inv(g, c0, c, r)
  requires 0 <= target < size(g) && 0 <= src < size(g)
  requires c[target].None? && c[src].Some?
  requires new_color == !c[src].value
  requires has_edge(g, src, target) || has_edge(g, target, src)
  ensures component_inv(g, c0, c[target := Some(new_color)], r)
{
  if c0[target].Some? {
    assert c[target] == c0[target];
    assert false;
  }
  assert c0[target].None?;
  if c0[src].Some? {
    if has_edge(g, src, target) {
      assert c0[src].Some? <==> c0[target].Some?;
    } else {
      assert has_edge(g, target, src);
      assert c0[target].Some? <==> c0[src].Some?;
    }
    assert c0[target].Some?;
    assert false;
  }
  assert c0[src].None?;
  assert forced(g, r, src, c[src].value);
  if has_edge(g, src, target) {
    lemma_forced_step_forward(g, r, src, target, c[src].value);
  } else {
    lemma_forced_step_backward(g, r, target, src, c[src].value);
  }
  assert forced(g, r, target, new_color);

  var c' := c[target := Some(new_color)];
  forall u: int | 0 <= u < size(g) && c'[u].Some? && c0[u].None?
    ensures forced(g, r, u, c'[u].value)
  {
    if u == target {
      assert c'[u].value == new_color;
    } else {
      assert c'[u] == c[u];
    }
  }
}

lemma lemma_extract_valid_coloring(g: Graph, c: seq<Option<bool>>, colors: seq<bool>)
  requires well_formed(g)
  requires partial_valid(g, c)
  requires forall k: int :: 0 <= k < size(g) ==> c[k].Some?
  requires |colors| == size(g)
  requires forall k: int :: 0 <= k < size(g) ==> colors[k] == c[k].value
  ensures is_valid_coloring(g, colors)
