lemma zig_bst_lemma(v: int, lv: int, ll: Tree, lr: Tree, r: Tree)
    requires is_bst(Node(v, Node(lv, ll, lr), r))
    ensures is_bst(Node(lv, ll, Node(v, lr, r)))
{
    assert forall x :: x in view(Node(lv, ll, lr)) ==> x < v;
    assert is_bst(Node(lv, ll, lr));
    assert forall x :: x in view(r) ==> x > v;
    assert is_bst(r);

    assert forall x :: x in view(ll) ==> x < lv;
    assert is_bst(ll);
    assert forall x :: x in view(lr) ==> x > lv;
    assert is_bst(lr);

    assert lv in view(Node(lv, ll, lr));
    assert lv < v;

    forall x | x in view(lr)
        ensures x < v
    {
        assert x in view(Node(lv, ll, lr));
    }

    assert forall x :: x in view(lr) ==> x < v;
    assert is_bst(Node(v, lr, r));

    forall x | x in view(Node(v, lr, r))
        ensures x > lv
    {
        assert x in view(lr) || x in view(r) || x == v;

        if x in view(lr) {
            assert x > lv;
        } else if x in view(r) {
            assert x > v;
            assert x > lv;
        } else {
            assert x == v;
            assert x > lv;
        }
    }

    assert forall x :: x in view(Node(v, lr, r)) ==> x > lv;
    assert is_bst(Node(lv, ll, Node(v, lr, r)));
}

