method zig_zag(g: Tree) returns (res: Tree)
    // g corresponds to Box<Node>, so it is non-Empty
    requires g.Node?
    // g.left is Some (P exists)
    requires g.left.Node?
    // g.left.right is Some (X exists - the 'Zig-Zag' shape)
    requires g.left.right.Node?
    requires is_bst(g)
    ensures is_bst(res)
    ensures view(res) == view(g)
    // X (the original grandchild) is now the root
    ensures res.val == g.left.right.val
{
    var p := g.left;
    var x := p.right;

    assert is_bst(p) && is_bst(g.right);
    assert is_bst(p.left) && is_bst(x);
    assert is_bst(x.left) && is_bst(x.right);

    assert view(x) == view(x.left) + view(x.right) + {x.val};
    assert view(p) == view(p.left) + view(x) + {p.val};
    assert view(g) == view(p) + view(g.right) + {g.val};

    assert x.val in view(x);
    assert x.val in view(p);
    assert p.val < x.val;
    assert x.val < g.val;

    var new_left := Node(p.val, p.left, x.left);
    var new_right := Node(g.val, x.right, g.right);
    res := Node(x.val, new_left, new_right);

    assert view(new_left) == view(p.left) + view(x.left) + {p.val};
    assert view(new_right) == view(x.right) + view(g.right) + {g.val};
    assert view(res) == view(new_left) + view(new_right) + {x.val};

    assert forall y :: y in view(x.left) ==> y in view(x) && y > p.val;
    assert is_bst(new_left);

    assert forall y :: y in view(x.right) ==> y in view(x) && y in view(p) && y < g.val;
    assert is_bst(new_right);

    assert forall y :: y in view(p.left) ==> y < p.val && y < x.val;
    assert forall y :: y in view(new_left) ==> y < x.val;

    assert forall y :: y in view(g.right) ==> y > g.val && y > x.val;
    assert forall y :: y in view(new_right) ==> y > x.val;

    assert is_bst(res);
    assert view(res) == view(g);
}

