lemma SwapValid(p: seq<int>, n: int, a: int, b: int)
    requires is_valid_index_permutation(p, n)
    requires 0 <= a < n && 0 <= b < n
    ensures is_valid_index_permutation(p[a := p[b]][b := p[a]], n)
{
    var q := p[a := p[b]][b := p[a]];
    assert |q| == n;
    forall i | 0 <= i < n
        ensures 0 <= q[i] < n
    {
        var fi := if i == b then a else if i == a then b else i;
        assert q[i] == p[fi];
    }
    forall i, j | 0 <= i < j < n
        ensures q[i] != q[j]
    {
        var fi := if i == b then a else if i == a then b else i;
        var fj := if j == b then a else if j == a then b else j;
        assert q[i] == p[fi];
        assert q[j] == p[fj];
        assert fi != fj;
        if fi < fj {
            assert p[fi] != p[fj];
        } else {
            assert p[fj] != p[fi];
        }
    }
}

method bubble_sort(v: seq<int>) returns (v_new: seq<int>)
    ensures is_sorted(v_new)
    ensures is_permutation(v, v_new)
{
    v_new := v;
    var n := |v|;
    ghost var p: seq<int> := seq(n, k => k);
    var i := n;
    while i > 0
        invariant 0 <= i <= n
        invariant |v_new| == n
        invariant is_valid_index_permutation(p, n)
        invariant forall k :: 0 <= k < n ==> v_new[k] == v[p[k]]
        invariant forall a, b :: i <= a < b < n ==> v_new[a] <= v_new[b]
        invariant forall a, b :: 0 <= a < i <= b < n ==> v_new[a] <= v_new[b]
        decreases i
    {
        var j := 0;
        while j < i - 1
            invariant 0 <= j <= i - 1
            invariant |v_new| == n
            invariant is_valid_index_permutation(p, n)
            invariant forall k :: 0 <= k < n ==> v_new[k] == v[p[k]]
            invariant forall a, b :: i <= a < b < n ==> v_new[a] <= v_new[b]
            invariant forall a, b :: 0 <= a < i <= b < n ==> v_new[a] <= v_new[b]
            invariant forall k :: 0 <= k <= j ==> v_new[k] <= v_new[j]
            decreases i - 1 - j
        {
            if v_new[j] > v_new[j+1] {
                var tmp := v_new[j];
                v_new := v_new[j := v_new[j+1]][j+1 := tmp];
                SwapValid(p, n, j, j+1);
                p := p[j := p[j+1]][j+1 := p[j]];
            }
            j := j + 1;
        }
        i := i - 1;
    }
    assert is_valid_index_permutation(p, |v|)
        && |v| == |v_new|
        && (forall k {:trigger p[k]} :: 0 <= k < |v| ==> v_new[k] == v[p[k]]);
}

