lemma ZigZigView(x: int, y: int, z: int, a: Tree, b: Tree, c: Tree, d: Tree)
    ensures
        view(Node(x, a, Node(y, b, Node(z, c, d)))) ==
        view(Node(z, Node(y, Node(x, a, b), c), d))
{
    assert forall q: int ::
        q in view(Node(x, a, Node(y, b, Node(z, c, d)))) <==>
        q in view(Node(z, Node(y, Node(x, a, b), c), d)) by
    {
        forall q: int
            ensures
                q in view(Node(x, a, Node(y, b, Node(z, c, d)))) <==>
                q in view(Node(z, Node(y, Node(x, a, b), c), d))
        {
            assert
                q in view(Node(x, a, Node(y, b, Node(z, c, d)))) <==>
                q in view(a) ||
                q in view(b) ||
                q in view(c) ||
                q in view(d) ||
                q == x ||
                q == y ||
                q == z;

            assert
                q in view(Node(z, Node(y, Node(x, a, b), c), d)) <==>
                q in view(a) ||
                q in view(b) ||
                q in view(c) ||
                q in view(d) ||
                q == x ||
                q == y ||
                q == z;
        }
    }
}

method zig_zig(g: Tree) returns (res: Tree)
    // g corresponds to Box<Node>, so it is non-Empty
    requires g.Node?
    // g.left.is_some()
    requires g.left.Node?
    // g.left.get_Some_0().left.is_some()
    requires g.left.left.Node?
    requires is_bst(g)
    ensures is_bst(res)
    ensures view(res) == view(g)
    // X (grandchild) is now root
    ensures res.val == g.left.left.val
{
    var z := g.val;
    var y := g.left.val;
    var x := g.left.left.val;

    var a := g.left.left.left;
    var b := g.left.left.right;
    var c := g.left.right;
    var d := g.right;

    assert g.left.left == Node(x, a, b);
    assert g.left == Node(y, Node(x, a, b), c);
    assert g == Node(z, Node(y, Node(x, a, b), c), d);

    assert is_bst(g.left);
    assert is_bst(g.left.left);
    assert is_bst(a);
    assert is_bst(b);
    assert is_bst(c);
    assert is_bst(d);

    assert forall q: int :: q in view(g.left) ==> q < z;
    assert forall q: int :: q in view(d) ==> q > z;
    assert forall q: int :: q in view(g.left.left) ==> q < y;
    assert forall q: int :: q in view(c) ==> q > y;
    assert forall q: int :: q in view(a) ==> q < x;
    assert forall q: int :: q in view(b) ==> q > x;

    assert x in view(g.left.left);
    assert y in view(g.left);
    assert x < y;
    assert y < z;

    assert forall q: int :: q in view(c) ==> q < z by {
        forall q: int | q in view(c)
            ensures q < z
        {
            assert q in view(g.left);
        }
    }

    assert forall q: int :: q in view(b) ==> q < y by {
        forall q: int | q in view(b)
            ensures q < y
        {
            assert q in view(g.left.left);
        }
    }

    var zTree := Node(z, c, d);

    assert is_bst(zTree);

    assert forall q: int :: q in view(zTree) ==> q > y by {
        forall q: int | q in view(zTree)
            ensures q > y
        {
            assert q in view(c) || q in view(d) || q == z;
            if q in view(c) {
                assert q > y;
            } else if q in view(d) {
                assert q > z;
                assert z > y;
            } else {
                assert q == z;
                assert z > y;
            }
        }
    }

    var yTree := Node(y, b, zTree);

    assert is_bst(yTree);

    assert forall q: int :: q in view(yTree) ==> q > x by {
        forall q: int | q in view(yTree)
            ensures q > x
        {
            assert q in view(b) || q in view(zTree) || q == y;
            if q in view(b) {
                assert q > x;
            } else if q in view(zTree) {
                assert q > y;
                assert y > x;
            } else {
                assert q == y;
                assert y > x;
            }
        }
    }

    res := Node(x, a, yTree);

    assert is_bst(res);

    ZigZigView(x, y, z, a, b, c, d);
    assert view(res) == view(g);
}

