lemma zig_zag_view_lemma(
    gv: int, pv: int, xv: int,
    a: Tree, b: Tree, c: Tree, d: Tree)
    ensures
        view(Node(xv, Node(pv, a, b), Node(gv, c, d))) ==
        view(Node(gv, Node(pv, a, Node(xv, b, c)), d))
{
    var rotated := Node(xv, Node(pv, a, b), Node(gv, c, d));
    var original := Node(gv, Node(pv, a, Node(xv, b, c)), d);

    forall y | y in view(original)
        ensures y in view(rotated)
    {
        assert
            y in view(Node(pv, a, Node(xv, b, c))) ||
            y in view(d) ||
            y == gv;

        if y == gv {
            assert y in view(Node(gv, c, d));
            assert y in view(rotated);
        } else if y in view(d) {
            assert y in view(Node(gv, c, d));
            assert y in view(rotated);
        } else {
            assert y in view(Node(pv, a, Node(xv, b, c)));
            assert
                y in view(a) ||
                y in view(Node(xv, b, c)) ||
                y == pv;

            if y == pv {
                assert y in view(Node(pv, a, b));
                assert y in view(rotated);
            } else if y in view(a) {
                assert y in view(Node(pv, a, b));
                assert y in view(rotated);
            } else {
                assert y in view(Node(xv, b, c));
                assert
                    y in view(b) ||
                    y in view(c) ||
                    y == xv;

                if y == xv {
                    assert y in view(rotated);
                } else if y in view(b) {
                    assert y in view(Node(pv, a, b));
                    assert y in view(rotated);
                } else {
                    assert y in view(c);
                    assert y in view(Node(gv, c, d));
                    assert y in view(rotated);
                }
            }
        }
    }

    forall y | y in view(rotated)
        ensures y in view(original)
    {
        assert
            y in view(Node(pv, a, b)) ||
            y in view(Node(gv, c, d)) ||
            y == xv;

        if y == xv {
            assert y in view(Node(xv, b, c));
            assert y in view(Node(pv, a, Node(xv, b, c)));
            assert y in view(original);
        } else if y in view(Node(pv, a, b)) {
            assert
                y in view(a) ||
                y in view(b) ||
                y == pv;

            if y == pv {
                assert y in view(Node(pv, a, Node(xv, b, c)));
                assert y in view(original);
            } else if y in view(a) {
                assert y in view(Node(pv, a, Node(xv, b, c)));
                assert y in view(original);
            } else {
                assert y in view(b);
                assert y in view(Node(xv, b, c));
                assert y in view(Node(pv, a, Node(xv, b, c)));
                assert y in view(original);
            }
        } else {
            assert y in view(Node(gv, c, d));
            assert
                y in view(c) ||
                y in view(d) ||
                y == gv;

            if y == gv {
                assert y in view(original);
            } else if y in view(d) {
                assert y in view(original);
            } else {
                assert y in view(c);
                assert y in view(Node(xv, b, c));
                assert y in view(Node(pv, a, Node(xv, b, c)));
                assert y in view(original);
            }
        }
    }

    assert view(original) <= view(rotated);
    assert view(rotated) <= view(original);
    assert view(rotated) == view(original);
}

method zig_zag(g: Tree) returns (res: Tree)
    // g corresponds to Box<Node>, so it is non-Empty
    requires g.Node?
    // g.left is Some (P exists)
    requires g.left.Node?
    // g.left.right is Some (X exists - the 'Zig-Zag' shape)
    requires g.left.right.Node?
    requires is_bst(g)
    ensures is_bst(res)
    ensures view(res) == view(g)
    // X (the original grandchild) is now the root
    ensures res.val == g.left.right.val
{
    var p := g.left;
    var x := p.right;
    var a := p.left;
    var b := x.left;
    var c := x.right;
    var d := g.right;

    assert g == Node(g.val, p, d);
    assert p == Node(p.val, a, x);
    assert x == Node(x.val, b, c);

    assert is_bst(p);
    assert is_bst(d);
    assert forall y :: y in view(p) ==> y < g.val;
    assert forall y :: y in view(d) ==> y > g.val;

    assert is_bst(a);
    assert is_bst(x);
    assert forall y :: y in view(a) ==> y < p.val;
    assert forall y :: y in view(x) ==> y > p.val;

    assert is_bst(b);
    assert is_bst(c);
    assert forall y :: y in view(b) ==> y < x.val;
    assert forall y :: y in view(c) ==> y > x.val;

    assert x.val in view(x);
    assert x.val in view(p);
    assert p.val < x.val;
    assert x.val < g.val;

    forall y | y in view(b)
        ensures y > p.val
    {
        assert y in view(x);
    }

    forall y | y in view(c)
        ensures y < g.val
    {
        assert y in view(x);
        assert y in view(p);
    }

    var newLeft := Node(p.val, a, b);
    var newRight := Node(g.val, c, d);

    node_is_bst(p.val, a, b);
    assert is_bst(newLeft);

    node_is_bst(g.val, c, d);
    assert is_bst(newRight);

    forall y | y in view(newLeft)
        ensures y < x.val
    {
        if y in view(a) {
            assert y < p.val;
        } else if y in view(b) {
            assert y < x.val;
        } else {
            assert y == p.val;
        }
    }

    forall y | y in view(newRight)
        ensures y > x.val
    {
        if y in view(c) {
            assert y > x.val;
        } else if y in view(d) {
            assert y > g.val;
        } else {
            assert y == g.val;
        }
    }

    node_is_bst(x.val, newLeft, newRight);
    res := Node(x.val, newLeft, newRight);

    zig_zag_view_lemma(g.val, p.val, x.val, a, b, c, d);
}
