function change_opt(coins: seq<int>, amount: int): int
    decreases amount, |coins|
{
    if amount < 0 then
        -1
    else if amount == 0 then
        0
    else if |coins| == 0 then
        -1
    else if coins[0] <= 0 then
        change_opt(coins[1..], amount)
    else if coins[0] > amount then
        change_opt(coins[1..], amount)
    else
        var skip := change_opt(coins[1..], amount);
        var previous := change_opt(coins, amount - coins[0]);
        var take := if previous == -1 then -1 else previous + 1;
        choose_best(skip, take)
}

lemma change_opt_correct(coins: seq<int>, amount: int)
    requires amount >= 0
    requires positive_coins(coins)
    ensures change_opt(coins, amount) >= -1
    ensures change_opt(coins, amount) != -1 ==>
        change_opt(coins, amount) >= 0
    ensures change_opt(coins, amount) != -1 ==>
        exists counts: seq<int> ::
            is_valid_change(counts, coins, amount) &&
            total_coins(counts) == change_opt(coins, amount)
    ensures change_opt(coins, amount) != -1 ==>
        forall counts: seq<int> ::
            is_valid_change(counts, coins, amount) ==>
            total_coins(counts) >= change_opt(coins, amount)
    ensures change_opt(coins, amount) == -1 ==>
        forall counts: seq<int> ::
            is_valid_change(counts, coins, amount) ==> false
    decreases amount, |coins|
{
    if amount == 0 {
        zero_counts_properties(coins);
        assert is_valid_change(zero_counts(coins), coins, 0);
        assert total_coins(zero_counts(coins)) == 0;
        assert exists counts: seq<int> ::
            is_valid_change(counts, coins, 0) &&
            total_coins(counts) == 0;

        forall counts: seq<int> | is_valid_change(counts, coins, 0)
            ensures total_coins(counts) >= 0
        {
            nonnegative_total_coins(counts);
        }
    } else if |coins| == 0 {
        assert change_opt(coins, amount) == -1;

        forall counts: seq<int> | is_valid_change(counts, coins, amount)
            ensures false
        {
            assert |counts| == 0;
            assert counts == [];
            assert coins == [];
            assert total_amount(counts, coins) == 0;
            assert total_amount(counts, coins) == amount;
            assert amount > 0;
            assert false;
        }
    } else {
        assert coins[0] > 0;
        positive_tail(coins);
        change_opt_correct(coins[1..], amount);

        var skip := change_opt(coins[1..], amount);

        if coins[0] > amount {
            assert change_opt(coins, amount) == skip;

            if skip != -1 {
                var tail_counts :|
                    is_valid_change(tail_counts, coins[1..], amount) &&
                    total_coins(tail_counts) == skip;

                lift_zero_count(tail_counts, coins, amount);
                assert is_valid_change([0] + tail_counts, coins, amount);
                assert total_coins([0] + tail_counts) == skip;

                assert exists counts: seq<int> ::
                    is_valid_change(counts, coins, amount) &&
                    total_coins(counts) == skip;

                forall counts: seq<int> |
                    is_valid_change(counts, coins, amount)
                    ensures total_coins(counts) >= skip
                {
                    first_count_zero_if_too_large(
                        counts, coins, amount);
                    drop_zero_count(counts, coins, amount);

                    assert is_valid_change(
                        counts[1..], coins[1..], amount);
                    assert total_coins(counts)
                        == total_coins(counts[1..]);
                    assert total_coins(counts[1..]) >= skip;
                }
            } else {
                forall counts: seq<int> |
                    is_valid_change(counts, coins, amount)
                    ensures false
                {
                    first_count_zero_if_too_large(
                        counts, coins, amount);
                    drop_zero_count(counts, coins, amount);

                    assert is_valid_change(
                        counts[1..], coins[1..], amount);
                    assert false;
                }
            }
        } else {
            assert coins[0] <= amount;
            var remainder := amount - coins[0];
            assert remainder >= 0;
            assert remainder < amount;

            change_opt_correct(coins, remainder);
            var previous := change_opt(coins, remainder);
            var take := if previous == -1 then -1 else previous + 1;

            assert skip >= -1;
            assert previous >= -1;
            assert take >= -1;

            choose_best_properties(skip, take);

            var optimum := change_opt(coins, amount);
            assert optimum == choose_best(skip, take);
            assert optimum >= -1;

            if optimum != -1 {
                assert optimum >= 0;

                if optimum == skip {
                    assert skip != -1;

                    var tail_counts :|
                        is_valid_change(
                            tail_counts, coins[1..], amount) &&
                        total_coins(tail_counts) == skip;

                    lift_zero_count(tail_counts, coins, amount);
                    assert is_valid_change(
                        [0] + tail_counts, coins, amount);
                    assert total_coins([0] + tail_counts) == optimum;

                    assert exists counts: seq<int> ::
                        is_valid_change(counts, coins, amount) &&
                        total_coins(counts) == optimum;
                } else {
                    assert optimum == take;
                    assert take != -1;
                    assert previous != -1;
                    assert take == previous + 1;

                    var previous_counts :|
                        is_valid_change(
                            previous_counts, coins, remainder) &&
                        total_coins(previous_counts) == previous;

                    lift_one_count(previous_counts, coins, remainder);

                    assert remainder + coins[0] == amount;
                    assert is_valid_change(
                        [previous_counts[0] + 1]
                            + previous_counts[1..],
                        coins,
                        amount);
                    assert total_coins(
                        [previous_counts[0] + 1]
                            + previous_counts[1..]) == optimum;

                    assert exists counts: seq<int> ::
                        is_valid_change(counts, coins, amount) &&
                        total_coins(counts) == optimum;
                }

                forall counts: seq<int> |
                    is_valid_change(counts, coins, amount)
                    ensures total_coins(counts) >= optimum
                {
                    assert |counts| == |coins|;
                    assert |counts| > 0;
                    assert counts[0] >= 0;

                    if counts[0] == 0 {
                        drop_zero_count(counts, coins, amount);

                        assert is_valid_change(
                            counts[1..], coins[1..], amount);
                        assert skip != -1;
                        assert total_coins(counts[1..]) >= skip;
                        assert optimum <= skip;
                        assert total_coins(counts)
                            == total_coins(counts[1..]);
                    } else {
                        assert counts[0] > 0;
                        drop_one_count(counts, coins, amount);

                        var reduced :=
                            [counts[0] - 1] + counts[1..];

                        assert is_valid_change(
                            reduced, coins, remainder);
                        assert previous != -1;
                        assert take == previous + 1;
                        assert total_coins(reduced) >= previous;
                        assert optimum <= take;
                        assert total_coins(counts)
                            == total_coins(reduced) + 1;
                    }
                }
            } else {
                assert skip == -1;
                assert take == -1;

                if previous != -1 {
                    assert previous >= 0;
                    assert take == previous + 1;
                    assert take > 0;
                    assert false;
                }
                assert previous == -1;

                forall counts: seq<int> |
                    is_valid_change(counts, coins, amount)
                    ensures false
                {
                    assert |counts| == |coins|;
                    assert |counts| > 0;
                    assert counts[0] >= 0;

                    if counts[0] == 0 {
                        drop_zero_count(counts, coins, amount);
                        assert is_valid_change(
                            counts[1..], coins[1..], amount);
                        assert false;
                    } else {
                        assert counts[0] > 0;
                        drop_one_count(counts, coins, amount);

                        assert is_valid_change(
                            [counts[0] - 1] + counts[1..],
                            coins,
                            remainder);
                        assert false;
                    }
                }
            }
        }
    }
}

