    invariant forall v, i :: v in rank && 0 <= i < |graph.adj[v]| ==> graph.adj[v][i] in rank && rank[graph.adj[v][i]] < rank[v]
    decreases |remaining|
  {
    var v :| 0 <= v < n && v in remaining && forall i :: 0 <= i < |graph.adj[v]| ==> graph.adj[v][i] !in remaining;
    rank := rank[v := cnt];
    cnt := cnt + 1;
    remaining := remaining - {v};
  }
  if remaining == {} {
    forall p | is_cycle(graph, p) ensures false {
      assert has_edge(graph, p[0], p[1]);
      assert 0 <= p[0] < n;
      assert p[0] in rank;
      RankDecreases(graph, rank, p);
    }
    return false;
  } else {
    forall v | v in remaining ensures exists i :: 0 <= i < |graph.adj[v]| && graph.adj[v][i] in remaining {
      assert 0 <= v < n;
    }
    FindCycle(graph, remaining);
    return true;
  }
}

