lemma FromGood(coins: seq<int>, a: int, dp: seq<int>, wit: seq<seq<int>>)
    requires |dp| == a && |wit| == a
    requires forall b :: 0 <= b < a ==> Good(coins, b, dp[b], wit[b])
    ensures forall b :: 0 <= b < a ==> dp[b] != -1 ==> LowerBound(coins, b, dp[b])
    ensures forall b :: 0 <= b < a ==> dp[b] == -1 ==> Impossible(coins, b)
{
    forall b | 0 <= b < a
        ensures dp[b] != -1 ==> LowerBound(coins, b, dp[b])
        ensures dp[b] == -1 ==> Impossible(coins, b)
    {
        GoodPost(coins, b, dp[b], wit[b]);
    }
}

lemma AllZero(s: seq<int>, coins: seq<int>)
    requires |s| == |coins|
    requires forall i :: 0 <= i < |s| ==> s[i] == 0
    ensures total_amount(s, coins) == 0 && total_coins(s) == 0
    decreases |s|
{
    if |s| > 0 {
        AllZero(s[1..], coins[1..]);
    }
}

lemma NonnegCoins(s: seq<int>)
    requires forall i :: 0 <= i < |s| ==> s[i] >= 0
    ensures total_coins(s) >= 0
    decreases |s|
{
    if |s| > 0 {
        NonnegCoins(s[1..]);
    }
}

lemma NonnegAmount(s: seq<int>, coins: seq<int>)
    requires |s| == |coins|
    requires forall i :: 0 <= i < |s| ==> s[i] >= 0
    requires forall i :: 0 <= i < |coins| ==> coins[i] > 0
    ensures total_amount(s, coins) >= 0
    decreases |s|
{
    if |s| > 0 {
        assert s[0] * coins[0] >= 0;
        NonnegAmount(s[1..], coins[1..]);
    }
}

lemma UpdateLemma(s: seq<int>, coins: seq<int>, i: int, d: int)
    requires |s| == |coins| && 0 <= i < |s|
    ensures total_amount(s[i := s[i] + d], coins) == total_amount(s, coins) + d * coins[i]
    ensures total_coins(s[i := s[i] + d]) == total_coins(s) + d
    decreases |s|
{
    var t := s[i := s[i] + d];
    if i == 0 {
        assert t[1..] == s[1..];
        assert t[0] == s[0] + d;
        assert (s[0] + d) * coins[0] == s[0] * coins[0] + d * coins[0];
        assert t[0] * coins[0] == s[0] * coins[0] + d * coins[0];
    } else {
        assert t[1..] == s[1..][i-1 := s[1..][i-1] + d];
        UpdateLemma(s[1..], coins[1..], i-1, d);
        assert coins[1..][i-1] == coins[i];
    }
}

lemma StepLemma(coins: seq<int>, a: int, dp: seq<int>, best: int)
    requires a >= 1
    requires |dp| == a
    requires forall i: int :: 0 <= i < |coins| ==> coins[i] > 0
    requires forall b :: 0 <= b < a ==> dp[b] != -1 ==> LowerBound(coins, b, dp[b])
    requires forall b :: 0 <= b < a ==> dp[b] == -1 ==> Impossible(coins, b)
    requires forall j :: 0 <= j < |coins| ==> coins[j] <= a && dp[a - coins[j]] != -1 ==> best != -1 && best <= dp[a - coins[j]] + 1
    ensures best == -1 ==> Impossible(coins, a)
    ensures best != -1 ==> LowerBound(coins, a, best)
{
    forall counts | is_valid_change(counts, coins, a)
        ensures best != -1 && total_coins(counts) >= best
    {
        if forall k :: 0 <= k < |counts| ==> counts[k] == 0 {
            AllZero(counts, coins);
            assert false;
        }
        assert exists k :: 0 <= k < |counts| && counts[k] != 0;
        var k :| 0 <= k < |counts| && counts[k] != 0;
        assert counts[k] > 0;
        var c := coins[k];
        var cs := counts[k := counts[k] + (-1)];
        UpdateLemma(counts, coins, k, -1);
        assert forall j :: 0 <= j < |cs| ==> cs[j] >= 0;
        NonnegAmount(cs, coins);
        assert total_amount(cs, coins) == a - c;
        assert 0 <= a - c < a;
        assert is_valid_change(cs, coins, a - c);
        if dp[a - c] == -1 {
            assert Impossible(coins, a - c);
            assert false;
        } else {
            assert LowerBound(coins, a - c, dp[a - c]);
            assert total_coins(cs) >= dp[a - c];
            assert coins[k] <= a && dp[a - coins[k]] != -1;
        }
    }
}

method ComputeBest(coins: seq<int>, a: int, dp: seq<int>, ghost wit: seq<seq<int>>) returns (best: int, ghost bw: seq<int>)
    requires a >= 1 && |dp| == a && |wit| == a
    requires forall i: int :: 0 <= i < |coins| ==> coins[i] > 0
    requires forall b :: 0 <= b < a ==> Good(coins, b, dp[b], wit[b])
    ensures best != -1 ==> is_valid_change(bw, coins, a) && total_coins(bw) == best
    ensures forall j :: 0 <= j < |coins| ==> coins[j] <= a && dp[a - coins[j]] != -1 ==> best != -1 && best <= dp[a - coins[j]] + 1
{
    best := -1;
    bw := [];
    var i := 0;
    while i < |coins|
        invariant 0 <= i <= |coins|
        invariant best == -1 || best >= 1
        invariant best != -1 ==> is_valid_change(bw, coins, a) && total_coins(bw) == best
        invariant forall j :: 0 <= j < i ==> coins[j] <= a && dp[a - coins[j]] != -1 ==> best != -1 && best <= dp[a - coins[j]] + 1
    {
        var c := coins[i];
        ghost var ob := best;
        if c <= a && dp[a - c] != -1 {
            GoodValid(coins, a - c, dp[a - c], wit[a - c]);
            NonnegCoins(wit[a - c]);
            assert dp[a - c] >= 0;
            var cand := dp[a - c] + 1;
            assert cand >= 1;
            if best == -1 || cand < best {
                UpdateLemma(wit[a - c], coins, i, 1);
                best := cand;
                bw := wit[a - c][i := wit[a - c][i] + 1];
                assert is_valid_change(bw, coins, a);
            }
        }
        assert ob != -1 ==> best != -1 && best <= ob;
        assert c <= a && dp[a - c] != -1 ==> best != -1 && best <= dp[a - c] + 1;
        forall j | 0 <= j < i + 1 && coins[j] <= a && dp[a - coins[j]] != -1
            ensures best != -1 && best <= dp[a - coins[j]] + 1
        {
            if j < i {
                assert ob != -1 && ob <= dp[a - coins[j]] + 1;
            } else {
                assert j == i;
                assert coins[j] == c;
            }
        }
        i := i + 1;
    }
}

method coin_change(coins: seq<int>, amount: int) returns (min_coins: int)
    requires |coins| > 0
    requires |coins| <= 100
    requires amount <= 10000
    // Coins must be positive
    requires forall i: int :: 0 <= i < |coins| ==> coins[i] > 0
    requires forall i: int :: 0 <= i < |coins| ==> coins[i] <= 10000
    ensures
        // Case 1: Solution exists
        min_coins != -1 ==> (
            // Existence
            (exists counts: seq<int> :: is_valid_change(counts, coins, amount) && total_coins(counts) == min_coins)
            &&
            // Lower Bound (Optimality)
            (forall counts: seq<int> :: is_valid_change(counts, coins, amount) ==> total_coins(counts) >= min_coins)
        )
    ensures
        // Case 2: Impossible
        min_coins == -1 ==> (
            forall counts: seq<int> :: is_valid_change(counts, coins, amount) ==> false
        )
{
    if amount < 0 {
        forall counts | is_valid_change(counts, coins, amount)
            ensures false
        {
            NonnegAmount(counts, coins);
        }
        return -1;
    }

    var dp: seq<int> := [0];
    ghost var w0: seq<int> := seq(|coins|, _ => 0);
    AllZero(w0, coins);
    assert is_valid_change(w0, coins, 0);
    forall counts | is_valid_change(counts, coins, 0)
        ensures total_coins(counts) >= 0
    {
        NonnegCoins(counts);
    }
    assert LowerBound(coins, 0, 0);
    MakeGood(coins, 0, 0, w0);
    ghost var wit: seq<seq<int>> := [w0];

    var a := 1;
    while a <= amount
        invariant 1 <= a <= amount + 1
        invariant |dp| == a && |wit| == a
        invariant forall b :: 0 <= b < a ==> Good(coins, b, dp[b], wit[b])
    {
        var best;
        ghost var bw;
        best, bw := ComputeBest(coins, a, dp, wit);
        FromGood(coins, a, dp, wit);
        StepLemma(coins, a, dp, best);
        MakeGood(coins, a, best, bw);
        var dp' := dp + [best];
        ghost var wit' := wit + [bw];
        assert forall b :: 0 <= b < a + 1 ==> Good(coins, b, dp'[b], wit'[b]) by {
            forall b | 0 <= b < a + 1
                ensures Good(coins, b, dp'[b], wit'[b])
            {
                if b < a {
                    assert dp'[b] == dp[b] && wit'[b] == wit[b];
                } else {
                    assert dp'[b] == best && wit'[b] == bw;
                }
            }
        }
        dp := dp';
        wit := wit';
        a := a + 1;
    }

    min_coins := dp[amount];
    GoodPost(coins, amount, dp[amount], wit[amount]);
    if min_coins != -1 {
        assert is_valid_change(wit[amount], coins, amount) && total_coins(wit[amount]) == min_coins;
        assert LowerBound(coins, amount, min_coins);
    } else {
        assert Impossible(coins, amount);
    }
}

