ghost predicate closed(g: Graph, S: set<int>) {
  forall u: int, j: int ::
    u in S && 0 <= u < |g.adj| && 0 <= j < |g.adj[u]| ==> g.adj[u][j] in S
}

lemma RangeCard(n: int)
  requires n >= 0
  ensures |set x: int | 0 <= x < n| == n
  decreases n
{
  if n > 0 {
    RangeCard(n - 1);
    assert (set x: int | 0 <= x < n) == (set x: int | 0 <= x < n - 1) + {n - 1};
  }
}

lemma SubsetCard(a: set<int>, b: set<int>)
  requires a <= b
  ensures |a| <= |b|
{
  assert b == a + (b - a);
  assert a !! (b - a);
}

lemma ReachStep(g: Graph, s: int, u: int, v: int)
  requires reachable(g, s, u)
  requires has_edge(g, u, v)
  ensures reachable(g, s, v)
{
  var p :| is_path(g, p) && p[0] == s && p[|p| - 1] == u;
  var q := p + [v];
  forall i | 0 <= i < |q| - 1
    ensures has_edge(g, q[i], q[i+1])
  {
    if i < |p| - 1 {
      assert q[i] == p[i] && q[i+1] == p[i+1];
      assert has_edge(g, p[i], p[i+1]);
    } else {
      assert q[i] == u && q[i+1] == v;
    }
  }
  assert is_path(g, q);
  assert q[0] == s && q[|q| - 1] == v;
}

lemma PathInClosed(g: Graph, S: set<int>, p: seq<int>)
  requires is_path(g, p)
  requires p[0] in S
  requires closed(g, S)
  ensures p[|p| - 1] in S
  decreases |p|
{
  if |p| > 1 {
    var q := p[..|p| - 1];
    forall i | 0 <= i < |q| - 1
      ensures has_edge(g, q[i], q[i+1])
    {
      assert q[i] == p[i] && q[i+1] == p[i+1];
      assert has_edge(g, p[i], p[i+1]);
    }
    assert is_path(g, q);
    assert q[0] == p[0];
    PathInClosed(g, S, q);
    assert q[|q| - 1] == p[|p| - 2];
    assert has_edge(g, p[|p| - 2], p[|p| - 1]);
    var j :| 0 <= p[|p| - 2] < |g.adj| && 0 <= j < |g.adj[p[|p| - 2]]| && g.adj[p[|p| - 2]][j] == p[|p| - 1];
  }
}

method dfs_check_reachability(graph: Graph, start: int, target: int) returns (res: bool)
  requires well_formed(graph)
  requires 0 <= start < size(graph)
  requires 0 <= target < size(graph)
  ensures res == reachable(graph, start, target)
{
  var n := |graph.adj|;
  var visited: set<int> := {start};
  var stack: seq<int> := [start];
  ghost var all := set x: int | 0 <= x < n;
  RangeCard(n);
  assert is_path(graph, [start]);
  assert reachable(graph, start, start);
  while |stack| > 0
    invariant |all| == n
    invariant all == set x: int | 0 <= x < n
    invariant visited <= all
    invariant |visited| <= n
    invariant forall x :: x in visited ==> 0 <= x < n
    invariant start in visited
    invariant forall x :: x in stack ==> x in visited
    invariant forall x :: x in visited ==> reachable(graph, start, x)
    invariant forall w :: w in visited && w !in stack ==>
      forall j :: 0 <= j < |graph.adj[w]| ==> graph.adj[w][j] in visited
    decreases n - |visited|, |stack|
  {
    ghost var stack0 := stack;
    ghost var visited0 := visited;
    var u := stack[|stack| - 1];
    assert u in stack0;
    assert u in visited;
    stack := stack[..|stack| - 1];
    assert stack0 == stack + [u];
    ghost var rest := stack;
    var i := 0;
    while i < |graph.adj[u]|
      invariant 0 <= i <= |graph.adj[u]|
      invariant visited0 <= visited
      invariant visited <= all
      invariant forall x :: x in visited ==> 0 <= x < n
      invariant u in visited
      invariant start in visited
      invariant forall x :: x in stack ==> x in visited
      invariant forall x :: x in visited ==> reachable(graph, start, x)
      invariant forall w :: w in visited && w !in stack && w != u ==>
        forall j :: 0 <= j < |graph.adj[w]| ==> graph.adj[w][j] in visited
      invariant forall j :: 0 <= j < i ==> graph.adj[u][j] in visited
      invariant |visited| >= |visited0|
      invariant |visited| == |visited0| ==> stack == rest
    {
      var v := graph.adj[u][i];
      if v !in visited {
        assert has_edge(graph, u, v);
        ReachStep(graph, start, u, v);
        assert v in all;
        assert |visited + {v}| == |visited| + 1;
        visited := visited + {v};
        stack := stack + [v];
      }
      i := i + 1;
    }
    SubsetCard(visited, all);
  }
  assert closed(graph, visited);
  res := target in visited;
  if !res {
    if reachable(graph, start, target) {
      var p :| is_path(graph, p) && p[0] == start && p[|p| - 1] == target;
      PathInClosed(graph, visited, p);
      assert false;
    }
  }
}

