ghost predicate HasSucc(g: Graph, rem: set<int>, u: int) {
  0 <= u < |g.adj| && exists i :: 0 <= i < |g.adj[u]| && g.adj[u][i] in rem
}

lemma RankDecreases(g: Graph, rank: map<int,int>, p: seq<int>)
  requires is_path(g, p) && |p| > 1
  requires p[0] in rank
  requires forall v, i :: v in rank && 0 <= v < |g.adj| && 0 <= i < |g.adj[v]| ==> g.adj[v][i] in rank && rank[g.adj[v][i]] < rank[v]
  ensures p[|p|-1] in rank && rank[p[|p|-1]] < rank[p[0]]
  decreases |p|
{
  assert has_edge(g, p[0], p[1]);
  assert 0 <= p[0] < |g.adj|;
  var i :| 0 <= i < |g.adj[p[0]]| && g.adj[p[0]][i] == p[1];
  assert p[1] in rank && rank[p[1]] < rank[p[0]];
  if |p| > 2 {
    var q := p[1..];
    forall k | 0 <= k < |q| - 1 ensures has_edge(g, q[k], q[k+1]) {
      assert q[k] == p[k+1];
      assert q[k+1] == p[k+2];
    }
    assert is_path(g, q);
    RankDecreases(g, rank, q);
    assert q[|q|-1] == p[|p|-1];
  }
}

lemma FindCycle(g: Graph, R: set<int>)
  requires well_formed(g)
  requires R != {}
  requires forall v :: v in R ==> 0 <= v < |g.adj|
  requires forall v :: v in R ==> HasSucc(g, R, v)
  ensures graph_has_cycle(g)
{
  var start :| start in R;
  var walk := [start];
  var unvisited := R - {start};
  while true
    invariant |walk| > 0
    invariant is_path(g, walk)
    invariant forall k :: 0 <= k < |walk| ==> walk[k] in R
    invariant forall x :: x in R && x !in unvisited ==> x in walk
    invariant unvisited <= R
    decreases |unvisited|
  {
    var u := walk[|walk|-1];
    assert u in R;
    assert HasSucc(g, R, u);
    var i :| 0 <= i < |g.adj[u]| && g.adj[u][i] in R;
    var w := g.adj[u][i];
    assert has_edge(g, u, w);
    if w !in unvisited {
      assert w in walk;
      var j :| 0 <= j < |walk| && walk[j] == w;
      var c := walk[j..] + [w];
      forall k | 0 <= k < |c| - 1 ensures has_edge(g, c[k], c[k+1]) {
        if k < |c| - 2 {
          assert c[k] == walk[j+k] && c[k+1] == walk[j+k+1];
        } else {
          assert c[k] == u && c[k+1] == w;
        }
      }
      assert is_path(g, c);
      assert c[0] == w && c[|c|-1] == w;
      assert is_cycle(g, c);
      return;
    }
    var walk' := walk + [w];
    forall k | 0 <= k < |walk'| - 1 ensures has_edge(g, walk'[k], walk'[k+1]) {
      if k < |walk| - 1 {
        assert walk'[k] == walk[k] && walk'[k+1] == walk[k+1];
      } else {
        assert walk'[k] == u && walk'[k+1] == w;
      }
    }
    walk := walk';
    unvisited := unvisited - {w};
  }
}

method FindSink(g: Graph, remaining: set<int>) returns (found: bool, v: int)
  ensures found ==> 0 <= v < |g.adj| && v in remaining && forall i :: 0 <= i < |g.adj[v]| ==> g.adj[v][i] !in remaining
  ensures !found ==> forall u :: 0 <= u < |g.adj| && u in remaining ==> HasSucc(g, remaining, u)
{
  var u := 0;
  while u < |g.adj|
    invariant 0 <= u <= |g.adj|
    invariant forall w :: 0 <= w < u && w in remaining ==> HasSucc(g, remaining, w)
  {
    if u in remaining {
      var j := 0;
      while j < |g.adj[u]| && g.adj[u][j] !in remaining
        invariant 0 <= j <= |g.adj[u]|
        invariant forall i :: 0 <= i < j ==> g.adj[u][i] !in remaining
      {
        j := j + 1;
      }
      if j == |g.adj[u]| {
        return true, u;
      }
      assert g.adj[u][j] in remaining;
      assert HasSucc(g, remaining, u);
    }
    u := u + 1;
  }
  return false, 0;
}

method has_cycle(graph: Graph) returns (res: bool)
  requires well_formed(graph)
  ensures res == graph_has_cycle(graph)
{
  var n := |graph.adj|;
  var remaining: set<int> := set v | 0 <= v < n;
  var rank: map<int,int> := map[];
  var cnt := 0;
  var found, v := FindSink(graph, remaining);
  while found
    invariant n == |graph.adj|
    invariant forall v :: v in remaining ==> 0 <= v < n
    invariant forall v :: v in rank <==> (0 <= v < n && v !in remaining)
    invariant forall v :: v in rank ==> rank[v] < cnt
    invariant forall v, i :: v in rank && 0 <= v < |graph.adj| && 0 <= i < |graph.adj[v]| ==> graph.adj[v][i] in rank && rank[graph.adj[v][i]] < rank[v]
    invariant found ==> 0 <= v < n && v in remaining && forall i :: 0 <= i < |graph.adj[v]| ==> graph.adj[v][i] !in remaining
    invariant !found ==> forall u :: 0 <= u < n && u in remaining ==> HasSucc(graph, remaining, u)
    decreases |remaining|
  {
    rank := rank[v := cnt];
    cnt := cnt + 1;
    remaining := remaining - {v};
    found, v := FindSink(graph, remaining);
  }
  if remaining == {} {
    forall p | is_cycle(graph, p) ensures false {
      assert has_edge(graph, p[0], p[1]);
      assert 0 <= p[0] < n;
      assert p[0] in rank;
      RankDecreases(graph, rank, p);
    }
    return false;
  } else {
    forall u | u in remaining ensures HasSucc(graph, remaining, u) {
      assert 0 <= u < n;
    }
    FindCycle(graph, remaining);
    return true;
  }
}

response:
The errors came from the nested `exists i :: ... g.adj[u][i] in remaining` inside a `forall`, which Dafny struggled to carry between `FindSink` and `has_cycle`. I wrapped that condition in a named predicate, `HasSucc`, and used it in the invariants, postconditions and `FindCycle`'s precondition. I added an explicit `assert HasSucc(...)` where the witness is found. The remaining warning on the set comprehension is only a trigger warning, not an error.

