lemma PathVerticesInRange(g: Graph, p: seq<int>)
  requires well_formed(g)
  requires is_path(g, p)
  requires |p| > 1
  ensures forall i: int ::
    0 <= i < |p| ==> 0 <= p[i] < |g.adj|
{
  forall i: int | 0 <= i < |p|
    ensures 0 <= p[i] < |g.adj|
  {
    if i < |p| - 1 {
      assert has_edge(g, p[i], p[i + 1]);
      var e :|
        0 <= p[i] < |g.adj| &&
        0 <= e < |g.adj[p[i]]| &&
        g.adj[p[i]][e] == p[i + 1];
      assert 0 <= p[i] < |g.adj|;
    } else {
      assert i == |p| - 1;
      assert 0 <= i - 1 < |p| - 1;
      assert has_edge(g, p[i - 1], p[i]);

      var e :|
        0 <= p[i - 1] < |g.adj| &&
        0 <= e < |g.adj[p[i - 1]]| &&
        g.adj[p[i - 1]][e] == p[i];

      assert 0 <= g.adj[p[i - 1]][e] < |g.adj|;
      assert 0 <= p[i] < |g.adj|;
    }
  }
}

