    if Reach(graph, u, u, |graph.adj|) {
      res := true;
    }

    assert
      res ==
        (exists x: int ::
          0 <= x < u + 1 &&
          Reach(graph, x, x, |graph.adj|));

    u := u + 1;
  }

  GraphCycleReach(graph);
