method coin_change(coins: seq<int>, amount: int) returns (min_coins: int)
    requires |coins| > 0
    requires |coins| <= 100
    requires amount <= 10000
    // Coins must be positive
    requires forall i: int :: 0 <= i < |coins| ==> coins[i] > 0
    requires forall i: int :: 0 <= i < |coins| ==> coins[i] <= 10000
    ensures
        // Case 1: Solution exists
        min_coins != -1 ==> (
            // Existence
            (exists counts: seq<int> :: is_valid_change(counts, coins, amount) && total_coins(counts) == min_coins)
            &&
            // Lower Bound (Optimality)
            (forall counts: seq<int> :: is_valid_change(counts, coins, amount) ==> total_coins(counts) >= min_coins)
        )
    ensures
        // Case 2: Impossible
        min_coins == -1 ==> (
            forall counts: seq<int> :: is_valid_change(counts, coins, amount) ==> false
        )
{
    if amount < 0 {
        lemma_negative_amount(coins, amount);
        reveal is_optimal_result();
        return -1;
    }

    var empty_coins := coins[|coins|..];
    assert |empty_coins| == 0;
    var dp: seq<int> := [];
    var a := 0;
    while a <= amount
        invariant 0 <= a <= amount + 1
        invariant |dp| == a
        invariant forall k: int :: 0 <= k < a ==> is_optimal_result(empty_coins, k, dp[k])
        decreases amount - a
    {
        var val := if a == 0 then 0 else -1;
        lemma_base_case(empty_coins, a);
        dp := dp + [val];
        a := a + 1;
    }

    var idx := |coins|;
    while idx > 0
        invariant 0 <= idx <= |coins|
        invariant |dp| == amount + 1
        invariant forall k: int :: 0 <= k <= amount ==> is_optimal_result(coins[idx..], k, dp[k])
        decreases idx
    {
        idx := idx - 1;
        var sub_coins := coins[idx..];
        assert sub_coins[0] == coins[idx];
        assert sub_coins[1..] == coins[idx + 1..];
        forall i: int | 0 <= i < |sub_coins|
            ensures sub_coins[i] > 0
        {
            assert sub_coins[i] == coins[idx + i];
        }

        var new_dp: seq<int> := [];
        var cur_a := 0;
        while cur_a <= amount
            invariant 0 <= cur_a <= amount + 1
            invariant |new_dp| == cur_a
            invariant forall k: int :: 0 <= k < cur_a ==> is_optimal_result(sub_coins, k, new_dp[k])
            decreases amount - cur_a
        {
            var opt1 := dp[cur_a];
            assert is_optimal_result(sub_coins[1..], cur_a, opt1);
            var opt2_prev := if cur_a >= sub_coins[0] then new_dp[cur_a - sub_coins[0]] else -1;
            if cur_a >= sub_coins[0] {
                assert 0 <= cur_a - sub_coins[0] < cur_a;
                assert is_optimal_result(sub_coins, cur_a - sub_coins[0], opt2_prev);
            }
            var opt2 := if cur_a >= sub_coins[0] && opt2_prev != -1 then opt2_prev + 1 else -1;
            var res := combine_options(opt1, opt2);
            lemma_step(sub_coins, cur_a, opt1, opt2_prev);
            new_dp := new_dp + [res];
            cur_a := cur_a + 1;
        }
        dp := new_dp;
    }

    assert coins[0..] == coins;
    assert is_optimal_result(coins, amount, dp[amount]);
    min_coins := dp[amount];
    reveal is_optimal_result();
}

