    if i < |p| - 1 {
      assert r[i] == p[i];
      assert r[i + 1] == p[i + 1];
      assert has_edge(g, p[i], p[i + 1]);
    } else {
      var j := i - (|p| - 1);
      assert 0 <= j < |q| - 1;
      assert has_edge(g, q[j], q[j + 1]);

      if i == |p| - 1 {
        assert j == 0;
        assert r[i] == p[|p| - 1];
        assert r[i] == q[0];
        assert r[i + 1] == q[1];
      } else {
        assert |p| <= i;
        assert r[i] == q[j];
        assert r[i + 1] == q[j + 1];
      }
    }
  }

  assert is_path(g, r);
