lemma BoundedSetCardinality(s: set<int>, n: int)
  requires 0 <= n
  requires forall x: int :: x in s ==> 0 <= x < n
  ensures |s| <= n
  decreases n
{
  if n == 0 {
    assert forall x: int :: x !in s;
    assert s == {};
  } else {
    var t := s - {n - 1};

    assert forall x: int :: x in t ==> 0 <= x < n - 1 by
    {
      forall x: int | x in t
        ensures 0 <= x < n - 1
      {
        assert x in s;
        assert 0 <= x < n;
        assert x != n - 1;
      }
    }

    BoundedSetCardinality(t, n - 1);

    if n - 1 in s {
      assert n - 1 !in t;
      assert s == t + {n - 1};
      assert |s| == |t| + 1;
    } else {
      assert s == t;
    }
  }
}

