      assert p'[i] == p[i] && p'[i + 1] == p[i + 1];
      assert has_edge(g, p[i], p[i + 1]);
    } else {
      assert i == |p| - 1;
      assert p'[i] == p[|p| - 1] && p'[i + 1] == nxt;
    }
  }
}

lemma LemmaSubpathIsCycle(g: Graph, walk: seq<int>, idx: int, nxt: int)
  requires is_path(g, walk)
  requires 0 <= idx < |walk|
  requires walk[idx] == nxt
  requires has_edge(g, walk[|walk| - 1], nxt)
  ensures is_cycle(g, walk[idx..] + [nxt])
  ensures graph_has_cycle(g)
{
  var sub := walk[idx..];
  forall i: int | 0 <= i < |sub| - 1
    ensures has_edge(g, sub[i], sub[i + 1])
  {
    assert sub[i] == walk[idx + i];
    assert sub[i + 1] == walk[idx + i + 1];
    assert has_edge(g, walk[idx + i], walk[idx + i + 1]);
  }
  assert is_path(g, sub);
  assert sub[|sub| - 1] == walk[|walk| - 1];
  LemmaExtendPath(g, sub, nxt);
  var cyc := sub + [nxt];
  assert is_path(g, cyc);
  assert |cyc| > 1;
  assert cyc[0] == nxt;
  assert cyc[|cyc| - 1] == nxt;
  assert is_cycle(g, cyc);
}

lemma LemmaWalkToCycle(
  g: Graph,
  ranked: seq<bool>,
  next_v: seq<int>,
  unranked: set<int>,
  walk: seq<int>,
  rem: set<int>
)
  requires well_formed(g)
  requires |ranked| == |g.adj|
  requires |next_v| == |g.adj|
  requires forall x: int :: x in unranked <==> (0 <= x < |g.adj| && !ranked[x])
  requires forall w: int :: 0 <= w < |g.adj| && !ranked[w] ==>
    0 <= next_v[w] < |g.adj| && !ranked[next_v[w]] && has_edge(g, w, next_v[w])
  requires |walk| >= 1
  requires is_path(g, walk)
  requires forall k: int :: 0 <= k < |walk| ==> 0 <= walk[k] < |g.adj| && !ranked[walk[k]]
  requires forall x: int :: x in rem <==> (x in unranked && x !in walk)
  ensures graph_has_cycle(g)
  decreases |rem|
{
  var curr := walk[|walk| - 1];
  assert 0 <= curr < |g.adj| && !ranked[curr];
  var nxt := next_v[curr];
  assert 0 <= nxt < |g.adj| && !ranked[nxt] && has_edge(g, curr, nxt);
  assert nxt in unranked;
  if nxt in walk {
    var idx: int :| 0 <= idx < |walk| && walk[idx] == nxt;
    LemmaSubpathIsCycle(g, walk, idx, nxt);
  } else {
    assert nxt in rem;
    LemmaExtendPath(g, walk, nxt);
    var walk' := walk + [nxt];
    var rem' := rem - {nxt};
    assert |rem'| < |rem|;
    forall k: int | 0 <= k < |walk'|
      ensures 0 <= walk'[k] < |g.adj| && !ranked[walk'[k]]
    {
      if k < |walk| {
        assert walk'[k] == walk[k];
      } else {
        assert walk'[k] == nxt;
      }
    }
    forall x: int
      ensures x in rem' <==> (x in unranked && x !in walk')
    {
    }
    LemmaWalkToCycle(g, ranked, next_v, unranked, walk', rem');
  }
}

lemma LemmaUnrankedHasCycle(
  g: Graph,
  ranked: seq<bool>,
  next_v: seq<int>,
  unranked: set<int>
)
  requires well_formed(g)
  requires |ranked| == |g.adj|
  requires |next_v| == |g.adj|
  requires unranked != {}
  requires forall x: int :: x in unranked <==> (0 <= x < |g.adj| && !ranked[x])
  requires forall w: int :: 0 <= w < |g.adj| && !ranked[w] ==>
    0 <= next_v[w] < |g.adj| && !ranked[next_v[w]] && has_edge(g, w, next_v[w])
  ensures graph_has_cycle(g)
{
  var start: int :| start in unranked;
  var walk0 := [start];
  var rem0 := unranked - {start};
  assert |walk0| == 1;
  assert is_path(g, walk0);
  LemmaWalkToCycle(g, ranked, next_v, unranked, walk0, rem0);
}

method has_cycle(graph: Graph) returns (res: bool)
  requires well_formed(graph)
  ensures res == graph_has_cycle(graph)
{
  var n := |graph.adj|;
  var unranked: set<int> := {};
  var ranked: seq<bool> := [];
  var rank: seq<int> := [];
  var idx := 0;
  while idx < n
    invariant 0 <= idx <= n
    invariant |ranked| == idx
    invariant |rank| == idx
    invariant forall x: int :: 0 <= x < idx ==> !ranked[x]
    invariant forall x: int :: x in unranked <==> 0 <= x < idx
    decreases n - idx
  {
    unranked := unranked + {idx};
    ranked := ranked + [false];
    rank := rank + [0];
    idx := idx + 1;
  }

  var step := 0;
  while unranked != {}
    invariant |ranked| == n
    invariant |rank| == n
    invariant forall x: int :: x in unranked <==> (0 <= x < n && !ranked[x])
    invariant forall u: int :: 0 <= u < n && ranked[u] ==> rank[u] < step
    invariant forall u: int, v: int ::
      0 <= u < n && 0 <= v < n && ranked[u] && has_edge(graph, u, v)
      ==> ranked[v] && rank[u] > rank[v]
    decreases |unranked|
  {
    var found_sink := false;
    var sink := 0;
    var next_v: seq<int> := [];
    var u := 0;
    while u < n
      invariant 0 <= u <= n
      invariant |next_v| == u
      invariant found_sink ==> 0 <= sink < n && !ranked[sink]
      invariant found_sink ==> forall j: int :: 0 <= j < |graph.adj[sink]| ==> ranked[graph.adj[sink][j]]
      invariant !found_sink ==> forall w: int :: 0 <= w < u && !ranked[w] ==>
        0 <= next_v[w] < n && !ranked[next_v[w]] && has_edge(graph, w, next_v[w])
      decreases n - u
    {
      if ranked[u] {
        next_v := next_v + [0];
      } else {
        var all_ranked := true;
        var unranked_nbr := 0;
        var i := 0;
        while i < |graph.adj[u]|
          invariant 0 <= i <= |graph.adj[u]|
          invariant all_ranked ==> forall j: int :: 0 <= j < i ==> ranked[graph.adj[u][j]]
          invariant !all_ranked ==> 0 <= unranked_nbr < n && !ranked[unranked_nbr] && has_edge(graph, u, unranked_nbr)
          decreases |graph.adj[u]| - i
        {
          var v := graph.adj[u][i];
          assert 0 <= v < n;
          if !ranked[v] {
            all_ranked := false;
            unranked_nbr := v;
            assert has_edge(graph, u, v);
          }
          i := i + 1;
        }
        if all_ranked {
          found_sink := true;
          sink := u;
          next_v := next_v + [0];
        } else {
          next_v := next_v + [unranked_nbr];
        }
      }
      u := u + 1;
    }

    if !found_sink {
      LemmaUnrankedHasCycle(graph, ranked, next_v, unranked);
      return true;
    }

    assert sink in unranked;
    var ranked' := ranked[sink := true];
    var rank' := rank[sink := step];
    var unranked' := unranked - {sink};
    assert |unranked'| < |unranked|;

    forall u': int, v': int | 0 <= u' < n && 0 <= v' < n && ranked'[u'] && has_edge(graph, u', v')
      ensures ranked'[v'] && rank'[u'] > rank'[v']
    {
      if u' == sink {
        var j: int :| 0 <= j < |graph.adj[sink]| && graph.adj[sink][j] == v';
        assert ranked[v'];
        assert v' != sink;
        assert rank[v'] < step;
      } else {
        assert ranked[u'];
        assert ranked[v'];
        assert v' != sink;
      }
    }

    ranked := ranked';
    rank := rank';
    unranked := unranked';
    step := step + 1;
  }

  assert forall u: int :: 0 <= u < n ==> ranked[u];
  assert valid_ranking(graph, rank);
  LemmaNoCycleIfRanked(graph, rank);
  return false;
}
