function Edge(g: Graph, u: int, v: int): bool
  requires 0 <= u < |g.adj|
{
  v in g.adj[u]
}

lemma EdgeHasEdge(g: Graph, u: int, v: int)
  requires 0 <= u < |g.adj|
  ensures Edge(g, u, v) == has_edge(g, u, v)
{
  if Edge(g, u, v) {
    var i :| 0 <= i < |g.adj[u]| && g.adj[u][i] == v;
    assert has_edge(g, u, v);
  }

  if has_edge(g, u, v) {
    var i :|
      0 <= u < |g.adj| &&
      0 <= i < |g.adj[u]| &&
      g.adj[u][i] == v;
    assert v in g.adj[u];
    assert Edge(g, u, v);
  }
}

ghost predicate LimitedPath(
    g: Graph, p: seq<int>, u: int, v: int, k: nat)
{
  is_path(g, p) &&
  |p| > 1 &&
  p[0] == u &&
  p[|p| - 1] == v &&
  (forall i: int ::
    1 <= i < |p| - 1 ==> 0 <= p[i] < k)
}

ghost function FirstIndex(s: seq<int>, x: int): nat
  requires x in s
  ensures FirstIndex(s, x) < |s|
  ensures s[FirstIndex(s, x)] == x
  ensures forall i: int ::
    0 <= i < FirstIndex(s, x) ==> s[i] != x
  decreases |s|
{
  if s[0] == x then
    0
  else
    1 + FirstIndex(s[1..], x)
}

ghost function LastIndex(s: seq<int>, x: int): nat
  requires x in s
  ensures LastIndex(s, x) < |s|
  ensures s[LastIndex(s, x)] == x
  ensures forall i: int ::
    LastIndex(s, x) < i < |s| ==> s[i] != x
  decreases |s|
{
  if s[|s| - 1] == x then
    |s| - 1
  else
    LastIndex(s[..|s| - 1], x)
}

lemma PathSlice(g: Graph, p: seq<int>, a: int, b: int)
  requires is_path(g, p)
  requires 0 <= a < b <= |p|
  ensures is_path(g, p[a..b])
{
  var q := p[a..b];
  assert |q| == b - a;
  assert |q| > 0;

  forall i: int | 0 <= i < |q| - 1
    ensures has_edge(g, q[i], q[i + 1])
  {
    assert 0 <= a + i < |p| - 1;
    assert q[i] == p[a + i];
    assert q[i + 1] == p[a + i + 1];
    assert has_edge(g, p[a + i], p[a + i + 1]);
  }

  assert is_path(g, q);
}

lemma PathJoin(g: Graph, p: seq<int>, q: seq<int>)
  requires is_path(g, p)
  requires is_path(g, q)
  requires |p| > 1
  requires |q| > 1
  requires p[|p| - 1] == q[0]
  ensures is_path(g, p + q[1..])
{
  var r := p + q[1..];
  assert |r| == |p| + |q| - 1;
  assert |r| > 0;

  forall i: int | 0 <= i < |r| - 1
    ensures has_edge(g, r[i], r[i + 1])
  {
    if i < |p| - 1 {
      assert r[i] == p[i];
      assert r[i + 1] == p[i + 1];
      assert has_edge(g, p[i], p[i + 1]);
    } else {
      var j := i - (|p| - 1);
      assert 0 <= j < |q| - 1;
      assert has_edge(g, q[j], q[j + 1]);

      if i == |p| - 1 {
        assert j == 0;
        assert r[i] == p[|p| - 1];
        assert r[i] == q[0];
        assert r[i + 1] == q[1];
      } else {
        assert |p| <= i;
        assert r[i] == q[j];
        assert r[i + 1] == q[j + 1];
      }
    }
  }

  assert is_path(g, r);
}

lemma LimitedZero(g: Graph, u: int, v: int)
  requires 0 <= u < |g.adj|
  ensures
    Edge(g, u, v) ==
      (exists p: seq<int> :: LimitedPath(g, p, u, v, 0))
{
  EdgeHasEdge(g, u, v);

  if Edge(g, u, v) {
    var p := [u, v];
    assert |p| == 2;

    forall i: int | 0 <= i < |p| - 1
      ensures has_edge(g, p[i], p[i + 1])
    {
      assert i == 0;
      assert p[i] == u;
      assert p[i + 1] == v;
      assert has_edge(g, u, v);
    }

    assert is_path(g, p);
    assert LimitedPath(g, p, u, v, 0);
    assert exists p: seq<int> :: LimitedPath(g, p, u, v, 0);
  }

  if exists p: seq<int> :: LimitedPath(g, p, u, v, 0) {
    var p :| LimitedPath(g, p, u, v, 0);

    if |p| > 2 {
      assert 1 <= 1 < |p| - 1;
      assert 0 <= p[1] < 0;
      assert false;
    }

    assert |p| == 2;
    assert has_edge(g, p[0], p[1]);
    assert p[0] == u;
    assert p[1] == v;
    assert has_edge(g, u, v);
    assert Edge(g, u, v);
  }
}

lemma LimitedStepForward(
    g: Graph, u: int, v: int, k: nat)
  ensures
    (exists p: seq<int> :: LimitedPath(g, p, u, v, k + 1))
    ==>
    ((exists p: seq<int> :: LimitedPath(g, p, u, v, k)) ||
     ((exists p: seq<int> :: LimitedPath(g, p, u, k, k)) &&
      (exists p: seq<int> :: LimitedPath(g, p, k, v, k))))
{
  if exists p: seq<int> :: LimitedPath(g, p, u, v, k + 1) {
    var p :| LimitedPath(g, p, u, v, k + 1);

    if forall i: int ::
         1 <= i < |p| - 1 ==> p[i] != k
    {
      forall i: int | 1 <= i < |p| - 1
        ensures 0 <= p[i] < k
      {
        assert 0 <= p[i] < k + 1;
        assert p[i] != k;
      }

      assert LimitedPath(g, p, u, v, k);
      assert exists q: seq<int> :: LimitedPath(g, q, u, v, k);
    } else {
      assert exists i: int ::
        1 <= i < |p| - 1 && p[i] == k;
      var z :| 1 <= z < |p| - 1 && p[z] == k;

      var middle := p[1..|p| - 1];
      assert middle[z - 1] == k;
      assert k in middle;

      var a := 1 + FirstIndex(middle, k);
      var b := 1 + LastIndex(middle, k);

      assert 1 <= a < |p| - 1;
      assert 1 <= b < |p| - 1;
      assert p[a] == k;
      assert p[b] == k;

      var left := p[..a + 1];
      var right := p[b..];

      PathSlice(g, p, 0, a + 1);
      PathSlice(g, p, b, |p|);

      assert is_path(g, left);
      assert is_path(g, right);
      assert |left| == a + 1;
      assert |right| == |p| - b;
      assert |left| > 1;
      assert |right| > 1;
      assert left[0] == u;
      assert left[|left| - 1] == k;
      assert right[0] == k;
      assert right[|right| - 1] == v;

      forall i: int | 1 <= i < |left| - 1
        ensures 0 <= left[i] < k
      {
        assert i < a;
        assert left[i] == p[i];
        assert 0 <= p[i] < k + 1;
        assert 0 <= i - 1 < FirstIndex(middle, k);
        assert middle[i - 1] != k;
        assert middle[i - 1] == p[i];
        assert p[i] != k;
      }

      forall i: int | 1 <= i < |right| - 1
        ensures 0 <= right[i] < k
      {
        var original := b + i;
        var mi := original - 1;
        assert b < original < |p| - 1;
        assert right[i] == p[original];
        assert 0 <= p[original] < k + 1;
        assert LastIndex(middle, k) < mi < |middle|;
        assert middle[mi] != k;
        assert middle[mi] == p[original];
        assert p[original] != k;
      }

      assert LimitedPath(g, left, u, k, k);
      assert LimitedPath(g, right, k, v, k);
      assert exists q: seq<int> :: LimitedPath(g, q, u, k, k);
      assert exists q: seq<int> :: LimitedPath(g, q, k, v, k);
    }
  }
}

lemma LimitedStepBackward(
    g: Graph, u: int, v: int, k: nat)
  ensures
    ((exists p: seq<int> :: LimitedPath(g, p, u, v, k)) ||
     ((exists p: seq<int> :: LimitedPath(g, p, u, k, k)) &&
      (exists p: seq<int> :: LimitedPath(g, p, k, v, k))))
    ==>
    (exists p: seq<int> :: LimitedPath(g, p, u, v, k + 1))
{
  if
    (exists p: seq<int> :: LimitedPath(g, p, u, v, k)) ||
    ((exists p: seq<int> :: LimitedPath(g, p, u, k, k)) &&
     (exists p: seq<int> :: LimitedPath(g, p, k, v, k)))
  {
    if exists p: seq<int> :: LimitedPath(g, p, u, v, k) {
      var p :| LimitedPath(g, p, u, v, k);

      forall i: int | 1 <= i < |p| - 1
        ensures 0 <= p[i] < k + 1
      {
        assert 0 <= p[i] < k;
      }

      assert LimitedPath(g, p, u, v, k + 1);
      assert exists q: seq<int> ::
        LimitedPath(g, q, u, v, k + 1);
    } else {
      assert exists p: seq<int> :: LimitedPath(g, p, u, k, k);
      assert exists q: seq<int> :: LimitedPath(g, q, k, v, k);

      var p :| LimitedPath(g, p, u, k, k);
      var q :| LimitedPath(g, q, k, v, k);

      var r := p + q[1..];
      PathJoin(g, p, q);

      assert |r| == |p| + |q| - 1;
      assert |r| > 1;
      assert r[0] == u;
      assert r[|r| - 1] == v;

      forall i: int | 1 <= i < |r| - 1
        ensures 0 <= r[i] < k + 1
      {
        if i < |p| - 1 {
          assert r[i] == p[i];
          assert 0 <= p[i] < k;
