method has_cycle(graph: Graph) returns (res: bool)
  requires well_formed(graph)
  ensures res == graph_has_cycle(graph)
{
  res := false;
  var u := 0;

  while u < |graph.adj|
    invariant 0 <= u <= |graph.adj|
    invariant
      res ==
        (exists x: int ::
          0 <= x < u &&
          Reach(graph, x, x, |graph.adj|))
  {
    assert
      (exists x: int ::
        0 <= x < u + 1 &&
        Reach(graph, x, x, |graph.adj|))
      ==
      ((exists x: int ::
          0 <= x < u &&
          Reach(graph, x, x, |graph.adj|)) ||
       Reach(graph, u, u, |graph.adj|))
      by
      {
        if exists x: int ::
             0 <= x < u + 1 &&
             Reach(graph, x, x, |graph.adj|)
        {
          var x :|
            0 <= x < u + 1 &&
            Reach(graph, x, x, |graph.adj|);
          if x < u {
            assert exists y: int ::
              0 <= y < u &&
              Reach(graph, y, y, |graph.adj|);
          } else {
            assert x == u;
          }
        }

        if
          (exists x: int ::
            0 <= x < u &&
            Reach(graph, x, x, |graph.adj|)) ||
          Reach(graph, u, u, |graph.adj|)
        {
          if Reach(graph, u, u, |graph.adj|) {
            assert exists x: int ::
              0 <= x < u + 1 &&
              Reach(graph, x, x, |graph.adj|);
          } else {
            var x :|
              0 <= x < u &&
              Reach(graph, x, x, |graph.adj|);
            assert exists y: int ::
              0 <= y < u + 1 &&
              Reach(graph, y, y, |graph.adj|);
          }
        }
      }

    if Reach(graph, u, u, |graph.adj|) {
      res := true;
    }

    assert
      res ==
        (exists x: int ::
          0 <= x < u + 1 &&
          Reach(graph, x, x, |graph.adj|));

    u := u + 1;
  }

  assert u == |graph.adj|;
  GraphCycleReach(graph);

  assert res ==> graph_has_cycle(graph) by {
    if res {
      assert exists x: int ::
        0 <= x < u &&
        Reach(graph, x, x, |graph.adj|);

      var x :|
        0 <= x < u &&
        Reach(graph, x, x, |graph.adj|);

      assert 0 <= x < |graph.adj|;
      assert exists y: int ::
        0 <= y < |graph.adj| &&
        Reach(graph, y, y, |graph.adj|);
      assert graph_has_cycle(graph);
    }
  }

  assert graph_has_cycle(graph) ==> res by {
    if graph_has_cycle(graph) {
      assert exists x: int ::
        0 <= x < |graph.adj| &&
        Reach(graph, x, x, |graph.adj|);

      var x :|
        0 <= x < |graph.adj| &&
        Reach(graph, x, x, |graph.adj|);

      assert 0 <= x < u;
      assert exists y: int ::
        0 <= y < u &&
        Reach(graph, y, y, |graph.adj|);
      assert res;
    }
  }

  assert res == graph_has_cycle(graph);
}
