lemma ClosedSetUnreachable(g: Graph, visited: set<int>, p: seq<int>)
  requires forall u, v :: u in visited && has_edge(g, u, v) ==> v in visited
  requires is_path(g, p)
  requires p[0] in visited
  ensures p[|p| - 1] in visited
  decreases |p|
