ghost predicate WitnessOK(
    graph: WeightedGraph,
    start: int,
    dist: seq<Option<int>>,
    witness: seq<seq<int>>
) {
    |dist| == size(graph)
    && |witness| == size(graph)
    && forall v: int ::
        0 <= v < size(graph) && HasValue(dist[v]) ==>
            is_path(view(graph), witness[v])
            && witness[v][0] == start
            && witness[v][|witness[v]| - 1] == v
            && path_weight(view(graph), witness[v]) == OVal(dist[v])
}

ghost predicate SettledOK(
    graph: WeightedGraph,
    start: int,
    dist: seq<Option<int>>,
    done: set<int>
) {
    forall v: int ::
        v in done ==>
            0 <= v < size(graph)
            && HasValue(dist[v])
            && is_shortest_dist(view(graph), start, v, OVal(dist[v]))
}

ghost predicate FrontierOK(
    graph: WeightedGraph,
    dist: seq<Option<int>>,
    done: set<int>
) {
    forall u: int, v: int ::
        u in done
        && 0 <= v < size(graph)
        && connected(view(graph), u, v)
        ==>
            HasValue(dist[u])
            && HasValue(dist[v])
            && OVal(dist[v])
                <= OVal(dist[u]) + get_edge_weight(view(graph), u, v)
}

ghost predicate FrontierExcept(
    graph: WeightedGraph,
    dist: seq<Option<int>>,
    done: set<int>,
