            ) == OVal(newDist[u]) + w;
            assert OVal(newDist[v])
                <= OVal(newDist[u]) + w;
        } else {
            var nd := OVal(newDist[u]) + w;
            if !HasValue(newDist[v]) || nd < OVal(newDist[v]) {
                var oldDist := newDist;
                var oldWitness := newWitness;
                var q := oldWitness[u] + [v];

                AppendEdgeLemma(graph, oldWitness[u], v, w);
                newDist := oldDist[v := Some(nd)];
                newWitness := oldWitness[v := q];

                assert WitnessOK(
                    graph, start, newDist, newWitness
                ) by {
                    forall x: int
                        | 0 <= x < size(graph)
                          && HasValue(newDist[x])
                        ensures
                            is_path(view(graph), newWitness[x])
                            && newWitness[x][0] == start
                            && newWitness[x][|newWitness[x]| - 1] == x
                            && path_weight(
                                view(graph), newWitness[x]
                            ) == OVal(newDist[x])
                    {
                        if x == v {
                            assert newWitness[x] == q;
                            assert newDist[x] == Some(nd);
                        } else {
                            assert newWitness[x] == oldWitness[x];
                            assert newDist[x] == oldDist[x];
                        }
                    }
                }

                assert SettledOK(
                    graph, start, newDist, done
                ) by {
                    forall x: int | x in done
                        ensures
                            0 <= x < size(graph)
                            && HasValue(newDist[x])
                            && is_shortest_dist(
                                view(graph), start, x,
                                OVal(newDist[x])
                            )
                    {
                        assert x != v;
                        assert newDist[x] == oldDist[x];
                    }
                }

                assert FrontierExcept(
                    graph, newDist, done, u
                ) by {
                    forall x: int, y: int
                        | x in done
                          && x != u
                          && 0 <= y < size(graph)
                          && connected(view(graph), x, y)
                        ensures
                            HasValue(newDist[x])
                            && HasValue(newDist[y])
                            && OVal(newDist[y])
                                <= OVal(newDist[x])
                                  + get_edge_weight(
                                      view(graph), x, y
                                  )
                    {
                        assert x != v;
                        if y == v {
                            assert OVal(newDist[y])
                                <= OVal(oldDist[y]);
                            assert newDist[x] == oldDist[x];
                        } else {
                            assert newDist[x] == oldDist[x];
                            assert newDist[y] == oldDist[y];
                        }
                    }
                }
            }
        }

        i := i + 1;
    }

    assert FrontierOK(graph, newDist, done) by {
        forall x: int, v: int
            | x in done
              && 0 <= v < size(graph)
              && connected(view(graph), x, v)
            ensures
                HasValue(newDist[x])
                && HasValue(newDist[v])
                && OVal(newDist[v])
                    <= OVal(newDist[x])
                      + get_edge_weight(view(graph), x, v)
        {
            if x != u {
            } else {
                var w :| has_edge(view(graph), u, v, w);
                var j :| 0 <= u < |graph.adj|
                          && 0 <= j < |graph.adj[u]|
                          && graph.adj[u][j].0 == v
                          && graph.adj[u][j].1 == w;
                assert j < |graph.adj[u]|;
                GetEdgeWeightLemma(graph, u, v, w);
            }
        }
    }
}

method dijkstra_shortest_paths(
    graph: WeightedGraph,
    start: int
) returns (res: seq<Option<int>>)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    requires weights_non_negative(view(graph))
    requires weights_and_size_bounded(view(graph))
    ensures |res| == size(graph)
    ensures forall v: int :: 0 <= v < size(graph) ==>
        match res[v] {
            case Some(d) =>
                is_shortest_dist(view(graph), start, v, d)
            case None =>
                forall p: seq<int> {:trigger is_path(view(graph), p)} ::
                    is_path(view(graph), p)
                    && p[0] == start
                    && p[|p| - 1] == v
                    ==> false
        }
{
    var n := size(graph);
    var dist := seq(n, i =>
        if i == start then Some(0) else None);
    var witness := seq(n, i =>
        if i == start then [start] else []);
    var done: set<int> := {};
    var count := 0;
    var stuck := false;

    assert is_path(view(graph), [start]);
    assert WitnessOK(graph, start, dist, witness);
    assert SettledOK(graph, start, dist, done);
    assert FrontierOK(graph, dist, done);
    assert HasValue(dist[start]);

    while count < n && !stuck
        invariant |dist| == n
        invariant |witness| == n
        invariant WitnessOK(graph, start, dist, witness)
        invariant SettledOK(graph, start, dist, done)
        invariant FrontierOK(graph, dist, done)
        invariant HasValue(dist[start])
        invariant forall v: int :: v in done ==> 0 <= v < n
        invariant count == |done|
        invariant 0 <= count <= n
        invariant stuck ==>
            forall v: int ::
                0 <= v < n && v !in done ==>
                    !HasValue(dist[v])
        decreases n - count
    {
        var found := false;
        var best := -1;
        var bestDistance := 0;
        var i := 0;

        while i < n
            invariant 0 <= i <= n
            invariant found ==>
                0 <= best < n
                && best !in done
                && HasValue(dist[best])
                && bestDistance == OVal(dist[best])
            invariant forall v: int ::
                0 <= v < i
                && v !in done
                && HasValue(dist[v])
                ==> found && bestDistance <= OVal(dist[v])
            decreases n - i
        {
            if i !in done && HasValue(dist[i]) {
                if !found || OVal(dist[i]) < bestDistance {
                    found := true;
                    best := i;
                    bestDistance := OVal(dist[i]);
                }
            }
            i := i + 1;
        }

        if !found {
            assert forall v: int ::
                0 <= v < n && v !in done ==>
                    !HasValue(dist[v]);
            stuck := true;
        } else {
            assert forall v: int ::
                0 <= v < n
                && v !in done
                && HasValue(dist[v])
                ==> OVal(dist[best]) <= OVal(dist[v]);

            SelectedVertexIsShortest(
                graph, start, dist, witness, done, best
            );

            var oldDone := done;
            done := done + {best};
            count := count + 1;

            assert |done| == |oldDone| + 1;
            assert SettledOK(graph, start, dist, done);
            assert FrontierExcept(
                graph, dist, done, best
            );

            var oldDist := dist;
            (dist, witness) := RelaxFrom(
                graph, start, dist, witness, done, best
            );
            assert HasValue(dist[start]);
        }
    }

    if stuck {
        NoTentativeMeansUnreachable(
            graph, start, dist, done
        );
    } else {
        assert count == n;
        assert |done| == n;
        BoundedSetCardinality(done, n);

        forall v: int | 0 <= v < n
            ensures v in done
        {
            if v !in done {
                var larger := done + {v};
                assert |larger| == |done| + 1;
                assert forall x: int ::
                    x in larger ==> 0 <= x < n;
                BoundedSetCardinality(larger, n);
                assert false;
            }
        }
    }

    res := dist;

    forall v: int | 0 <= v < n
        ensures
            match res[v]
            case Some(d) =>
                is_shortest_dist(view(graph), start, v, d)
            case None =>
                forall p: seq<int> {:trigger is_path(view(graph), p)} ::
                    is_path(view(graph), p)
                    && p[0] == start
                    && p[|p| - 1] == v
                    ==> false
    {
        if v in done {
            assert HasValue(res[v]);
            assert is_shortest_dist(
                view(graph), start, v, OVal(res[v])
            );
        } else {
            assert stuck;
            assert !HasValue(res[v]);
            NoTentativeMeansUnreachable(
                graph, start, res, done
            );
        }
    }
}
