}

ghost predicate Inv(graph: WeightedGraph, start: int, dist: seq<Option<int>>) {
  && |dist| == |graph.adj|
  && 0 <= start < |dist|
  && dist[start] == Some(0)
  && (forall v :: 0 <= v < |dist| && dist[v].Some? ==>
        dist[v].value >= 0 && path_witness(graph.adj, start, v, dist[v].value))
}

