lemma EdgeWeight(graph: WeightedGraph, u: int, i: int)
  requires well_formed(graph)
  requires 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]|
  ensures has_edge(graph.adj, u, graph.adj[u][i].0, graph.adj[u][i].1)
  ensures get_edge_weight(graph.adj, u, graph.adj[u][i].0) == graph.adj[u][i].1
  ensures 0 <= graph.adj[u][i].0 < |graph.adj|
{
  var g := graph.adj;
  var v := g[u][i].0;
  var w := g[u][i].1;
  assert has_edge(g, u, v, w);
  forall w' | has_edge(g, u, v, w') ensures w' == w {
    var j :| 0 <= u < |g| && 0 <= j < |g[u]| && g[u][j].0 == v && g[u][j].1 == w';
    if j != i {
      assert g[u][i].0 != g[u][j].0;
    }
  }
  var r := get_edge_weight(g, u, v);
  assert has_edge(g, u, v, r);
}

lemma ExtendPath(graph: WeightedGraph, start: int, u: int, i: int, du: int)
  requires well_formed(graph)
  requires 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]|
  requires path_witness(graph.adj, start, u, du)
  ensures path_witness(graph.adj, start, graph.adj[u][i].0, du + graph.adj[u][i].1)
{
  var g := graph.adj;
  var v := g[u][i].0;
  var w := g[u][i].1;
  var p :| is_path(g, p) && p[0] == start && p[|p| - 1] == u && path_weight(g, p) == du;
  EdgeWeight(graph, u, i);
  assert has_edge(g, u, v, w);
  assert connected(g, u, v);
  var q := p + [v];
  forall k | 0 <= k < |q| - 1 ensures connected(g, q[k], q[k+1]) {
    if k < |p| - 1 {
      assert q[k] == p[k] && q[k+1] == p[k+1];
    } else {
      assert q[k] == u && q[k+1] == v;
    }
  }
  assert is_path(g, q);
  assert q[..|q| - 1] == p;
  assert q[|q| - 2] == u;
  assert q[|q| - 1] == v;
  assert path_weight(g, q) == path_weight(g, p) + get_edge_weight(g, u, v);
  assert q[0] == start;
  assert path_witness(g, start, v, du + w);
}

lemma InvUpdate(graph: WeightedGraph, start: int, dist: seq<Option<int>>, v: int, nd: int)
  requires Inv(graph, start, dist)
  requires 0 <= v < |dist| && v != start && nd >= 0
  requires path_witness(graph.adj, start, v, nd)
  ensures Inv(graph, start, dist[v := Some(nd)])
{
  var d2 := dist[v := Some(nd)];
  forall x | 0 <= x < |d2| && d2[x].Some?
    ensures d2[x].value >= 0 && path_witness(graph.adj, start, x, d2[x].value)
  {
    if x != v {
      assert d2[x] == dist[x];
    }
  }
}

lemma LowerBound(graph: WeightedGraph, start: int, dist: seq<Option<int>>, p: seq<int>)
  requires well_formed(graph)
  requires |dist| == |graph.adj|
  requires 0 <= start < |graph.adj|
  requires dist[start] == Some(0)
  requires AllOk(graph.adj, dist)
  requires is_path(graph.adj, p) && p[0] == start
  ensures 0 <= p[|p| - 1] < |dist|
  ensures dist[p[|p| - 1]].Some? && dist[p[|p| - 1]].value <= path_weight(graph.adj, p)
  decreases |p|
{
  var g := graph.adj;
  if |p| == 1 {
  } else {
    var q := p[..|p| - 1];
    forall k | 0 <= k < |q| - 1 ensures connected(g, q[k], q[k+1]) {
      assert q[k] == p[k] && q[k+1] == p[k+1];
    }
    assert is_path(g, q);
    LowerBound(graph, start, dist, q);
    var u := p[|p| - 2];
    var v := p[|p| - 1];
    assert q[|q| - 1] == u;
    assert connected(g, u, v);
    var w :| has_edge(g, u, v, w);
    var i :| 0 <= u < |g| && 0 <= i < |g[u]| && g[u][i].0 == v && g[u][i].1 == w;
    EdgeWeight(graph, u, i);
    assert edge_ok(g, dist, u, i);
    assert path_weight(g, p) == path_weight(g, q) + get_edge_weight(g, u, v);
  }
}

lemma Final(graph: WeightedGraph, start: int, dist: seq<Option<int>>)
  requires well_formed(graph)
  requires Inv(graph, start, dist)
  requires AllOk(graph.adj, dist)
  ensures |dist| == size(graph)
  ensures forall v: int :: 0 <= v < size(graph) ==> 
        match dist[v] {
            case Some(d) => 
                is_shortest_dist(view(graph), start, v, d)
            case None => 
                forall p: seq<int> {:trigger is_path(view(graph), p)} :: 
                    is_path(view(graph), p) && p[0] == start && p[|p| - 1] == v ==> false
        }
{
  var g := view(graph);
  assert g == graph.adj;
  forall v | 0 <= v < |dist|
    ensures dist[v].Some? ==> is_shortest_dist(g, start, v, dist[v].value)
    ensures dist[v].None? ==> forall p: seq<int> {:trigger is_path(g, p)} ::
                is_path(g, p) && p[0] == start && p[|p| - 1] == v ==> false
  {
    forall p: seq<int> | is_path(g, p) && p[0] == start && p[|p| - 1] == v
      ensures dist[v].Some? && path_weight(g, p) >= dist[v].value
    {
      LowerBound(graph, start, dist, p);
    }
    if dist[v].Some? {
      var d := dist[v].value;
      assert path_witness(graph.adj, start, v, d);
      var p :| is_path(graph.adj, p) && p[0] == start && p[|p| - 1] == v && path_weight(graph.adj, p) == d;
      assert is_path(g, p) && path_weight(g, p) == d;
    }
  }
}

method dijkstra_shortest_paths(graph: WeightedGraph, start: int) returns (res: seq<Option<int>>)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    requires weights_non_negative(view(graph))
    requires weights_and_size_bounded(view(graph))
    ensures |res| == size(graph)
    ensures forall v: int :: 0 <= v < size(graph) ==> 
        match res[v] {
            case Some(d) => 
                is_shortest_dist(view(graph), start, v, d)
            case None => 
                forall p: seq<int> {:trigger is_path(view(graph), p)} :: 
                    is_path(view(graph), p) && p[0] == start && p[|p| - 1] == v ==> false
        }
{
  var n := |graph.adj|;
  var dist: seq<Option<int>> := seq(n, (k: int) => if k == start then Some(0) else None);
  assert is_path(graph.adj, [start]);
  assert path_weight(graph.adj, [start]) == 0;
  assert path_witness(graph.adj, start, start, 0);
  assert Inv(graph, start, dist);
  var changed := true;
  while changed
    invariant Inv(graph, start, dist)
    invariant !changed ==> AllOk(graph.adj, dist)
    decreases countNone(dist), sumSome(dist), if changed then 1 else 0
  {
    ghost var dist0 := dist;
    changed := false;
    var u := 0;
    while u < n
      invariant 0 <= u <= n
      invariant Inv(graph, start, dist)
      invariant !changed ==> dist == dist0
      invariant changed ==> lexLt(countNone(dist), sumSome(dist), countNone(dist0), sumSome(dist0))
      invariant !changed ==> forall uu, ii :: 0 <= uu < u && 0 <= ii < |graph.adj[uu]| ==> edge_ok(graph.adj, dist, uu, ii)
    {
      var i := 0;
      while i < |graph.adj[u]|
        invariant 0 <= i <= |graph.adj[u]|
        invariant Inv(graph, start, dist)
        invariant !changed ==> dist == dist0
        invariant changed ==> lexLt(countNone(dist), sumSome(dist), countNone(dist0), sumSome(dist0))
        invariant !changed ==> forall uu, ii :: 0 <= uu < u && 0 <= ii < |graph.adj[uu]| ==> edge_ok(graph.adj, dist, uu, ii)
        invariant !changed ==> forall ii :: 0 <= ii < i ==> edge_ok(graph.adj, dist, u, ii)
      {
        var v := graph.adj[u][i].0;
        var w := graph.adj[u][i].1;
        EdgeWeight(graph, u, i);
        assert 0 <= v < n;
        if dist[u].Some? && (dist[v].None? || dist[u].value + w < dist[v].value) {
          var nd := dist[u].value + w;
          assert has_edge(view(graph), u, v, w);
          assert w >= 0;
          assert dist[u].value >= 0;
          assert nd >= 0;
          assert v != start;
          ExtendPath(graph, start, u, i, dist[u].value);
          InvUpdate(graph, start, dist, v, nd);
          if dist[v].None? {
            UpdateNoneToSome(dist, v, nd);
          } else {
            UpdateSomeToSmaller(dist, v, nd);
          }
          dist := dist[v := Some(nd)];
          changed := true;
        } else {
          assert edge_ok(graph.adj, dist, u, i);
        }
        i := i + 1;
      }
      u := u + 1;
    }
  }
  Final(graph, start, dist);
  res := dist;
}

response:
Instead of the textbook priority-queue Dijkstra, this implements a relaxation-to-fixpoint (Bellman-Ford-style) algorithm, which is much easier to verify. The contracts are unchanged.

- **Path invariant:** every `Some(d)` entry is the weight of an actual path from `start`.
- **Termination:** each pass that changes something strictly decreases the pair (number of `None` entries, sum of the `Some` values), compared lexicographically.
- **Fixpoint argument:** when a pass changes nothing, every edge satisfies the triangle inequality. Induction on path length then shows every path from `start` to `v` reaches a `Some` entry no larger than the path's weight. That gives both the shortest-distance case and the unreachable (`None`) case.

