lemma EdgeWeight(graph: WeightedGraph, u: int, i: int)
  requires well_formed(graph)
  requires 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]|
  ensures has_edge(graph.adj, u, graph.adj[u][i].0, graph.adj[u][i].1)
  ensures get_edge_weight(graph.adj, u, graph.adj[u][i].0) == graph.adj[u][i].1
  ensures 0 <= graph.adj[u][i].0 < |graph.adj|
{
  var g := graph.adj;
  var v := g[u][i].0;
  var w := g[u][i].1;
  assert has_edge(g, u, v, w);
  forall w' | has_edge(g, u, v, w') ensures w' == w {
    var j :| 0 <= u < |g| && 0 <= j < |g[u]| && g[u][j].0 == v && g[u][j].1 == w';
    if j != i {
      assert g[u][i].0 != g[u][j].0;
    }
  }
  var r := get_edge_weight(g, u, v);
  assert has_edge(g, u, v, r);
}

lemma ExtendPath(graph: WeightedGraph, start: int, u: int, i: int, du: int)
  requires well_formed(graph)
  requires 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]|
  requires path_witness(graph.adj, start, u, du)
  ensures path_witness(graph.adj, start, graph.adj[u][i].0, du + graph.adj[u][i].1)
{
  var g := graph.adj;
  var v := g[u][i].0;
  var w := g[u][i].1;
  var p :| is_path(g, p) && p[0] == start && p[|p| - 1] == u && path_weight(g, p) == du;
  EdgeWeight(graph, u, i);
  assert has_edge(g, u, v, w);
  assert connected(g, u, v);
  var q := p + [v];
  forall k | 0 <= k < |q| - 1 ensures connected(g, q[k], q[k+1]) {
    if k < |p| - 1 {
      assert q[k] == p[k] && q[k+1] == p[k+1];
    } else {
      assert q[k] == u && q[k+1] == v;
    }
  }
  assert is_path(g, q);
  assert q[..|q| - 1] == p;
  assert q[|q| - 2] == u;
  assert q[|q| - 1] == v;
  assert path_weight(g, q) == path_weight(g, p) + get_edge_weight(g, u, v);
  assert q[0] == start;
  assert path_witness(g, start, v, du + w);
}

lemma InvUpdate(graph: WeightedGraph, start: int, dist: seq<Option<int>>, v: int, nd: int)
  requires Inv(graph, start, dist)
  requires 0 <= v < |dist| && v != start && nd >= 0
  requires path_witness(graph.adj, start, v, nd)
  ensures Inv(graph, start, dist[v := Some(nd)])
{
  var d2 := dist[v := Some(nd)];
  forall x | 0 <= x < |d2| && d2[x].Some?
    ensures d2[x].value >= 0 && path_witness(graph.adj, start, x, d2[x].value)
  {
    if x != v {
      assert d2[x] == dist[x];
    }
  }
}

