function m_has_capacity(g: seq<seq<(int, int)>>, u: int, v: int, c: int): bool {
    exists i: int ::
        0 <= u < |g| && 0 <= i < |g[u]|
        && g[u][i].0 == v
        && g[u][i].1 == c
}

function m_get_flow(f: FlowMap, u: int, v: int): int {
    if (u, v) in f then f[(u, v)] else 0
}

function m_sum_flow_out(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int,
    idx: int
): int
    decreases idx
{
    if idx <= 0 || u < 0 || u >= |g| then
        0
    else if idx - 1 < |g[u]| then
        m_sum_flow_out(g, f, u, idx - 1)
            + m_get_flow(f, u, g[u][idx - 1].0)
    else
        m_sum_flow_out(g, f, u, idx - 1)
}

function m_sum_flow_in(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int,
    idx: int
): int
    decreases idx
{
    if idx <= 0 then
        0
    else
        m_sum_flow_in(g, f, u, idx - 1)
            + m_get_flow(f, idx - 1, u)
}

function m_total_flow_out(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int
): int {
    if 0 <= u < |g| then
        m_sum_flow_out(g, f, u, |g[u]|)
    else
        0
}

function m_total_flow_in(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int
): int {
    m_sum_flow_in(g, f, u, |g|)
}

predicate m_respects_capacity(
    g: seq<seq<(int, int)>>,
    f: FlowMap
) {
    forall u: int, v: int ::
        (u, v) in f ==> (
            f[(u, v)] > 0 ==> (
                exists c: int ::
                    m_has_capacity(g, u, v, c)
                    && f[(u, v)] <= c
            )
        )
}

predicate m_is_conserved(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int
) {
    forall u: int ::
        0 <= u < |g| && u != s && u != t
        ==> m_total_flow_in(g, f, u) == m_total_flow_out(g, f, u)
}

predicate m_is_valid_flow(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int
) {
    m_respects_capacity(g, f)
    && m_is_conserved(g, f, s, t)
    && (forall u: int, v: int ::
            (u, v) in f ==> f[(u, v)] >= 0)
}

function m_flow_val(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int
): int {
    m_total_flow_out(g, f, s) - m_total_flow_in(g, f, s)
}

predicate m_is_max_flow(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int
) {
    m_is_valid_flow(g, f, s, t)
    && (forall other: FlowMap ::
            m_is_valid_flow(g, other, s, t)
            ==> m_flow_val(g, f, s) >= m_flow_val(g, other, s))
}

predicate m_goal(
    g: seq<seq<(int, int)>>,
    s: int,
    t: int,
    value: int
) {
    exists f: FlowMap ::
        m_is_max_flow(g, f, s, t)
        && m_flow_val(g, f, s) == value
}

lemma MHasCapacitySame(
    g: seq<seq<(int, int)>>,
    u: int,
    v: int,
    c: int
)
    ensures m_has_capacity(g, u, v, c)
        <==> has_capacity(g, u, v, c)
{
}

lemma MGetFlowSame(f: FlowMap, u: int, v: int)
    ensures m_get_flow(f, u, v) == get_flow(f, u, v)
{
}

lemma MSumOutSame(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int,
    idx: int
)
    ensures m_sum_flow_out(g, f, u, idx)
        == sum_flow_out_recursive(g, f, u, idx)
    decreases idx
{
    if idx > 0 && 0 <= u < |g| {
        MSumOutSame(g, f, u, idx - 1);
        if idx - 1 < |g[u]| {
            MGetFlowSame(f, u, g[u][idx - 1].0);
        }
    }
}

lemma MSumInSame(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int,
    idx: int
)
    ensures m_sum_flow_in(g, f, u, idx)
        == sum_flow_in_recursive(g, f, u, idx)
    decreases idx
{
    if idx > 0 {
        MSumInSame(g, f, u, idx - 1);
        MGetFlowSame(f, idx - 1, u);
    }
}

lemma MTotalOutSame(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int
)
    ensures m_total_flow_out(g, f, u) == total_flow_out(g, f, u)
{
    if 0 <= u < |g| {
        MSumOutSame(g, f, u, |g[u]|);
    }
}

lemma MTotalInSame(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int
)
    ensures m_total_flow_in(g, f, u) == total_flow_in(g, f, u)
{
    MSumInSame(g, f, u, |g|);
}

lemma MRespectsSame(
    g: seq<seq<(int, int)>>,
    f: FlowMap
)
    ensures m_respects_capacity(g, f)
        <==> respects_capacity(g, f)
{
    assert forall u: int, v: int, c: int ::
        m_has_capacity(g, u, v, c)
        <==> has_capacity(g, u, v, c) by
    {
        forall u: int, v: int, c: int {
            MHasCapacitySame(g, u, v, c);
        }
    }
}

lemma MConservedSame(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int
)
    ensures m_is_conserved(g, f, s, t)
        <==> is_conserved(g, f, s, t)
{
    assert forall u: int ::
        m_total_flow_out(g, f, u) == total_flow_out(g, f, u) by
    {
        forall u: int {
            MTotalOutSame(g, f, u);
        }
    }

    assert forall u: int ::
        m_total_flow_in(g, f, u) == total_flow_in(g, f, u) by
    {
        forall u: int {
            MTotalInSame(g, f, u);
        }
    }
}

lemma MValidSame(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int
)
    ensures m_is_valid_flow(g, f, s, t)
        <==> is_valid_flow(g, f, s, t)
{
    MRespectsSame(g, f);
    MConservedSame(g, f, s, t);
}

lemma MFlowValueSame(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int
)
    ensures m_flow_val(g, f, s) == flow_val(g, f, s)
{
    MTotalOutSame(g, f, s);
    MTotalInSame(g, f, s);
}

lemma MMaxSame(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int
)
    ensures m_is_max_flow(g, f, s, t)
        <==> is_max_flow(g, f, s, t)
{
    MValidSame(g, f, s, t);
    MFlowValueSame(g, f, s);

    assert forall other: FlowMap ::
        (m_is_valid_flow(g, other, s, t)
            <==> is_valid_flow(g, other, s, t))
        && m_flow_val(g, other, s) == flow_val(g, other, s) by
    {
        forall other: FlowMap {
            MValidSame(g, other, s, t);
            MFlowValueSame(g, other, s);
        }
    }
}

lemma EmptyOut(
    g: seq<seq<(int, int)>>,
    u: int,
    idx: int
)
    ensures sum_flow_out_recursive(g, map[], u, idx) == 0
    decreases idx
{
    if idx > 0 && 0 <= u < |g| {
        EmptyOut(g, u, idx - 1);
        assert get_flow(map[], u, g[u][idx - 1].0) == 0
            || idx - 1 >= |g[u]|;
    }
}

