lemma FindMaximumFlowValue(
    g: seq<seq<(int, int)>>,
    s: int,
    t: int,
    bound: int
)
    requires 0 <= bound
    requires FeasibleFlowValue(g, s, t, 0)
    requires forall f: FlowMap ::
        is_valid_flow(g, f, s, t)
        ==> flow_val(g, f, s) <= bound
    ensures exists f: FlowMap :: is_max_flow(g, f, s, t)
    decreases bound
{
    if FeasibleFlowValue(g, s, t, bound) {
        ghost var f: FlowMap :|
            is_valid_flow(g, f, s, t)
            && flow_val(g, f, s) == bound;

        assert forall other: FlowMap
            {:trigger is_valid_flow(g, other, s, t)} ::
            is_valid_flow(g, other, s, t)
            ==> flow_val(g, f, s) >= flow_val(g, other, s) by
        {
            forall other: FlowMap
                | is_valid_flow(g, other, s, t)
            {
                assert flow_val(g, other, s) <= bound;
            }
        }

        assert is_max_flow(g, f, s, t);
    } else {
        if bound == 0 {
            assert FeasibleFlowValue(g, s, t, bound);
            assert false;
        }

        assert forall f: FlowMap ::
            is_valid_flow(g, f, s, t)
            ==> flow_val(g, f, s) <= bound - 1 by
        {
            forall f: FlowMap
                | is_valid_flow(g, f, s, t)
