lemma lemma_edge_at_index(graph: WeightedGraph, u: int, i: int)
    requires well_formed(graph)
    requires weights_non_negative(view(graph))
    requires 0 <= u < size(graph)
    requires 0 <= i < |graph.adj[u]|
    ensures 0 <= graph.adj[u][i].0 < size(graph)
    ensures has_edge(view(graph), u, graph.adj[u][i].0, graph.adj[u][i].1)
    ensures connected(view(graph), u, graph.adj[u][i].0)
    ensures get_edge_weight(view(graph), u, graph.adj[u][i].0) == graph.adj[u][i].1
    ensures graph.adj[u][i].1 >= 0
{
    var g := view(graph);
    var v := g[u][i].0;
    var w := g[u][i].1;
    assert 0 <= v < |g|;
    assert has_edge(g, u, v, w);
    assert connected(g, u, v);
    var w' := get_edge_weight(g, u, v);
    assert has_edge(g, u, v, w');
    var j :| 0 <= j < |g[u]| && g[u][j].0 == v && g[u][j].1 == w';
    if i != j {
        assert g[u][i].0 != g[u][j].0;
    }
    assert i == j;
    assert w' == w;
}

lemma lemma_connected_edge(graph: WeightedGraph, u: int, v: int)
    requires well_formed(graph)
    requires weights_non_negative(view(graph))
    requires connected(view(graph), u, v)
    ensures 0 <= u < size(graph)
    ensures 0 <= v < size(graph)
    ensures get_edge_weight(view(graph), u, v) >= 0
    ensures exists i: int :: 0 <= i < |graph.adj[u]| && graph.adj[u][i].0 == v && graph.adj[u][i].1 == get_edge_weight(view(graph), u, v)
{
