lemma lemma_extend_path(g: seq<seq<(int, int)>>, p: seq<int>, start: int, u: int, v: int)
    requires is_path(g, p)
    requires p[0] == start
    requires p[|p| - 1] == u
    requires connected(g, u, v)
    ensures |p + [v]| > 0
    ensures is_path(g, p + [v])
    ensures (p + [v])[0] == start
    ensures (p + [v])[|p + [v]| - 1] == v
    ensures path_weight(g, p + [v]) == path_weight(g, p) + get_edge_weight(g, u, v)
{
    var p' := p + [v];
    assert |p'| == |p| + 1;
    assert |p'| >= 2;
    assert p'[..|p'| - 1] == p;
    assert p'[|p'| - 2] == u;
    assert p'[|p'| - 1] == v;
    forall i: int | 0 <= i < |p'| - 1
        ensures connected(g, p'[i], p'[i + 1])
    {
        if i < |p| - 1 {
            assert p'[i] == p[i];
            assert p'[i + 1] == p[i + 1];
            assert connected(g, p[i], p[i + 1]);
        } else {
            assert i == |p| - 1;
            assert p'[i] == u;
            assert p'[i + 1] == v;
        }
    }
}

lemma lemma_path_lower_bound(
    graph: WeightedGraph,
    start: int,
    res: seq<Option<int>>,
    p: seq<int>
)
    requires well_formed(graph)
    requires weights_non_negative(view(graph))
    requires 0 <= start < size(graph)
    requires |res| == size(graph)
    requires res[start] == Some(0)
