        0 <= u < size(graph) && 0 <= v < size(graph) && res[u].Some? && connected(view(graph), u, v) ==>
            res[v].Some? && res[v].value <= res[u].value + get_edge_weight(view(graph), u, v)
    requires is_path(view(graph), p)
    requires p[0] == start
    ensures 0 <= p[|p| - 1] < size(graph)
    ensures res[p[|p| - 1]].Some?
    ensures path_weight(view(graph), p) >= res[p[|p| - 1]].value
    decreases |p|
