            res[v].Some? && res[v].value <= res[u].value + get_edge_weight(g, u, v)
        invariant done ==> (forall v: int :: 0 <= v < n && res[v].Some? ==> visited[v])
        decreases |unvisited|, if done then 0 else 1
    {
