            invariant best_u == -1 || (0 <= best_u < idx && !visited[best_u] && res[best_u].Some?)
            invariant best_u == -1 ==> (forall w: int :: 0 <= w < idx && !visited[w] ==> res[w].None?)
            invariant best_u != -1 ==> (forall w: int :: 0 <= w < idx && !visited[w] && res[w].Some? ==> res[best_u].value <= res[w].value)
            decreases n - idx
