                    best_u := idx;
                }
            }
            idx := idx + 1;
        }

        if best_u == -1 {
            done := true;
        } else {
            var u := best_u;
            assert u in unvisited;
            visited := visited[u := true];
            unvisited := unvisited - {u};

            var edges := graph.adj[u];
            var i := 0;
            while i < |edges|
                invariant 0 <= i <= |edges|
                invariant |res| == n
                invariant |paths| == n
                invariant res[start] == Some(0)
                invariant visited[u] && res[u].Some?
                invariant forall x: int :: 0 <= x < n && visited[x] ==> res[x].Some? && res[x].value <= res[u].value
                invariant forall v: int :: 0 <= v < n && res[v].Some? ==>
                    |paths[v]| > 0
                    && res[v].value >= 0
                    && is_path(g, paths[v])
                    && paths[v][0] == start
                    && paths[v][|paths[v]| - 1] == v
                    && path_weight(g, paths[v]) == res[v].value
                invariant forall x: int, y: int :: 0 <= x < n && 0 <= y < n && visited[x] && !visited[y] && res[y].Some? ==>
                    res[x].value <= res[y].value
                invariant forall x: int, y: int :: 0 <= x < n && 0 <= y < n && visited[x] && x != u && connected(g, x, y) ==>
                    res[y].Some? && res[y].value <= res[x].value + get_edge_weight(g, x, y)
                invariant forall j: int :: 0 <= j < i ==>
                    0 <= edges[j].0 < n && res[edges[j].0].Some? && res[edges[j].0].value <= res[u].value + edges[j].1
                decreases |edges| - i
            {
                var v := edges[i].0;
                var w := edges[i].1;
                lemma_edge_at_index(graph, u, i);
                if res[v].None? || res[u].value + w < res[v].value {
                    assert !visited[v];
                    assert v != start;
                    lemma_extend_path(g, paths[u], start, u, v);
                    res := res[v := Some(res[u].value + w)];
                    paths := paths[v := paths[u] + [v]];
                }
                i := i + 1;
            }

            forall x: int, y: int | 0 <= x < n && 0 <= y < n && visited[x] && connected(g, x, y)
                ensures res[y].Some? && res[y].value <= res[x].value + get_edge_weight(g, x, y)
            {
                if x == u {
                    lemma_connected_edge(graph, u, y);
                    var j :| 0 <= j < |edges| && edges[j].0 == y && edges[j].1 == get_edge_weight(g, u, y);
                    assert res[edges[j].0].Some? && res[edges[j].0].value <= res[u].value + edges[j].1;
                }
            }
        }
    }

    forall v: int | 0 <= v < n
        ensures match res[v] {
            case Some(d) =>
                is_shortest_dist(g, start, v, d)
            case None =>
                forall p: seq<int> {:trigger is_path(g, p)} ::
                    is_path(g, p) && p[0] == start && p[|p| - 1] == v ==> false
        }
    {
        match res[v] {
            case Some(d) =>
                assert is_path(g, paths[v]);
                assert paths[v][0] == start && paths[v][|paths[v]| - 1] == v && path_weight(g, paths[v]) == d;
                forall p: seq<int> {:trigger is_path(g, p)} | is_path(g, p) && p[0] == start && p[|p| - 1] == v
                    ensures path_weight(g, p) >= d
                {
                    lemma_path_lower_bound(graph, start, res, p);
                }
            case None =>
                forall p: seq<int> {:trigger is_path(g, p)} | is_path(g, p) && p[0] == start && p[|p| - 1] == v
                    ensures false
                {
                    lemma_path_lower_bound(graph, start, res, p);
                }
        }
    }
