lemma MulPos(d: int, k: int)
  requires d > 0 && d * k >= 0
  ensures k >= 0
{
  if k < 0 {
    assert d * (-k) > 0;
    assert d * k == -(d * (-k));
  }
}

lemma DivMod(d: nat, x: nat, y: nat)
  requires y > 0
  ensures (divides(d, x) && divides(d, y)) <==> (divides(d, y) && divides(d, x % y))
{
  var q: nat := x / y;
  var r: nat := x % y;
  assert x == q * y + r;
  if divides(d, x) && divides(d, y) {
    var k1: nat :| d * k1 == x;
    var k2: nat :| d * k2 == y;
    assert d != 0 by {
      if d == 0 {
        assert d * k2 == 0;
      }
    }
    var k3: int := k1 - q * k2;
    assert d * k3 == r by {
      calc {
        d * k3;
        == d * k1 - d * (q * k2);
        == x - q * (d * k2);
        == x - q * y;
        == r;
      }
    }
    MulPos(d, k3);
    var k3n: nat := k3;
    assert d * k3n == r;
    assert divides(d, r);
  }
  if divides(d, y) && divides(d, r) {
    var k2: nat :| d * k2 == y;
    var k3: nat :| d * k3 == r;
    var k: nat := q * k2 + k3;
    calc {
      d * k;
      == d * (q * k2) + d * k3;
      == q * (d * k2) + r;
      == q * y + r;
      == x;
    }
    assert divides(d, x);
  }
}

lemma GcdX0(x: nat)
  requires x > 0
  ensures is_gcd(x, x, 0)
{
  assert x * 1 == x;
  assert divides(x, x);
  assert x * 0 == 0;
  assert divides(x, 0);
  forall d: nat | divides(d, x) && divides(d, 0)
    ensures d <= x
  {
    var k: nat :| d * k == x;
    assert k != 0;
    assert d * k == d + d * (k - 1);
    assert d * (k - 1) >= 0;
  }
}

lemma SpecEq(g: nat, a: nat, b: nat)
  requires is_gcd(g, a, b)
  ensures spec_gcd(a, b) == g
{
  if a == 0 && b == 0 {
    assert (g + 1) * 0 == 0;
    assert divides(g + 1, a) && divides(g + 1, b);
    assert false;
  } else {
    assert exists g': nat :: is_gcd(g', a, b);
    var h := spec_gcd(a, b);
    assert is_gcd(h, a, b);
    assert h <= g;
    assert g <= h;
  }
}

method compute_gcd(a: int, b: int) returns (res: int)
  // Simulate u64: inputs are non-negative
  requires a >= 0 && b >= 0
  ensures res == spec_gcd(a, b)
  // Result is unsigned
  ensures res >= 0
{
  var x: nat := a;
  var y: nat := b;
  while y != 0
    invariant forall d: nat :: (divides(d, x) && divides(d, y)) <==> (divides(d, a) && divides(d, b))
    decreases y
  {
    forall d: nat
      ensures (divides(d, x) && divides(d, y)) <==> (divides(d, y) && divides(d, x % y))
    {
      DivMod(d, x, y);
    }
    x, y := y, x % y;
  }
  res := x;
  if x == 0 {
    assert 0 * 0 == 0;
    assert divides(0, 0);
    assert divides(0, x) && divides(0, y);
    assert divides(0, a) && divides(0, b);
    assert a == 0;
    assert b == 0;
  } else {
    GcdX0(x);
    assert divides(x, x) && divides(x, y);
    assert divides(x, a) && divides(x, b);
    forall d: nat | divides(d, a) && divides(d, b)
      ensures d <= x
    {
      assert divides(d, x) && divides(d, 0);
    }
    assert is_gcd(x, a, b);
    SpecEq(x, a, b);
  }
}

