    assert exists ky: nat :: d * ky == y;

    var kr: nat :| d * kr == x - y;
    var ky: nat :| d * ky == y;
    var k: nat := kr + ky;

    assert (x - y) + y == x;

    calc {
      d * k == d * (kr + ky);
      _ == d * kr + d * ky;
      _ == (x - y) + y;
      _ == x;
