              && 0 <= i < |graph.adj[u]|
              && graph.adj[u][i].0 == v
              && graph.adj[u][i].1 == w1;
    var j :| 0 <= u < |graph.adj|
              && 0 <= j < |graph.adj[u]|
              && graph.adj[u][j].0 == v
              && graph.adj[u][j].1 == w2;

    if i != j {
        assert graph.adj[u][i].0 != graph.adj[u][j].0;
        assert false;
    }
}

