                    view(graph), p[|p| - 2], p[|p| - 1]
                );
        assert get_edge_weight(
            view(graph), p[|p| - 2], p[|p| - 1]
        ) == w;
        assert path_weight(view(graph), q)
            <= path_weight(view(graph), p);
    }
}

lemma SelectedVertexIsShortest(
    graph: WeightedGraph,
    start: int,
    dist: seq<Option<int>>,
    paths: seq<seq<int>>,
    done: set<int>,
    best: int
)
    requires well_formed(graph)
    requires weights_non_negative(view(graph))
    requires 0 <= start < size(graph)
    requires WitnessOK(graph, start, dist, paths)
    requires SettledOK(graph, start, dist, done)
    requires FrontierOK(graph, dist, done)
    requires dist[start] == Some(0)
    requires 0 <= best < size(graph)
    requires best !in done
    requires HasValue(dist[best])
    requires forall v: int ::
        0 <= v < size(graph)
        && v !in done
        && HasValue(dist[v])
        ==> OVal(dist[best]) <= OVal(dist[v])
    ensures is_shortest_dist(
        view(graph), start, best, OVal(dist[best])
    )
{
    assert is_path(view(graph), paths[best]);
    assert paths[best][0] == start;
    assert paths[best][|paths[best]| - 1] == best;
    assert path_weight(view(graph), paths[best]) == OVal(dist[best]);

    assert exists p: seq<int> {:trigger is_path(view(graph), p)} ::
        is_path(view(graph), p)
        && p[0] == start
        && p[|p| - 1] == best
        && path_weight(view(graph), p) == OVal(dist[best]);

    forall p: seq<int> {:trigger is_path(view(graph), p)}
        | is_path(view(graph), p)
          && p[0] == start
          && p[|p| - 1] == best
        ensures path_weight(view(graph), p) >= OVal(dist[best])
    {
        PathVerticesBounded(graph, p);

        if start !in done {
            assert HasValue(dist[start]);
            assert OVal(dist[start]) == 0;
            assert OVal(dist[best]) <= OVal(dist[start]);
            PathWeightNonnegative(graph, p);
        } else {
            var k := 0;
            while k < |p| && p[k] in done
                invariant 0 <= k <= |p|
                invariant forall j: int ::
                    0 <= j < k ==> p[j] in done
                decreases |p| - k
            {
                k := k + 1;
            }

            assert p[|p| - 1] == best;
            assert best !in done;
            assert k < |p|;
            assert p[k] !in done;
            assert k > 0;
            assert p[k - 1] in done;

            PrefixIsPath(graph, p, k);
            assert p[..k][0] == start;
            assert p[..k][|p[..k]| - 1] == p[k - 1];

            assert is_shortest_dist(
                view(graph), start, p[k - 1],
                OVal(dist[p[k - 1]])
            );
            assert path_weight(view(graph), p[..k])
                >= OVal(dist[p[k - 1]]);

            assert connected(view(graph), p[k - 1], p[k]);
            assert HasValue(dist[p[k]]);
            assert OVal(dist[p[k]])
                <= OVal(dist[p[k - 1]])
                    + get_edge_weight(
                        view(graph), p[k - 1], p[k]
                    );

            assert OVal(dist[best]) <= OVal(dist[p[k]]);

            var w :| has_edge(
                view(graph), p[k - 1], p[k], w
            );
            GetEdgeWeightLemma(graph, p[k - 1], p[k], w);

            PrefixIsPath(graph, p, k + 1);
            assert p[..k + 1] == p[..k] + [p[k]];
            AppendEdgeLemma(graph, p[..k], p[k], w);
            PrefixWeightAtMostPath(graph, p, k + 1);

            assert path_weight(view(graph), p[..k + 1])
                == path_weight(view(graph), p[..k]) + w;
        }
    }
}

lemma NoTentativeMeansUnreachable(
    graph: WeightedGraph,
    start: int,
    dist: seq<Option<int>>,
    done: set<int>
)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    requires |dist| == size(graph)
    requires HasValue(dist[start])
    requires FrontierOK(graph, dist, done)
    requires forall v: int ::
        0 <= v < size(graph) && v !in done
        ==> !HasValue(dist[v])
    ensures forall v: int ::
        0 <= v < size(graph) && v !in done ==>
            forall p: seq<int> {:trigger is_path(view(graph), p)} ::
                is_path(view(graph), p)
                && p[0] == start
                && p[|p| - 1] == v
                ==> false
{
    assert start in done;

    forall v: int | 0 <= v < size(graph) && v !in done
        ensures forall p: seq<int> {:trigger is_path(view(graph), p)} ::
            is_path(view(graph), p)
            && p[0] == start
            && p[|p| - 1] == v
            ==> false
    {
        forall p: seq<int> {:trigger is_path(view(graph), p)}
            | is_path(view(graph), p)
              && p[0] == start
              && p[|p| - 1] == v
            ensures false
        {
            PathVerticesBounded(graph, p);

            var k := 0;
            while k < |p| && p[k] in done
                invariant 0 <= k <= |p|
                invariant forall j: int ::
                    0 <= j < k ==> p[j] in done
                decreases |p| - k
            {
                k := k + 1;
            }

            assert k < |p|;
            assert k > 0;
            assert p[k - 1] in done;
            assert p[k] !in done;
            assert connected(view(graph), p[k - 1], p[k]);
            assert HasValue(dist[p[k]]);
            assert false;
        }
    }
}

lemma BoundedSetCardinality(s: set<int>, n: int)
    requires 0 <= n
    requires forall x: int :: x in s ==> 0 <= x < n
    ensures |s| <= n
    decreases n
{
    if n == 0 {
        assert s == {};
    } else {
        var t := set x: int | x in s && x < n - 1;
        BoundedSetCardinality(t, n - 1);

        if n - 1 in s {
            assert s == t + {n - 1};
            assert |s| == |t| + 1;
        } else {
            assert s == t;
        }
    }
}

method RelaxFrom(
    graph: WeightedGraph,
    start: int,
    dist: seq<Option<int>>,
    paths: seq<seq<int>>,
    done: set<int>,
    u: int
) returns (
    newDist: seq<Option<int>>,
    newPaths: seq<seq<int>>
)
    requires well_formed(graph)
    requires weights_non_negative(view(graph))
    requires 0 <= start < size(graph)
    requires WitnessOK(graph, start, dist, paths)
    requires SettledOK(graph, start, dist, done)
    requires start in done
    requires dist[start] == Some(0)
    requires u in done
    requires FrontierExcept(graph, dist, done, u)
    ensures WitnessOK(graph, start, newDist, newPaths)
    ensures SettledOK(graph, start, newDist, done)
    ensures FrontierOK(graph, newDist, done)
    ensures newDist[start] == Some(0)
    ensures forall v: int ::
        0 <= v < size(graph) && HasValue(dist[v]) ==>
            HasValue(newDist[v])
            && OVal(newDist[v]) <= OVal(dist[v])
{
    newDist := dist;
    newPaths := paths;
    var i := 0;

    while i < |graph.adj[u]|
        invariant 0 <= i <= |graph.adj[u]|
        invariant WitnessOK(graph, start, newDist, newPaths)
        invariant SettledOK(graph, start, newDist, done)
        invariant FrontierExcept(graph, newDist, done, u)
        invariant newDist[start] == Some(0)
        invariant forall v: int ::
            0 <= v < size(graph) && HasValue(dist[v]) ==>
                HasValue(newDist[v])
                && OVal(newDist[v]) <= OVal(dist[v])
        invariant forall j: int ::
            0 <= j < i ==>
                HasValue(newDist[graph.adj[u][j].0])
                && OVal(newDist[graph.adj[u][j].0])
                    <= OVal(newDist[u]) + graph.adj[u][j].1
        decreases |graph.adj[u]| - i
    {
        var v := graph.adj[u][i].0;
        var w := graph.adj[u][i].1;

        assert 0 <= v < size(graph);
        assert has_edge(view(graph), u, v, w);
        GetEdgeWeightLemma(graph, u, v, w);
        assert w >= 0;

        if v in done {
            assert is_shortest_dist(
                view(graph), start, v, OVal(newDist[v])
            );
            AppendEdgeLemma(graph, newPaths[u], v, w);
            assert path_weight(
                view(graph), newPaths[u] + [v]
            ) == OVal(newDist[u]) + w;
            assert path_weight(
                view(graph), newPaths[u] + [v]
            ) >= OVal(newDist[v]);
            assert OVal(newDist[v])
                <= OVal(newDist[u]) + w;
        } else {
            assert v != start;
            var nd := OVal(newDist[u]) + w;
            if !HasValue(newDist[v]) || nd < OVal(newDist[v]) {
                var oldDist := newDist;
                var oldPaths := newPaths;
                var q := oldPaths[u] + [v];

                AppendEdgeLemma(graph, oldPaths[u], v, w);
                newDist := oldDist[v := Some(nd)];
                newPaths := oldPaths[v := q];

                assert newDist[start] == Some(0);

                assert WitnessOK(
                    graph, start, newDist, newPaths
                ) by {
                    forall x: int
                        | 0 <= x < size(graph)
                          && HasValue(newDist[x])
                        ensures
                            is_path(view(graph), newPaths[x])
                            && newPaths[x][0] == start
                            && newPaths[x][|newPaths[x]| - 1] == x
                            && path_weight(
                                view(graph), newPaths[x]
                            ) == OVal(newDist[x])
                    {
                        if x == v {
                            assert newPaths[x] == q;
                            assert newDist[x] == Some(nd);
                        } else {
                            assert newPaths[x] == oldPaths[x];
                            assert newDist[x] == oldDist[x];
                        }
                    }
                }

                assert SettledOK(
                    graph, start, newDist, done
                ) by {
                    forall x: int | x in done
                        ensures
                            0 <= x < size(graph)
                            && HasValue(newDist[x])
                            && is_shortest_dist(
                                view(graph), start, x,
                                OVal(newDist[x])
                            )
                    {
                        assert x != v;
                        assert newDist[x] == oldDist[x];
                    }
                }

                assert FrontierExcept(
                    graph, newDist, done, u
                ) by {
                    forall x: int, y: int
                        | x in done
                          && x != u
                          && 0 <= x < size(graph)
                          && 0 <= y < size(graph)
                          && connected(view(graph), x, y)
                        ensures
                            HasValue(newDist[x])
                            && HasValue(newDist[y])
                            && OVal(newDist[y])
                                <= OVal(newDist[x])
                                  + get_edge_weight(
                                      view(graph), x, y
                                  )
                    {
                        assert x != v;
                        if y == v {
                            assert HasValue(oldDist[y]);
                            assert OVal(newDist[y])
                                <= OVal(oldDist[y]);
                            assert newDist[x] == oldDist[x];
                        } else {
                            assert newDist[x] == oldDist[x];
                            assert newDist[y] == oldDist[y];
                        }
                    }
                }
            }
        }

        i := i + 1;
    }

    assert FrontierOK(graph, newDist, done) by {
        forall x: int, v: int
            | x in done
              && 0 <= x < size(graph)
              && 0 <= v < size(graph)
              && connected(view(graph), x, v)
            ensures
                HasValue(newDist[x])
                && HasValue(newDist[v])
                && OVal(newDist[v])
                    <= OVal(newDist[x])
                      + get_edge_weight(view(graph), x, v)
        {
            if x != u {
            } else {
                var w :| has_edge(view(graph), u, v, w);
                var j :| 0 <= u < |graph.adj|
                          && 0 <= j < |graph.adj[u]|
                          && graph.adj[u][j].0 == v
                          && graph.adj[u][j].1 == w;
                assert j < |graph.adj[u]|;
                GetEdgeWeightLemma(graph, u, v, w);
            }
        }
    }
}

method dijkstra_shortest_paths(
    graph: WeightedGraph,
    start: int
) returns (res: seq<Option<int>>)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    requires weights_non_negative(view(graph))
    requires weights_and_size_bounded(view(graph))
    ensures |res| == size(graph)
    ensures forall v: int :: 0 <= v < size(graph) ==>
        match res[v] {
            case Some(d) =>
                is_shortest_dist(view(graph), start, v, d)
            case None =>
                forall p: seq<int> {:trigger is_path(view(graph), p)} ::
                    is_path(view(graph), p)
                    && p[0] == start
                    && p[|p| - 1] == v
                    ==> false
        }
{
    var n := |graph.adj|;
    var dist := seq(n, i =>
        if i == start then Some(0) else None);
    var paths := seq(n, i =>
        if i == start then [start] else []);
    var done: set<int> := {};
    var count := 0;
    var stuck := false;

    assert n == size(graph);
    assert is_path(view(graph), [start]);
    assert WitnessOK(graph, start, dist, paths);
    assert SettledOK(graph, start, dist, done);
    assert FrontierOK(graph, dist, done);
    assert dist[start] == Some(0);

    while count < n && !stuck
        invariant n == |graph.adj|
        invariant n == size(graph)
        invariant |dist| == n
        invariant |paths| == n
        invariant WitnessOK(graph, start, dist, paths)
        invariant SettledOK(graph, start, dist, done)
        invariant FrontierOK(graph, dist, done)
        invariant dist[start] == Some(0)
        invariant forall v: int :: v in done ==> 0 <= v < n
        invariant count == |done|
        invariant 0 <= count <= n
        invariant done != {} ==> start in done
        invariant done == {} ==>
            forall v: int ::
                0 <= v < n ==> (HasValue(dist[v]) <==> v == start)
        invariant stuck ==>
            forall v: int ::
                0 <= v < n && v !in done ==>
                    !HasValue(dist[v])
        decreases n - count, if stuck then 0 else 1
    {
        var found := false;
        var best := -1;
        var bestDistance := 0;
        var i := 0;

        while i < n
            invariant 0 <= i <= n
            invariant found ==>
                0 <= best < n
                && best !in done
                && HasValue(dist[best])
                && bestDistance == OVal(dist[best])
            invariant forall v: int ::
                0 <= v < i
                && v !in done
                && HasValue(dist[v])
                ==> found && bestDistance <= OVal(dist[v])
            decreases n - i
        {
            if i !in done && HasValue(dist[i]) {
                if !found || OVal(dist[i]) < bestDistance {
                    found := true;
                    best := i;
                    bestDistance := OVal(dist[i]);
                }
            }
            i := i + 1;
        }

        if !found {
            assert forall v: int ::
                0 <= v < n && v !in done ==>
                    !HasValue(dist[v]);
            stuck := true;
        } else {
            assert forall v: int ::
                0 <= v < n
                && v !in done
                && HasValue(dist[v])
                ==> OVal(dist[best]) <= OVal(dist[v]);

            SelectedVertexIsShortest(
                graph, start, dist, paths, done, best
            );

            assert done == {} ==> best == start;
            assert done != {} ==> start in done;

            var oldDone := done;
            done := done + {best};
            count := count + 1;

            assert |done| == |oldDone| + 1;
            assert start in done;

            assert SettledOK(graph, start, dist, done) by {
                forall x: int | x in done
                    ensures
                        0 <= x < size(graph)
                        && HasValue(dist[x])
                        && is_shortest_dist(
                            view(graph), start, x, OVal(dist[x])
                        )
                {
                    if x == best {
                    } else {
                        assert x in oldDone;
                    }
                }
            }

            assert FrontierExcept(
                graph, dist, done, best
            ) by {
                forall x: int, v: int
                    | x in done
                      && x != best
                      && 0 <= x < size(graph)
                      && 0 <= v < size(graph)
                      && connected(view(graph), x, v)
                    ensures
                        HasValue(dist[x])
                        && HasValue(dist[v])
                        && OVal(dist[v])
                            <= OVal(dist[x])
                              + get_edge_weight(view(graph), x, v)
                {
                    assert x in oldDone;
                }
            }

            dist, paths := RelaxFrom(
                graph, start, dist, paths, done, best
            );
            assert dist[start] == Some(0);
        }
    }

    if stuck {
        NoTentativeMeansUnreachable(
            graph, start, dist, done
        );
    } else {
        assert count == n;
        assert |done| == n;
        BoundedSetCardinality(done, n);

        forall v: int | 0 <= v < n
            ensures v in done
        {
            if v !in done {
                var larger := done + {v};
                assert |larger| == |done| + 1;
                assert forall x: int ::
                    x in larger ==> 0 <= x < n;
                BoundedSetCardinality(larger, n);
                assert false;
            }
        }
    }

    assert stuck || (forall v: int :: 0 <= v < n ==> v in done);

    res := dist;

    forall v: int | 0 <= v < n
        ensures
            match res[v]
            case Some(d) =>
                is_shortest_dist(view(graph), start, v, d)
            case None =>
                forall p: seq<int> {:trigger is_path(view(graph), p)} ::
                    is_path(view(graph), p)
                    && p[0] == start
                    && p[|p| - 1] == v
                    ==> false
    {
        if v in done {
            assert HasValue(res[v]);
            assert is_shortest_dist(
                view(graph), start, v, OVal(res[v])
            );
        } else {
            assert stuck;
            assert !HasValue(res[v]);
            NoTentativeMeansUnreachable(
                graph, start, res, done
            );
        }
    }
}

