ghost predicate common_divisor(d: nat, a: nat, b: nat)
{
  divides(d, a) && divides(d, b)
}

lemma divides_zero(d: nat)
  ensures divides(d, 0)
{
  var k: nat := 0;
  assert d * k == 0;
  assert divides(d, 0);
}

lemma divides_self(n: nat)
  ensures divides(n, n)
{
  var k: nat := 1;
  assert n * k == n;
  assert divides(n, n);
}

lemma multiplication_strictly_monotone(c: nat, p: nat, q: nat)
  requires c > 0
  requires p < q
  ensures c * p < c * q
{
  var t: nat := q - p;
  var s: nat := t - 1;

  assert t > 0;
  assert t == s + 1;
  assert q == p + t;

  calc {
    c * p;
    < c * p + c;
    <= c * p + c * s + c;
    == c * p + c * (s + 1);
    == c * p + c * t;
    == c * (p + t);
    == c * q;
  }
}

lemma divisor_bound(d: nat, n: nat)
  requires n > 0
  requires divides(d, n)
  ensures d <= n
{
  assert exists k: nat :: d * k == n;
  var k: nat :| d * k == n;

  assert d > 0;
  assert k > 0;

  if k == 1 {
    assert d == n;
  } else {
    assert 1 < k;
    multiplication_strictly_monotone(d, 1, k);
    assert d * 1 < d * k;
  }
}

lemma divides_difference(d: nat, x: nat, y: nat)
  requires y <= x
  ensures common_divisor(d, x, y)
       <==> common_divisor(d, x - y, y)
{
  if common_divisor(d, x, y) {
    assert exists kx: nat :: d * kx == x;
    assert exists ky: nat :: d * ky == y;

    var kx: nat :| d * kx == x;
    var ky: nat :| d * ky == y;

    if d == 0 {
      assert x == 0;
      assert y == 0;
      assert x - y == 0;
      divides_zero(d);
      assert divides(d, x - y);
    } else {
      assert ky <= kx by {
        if ky > kx {
          multiplication_strictly_monotone(d, kx, ky);
          assert d * kx < d * ky;
          assert false;
        }
      }

      var k: nat := kx - ky;
      assert kx == ky + k;

      calc {
        x;
        == d * kx;
        == d * (ky + k);
        == d * ky + d * k;
        == y + d * k;
      }

      assert d * k == x - y;
      assert divides(d, x - y);
    }

    assert common_divisor(d, x - y, y);
  }

  if common_divisor(d, x - y, y) {
    assert exists kr: nat :: d * kr == x - y;
    assert exists ky: nat :: d * ky == y;

    var kr: nat :| d * kr == x - y;
    var ky: nat :| d * ky == y;
    var k: nat := kr + ky;

    assert (x - y) + y == x;

    calc {
      d * k;
      == d * (kr + ky);
      == d * kr + d * ky;
      == (x - y) + y;
      == x;
    }

    assert divides(d, x);
    assert common_divisor(d, x, y);
  }
}

lemma replace_first_number(x: nat, y: nat, a: nat, b: nat)
  requires y < x
  requires forall d: nat ::
    common_divisor(d, x, y) <==> common_divisor(d, a, b)
  ensures forall d: nat ::
    common_divisor(d, x - y, y) <==> common_divisor(d, a, b)
{
  forall d: nat
    ensures common_divisor(d, x - y, y)
         <==> common_divisor(d, a, b)
  {
    assert common_divisor(d, x, y)
         <==> common_divisor(d, a, b);
    divides_difference(d, x, y);
  }
}

