      == d * kr + d * ky;
      == (x - y) + y;
      == x;
    }

    assert divides(d, x);
    assert common_divisor(d, x, y);
  }
}

lemma replace_first_number(x: nat, y: nat, a: nat, b: nat)
  requires y < x
  requires forall d: nat ::
    common_divisor(d, x, y) <==> common_divisor(d, a, b)
  ensures forall d: nat ::
    common_divisor(d, x - y, y) <==> common_divisor(d, a, b)
{
  forall d: nat
    ensures common_divisor(d, x - y, y)
         <==> common_divisor(d, a, b)
  {
    assert common_divisor(d, x, y)
         <==> common_divisor(d, a, b);
    divides_difference(d, x, y);
  }
}

lemma replace_second_number(x: nat, y: nat, a: nat, b: nat)
  requires x < y
  requires forall d: nat ::
    common_divisor(d, x, y) <==> common_divisor(d, a, b)
  ensures forall d: nat ::
    common_divisor(d, x, y - x) <==> common_divisor(d, a, b)
{
  forall d: nat
    ensures common_divisor(d, x, y - x)
         <==> common_divisor(d, a, b)
  {
    assert common_divisor(d, x, y)
         <==> common_divisor(d, a, b);
    assert common_divisor(d, y, x)
         <==> common_divisor(d, x, y);

    divides_difference(d, y, x);

    assert common_divisor(d, y - x, x)
         <==> common_divisor(d, y, x);
    assert common_divisor(d, x, y - x)
         <==> common_divisor(d, y - x, x);
  }
}

lemma gcd_with_zero_left(n: nat)
  requires n > 0
  ensures is_gcd(n, 0, n)
{
  divides_zero(n);
  divides_self(n);

  forall d: nat
    ensures divides(d, 0) && divides(d, n) ==> d <= n
  {
    if divides(d, 0) && divides(d, n) {
      divisor_bound(d, n);
    }
  }

  assert is_gcd(n, 0, n);
}

lemma gcd_with_zero_right(n: nat)
  requires n > 0
  ensures is_gcd(n, n, 0)
{
  divides_self(n);
  divides_zero(n);

  forall d: nat
    ensures divides(d, n) && divides(d, 0) ==> d <= n
  {
    if divides(d, n) && divides(d, 0) {
      divisor_bound(d, n);
    }
  }

  assert is_gcd(n, n, 0);
}

lemma unique_gcd(g: nat, h: nat, a: nat, b: nat)
  requires is_gcd(g, a, b)
  requires is_gcd(h, a, b)
  ensures g == h
{
  assert divides(g, a) && divides(g, b);
  assert divides(h, a) && divides(h, b);
  assert g <= h;
  assert h <= g;
}

lemma gcd_matches_spec(g: nat, a: nat, b: nat)
  requires a > 0 || b > 0
  requires is_gcd(g, a, b)
  ensures g == spec_gcd(a, b)
{
  assert !(a == 0 && b == 0);
  assert exists h: nat :: is_gcd(h, a, b);
  assert is_gcd(spec_gcd(a, b), a, b);
  unique_gcd(g, spec_gcd(a, b), a, b);
}

method compute_gcd(a: int, b: int) returns (res: int)
  // Simulate u64: inputs are non-negative
  requires a >= 0 && b >= 0
  ensures res == spec_gcd(a, b)
  // Result is unsigned
  ensures res >= 0
{
  var aa: nat := a;
  var bb: nat := b;

  if aa == 0 && bb == 0 {
    res := 0;
    assert spec_gcd(aa, bb) == 0;
    return;
  }

  if aa == 0 {
    assert bb > 0;
    gcd_with_zero_left(bb);
    gcd_matches_spec(bb, aa, bb);
    res := bb;
    return;
  }

  if bb == 0 {
    assert aa > 0;
    gcd_with_zero_right(aa);
    gcd_matches_spec(aa, aa, bb);
    res := aa;
    return;
  }

  var x: nat := aa;
  var y: nat := bb;

  while x != y
    invariant x > 0
    invariant y > 0
    invariant forall d: nat ::
      common_divisor(d, x, y) <==> common_divisor(d, aa, bb)
    decreases x + y
  {
    if x > y {
      replace_first_number(x, y, aa, bb);
      x := x - y;
    } else {
      assert x < y;
      replace_second_number(x, y, aa, bb);
      y := y - x;
    }
  }

  assert x == y;
  divides_self(x);
  assert divides(x, x);
  assert divides(x, y);
  assert common_divisor(x, x, y);
  assert common_divisor(x, aa, bb);
  assert divides(x, aa);
  assert divides(x, bb);

  forall d: nat
    ensures divides(d, aa) && divides(d, bb) ==> d <= x
  {
    if divides(d, aa) && divides(d, bb) {
      assert common_divisor(d, aa, bb);
      assert common_divisor(d, x, y);
      assert divides(d, x);
      divisor_bound(d, x);
    }
  }

  assert forall d: nat ::
    divides(d, aa) && divides(d, bb) ==> d <= x;
  assert is_gcd(x, aa, bb);
  gcd_matches_spec(x, aa, bb);

  res := x;
}
