function HasValue(o: Option<int>): bool {
    match o
    case Some(_) => true
    case None => false
}

function OVal(o: Option<int>): int
    requires HasValue(o)
{
    match o
    case Some(x) => x
    case None => 0
}

ghost predicate WitnessOK(
    graph: WeightedGraph,
    start: int,
    dist: seq<Option<int>>,
    paths: seq<seq<int>>
) {
    |dist| == size(graph)
    && |paths| == size(graph)
    && forall v: int ::
        0 <= v < size(graph) && HasValue(dist[v]) ==>
            is_path(view(graph), paths[v])
            && paths[v][0] == start
            && paths[v][|paths[v]| - 1] == v
            && path_weight(view(graph), paths[v]) == OVal(dist[v])
}

ghost predicate SettledOK(
    graph: WeightedGraph,
    start: int,
    dist: seq<Option<int>>,
    done: set<int>
) {
    |dist| == size(graph)
    && forall v: int ::
        v in done ==>
            0 <= v < size(graph)
            && HasValue(dist[v])
            && is_shortest_dist(view(graph), start, v, OVal(dist[v]))
}

ghost predicate FrontierOK(
    graph: WeightedGraph,
    dist: seq<Option<int>>,
    done: set<int>
) {
    |dist| == size(graph)
    && forall u: int, v: int ::
        u in done
        && 0 <= u < size(graph)
        && 0 <= v < size(graph)
        && connected(view(graph), u, v)
        ==>
            HasValue(dist[u])
            && HasValue(dist[v])
            && OVal(dist[v])
                <= OVal(dist[u]) + get_edge_weight(view(graph), u, v)
}

ghost predicate FrontierExcept(
    graph: WeightedGraph,
    dist: seq<Option<int>>,
    done: set<int>,
    except: int
) {
    |dist| == size(graph)
    && forall u: int, v: int ::
        u in done
        && u != except
        && 0 <= u < size(graph)
        && 0 <= v < size(graph)
        && connected(view(graph), u, v)
        ==>
            HasValue(dist[u])
            && HasValue(dist[v])
            && OVal(dist[v])
                <= OVal(dist[u]) + get_edge_weight(view(graph), u, v)
}

lemma EdgeWeightUnique(
    graph: WeightedGraph,
    u: int,
    v: int,
    w1: int,
    w2: int
)
    requires well_formed(graph)
    requires has_edge(view(graph), u, v, w1)
    requires has_edge(view(graph), u, v, w2)
    ensures w1 == w2
{
    var i :| 0 <= u < |graph.adj|
              && 0 <= i < |graph.adj[u]|
              && graph.adj[u][i].0 == v
              && graph.adj[u][i].1 == w1;
    var j :| 0 <= u < |graph.adj|
              && 0 <= j < |graph.adj[u]|
              && graph.adj[u][j].0 == v
              && graph.adj[u][j].1 == w2;

    if i != j {
        assert graph.adj[u][i].0 != graph.adj[u][j].0;
        assert false;
    }
}

lemma GetEdgeWeightLemma(
    graph: WeightedGraph,
    u: int,
    v: int,
    w: int
)
    requires well_formed(graph)
    requires has_edge(view(graph), u, v, w)
    ensures get_edge_weight(view(graph), u, v) == w
{
    assert exists x: int :: has_edge(view(graph), u, v, x);
    assert has_edge(
        view(graph), u, v,
        get_edge_weight(view(graph), u, v)
    );
    EdgeWeightUnique(
        graph, u, v, w,
        get_edge_weight(view(graph), u, v)
    );
}

lemma PrefixIsPath(
    graph: WeightedGraph,
    p: seq<int>,
    k: int
)
    requires is_path(view(graph), p)
    requires 1 <= k <= |p|
    ensures is_path(view(graph), p[..k])
{
    assert |p[..k]| > 0;
    forall i: int | 0 <= i < |p[..k]| - 1
        ensures connected(view(graph), p[..k][i], p[..k][i + 1])
    {
        assert p[..k][i] == p[i];
        assert p[..k][i + 1] == p[i + 1];
    }
}

lemma PathVerticesBounded(
    graph: WeightedGraph,
    p: seq<int>
)
    requires well_formed(graph)
    requires is_path(view(graph), p)
    requires 0 <= p[0] < size(graph)
    ensures forall i: int :: 0 <= i < |p| ==>
        0 <= p[i] < size(graph)
{
    forall i: int | 0 <= i < |p|
        ensures 0 <= p[i] < size(graph)
    {
        if i == 0 {
        } else {
            assert connected(view(graph), p[i - 1], p[i]);
            var w :| has_edge(view(graph), p[i - 1], p[i], w);
            var j :| 0 <= p[i - 1] < |graph.adj|
                      && 0 <= j < |graph.adj[p[i - 1]]|
                      && graph.adj[p[i - 1]][j].0 == p[i]
                      && graph.adj[p[i - 1]][j].1 == w;
            assert 0 <= graph.adj[p[i - 1]][j].0 < |graph.adj|;
        }
    }
}

lemma AppendEdgeLemma(
    graph: WeightedGraph,
    p: seq<int>,
    v: int,
    w: int
)
    requires well_formed(graph)
    requires is_path(view(graph), p)
    requires has_edge(view(graph), p[|p| - 1], v, w)
    ensures is_path(view(graph), p + [v])
    ensures path_weight(view(graph), p + [v])
        == path_weight(view(graph), p) + w
{
    GetEdgeWeightLemma(graph, p[|p| - 1], v, w);

    assert |p + [v]| > 0;
    forall i: int | 0 <= i < |p + [v]| - 1
        ensures connected(
            view(graph),
            (p + [v])[i],
            (p + [v])[i + 1]
        )
    {
        if i < |p| - 1 {
            assert (p + [v])[i] == p[i];
            assert (p + [v])[i + 1] == p[i + 1];
        } else {
            assert i == |p| - 1;
            assert (p + [v])[i] == p[|p| - 1];
            assert (p + [v])[i + 1] == v;
        }
    }

    assert (p + [v])[..|p + [v]| - 1] == p;
}

lemma PathWeightNonnegative(
    graph: WeightedGraph,
    p: seq<int>
)
    requires well_formed(graph)
    requires weights_non_negative(view(graph))
    requires is_path(view(graph), p)
    ensures path_weight(view(graph), p) >= 0
    decreases |p|
{
    if |p| >= 2 {
        PrefixIsPath(graph, p, |p| - 1);
        PathWeightNonnegative(graph, p[..|p| - 1]);

        assert connected(
            view(graph), p[|p| - 2], p[|p| - 1]
        );
        var w :| has_edge(
            view(graph), p[|p| - 2], p[|p| - 1], w
        );
        GetEdgeWeightLemma(
            graph, p[|p| - 2], p[|p| - 1], w
        );
        assert w >= 0;
    }
}

lemma PrefixWeightAtMostPath(
    graph: WeightedGraph,
    p: seq<int>,
    k: int
)
    requires well_formed(graph)
    requires weights_non_negative(view(graph))
    requires is_path(view(graph), p)
    requires 1 <= k <= |p|
    ensures path_weight(view(graph), p[..k])
        <= path_weight(view(graph), p)
    decreases |p| - k
{
    if k < |p| {
        assert |p| >= 2;

        var q := p[..|p| - 1];
        PrefixIsPath(graph, p, |p| - 1);
        assert 1 <= k <= |q|;
        PrefixWeightAtMostPath(graph, q, k);

        assert q[..k] == p[..k];
        assert path_weight(view(graph), p[..k])
            <= path_weight(view(graph), q);

        assert connected(
            view(graph), p[|p| - 2], p[|p| - 1]
        );
        var w :| has_edge(
            view(graph), p[|p| - 2], p[|p| - 1], w
        );
        GetEdgeWeightLemma(
            graph, p[|p| - 2], p[|p| - 1], w
        );
        assert w >= 0;

        assert p[..|p| - 1] == q;
        assert path_weight(view(graph), p)
            == path_weight(view(graph), q)
                + get_edge_weight(
                    view(graph), p[|p| - 2], p[|p| - 1]
                );
        assert get_edge_weight(
            view(graph), p[|p| - 2], p[|p| - 1]
        ) == w;
        assert path_weight(view(graph), q)
            <= path_weight(view(graph), p);
        assert path_weight(view(graph), p[..k])
            <= path_weight(view(graph), p);
    } else {
        assert k == |p|;
        assert p[..k] == p;
    }
}

lemma SelectedVertexIsShortest(
    graph: WeightedGraph,
    start: int,
    dist: seq<Option<int>>,
    paths: seq<seq<int>>,
    done: set<int>,
    best: int
)
    requires well_formed(graph)
    requires weights_non_negative(view(graph))
    requires 0 <= start < size(graph)
    requires WitnessOK(graph, start, dist, paths)
    requires SettledOK(graph, start, dist, done)
    requires FrontierOK(graph, dist, done)
    requires dist[start] == Some(0)
    requires 0 <= best < size(graph)
    requires best !in done
    requires HasValue(dist[best])
    requires forall v: int ::
        0 <= v < size(graph)
        && v !in done
        && HasValue(dist[v])
        ==> OVal(dist[best]) <= OVal(dist[v])
    ensures is_shortest_dist(
        view(graph), start, best, OVal(dist[best])
    )
{
    assert is_path(view(graph), paths[best]);
    assert paths[best][0] == start;
    assert paths[best][|paths[best]| - 1] == best;
    assert path_weight(view(graph), paths[best]) == OVal(dist[best]);

    assert exists p: seq<int> {:trigger is_path(view(graph), p)} ::
        is_path(view(graph), p)
        && p[0] == start
        && p[|p| - 1] == best
        && path_weight(view(graph), p) == OVal(dist[best]);

    forall p: seq<int> {:trigger is_path(view(graph), p)}
        | is_path(view(graph), p)
          && p[0] == start
          && p[|p| - 1] == best
        ensures path_weight(view(graph), p) >= OVal(dist[best])
    {
        PathVerticesBounded(graph, p);

        if start !in done {
            assert HasValue(dist[start]);
            assert OVal(dist[start]) == 0;
            assert OVal(dist[best]) <= OVal(dist[start]);
            PathWeightNonnegative(graph, p);
        } else {
            var k := 0;
            while k < |p| && p[k] in done
                invariant 0 <= k <= |p|
                invariant forall j: int ::
                    0 <= j < k ==> p[j] in done
                decreases |p| - k
            {
                k := k + 1;
            }

            assert p[|p| - 1] == best;
            assert best !in done;
            assert k < |p|;
            assert p[k] !in done;
            assert k > 0;
            assert p[k - 1] in done;

            PrefixIsPath(graph, p, k);
            assert p[..k][0] == start;
            assert p[..k][|p[..k]| - 1] == p[k - 1];

            assert is_shortest_dist(
                view(graph), start, p[k - 1],
                OVal(dist[p[k - 1]])
            );
            assert path_weight(view(graph), p[..k])
                >= OVal(dist[p[k - 1]]);

            assert connected(view(graph), p[k - 1], p[k]);
            assert HasValue(dist[p[k]]);
            assert OVal(dist[p[k]])
                <= OVal(dist[p[k - 1]])
                    + get_edge_weight(
                        view(graph), p[k - 1], p[k]
                    );

            assert OVal(dist[best]) <= OVal(dist[p[k]]);

            var w :| has_edge(
                view(graph), p[k - 1], p[k], w
            );
            GetEdgeWeightLemma(graph, p[k - 1], p[k], w);

            PrefixIsPath(graph, p, k + 1);
            assert p[..k + 1] == p[..k] + [p[k]];
            AppendEdgeLemma(graph, p[..k], p[k], w);
            PrefixWeightAtMostPath(graph, p, k + 1);

            assert path_weight(view(graph), p[..k + 1])
                == path_weight(view(graph), p[..k]) + w;
        }
    }
}

lemma NoTentativeMeansUnreachable(
    graph: WeightedGraph,
    start: int,
    dist: seq<Option<int>>,
    done: set<int>
)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    requires |dist| == size(graph)
    requires HasValue(dist[start])
    requires FrontierOK(graph, dist, done)
    requires forall v: int ::
        0 <= v < size(graph) && v !in done
        ==> !HasValue(dist[v])
    ensures forall v: int ::
        0 <= v < size(graph) && v !in done ==>
            forall p: seq<int> {:trigger is_path(view(graph), p)} ::
                is_path(view(graph), p)
                && p[0] == start
                && p[|p| - 1] == v
                ==> false
{
    assert start in done;

    forall v: int | 0 <= v < size(graph) && v !in done
        ensures forall p: seq<int> {:trigger is_path(view(graph), p)} ::
            is_path(view(graph), p)
            && p[0] == start
            && p[|p| - 1] == v
            ==> false
    {
        forall p: seq<int> {:trigger is_path(view(graph), p)}
            | is_path(view(graph), p)
              && p[0] == start
              && p[|p| - 1] == v
            ensures false
        {
            PathVerticesBounded(graph, p);

            var k := 0;
            while k < |p| && p[k] in done
                invariant 0 <= k <= |p|
                invariant forall j: int ::
                    0 <= j < k ==> p[j] in done
                decreases |p| - k
            {
                k := k + 1;
            }

            assert k < |p|;
            assert k > 0;
            assert p[k - 1] in done;
            assert p[k] !in done;
            assert connected(view(graph), p[k - 1], p[k]);
            assert HasValue(dist[p[k]]);
            assert false;
        }
    }
}

lemma BoundedSetCardinality(s: set<int>, n: int)
    requires 0 <= n
    requires forall x: int :: x in s ==> 0 <= x < n
    ensures |s| <= n
    decreases n
{
    if n == 0 {
        assert s == {};
    } else {
        var t := set x: int | x in s && x < n - 1;
        BoundedSetCardinality(t, n - 1);

        if n - 1 in s {
            assert s == t + {n - 1};
            assert |s| == |t| + 1;
        } else {
            assert s == t;
        }
    }
}

method RelaxFrom(
    graph: WeightedGraph,
    start: int,
    dist: seq<Option<int>>,
    paths: seq<seq<int>>,
    done: set<int>,
    u: int
) returns (
    newDist: seq<Option<int>>,
    newPaths: seq<seq<int>>
)
    requires well_formed(graph)
    requires weights_non_negative(view(graph))
    requires 0 <= start < size(graph)
    requires WitnessOK(graph, start, dist, paths)
    requires SettledOK(graph, start, dist, done)
    requires start in done
    requires dist[start] == Some(0)
    requires u in done
    requires FrontierExcept(graph, dist, done, u)
    ensures WitnessOK(graph, start, newDist, newPaths)
    ensures SettledOK(graph, start, newDist, done)
    ensures FrontierOK(graph, newDist, done)
    ensures newDist[start] == Some(0)
    ensures forall v: int ::
        0 <= v < size(graph) && HasValue(dist[v]) ==>
            HasValue(newDist[v])
            && OVal(newDist[v]) <= OVal(dist[v])
{
    newDist := dist;
    newPaths := paths;
    var i := 0;

    while i < |graph.adj[u]|
        invariant 0 <= i <= |graph.adj[u]|
        invariant WitnessOK(graph, start, newDist, newPaths)
        invariant SettledOK(graph, start, newDist, done)
        invariant FrontierExcept(graph, newDist, done, u)
        invariant newDist[start] == Some(0)
        invariant forall v: int ::
            0 <= v < size(graph) && HasValue(dist[v]) ==>
                HasValue(newDist[v])
                && OVal(newDist[v]) <= OVal(dist[v])
        invariant forall j: int ::
            0 <= j < i ==>
                HasValue(newDist[graph.adj[u][j].0])
                && OVal(newDist[graph.adj[u][j].0])
                    <= OVal(newDist[u]) + graph.adj[u][j].1
        decreases |graph.adj[u]| - i
    {
        var v := graph.adj[u][i].0;
        var w := graph.adj[u][i].1;

        assert 0 <= v < size(graph);
        assert has_edge(view(graph), u, v, w);
        GetEdgeWeightLemma(graph, u, v, w);
        assert w >= 0;

        if v in done {
            assert is_shortest_dist(
                view(graph), start, v, OVal(newDist[v])
            );
            AppendEdgeLemma(graph, newPaths[u], v, w);
            assert path_weight(
                view(graph), newPaths[u] + [v]
            ) == OVal(newDist[u]) + w;
            assert path_weight(
                view(graph), newPaths[u] + [v]
            ) >= OVal(newDist[v]);
            assert OVal(newDist[v])
                <= OVal(newDist[u]) + w;
        } else {
            assert v != start;
            var nd := OVal(newDist[u]) + w;
            if !HasValue(newDist[v]) || nd < OVal(newDist[v]) {
                var oldDist := newDist;
                var oldPaths := newPaths;
                var q := oldPaths[u] + [v];

                AppendEdgeLemma(graph, oldPaths[u], v, w);
                newDist := oldDist[v := Some(nd)];
                newPaths := oldPaths[v := q];

                assert newDist[start] == Some(0);

                assert WitnessOK(
                    graph, start, newDist, newPaths
                ) by {
                    forall x: int
                        | 0 <= x < size(graph)
                          && HasValue(newDist[x])
                        ensures
                            is_path(view(graph), newPaths[x])
                            && newPaths[x][0] == start
                            && newPaths[x][|newPaths[x]| - 1] == x
                            && path_weight(
                                view(graph), newPaths[x]
                            ) == OVal(newDist[x])
                    {
                        if x == v {
                            assert newPaths[x] == q;
                            assert newDist[x] == Some(nd);
                        } else {
                            assert newPaths[x] == oldPaths[x];
                            assert newDist[x] == oldDist[x];
                        }
                    }
                }

                assert SettledOK(
                    graph, start, newDist, done
                ) by {
