method dijkstra_shortest_paths(
    graph: WeightedGraph,
    start: int
) returns (res: seq<Option<int>>)
    requires well_formed(graph)
    requires 0 <= start < size(graph)
    requires weights_non_negative(view(graph))
    requires weights_and_size_bounded(view(graph))
    ensures |res| == size(graph)
    ensures forall v: int :: 0 <= v < size(graph) ==>
        match res[v] {
            case Some(d) =>
                is_shortest_dist(view(graph), start, v, d)
            case None =>
                forall p: seq<int> {:trigger is_path(view(graph), p)} ::
                    is_path(view(graph), p)
                    && p[0] == start
                    && p[|p| - 1] == v
                    ==> false
        }
{
    var n := |graph.adj|;
    var dist := seq(n, i =>
        if i == start then Some(0) else None);
    var paths := seq(n, i =>
        if i == start then [start] else []);
    var done: set<int> := {};
    var count := 0;
    var stuck := false;

    assert n == size(graph);
    assert is_path(view(graph), [start]);
    assert WitnessOK(graph, start, dist, paths);
    assert SettledOK(graph, start, dist, done);
    assert FrontierOK(graph, dist, done);
    assert dist[start] == Some(0);

    while count < n && !stuck
        invariant n == |graph.adj|
        invariant n == size(graph)
        invariant |dist| == n
        invariant |paths| == n
        invariant WitnessOK(graph, start, dist, paths)
        invariant SettledOK(graph, start, dist, done)
        invariant FrontierOK(graph, dist, done)
        invariant dist[start] == Some(0)
        invariant forall v: int :: v in done ==> 0 <= v < n
        invariant count == |done|
        invariant 0 <= count <= n
        invariant done != {} ==> start in done
        invariant done == {} ==>
            forall v: int ::
                0 <= v < n ==> (HasValue(dist[v]) <==> v == start)
        invariant stuck ==>
            forall v: int ::
                0 <= v < n && v !in done ==>
                    !HasValue(dist[v])
        decreases n - count, if stuck then 0 else 1
    {
        var found := false;
        var best := -1;
        var bestDistance := 0;
        var i := 0;

        while i < n
            invariant 0 <= i <= n
            invariant found ==>
                0 <= best < n
                && best !in done
                && HasValue(dist[best])
                && bestDistance == OVal(dist[best])
            invariant forall v: int ::
                0 <= v < i
                && v !in done
                && HasValue(dist[v])
                ==> found && bestDistance <= OVal(dist[v])
            decreases n - i
        {
            if i !in done && HasValue(dist[i]) {
                if !found || OVal(dist[i]) < bestDistance {
                    found := true;
                    best := i;
                    bestDistance := OVal(dist[i]);
                }
            }
            i := i + 1;
        }

        if !found {
            assert forall v: int ::
                0 <= v < n && v !in done ==>
                    !HasValue(dist[v]);
            stuck := true;
        } else {
            assert forall v: int ::
                0 <= v < n
                && v !in done
                && HasValue(dist[v])
                ==> OVal(dist[best]) <= OVal(dist[v]);

            SelectedVertexIsShortest(
                graph, start, dist, paths, done, best
            );

            assert done == {} ==> best == start;
            assert done != {} ==> start in done;

            var oldDone := done;
            done := done + {best};
            count := count + 1;

            assert |done| == |oldDone| + 1;
            assert start in done;

            assert SettledOK(graph, start, dist, done) by {
                forall x: int | x in done
                    ensures
                        0 <= x < size(graph)
                        && HasValue(dist[x])
                        && is_shortest_dist(
                            view(graph), start, x, OVal(dist[x])
                        )
                {
                    if x == best {
                    } else {
                        assert x in oldDone;
                    }
                }
            }

            assert FrontierExcept(
                graph, dist, done, best
            ) by {
                forall x: int, v: int
                    | x in done
                      && x != best
                      && 0 <= x < size(graph)
                      && 0 <= v < size(graph)
                      && connected(view(graph), x, v)
                    ensures
                        HasValue(dist[x])
                        && HasValue(dist[v])
                        && OVal(dist[v])
                            <= OVal(dist[x])
                              + get_edge_weight(view(graph), x, v)
                {
                    assert x in oldDone;
                }
            }

            dist, paths := RelaxFrom(
                graph, start, dist, paths, done, best
            );
            assert dist[start] == Some(0);
        }
    }

    if stuck {
        NoTentativeMeansUnreachable(
            graph, start, dist, done
        );
    } else {
        assert count == n;
        assert |done| == n;
        BoundedSetCardinality(done, n);

        forall v: int | 0 <= v < n
            ensures v in done
        {
            if v !in done {
                var larger := done + {v};
                assert |larger| == |done| + 1;
                assert forall x: int ::
                    x in larger ==> 0 <= x < n;
                BoundedSetCardinality(larger, n);
                assert false;
            }
        }
    }

    assert stuck || (forall v: int :: 0 <= v < n ==> v in done);

    res := dist;

    forall v: int | 0 <= v < n
        ensures
            match res[v]
            case Some(d) =>
                is_shortest_dist(view(graph), start, v, d)
            case None =>
                forall p: seq<int> {:trigger is_path(view(graph), p)} ::
                    is_path(view(graph), p)
                    && p[0] == start
                    && p[|p| - 1] == v
                    ==> false
    {
        if v in done {
            assert HasValue(res[v]);
            assert is_shortest_dist(
                view(graph), start, v, OVal(res[v])
            );
        } else {
            assert stuck;
            assert !HasValue(res[v]);
            NoTentativeMeansUnreachable(
                graph, start, res, done
            );
        }
    }
