method rob(nums: seq<int>) returns (max_amount: int)
    requires |nums| <= 100
    // Constraints matching Verus u64
    requires forall i: int :: 0 <= i < |nums| ==> nums[i] >= 0
    requires forall i: int :: 0 <= i < |nums| ==> nums[i] <= 10000
    ensures max_amount >= 0
    // 1. Upper Bound
    ensures forall houses: seq<int> :: (is_valid_robbery(houses, |nums|) 
            ==> total_loot(houses, nums) <= max_amount)
    // 2. Existence
    ensures exists houses: seq<int> :: (is_valid_robbery(houses, |nums|) 
            && total_loot(houses, nums) == max_amount)
{
    var a := 0;
    var b := 0;
    var i := 0;
    while i < |nums|
        invariant 0 <= i <= |nums|
        invariant a == best(nums, i - 1)
        invariant b == best(nums, i)
        decreases |nums| - i
    {
        var c := if b >= a + nums[i] then b else a + nums[i];
        a := b;
        b := c;
        i := i + 1;
    }
    max_amount := b;
    BestNonneg(nums, |nums|);
    forall houses | is_valid_robbery(houses, |nums|)
        ensures total_loot(houses, nums) <= max_amount
    {
        Upper(nums, |nums|, houses);
    }
    var h := Exists(nums, |nums|);
    assert is_valid_robbery(h, |nums|) && total_loot(h, nums) == max_amount;
}

