function find_edge(adj_u: seq<(int, int)>, v: int, idx: int): int
    requires 0 <= idx <= |adj_u|
    ensures -1 <= find_edge(adj_u, v, idx) < |adj_u|
    ensures find_edge(adj_u, v, idx) >= 0 ==> idx <= find_edge(adj_u, v, idx) && adj_u[find_edge(adj_u, v, idx)].0 == v
    ensures find_edge(adj_u, v, idx) == -1 ==> forall k: int :: idx <= k < |adj_u| ==> adj_u[k].0 != v
    decreases |adj_u| - idx
{
    if idx == |adj_u| then -1
    else if adj_u[idx].0 == v then idx
    else find_edge(adj_u, v, idx + 1)
}

function get_cap(g: seq<seq<(int, int)>>, u: int, v: int): int
{
    if 0 <= u < |g| then
        var idx := find_edge(g[u], v, 0);
        if idx >= 0 then g[u][idx].1 else 0
    else 0
}

function flow_at(f: FlowMap, u: int, v: int): int
    ensures flow_at(f, u, v) == get_flow(f, u, v)
{
    if (u, v) in f then f[(u, v)] else 0
}

function res_cap(g: seq<seq<(int, int)>>, f: FlowMap, u: int, v: int): int
{
    if flow_at(f, u, v) < get_cap(g, u, v) then
        get_cap(g, u, v) - flow_at(f, u, v)
    else
        flow_at(f, v, u)
}

function push_edge(g: seq<seq<(int, int)>>, f: FlowMap, u: int, v: int, delta: int): FlowMap
{
    if flow_at(f, u, v) < get_cap(g, u, v) then
        f[(u, v) := flow_at(f, u, v) + delta]
    else
        f[(v, u) := flow_at(f, v, u) - delta]
}

