    decreases v_idx
{
    if v_idx <= 0 then 0
    else sum_row(f, u, v_idx - 1) + get_flow(f, u, v_idx - 1)
}

ghost function sum_out_partial(g: seq<seq<(int, int)>>, f: FlowMap, u: int, idx: int, v_idx: int): int
    decreases v_idx
{
    if v_idx <= 0 || u < 0 || u >= |g| then 0
    else
        var v := v_idx - 1;
        var e := find_edge(g[u], v, 0);
        var term := if 0 <= e < idx then get_flow(f, u, v) else 0;
        sum_out_partial(g, f, u, idx, v_idx - 1) + term
}

lemma LemmaSumOutPartialZero(g: seq<seq<(int, int)>>, f: FlowMap, u: int, v_idx: int)
    ensures sum_out_partial(g, f, u, 0, v_idx) == 0
    decreases v_idx
{
    if v_idx > 0 && 0 <= u < |g| {
        LemmaSumOutPartialZero(g, f, u, v_idx - 1);
    }
}

lemma LemmaSumOutPartialStep(g: CapacityGraph, f: FlowMap, u: int, idx: int, v_idx: int)
    requires well_formed(g)
    requires 0 <= u < |g.adj|
    requires 0 <= idx < |g.adj[u]|
    requires 0 <= v_idx <= |g.adj|
    ensures sum_out_partial(g.adj, f, u, idx + 1, v_idx) ==
        sum_out_partial(g.adj, f, u, idx, v_idx) + (if g.adj[u][idx].0 < v_idx then get_flow(f, u, g.adj[u][idx].0) else 0)
    decreases v_idx
{
    if v_idx > 0 {
        LemmaSumOutPartialStep(g, f, u, idx, v_idx - 1);
        var v := v_idx - 1;
        var w := g.adj[u][idx].0;
        LemmaFindEdgeUnique(g, u, idx);
        var e := find_edge(g.adj[u], v, 0);
        if v == w {
            assert e == idx;
        } else {
            if e == idx {
                assert g.adj[u][e].0 == v;
                assert false;
            }
        }
    }
}

lemma LemmaSumFlowOutRecEqPartial(g: CapacityGraph, f: FlowMap, u: int, idx: int)
    requires well_formed(g)
    requires 0 <= u < |g.adj|
    requires 0 <= idx <= |g.adj[u]|
    ensures sum_flow_out_recursive(g.adj, f, u, idx) == sum_out_partial(g.adj, f, u, idx, |g.adj|)
    decreases idx
{
    if idx == 0 {
        LemmaSumOutPartialZero(g.adj, f, u, |g.adj|);
    } else {
        LemmaSumFlowOutRecEqPartial(g, f, u, idx - 1);
        LemmaSumOutPartialStep(g, f, u, idx - 1, |g.adj|);
        assert 0 <= g.adj[u][idx - 1].0 < |g.adj|;
    }
}

lemma LemmaSumOutPartialFullEqSumRow(g: CapacityGraph, f: FlowMap, u: int, v_idx: int)
    requires well_formed(g)
    requires 0 <= u < |g.adj|
    requires 0 <= v_idx <= |g.adj|
    requires forall v: int :: 0 <= v < v_idx && get_flow(f, u, v) != 0 ==> find_edge(g.adj[u], v, 0) >= 0
    ensures sum_out_partial(g.adj, f, u, |g.adj[u]|, v_idx) == sum_row(f, u, v_idx)
    decreases v_idx
{
    if v_idx > 0 {
        LemmaSumOutPartialFullEqSumRow(g, f, u, v_idx - 1);
        var v := v_idx - 1;
        var e := find_edge(g.adj[u], v, 0);
        if get_flow(f, u, v) != 0 {
            assert 0 <= e < |g.adj[u]|;
        }
    }
}

lemma LemmaTotalFlowOutEqSumRow(g: CapacityGraph, f: FlowMap, s: int, t: int, u: int)
    requires well_formed(g)
    requires capacities_bounded(g.adj)
    requires is_valid_flow(g.adj, f, s, t) || wf_flow(g.adj, f)
    requires 0 <= u < |g.adj|
    ensures total_flow_out(g.adj, f, u) == sum_row(f, u, |g.adj|)
{
    forall v: int | 0 <= v < |g.adj| && get_flow(f, u, v) != 0
        ensures find_edge(g.adj[u], v, 0) >= 0
    {
        if is_valid_flow(g.adj, f, s, t) {
            LemmaValidFlowBounds(g, f, s, t, u, v);
        } else {
            LemmaWfFlowImpliesRespectsCapacity(g, f);
        }
    }
    LemmaSumFlowOutRecEqPartial(g, f, u, |g.adj[u]|);
    LemmaSumOutPartialFullEqSumRow(g, f, u, |g.adj|);
}

lemma LemmaSumRowUnchanged(f: FlowMap, f': FlowMap, w: int, v_idx: int)
    requires forall v: int :: 0 <= v < v_idx ==> get_flow(f', w, v) == get_flow(f, w, v)
    ensures sum_row(f', w, v_idx) == sum_row(f, w, v_idx)
    decreases v_idx
{
    if v_idx > 0 {
        LemmaSumRowUnchanged(f, f', w, v_idx - 1);
    }
}

lemma LemmaSumRowUpdate(f: FlowMap, a: int, b: int, new_val: int, w: int, v_idx: int)
    requires 0 <= b < v_idx
    ensures sum_row(f[(a, b) := new_val], w, v_idx) ==
        sum_row(f, w, v_idx) + (if w == a then new_val - get_flow(f, a, b) else 0)
    decreases v_idx
{
    var f' := f[(a, b) := new_val];
    if v_idx - 1 == b {
        LemmaSumRowUnchanged(f, f', w, v_idx - 1);
    } else {
        LemmaSumRowUpdate(f, a, b, new_val, w, v_idx - 1);
    }
}

lemma LemmaSumColUnchanged(g: seq<seq<(int, int)>>, f: FlowMap, f': FlowMap, w: int, v_idx: int)
    requires forall v: int :: 0 <= v < v_idx ==> get_flow(f', v, w) == get_flow(f, v, w)
    ensures sum_flow_in_recursive(g, f', w, v_idx) == sum_flow_in_recursive(g, f, w, v_idx)
    decreases v_idx
{
    if v_idx > 0 {
        LemmaSumColUnchanged(g, f, f', w, v_idx - 1);
    }
}

lemma LemmaSumColUpdate(g: seq<seq<(int, int)>>, f: FlowMap, a: int, b: int, new_val: int, w: int, v_idx: int)
    requires 0 <= a < v_idx
    ensures sum_flow_in_recursive(g, f[(a, b) := new_val], w, v_idx) ==
        sum_flow_in_recursive(g, f, w, v_idx) + (if w == b then new_val - get_flow(f, a, b) else 0)
    decreases v_idx
{
    var f' := f[(a, b) := new_val];
    if v_idx - 1 == a {
        LemmaSumColUnchanged(g, f, f', w, v_idx - 1);
    } else {
        LemmaSumColUpdate(g, f, a, b, new_val, w, v_idx - 1);
    }
}

lemma LemmaPushEdge(g: CapacityGraph, f: FlowMap, s: int, t: int, u: int, v: int, delta: int)
    requires well_formed(g)
    requires capacities_bounded(g.adj)
    requires wf_flow(g.adj, f)
    requires 0 <= u < |g.adj| && 0 <= v < |g.adj| && u != v
    requires 0 < delta <= res_cap(g.adj, f, u, v)
    ensures var f' := push_edge(g.adj, f, u, v, delta);
        && wf_flow(g.adj, f')
        && (forall w: int :: 0 <= w < |g.adj| ==>
            net_flow(g.adj, f', w) == net_flow(g.adj, f, w) + (if w == u then delta else 0) - (if w == v then delta else 0))
        && (forall x: int, y: int :: (x, y) != (u, v) && (x, y) != (v, u) ==> get_flow(f', x, y) == get_flow(f, x, y))
{
    LemmaWfFlowImpliesRespectsCapacity(g, f);
    var f' := push_edge(g.adj, f, u, v, delta);
    if flow_at(f, u, v) < get_cap(g.adj, u, v) {
        var new_val := flow_at(f, u, v) + delta;
        assert f' == f[(u, v) := new_val];
        assert wf_flow(g.adj, f');
        forall w: int | 0 <= w < |g.adj|
            ensures net_flow(g.adj, f', w) == net_flow(g.adj, f, w) + (if w == u then delta else 0) - (if w == v then delta else 0)
        {
            LemmaTotalFlowOutEqSumRow(g, f, s, t, w);
            LemmaTotalFlowOutEqSumRow(g, f', s, t, w);
            LemmaSumRowUpdate(f, u, v, new_val, w, |g.adj|);
            LemmaSumColUpdate(g.adj, f, u, v, new_val, w, |g.adj|);
        }
    } else {
        var new_val := flow_at(f, v, u) - delta;
        assert f' == f[(v, u) := new_val];
        assert wf_flow(g.adj, f');
        forall w: int | 0 <= w < |g.adj|
            ensures net_flow(g.adj, f', w) == net_flow(g.adj, f, w) + (if w == u then delta else 0) - (if w == v then delta else 0)
        {
            LemmaTotalFlowOutEqSumRow(g, f, s, t, w);
            LemmaTotalFlowOutEqSumRow(g, f', s, t, w);
            LemmaSumRowUpdate(f, v, u, new_val, w, |g.adj|);
            LemmaSumColUpdate(g.adj, f, v, u, new_val, w, |g.adj|);
        }
    }
}

lemma LemmaZeroSumRow(f: FlowMap, w: int, v_idx: int)
    requires f == map[]
    ensures sum_row(f, w, v_idx) == 0
    decreases v_idx
{
