        LemmaZeroSumRow(f, w, v_idx - 1);
    }
}

lemma LemmaZeroSumCol(g: seq<seq<(int, int)>>, f: FlowMap, w: int, v_idx: int)
    requires f == map[]
    ensures sum_flow_in_recursive(g, f, w, v_idx) == 0
    decreases v_idx
