lemma LemmaZeroFlowValid(g: CapacityGraph, s: int, t: int)
    requires well_formed(g)
    requires capacities_bounded(g.adj)
    ensures var f: FlowMap := map[];
        wf_flow(g.adj, f) && is_valid_flow(g.adj, f, s, t) && flow_val(g.adj, f, s) == 0 && (forall w: int :: 0 <= w < |g.adj| ==> net_flow(g.adj, f, w) == 0)
{
    var f: FlowMap := map[];
    assert wf_flow(g.adj, f);
    LemmaWfFlowImpliesRespectsCapacity(g, f);
    forall w: int | 0 <= w < |g.adj|
        ensures total_flow_out(g.adj, f, w) == 0 && total_flow_in(g.adj, f, w) == 0
