ghost function sum_row_diff(f: FlowMap, u: int, v_idx: int): int
    decreases v_idx
{
    if v_idx <= 0 then 0
    else sum_row_diff(f, u, v_idx - 1) + (get_flow(f, u, v_idx - 1) - get_flow(f, v_idx - 1, u))
}

ghost function sum_row_diff_inS(f: FlowMap, S: seq<bool>, u: int, v_idx: int): int
    requires 0 <= v_idx <= |S|
    decreases v_idx
{
    if v_idx <= 0 then 0
    else
        var v := v_idx - 1;
        var term := if S[v] then get_flow(f, u, v) - get_flow(f, v, u) else 0;
        sum_row_diff_inS(f, S, u, v_idx - 1) + term
}

ghost function sum_row_diff_outS(f: FlowMap, S: seq<bool>, u: int, v_idx: int): int
    requires 0 <= v_idx <= |S|
    decreases v_idx
{
    if v_idx <= 0 then 0
    else
        var v := v_idx - 1;
        var term := if !S[v] then get_flow(f, u, v) - get_flow(f, v, u) else 0;
        sum_row_diff_outS(f, S, u, v_idx - 1) + term
}

ghost function sum_inS_inS(f: FlowMap, S: seq<bool>, u_idx: int, v_idx: int): int
    requires 0 <= u_idx <= |S| && 0 <= v_idx <= |S|
    decreases u_idx
{
    if u_idx <= 0 then 0
    else
        var u := u_idx - 1;
        var term := if S[u] then sum_row_diff_inS(f, S, u, v_idx) else 0;
        sum_inS_inS(f, S, u_idx - 1, v_idx) + term
}

ghost function sum_inS_outS(f: FlowMap, S: seq<bool>, u_idx: int, v_idx: int): int
    requires 0 <= u_idx <= |S| && 0 <= v_idx <= |S|
    decreases u_idx
{
    if u_idx <= 0 then 0
    else
        var u := u_idx - 1;
        var term := if S[u] then sum_row_diff_outS(f, S, u, v_idx) else 0;
        sum_inS_outS(f, S, u_idx - 1, v_idx) + term
}

ghost function sum_net_flow_S(g: seq<seq<(int, int)>>, f: FlowMap, S: seq<bool>, u_idx: int): int
    requires |S| == |g| && 0 <= u_idx <= |g|
    decreases u_idx
{
    if u_idx <= 0 then 0
    else
        var u := u_idx - 1;
        var term := if S[u] then net_flow(g, f, u) else 0;
        sum_net_flow_S(g, f, S, u_idx - 1) + term
}

lemma LemmaSumRowDiffSplit(g: seq<seq<(int, int)>>, f: FlowMap, S: seq<bool>, u: int, v_idx: int)
    requires |S| == |g| && 0 <= v_idx <= |g|
    ensures sum_row_diff(f, u, v_idx) == sum_row(f, u, v_idx) - sum_flow_in_recursive(g, f, u, v_idx)
    ensures sum_row_diff(f, u, v_idx) == sum_row_diff_inS(f, S, u, v_idx) + sum_row_diff_outS(f, S, u, v_idx)
    decreases v_idx
{
    if v_idx > 0 {
        LemmaSumRowDiffSplit(g, f, S, u, v_idx - 1);
    }
}

lemma LemmaSumNetFlowS(g: CapacityGraph, f: FlowMap, s: int, t: int, S: seq<bool>, u_idx: int)
    requires well_formed(g)
    requires capacities_bounded(g.adj)
    requires is_valid_flow(g.adj, f, s, t)
    requires |S| == |g.adj| && 0 <= s < |g.adj| && 0 <= t < |g.adj|
    requires S[s] && !S[t]
    requires 0 <= u_idx <= |g.adj|
    ensures sum_net_flow_S(g.adj, f, S, u_idx) == (if s < u_idx then flow_val(g.adj, f, s) else 0)
    ensures sum_net_flow_S(g.adj, f, S, u_idx) == sum_inS_inS(f, S, u_idx, |g.adj|) + sum_inS_outS(f, S, u_idx, |g.adj|)
    decreases u_idx
{
    if u_idx > 0 {
        LemmaSumNetFlowS(g, f, s, t, S, u_idx - 1);
        var u := u_idx - 1;
        LemmaTotalFlowOutEqSumRow(g, f, s, t, u);
        LemmaSumRowDiffSplit(g.adj, f, S, u, |g.adj|);
        if u != s && u != t {
            assert total_flow_in(g.adj, f, u) == total_flow_out(g.adj, f, u);
        }
    }
}

lemma LemmaSumInSColStep(f: FlowMap, S: seq<bool>, u_idx: int, k: int)
    requires 0 <= u_idx <= |S| && 0 <= k < |S|
    ensures sum_inS_inS(f, S, u_idx, k + 1) ==
        sum_inS_inS(f, S, u_idx, k) - (if S[k] then sum_row_diff_inS(f, S, k, u_idx) else 0)
    decreases u_idx
{
    if u_idx > 0 {
        LemmaSumInSColStep(f, S, u_idx - 1, k);
    }
}

lemma LemmaSumInSSquareZero(f: FlowMap, S: seq<bool>, k: int)
    requires 0 <= k <= |S|
    ensures sum_inS_inS(f, S, k, k) == 0
    decreases k
{
    if k > 0 {
        LemmaSumInSSquareZero(f, S, k - 1);
        LemmaSumInSColStep(f, S, k - 1, k - 1);
    }
}

ghost predicate is_saturated_cut(g: seq<seq<(int, int)>>, f: FlowMap, S: seq<bool>)
    requires |S| == |g|
{
    forall u: int, v: int :: 0 <= u < |g| && 0 <= v < |g| && S[u] && !S[v] ==>
        get_flow(f, u, v) == get_cap(g, u, v) && get_flow(f, v, u) == 0
}

lemma LemmaCompareRowOutS(g: CapacityGraph, f: FlowMap, other: FlowMap, s: int, t: int, S: seq<bool>, u: int, v_idx: int)
    requires well_formed(g)
    requires capacities_bounded(g.adj)
    requires is_valid_flow(g.adj, other, s, t)
    requires |S| == |g.adj| && 0 <= u < |g.adj| && S[u]
    requires is_saturated_cut(g.adj, f, S)
    requires 0 <= v_idx <= |g.adj|
    ensures sum_row_diff_outS(f, S, u, v_idx) >= sum_row_diff_outS(other, S, u, v_idx)
    decreases v_idx
{
    if v_idx > 0 {
        LemmaCompareRowOutS(g, f, other, s, t, S, u, v_idx - 1);
        var v := v_idx - 1;
        if !S[v] {
            LemmaValidFlowBounds(g, other, s, t, u, v);
            LemmaValidFlowBounds(g, other, s, t, v, u);
        }
    }
}

lemma LemmaCompareOutS(g: CapacityGraph, f: FlowMap, other: FlowMap, s: int, t: int, S: seq<bool>, u_idx: int)
    requires well_formed(g)
    requires capacities_bounded(g.adj)
    requires is_valid_flow(g.adj, other, s, t)
    requires |S| == |g.adj|
    requires is_saturated_cut(g.adj, f, S)
    requires 0 <= u_idx <= |g.adj|
    ensures sum_inS_outS(f, S, u_idx, |g.adj|) >= sum_inS_outS(other, S, u_idx, |g.adj|)
    decreases u_idx
{
    if u_idx > 0 {
        LemmaCompareOutS(g, f, other, s, t, S, u_idx - 1);
        var u := u_idx - 1;
        if S[u] {
            LemmaCompareRowOutS(g, f, other, s, t, S, u, |g.adj|);
        }
    }
}

lemma LemmaSaturatedCutImpliesMaxFlow(g: CapacityGraph, f: FlowMap, s: int, t: int, S: seq<bool>)
    requires well_formed(g)
    requires capacities_bounded(g.adj)
    requires 0 <= s < |g.adj| && 0 <= t < |g.adj| && s != t
    requires is_valid_flow(g.adj, f, s, t)
    requires |S| == |g.adj| && S[s] && !S[t]
    requires is_saturated_cut(g.adj, f, S)
    ensures is_max_flow(g.adj, f, s, t)
{
    forall other: FlowMap {:trigger is_valid_flow(g.adj, other, s, t)}
        ensures is_valid_flow(g.adj, other, s, t) ==> flow_val(g.adj, f, s) >= flow_val(g.adj, other, s)
    {
        if is_valid_flow(g.adj, other, s, t) {
            LemmaSumNetFlowS(g, f, s, t, S, |g.adj|);
            LemmaSumInSSquareZero(f, S, |g.adj|);
            LemmaSumNetFlowS(g, other, s, t, S, |g.adj|);
            LemmaSumInSSquareZero(other, S, |g.adj|);
            LemmaCompareOutS(g, f, other, s, t, S, |g.adj|);
        }
    }
}

ghost predicate valid_res_path(g: seq<seq<(int, int)>>, f: FlowMap, S: seq<bool>, s: int, u: int, p: seq<int>)
    requires |S| == |g|
{
    && |p| >= 1
    && p[0] == s
    && p[|p| - 1] == u
    && (forall i: int :: 0 <= i < |p| ==> 0 <= p[i] < |g| && S[p[i]])
    && (forall i: int, j: int :: 0 <= i < j < |p| ==> p[i] != p[j])
    && (forall i: int :: 0 <= i < |p| - 1 ==> res_cap(g, f, p[i], p[i + 1]) > 0)
}

lemma LemmaExtendResPath(g: seq<seq<(int, int)>>, f: FlowMap, S: seq<bool>, paths: seq<seq<int>>, s: int, u: int, v: int)
    requires |S| == |g| && |paths| == |g|
    requires 0 <= u < |g| && 0 <= v < |g|
    requires S[u] && !S[v] && res_cap(g, f, u, v) > 0
    requires forall w: int :: 0 <= w < |g| && S[w] ==> valid_res_path(g, f, S, s, w, paths[w])
    ensures var S' := S[v := true];
        var paths' := paths[v := paths[u] + [v]];
        forall w: int :: 0 <= w < |g| && S'[w] ==> valid_res_path(g, f, S', s, w, paths'[w])
{
    var S' := S[v := true];
    var pu := paths[u];
    var pv := pu + [v];
    var paths' := paths[v := pv];
    assert valid_res_path(g, f, S, s, u, pu);
    forall i: int, j: int | 0 <= i < j < |pv|
        ensures pv[i] != pv[j]
    {
        if j == |pu| {
            assert S[pu[i]];
            assert !S[v];
        }
    }
    assert valid_res_path(g, f, S', s, v, pv);
    forall w: int | 0 <= w < |g| && S'[w]
        ensures valid_res_path(g, f, S', s, w, paths'[w])
    {
        if w != v {
            assert valid_res_path(g, f, S, s, w, paths[w]);
        }
    }
}

ghost function count_false(S: seq<bool>, idx: int): int
    requires 0 <= idx <= |S|
    ensures count_false(S, idx) >= 0
    decreases idx
{
    if idx == 0 then 0
    else count_false(S, idx - 1) + (if !S[idx - 1] then 1 else 0)
}

lemma LemmaCountFalseDecrease(S: seq<bool>, v: int, idx: int)
    requires 0 <= v < |S|
    requires !S[v]
    requires 0 <= idx <= |S|
    ensures count_false(S[v := true], idx) == count_false(S, idx) - (if v < idx then 1 else 0)
    decreases idx
