method max_flow_value(graph: CapacityGraph, s: int, t: int) returns (max_val: int)
    requires well_formed(graph)
    requires capacities_bounded(view(graph))
    requires 0 <= s < size(graph)
    requires 0 <= t < size(graph)
    requires s != t
    ensures exists f: FlowMap :: 
            is_max_flow(view(graph), f, s, t) 
            && flow_val(view(graph), f, s) == max_val
{
    var g := graph.adj;
    var n := |g|;
    var f: FlowMap := map[];
    max_val := 0;
    LemmaZeroFlowValid(graph, s, t);

    var done := false;
    while !done
        invariant wf_flow(g, f)
        invariant is_valid_flow(g, f, s, t)
        invariant forall w: int :: 0 <= w < n && w != s && w != t ==> net_flow(g, f, w) == 0
        invariant max_val == flow_val(g, f, s)
        invariant done ==> is_max_flow(g, f, s, t)
        decreases 100_000 * n - flow_val(g, f, s), if done then 0 else 1
    {
        LemmaFlowValUpperBound(graph, f, s, t);
        var S := seq(n, i => i == s);
        var paths := seq(n, i => [s]);
        var search_done := false;

        while !S[t] && !search_done
            invariant |S| == n && |paths| == n
            invariant S[s]
            invariant forall w: int :: 0 <= w < n && S[w] ==> valid_res_path(g, f, S, s, w, paths[w])
            invariant search_done ==> forall u0: int, v0: int :: 0 <= u0 < n && 0 <= v0 < n && S[u0] && !S[v0] ==> res_cap(g, f, u0, v0) <= 0
            decreases count_false(S, n), if search_done then 0 else 1
        {
            var found_edge := false;
            var best_u := 0;
            var best_v := 0;
            var u := 0;
            while u < n && !found_edge
                invariant 0 <= u <= n
                invariant found_edge ==> 0 <= best_u < n && 0 <= best_v < n && S[best_u] && !S[best_v] && res_cap(g, f, best_u, best_v) > 0
                invariant !found_edge ==> forall u0: int, v0: int :: 0 <= u0 < u && 0 <= v0 < n && S[u0] && !S[v0] ==> res_cap(g, f, u0, v0) <= 0
                decreases n - u, if found_edge then 0 else 1
            {
                var v := 0;
                while v < n && !found_edge
                    invariant 0 <= v <= n
                    invariant found_edge ==> 0 <= best_u < n && 0 <= best_v < n && S[best_u] && !S[best_v] && res_cap(g, f, best_u, best_v) > 0
                    invariant !found_edge ==> forall u0: int, v0: int :: 0 <= u0 < u && 0 <= v0 < n && S[u0] && !S[v0] ==> res_cap(g, f, u0, v0) <= 0
                    invariant !found_edge ==> forall v0: int :: 0 <= v0 < v && S[u] && !S[v0] ==> res_cap(g, f, u, v0) <= 0
                    decreases n - v, if found_edge then 0 else 1
                {
                    if S[u] && !S[v] && res_cap(g, f, u, v) > 0 {
                        found_edge := true;
                        best_u := u;
                        best_v := v;
                    } else {
                        v := v + 1;
                    }
                }
                if !found_edge {
                    u := u + 1;
                }
            }

            if found_edge {
                LemmaExtendResPath(g, f, S, paths, s, best_u, best_v);
                LemmaCountFalseDecrease(S, best_v, n);
                paths := paths[best_v := paths[best_u] + [best_v]];
                S := S[best_v := true];
            } else {
                search_done := true;
            }
        }

        if !S[t] {
            LemmaWfFlowImpliesRespectsCapacity(graph, f);
            assert is_saturated_cut(g, f, S);
            LemmaSaturatedCutImpliesMaxFlow(graph, f, s, t, S);
            done := true;
        } else {
            var p := paths[t];
            assert valid_res_path(g, f, S, s, t, p);
            assert |p| >= 2;
            var delta := res_cap(g, f, p[0], p[1]);
            var idx := 1;
            while idx < |p| - 1
                invariant 1 <= idx <= |p| - 1
                invariant delta > 0
                invariant forall k: int :: 0 <= k < idx ==> delta <= res_cap(g, f, p[k], p[k + 1])
                decreases (|p| - 1) - idx
            {
                var rc := res_cap(g, f, p[idx], p[idx + 1]);
                if rc < delta {
                    delta := rc;
                }
                idx := idx + 1;
            }

            ghost var f_init := f;
            var step := 0;
            while step < |p| - 1
                invariant 0 <= step <= |p| - 1
                invariant wf_flow(g, f)
                invariant forall k: int :: step <= k < |p| - 1 ==>
                    get_flow(f, p[k], p[k + 1]) == get_flow(f_init, p[k], p[k + 1]) &&
                    get_flow(f, p[k + 1], p[k]) == get_flow(f_init, p[k + 1], p[k])
                invariant forall w: int :: 0 <= w < n ==>
                    net_flow(g, f, w) == net_flow(g, f_init, w) + (if w == p[0] then delta else 0) - (if w == p[step] then delta else 0)
                decreases (|p| - 1) - step
            {
                var pu := p[step];
                var pv := p[step + 1];
                assert res_cap(g, f, pu, pv) == res_cap(g, f_init, pu, pv);
                LemmaPushEdge(graph, f, s, t, pu, pv, delta);
                var f_next := push_edge(g, f, pu, pv, delta);
                forall k: int | step + 1 <= k < |p| - 1
                    ensures get_flow(f_next, p[k], p[k + 1]) == get_flow(f_init, p[k], p[k + 1])
                    ensures get_flow(f_next, p[k + 1], p[k]) == get_flow(f_init, p[k + 1], p[k])
                {
                    assert step < k < k + 1;
                    assert pu != p[k] && pu != p[k + 1];
                }
                f := f_next;
                step := step + 1;
            }

            LemmaWfFlowImpliesRespectsCapacity(graph, f);
            assert is_conserved(g, f, s, t);
            assert is_valid_flow(g, f, s, t);
            assert flow_val(g, f, s) == flow_val(g, f_init, s) + delta;
            max_val := max_val + delta;
            LemmaFlowValUpperBound(graph, f, s, t);
        }
    }
    assert is_max_flow(view(graph), f, s, t) && flow_val(view(graph), f, s) == max_val;
