    s: int,
    t: int,
    prefix: seq<int>,
    value: int
)
    requires |prefix| < |g| * |g|
    requires VRange(prefix, 100000)
    requires 0 <= value <= 100000
    ensures |EnumerateValues(g, s, t, prefix, value).1|
        == |g| * |g|
    ensures VRange(
        EnumerateValues(g, s, t, prefix, value).1,
        100000)
    ensures VExtends(
        prefix,
        EnumerateValues(g, s, t, prefix, value).1)
    ensures EnumerateValues(g, s, t, prefix, value).0 ==
        (if VValid(
            g,
            EnumerateValues(g, s, t, prefix, value).1,
            s,
            t)
         then VFlowValue(
            g,
            EnumerateValues(g, s, t, prefix, value).1,
            s)
         else -1)
    ensures forall x: seq<int> |
        |x| == |g| * |g|
        && VRange(x, 100000)
        && VExtends(prefix, x)
        && x[|prefix|] <= value
        && VValid(g, x, s, t)
        ::
        EnumerateValues(g, s, t, prefix, value).0
            >= VFlowValue(g, x, s)
    decreases |g| * |g| - |prefix|, value + 1
{
    if value == 0 {
        assert VRange(prefix + [0], 100000);
        EnumerateFlowsCorrect(g, s, t, prefix + [0]);

        forall x: seq<int> |
            |x| == |g| * |g|
            && VRange(x, 100000)
            && VExtends(prefix, x)
            && x[|prefix|] <= 0
            && VValid(g, x, s, t)
            ensures EnumerateValues(g, s, t, prefix, value).0
                >= VFlowValue(g, x, s)
        {
            assert x[|prefix|] == 0;
            assert x[..|prefix|] == prefix;
            assert x[..|prefix + [0]|] == prefix + [0];
            assert VExtends(prefix + [0], x);
        }

        ExtendsAppend(
            prefix,
            EnumerateFlows(g, s, t, prefix + [0]).1,
            0);
    } else {
        assert VRange(prefix + [value], 100000);
        EnumerateFlowsCorrect(g, s, t, prefix + [value]);
        EnumerateValuesCorrect(g, s, t, prefix, value - 1);

        var a := EnumerateFlows(g, s, t, prefix + [value]);
        var b := EnumerateValues(g, s, t, prefix, value - 1);

        ExtendsAppend(prefix, a.1, value);

        forall x: seq<int> |
            |x| == |g| * |g|
            && VRange(x, 100000)
            && VExtends(prefix, x)
            && x[|prefix|] <= value
            && VValid(g, x, s, t)
            ensures EnumerateValues(g, s, t, prefix, value).0
                >= VFlowValue(g, x, s)
        {
            if x[|prefix|] == value {
                assert x[..|prefix + [value]|] == prefix + [value];
                assert VExtends(prefix + [value], x);
                assert a.0 >= VFlowValue(g, x, s);
                assert Better(a, b).0 >= a.0;
            } else {
                assert x[|prefix|] <= value - 1;
                assert b.0 >= VFlowValue(g, x, s);
                assert Better(a, b).0 >= b.0;
            }
        }
    }
}

ghost function VectorMap(
    x: seq<int>,
    n: int
): FlowMap
    requires n >= 0
    requires |x| == n * n
{
    map u: int, v: int |
        0 <= u < n && 0 <= v < n
        :: (u, v) := x[u * n + v]
}

lemma VectorMapGet(
    x: seq<int>,
    n: int,
    u: int,
    v: int
)
    requires n >= 0
    requires |x| == n * n
    requires 0 <= u < n
    requires 0 <= v < n
    ensures get_flow(VectorMap(x, n), u, v)
        == VGet(x, n, u, v)
{
    assert 0 <= u * n + v < n * n;
    assert (u, v) in VectorMap(x, n);
}

lemma VectorOutSame(
    g: seq<seq<(int, int)>>,
    x: seq<int>,
    u: int,
    idx: int
)
    requires |x| == |g| * |g|
    requires 0 <= u < |g|
    requires 0 <= idx <= |g[u]|
    ensures sum_flow_out_recursive(
        g, VectorMap(x, |g|), u, idx)
        == VSumOut(g, x, u, idx)
    decreases idx
{
    if idx > 0 {
        VectorOutSame(g, x, u, idx - 1);
        var v := g[u][idx - 1].0;
        if 0 <= v < |g| {
            VectorMapGet(x, |g|, u, v);
        }
    }
}

lemma VectorInSame(
    g: seq<seq<(int, int)>>,
    x: seq<int>,
    u: int,
    idx: int
)
    requires |x| == |g| * |g|
    requires 0 <= u < |g|
    requires 0 <= idx <= |g|
    ensures sum_flow_in_recursive(
        g, VectorMap(x, |g|), u, idx)
        == VSumIn(g, x, u, idx)
    decreases idx
{
    if idx > 0 {
        VectorInSame(g, x, u, idx - 1);
        VectorMapGet(x, |g|, idx - 1, u);
    }
}

lemma VectorFlowValid(
    g: seq<seq<(int, int)>>,
    x: seq<int>,
    s: int,
    t: int
)
    requires well_formed(CapacityGraph(g))
    requires VValid(g, x, s, t)
    ensures is_valid_flow(g, VectorMap(x, |g|), s, t)
    ensures flow_val(g, VectorMap(x, |g|), s)
        == VFlowValue(g, x, s)
{
    ghost var f := VectorMap(x, |g|);

    forall u: int, v: int |
        (u, v) in f
        ensures f[(u, v)] >= 0
    {
        assert 0 <= u < |g|;
        assert 0 <= v < |g|;
        VectorMapGet(x, |g|, u, v);
        assert 0 <= VGet(x, |g|, u, v);
    }

    forall u: int, v: int |
        (u, v) in f
        ensures f[(u, v)] > 0 ==>
            exists c: int ::
                has_capacity(g, u, v, c)
                && f[(u, v)] <= c
    {
        assert 0 <= u < |g|;
        assert 0 <= v < |g|;
        VectorMapGet(x, |g|, u, v);

        if f[(u, v)] > 0 {
            assert VEdgeOK(g, u, v, VGet(x, |g|, u, v));
            var i: int :|
                0 <= i < |g[u]|
                && g[u][i].0 == v
                && VGet(x, |g|, u, v) <= g[u][i].1;
            assert has_capacity(g, u, v, g[u][i].1);
        }
    }

    assert respects_capacity(g, f);

    forall u: int |
        0 <= u < |g| && u != s && u != t
        ensures total_flow_in(g, f, u)
            == total_flow_out(g, f, u)
    {
        VectorInSame(g, x, u, |g|);
        VectorOutSame(g, x, u, |g[u]|);
        assert VTotalIn(g, x, u) == VTotalOut(g, x, u);
    }

    assert is_conserved(g, f, s, t);
    assert is_valid_flow(g, f, s, t);

    VectorInSame(g, x, s, |g|);
    VectorOutSame(g, x, s, |g[s]|);
}

