method max_flow_value(
    graph: CapacityGraph,
    s: int,
    t: int
) returns (max_val: int)
    requires well_formed(graph)
    requires capacities_bounded(view(graph))
    requires 0 <= s < size(graph)
    requires 0 <= t < size(graph)
    requires s != t
    ensures exists f: FlowMap ::
            is_max_flow(view(graph), f, s, t)
            && flow_val(view(graph), f, s) == max_val
{
    var result :=
        EnumerateFlows(view(graph), s, t, []);

    EnumerateFlowsCorrect(view(graph), s, t, []);

    ghost var zero :=
        seq(|view(graph)| * |view(graph)|, k => 0);

    ZeroVectorValid(view(graph), s, t);

    assert VExtends([], zero);
    assert result.0 >= VFlowValue(view(graph), zero, s);
    assert result.0 >= 0;
    assert VValid(view(graph), result.1, s, t);
    assert result.0 == VFlowValue(view(graph), result.1, s);

    ghost var maximal :=
        VectorMap(result.1, |view(graph)|);

    VectorFlowValid(
        view(graph), result.1, s, t);

    forall other: FlowMap
        | is_valid_flow(view(graph), other, s, t)
        ensures flow_val(view(graph), maximal, s)
            >= flow_val(view(graph), other, s)
    {
        ExtractValid(
            view(graph), other, s, t);

        ghost var extracted :=
            ExtractVector(view(graph), other);

        assert |extracted|
            == |view(graph)| * |view(graph)|;
        assert VRange(extracted, 100000);
        assert VExtends([], extracted);

        assert result.0
            >= VFlowValue(view(graph), extracted, s);
        assert VFlowValue(view(graph), extracted, s)
            == flow_val(view(graph), other, s);
        assert flow_val(view(graph), maximal, s)
            == result.0;
    }

    assert forall other: FlowMap
        {:trigger is_valid_flow(view(graph), other, s, t)} ::
        is_valid_flow(view(graph), other, s, t)
        ==> flow_val(view(graph), maximal, s)
            >= flow_val(view(graph), other, s);

    assert is_max_flow(
        view(graph), maximal, s, t);

    max_val := result.0;

    assert flow_val(view(graph), maximal, s)
        == max_val;
}
