lemma lemma_mul_nonneg(a: nat, b: nat)
  ensures a * b >= 0
  decreases b
{
  if b == 0 {
    assert a * 0 == 0;
  } else {
    lemma_mul_nonneg(a, b - 1);
    assert a * b == a * (b - 1) + a;
  }
}

lemma lemma_mul_neg(y: nat, q: int)
  requires y > 0 && q < 0
  ensures y * q <= -y
  ensures q * y <= -y
  decreases -q
{
  if q == -1 {
    assert y * (-1) == -y;
    assert (-1) * y == -y;
  } else {
    lemma_mul_neg(y, q + 1);
    assert y * q == y * (q + 1) - y;
    assert q * y == (q + 1) * y - y;
  }
}

lemma lemma_mul_ge_one(d: nat, k: nat)
  requires k >= 1
  ensures d <= d * k
  decreases k
{
  if k == 1 {
    assert d * 1 == d;
  } else {
    lemma_mul_ge_one(d, k - 1);
    assert d * k == d * (k - 1) + d;
  }
}

lemma lemma_mul_comm_nat(a: nat, b: nat)
  ensures a * b == b * a
  decreases b
{
  if b == 0 {
    assert a * 0 == 0;
    assert 0 * a == 0;
  } else {
    lemma_mul_comm_nat(a, b - 1);
    calc {
      a * b;
      == a * (b - 1) + a;
      == (b - 1) * a + a;
      == b * a;
    }
  }
}

lemma lemma_mul_add_nat(a: int, b: int, c: nat)
  ensures a * (b + c) == a * b + a * c
  decreases c
{
  if c == 0 {
    assert a * (b + 0) == a * b;
    assert a * 0 == 0;
  } else {
    lemma_mul_add_nat(a, b, c - 1);
    calc {
      a * (b + c);
      == a * ((b + (c - 1)) + 1);
      == a * (b + (c - 1)) + a;
      == (a * b + a * (c - 1)) + a;
      == a * b + (a * (c - 1) + a);
      == a * b + a * c;
    }
  }
}

lemma lemma_mul_sub_nat(a: int, b: int, c: nat)
  ensures a * (b - c) == a * b - a * c
  decreases c
{
  if c == 0 {
    assert a * (b - 0) == a * b;
    assert a * 0 == 0;
  } else {
    lemma_mul_sub_nat(a, b, c - 1);
    calc {
      a * (b - c);
      == a * ((b - (c - 1)) - 1);
      == a * (b - (c - 1)) - a;
      == (a * b - a * (c - 1)) - a;
      == a * b - (a * (c - 1) + a);
      == a * b - a * c;
    }
  }
}

lemma lemma_mul_assoc_nat(a: int, b: nat, c: nat)
  ensures (a * b) * c == a * (b * c)
  decreases c
{
  if c == 0 {
    assert (a * b) * 0 == 0;
    assert b * 0 == 0;
    assert a * 0 == 0;
  } else {
    lemma_mul_assoc_nat(a, b, c - 1);
    lemma_mul_nonneg(b, c - 1);
    lemma_mul_add_nat(a, b * (c - 1), b);
    calc {
      (a * b) * c;
      == (a * b) * (c - 1) + a * b;
      == a * (b * (c - 1)) + a * b;
      == a * (b * (c - 1) + b);
      == a * (b * c);
    }
  }
}

lemma lemma_divides_refl(x: nat)
  ensures divides(x, x)
{
  var k: nat := 1;
  assert x * k == x;
