lemma lemma_divides_le(d: nat, x: nat)
  requires x > 0
  requires divides(d, x)
  ensures d <= x
{
  var k: nat :| d * k == x;
  if k == 0 {
    assert d * 0 == 0;
    assert false;
  } else {
    lemma_mul_ge_one(d, k);
