lemma lemma_div_mod_nat(x: nat, y: nat)
  requires y > 0
  ensures 0 <= x % y < y
  ensures x / y >= 0
  ensures y * (x / y) + (x % y) == x
{
  if x / y < 0 {
    lemma_mul_neg(y, x / y);
    assert false;
  }
  var q: nat := x / y;
  lemma_mul_comm_nat(y, q);
}

lemma lemma_divides_mod(d: nat, x: nat, y: nat)
  requires y > 0
  requires divides(d, x)
  requires divides(d, y)
  ensures divides(d, x % y)
{
  lemma_div_mod_nat(x, y);
  var q: nat := x / y;
  var r: nat := x % y;
  var kx: nat :| d * kx == x;
  var ky: nat :| d * ky == y;
  lemma_mul_nonneg(ky, q);
  var kyq: nat := ky * q;
  lemma_mul_assoc_nat(d, ky, q);
  lemma_mul_sub_nat(d, kx, kyq);
  calc {
    r;
    == x - y * q;
    == d * kx - (d * ky) * q;
    == d * kx - d * kyq;
    == d * (kx - kyq);
  }
  if d == 0 {
    assert d * kx == 0;
    assert x == 0;
    assert r == 0;
    lemma_divides_zero(0);
  } else {
    var kr: int := kx - kyq;
    if kr < 0 {
      lemma_mul_neg(d, kr);
      assert d * kr <= -d;
      assert false;
    }
    var kr_nat: nat := kr;
    assert d * kr_nat == r;
  }
}

lemma lemma_divides_unmod(d: nat, x: nat, y: nat)
  requires y > 0
  requires divides(d, y)
  requires divides(d, x % y)
  ensures divides(d, x)
{
  lemma_div_mod_nat(x, y);
  var q: nat := x / y;
  var r: nat := x % y;
  var ky: nat :| d * ky == y;
  var kr: nat :| d * kr == r;
  lemma_mul_nonneg(ky, q);
  var kyq: nat := ky * q;
  lemma_mul_assoc_nat(d, ky, q);
  lemma_mul_add_nat(d, kyq, kr);
  calc {
    x;
    == y * q + r;
    == (d * ky) * q + d * kr;
    == d * kyq + d * kr;
    == d * (kyq + kr);
  }
  var kx: nat := kyq + kr;
  assert d * kx == x;
}

lemma lemma_gcd_step(x: nat, y: nat)
  requires y > 0
  ensures forall d: nat :: (divides(d, x) && divides(d, y)) <==> (divides(d, y) && divides(d, x % y))
{
  forall d: nat
    ensures (divides(d, x) && divides(d, y)) <==> (divides(d, y) && divides(d, x % y))
  {
    if divides(d, x) && divides(d, y) {
      lemma_divides_mod(d, x, y);
    }
    if divides(d, y) && divides(d, x % y) {
      lemma_divides_unmod(d, x, y);
    }
  }
}

lemma lemma_finish_gcd(a: nat, b: nat, x: nat)
  requires !(a == 0 && b == 0)
  requires x > 0
  requires forall d: nat :: (divides(d, x) && divides(d, 0)) <==> (divides(d, a) && divides(d, b))
  ensures is_gcd(x, a, b)
