            (if n == 1 then [] else Witness(nums[..n-2])) + [n-1]
}

lemma NonnegativePrefix(nums: seq<int>, m: int)
    requires Nonnegative(nums)
    requires 0 <= m <= |nums|
    ensures Nonnegative(nums[..m])
{
    forall i: int | 0 <= i < m
        ensures (nums[..m])[i] >= 0
    {
        assert (nums[..m])[i] == nums[i];
    }
}

lemma LootAppend(houses: seq<int>, x: int, nums: seq<int>)
    ensures total_loot(houses + [x], nums)
         == total_loot(houses, nums)
          + (if 0 <= x < |nums| then nums[x] else 0)
    decreases |houses|
{
    if |houses| > 0 {
        assert (houses + [x])[0] == houses[0];
        assert (houses + [x])[1..] == houses[1..] + [x];
        LootAppend(houses[1..], x, nums);
    }
}

lemma LootPrefix(houses: seq<int>, nums: seq<int>, m: int)
    requires 0 <= m <= |nums|
    requires forall i: int :: 0 <= i < |houses| ==> 0 <= houses[i] < m
    ensures total_loot(houses, nums[..m]) == total_loot(houses, nums)
    decreases |houses|
{
    if |houses| > 0 {
        assert 0 <= houses[0] < m;
        assert (nums[..m])[houses[0]] == nums[houses[0]];

        assert forall i: int ::
            0 <= i < |houses[1..]| ==>
                houses[1..][i] == houses[i+1];

        assert forall i: int ::
            0 <= i < |houses[1..]| ==>
                0 <= houses[1..][i] < m;

        LootPrefix(houses[1..], nums, m);
    }
}

lemma OrderedIndices(
    houses: seq<int>, nums_len: int, i: int, j: int)
    requires is_valid_robbery(houses, nums_len)
    requires 0 <= i <= j < |houses|
    ensures houses[i] <= houses[j]
    decreases j - i
{
    if i < j {
        OrderedIndices(houses, nums_len, i, j-1);
        assert 0 <= j-1 < |houses|-1;
        assert houses[j] >= houses[j-1] + 2;
    }
}

lemma ValidWeaken(houses: seq<int>, small: int, large: int)
    requires is_valid_robbery(houses, small)
    requires small <= large
    ensures is_valid_robbery(houses, large)
{
    forall i: int | 0 <= i < |houses|
        ensures 0 <= houses[i] < large
    {
        assert 0 <= houses[i] < small;
    }
}

lemma ValidWithoutLastHouse(houses: seq<int>, n: int)
    requires n >= 1
    requires is_valid_robbery(houses, n)
    requires |houses| == 0 || houses[|houses|-1] < n-1
    ensures is_valid_robbery(houses, n-1)
{
    if |houses| > 0 {
        var last := |houses|-1;

        forall i: int | 0 <= i < |houses|
            ensures 0 <= houses[i] < n-1
        {
            OrderedIndices(houses, n, i, last);
            assert houses[i] <= houses[last];
        }
    }

    forall i: int | 0 <= i < |houses|-1
        ensures houses[i+1] >= houses[i] + 2
    {
        assert houses[i+1] >= houses[i] + 2;
    }
}

lemma PrefixBeforeLastValid(houses: seq<int>, n: int)
    requires n >= 1
    requires is_valid_robbery(houses, n)
    requires |houses| > 0
    requires houses[|houses|-1] == n-1
    ensures is_valid_robbery(
        houses[..|houses|-1],
        if n == 1 then 0 else n-2)
{
    var last := |houses|-1;
    var prefix := houses[..last];

    if n == 1 {
        if last > 0 {
            assert 0 <= houses[last-1];
            assert houses[last] >= houses[last-1] + 2;
            assert houses[last] == 0;
            assert false;
        }
        assert |prefix| == 0;
    } else {
        forall i: int | 0 <= i < |prefix|
            ensures 0 <= prefix[i] < n-2
        {
            assert prefix[i] == houses[i];
            assert last > 0;
            OrderedIndices(houses, n, i, last-1);
            assert houses[last] >= houses[last-1] + 2;
            assert houses[i] <= houses[last-1];
            assert houses[last] == n-1;
        }

        forall i: int | 0 <= i < |prefix|-1
            ensures prefix[i+1] >= prefix[i] + 2
        {
            assert prefix[i] == houses[i];
            assert prefix[i+1] == houses[i+1];
            assert houses[i+1] >= houses[i] + 2;
        }
    }
}

lemma AppendLastValid(houses: seq<int>, n: int)
    requires n >= 1
    requires is_valid_robbery(
        houses,
        if n == 1 then 0 else n-2)
    ensures is_valid_robbery(houses + [n-1], n)
{
    var bound := if n == 1 then 0 else n-2;
    var result := houses + [n-1];

    if n == 1 && |houses| > 0 {
        assert 0 <= houses[0] < 0;
        assert false;
    }

    forall i: int | 0 <= i < |result|
        ensures 0 <= result[i] < n
    {
        if i < |houses| {
            assert result[i] == houses[i];
            assert 0 <= houses[i] < bound;
        } else {
            assert i == |houses|;
            assert result[i] == n-1;
        }
    }

    forall i: int | 0 <= i < |result|-1
        ensures result[i+1] >= result[i] + 2
    {
        if i < |houses|-1 {
            assert result[i] == houses[i];
            assert result[i+1] == houses[i+1];
            assert houses[i+1] >= houses[i] + 2;
        } else {
            assert i == |houses|-1;
            assert |houses| > 0;
            assert n > 1;
            assert result[i] == houses[i];
            assert result[i+1] == n-1;
            assert houses[i] < n-2;
        }
    }
}

lemma OptNonnegative(nums: seq<int>)
    requires Nonnegative(nums)
    ensures Opt(nums) >= 0
    decreases |nums|
{
    if |nums| > 0 {
        var n := |nums|;
        NonnegativePrefix(nums, n-1);
        OptNonnegative(nums[..n-1]);
        Max2Left(
            Opt(nums[..n-1]),
            nums[n-1] +
                (if n == 1 then 0 else Opt(nums[..n-2])));
    }
}

lemma WitnessProperties(nums: seq<int>)
    requires Nonnegative(nums)
    ensures is_valid_robbery(Witness(nums), |nums|)
    ensures total_loot(Witness(nums), nums) == Opt(nums)
    decreases |nums|
{
    if |nums| == 0 {
        assert Witness(nums) == [];
    } else {
        var n := |nums|;
        var prefix1 := nums[..n-1];
        var skip := Opt(prefix1);
        var tailOpt :=
            if n == 1 then 0 else Opt(nums[..n-2]);
        var take := nums[n-1] + tailOpt;

        NonnegativePrefix(nums, n-1);
        WitnessProperties(prefix1);

        if n > 1 {
            NonnegativePrefix(nums, n-2);
            WitnessProperties(nums[..n-2]);
        }

        if skip >= take {
            assert Witness(nums) == Witness(prefix1);
            ValidWeaken(Witness(prefix1), n-1, n);
            LootPrefix(Witness(prefix1), nums, n-1);
            assert Opt(nums) == skip;
        } else {
            var prior :=
                if n == 1 then [] else Witness(nums[..n-2]);

            assert Witness(nums) == prior + [n-1];

            if n == 1 {
                assert is_valid_robbery(prior, 0);
            } else {
                assert is_valid_robbery(prior, n-2);
            }

            AppendLastValid(prior, n);
            LootAppend(prior, n-1, nums);

            if n == 1 {
                assert prior == [];
                assert total_loot(prior, nums) == 0;
            } else {
                LootPrefix(prior, nums, n-2);
                assert total_loot(prior, nums)
                    == Opt(nums[..n-2]);
            }

            assert 0 <= n-1 < |nums|;
            assert Opt(nums) == take;
        }
    }
}

lemma UpperBound(nums: seq<int>, houses: seq<int>)
    requires Nonnegative(nums)
    requires is_valid_robbery(houses, |nums|)
    ensures total_loot(houses, nums) <= Opt(nums)
    decreases |nums|
{
    if |nums| == 0 {
        if |houses| > 0 {
            assert 0 <= houses[0] < 0;
            assert false;
        }
        assert houses == [];
    } else {
        var n := |nums|;
        var prefix1 := nums[..n-1];
        var skip := Opt(prefix1);
        var tailOpt :=
            if n == 1 then 0 else Opt(nums[..n-2]);
        var take := nums[n-1] + tailOpt;

        if |houses| == 0 {
            OptNonnegative(nums);
            assert total_loot(houses, nums) == 0;
        } else {
            var last := |houses|-1;
            assert 0 <= houses[last] < n;

            if houses[last] == n-1 {
                var prefix := houses[..last];
                assert houses == prefix + [n-1];

                PrefixBeforeLastValid(houses, n);
                LootAppend(prefix, n-1, nums);

                if n == 1 {
                    assert is_valid_robbery(prefix, 0);
                    if |prefix| > 0 {
                        assert 0 <= prefix[0] < 0;
                        assert false;
                    }
                    assert prefix == [];
                    assert total_loot(prefix, nums) == 0;
                } else {
                    NonnegativePrefix(nums, n-2);
                    UpperBound(nums[..n-2], prefix);
                    LootPrefix(prefix, nums, n-2);
                    assert total_loot(prefix, nums)
                        <= Opt(nums[..n-2]);
                }

                Max2Right(skip, take);
                assert Opt(nums) == Max2(skip, take);
            } else {
                assert houses[last] < n-1;
                ValidWithoutLastHouse(houses, n);

                NonnegativePrefix(nums, n-1);
                UpperBound(prefix1, houses);
                LootPrefix(houses, nums, n-1);

                Max2Left(skip, take);
                assert Opt(nums) == Max2(skip, take);
            }
        }
    }
}

method rob(nums: seq<int>) returns (max_amount: int)
    requires |nums| <= 100
    requires forall i: int :: 0 <= i < |nums| ==> nums[i] >= 0
    requires forall i: int :: 0 <= i < |nums| ==> nums[i] <= 10000
    ensures max_amount >= 0
    ensures forall houses: seq<int> :: (is_valid_robbery(houses, |nums|)
            ==> total_loot(houses, nums) <= max_amount)
    ensures exists houses: seq<int> :: (is_valid_robbery(houses, |nums|)
            && total_loot(houses, nums) == max_amount)
{
    assert Nonnegative(nums);

    max_amount := Opt(nums);
    OptNonnegative(nums);
    WitnessProperties(nums);

    forall houses: seq<int> | is_valid_robbery(houses, |nums|)
        ensures total_loot(houses, nums) <= max_amount
    {
        UpperBound(nums, houses);
    }

    var houses := Witness(nums);
    assert is_valid_robbery(houses, |nums|);
    assert total_loot(houses, nums) == max_amount;
    assert exists h: seq<int> ::
        is_valid_robbery(h, |nums|)
        && total_loot(h, nums) == max_amount;
}
