lemma lemma_mul_nonneg(a: nat, b: nat)
  ensures a * b >= 0
  decreases b
{
  if b == 0 {
    assert a * 0 == 0;
  } else {
    lemma_mul_nonneg(a, b - 1);
    assert a * b == a * (b - 1) + a;
  }
}

lemma lemma_mul_neg(y: int, q: int)
  requires y > 0 && q < 0
  ensures y * q <= 0 - y
  ensures q * y <= 0 - y
  decreases 0 - q
{
  if q == -1 {
    assert y * (-1) == 0 - y;
    assert (-1) * y == 0 - y;
  } else {
    lemma_mul_neg(y, q + 1);
    assert y * q == y * (q + 1) - y;
    assert q * y == (q + 1) * y - y;
  }
}

lemma lemma_mul_ge_one(d: nat, k: nat)
  requires k >= 1
  ensures d <= d * k
  decreases k
{
  if k == 1 {
    assert d * 1 == d;
  } else {
    lemma_mul_ge_one(d, k - 1);
    assert d * k == d * (k - 1) + d;
  }
}

lemma lemma_mul_comm_nat(a: nat, b: nat)
  ensures a * b == b * a
  decreases b
{
  if b == 0 {
    assert a * 0 == 0;
    assert 0 * a == 0;
  } else {
    lemma_mul_comm_nat(a, b - 1);
    calc {
      a * b;
      == a * (b - 1) + a;
      == (b - 1) * a + a;
      == b * a;
    }
  }
}

lemma lemma_mul_add_nat(a: int, b: int, c: nat)
  ensures a * (b + c) == a * b + a * c
  decreases c
{
  if c == 0 {
    assert a * (b + 0) == a * b;
    assert a * 0 == 0;
  } else {
    lemma_mul_add_nat(a, b, c - 1);
    calc {
      a * (b + c);
      == a * ((b + (c - 1)) + 1);
      == a * (b + (c - 1)) + a;
      == (a * b + a * (c - 1)) + a;
      == a * b + (a * (c - 1) + a);
      == a * b + a * c;
    }
  }
}

lemma lemma_mul_sub_nat(a: int, b: int, c: nat)
  ensures a * (b - c) == a * b - a * c
  decreases c
{
  if c == 0 {
    assert a * (b - 0) == a * b;
    assert a * 0 == 0;
  } else {
    lemma_mul_sub_nat(a, b, c - 1);
    calc {
      a * (b - c);
      == a * ((b - (c - 1)) - 1);
      == a * (b - (c - 1)) - a;
      == (a * b - a * (c - 1)) - a;
      == a * b - (a * (c - 1) + a);
      == a * b - a * c;
    }
  }
}

lemma lemma_mul_assoc_nat(a: int, b: nat, c: nat)
  ensures (a * b) * c == a * (b * c)
  decreases c
{
  if c == 0 {
    assert (a * b) * 0 == 0;
    assert b * 0 == 0;
    assert a * 0 == 0;
  } else {
    lemma_mul_assoc_nat(a, b, c - 1);
    lemma_mul_nonneg(b, c - 1);
    lemma_mul_add_nat(a, b * (c - 1), b);
    calc {
      (a * b) * c;
      == (a * b) * (c - 1) + a * b;
      == a * (b * (c - 1)) + a * b;
      == a * (b * (c - 1) + b);
      == a * (b * c);
    }
  }
}

lemma lemma_divides_refl(x: nat)
  ensures divides(x, x)
{
  var k: nat := 1;
  assert x * k == x;
}

lemma lemma_divides_zero(x: nat)
  ensures divides(x, 0)
{
  var k: nat := 0;
  assert x * k == 0;
}

lemma lemma_divides_le(d: nat, x: nat)
  requires x > 0
  requires divides(d, x)
  ensures d <= x
{
  var k: nat :| d * k == x;
  if k == 0 {
    assert d * 0 == 0;
    assert false;
  } else {
    lemma_mul_ge_one(d, k);
  }
}

lemma lemma_div_mod_nat(x: nat, y: nat)
  requires y > 0
  ensures 0 <= x % y < y
  ensures x / y >= 0
  ensures y * (x / y) + (x % y) == x
{
  if x / y < 0 {
    lemma_mul_neg(y, x / y);
    assert false;
  }
  var q: nat := x / y;
  lemma_mul_comm_nat(y, q);
}

lemma lemma_divides_mod(d: nat, x: nat, y: nat)
  requires y > 0
  requires divides(d, x)
  requires divides(d, y)
  ensures divides(d, x % y)
{
  lemma_div_mod_nat(x, y);
  var q: nat := x / y;
  var r: nat := x % y;
  var kx: nat :| d * kx == x;
  var ky: nat :| d * ky == y;
  lemma_mul_nonneg(ky, q);
  var kyq: nat := ky * q;
  lemma_mul_assoc_nat(d, ky, q);
  lemma_mul_sub_nat(d, kx, kyq);
  calc {
    r;
    == x - y * q;
    == d * kx - (d * ky) * q;
    == d * kx - d * kyq;
    == d * (kx - kyq);
  }
  if d == 0 {
    assert d * kx == 0;
    assert x == 0;
    assert r == 0;
    lemma_divides_zero(0);
  } else {
    var kr: int := kx - kyq;
    if kr < 0 {
      lemma_mul_neg(d, kr);
      assert d * kr <= 0 - d;
      assert false;
    }
    var kr_nat: nat := kr;
    assert d * kr_nat == r;
  }
}

lemma lemma_divides_unmod(d: nat, x: nat, y: nat)
  requires y > 0
  requires divides(d, y)
  requires divides(d, x % y)
  ensures divides(d, x)
{
  lemma_div_mod_nat(x, y);
  var q: nat := x / y;
  var r: nat := x % y;
  var ky: nat :| d * ky == y;
  var kr: nat :| d * kr == r;
  lemma_mul_nonneg(ky, q);
  var kyq: nat := ky * q;
  lemma_mul_assoc_nat(d, ky, q);
  lemma_mul_add_nat(d, kyq, kr);
  calc {
    x;
    == y * q + r;
    == (d * ky) * q + d * kr;
    == d * kyq + d * kr;
    == d * (kyq + kr);
  }
  var kx: nat := kyq + kr;
  assert d * kx == x;
}

lemma lemma_gcd_step(x: nat, y: nat)
  requires y > 0
  ensures forall d: nat :: (divides(d, x) && divides(d, y)) <==> (divides(d, y) && divides(d, x % y))
{
  forall d: nat
    ensures (divides(d, x) && divides(d, y)) <==> (divides(d, y) && divides(d, x % y))
  {
    if divides(d, x) && divides(d, y) {
      lemma_divides_mod(d, x, y);
    }
    if divides(d, y) && divides(d, x % y) {
      lemma_divides_unmod(d, x, y);
    }
  }
}

lemma lemma_finish_gcd(a: nat, b: nat, x: nat)
  requires !(a == 0 && b == 0)
  requires x > 0
  requires forall d: nat :: (divides(d, x) && divides(d, 0)) <==> (divides(d, a) && divides(d, b))
  ensures is_gcd(x, a, b)
  ensures spec_gcd(a, b) == x
{
  lemma_divides_refl(x);
  lemma_divides_zero(x);
  assert divides(x, x) && divides(x, 0);
  assert divides(x, a) && divides(x, b);
  forall d: nat | divides(d, a) && divides(d, b)
    ensures d <= x
  {
    assert divides(d, x) && divides(d, 0);
    lemma_divides_le(d, x);
  }
  assert is_gcd(x, a, b);
  assert exists g: nat :: is_gcd(g, a, b);
  var s: nat := spec_gcd(a, b);
  assert is_gcd(s, a, b);
  assert divides(s, a) && divides(s, b);
  assert s <= x;
  assert x <= s;
}

method compute_gcd(a: int, b: int) returns (res: int)
  // Simulate u64: inputs are non-negative
  requires a >= 0 && b >= 0
  ensures res == spec_gcd(a, b)
  // Result is unsigned
  ensures res >= 0
{
  if a == 0 && b == 0 {
    return 0;
  }

  var x: nat := a;
  var y: nat := b;

  while y != 0
    invariant x != 0 || y != 0
    invariant forall d: nat :: (divides(d, x) && divides(d, y)) <==> (divides(d, a) && divides(d, b))
    decreases y
  {
    lemma_gcd_step(x, y);
    var r: nat := x % y;
    x := y;
    y := r;
  }

  lemma_finish_gcd(a, b, x);
  res := x;
}

