predicate VRange(x: seq<int>, bound: int)
{
    forall i: int | 0 <= i < |x| ::
        0 <= x[i] <= bound
}

predicate VExtends(prefix: seq<int>, x: seq<int>)
{
    |prefix| <= |x| && x[..|prefix|] == prefix
}

function VGet(x: seq<int>, n: int, u: int, v: int): int
{
    if n > 0 && 0 <= u < n && 0 <= v < n
       && u * n + v < |x|
    then x[u * n + v]
    else 0
}

predicate VEdgeOK(
    g: seq<seq<(int, int)>>,
    u: int,
    v: int,
    value: int
)
{
    value == 0 ||
    exists i: int | 0 <= i < |g[u]| ::
        g[u][i].0 == v
        && value <= g[u][i].1
}

function VSumOut(
    g: seq<seq<(int, int)>>,
    x: seq<int>,
    u: int,
    idx: int
): int
    decreases idx
{
    if idx <= 0 || u < 0 || u >= |g| then
        0
    else if idx - 1 < |g[u]| then
        VSumOut(g, x, u, idx - 1)
        + VGet(x, |g|, u, g[u][idx - 1].0)
    else
        VSumOut(g, x, u, idx - 1)
}

function VSumIn(
    g: seq<seq<(int, int)>>,
    x: seq<int>,
    u: int,
    idx: int
): int
    decreases idx
{
    if idx <= 0 then
        0
    else
        VSumIn(g, x, u, idx - 1)
        + VGet(x, |g|, idx - 1, u)
}

function VTotalOut(
    g: seq<seq<(int, int)>>,
    x: seq<int>,
    u: int
): int
{
    if 0 <= u < |g| then
        VSumOut(g, x, u, |g[u]|)
    else 0
}

function VTotalIn(
    g: seq<seq<(int, int)>>,
    x: seq<int>,
    u: int
): int
{
    VSumIn(g, x, u, |g|)
}

function VFlowValue(
    g: seq<seq<(int, int)>>,
    x: seq<int>,
    s: int
): int
{
    VTotalOut(g, x, s) - VTotalIn(g, x, s)
}

predicate VValid(
    g: seq<seq<(int, int)>>,
    x: seq<int>,
    s: int,
    t: int
)
{
    |x| == |g| * |g|
    && VRange(x, 100000)
    && (forall u: int | 0 <= u < |g| ::
            forall v: int | 0 <= v < |g| ::
                VEdgeOK(g, u, v, VGet(x, |g|, u, v)))
    && (forall u: int | 0 <= u < |g| && u != s && u != t ::
            VTotalIn(g, x, u) == VTotalOut(g, x, u))
}

function Better(
    a: (int, seq<int>),
    b: (int, seq<int>)
): (int, seq<int>)
{
    if a.0 >= b.0 then a else b
}

function EnumerateFlows(
    g: seq<seq<(int, int)>>,
    s: int,
    t: int,
    prefix: seq<int>
): (int, seq<int>)
    requires |prefix| <= |g| * |g|
    decreases |g| * |g| - |prefix|, 100002
{
    if |prefix| == |g| * |g| then
        if VValid(g, prefix, s, t) then
            (VFlowValue(g, prefix, s), prefix)
        else
            (-1, prefix)
    else
        EnumerateValues(g, s, t, prefix, 100000)
}

function EnumerateValues(
    g: seq<seq<(int, int)>>,
    s: int,
    t: int,
    prefix: seq<int>,
    value: int
): (int, seq<int>)
    requires |prefix| < |g| * |g|
    requires 0 <= value <= 100000
    decreases |g| * |g| - |prefix|, value + 1
{
    if value == 0 then
        EnumerateFlows(g, s, t, prefix + [0])
    else
        Better(
            EnumerateFlows(g, s, t, prefix + [value]),
            EnumerateValues(g, s, t, prefix, value - 1)
        )
}

lemma ExtendsAppend(
    prefix: seq<int>,
    x: seq<int>,
    value: int
)
    requires VExtends(prefix + [value], x)
    ensures VExtends(prefix, x)
{
    assert x[..|prefix + [value]|] == prefix + [value];
    assert x[..|prefix|] == prefix;
}

lemma EnumerateFlowsCorrect(
    g: seq<seq<(int, int)>>,
    s: int,
    t: int,
    prefix: seq<int>
)
    requires |prefix| <= |g| * |g|
    requires VRange(prefix, 100000)
    ensures |EnumerateFlows(g, s, t, prefix).1| == |g| * |g|
    ensures VRange(EnumerateFlows(g, s, t, prefix).1, 100000)
    ensures VExtends(prefix, EnumerateFlows(g, s, t, prefix).1)
    ensures EnumerateFlows(g, s, t, prefix).0 ==
        (if VValid(
            g,
            EnumerateFlows(g, s, t, prefix).1,
            s,
            t)
         then VFlowValue(
            g,
            EnumerateFlows(g, s, t, prefix).1,
            s)
         else -1)
    ensures forall x: seq<int> |
        |x| == |g| * |g|
        && VRange(x, 100000)
        && VExtends(prefix, x)
        && VValid(g, x, s, t)
        ::
        EnumerateFlows(g, s, t, prefix).0
            >= VFlowValue(g, x, s)
    decreases |g| * |g| - |prefix|, 100002
{
    if |prefix| == |g| * |g| {
        assert VExtends(prefix, prefix);
    } else {
        EnumerateValuesCorrect(g, s, t, prefix, 100000);

        forall x: seq<int> |
            |x| == |g| * |g|
            && VRange(x, 100000)
            && VExtends(prefix, x)
            && VValid(g, x, s, t)
            ensures EnumerateFlows(g, s, t, prefix).0
                >= VFlowValue(g, x, s)
        {
            assert |prefix| < |x|;
            assert 0 <= x[|prefix|] <= 100000;
        }
    }
}

lemma EnumerateValuesCorrect(
    g: seq<seq<(int, int)>>,
    s: int,
    t: int,
    prefix: seq<int>,
    value: int
)
    requires |prefix| < |g| * |g|
    requires VRange(prefix, 100000)
    requires 0 <= value <= 100000
    ensures |EnumerateValues(g, s, t, prefix, value).1|
        == |g| * |g|
    ensures VRange(
        EnumerateValues(g, s, t, prefix, value).1,
        100000)
    ensures VExtends(
        prefix,
        EnumerateValues(g, s, t, prefix, value).1)
    ensures EnumerateValues(g, s, t, prefix, value).0 ==
        (if VValid(
            g,
            EnumerateValues(g, s, t, prefix, value).1,
            s,
            t)
         then VFlowValue(
            g,
            EnumerateValues(g, s, t, prefix, value).1,
            s)
         else -1)
    ensures forall x: seq<int> |
        |x| == |g| * |g|
        && VRange(x, 100000)
        && VExtends(prefix, x)
        && x[|prefix|] <= value
        && VValid(g, x, s, t)
        ::
        EnumerateValues(g, s, t, prefix, value).0
            >= VFlowValue(g, x, s)
    decreases |g| * |g| - |prefix|, value + 1
{
    if value == 0 {
        assert VRange(prefix + [0], 100000);
        EnumerateFlowsCorrect(g, s, t, prefix + [0]);

        forall x: seq<int> |
            |x| == |g| * |g|
            && VRange(x, 100000)
            && VExtends(prefix, x)
            && x[|prefix|] <= 0
            && VValid(g, x, s, t)
            ensures EnumerateValues(g, s, t, prefix, value).0
                >= VFlowValue(g, x, s)
        {
            assert x[|prefix|] == 0;
            assert x[..|prefix|] == prefix;
            assert x[..|prefix + [0]|] == prefix + [0];
            assert VExtends(prefix + [0], x);
        }

        ExtendsAppend(
            prefix,
            EnumerateFlows(g, s, t, prefix + [0]).1,
