lemma LemmaExtendValidRobbery(h: seq<int>, k: int)
    requires k >= 0
    requires is_valid_robbery(h, k - 1)
    ensures is_valid_robbery(h + [k], k + 1)
{
    var h' := h + [k];
    forall i: int | 0 <= i < |h'|
        ensures 0 <= h'[i] < k + 1
    {
        if i < |h| {
