        } else {
            assert h'[i] == k;
        }
    }
    forall i: int | 0 <= i < |h'| - 1
        ensures h'[i+1] >= h'[i] + 2
    {
        if i < |h| - 1 {
            assert h'[i] == h[i];
            assert h'[i+1] == h[i+1];
        } else {
