        assert h[|h| - 1] == k;
        var h_prev := h[..|h| - 1];
        forall i: int | 0 <= i < |h_prev|
            ensures 0 <= h_prev[i] < k - 1
        {
            LemmaValidRobberyOrder(h, k + 1, i, |h| - 1);
        }
        forall i: int | 0 <= i < |h_prev| - 1
            ensures h_prev[i+1] >= h_prev[i] + 2
        {
            assert h_prev[i] == h[i];
            assert h_prev[i+1] == h[i+1];
        }
        assert is_valid_robbery(h_prev, k - 1);
        assert total_loot(h_prev, nums) <= prev2;
        assert h == h_prev + [k];
        LemmaTotalLootAppend(h_prev, k, nums);
        assert total_loot(h, nums) == total_loot(h_prev, nums) + nums[k];
    }
}

method rob(nums: seq<int>) returns (max_amount: int)
    requires |nums| <= 100
    // Constraints matching Verus u64
    requires forall i: int :: 0 <= i < |nums| ==> nums[i] >= 0
    requires forall i: int :: 0 <= i < |nums| ==> nums[i] <= 10000
    ensures max_amount >= 0
    // 1. Upper Bound
    ensures forall houses: seq<int> :: (is_valid_robbery(houses, |nums|) 
            ==> total_loot(houses, nums) <= max_amount)
    // 2. Existence
    ensures exists houses: seq<int> :: (is_valid_robbery(houses, |nums|) 
            && total_loot(houses, nums) == max_amount)
{
    var prev2: int := 0;
    var prev1: int := 0;
    ghost var houses2: seq<int> := [];
    ghost var houses1: seq<int> := [];

    forall h: seq<int> | is_valid_robbery(h, -1)
        ensures total_loot(h, nums) <= prev2
    {
        LemmaEmptyValidRobbery(h, -1, nums);
    }
    forall h: seq<int> | is_valid_robbery(h, 0)
        ensures total_loot(h, nums) <= prev1
    {
        LemmaEmptyValidRobbery(h, 0, nums);
    }

    var k: int := 0;
    while k < |nums|
        invariant 0 <= k <= |nums|
        invariant prev2 >= 0 && prev1 >= 0
        invariant is_valid_robbery(houses2, k - 1)
        invariant total_loot(houses2, nums) == prev2
        invariant forall h: seq<int> :: is_valid_robbery(h, k - 1) ==> total_loot(h, nums) <= prev2
        invariant is_valid_robbery(houses1, k)
        invariant total_loot(houses1, nums) == prev1
        invariant forall h: seq<int> :: is_valid_robbery(h, k) ==> total_loot(h, nums) <= prev1
        decreases |nums| - k
    {
        var candidate: int := prev2 + nums[k];
        var next: int;
        ghost var houses_next: seq<int>;

        if candidate > prev1 {
            next := candidate;
            houses_next := houses2 + [k];
            LemmaExtendValidRobbery(houses2, k);
            LemmaTotalLootAppend(houses2, k, nums);
        } else {
            next := prev1;
            houses_next := houses1;
            LemmaMonotoneValidRobbery(houses1, k, k + 1);
        }

        forall h: seq<int> | is_valid_robbery(h, k + 1)
            ensures total_loot(h, nums) <= next
        {
            LemmaStepUpperBound(h, k, nums, prev2, prev1, next);
        }

        prev2 := prev1;
        houses2 := houses1;
        prev1 := next;
        houses1 := houses_next;
        k := k + 1;
    }

    max_amount := prev1;
    assert is_valid_robbery(houses1, |nums|) && total_loot(houses1, nums) == max_amount;
}
