lemma swap_preserves_perm(v: seq<int>, s: seq<int>, p: seq<int>, a: int, b: int)
    requires is_perm_with(v, s, p)
    requires 0 <= a < b < |s|
    ensures is_perm_with(v, swap_seq(s, a, b), swap_seq(p, a, b))
{
    var s' := swap_seq(s, a, b);
    var p' := swap_seq(p, a, b);
    var n := |v|;
    assert |p'| == n;
    assert |s'| == n;

    forall i {:trigger p'[i]} | 0 <= i < n
        ensures 0 <= p'[i] < n
        ensures s'[i] == v[p'[i]]
    {
        if i == a {
            assert p'[a] == p[b];
            assert s'[a] == s[b];
            assert s[b] == v[p[b]];
        } else if i == b {
            assert p'[b] == p[a];
            assert s'[b] == s[a];
            assert s[a] == v[p[a]];
        } else {
            assert p'[i] == p[i];
            assert s'[i] == s[i];
            assert s[i] == v[p[i]];
        }
    }

    forall i, j {:trigger p'[i], p'[j]} | 0 <= i < j < n
        ensures p'[i] != p'[j]
    {
        if i == a && j == b {
            assert p'[i] == p[b] && p'[j] == p[a];
            assert p[a] != p[b];
        } else if i == a {
            assert p'[i] == p[b] && p'[j] == p[j];
            if b < j {
                assert p[b] != p[j];
            } else {
                assert j < b;
                assert p[j] != p[b];
            }
        } else if j == a {
            assert p'[i] == p[i] && p'[j] == p[b];
            assert i < a < b;
            assert p[i] != p[b];
        } else if i == b {
            assert p'[i] == p[a] && p'[j] == p[j];
            assert a < b < j;
            assert p[a] != p[j];
        } else if j == b {
            assert p'[i] == p[i] && p'[j] == p[a];
            if i < a {
                assert p[i] != p[a];
            } else {
                assert a < i;
                assert p[a] != p[i];
            }
        } else {
            assert p'[i] == p[i] && p'[j] == p[j];
            assert p[i] != p[j];
        }
    }
}

