lemma swap_step_sorted_lemma(s: seq<int>, i: int, j: int)
    requires 0 < j <= i < |s|
    requires partially_sorted_except(s, i, j)
    requires s[j - 1] > s[j]
    ensures partially_sorted_except(swap_seq(s, j - 1, j), i, j - 1)
{
    var s' := swap_seq(s, j - 1, j);
    forall a, b | 0 <= a < b <= i && b != j - 1
        ensures s'[a] <= s'[b]
    {
        if b == j {
            if a == j - 1 {
                assert s'[a] == s[j] && s'[b] == s[j - 1];
            } else {
                assert 0 <= a < j - 1;
                assert s[a] <= s[j - 1];
                assert s'[a] == s[a] && s'[b] == s[j - 1];
            }
        } else if b > j {
            assert s'[b] == s[b];
            if a == j - 1 {
                assert s'[a] == s[j];
                assert s[j] <= s[b];
            } else if a == j {
                assert s'[a] == s[j - 1];
                assert s[j - 1] <= s[b];
            } else {
                assert s'[a] == s[a];
                assert s[a] <= s[b];
            }
        } else {
            assert b < j - 1;
            assert s'[a] == s[a] && s'[b] == s[b];
            assert s[a] <= s[b];
        }
    }
}

lemma inner_exit_lemma(s: seq<int>, i: int, j: int)
    requires 0 <= j <= i < |s|
    requires partially_sorted_except(s, i, j)
    requires j == 0 || s[j - 1] <= s[j]
    ensures sorted_prefix(s, i + 1)
{
    forall a, b | 0 <= a < b < i + 1
        ensures s[a] <= s[b]
    {
        if b == j {
            assert j > 0;
            assert s[j - 1] <= s[j];
            if a == j - 1 {
            } else {
                assert 0 <= a < j - 1;
                assert s[a] <= s[j - 1];
            }
        } else {
            assert b != j;
            assert s[a] <= s[b];
        }
    }
}

method insertion_sort(v: seq<int>) returns (v_new: seq<int>)
    ensures is_sorted(v_new)
    ensures is_permutation(v, v_new)
{
    v_new := v;
    ghost var p := id_perm(|v|);
    id_perm_is_perm(v);

    var i := 0;
    while i < |v_new|
        invariant 0 <= i <= |v_new|
        invariant |v_new| == |v|
        invariant sorted_prefix(v_new, i)
        invariant is_perm_with(v, v_new, p)
        decreases |v_new| - i
    {
        var j := i;
        inner_entry_lemma(v_new, i);
        while j > 0 && v_new[j - 1] > v_new[j]
            invariant 0 <= j <= i < |v_new|
            invariant |v_new| == |v|
            invariant partially_sorted_except(v_new, i, j)
            invariant is_perm_with(v, v_new, p)
            decreases j
        {
            swap_step_sorted_lemma(v_new, i, j);
            swap_preserves_perm(v, v_new, p, j - 1, j);
            v_new := swap_seq(v_new, j - 1, j);
            p := swap_seq(p, j - 1, j);
            j := j - 1;
        }
        inner_exit_lemma(v_new, i, j);
        i := i + 1;
    }
    assert sorted_prefix(v_new, |v_new|);
    assert is_sorted(v_new);
    perm_witness_lemma(v, v_new, p);
}

