predicate VRange(x: seq<int>, bound: int)
{
    forall i: int | 0 <= i < |x| ::
        0 <= x[i] <= bound
}

predicate VExtends(prefix: seq<int>, x: seq<int>)
{
    |prefix| <= |x| && x[..|prefix|] == prefix
}

function VGet(x: seq<int>, n: int, u: int, v: int): int
{
    if n > 0
       && 0 <= u < n
       && 0 <= v < n
       && u * n + v < |x|
    then x[u * n + v]
    else 0
}

predicate VEdgeOK(
    g: seq<seq<(int, int)>>,
    u: int,
    v: int,
    value: int
)
{
    0 <= u < |g|
    &&
    (
        value == 0
        ||
        exists i: int | 0 <= i < |g[u]| ::
            g[u][i].0 == v
            && value <= g[u][i].1
    )
}

function VSumOut(
    g: seq<seq<(int, int)>>,
    x: seq<int>,
    u: int,
    idx: int
): int
    decreases idx
{
    if idx <= 0 || u < 0 || u >= |g| then
        0
    else if idx - 1 < |g[u]| then
        VSumOut(g, x, u, idx - 1)
        + VGet(x, |g|, u, g[u][idx - 1].0)
    else
        VSumOut(g, x, u, idx - 1)
}

function VSumIn(
    g: seq<seq<(int, int)>>,
    x: seq<int>,
    u: int,
    idx: int
): int
    decreases idx
{
    if idx <= 0 then
        0
    else
        VSumIn(g, x, u, idx - 1)
        + VGet(x, |g|, idx - 1, u)
}

function VTotalOut(
    g: seq<seq<(int, int)>>,
    x: seq<int>,
    u: int
): int
{
    if 0 <= u < |g| then
        VSumOut(g, x, u, |g[u]|)
    else 0
}

function VTotalIn(
    g: seq<seq<(int, int)>>,
    x: seq<int>,
    u: int
): int
{
    VSumIn(g, x, u, |g|)
}

function VFlowValue(
    g: seq<seq<(int, int)>>,
    x: seq<int>,
    s: int
): int
{
