    decreases idx
{
    if idx <= 0 || u < 0 || u >= |g| then
        0
    else if idx - 1 < |g[u]| then
        VSumOut(g, x, u, idx - 1)
        + VGet(x, |g|, u, g[u][idx - 1].0)
    else
        VSumOut(g, x, u, idx - 1)
}

function VSumIn(
    g: seq<seq<(int, int)>>,
    x: seq<int>,
    u: int,
    idx: int
): int
    decreases idx
{
    if idx <= 0 then
        0
    else
        VSumIn(g, x, u, idx - 1)
        + VGet(x, |g|, idx - 1, u)
}

function VTotalOut(
    g: seq<seq<(int, int)>>,
    x: seq<int>,
    u: int
): int
{
    if 0 <= u < |g| then
        VSumOut(g, x, u, |g[u]|)
    else 0
}

function VTotalIn(
    g: seq<seq<(int, int)>>,
    x: seq<int>,
    u: int
): int
{
    VSumIn(g, x, u, |g|)
}

function VFlowValue(
    g: seq<seq<(int, int)>>,
    x: seq<int>,
    s: int
): int
{
    VTotalOut(g, x, s) - VTotalIn(g, x, s)
}

predicate VValid(
    g: seq<seq<(int, int)>>,
    x: seq<int>,
    s: int,
    t: int
)
{
    |x| == |g| * |g|
    && VRange(x, 100000)
    && (forall u: int, v: int
            {:trigger VGet(x, |g|, u, v)}
        | 0 <= u < |g| && 0 <= v < |g| ::
            VEdgeOK(g, u, v, VGet(x, |g|, u, v)))
    && (forall u: int | 0 <= u < |g| && u != s && u != t ::
            VTotalIn(g, x, u) == VTotalOut(g, x, u))
}

function Better(
    a: (int, seq<int>),
    b: (int, seq<int>)
): (int, seq<int>)
{
    if a.0 >= b.0 then a else b
}

function EnumerateFlows(
    g: seq<seq<(int, int)>>,
    s: int,
    t: int,
    prefix: seq<int>
): (int, seq<int>)
    requires |prefix| <= |g| * |g|
    decreases |g| * |g| - |prefix|, 100002
{
    if |prefix| == |g| * |g| then
        if VValid(g, prefix, s, t) then
            (VFlowValue(g, prefix, s), prefix)
        else
            (-1, prefix)
    else
        EnumerateValues(g, s, t, prefix, 100000)
}

function EnumerateValues(
    g: seq<seq<(int, int)>>,
    s: int,
    t: int,
    prefix: seq<int>,
    value: int
): (int, seq<int>)
    requires |prefix| < |g| * |g|
    requires 0 <= value <= 100000
    decreases |g| * |g| - |prefix|, value + 1
{
    if value == 0 then
        EnumerateFlows(g, s, t, prefix + [0])
    else
        Better(
            EnumerateFlows(g, s, t, prefix + [value]),
            EnumerateValues(g, s, t, prefix, value - 1)
        )
}

lemma ExtendsAppend(
    prefix: seq<int>,
    x: seq<int>,
    value: int
)
    requires VExtends(prefix + [value], x)
    ensures VExtends(prefix, x)
{
    assert x[..|prefix + [value]|] == prefix + [value];
    assert x[..|prefix|] == prefix;
}

lemma {:isolate_assertions} EnumerateFlowsCorrect(
    g: seq<seq<(int, int)>>,
    s: int,
    t: int,
    prefix: seq<int>
)
    requires |prefix| <= |g| * |g|
    requires VRange(prefix, 100000)
    ensures |EnumerateFlows(g, s, t, prefix).1| == |g| * |g|
    ensures VRange(EnumerateFlows(g, s, t, prefix).1, 100000)
    ensures VExtends(prefix, EnumerateFlows(g, s, t, prefix).1)
    ensures EnumerateFlows(g, s, t, prefix).0 ==
        (if VValid(
            g,
            EnumerateFlows(g, s, t, prefix).1,
            s,
            t)
         then VFlowValue(
            g,
            EnumerateFlows(g, s, t, prefix).1,
            s)
         else -1)
    ensures forall x: seq<int> |
        |x| == |g| * |g|
        && VRange(x, 100000)
        && VExtends(prefix, x)
        && VValid(g, x, s, t)
        ::
        EnumerateFlows(g, s, t, prefix).0
            >= VFlowValue(g, x, s)
    decreases |g| * |g| - |prefix|, 100002
{
    if |prefix| == |g| * |g| {
        assert VExtends(prefix, prefix);
    } else {
        EnumerateValuesCorrect(g, s, t, prefix, 100000);

        forall x: seq<int> |
            |x| == |g| * |g|
            && VRange(x, 100000)
            && VExtends(prefix, x)
            && VValid(g, x, s, t)
            ensures EnumerateFlows(g, s, t, prefix).0
                >= VFlowValue(g, x, s)
        {
            assert |prefix| < |x|;
            assert 0 <= x[|prefix|] <= 100000;
        }
    }
}

lemma {:isolate_assertions} EnumerateValuesCorrect(
    g: seq<seq<(int, int)>>,
    s: int,
    t: int,
    prefix: seq<int>,
    value: int
)
    requires |prefix| < |g| * |g|
    requires VRange(prefix, 100000)
    requires 0 <= value <= 100000
    ensures |EnumerateValues(g, s, t, prefix, value).1|
        == |g| * |g|
    ensures VRange(
        EnumerateValues(g, s, t, prefix, value).1,
        100000)
    ensures VExtends(
        prefix,
        EnumerateValues(g, s, t, prefix, value).1)
    ensures EnumerateValues(g, s, t, prefix, value).0 ==
        (if VValid(
            g,
            EnumerateValues(g, s, t, prefix, value).1,
            s,
            t)
         then VFlowValue(
            g,
            EnumerateValues(g, s, t, prefix, value).1,
            s)
         else -1)
    ensures forall x: seq<int> |
        |x| == |g| * |g|
        && VRange(x, 100000)
        && VExtends(prefix, x)
        && x[|prefix|] <= value
        && VValid(g, x, s, t)
        ::
        EnumerateValues(g, s, t, prefix, value).0
            >= VFlowValue(g, x, s)
    decreases |g| * |g| - |prefix|, value + 1
{
    if value == 0 {
        assert VRange(prefix + [0], 100000);
        EnumerateFlowsCorrect(g, s, t, prefix + [0]);

        forall x: seq<int> |
            |x| == |g| * |g|
            && VRange(x, 100000)
            && VExtends(prefix, x)
            && x[|prefix|] <= 0
            && VValid(g, x, s, t)
            ensures EnumerateValues(g, s, t, prefix, value).0
                >= VFlowValue(g, x, s)
        {
            assert x[|prefix|] == 0;
            assert x[..|prefix|] == prefix;
            assert x[..|prefix + [0]|] == prefix + [0];
            assert VExtends(prefix + [0], x);
        }

        ExtendsAppend(
            prefix,
            EnumerateFlows(g, s, t, prefix + [0]).1,
            0);
    } else {
        assert VRange(prefix + [value], 100000);
        EnumerateFlowsCorrect(g, s, t, prefix + [value]);
        EnumerateValuesCorrect(g, s, t, prefix, value - 1);

        var a := EnumerateFlows(g, s, t, prefix + [value]);
        var b := EnumerateValues(g, s, t, prefix, value - 1);

        ExtendsAppend(prefix, a.1, value);

        forall x: seq<int> |
            |x| == |g| * |g|
            && VRange(x, 100000)
            && VExtends(prefix, x)
            && x[|prefix|] <= value
            && VValid(g, x, s, t)
            ensures EnumerateValues(g, s, t, prefix, value).0
                >= VFlowValue(g, x, s)
        {
            if x[|prefix|] == value {
                assert x[..|prefix + [value]|] == prefix + [value];
                assert VExtends(prefix + [value], x);
                assert a.0 >= VFlowValue(g, x, s);
                assert Better(a, b).0 >= a.0;
            } else {
                assert x[|prefix|] <= value - 1;
                assert b.0 >= VFlowValue(g, x, s);
                assert Better(a, b).0 >= b.0;
            }
        }
    }
}

ghost function AddVectorRow(
    m: FlowMap,
    x: seq<int>,
    n: int,
    u: int,
    count: int
): FlowMap
    requires n >= 0
    requires |x| == n * n
    requires 0 <= u < n
    requires 0 <= count <= n
    decreases count
{
    if count == 0 then
        m
    else
        AddVectorRow(m, x, n, u, count - 1)
            [ (u, count - 1) := x[u * n + count - 1] ]
}

ghost function VectorMapRows(
    x: seq<int>,
    n: int,
    rows: int
): FlowMap
    requires n >= 0
    requires |x| == n * n
    requires 0 <= rows <= n
    decreases rows
{
    if rows == 0 then
        map[]
    else
        AddVectorRow(
            VectorMapRows(x, n, rows - 1),
            x,
            n,
            rows - 1,
            n)
}

ghost function VectorMap(
    x: seq<int>,
    n: int
): FlowMap
    requires n >= 0
    requires |x| == n * n
{
    VectorMapRows(x, n, n)
}

lemma AddVectorRowSame(
    m: FlowMap,
    x: seq<int>,
    n: int,
    u: int,
    count: int,
    v: int
)
    requires n > 0
    requires |x| == n * n
    requires 0 <= u < n
    requires 0 <= v < count <= n
    ensures get_flow(
        AddVectorRow(m, x, n, u, count), u, v)
        == x[u * n + v]
    decreases count
{
    assert 0 <= u * n + v < n * n;

    if count > 1 && v < count - 1 {
        AddVectorRowSame(m, x, n, u, count - 1, v);
        assert (u, v) != (u, count - 1);
    } else {
        assert v == count - 1;
    }
}

lemma AddVectorRowOther(
    m: FlowMap,
    x: seq<int>,
    n: int,
    u: int,
    count: int,
    a: int,
    b: int
)
    requires n > 0
    requires |x| == n * n
    requires 0 <= u < n
    requires 0 <= count <= n
    requires a != u
    ensures get_flow(
        AddVectorRow(m, x, n, u, count), a, b)
        == get_flow(m, a, b)
    decreases count
{
    if count > 0 {
        AddVectorRowOther(m, x, n, u, count - 1, a, b);
        assert (a, b) != (u, count - 1);
    }
}

lemma {:isolate_assertions} VectorMapRowsGet(
    x: seq<int>,
    n: int,
    rows: int,
    u: int,
    v: int
)
    requires n > 0
    requires |x| == n * n
    requires 0 <= rows <= n
    requires 0 <= u < rows
    requires 0 <= v < n
    ensures get_flow(VectorMapRows(x, n, rows), u, v)
        == x[u * n + v]
    decreases rows
{
    if u == rows - 1 {
        AddVectorRowSame(
            VectorMapRows(x, n, rows - 1),
            x, n, rows - 1, n, v);
    } else {
        assert u < rows - 1;
        VectorMapRowsGet(x, n, rows - 1, u, v);
        AddVectorRowOther(
            VectorMapRows(x, n, rows - 1),
            x, n, rows - 1, n, u, v);
    }
}

lemma {:isolate_assertions} VectorMapGet(
    x: seq<int>,
    n: int,
    u: int,
    v: int
)
    requires n >= 0
    requires |x| == n * n
    requires 0 <= u < n
    requires 0 <= v < n
    ensures get_flow(VectorMap(x, n), u, v)
        == VGet(x, n, u, v)
{
    assert n > 0;
    assert 0 <= u * n + v < n * n;
    VectorMapRowsGet(x, n, n, u, v);
}

lemma VectorOutSame(
    g: seq<seq<(int, int)>>,
    x: seq<int>,
    u: int,
    idx: int
)
    requires |x| == |g| * |g|
    requires 0 <= u < |g|
    requires 0 <= idx <= |g[u]|
    ensures sum_flow_out_recursive(
        g, VectorMap(x, |g|), u, idx)
        == VSumOut(g, x, u, idx)
    decreases idx
{
    if idx > 0 {
        VectorOutSame(g, x, u, idx - 1);
        var v := g[u][idx - 1].0;
        if 0 <= v < |g| {
            VectorMapGet(x, |g|, u, v);
        }
    }
}

lemma VectorInSame(
    g: seq<seq<(int, int)>>,
    x: seq<int>,
    u: int,
    idx: int
)
    requires |x| == |g| * |g|
    requires 0 <= u < |g|
    requires 0 <= idx <= |g|
    ensures sum_flow_in_recursive(
        g, VectorMap(x, |g|), u, idx)
        == VSumIn(g, x, u, idx)
    decreases idx
{
    if idx > 0 {
        VectorInSame(g, x, u, idx - 1);
        VectorMapGet(x, |g|, idx - 1, u);
    }
}

lemma {:isolate_assertions} VectorFlowValid(
    g: seq<seq<(int, int)>>,
    x: seq<int>,
    s: int,
    t: int
)
    requires well_formed(CapacityGraph(g))
    requires VValid(g, x, s, t)
    ensures is_valid_flow(g, VectorMap(x, |g|), s, t)
    ensures flow_val(g, VectorMap(x, |g|), s)
        == VFlowValue(g, x, s)
{
    ghost var f := VectorMap(x, |g|);

    forall u: int, v: int |
        (u, v) in f
        ensures f[(u, v)] >= 0
    {
        if 0 <= u < |g| && 0 <= v < |g| {
            VectorMapGet(x, |g|, u, v);
            assert 0 <= VGet(x, |g|, u, v);
        } else {
            assert (u, v) !in f;
        }
    }

    forall u: int, v: int |
        (u, v) in f
        ensures f[(u, v)] > 0 ==>
            exists c: int ::
                has_capacity(g, u, v, c)
                && f[(u, v)] <= c
    {
        assert 0 <= u < |g|;
        assert 0 <= v < |g|;
        VectorMapGet(x, |g|, u, v);

        if f[(u, v)] > 0 {
            assert VEdgeOK(g, u, v, VGet(x, |g|, u, v));
            var i: int :|
                0 <= i < |g[u]|
                && g[u][i].0 == v
                && VGet(x, |g|, u, v) <= g[u][i].1;
            assert has_capacity(g, u, v, g[u][i].1);
        }
    }

    assert respects_capacity(g, f);

    forall u: int |
        0 <= u < |g| && u != s && u != t
        ensures total_flow_in(g, f, u)
            == total_flow_out(g, f, u)
    {
        VectorInSame(g, x, u, |g|);
        VectorOutSame(g, x, u, |g[u]|);
        assert VTotalIn(g, x, u) == VTotalOut(g, x, u);
    }

    assert is_conserved(g, f, s, t);
    assert is_valid_flow(g, f, s, t);

    VectorInSame(g, x, s, |g|);
    VectorOutSame(g, x, s, |g[s]|);
}

lemma {:isolate_assertions} DivisionIndex(
    n: int,
    u: int,
    v: int
)
    requires n > 0
    requires 0 <= u < n
    requires 0 <= v < n
    ensures (u * n + v) / n == u
    ensures (u * n + v) % n == v
{
    assert u * n <= u * n + v;
    assert u * n + v < u * n + n;
    assert u * n + n == (u + 1) * n;
    assert (u * n + v) / n == u;
    assert u * n + v ==
        ((u * n + v) / n) * n + (u * n + v) % n;
}

ghost function ExtractVector(
    g: seq<seq<(int, int)>>,
    f: FlowMap
): seq<int>
    requires |g| > 0
{
    seq(|g| * |g|,
        k => get_flow(f, k / |g|, k % |g|))
}

lemma {:isolate_assertions} ExtractGet(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int,
    v: int
)
    requires |g| > 0
    requires 0 <= u < |g|
    requires 0 <= v < |g|
    ensures VGet(
        ExtractVector(g, f), |g|, u, v)
        == get_flow(f, u, v)
{
    DivisionIndex(|g|, u, v);
    assert 0 <= u * |g| + v < |g| * |g|;
    assert ExtractVector(g, f)[u * |g| + v]
        == get_flow(f, u, v);
}

lemma ExtractOutSame(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int,
    idx: int
)
    requires |g| > 0
    requires well_formed(CapacityGraph(g))
    requires 0 <= u < |g|
    requires 0 <= idx <= |g[u]|
    ensures VSumOut(
        g, ExtractVector(g, f), u, idx)
        == sum_flow_out_recursive(g, f, u, idx)
    decreases idx
{
    if idx > 0 {
        ExtractOutSame(g, f, u, idx - 1);
        var v := g[u][idx - 1].0;
        assert 0 <= v < |g|;
        ExtractGet(g, f, u, v);
    }
}

lemma ExtractInSame(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    u: int,
    idx: int
)
    requires |g| > 0
    requires 0 <= u < |g|
    requires 0 <= idx <= |g|
    ensures VSumIn(
        g, ExtractVector(g, f), u, idx)
        == sum_flow_in_recursive(g, f, u, idx)
    decreases idx
{
    if idx > 0 {
        ExtractInSame(g, f, u, idx - 1);
        ExtractGet(g, f, idx - 1, u);
    }
}

lemma {:isolate_assertions} ExtractValid(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int
)
    requires |g| > 0
    requires well_formed(CapacityGraph(g))
    requires capacities_bounded(g)
    requires is_valid_flow(g, f, s, t)
    requires 0 <= s < |g|
    ensures VValid(g, ExtractVector(g, f), s, t)
    ensures VFlowValue(g, ExtractVector(g, f), s)
        == flow_val(g, f, s)
{
    ghost var x := ExtractVector(g, f);

    forall k: int | 0 <= k < |x|
        ensures 0 <= x[k] <= 100000
    {
        var u := k / |g|;
        var v := k % |g|;

        assert 0 <= u < |g|;
        assert 0 <= v < |g|;
        assert x[k] == get_flow(f, u, v);

        if (u, v) in f {
            assert f[(u, v)] >= 0;
            if f[(u, v)] > 0 {
                var c: int :|
                    has_capacity(g, u, v, c)
                    && f[(u, v)] <= c;
                assert 0 <= c <= 100000;
            }
        } else {
            assert get_flow(f, u, v) == 0;
        }
    }

    assert VRange(x, 100000);

    forall u: int, v: int
        | 0 <= u < |g| && 0 <= v < |g|
        ensures VEdgeOK(g, u, v, VGet(x, |g|, u, v))
    {
        ExtractGet(g, f, u, v);

        if get_flow(f, u, v) > 0 {
            assert (u, v) in f;
            var c: int :|
                has_capacity(g, u, v, c)
                && f[(u, v)] <= c;
            var i: int :|
                0 <= u < |g|
                && 0 <= i < |g[u]|
                && g[u][i].0 == v
                && g[u][i].1 == c;
            assert VEdgeOK(g, u, v, VGet(x, |g|, u, v));
        } else {
            assert get_flow(f, u, v) >= 0;
            assert get_flow(f, u, v) == 0;
        }
    }

    forall u: int |
        0 <= u < |g| && u != s && u != t
        ensures VTotalIn(g, x, u)
            == VTotalOut(g, x, u)
    {
        ExtractInSame(g, f, u, |g|);
        ExtractOutSame(g, f, u, |g[u]|);
        assert total_flow_in(g, f, u)
            == total_flow_out(g, f, u);
    }

    assert VValid(g, x, s, t);

    ExtractInSame(g, f, s, |g|);
    ExtractOutSame(g, f, s, |g[s]|);
}

lemma ZeroVSumOut(
    g: seq<seq<(int, int)>>,
    n: int,
    u: int,
    idx: int
)
    requires n == |g| * |g|
    requires 0 <= u < |g|
    requires 0 <= idx <= |g[u]|
    ensures VSumOut(g, seq(n, k => 0), u, idx) == 0
    decreases idx
{
    if idx > 0 {
        ZeroVSumOut(g, n, u, idx - 1);
    }
}

lemma ZeroVSumIn(
    g: seq<seq<(int, int)>>,
    n: int,
    u: int,
    idx: int
)
    requires n == |g| * |g|
    requires 0 <= u < |g|
    requires 0 <= idx <= |g|
    ensures VSumIn(g, seq(n, k => 0), u, idx) == 0
    decreases idx
{
    if idx > 0 {
        ZeroVSumIn(g, n, u, idx - 1);
    }
}

lemma {:isolate_assertions} ZeroVectorValid(
    g: seq<seq<(int, int)>>,
    s: int,
    t: int
)
    requires 0 <= s < |g|
    ensures VValid(
        g, seq(|g| * |g|, k => 0), s, t)
    ensures VFlowValue(
        g, seq(|g| * |g|, k => 0), s) == 0
{
    ghost var z := seq(|g| * |g|, k => 0);

    assert VRange(z, 100000);

    forall u: int, v: int
        | 0 <= u < |g| && 0 <= v < |g|
        ensures VEdgeOK(g, u, v, VGet(z, |g|, u, v))
    {
        assert 0 <= u * |g| + v < |g| * |g|;
        assert VGet(z, |g|, u, v) == 0;
    }

    forall u: int |
        0 <= u < |g| && u != s && u != t
        ensures VTotalIn(g, z, u)
            == VTotalOut(g, z, u)
    {
        ZeroVSumIn(g, |g| * |g|, u, |g|);
        ZeroVSumOut(g, |g| * |g|, u, |g[u]|);
    }

    ZeroVSumIn(g, |g| * |g|, s, |g|);
    ZeroVSumOut(g, |g| * |g|, s, |g[s]|);
}

method {:isolate_assertions} max_flow_value(
    graph: CapacityGraph,
    s: int,
    t: int
) returns (max_val: int)
    requires well_formed(graph)
    requires capacities_bounded(view(graph))
    requires 0 <= s < size(graph)
    requires 0 <= t < size(graph)
    requires s != t
    ensures exists f: FlowMap ::
            is_max_flow(view(graph), f, s, t)
            && flow_val(view(graph), f, s) == max_val
{
    var result := EnumerateFlows(graph.adj, s, t, []);

    EnumerateFlowsCorrect(graph.adj, s, t, []);

    ghost var zero :=
        seq(|graph.adj| * |graph.adj|, k => 0);

    ZeroVectorValid(graph.adj, s, t);

    assert VExtends([], zero);
    assert result.0 >= VFlowValue(graph.adj, zero, s);
    assert result.0 >= 0;
    assert VValid(graph.adj, result.1, s, t);
    assert result.0 == VFlowValue(graph.adj, result.1, s);

    ghost var maximal :=
        VectorMap(result.1, |graph.adj|);

    VectorFlowValid(graph.adj, result.1, s, t);

    forall other: FlowMap
        | is_valid_flow(graph.adj, other, s, t)
        ensures flow_val(graph.adj, maximal, s)
            >= flow_val(graph.adj, other, s)
    {
        ExtractValid(graph.adj, other, s, t);

        ghost var extracted :=
            ExtractVector(graph.adj, other);

        assert |extracted| == |graph.adj| * |graph.adj|;
        assert VRange(extracted, 100000);
        assert VExtends([], extracted);

        assert result.0
            >= VFlowValue(graph.adj, extracted, s);
        assert VFlowValue(graph.adj, extracted, s)
            == flow_val(graph.adj, other, s);
        assert flow_val(graph.adj, maximal, s)
            == result.0;
    }

    assert forall other: FlowMap
        {:trigger is_valid_flow(graph.adj, other, s, t)} ::
        is_valid_flow(graph.adj, other, s, t)
        ==> flow_val(graph.adj, maximal, s)
            >= flow_val(graph.adj, other, s);

    assert is_max_flow(graph.adj, maximal, s, t);

    max_val := result.0;

    assert graph.adj == view(graph);
    assert flow_val(view(graph), maximal, s) == max_val;
    assert is_max_flow(view(graph), maximal, s, t);
}
