// ================= Generic double-sum machinery =================

ghost function Row2(h: (int, int) -> int, u: int, b: int): int
  decreases b
{
  if b <= 0 then 0 else Row2(h, u, b - 1) + h(u, b - 1)
}

ghost function Col2(h: (int, int) -> int, v: int, a: int): int
  decreases a
{
  if a <= 0 then 0 else Col2(h, v, a - 1) + h(a - 1, v)
}

ghost function SumR(h: (int, int) -> int, a: int, b: int): int
  decreases a
{
  if a <= 0 then 0 else SumR(h, a - 1, b) + Row2(h, a - 1, b)
}

ghost function SumC(h: (int, int) -> int, b: int, a: int): int
  decreases b
{
  if b <= 0 then 0 else SumC(h, b - 1, a) + Col2(h, b - 1, a)
}

ghost function Net(h: (int, int) -> int, u: int, n: int): int
{
  Row2(h, u, n) - Col2(h, u, n)
}

lemma Row2Ext(h1: (int, int) -> int, h2: (int, int) -> int, u: int, b: int)
  requires forall v :: 0 <= v < b ==> h1(u, v) == h2(u, v)
  ensures Row2(h1, u, b) == Row2(h2, u, b)
  decreases b
{
  if b > 0 { Row2Ext(h1, h2, u, b - 1); }
}

lemma Col2Ext(h1: (int, int) -> int, h2: (int, int) -> int, v: int, a: int)
  requires forall x :: 0 <= x < a ==> h1(x, v) == h2(x, v)
  ensures Col2(h1, v, a) == Col2(h2, v, a)
  decreases a
{
  if a > 0 { Col2Ext(h1, h2, v, a - 1); }
}

lemma Row2Mono(h1: (int, int) -> int, h2: (int, int) -> int, u: int, b: int)
  requires forall v :: 0 <= v < b ==> h1(u, v) <= h2(u, v)
  ensures Row2(h1, u, b) <= Row2(h2, u, b)
  decreases b
{
  if b > 0 { Row2Mono(h1, h2, u, b - 1); }
}

lemma SumRMono(h1: (int, int) -> int, h2: (int, int) -> int, a: int, b: int)
  requires forall u, v :: 0 <= u < a && 0 <= v < b ==> h1(u, v) <= h2(u, v)
  ensures SumR(h1, a, b) <= SumR(h2, a, b)
  decreases a
{
  if a > 0 {
    SumRMono(h1, h2, a - 1, b);
    Row2Mono(h1, h2, a - 1, b);
  }
}

lemma Row2Zero(h: (int, int) -> int, u: int, b: int)
  requires forall v :: 0 <= v < b ==> h(u, v) == 0
  ensures Row2(h, u, b) == 0
  decreases b
{
  if b > 0 { Row2Zero(h, u, b - 1); }
}

lemma Col2Zero(h: (int, int) -> int, v: int, a: int)
  requires forall x :: 0 <= x < a ==> h(x, v) == 0
  ensures Col2(h, v, a) == 0
  decreases a
{
  if a > 0 { Col2Zero(h, v, a - 1); }
}

lemma Col2NonNeg(h: (int, int) -> int, v: int, a: int)
  requires forall x :: 0 <= x < a ==> h(x, v) >= 0
  ensures Col2(h, v, a) >= 0
  decreases a
{
  if a > 0 { Col2NonNeg(h, v, a - 1); }
}

lemma Row2Lin(h: (int, int) -> int, h1: (int, int) -> int, h2: (int, int) -> int, u: int, b: int)
  requires forall v :: 0 <= v < b ==> h(u, v) == h1(u, v) - h2(u, v)
  ensures Row2(h, u, b) == Row2(h1, u, b) - Row2(h2, u, b)
  decreases b
{
  if b > 0 { Row2Lin(h, h1, h2, u, b - 1); }
}

lemma SumRLin(h: (int, int) -> int, h1: (int, int) -> int, h2: (int, int) -> int, a: int, b: int)
  requires forall u, v :: 0 <= u < a && 0 <= v < b ==> h(u, v) == h1(u, v) - h2(u, v)
  ensures SumR(h, a, b) == SumR(h1, a, b) - SumR(h2, a, b)
  decreases a
{
  if a > 0 {
    SumRLin(h, h1, h2, a - 1, b);
    Row2Lin(h, h1, h2, a - 1, b);
  }
}

lemma Row2Upd(h: (int, int) -> int, hn: (int, int) -> int, a: int, c: int, d: int, u: int, m: int)
  requires forall x, y :: hn(x, y) == h(x, y) + (if x == a && y == c then d else 0)
  ensures Row2(hn, u, m) == Row2(h, u, m) + (if u == a && 0 <= c < m then d else 0)
  decreases m
{
  if m > 0 { Row2Upd(h, hn, a, c, d, u, m - 1); }
}

lemma Col2Upd(h: (int, int) -> int, hn: (int, int) -> int, a: int, c: int, d: int, u: int, m: int)
  requires forall x, y :: hn(x, y) == h(x, y) + (if x == a && y == c then d else 0)
  ensures Col2(hn, u, m) == Col2(h, u, m) + (if u == c && 0 <= a < m then d else 0)
  decreases m
{
  if m > 0 { Col2Upd(h, hn, a, c, d, u, m - 1); }
}

lemma SumCZero(h: (int, int) -> int, b: int)
  ensures SumC(h, b, 0) == 0
  decreases b
{
  if b > 0 { SumCZero(h, b - 1); }
}

lemma SwapStep(h: (int, int) -> int, a: int, b: int)
  requires a >= 1
  ensures SumC(h, b, a) == SumC(h, b, a - 1) + Row2(h, a - 1, b)
  decreases b
{
  if b > 0 {
    SwapStep(h, a, b - 1);
    assert Col2(h, b - 1, a) == Col2(h, b - 1, a - 1) + h(a - 1, b - 1);
    assert Row2(h, a - 1, b) == Row2(h, a - 1, b - 1) + h(a - 1, b - 1);
  }
}

lemma Swap(h: (int, int) -> int, a: int, b: int)
  requires a >= 0
  ensures SumR(h, a, b) == SumC(h, b, a)
  decreases a
{
  if a > 0 {
    Swap(h, a - 1, b);
    SwapStep(h, a, b);
  } else {
    SumCZero(h, b);
  }
}

// ================= Cut machinery =================

ghost predicate InVis(vis: seq<bool>, u: int) {
  0 <= u < |vis| && vis[u]
}

ghost function At(M: seq<seq<int>>, x: int, y: int): int {
  if 0 <= x < |M| && 0 <= y < |M[x]| then M[x][y] else 0
}

ghost function MF(M: seq<seq<int>>): (int, int) -> int {
  (x: int, y: int) => At(M, x, y)
}

ghost function FF(f: FlowMap): (int, int) -> int {
  (x: int, y: int) => get_flow(f, x, y)
}

ghost function AA(h: (int, int) -> int, vis: seq<bool>): (int, int) -> int {
  (x: int, y: int) => if InVis(vis, x) then h(x, y) else 0
}

ghost function BB(h: (int, int) -> int, vis: seq<bool>): (int, int) -> int {
  (x: int, y: int) => if InVis(vis, y) then h(x, y) else 0
}

ghost function TT(h: (int, int) -> int, vis: seq<bool>): (int, int) -> int {
  (x: int, y: int) => (if InVis(vis, x) then h(x, y) else 0) - (if InVis(vis, y) then h(x, y) else 0)
}

ghost function KK(C: seq<seq<int>>, vis: seq<bool>): (int, int) -> int {
  (x: int, y: int) => if InVis(vis, x) && !InVis(vis, y) then At(C, x, y) else 0
}

ghost function WS(h: (int, int) -> int, vis: seq<bool>, k: int, n: int): int
  decreases k
{
  if k <= 0 then 0 else WS(h, vis, k - 1, n) + (if InVis(vis, k - 1) then Net(h, k - 1, n) else 0)
}

lemma WSSplit(h: (int, int) -> int, vis: seq<bool>, k: int, n: int)
  requires k >= 0
  ensures WS(h, vis, k, n) == SumR(AA(h, vis), k, n) - SumC(BB(h, vis), k, n)
  decreases k
{
  if k > 0 {
    WSSplit(h, vis, k - 1, n);
    var u := k - 1;
    if InVis(vis, u) {
      Row2Ext(AA(h, vis), h, u, n);
      Col2Ext(BB(h, vis), h, u, n);
    } else {
      Row2Zero(AA(h, vis), u, n);
      Col2Zero(BB(h, vis), u, n);
    }
  }
}

lemma WSCons(h: (int, int) -> int, vis: seq<bool>, k: int, n: int, s: int, t: int)
  requires 0 <= k <= n && 0 <= s < n && 0 <= t < n && s != t
  requires |vis| == n && vis[s] && !vis[t]
  requires forall u :: 0 <= u < n && u != s && u != t ==> Net(h, u, n) == 0
  ensures WS(h, vis, k, n) == (if s < k then Net(h, s, n) else 0)
  decreases k
{
  if k > 0 { WSCons(h, vis, k - 1, n, s, t); }
}

lemma CutLemma(h: (int, int) -> int, vis: seq<bool>, n: int, s: int, t: int)
  requires 0 <= s < n && 0 <= t < n && s != t && |vis| == n && vis[s] && !vis[t]
  requires forall u :: 0 <= u < n && u != s && u != t ==> Net(h, u, n) == 0
  ensures Net(h, s, n) == SumR(TT(h, vis), n, n)
{
  WSCons(h, vis, n, n, s, t);
  WSSplit(h, vis, n, n);
  Swap(BB(h, vis), n, n);
  forall u, v | 0 <= u < n && 0 <= v < n
    ensures TT(h, vis)(u, v) == AA(h, vis)(u, v) - BB(h, vis)(u, v)
  {
  }
  SumRLin(TT(h, vis), AA(h, vis), BB(h, vis), n, n);
}

// ================= Matrices / capacities =================

ghost predicate Square(M: seq<seq<int>>, n: int) {
  |M| == n && forall i :: 0 <= i < n ==> |M[i]| == n
}

ghost predicate CapEntry(g: seq<seq<(int, int)>>, i: int, j: int, c: int) {
  c >= 0 && (c > 0 ==> has_capacity(g, i, j, c)) && (forall c2 :: has_capacity(g, i, j, c2) ==> c2 == c)
}

ghost predicate CapOK(g: seq<seq<(int, int)>>, C: seq<seq<int>>) {
  Square(C, |g|) && forall i, j :: 0 <= i < |g| && 0 <= j < |g| ==> CapEntry(g, i, j, C[i][j])
}

ghost predicate IsTarget(g: seq<seq<(int, int)>>, u: int, v: int) {
  0 <= u < |g| && exists i :: 0 <= i < |g[u]| && g[u][i].0 == v
}

predicate Res(C: seq<seq<int>>, F: seq<seq<int>>, u: int, v: int)
  requires 0 <= u < |C| && 0 <= v < |C| && |F| == |C|
  requires |C[u]| == |C| && |F[u]| == |C| && |F[v]| == |C|
{
  F[u][v] < C[u][v] || F[v][u] > 0
}

// ================= Adjacency-sum vs full-sum =================

ghost predicate InPrefix(adj: seq<(int, int)>, k: int, v: int)
  decreases k
{
  0 < k <= |adj| && (adj[k - 1].0 == v || InPrefix(adj, k - 1, v))
}

ghost function PartRow(f: FlowMap, u: int, adj: seq<(int, int)>, k: int, m: int): int
  decreases m
{
  if m <= 0 then 0
  else PartRow(f, u, adj, k, m - 1) + (if InPrefix(adj, k, m - 1) then get_flow(f, u, m - 1) else 0)
}

lemma NotInPrefix(adj: seq<(int, int)>, k: int, v: int)
  requires 0 <= k <= |adj|
  requires forall i :: 0 <= i < k ==> adj[i].0 != v
  ensures !InPrefix(adj, k, v)
  decreases k
{
  if k > 0 { NotInPrefix(adj, k - 1, v); }
}

lemma InPrefixIntro(adj: seq<(int, int)>, k: int, i: int)
  requires 0 <= i < k <= |adj|
  ensures InPrefix(adj, k, adj[i].0)
  decreases k
{
  if i < k - 1 { InPrefixIntro(adj, k - 1, i); }
}

lemma PartRowZero(f: FlowMap, u: int, adj: seq<(int, int)>, m: int)
  ensures PartRow(f, u, adj, 0, m) == 0
  decreases m
{
  if m > 0 { PartRowZero(f, u, adj, m - 1); }
}

lemma PartRowStep(f: FlowMap, u: int, adj: seq<(int, int)>, k: int, m: int)
  requires 0 <= k < |adj| && !InPrefix(adj, k, adj[k].0)
  ensures PartRow(f, u, adj, k + 1, m)
          == PartRow(f, u, adj, k, m) + (if 0 <= adj[k].0 < m then get_flow(f, u, adj[k].0) else 0)
  decreases m
{
  if m > 0 { PartRowStep(f, u, adj, k, m - 1); }
}

lemma PartRowFull(f: FlowMap, u: int, adj: seq<(int, int)>, m: int)
  requires forall v :: 0 <= v < m && !InPrefix(adj, |adj|, v) ==> get_flow(f, u, v) == 0
  ensures PartRow(f, u, adj, |adj|, m) == Row2(FF(f), u, m)
  decreases m
{
  if m > 0 { PartRowFull(f, u, adj, m - 1); }
}

lemma OutSum(graph: CapacityGraph, f: FlowMap, u: int, k: int)
  requires well_formed(graph) && 0 <= u < |graph.adj| && 0 <= k <= |graph.adj[u]|
  ensures sum_flow_out_recursive(graph.adj, f, u, k) == PartRow(f, u, graph.adj[u], k, |graph.adj|)
  decreases k
{
  if k == 0 {
    PartRowZero(f, u, graph.adj[u], |graph.adj|);
  } else {
    OutSum(graph, f, u, k - 1);
    NotInPrefix(graph.adj[u], k - 1, graph.adj[u][k - 1].0);
    PartRowStep(f, u, graph.adj[u], k - 1, |graph.adj|);
  }
}

lemma TotalOut(graph: CapacityGraph, f: FlowMap, u: int)
  requires well_formed(graph)
  requires 0 <= u < |graph.adj|
  requires forall v :: 0 <= v < |graph.adj| && !IsTarget(graph.adj, u, v) ==> get_flow(f, u, v) == 0
  ensures total_flow_out(graph.adj, f, u) == Row2(FF(f), u, |graph.adj|)
{
  OutSum(graph, f, u, |graph.adj[u]|);
  forall v | 0 <= v < |graph.adj| && !InPrefix(graph.adj[u], |graph.adj[u]|, v)
    ensures get_flow(f, u, v) == 0
  {
    if IsTarget(graph.adj, u, v) {
      var i :| 0 <= i < |graph.adj[u]| && graph.adj[u][i].0 == v;
      InPrefixIntro(graph.adj[u], |graph.adj[u]|, i);
      assert false;
    }
  }
  PartRowFull(f, u, graph.adj[u], |graph.adj|);
}

lemma InSum(g: seq<seq<(int, int)>>, f: FlowMap, u: int, k: int)
  ensures sum_flow_in_recursive(g, f, u, k) == Col2(FF(f), u, k)
  decreases k
{
  if k > 0 { InSum(g, f, u, k - 1); }
}

// ================= Facts about arbitrary valid flows =================

lemma GetFlowBounds(g: seq<seq<(int, int)>>, C: seq<seq<int>>, f: FlowMap, s: int, t: int, u: int, v: int)
  requires CapOK(g, C) && is_valid_flow(g, f, s, t)
  requires 0 <= u < |g| && 0 <= v < |g|
  ensures 0 <= get_flow(f, u, v) <= C[u][v]
  ensures get_flow(f, u, v) > 0 ==> IsTarget(g, u, v)
{
  assert CapEntry(g, u, v, C[u][v]);
  if (u, v) in f {
    assert f[(u, v)] >= 0;
    if f[(u, v)] > 0 {
      var c :| has_capacity(g, u, v, c) && f[(u, v)] <= c;
      var i :| 0 <= u < |g| && 0 <= i < |g[u]| && g[u][i].0 == v && g[u][i].1 == c;
      assert IsTarget(g, u, v);
    }
  }
}

lemma OtherFacts(graph: CapacityGraph, C: seq<seq<int>>, f: FlowMap, s: int, t: int)
  requires well_formed(graph) && CapOK(graph.adj, C) && is_valid_flow(graph.adj, f, s, t)
  ensures forall u, v :: 0 <= u < |graph.adj| && 0 <= v < |graph.adj| ==> 0 <= FF(f)(u, v) <= At(C, u, v)
  ensures forall u :: 0 <= u < |graph.adj| ==> total_flow_out(graph.adj, f, u) == Row2(FF(f), u, |graph.adj|)
  ensures forall u :: total_flow_in(graph.adj, f, u) == Col2(FF(f), u, |graph.adj|)
{
  forall u, v | 0 <= u < |graph.adj| && 0 <= v < |graph.adj|
    ensures 0 <= FF(f)(u, v) <= At(C, u, v)
  {
    GetFlowBounds(graph.adj, C, f, s, t, u, v);
  }
  forall u | 0 <= u < |graph.adj|
    ensures total_flow_out(graph.adj, f, u) == Row2(FF(f), u, |graph.adj|)
  {
    forall v | 0 <= v < |graph.adj| && !IsTarget(graph.adj, u, v)
      ensures get_flow(f, u, v) == 0
    {
      GetFlowBounds(graph.adj, C, f, s, t, u, v);
    }
    TotalOut(graph, f, u);
  }
  forall u ensures total_flow_in(graph.adj, f, u) == Col2(FF(f), u, |graph.adj|) {
    InSum(graph.adj, f, u, |graph.adj|);
  }
}

lemma OtherBound(graph: CapacityGraph, C: seq<seq<int>>, vis: seq<bool>, f: FlowMap, s: int, t: int)
  requires well_formed(graph) && CapOK(graph.adj, C)
  requires 0 <= s < |graph.adj| && 0 <= t < |graph.adj| && s != t
  requires |vis| == |graph.adj| && vis[s] && !vis[t]
  requires is_valid_flow(graph.adj, f, s, t)
  ensures flow_val(graph.adj, f, s) <= SumR(KK(C, vis), |graph.adj|, |graph.adj|)
{
  var n := |graph.adj|;
  OtherFacts(graph, C, f, s, t);
  forall u | 0 <= u < n && u != s && u != t ensures Net(FF(f), u, n) == 0 {
    assert total_flow_in(graph.adj, f, u) == total_flow_out(graph.adj, f, u);
  }
  CutLemma(FF(f), vis, n, s, t);
  forall u, v | 0 <= u < n && 0 <= v < n ensures TT(FF(f), vis)(u, v) <= KK(C, vis)(u, v) {
    assert 0 <= FF(f)(u, v) <= At(C, u, v);
  }
  SumRMono(TT(FF(f), vis), KK(C, vis), n, n);
}

// ================= Our flow as a FlowMap =================

ghost function MB(F: seq<seq<int>>, n: int, u: int, v: int): FlowMap
  requires Square(F, n) && 0 <= u <= n && 0 <= v <= n && (u < n || v == 0)
  decreases u, v
{
  if v > 0 then MB(F, n, u, v - 1)[(u, v - 1) := F[u][v - 1]]
  else if u > 0 then MB(F, n, u - 1, n)
  else map[]
}

lemma MBProps(F: seq<seq<int>>, n: int, u: int, v: int)
  requires Square(F, n) && 0 <= u <= n && 0 <= v <= n && (u < n || v == 0)
  ensures forall a, b :: (a, b) in MB(F, n, u, v) <==> ((0 <= a < u && 0 <= b < n) || (a == u && 0 <= b < v))
  ensures forall a, b :: 0 <= a < n && 0 <= b < n && (a, b) in MB(F, n, u, v) ==> MB(F, n, u, v)[(a, b)] == F[a][b]
  decreases u, v
{
  if v > 0 {
    MBProps(F, n, u, v - 1);
  } else if u > 0 {
    MBProps(F, n, u - 1, n);
  }
}

lemma OurFlow(graph: CapacityGraph, C: seq<seq<int>>, F: seq<seq<int>>, s: int, t: int) returns (fm: FlowMap)
  requires well_formed(graph) && CapOK(graph.adj, C) && Square(F, |graph.adj|)
  requires 0 <= s < |graph.adj| && 0 <= t < |graph.adj|
  requires forall a, b :: 0 <= a < |graph.adj| && 0 <= b < |graph.adj| ==> 0 <= F[a][b] <= C[a][b]
  requires forall u :: 0 <= u < |graph.adj| && u != s && u != t ==> Net(MF(F), u, |graph.adj|) == 0
  ensures is_valid_flow(graph.adj, fm, s, t)
  ensures flow_val(graph.adj, fm, s) == Net(MF(F), s, |graph.adj|)
{
  var n := |graph.adj|;
  fm := MB(F, n, n, 0);
  MBProps(F, n, n, 0);
  forall a, b ensures get_flow(fm, a, b) == MF(F)(a, b) {
    if 0 <= a < n && 0 <= b < n {
      assert (a, b) in fm;
    } else {
      assert (a, b) !in fm;
    }
  }
  forall a, b | (a, b) in fm
    ensures fm[(a, b)] > 0 ==> exists c :: has_capacity(graph.adj, a, b, c) && fm[(a, b)] <= c
  {
    if fm[(a, b)] > 0 {
      assert CapEntry(graph.adj, a, b, C[a][b]);
      assert has_capacity(graph.adj, a, b, C[a][b]) && fm[(a, b)] <= C[a][b];
    }
  }
  assert respects_capacity(graph.adj, fm);
  assert forall a, b :: (a, b) in fm ==> fm[(a, b)] >= 0;
  forall u | 0 <= u < n
    ensures total_flow_out(graph.adj, fm, u) == Row2(MF(F), u, n)
         && total_flow_in(graph.adj, fm, u) == Col2(MF(F), u, n)
  {
    forall v | 0 <= v < n && !IsTarget(graph.adj, u, v) ensures get_flow(fm, u, v) == 0 {
      assert CapEntry(graph.adj, u, v, C[u][v]);
      if C[u][v] > 0 {
        var i :| 0 <= u < |graph.adj| && 0 <= i < |graph.adj[u]| && graph.adj[u][i].0 == v && graph.adj[u][i].1 == C[u][v];
        assert IsTarget(graph.adj, u, v);
      }
    }
    TotalOut(graph, fm, u);
    InSum(graph.adj, fm, u, n);
    Row2Ext(FF(fm), MF(F), u, n);
    Col2Ext(FF(fm), MF(F), u, n);
  }
  forall u | 0 <= u < n && u != s && u != t
    ensures total_flow_in(graph.adj, fm, u) == total_flow_out(graph.adj, fm, u)
  {
    assert total_flow_out(graph.adj, fm, u) == Row2(MF(F), u, n);
    assert total_flow_in(graph.adj, fm, u) == Col2(MF(F), u, n);
    assert Net(MF(F), u, n) == 0;
  }
  assert is_conserved(graph.adj, fm, s, t);
}

lemma OurBound(C: seq<seq<int>>, F: seq<seq<int>>, vis: seq<bool>, n: int, s: int, t: int)
  requires Square(C, n) && Square(F, n) && |vis| == n
  requires 0 <= s < n && 0 <= t < n && s != t && vis[s] && !vis[t]
  requires forall a, b :: 0 <= a < n && 0 <= b < n ==> 0 <= F[a][b] <= C[a][b]
  requires forall u :: 0 <= u < n && u != s && u != t ==> Net(MF(F), u, n) == 0
  requires forall a, b :: 0 <= a < n && 0 <= b < n && vis[a] && Res(C, F, a, b) ==> vis[b]
  ensures Net(MF(F), s, n) == SumR(KK(C, vis), n, n)
{
  CutLemma(MF(F), vis, n, s, t);
  forall u, v | 0 <= u < n && 0 <= v < n ensures TT(MF(F), vis)(u, v) == KK(C, vis)(u, v) {
    assert InVis(vis, u) == vis[u] && InVis(vis, v) == vis[v];
    assert At(F, u, v) == F[u][v] && At(C, u, v) == C[u][v];
    assert MF(F)(u, v) == F[u][v];
    assert 0 <= F[u][v] <= C[u][v];
    assert 0 <= F[v][u] <= C[v][u];
    assert TT(MF(F), vis)(u, v) == (if vis[u] then F[u][v] else 0) - (if vis[v] then F[u][v] else 0);
    assert KK(C, vis)(u, v) == (if vis[u] && !vis[v] then C[u][v] else 0);
    if vis[u] && !vis[v] {
      assert !Res(C, F, u, v);
      assert F[u][v] == C[u][v];
    } else if vis[v] && !vis[u] {
      assert !Res(C, F, v, u);
      assert F[u][v] == 0;
    }
  }
  SumRMono(TT(MF(F), vis), KK(C, vis), n, n);
  SumRMono(KK(C, vis), TT(MF(F), vis), n, n);
}

lemma Final(graph: CapacityGraph, C: seq<seq<int>>, F: seq<seq<int>>, vis: seq<bool>, s: int, t: int, val: int)
  requires well_formed(graph)
  requires CapOK(graph.adj, C)
  requires Square(C, |graph.adj|)
  requires Square(F, |graph.adj|)
  requires 0 <= s < |graph.adj| && 0 <= t < |graph.adj| && s != t
  requires |vis| == |graph.adj| && vis[s] && !vis[t]
  requires forall a, b :: 0 <= a < |graph.adj| && 0 <= b < |graph.adj| ==> 0 <= F[a][b] <= C[a][b]
  requires forall u :: 0 <= u < |graph.adj| && u != s && u != t ==> Net(MF(F), u, |graph.adj|) == 0
  requires val == Net(MF(F), s, |graph.adj|)
  requires forall a, b :: 0 <= a < |graph.adj| && 0 <= b < |graph.adj| && vis[a] && Res(C, F, a, b) ==> vis[b]
  ensures exists f: FlowMap :: is_max_flow(view(graph), f, s, t) && flow_val(view(graph), f, s) == val
{
  var n := |graph.adj|;
  var fm := OurFlow(graph, C, F, s, t);
  OurBound(C, F, vis, n, s, t);
  forall other: FlowMap | is_valid_flow(graph.adj, other, s, t)
    ensures flow_val(graph.adj, fm, s) >= flow_val(graph.adj, other, s)
  {
    OtherBound(graph, C, vis, other, s, t);
  }
  assert is_max_flow(graph.adj, fm, s, t);
  assert view(graph) == graph.adj;
  assert is_max_flow(view(graph), fm, s, t) && flow_val(view(graph), fm, s) == val;
}

// ================= Algorithm helpers =================

lemma UpdNet(F: seq<seq<int>>, a: int, b: int, x: int, n: int)
  requires Square(F, n) && 0 <= a < n && 0 <= b < n
  ensures forall u :: Net(MF(F[a := F[a][b := x]]), u, n)
                      == Net(MF(F), u, n) + (if u == a then x - F[a][b] else 0) - (if u == b then x - F[a][b] else 0)
{
  var Fn := F[a := F[a][b := x]];
  var d := x - F[a][b];
  forall i, j ensures MF(Fn)(i, j) == MF(F)(i, j) + (if i == a && j == b then d else 0) {
    if 0 <= i < n && 0 <= j < n {
      if i != a { assert Fn[i] == F[i]; }
    }
  }
  forall u ensures Net(MF(Fn), u, n) == Net(MF(F), u, n) + (if u == a then d else 0) - (if u == b then d else 0) {
    Row2Upd(MF(F), MF(Fn), a, b, d, u, n);
    Col2Upd(MF(F), MF(Fn), a, b, d, u, n);
  }
}

lemma Bound(C: seq<seq<int>>, F: seq<seq<int>>, n: int, s: int)
  requires Square(C, n) && Square(F, n) && 0 <= s < n
  requires forall a, b :: 0 <= a < n && 0 <= b < n ==> 0 <= F[a][b] <= C[a][b]
  ensures Net(MF(F), s, n) <= Row2(MF(C), s, n)
{
  Row2Mono(MF(F), MF(C), s, n);
  Col2NonNeg(MF(F), s, n);
}

method BuildRow(graph: CapacityGraph, u: int) returns (row: seq<int>)
  requires well_formed(graph)
  requires capacities_bounded(graph.adj)
  requires 0 <= u < |graph.adj|
  ensures |row| == |graph.adj|
  ensures forall j :: 0 <= j < |graph.adj| ==> CapEntry(graph.adj, u, j, row[j])
{
  var n := |graph.adj|;
  row := seq(n, j => 0);
  var k := 0;
  while k < |graph.adj[u]|
    invariant 0 <= k <= |graph.adj[u]|
    invariant |row| == n
    invariant forall i :: 0 <= i < k ==> row[graph.adj[u][i].0] == graph.adj[u][i].1
    invariant forall j :: 0 <= j < n && (forall i :: 0 <= i < k ==> graph.adj[u][i].0 != j) ==> row[j] == 0
  {
    row := row[graph.adj[u][k].0 := graph.adj[u][k].1];
    k := k + 1;
  }
  forall j | 0 <= j < n ensures CapEntry(graph.adj, u, j, row[j]) {
    if exists i :: 0 <= i < |graph.adj[u]| && graph.adj[u][i].0 == j {
      var i :| 0 <= i < |graph.adj[u]| && graph.adj[u][i].0 == j;
      assert row[j] == graph.adj[u][i].1;
      assert has_capacity(graph.adj, u, j, graph.adj[u][i].1);
      forall c2 | has_capacity(graph.adj, u, j, c2) ensures c2 == row[j] {
        var i2 :| 0 <= u < |graph.adj| && 0 <= i2 < |graph.adj[u]| && graph.adj[u][i2].0 == j && graph.adj[u][i2].1 == c2;
        assert i2 == i;
      }
    } else {
      assert row[j] == 0;
      forall c2 | has_capacity(graph.adj, u, j, c2) ensures c2 == row[j] {
        var i2 :| 0 <= u < |graph.adj| && 0 <= i2 < |graph.adj[u]| && graph.adj[u][i2].0 == j && graph.adj[u][i2].1 == c2;
        assert false;
      }
    }
  }
}

method BuildCap(graph: CapacityGraph) returns (C: seq<seq<int>>)
  requires well_formed(graph)
  requires capacities_bounded(graph.adj)
  ensures CapOK(graph.adj, C)
{
  var n := |graph.adj|;
  C := [];
  var u := 0;
  while u < n
    invariant 0 <= u <= n
    invariant |C| == u
    invariant forall i :: 0 <= i < u ==> |C[i]| == n
    invariant forall i, j :: 0 <= i < u && 0 <= j < n ==> CapEntry(graph.adj, i, j, C[i][j])
  {
    var row := BuildRow(graph, u);
    C := C + [row];
    u := u + 1;
  }
}

method FindEdge(C: seq<seq<int>>, F: seq<seq<int>>, n: int, vis: seq<bool>) returns (found: bool, u: int, v: int)
  requires Square(C, n) && Square(F, n) && |vis| == n
  ensures found ==> 0 <= u < n && 0 <= v < n && vis[u] && !vis[v] && Res(C, F, u, v)
  ensures !found ==> forall a, b :: 0 <= a < n && 0 <= b < n && vis[a] && Res(C, F, a, b) ==> vis[b]
{
  found, u, v := false, 0, 0;
  var a := 0;
  while a < n
    invariant 0 <= a <= n
    invariant !found
    invariant forall x, y :: 0 <= x < a && 0 <= y < n && vis[x] && Res(C, F, x, y) ==> vis[y]
  {
    if vis[a] {
      var b := 0;
      while b < n
        invariant 0 <= b <= n
        invariant forall y :: 0 <= y < b && Res(C, F, a, y) ==> vis[y]
      {
        if !vis[b] && Res(C, F, a, b) {
          return true, a, b;
        }
        b := b + 1;
      }
    }
    a := a + 1;
  }
}

method Reach(C: seq<seq<int>>, F: seq<seq<int>>, n: int, s: int) returns (vis: seq<bool>, par: seq<int>, ord: seq<int>)
  requires Square(C, n) && Square(F, n) && 0 <= s < n
  ensures |vis| == n && |par| == n && |ord| == n
  ensures vis[s]
  ensures forall v :: 0 <= v < n ==> ord[v] >= 0
  ensures forall v :: 0 <= v < n && vis[v] && v != s ==>
            0 <= par[v] < n && vis[par[v]] && ord[par[v]] < ord[v] && Res(C, F, par[v], v)
  ensures forall a, b :: 0 <= a < n && 0 <= b < n && vis[a] && Res(C, F, a, b) ==> vis[b]
{
  vis := seq(n, i => i == s);
  par := seq(n, i => 0);
  ord := seq(n, i => 0);
  var cnt := 1;
  while true
    invariant |vis| == n && |par| == n && |ord| == n
    invariant vis[s]
    invariant forall w :: 0 <= w < n ==> 0 <= ord[w] < cnt
    invariant forall w :: 0 <= w < n && vis[w] && w != s ==>
                0 <= par[w] < n && vis[par[w]] && ord[par[w]] < ord[w] && Res(C, F, par[w], w)
    decreases set w | 0 <= w < n && !vis[w]
  {
    var found, u, v := FindEdge(C, F, n, vis);
    if !found { return; }
    ghost var U0 := set w | 0 <= w < n && !vis[w];
    vis := vis[v := true];
    par := par[v := u];
    ord := ord[v := cnt];
    cnt := cnt + 1;
    assert v in U0;
    assert v !in (set w | 0 <= w < n && !vis[w]);
    assert (set w | 0 <= w < n && !vis[w]) < U0;
  }
}

