method max_flow_value(graph: CapacityGraph, s: int, t: int) returns (max_val: int)
    requires well_formed(graph)
    requires capacities_bounded(view(graph))
    requires 0 <= s < size(graph)
    requires 0 <= t < size(graph)
    requires s != t
    ensures exists f: FlowMap :: 
            is_max_flow(view(graph), f, s, t) 
            && flow_val(view(graph), f, s) == max_val
{
  var n := |graph.adj|;
  var C := BuildCap(graph);
  assert Square(C, n);
  var F: seq<seq<int>> := seq(n, i => seq(n, j => 0));
  assert forall i, j :: 0 <= i < n && 0 <= j < n ==> F[i][j] == 0;
  var val := 0;
  forall u | 0 <= u < n ensures Net(MF(F), u, n) == 0 {
    Row2Zero(MF(F), u, n);
    Col2Zero(MF(F), u, n);
  }
  Bound(C, F, n, s);
  while true
    invariant Square(C, n) && CapOK(graph.adj, C)
    invariant Square(F, n)
    invariant forall a, b :: 0 <= a < n && 0 <= b < n ==> 0 <= F[a][b] <= C[a][b]
    invariant forall u :: 0 <= u < n && u != s && u != t ==> Net(MF(F), u, n) == 0
    invariant val == Net(MF(F), s, n)
    invariant val <= Row2(MF(C), s, n)
    decreases Row2(MF(C), s, n) - val
  {
    ghost var F0 := F;
    var vis, par, ord := Reach(C, F, n, s);
    if !vis[t] {
      Final(graph, C, F, vis, s, t, val);
      return val;
    }
    var cur := t;
    while cur != s
      invariant 0 <= cur < n && vis[cur]
      invariant Square(F, n) && Square(F0, n)
      invariant forall a, b :: 0 <= a < n && 0 <= b < n ==> 0 <= F[a][b] <= C[a][b]
      invariant forall a, b :: 0 <= a < n && 0 <= b < n && ord[a] <= ord[cur] && ord[b] <= ord[cur] ==> F[a][b] == F0[a][b]
      invariant forall u :: 0 <= u < n ==>
                  Net(MF(F), u, n) == Net(MF(F0), u, n) + (if u == cur then 1 else 0) - (if u == t then 1 else 0)
      invariant forall w :: 0 <= w < n ==> ord[w] >= 0
      invariant forall w :: 0 <= w < n && vis[w] && w != s ==>
                  0 <= par[w] < n && vis[par[w]] && ord[par[w]] < ord[w] && Res(C, F0, par[w], w)
      decreases ord[cur]
    {
      var p := par[cur];
      assert F[p][cur] == F0[p][cur] && F[cur][p] == F0[cur][p];
      ghost var Fold := F;
      if F[cur][p] > 0 {
        var x := F[cur][p] - 1;
        F := F[cur := F[cur][p := x]];
        UpdNet(Fold, cur, p, x, n);
      } else {
        var x := F[p][cur] + 1;
        F := F[p := F[p][cur := x]];
        UpdNet(Fold, p, cur, x, n);
      }
      cur := p;
    }
    val := val + 1;
    Bound(C, F, n, s);
  }
}
