predicate path_to(path: seq<int>, nums: seq<int>, t: int) {
    |path| >= 1 &&
    path[0] == 0 &&
    path[|path|-1] == t &&
    (forall i: int :: 0 <= i < |path| ==> 0 <= path[i] < |nums|) &&
    (forall i: int :: 0 <= i < |path| - 1 ==>
        path[i+1] > path[i] &&
        path[i+1] <= path[i] + nums[path[i]])
}

lemma Extend(p: seq<int>, nums: seq<int>, i: int, j: int)
    requires path_to(p, nums, i)
    requires 0 <= i < j < |nums|
    requires j <= i + nums[i]
    ensures path_to(p + [j], nums, j)
{
    var q := p + [j];
    assert forall k :: 0 <= k < |p| ==> q[k] == p[k];
    assert q[|q|-1] == j;
    assert q[|p|-1] == i;
    forall k | 0 <= k < |q| - 1
        ensures q[k+1] > q[k] && q[k+1] <= q[k] + nums[q[k]]
    {
        if k < |p| - 1 {
            assert q[k] == p[k];
            assert q[k+1] == p[k+1];
        } else {
            assert k == |p| - 1;
            assert q[k] == i;
            assert q[k+1] == j;
        }
    }
    forall k | 0 <= k < |q|
        ensures 0 <= q[k] < |nums|
    {
        if k < |p| {
            assert q[k] == p[k];
        }
    }
}

lemma Bounded(path: seq<int>, nums: seq<int>, m: int, i: int, k: int)
    requires is_valid_jump_path(path, nums)
    requires 0 <= m < i
    requires i <= |nums|
    requires forall t :: 0 <= t < i ==> t + nums[t] <= m
    requires 0 <= k < |path|
    ensures path[k] <= m
    decreases k
{
    if k > 0 {
        Bounded(path, nums, m, i, k - 1);
        assert 0 <= k - 1 < |path| - 1;
        assert path[k] <= path[k-1] + nums[path[k-1]];
        assert 0 <= path[k-1] < i;
        assert path[k-1] + nums[path[k-1]] <= m;
    }
}

lemma NoPath(nums: seq<int>, m: int, i: int)
    requires 0 <= m < i < |nums|
    requires forall t :: 0 <= t < i ==> t + nums[t] <= m
    ensures !(exists path: seq<int> :: is_valid_jump_path(path, nums))
{
    forall path: seq<int> | is_valid_jump_path(path, nums)
        ensures false
    {
        Bounded(path, nums, m, i, |path| - 1);
    }
}

method can_jump(nums: seq<int>) returns (reachable: bool)
    requires |nums| > 0
    requires |nums| <= 10000
    // From u64 constraint
    requires forall i: int :: 0 <= i < |nums| ==> nums[i] >= 0
    requires forall i: int :: 0 <= i < |nums| ==> nums[i] <= 10000
    ensures
        // reachable <==> exists path
        reachable <==> exists path: seq<int> :: is_valid_jump_path(path, nums)
{
    var n := |nums|;
    var maxReach := 0;
    var i := 0;
    ghost var paths: seq<seq<int>> := [[0]];
    while i < n
        invariant 0 <= i <= n
        invariant 0 <= maxReach
        invariant i <= maxReach + 1
        invariant forall k :: 0 <= k < i ==> k + nums[k] <= maxReach
        invariant |paths| == (if maxReach < n then maxReach + 1 else n)
        invariant forall j :: 0 <= j < |paths| ==> path_to(paths[j], nums, j)
    {
        if i > maxReach {
            NoPath(nums, maxReach, i);
            reachable := false;
            return;
        }
        var newReach := if i + nums[i] > maxReach then i + nums[i] else maxReach;
        ghost var oldLen := |paths|;
        ghost var target := if newReach < n then newReach + 1 else n;
        assert i < |paths|;
        ghost var p := paths[i];
        assert path_to(p, nums, i);
        while |paths| < target
            invariant oldLen <= |paths| <= target
            invariant forall j :: 0 <= j < |paths| ==> path_to(paths[j], nums, j)
            decreases target - |paths|
        {
            var j := |paths|;
            assert j < n;
            assert j > i;
            assert newReach == i + nums[i];
            Extend(p, nums, i, j);
            paths := paths + [p + [j]];
        }
        maxReach := newReach;
        i := i + 1;
    }
    assert maxReach >= n - 1;
    assert |paths| == n;
    assert path_to(paths[n-1], nums, n-1);
    assert is_valid_jump_path(paths[n-1], nums);
    reachable := true;
}

