predicate cj_valid_path_to(path: seq<int>, target: int, nums: seq<int>) {
    |path| >= 1 &&
    path[0] == 0 &&
    path[|path| - 1] == target &&
    (forall i: int :: 0 <= i < |path| ==> 0 <= path[i] < |nums|) &&
    (forall i: int :: 0 <= i < |path| - 1 ==>
        path[i + 1] > path[i] &&
        path[i + 1] <= path[i] + nums[path[i]])
}

lemma cj_extend_path(
    path: seq<int>,
    target: int,
    next: int,
    nums: seq<int>)
    requires cj_valid_path_to(path, target, nums)
    requires 0 <= next < |nums|
    requires target < next
    requires next <= target + nums[target]
    ensures cj_valid_path_to(path + [next], next, nums)
{
    var extended := path + [next];

    assert |path| >= 1;
    assert path[|path| - 1] == target;
    assert 0 <= path[|path| - 1] < |nums|;
    assert 0 <= target < |nums|;

    assert extended[0] == path[0];
    assert extended[|extended| - 1] == next;

