method can_jump(nums: seq<int>) returns (reachable: bool)
    requires |nums| > 0
    requires |nums| <= 10000
    // From u64 constraint
    requires forall i: int :: 0 <= i < |nums| ==> nums[i] >= 0
    requires forall i: int :: 0 <= i < |nums| ==> nums[i] <= 10000
    ensures
        // reachable <==> exists path
        reachable <==> exists path: seq<int> :: is_valid_jump_path(path, nums)
{
    var max_reach: int := 0;
    ghost var paths: seq<seq<int>> := [[0]];
    LemmaBasePath(nums);

    var i: int := 0;
    while i <= max_reach && max_reach < |nums| - 1
        invariant 0 <= i <= max_reach + 1
        invariant 0 <= max_reach < |nums|
        invariant |paths| == max_reach + 1
        invariant forall j: int :: 0 <= j <= max_reach ==> is_path_to(paths[j], nums, j)
        invariant max_reach < |nums| - 1 ==> (forall k: int :: 0 <= k < i ==> k + nums[k] <= max_reach)
        decreases |nums| - i
    {
        var reach: int := i + nums[i];
        if reach > max_reach {
            var new_max: int := if reach < |nums| - 1 then reach else |nums| - 1;
            ghost var p_i: seq<int> := paths[i];
            assert is_path_to(p_i, nums, i);
            while max_reach < new_max
                invariant 0 <= i <= max_reach <= new_max < |nums|
                invariant new_max <= i + nums[i]
                invariant is_path_to(p_i, nums, i)
                invariant |paths| == max_reach + 1
                invariant forall j: int :: 0 <= j <= max_reach ==> is_path_to(paths[j], nums, j)
                invariant forall k: int :: 0 <= k < i ==> k + nums[k] <= max_reach
                decreases new_max - max_reach
            {
                var next_j: int := max_reach + 1;
                ghost var old_paths := paths;
                LemmaExtendPath(p_i, nums, i, next_j);
                paths := paths + [p_i + [next_j]];
                max_reach := next_j;
                forall j: int | 0 <= j <= max_reach
                    ensures is_path_to(paths[j], nums, j)
                {
                    if j < max_reach {
                        assert paths[j] == old_paths[j];
                    } else {
                        assert j == next_j;
                        assert paths[j] == p_i + [next_j];
                    }
                }
            }
        }
        i := i + 1;
    }

    if max_reach == |nums| - 1 {
        LemmaPathToTargetIsValid(paths[|nums| - 1], nums);
        reachable := true;
    } else {
        assert i == max_reach + 1;
        LemmaNoValidPath(nums, max_reach);
        reachable := false;
    }
