function VGet(x: seq<int>, n: int, u: int, v: int): int
{
    if n > 0
       && 0 <= u < n
       && 0 <= v < n
       && u * n + v < |x|
    then x[u * n + v]
    else 0
}

predicate VEdgeOK(
    g: seq<seq<(int, int)>>,
    u: int,
    v: int,
