lemma {:isolate_assertions} ExtractValid(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int
)
    requires |g| > 0
    requires well_formed(CapacityGraph(g))
    requires capacities_bounded(g)
    requires is_valid_flow(g, f, s, t)
    requires 0 <= s < |g|
    ensures VValid(g, ExtractVector(g, f), s, t)
    ensures VFlowValue(g, ExtractVector(g, f), s)
        == flow_val(g, f, s)
{
    ghost var x := ExtractVector(g, f);

    forall k: int | 0 <= k < |x|
        ensures 0 <= x[k] <= 100000
    {
        var u := k / |g|;
        var v := k % |g|;

        assert 0 <= u < |g|;
        assert 0 <= v < |g|;
        assert x[k] == get_flow(f, u, v);

        if (u, v) in f {
            assert f[(u, v)] >= 0;
            if f[(u, v)] > 0 {
                var c: int :|
                    has_capacity(g, u, v, c)
                    && f[(u, v)] <= c;
                assert 0 <= c <= 100000;
            }
        } else {
            assert get_flow(f, u, v) == 0;
        }
    }

    assert VRange(x, 100000);

    forall u: int, v: int
        | 0 <= u < |g| && 0 <= v < |g|
        ensures VEdgeOK(g, u, v, VGet(x, |g|, u, v))
    {
        ExtractGet(g, f, u, v);

        if get_flow(f, u, v) > 0 {
            assert (u, v) in f;
            var c: int :|
                has_capacity(g, u, v, c)
                && f[(u, v)] <= c;
            var i: int :|
                0 <= u < |g|
                && 0 <= i < |g[u]|
                && g[u][i].0 == v
                && g[u][i].1 == c;
            assert VEdgeOK(g, u, v, VGet(x, |g|, u, v));
        } else {
            if (u, v) in f {
                assert f[(u, v)] >= 0;
            } else {
                assert get_flow(f, u, v) == 0;
            }
            assert get_flow(f, u, v) >= 0;
            assert get_flow(f, u, v) == 0;
        }
    }

    forall u: int |
        0 <= u < |g| && u != s && u != t
        ensures VTotalIn(g, x, u)
            == VTotalOut(g, x, u)
    {
        ExtractInSame(g, f, u, |g|);
        ExtractOutSame(g, f, u, |g[u]|);
        assert total_flow_in(g, f, u)
            == total_flow_out(g, f, u);
    }

    assert VValid(g, x, s, t);

    ExtractInSame(g, f, s, |g|);
    ExtractOutSame(g, f, s, |g[s]|);
}

