method {:isolate_assertions} max_flow_value(
    graph: CapacityGraph,
    s: int,
    t: int
) returns (max_val: int)
    requires well_formed(graph)
    requires capacities_bounded(view(graph))
    requires 0 <= s < size(graph)
    requires 0 <= t < size(graph)
    requires s != t
    ensures exists f: FlowMap ::
            is_max_flow(view(graph), f, s, t)
            && flow_val(view(graph), f, s) == max_val
{
    var result := EnumerateFlows(graph.adj, s, t, []);

    EnumerateFlowsCorrect(graph.adj, s, t, []);

    ghost var zero :=
        seq(|graph.adj| * |graph.adj|, k => 0);

    ZeroVectorValid(graph.adj, s, t);

    assert VExtends([], zero);
    assert result.0 >= VFlowValue(graph.adj, zero, s);
    assert result.0 >= 0;
    assert VValid(graph.adj, result.1, s, t);
    assert result.0 == VFlowValue(graph.adj, result.1, s);

    ghost var maximal :=
        VectorMap(result.1, |graph.adj|);

    VectorFlowValid(graph.adj, result.1, s, t);

    forall other: FlowMap
        | is_valid_flow(graph.adj, other, s, t)
        ensures flow_val(graph.adj, maximal, s)
            >= flow_val(graph.adj, other, s)
    {
        ExtractValid(graph.adj, other, s, t);

        ghost var extracted :=
            ExtractVector(graph.adj, other);

        assert |extracted| == |graph.adj| * |graph.adj|;
        assert VRange(extracted, 100000);
        assert VExtends([], extracted);

        assert result.0
            >= VFlowValue(graph.adj, extracted, s);
        assert VFlowValue(graph.adj, extracted, s)
            == flow_val(graph.adj, other, s);
        assert flow_val(graph.adj, maximal, s)
            == result.0;
    }

    assert forall other: FlowMap
        {:trigger is_valid_flow(graph.adj, other, s, t)} ::
        is_valid_flow(graph.adj, other, s, t)
        ==> flow_val(graph.adj, maximal, s)
            >= flow_val(graph.adj, other, s);

    assert is_max_flow(graph.adj, maximal, s, t);

    max_val := result.0;

    assert graph.adj == view(graph);
    assert flow_val(view(graph), maximal, s) == max_val;
    assert is_max_flow(view(graph), maximal, s, t);
}

