method quick_select(v: seq<int>, k: int) returns (v_new: seq<int>, res: int)
    requires 0 <= k < |v|
    ensures is_permutation(v, v_new)
    ensures is_kth_smallest(v, k, res)
{
    var n := |v|;
    assert 0 < n;

    var a := v;
    var p := seq(n, x => x);

    IdentityIsValidPermutation(n);

    var i := 1;
    while i < n
        invariant 1 <= i <= n
        invariant |a| == n
        invariant |p| == n
        invariant is_valid_index_permutation(p, n)
        invariant forall x {:trigger p[x]} ::
            0 <= x < n ==> a[x] == v[p[x]]
        invariant SegmentSorted(a, 0, i)
        decreases n - i
    {
        var j := i;

        while j > 0 && a[j] < a[j - 1]
            invariant 0 <= j <= i < n
            invariant |a| == n
            invariant |p| == n
            invariant is_valid_index_permutation(p, n)
            invariant forall x {:trigger p[x]} ::
                0 <= x < n ==> a[x] == v[p[x]]
            invariant SegmentSorted(a, 0, j)
            invariant SegmentSorted(a, j, i + 1)
            invariant AcrossHole(a, j, i + 1)
            decreases j
        {
            var oldA := a;
            var oldP := p;

            InsertionSwapPreservesStructure(oldA, j, i + 1);
            SwapPreservesValidPermutation(oldP, n, j - 1, j);

            a := Swap(oldA, j - 1, j);
            p := Swap(oldP, j - 1, j);

            forall x | 0 <= x < n
                ensures a[x] == v[p[x]]
            {
                TransposeIndexProperties(x, x, j - 1, j, n);
                SwapAt(oldA, j - 1, j, x);
                SwapAt(oldP, j - 1, j, x);
                assert
                    oldA[TransposeIndex(x, j - 1, j)]
                    ==
                    v[oldP[TransposeIndex(x, j - 1, j)]];
            }

            j := j - 1;
        }

        if j > 0 {
            assert !(a[j] < a[j - 1]);
            assert a[j - 1] <= a[j];
        }

        CombineInsertionSegments(a, j, i + 1);
        i := i + 1;
    }

    assert SegmentSorted(a, 0, n);
    assert is_sorted(a);

    v_new := a;
    res := a[k];

    assert exists q: seq<int> ::
        is_valid_index_permutation(q, |v|)
        && |v| == |v_new|
        && (forall x {:trigger q[x]} ::
            0 <= x < |v| ==> v_new[x] == v[q[x]]) by
    {
        witness p;
    }

    assert is_permutation(v, v_new);

    assert exists sorted_s: seq<int> ::
        is_permutation(v, sorted_s)
        && is_sorted(sorted_s)
        && 0 <= k < |v|
        && sorted_s[k] == res by
    {
