method kmp_search(haystack: seq<int>, needle: seq<int>) returns (indices: seq<int>)
    requires |haystack| < 1000000
    requires |needle| < 1000000
    ensures 
        // Type Constraint: Indices must be non-negative (simulating usize)
        forall k :: 0 <= k < |indices| ==> indices[k] >= 0
    ensures
        // Soundness: Every index returned is a valid match
        forall i :: 0 <= i < |indices| ==> 
            matches_at(haystack, needle, indices[i])
    ensures
        // Completeness: Every valid match in the haystack is found
        forall i :: matches_at(haystack, needle, i) ==> 
            exists k :: 0 <= k < |indices| && indices[k] == i
{
    indices := [];
    if |needle| > |haystack| {
        assert forall i :: !matches_at(haystack, needle, i);
        return;
    }
    var i := 0;
    while i <= |haystack| - |needle|
        invariant 0 <= i <= |haystack| - |needle| + 1
        invariant forall k :: 0 <= k < |indices| ==> indices[k] >= 0
        invariant forall k :: 0 <= k < |indices| ==> matches_at(haystack, needle, indices[k])
        invariant forall j :: 0 <= j < i && matches_at(haystack, needle, j) ==>
            exists k :: 0 <= k < |indices| && indices[k] == j
    {
        var m := check_at(haystack, needle, i);
        if m {
            ghost var old_ind := indices;
            indices := indices + [i];
            assert forall k :: 0 <= k < |old_ind| ==> indices[k] == old_ind[k];
            assert indices[|indices| - 1] == i;
            assert forall j :: 0 <= j < i && matches_at(haystack, needle, j) ==>
                exists k :: 0 <= k < |old_ind| && old_ind[k] == j;
        }
        i := i + 1;
    }
    assert forall j :: matches_at(haystack, needle, j) ==> 0 <= j < i;
}

