        swap_preserves_valid_state(v, v_new, p, i, min_idx);
        ghost var old_v_new := v_new;
        v_new := v_new[i := v_new[min_idx]][min_idx := v_new[i]];
        p := p[i := p[min_idx]][min_idx := p[i]];

        forall x, y | 0 <= x < y < i + 1
            ensures v_new[x] <= v_new[y]
        {
            if y < i {
                assert old_v_new[x] <= old_v_new[y];
            } else {
                assert y == i;
                assert v_new[x] == old_v_new[x];
                assert v_new[i] == old_v_new[min_idx];
                assert old_v_new[x] <= old_v_new[min_idx];
            }
        }

        forall x, y | 0 <= x < i + 1 <= y < n
            ensures v_new[x] <= v_new[y]
        {
            var orig_y := if y == min_idx then i else y;
            assert i <= orig_y < n;
            assert v_new[y] == old_v_new[orig_y];
            if x < i {
                assert v_new[x] == old_v_new[x];
                assert old_v_new[x] <= old_v_new[orig_y];
            } else {
                assert x == i;
                assert v_new[i] == old_v_new[min_idx];
                assert old_v_new[min_idx] <= old_v_new[orig_y];
            }
        }

        i := i + 1;
    }

    res := v_new[k];
    assert is_valid_index_permutation(p, |v|);
    assert is_permutation(v, v_new);
    assert is_sorted(v_new);
    assert is_kth_smallest(v, k, res);
}
