lemma AppendAllExists(haystack: seq<int>, needle: seq<int>, s: seq<int>, idx: int)
    requires forall i :: 0 <= i < idx && matches_at(haystack, needle, i) ==>
        exists k :: 0 <= k < |s| && s[k] == i
    ensures forall i :: 0 <= i <= idx && matches_at(haystack, needle, i) ==>
        exists k :: 0 <= k < |s + [idx]| && (s + [idx])[k] == i
{
    var s' := s + [idx];
    forall i | 0 <= i <= idx && matches_at(haystack, needle, i)
        ensures exists k :: 0 <= k < |s'| && s'[k] == i
    {
        if i < idx {
            var k :| 0 <= k < |s| && s[k] == i;
            assert 0 <= k < |s'| && s'[k] == i;
        } else {
            var k := |s|;
            assert 0 <= k < |s'| && s'[k] == i;
        }
    }
}

method is_match(haystack: seq<int>, needle: seq<int>, start_index: int) returns (b: bool)
    requires 0 <= start_index
    requires start_index + |needle| <= |haystack|
    ensures b <==> matches_at(haystack, needle, start_index)
{
    var i := 0;
    while i < |needle|
        invariant 0 <= i <= |needle|
        invariant forall j :: 0 <= j < i ==> haystack[start_index + j] == needle[j]
    {
        if haystack[start_index + i] != needle[i] {
            return false;
        }
        i := i + 1;
    }
    return true;
}

method kmp_search(haystack: seq<int>, needle: seq<int>) returns (indices: seq<int>)
    requires |haystack| < 1000000
    requires |needle| < 1000000
    ensures 
        // Type Constraint: Indices must be non-negative (simulating usize)
        forall k :: 0 <= k < |indices| ==> indices[k] >= 0
    ensures
        // Soundness: Every index returned is a valid match
        forall i :: 0 <= i < |indices| ==> 
            matches_at(haystack, needle, indices[i])
    ensures
        // Completeness: Every valid match in the haystack is found
        forall i :: matches_at(haystack, needle, i) ==> 
            exists k :: 0 <= k < |indices| && indices[k] == i
{
    indices := [];
    if |needle| > |haystack| {
        return;
    }
    var idx := 0;
    while idx <= |haystack| - |needle|
        invariant 0 <= idx <= |haystack| - |needle| + 1
        invariant forall k :: 0 <= k < |indices| ==> indices[k] >= 0
        invariant forall k :: 0 <= k < |indices| ==> matches_at(haystack, needle, indices[k])
        invariant forall i :: 0 <= i < idx && matches_at(haystack, needle, i) ==>
            exists k :: 0 <= k < |indices| && indices[k] == i
    {
        var matched := is_match(haystack, needle, idx);
        if matched {
            AppendAllExists(haystack, needle, indices, idx);
            indices := indices + [idx];
        }
        idx := idx + 1;
    }
}

