function max_int(a: int, b: int): int
{
    if a >= b then a else b
}

// Optimal value achievable using items w/v with remaining capacity c
function opt(w: seq<int>, v: seq<int>, c: int): int
    requires |w| == |v|
    decreases |w|
{
    if |w| == 0 then 0
    else if w[0] <= c then max_int(v[0] + opt(w[1..], v[1..], c - w[0]), opt(w[1..], v[1..], c))
    else opt(w[1..], v[1..], c)
}

lemma OptNonneg(w: seq<int>, v: seq<int>, c: int)
    requires |w| == |v|
    ensures opt(w, v, c) >= 0
    decreases |w|
{
    if |w| > 0 {
        OptNonneg(w[1..], v[1..], c);
    }
}

lemma WeightNonneg(sel: seq<bool>, w: seq<int>)
    requires |sel| <= |w|
    requires forall i :: 0 <= i < |w| ==> w[i] >= 0
    ensures total_weight(sel, w) >= 0
    decreases |sel|
{
    if |sel| > 0 {
        assert forall i :: 0 <= i < |w[1..]| ==> w[1..][i] >= 0;
        WeightNonneg(sel[1..], w[1..]);
    }
}

lemma UpperBound(sel: seq<bool>, w: seq<int>, v: seq<int>, c: int)
    requires |w| == |v|
    requires |sel| == |w|
    requires forall i :: 0 <= i < |w| ==> w[i] >= 0
    requires total_weight(sel, w) <= c
    ensures total_value(sel, v) <= opt(w, v, c)
    decreases |w|
{
    if |w| > 0 {
        assert forall i :: 0 <= i < |w[1..]| ==> w[1..][i] >= 0;
        WeightNonneg(sel[1..], w[1..]);
        if sel[0] {
            UpperBound(sel[1..], w[1..], v[1..], c - w[0]);
        } else {
            UpperBound(sel[1..], w[1..], v[1..], c);
        }
    }
}

lemma Witness(w: seq<int>, v: seq<int>, c: int) returns (sel: seq<bool>)
    requires |w| == |v|
    requires c >= 0
    ensures |sel| == |w|
    ensures total_weight(sel, w) <= c
    ensures total_value(sel, v) == opt(w, v, c)
    decreases |w|
{
    if |w| == 0 {
        sel := [];
    } else if w[0] <= c && v[0] + opt(w[1..], v[1..], c - w[0]) >= opt(w[1..], v[1..], c) {
        var r := Witness(w[1..], v[1..], c - w[0]);
        sel := [true] + r;
        assert sel[1..] == r;
    } else {
        var r := Witness(w[1..], v[1..], c);
        sel := [false] + r;
        assert sel[1..] == r;
    }
}

method solve_knapsack_01(weights: seq<int>, values: seq<int>, capacity: int) returns (max_val: int)
    requires |weights| == |values|
    requires |weights| <= 100 // Reasonable bound for recursion/verification time
    requires 0 <= capacity <= 1000 // Explicitly constrain non-negative capacity
    requires forall i :: 0 <= i < |weights| ==> 0 <= weights[i] <= 1000 // Explicitly constrain non-negative weights
    requires forall i :: 0 <= i < |values| ==> 0 <= values[i] <= 1000   // Explicitly constrain non-negative values
    ensures max_val >= 0
    ensures
        // 1. Upper Bound
        forall selected: seq<bool> :: 
            is_valid_strategy(selected, weights, capacity)
            ==> total_value(selected, values) <= max_val
    ensures
        // 2. Existence
        exists selected: seq<bool> :: 
            is_valid_strategy(selected, weights, capacity)
            && total_value(selected, values) == max_val
{
    var n := |weights|;
    var i := n;
    var row: seq<int> := seq(capacity + 1, _ => 0);
    while i > 0
        invariant 0 <= i <= n
        invariant |row| == capacity + 1
        invariant forall c :: 0 <= c <= capacity ==> row[c] == opt(weights[i..], values[i..], c)
        decreases i
    {
        var wi := weights[i-1];
        var vi := values[i-1];
        assert weights[i-1..][1..] == weights[i..];
        assert values[i-1..][1..] == values[i..];
        var newrow: seq<int> := [];
        var c := 0;
        while c <= capacity
            invariant 0 <= c <= capacity + 1
            invariant |newrow| == c
            invariant forall k :: 0 <= k < c ==> newrow[k] == opt(weights[i-1..], values[i-1..], k)
            decreases capacity + 1 - c
        {
            assert weights[i-1..][1..] == weights[i..];
            assert values[i-1..][1..] == values[i..];
            var x: int;
            if wi <= c {
                var a := vi + row[c - wi];
                var b := row[c];
                x := if a >= b then a else b;
            } else {
                x := row[c];
            }
            assert x == opt(weights[i-1..], values[i-1..], c);
            newrow := newrow + [x];
            c := c + 1;
        }
        row := newrow;
        i := i - 1;
    }
    assert weights[0..] == weights;
    assert values[0..] == values;
    max_val := row[capacity];
    assert max_val == opt(weights, values, capacity);

    OptNonneg(weights, values, capacity);

    forall selected: seq<bool> | is_valid_strategy(selected, weights, capacity)
        ensures total_value(selected, values) <= max_val
    {
        UpperBound(selected, weights, values, capacity);
    }

    var sel := Witness(weights, values, capacity);
    assert is_valid_strategy(sel, weights, capacity);
    assert total_value(sel, values) == max_val;
}

