method knapsack_recursive(weights: seq<int>, values: seq<int>, capacity: int)
    returns (best: int, chosen: seq<bool>)
    requires |weights| == |values|
    requires 0 <= capacity
    requires forall i :: 0 <= i < |weights| ==> 0 <= weights[i] <= 1000
    requires forall i :: 0 <= i < |values| ==> 0 <= values[i] <= 1000
    ensures best >= 0
    ensures is_valid_strategy(chosen, weights, capacity)
    ensures total_value(chosen, values) == best
    ensures forall selected: seq<bool> ::
        is_valid_strategy(selected, weights, capacity)
        ==> total_value(selected, values) <= best
    decreases |weights|
{
    if |weights| == 0 {
        best := 0;
        chosen := [];
    } else {
        assert |values| > 0;
        assert |weights[1..]| == |values[1..]|;

        forall i | 0 <= i < |weights[1..]|
            ensures 0 <= weights[1..][i] <= 1000
        {
            assert weights[1..][i] == weights[i + 1];
        }

        forall i | 0 <= i < |values[1..]|
            ensures 0 <= values[1..][i] <= 1000
        {
            assert values[1..][i] == values[i + 1];
        }

        var skipBest, skipChosen :=
            knapsack_recursive(weights[1..], values[1..], capacity);

        if weights[0] <= capacity {
            var takeBest, takeChosen :=
                knapsack_recursive(
                    weights[1..],
                    values[1..],
                    capacity - weights[0]
                );

            if values[0] + takeBest >= skipBest {
                best := values[0] + takeBest;
                chosen := [true] + takeChosen;

                assert |chosen| == |weights|;
                assert total_weight(chosen, weights)
                    == weights[0] + total_weight(takeChosen, weights[1..]);
                assert total_weight(chosen, weights) <= capacity;
                assert is_valid_strategy(chosen, weights, capacity);

                assert total_value(chosen, values)
                    == values[0] + total_value(takeChosen, values[1..]);
                assert total_value(chosen, values) == best;

                forall selected: seq<bool>
                    | is_valid_strategy(selected, weights, capacity)
                    ensures total_value(selected, values) <= best
                {
                    assert |selected| == |weights|;
                    assert |selected| > 0;

                    if selected[0] {
                        assert total_weight(selected, weights)
                            == weights[0]
                               + total_weight(selected[1..], weights[1..]);
                        assert total_weight(selected[1..], weights[1..])
                            <= capacity - weights[0];
                        assert |selected[1..]| == |weights[1..]|;
                        assert is_valid_strategy(
                            selected[1..],
                            weights[1..],
                            capacity - weights[0]
                        );

                        assert total_value(selected[1..], values[1..])
                            <= takeBest;
                        assert total_value(selected, values)
                            == values[0]
                               + total_value(selected[1..], values[1..]);
                    } else {
                        assert total_weight(selected, weights)
                            == total_weight(selected[1..], weights[1..]);
                        assert |selected[1..]| == |weights[1..]|;
                        assert is_valid_strategy(
                            selected[1..],
                            weights[1..],
                            capacity
                        );

                        assert total_value(selected[1..], values[1..])
                            <= skipBest;
                        assert skipBest <= best;
                        assert total_value(selected, values)
                            == total_value(selected[1..], values[1..]);
                    }
                }
            } else {
                best := skipBest;
                chosen := [false] + skipChosen;

                assert |chosen| == |weights|;
                assert total_weight(chosen, weights)
                    == total_weight(skipChosen, weights[1..]);
                assert total_weight(chosen, weights) <= capacity;
                assert is_valid_strategy(chosen, weights, capacity);

                assert total_value(chosen, values)
                    == total_value(skipChosen, values[1..]);
                assert total_value(chosen, values) == best;

                forall selected: seq<bool>
                    | is_valid_strategy(selected, weights, capacity)
                    ensures total_value(selected, values) <= best
                {
                    assert |selected| == |weights|;
                    assert |selected| > 0;

                    if selected[0] {
                        assert total_weight(selected, weights)
                            == weights[0]
                               + total_weight(selected[1..], weights[1..]);
                        assert total_weight(selected[1..], weights[1..])
                            <= capacity - weights[0];
                        assert |selected[1..]| == |weights[1..]|;
                        assert is_valid_strategy(
                            selected[1..],
                            weights[1..],
                            capacity - weights[0]
                        );

                        assert total_value(selected[1..], values[1..])
                            <= takeBest;
                        assert total_value(selected, values)
                            == values[0]
                               + total_value(selected[1..], values[1..]);
                        assert values[0] + takeBest < skipBest;
                    } else {
                        assert total_weight(selected, weights)
                            == total_weight(selected[1..], weights[1..]);
                        assert |selected[1..]| == |weights[1..]|;
                        assert is_valid_strategy(
                            selected[1..],
                            weights[1..],
                            capacity
                        );

                        assert total_value(selected[1..], values[1..])
                            <= skipBest;
                        assert total_value(selected, values)
                            == total_value(selected[1..], values[1..]);
                    }
                }
            }
        } else {
            best := skipBest;
            chosen := [false] + skipChosen;

