            assert total_weight(w, ws) == w[0] * ws[0] + total_weight(w[1..], ws[1..]);
            assert total_value(w, vs) == w[0] * vs[0] + total_value(w[1..], vs[1..]);
            assert total_weight(counts, ws) == counts[0] * ws[0] + total_weight(w[1..], ws[1..]);
            assert total_value(counts, vs) == counts[0] * vs[0] + total_value(w[1..], vs[1..]);
