            assert counts[0] * ws[0] == 0;
            assert counts[0] * vs[0] == 0;
            assert forall i :: 0 <= i < |counts| ==> counts[i] >= 0;
        }
    }
}

method solve_knapsack_unbounded(weights: seq<int>, values: seq<int>, capacity: int) returns (max_val: int)
    requires |weights| == |values|
    requires |weights| > 0
    requires 0 <= capacity <= 1000 // Explicitly constrain non-negative capacity
    requires forall i :: 0 <= i < |weights| ==> weights[i] > 0 // Weights must be positive (> 0) to avoid infinite loops
    requires forall i :: 0 <= i < |weights| ==> weights[i] <= 1000
    requires forall i :: 0 <= i < |values| ==> 0 <= values[i] <= 1000 // Explicitly constrain non-negative values
    ensures max_val >= 0
    ensures
        // 1. Upper Bound
        forall counts: seq<int> :: 
            is_valid_strategy(counts, weights, capacity)
            ==> total_value(counts, values) <= max_val
    ensures
        // 2. Existence
        exists counts: seq<int> :: 
            is_valid_strategy(counts, weights, capacity)
            && total_value(counts, values) == max_val
{
    var n := |weights|;
    assert GoodItems(weights, values);
    GoodDrop(weights, values, n);
    var row := new int[capacity + 1];
    var c := 0;
    while c <= capacity
        invariant 0 <= c <= capacity + 1
        invariant GoodItems(weights[n..], values[n..])
        invariant forall j :: 0 <= j < c ==> row[j] == Best(weights[n..], values[n..], j)
    {
        row[c] := 0;
        c := c + 1;
    }

    var i := n;
    while i > 0
        invariant 0 <= i <= n
        invariant row.Length == capacity + 1
        invariant GoodItems(weights[i..], values[i..])
        invariant forall j :: 0 <= j <= capacity ==> row[j] == Best(weights[i..], values[i..], j)
    {
        i := i - 1;
        GoodDrop(weights, values, i);
        GoodDrop(weights, values, i + 1);
        var ws := weights[i..];
        var vs := values[i..];
        assert ws[1..] == weights[i + 1..];
        assert vs[1..] == values[i + 1..];
        assert ws[0] == weights[i];
        assert vs[0] == values[i];
        c := 0;
        while c <= capacity
            invariant 0 <= c <= capacity + 1
            invariant GoodItems(ws, vs)
            invariant GoodItems(weights[i + 1..], values[i + 1..])
            invariant forall j :: 0 <= j < c ==> row[j] == Best(ws, vs, j)
            invariant forall j :: c <= j <= capacity ==> row[j] == Best(weights[i + 1..], values[i + 1..], j)
        {
            var skip := row[c];
            assert skip == Best(ws[1..], vs[1..], c);
            var best := skip;
            if weights[i] <= c {
                var take := values[i] + row[c - weights[i]];
                assert take == vs[0] + Best(ws, vs, c - ws[0]);
                if take > skip {
                    best := take;
                }
            }
            assert best == Best(ws, vs, c);
            row[c] := best;
            c := c + 1;
        }
    }

    assert weights[0..] == weights;
    assert values[0..] == values;
    max_val := row[capacity];
    assert max_val == Best(weights, values, capacity);

    forall counts: seq<int> | is_valid_strategy(counts, weights, capacity)
        ensures total_value(counts, values) <= max_val
    {
        UpperBound(counts, weights, values, capacity);
    }

    var w := ExistsOpt(weights, values, capacity);
    assert is_valid_strategy(w, weights, capacity) && total_value(w, values) == max_val;
}
