            skipCounts, weights, values, capacity);

        if capacity < weights[0] {
            maxValue := skipValue;
            best := skipBest;

            forall counts: seq<int>
                | is_valid_strategy(counts, weights, capacity)
                ensures total_value(counts, values) <= maxValue
            {
                FirstCountZero_4110(counts, weights, capacity);
                TailStrategy_4110(
                    counts, weights, values, capacity);
                assert total_value(
                    counts[1..], values[1..]) <= skipValue;
            }
        } else {
            var takeValue, takeCounts :=
                KnapsackRec_4110(
                    weights,
                    values,
                    capacity - weights[0]);

            var takeBest :=
                [takeCounts[0] + 1] + takeCounts[1..];

            AddFirstItem_4110(
                takeCounts, weights, values, capacity);

            if skipValue >= takeValue + values[0] {
                maxValue := skipValue;
                best := skipBest;
            } else {
                maxValue := takeValue + values[0];
                best := takeBest;
            }

            assert skipValue <= maxValue;
            assert takeValue + values[0] <= maxValue;

            forall counts: seq<int>
                | is_valid_strategy(counts, weights, capacity)
                ensures total_value(counts, values) <= maxValue
            {
                assert counts[0] >= 0;

                if counts[0] == 0 {
                    TailStrategy_4110(
                        counts, weights, values, capacity);
                    assert total_value(
                        counts[1..], values[1..]) <= skipValue;
                } else {
                    assert counts[0] > 0;
                    var reduced :=
                        [counts[0] - 1] + counts[1..];

                    RemoveFirstItem_4110(
                        counts, weights, values, capacity);

                    assert total_value(reduced, values)
                        <= takeValue;
                    assert total_value(counts, values)
                        == total_value(reduced, values)
                           + values[0];
                }
            }
        }
    }
}

