method solve_knapsack_01(weights: seq<int>, values: seq<int>, capacity: int) returns (max_val: int)
    requires |weights| == |values|
    requires |weights| <= 100 // Reasonable bound for recursion/verification time
    requires 0 <= capacity <= 1000 // Explicitly constrain non-negative capacity
    requires forall i :: 0 <= i < |weights| ==> 0 <= weights[i] <= 1000 // Explicitly constrain non-negative weights
    requires forall i :: 0 <= i < |values| ==> 0 <= values[i] <= 1000   // Explicitly constrain non-negative values
    ensures max_val >= 0
    ensures
        // 1. Upper Bound
        forall selected: seq<bool> :: 
            is_valid_strategy(selected, weights, capacity)
            ==> total_value(selected, values) <= max_val
    ensures
        // 2. Existence
        exists selected: seq<bool> :: 
            is_valid_strategy(selected, weights, capacity)
            && total_value(selected, values) == max_val
{
    var dp: seq<int> := seq(capacity + 1, _ => 0);
    var i: int := |weights|;

    while i > 0
        invariant 0 <= i <= |weights|
        invariant |dp| == capacity + 1
        invariant forall c :: 0 <= c <= capacity ==> dp[c] == opt(weights[i..], values[i..], c)
        decreases i
    {
        i := i - 1;
        assert weights[i..][1..] == weights[i + 1..];
        assert values[i..][1..] == values[i + 1..];

        var next_dp: seq<int> := [];
        var c: int := 0;
        while c <= capacity
            invariant 0 <= c <= capacity + 1
            invariant |next_dp| == c
            invariant forall k :: 0 <= k < c ==> next_dp[k] == opt(weights[i..], values[i..], k)
            decreases capacity + 1 - c
        {
            var skip := dp[c];
            var best: int;
            if weights[i] <= c {
                var take := values[i] + dp[c - weights[i]];
                best := if take > skip then take else skip;
            } else {
                best := skip;
            }
            assert best == opt(weights[i..], values[i..], c);
            next_dp := next_dp + [best];
            c := c + 1;
        }
        dp := next_dp;
    }

    assert weights[0..] == weights;
    assert values[0..] == values;
    max_val := dp[capacity];
    lemma_opt_spec(weights, values, capacity);
}

