        forall counts: seq<int> :: 
            is_valid_strategy(counts, weights, capacity)
            ==> total_value(counts, values) <= max_val
    ensures
        // 2. Existence
        exists counts: seq<int> :: 
            is_valid_strategy(counts, weights, capacity)
            && total_value(counts, values) == max_val
{
    var dp: seq<int> := [];
    var witnesses: seq<seq<int>> := [];
    var c := 0;

    while c <= capacity
        invariant 0 <= c <= capacity + 1
        invariant |dp| == c
        invariant |witnesses| == c
        invariant forall c' :: 0 <= c' < c ==> dp[c'] >= 0
        invariant forall c' :: 0 <= c' < c ==> is_optimal_witness(witnesses[c'], weights, values, c', dp[c'])
        invariant forall c' :: 0 <= c' < c ==> is_upper_bound(weights, values, c', dp[c'])
        decreases capacity + 1 - c
