    max_val := dp[capacity];
    assert is_upper_bound(weights, values, capacity, dp[capacity]);
    assert is_optimal_witness(witnesses[capacity], weights, values, capacity, dp[capacity]);
    assert is_valid_strategy(witnesses[capacity], weights, capacity) && total_value(witnesses[capacity], values) == max_val;
