  requires |c| > 0
  requires forall x :: 0 <= x < |c| ==> c[x] == c[0]
  ensures NumLabels(c) == 1
{
  assert Labels(c) == {c[0]} by {
    forall x | x in Labels(c) ensures x == c[0] {
      var j :| 0 <= j < |c| && c[j] == x;
    }
    assert c[0] in Labels(c);
  }
}

// ---------- Graph predicates ----------

ghost predicate InRange(g: seq<seq<(int, int)>>)
{
  forall u, i :: 0 <= u < |g| && 0 <= i < |g[u]| ==> 0 <= g[u][i].0 < |g|
}

ghost predicate WB(g: seq<seq<(int, int)>>)
{
  forall u, i :: 0 <= u < |g| && 0 <= i < |g[u]| ==> -100000 <= g[u][i].1 <= 100000
}

lemma GraphWeights(g: seq<seq<(int, int)>>)
  requires weights_bounded(g)
  ensures WB(g)
{
  forall u, i | 0 <= u < |g| && 0 <= i < |g[u]|
    ensures -100000 <= g[u][i].1 <= 100000
  {
    assert has_edge(g, u, g[u][i].0, g[u][i].1);
  }
}

ghost predicate Closed(g: seq<seq<(int, int)>>, c: seq<int>, t: int)
{
  forall u, i :: 0 <= u < |g| && 0 <= i < |g[u]| && u < |c| && 0 <= g[u][i].0 < |c| && g[u][i].1 <= t
    ==> c[u] == c[g[u][i].0]
}

ghost predicate ClosedUpTo(g: seq<seq<(int, int)>>, c: seq<int>, t: int, u0: int, i0: int)
{
  forall u, i :: 0 <= u < |g| && 0 <= i < |g[u]| && u < |c| && 0 <= g[u][i].0 < |c| && g[u][i].1 == t
    && (u < u0 || (u == u0 && i < i0))
    ==> c[u] == c[g[u][i].0]
}

lemma ClosedRelabel(g: seq<seq<(int, int)>>, c: seq<int>, t: int, a: int, b: int)
  requires Closed(g, c, t)
  ensures Closed(g, Relabel(c, a, b), t)
{
  var c' := Relabel(c, a, b);
  forall u, i | 0 <= u < |g| && 0 <= i < |g[u]| && u < |c'| && 0 <= g[u][i].0 < |c'| && g[u][i].1 <= t
    ensures c'[u] == c'[g[u][i].0]
  {
    assert c[u] == c[g[u][i].0];
  }
}

lemma ClosedUpToRelabel(g: seq<seq<(int, int)>>, c: seq<int>, t: int, u0: int, i0: int, a: int, b: int)
  requires ClosedUpTo(g, c, t, u0, i0)
  ensures ClosedUpTo(g, Relabel(c, a, b), t, u0, i0)
{
  var c' := Relabel(c, a, b);
  forall u, i | 0 <= u < |g| && 0 <= i < |g[u]| && u < |c'| && 0 <= g[u][i].0 < |c'| && g[u][i].1 == t
    && (u < u0 || (u == u0 && i < i0))
    ensures c'[u] == c'[g[u][i].0]
  {
    assert c[u] == c[g[u][i].0];
  }
}

lemma ClosedUpToExtend(g: seq<seq<(int, int)>>, c: seq<int>, t: int, u0: int, i0: int)
  requires 0 <= u0 < |g| && 0 <= i0 < |g[u0]|
  requires ClosedUpTo(g, c, t, u0, i0)
  requires u0 < |c| && 0 <= g[u0][i0].0 < |c| && g[u0][i0].1 == t ==> c[u0] == c[g[u0][i0].0]
  ensures ClosedUpTo(g, c, t, u0, i0 + 1)
{
  forall u, i | 0 <= u < |g| && 0 <= i < |g[u]| && u < |c| && 0 <= g[u][i].0 < |c| && g[u][i].1 == t
    && (u < u0 || (u == u0 && i < i0 + 1))
    ensures c[u] == c[g[u][i].0]
  {
    if u == u0 && i == i0 {
    } else {
      assert u < u0 || (u == u0 && i < i0);
    }
  }
}

lemma ClosedUpToNext(g: seq<seq<(int, int)>>, c: seq<int>, t: int, u0: int)
  requires 0 <= u0 < |g|
  requires ClosedUpTo(g, c, t, u0, |g[u0]|)
  ensures ClosedUpTo(g, c, t, u0 + 1, 0)
{
  forall u, i | 0 <= u < |g| && 0 <= i < |g[u]| && u < |c| && 0 <= g[u][i].0 < |c| && g[u][i].1 == t
    && (u < u0 + 1 || (u == u0 + 1 && i < 0))
    ensures c[u] == c[g[u][i].0]
  {
    assert u < u0 || (u == u0 && i < |g[u0]|);
  }
}

lemma ClosedUpToAll(g: seq<seq<(int, int)>>, c: seq<int>, t: int)
  requires ClosedUpTo(g, c, t, |g|, 0)
  requires Closed(g, c, t - 1)
  ensures Closed(g, c, t)
{
  forall u, i | 0 <= u < |g| && 0 <= i < |g[u]| && u < |c| && 0 <= g[u][i].0 < |c| && g[u][i].1 <= t
    ensures c[u] == c[g[u][i].0]
  {
    if g[u][i].1 < t {
      assert g[u][i].1 <= t - 1;
    } else {
      assert u < |g|;
    }
  }
}

// ---------- Connectivity of chosen edges ----------

ghost predicate ConnInv(c: seq<int>, T: seq<Edge>)
{
  forall x, y :: 0 <= x < |c| && 0 <= y < |c| && c[x] == c[y] ==> edges_connected(T, x, y)
}

lemma ConnRefl(T: seq<Edge>, x: int)
  ensures edges_connected(T, x, x)
{
  var p := [x];
  assert path_follows_edges(T, p);
}

lemma EdgeConn(T: seq<Edge>, k: int)
  requires 0 <= k < |T|
  ensures edges_connected(T, T[k].0, T[k].1)
  ensures edges_connected(T, T[k].1, T[k].0)
{
  var p := [T[k].0, T[k].1];
  assert edge_in_set(T, p[0], p[1]);
  assert path_follows_edges(T, p);
  var q := [T[k].1, T[k].0];
  assert edge_in_set(T, q[0], q[1]);
  assert path_follows_edges(T, q);
}

lemma Mono(T: seq<Edge>, e: Edge, x: int, y: int)
  requires edges_connected(T, x, y)
  ensures edges_connected(T + [e], x, y)
{
  var p :| |p| > 0 && p[0] == x && p[|p| - 1] == y && path_follows_edges(T, p);
  forall k | 0 <= k < |p| - 1 ensures edge_in_set(T + [e], p[k], p[k + 1]) {
    assert edge_in_set(T, p[k], p[k + 1]);
    var idx :| 0 <= idx < |T| && ((T[idx].0 == p[k] && T[idx].1 == p[k + 1]) || (T[idx].0 == p[k + 1] && T[idx].1 == p[k]));
    assert (T + [e])[idx] == T[idx];
  }
  assert path_follows_edges(T + [e], p);
}

lemma Trans(T: seq<Edge>, x: int, y: int, z: int)
  requires edges_connected(T, x, y) && edges_connected(T, y, z)
  ensures edges_connected(T, x, z)
{
  var p :| |p| > 0 && p[0] == x && p[|p| - 1] == y && path_follows_edges(T, p);
  var q :| |q| > 0 && q[0] == y && q[|q| - 1] == z && path_follows_edges(T, q);
  var r := p + q[1..];
  assert |r| == |p| + |q| - 1;
  forall k | 0 <= k < |r| - 1 ensures edge_in_set(T, r[k], r[k + 1]) {
    if k < |p| - 1 {
      assert r[k] == p[k] && r[k + 1] == p[k + 1];
      assert edge_in_set(T, p[k], p[k + 1]);
    } else {
      var j := k - |p| + 1;
      assert 0 <= j < |q| - 1;
      if k == |p| - 1 {
        assert r[k] == p[|p| - 1];
      } else {
        assert r[k] == q[1..][k - |p|];
      }
      assert r[k] == q[j];
      assert r[k + 1] == q[1..][k + 1 - |p|];
      assert r[k + 1] == q[j + 1];
      assert edge_in_set(T, q[j], q[j + 1]);
    }
  }
  assert r[0] == x;
  if |q| == 1 {
    assert r[|r| - 1] == p[|p| - 1];
  } else {
    assert r[|r| - 1] == q[1..][|q| - 2];
  }
  assert r[|r| - 1] == z;
  assert path_follows_edges(T, r);
}

lemma ConnStep(c: seq<int>, T: seq<Edge>, u: int, v: int, w: int)
  requires 0 <= u < |c| && 0 <= v < |c| && c[u] != c[v]
  requires ConnInv(c, T)
  ensures ConnInv(Relabel(c, c[u], c[v]), T + [(u, v, w)])
{
  var e: Edge := (u, v, w);
  var T' := T + [e];
  var a, b := c[u], c[v];
  var c' := Relabel(c, a, b);
  assert T'[|T|] == e;
  EdgeConn(T', |T|);
  forall x, y | 0 <= x < |c'| && 0 <= y < |c'| && c'[x] == c'[y]
    ensures edges_connected(T', x, y)
  {
    if c[x] == c[y] {
      Mono(T, e, x, y);
    } else if c[x] == b {
      assert c[y] == a;
      assert c[x] == c[v];
      assert c[u] == c[y];
      Mono(T, e, x, v);
      Mono(T, e, u, y);
      Trans(T', x, v, u);
      Trans(T', x, u, y);
    } else {
      assert c[y] == b;
      assert c[x] == a;
      assert c[x] == c[u];
      assert c[v] == c[y];
      Mono(T, e, x, u);
      Mono(T, e, v, y);
      Trans(T', x, u, v);
      Trans(T', x, v, y);
    }
  }
}

lemma ValidAppend(g: seq<seq<(int, int)>>, S: seq<Edge>, e: Edge)
  requires are_valid_edges(g, S)
  requires has_edge(g, e.0, e.1, e.2)
  ensures are_valid_edges(g, S + [e])
{
  forall k | 0 <= k < |S + [e]|
    ensures has_edge(g, (S + [e])[k].0, (S + [e])[k].1, (S + [e])[k].2)
  {
    if k < |S| {
      assert (S + [e])[k] == S[k];
    } else {
      assert (S + [e])[k] == e;
    }
  }
}

// ---------- Counting & weights ----------

ghost function cntLe(S: seq<Edge>, t: int): int
  decreases |S|
{
  if |S| == 0 then 0 else (if S[0].2 <= t then 1 else 0) + cntLe(S[1..], t)
}

ghost function tw(S: seq<Edge>, t: int): int
  decreases |S|
{
  if |S| == 0 then 0 else (if S[0].2 >= t then S[0].2 else t) + tw(S[1..], t)
}

ghost predicate Bounded(S: seq<Edge>)
{
  forall k :: 0 <= k < |S| ==> -100000 <= S[k].2 <= 100000
}

lemma CntAppend(S: seq<Edge>, e: Edge, t: int)
  ensures cntLe(S + [e], t) == cntLe(S, t) + (if e.2 <= t then 1 else 0)
  decreases |S|
{
  if |S| == 0 {
    assert S + [e] == [e];
    assert [e][1..] == [];
  } else {
    assert (S + [e])[1..] == S[1..] + [e];
    CntAppend(S[1..], e, t);
  }
}

lemma CntAll(S: seq<Edge>, t: int)
  requires forall k :: 0 <= k < |S| ==> S[k].2 <= t
  ensures cntLe(S, t) == |S|
  decreases |S|
{
  if |S| > 0 {
    assert forall k :: 0 <= k < |S[1..]| ==> S[1..][k] == S[k + 1];
    CntAll(S[1..], t);
  }
}

lemma TwStep(S: seq<Edge>, t: int)
  ensures tw(S, t + 1) == tw(S, t) + cntLe(S, t)
  decreases |S|
{
  if |S| > 0 {
    TwStep(S[1..], t);
  }
}

lemma TwTop(S: seq<Edge>)
  requires Bounded(S)
  ensures tw(S, 100000) == 100000 * |S|
  decreases |S|
{
  if |S| > 0 {
    assert Bounded(S[1..]) by {
      forall k | 0 <= k < |S[1..]| ensures -100000 <= S[1..][k].2 <= 100000 {
        assert S[1..][k] == S[k + 1];
      }
    }
    TwTop(S[1..]);
  }
}

lemma TwBottom(S: seq<Edge>)
  requires Bounded(S)
  ensures tw(S, -100000) == total_weight(S)
  decreases |S|
{
  if |S| > 0 {
    assert Bounded(S[1..]) by {
      forall k | 0 <= k < |S[1..]| ensures -100000 <= S[1..][k].2 <= 100000 {
        assert S[1..][k] == S[k + 1];
      }
    }
    TwBottom(S[1..]);
  }
}

lemma Telescope(T: seq<Edge>, O: seq<Edge>, t: int)
  requires -100000 <= t <= 100000
  requires tw(T, 100000) == tw(O, 100000)
  requires forall s :: t <= s < 100000 ==> cntLe(T, s) >= cntLe(O, s)
  ensures tw(T, t) <= tw(O, t)
  decreases 100000 - t
{
  if t < 100000 {
    Telescope(T, O, t + 1);
    TwStep(T, t);
    TwStep(O, t);
  }
}

lemma WeightsOf(g: seq<seq<(int, int)>>, S: seq<Edge>)
  requires weights_bounded(g)
  requires are_valid_edges(g, S)
  ensures Bounded(S)
{
  forall k | 0 <= k < |S| ensures -100000 <= S[k].2 <= 100000 {
    assert has_edge(g, S[k].0, S[k].1, S[k].2);
  }
}

// ---------- Processing another edge set ----------

ghost predicate EdgesInRange(S: seq<Edge>, n: int)
{
  forall k :: 0 <= k < |S| ==> 0 <= S[k].0 < n && 0 <= S[k].1 < n
}

lemma ValidInRange(g: seq<seq<(int, int)>>, S: seq<Edge>)
  requires InRange(g)
  requires are_valid_edges(g, S)
  ensures EdgesInRange(S, |g|)
{
  forall k | 0 <= k < |S| ensures 0 <= S[k].0 < |g| && 0 <= S[k].1 < |g| {
    assert has_edge(g, S[k].0, S[k].1, S[k].2);
    var i :| 0 <= S[k].0 < |g| && 0 <= i < |g[S[k].0]| && g[S[k].0][i].0 == S[k].1 && g[S[k].0][i].1 == S[k].2;
  }
}

ghost function Step(c: seq<int>, e: Edge, t: int): seq<int>
  ensures |Step(c, e, t)| == |c|
{
  if e.2 > t && 0 <= e.0 < |c| && 0 <= e.1 < |c| then Relabel(c, c[e.0], c[e.1]) else c
}

ghost function ProcessGt(c: seq<int>, S: seq<Edge>, t: int): seq<int>
  ensures |ProcessGt(c, S, t)| == |c|
  decreases |S|
{
  if |S| == 0 then c else ProcessGt(Step(c, S[0], t), S[1..], t)
}

lemma ProcessPreserves(c: seq<int>, S: seq<Edge>, t: int, x: int, y: int)
  requires 0 <= x < |c| && 0 <= y < |c| && c[x] == c[y]
  ensures ProcessGt(c, S, t)[x] == ProcessGt(c, S, t)[y]
  decreases |S|
{
  if |S| > 0 {
    var c1 := Step(c, S[0], t);
    assert c1[x] == c1[y];
    ProcessPreserves(c1, S[1..], t, x, y);
  }
}

lemma ProcessEdges(c: seq<int>, S: seq<Edge>, t: int)
  requires EdgesInRange(S, |c|)
  requires forall k :: 0 <= k < |S| && S[k].2 <= t ==> c[S[k].0] == c[S[k].1]
  ensures forall k :: 0 <= k < |S| ==> ProcessGt(c, S, t)[S[k].0] == ProcessGt(c, S, t)[S[k].1]
  decreases |S|
{
  if |S| > 0 {
    var c1 := Step(c, S[0], t);
    assert |c1| == |c|;
    assert c1[S[0].0] == c1[S[0].1];
    assert EdgesInRange(S[1..], |c1|) by {
      forall k | 0 <= k < |S[1..]| ensures 0 <= S[1..][k].0 < |c1| && 0 <= S[1..][k].1 < |c1| {
        assert S[1..][k] == S[k + 1];
      }
    }
    forall k | 0 <= k < |S[1..]| && S[1..][k].2 <= t
      ensures c1[S[1..][k].0] == c1[S[1..][k].1]
    {
      assert S[1..][k] == S[k + 1];
      assert c[S[k + 1].0] == c[S[k + 1].1];
    }
    ProcessEdges(c1, S[1..], t);
    ProcessPreserves(c1, S[1..], t, S[0].0, S[0].1);
    assert ProcessGt(c, S, t) == ProcessGt(c1, S[1..], t);
    forall k | 0 <= k < |S|
      ensures ProcessGt(c, S, t)[S[k].0] == ProcessGt(c, S, t)[S[k].1]
    {
      if k > 0 {
        assert S[k] == S[1..][k - 1];
      }
    }
  }
}

lemma ProcessCount(c: seq<int>, S: seq<Edge>, t: int)
  ensures NumLabels(ProcessGt(c, S, t)) >= NumLabels(c) - (|S| - cntLe(S, t))
  decreases |S|
{
  if |S| > 0 {
    var c1 := Step(c, S[0], t);
    if S[0].2 > t && 0 <= S[0].0 < |c| && 0 <= S[0].1 < |c| {
      RelabelCount(c, S[0].0, S[0].1);
    }
    ProcessCount(c1, S[1..], t);
  }
}

lemma PathConstant(c: seq<int>, S: seq<Edge>, p: seq<int>)
  requires EdgesInRange(S, |c|)
  requires forall k :: 0 <= k < |S| ==> c[S[k].0] == c[S[k].1]
  requires |p| > 0 && 0 <= p[0] < |c|
  requires path_follows_edges(S, p)
  ensures 0 <= p[|p| - 1] < |c| && c[p[|p| - 1]] == c[p[0]]
{
  var k := 0;
  while k < |p| - 1
    invariant 0 <= k <= |p| - 1
    invariant 0 <= p[k] < |c| && c[p[k]] == c[p[0]]
    decreases |p| - 1 - k
  {
    assert edge_in_set(S, p[k], p[k + 1]);
    var e :| 0 <= e < |S| && ((S[e].0 == p[k] && S[e].1 == p[k + 1]) || (S[e].0 == p[k + 1] && S[e].1 == p[k]));
    assert c[S[e].0] == c[S[e].1];
    k := k + 1;
  }
}

lemma SpanningConstant(g: seq<seq<(int, int)>>, c: seq<int>, S: seq<Edge>)
  requires |c| == |g| > 0
  requires is_spanning(g, S)
  requires EdgesInRange(S, |c|)
  requires forall k :: 0 <= k < |S| ==> c[S[k].0] == c[S[k].1]
  ensures forall x :: 0 <= x < |c| ==> c[x] == c[0]
{
  forall x | 0 <= x < |c| ensures c[x] == c[0] {
    assert edges_connected(S, 0, x);
    var p :| |p| > 0 && p[0] == 0 && p[|p| - 1] == x && path_follows_edges(S, p);
    PathConstant(c, S, p);
  }
}

lemma OtherBound(g: seq<seq<(int, int)>>, c: seq<int>, t: int, S: seq<Edge>)
  requires InRange(g)
  requires |c| == |g| > 0
  requires Closed(g, c, t)
  requires are_valid_edges(g, S)
  requires is_spanning(g, S)
  ensures |S| - cntLe(S, t) >= NumLabels(c) - 1
{
  ValidInRange(g, S);
  forall k | 0 <= k < |S| && S[k].2 <= t ensures c[S[k].0] == c[S[k].1] {
    assert has_edge(g, S[k].0, S[k].1, S[k].2);
    var i :| 0 <= S[k].0 < |g| && 0 <= i < |g[S[k].0]| && g[S[k].0][i].0 == S[k].1 && g[S[k].0][i].1 == S[k].2;
    assert c[S[k].0] == c[g[S[k].0][i].0];
  }
  var P := ProcessGt(c, S, t);
  ProcessEdges(c, S, t);
  SpanningConstant(g, P, S);
  ConstLabels(P);
  ProcessCount(c, S, t);
}

lemma Optimal(g: seq<seq<(int, int)>>, T: seq<Edge>, O: seq<Edge>, hist: map<int, seq<int>>)
  requires InRange(g) && |g| > 0 && weights_bounded(g)
  requires is_spanning_tree(g, T) && is_spanning_tree(g, O)
  requires forall s :: -100000 <= s < 100001 ==> s in hist && |hist[s]| == |g| && Closed(g, hist[s], s)
             && cntLe(T, s) == |g| - NumLabels(hist[s])
  ensures total_weight(T) <= total_weight(O)
{
  forall s | -100000 <= s < 100000 ensures cntLe(T, s) >= cntLe(O, s) {
    OtherBound(g, hist[s], s, O);
  }
  WeightsOf(g, T);
  WeightsOf(g, O);
  TwTop(T);
  TwTop(O);
  Telescope(T, O, -100000);
  TwBottom(T);
  TwBottom(O);
}

// ---------- Graph connectivity ----------

lemma GraphPathConstant(g: seq<seq<(int, int)>>, c: seq<int>, p: seq<int>)
  requires InRange(g) && WB(g) && |c| == |g|
  requires Closed(g, c, 100000)
  requires |p| > 0 && 0 <= p[0] < |g|
  requires path_follows_graph(g, p)
  ensures 0 <= p[|p| - 1] < |c| && c[p[|p| - 1]] == c[p[0]]
{
  var k := 0;
  while k < |p| - 1
    invariant 0 <= k <= |p| - 1
    invariant 0 <= p[k] < |c| && c[p[k]] == c[p[0]]
    decreases |p| - 1 - k
  {
    assert graph_has_any_edge(g, p[k], p[k + 1]);
    var i :| 0 <= p[k] < |g| && 0 <= i < |g[p[k]]| && g[p[k]][i].0 == p[k + 1];
    assert g[p[k]][i].1 <= 100000;
    assert c[p[k]] == c[g[p[k]][i].0];
    k := k + 1;
  }
}

lemma GraphConstant(g: seq<seq<(int, int)>>, c: seq<int>)
  requires InRange(g) && WB(g)
  requires |c| == |g| > 0
  requires graph_is_connected(g)
  requires Closed(g, c, 100000)
  ensures forall x :: 0 <= x < |c| ==> c[x] == c[0]
{
  forall x | 0 <= x < |c| ensures c[x] == c[0] {
    assert nodes_have_path(g, 0, x);
    var p :| |p| > 0 && p[0] == 0 && p[|p| - 1] == x && path_follows_graph(g, p);
    GraphPathConstant(g, c, p);
  }
}

// ---------- Main ----------

method kruskal_mst(graph: WeightedGraph) returns (edges: seq<Edge>)
    requires well_formed(graph)
    requires size(graph) > 0
    requires weights_bounded(view(graph))
    requires graph_is_connected(view(graph))
    ensures is_mst(view(graph), edges)
{
  ghost var g := graph.adj;
  assert g == view(graph);
  var n := |graph.adj|;
  assert InRange(g);
  GraphWeights(g);
  IotaLabels(n);
  var comp := Iota(n);
  edges := [];
  forall x, y | 0 <= x < |comp| && 0 <= y < |comp| && comp[x] == comp[y]
    ensures edges_connected(edges, x, y)
  {
    ConnRefl(edges, x);
  }
  assert ConnInv(comp, edges);
  ghost var hist: map<int, seq<int>> := map[];
  var t := -100000;
  while t <= 100000
    invariant -100000 <= t <= 100001
    invariant InRange(g) && WB(g)
    invariant |comp| == n
    invariant are_valid_edges(g, edges)
    invariant ConnInv(comp, edges)
    invariant |edges| + NumLabels(comp) == n
    invariant forall k :: 0 <= k < |edges| ==> edges[k].2 < t
    invariant Closed(g, comp, t - 1)
    invariant forall s :: -100000 <= s < t ==> s in hist && |hist[s]| == n && Closed(g, hist[s], s)
                && cntLe(edges, s) == n - NumLabels(hist[s])
    decreases 100001 - t
  {
    var u := 0;
    while u < n
      invariant 0 <= u <= n
      invariant InRange(g) && WB(g)
      invariant |comp| == n
      invariant are_valid_edges(g, edges)
      invariant ConnInv(comp, edges)
      invariant |edges| + NumLabels(comp) == n
      invariant forall k :: 0 <= k < |edges| ==> edges[k].2 <= t
      invariant Closed(g, comp, t - 1)
      invariant ClosedUpTo(g, comp, t, u, 0)
      invariant forall s :: -100000 <= s < t ==> s in hist && |hist[s]| == n && Closed(g, hist[s], s)
                  && cntLe(edges, s) == n - NumLabels(hist[s])
      decreases n - u
    {
      var i := 0;
      while i < |graph.adj[u]|
        invariant 0 <= i <= |graph.adj[u]|
        invariant InRange(g) && WB(g)
        invariant |comp| == n
        invariant are_valid_edges(g, edges)
        invariant ConnInv(comp, edges)
        invariant |edges| + NumLabels(comp) == n
        invariant forall k :: 0 <= k < |edges| ==> edges[k].2 <= t
        invariant Closed(g, comp, t - 1)
        invariant ClosedUpTo(g, comp, t, u, i)
        invariant forall s :: -100000 <= s < t ==> s in hist && |hist[s]| == n && Closed(g, hist[s], s)
                    && cntLe(edges, s) == n - NumLabels(hist[s])
        decreases |graph.adj[u]| - i
      {
        var v := graph.adj[u][i].0;
        var w := graph.adj[u][i].1;
