          RelabelCount(comp, u, v);
          ConnStep(comp, edges, u, v, w);
          ClosedRelabel(g, comp, t - 1, comp[u], comp[v]);
          ClosedUpToRelabel(g, comp, t, u, i, comp[u], comp[v]);
