// ---------- Executable helpers ----------

function Iota(n: int): seq<int>
  requires n >= 0
{
  seq(n, j => j)
}

function Relabel(c: seq<int>, a: int, b: int): seq<int>
{
  seq(|c|, j requires 0 <= j < |c| => if c[j] == b then a else c[j])
}

// ---------- Label sets ----------

ghost function Labels(c: seq<int>): set<int>
{
  set j | 0 <= j < |c| :: c[j]
}

ghost function NumLabels(c: seq<int>): int
{
  |Labels(c)|
}

ghost function RangeSet(n: int): set<int>
{
  set j | 0 <= j < n
}

lemma RangeCard(n: int)
  requires n >= 0
  ensures |RangeSet(n)| == n
{
  if n > 0 {
    RangeCard(n - 1);
    assert RangeSet(n) == RangeSet(n - 1) + {n - 1};
  }
}

lemma IotaLabels(n: int)
  requires n >= 0
  ensures |Iota(n)| == n
  ensures forall j :: 0 <= j < n ==> Iota(n)[j] == j
  ensures NumLabels(Iota(n)) == n
{
  var c := Iota(n);
  assert Labels(c) == RangeSet(n) by {
    forall x | x in Labels(c) ensures x in RangeSet(n) {
      var j :| 0 <= j < |c| && c[j] == x;
    }
    forall x | x in RangeSet(n) ensures x in Labels(c) {
      assert c[x] == x;
    }
  }
  RangeCard(n);
}

lemma RelabelLabels(c: seq<int>, a: int, b: int)
  requires a in Labels(c)
  requires a != b
  ensures Labels(Relabel(c, a, b)) == Labels(c) - {b}
{
  var c' := Relabel(c, a, b);
  forall x | x in Labels(c')
    ensures x in Labels(c) - {b}
  {
    var j :| 0 <= j < |c'| && c'[j] == x;
    if c[j] == b {
      assert x == a;
    } else {
      assert x == c[j];
      assert c[j] in Labels(c);
    }
  }
  forall x | x in Labels(c) - {b}
    ensures x in Labels(c')
  {
    var j :| 0 <= j < |c| && c[j] == x;
    assert c'[j] == x;
  }
}

lemma RelabelCount(c: seq<int>, u: int, v: int)
  requires 0 <= u < |c| && 0 <= v < |c|
  ensures c[u] != c[v] ==> NumLabels(Relabel(c, c[u], c[v])) == NumLabels(c) - 1
  ensures NumLabels(Relabel(c, c[u], c[v])) >= NumLabels(c) - 1
{
  var a, b := c[u], c[v];
  assert a in Labels(c);
  assert b in Labels(c);
  if a == b {
    forall j | 0 <= j < |c| ensures Relabel(c, a, b)[j] == c[j] {}
    assert Relabel(c, a, b) == c;
  } else {
    RelabelLabels(c, a, b);
    var L := Labels(c);
    assert L == (L - {b}) + {b};
    assert |L| == |L - {b}| + 1;
  }
}

lemma ConstLabels(c: seq<int>)
  requires |c| > 0
  requires forall x :: 0 <= x < |c| ==> c[x] == c[0]
  ensures NumLabels(c) == 1
{
  assert Labels(c) == {c[0]} by {
    forall x | x in Labels(c) ensures x == c[0] {
      var j :| 0 <= j < |c| && c[j] == x;
    }
    assert c[0] in Labels(c);
  }
}

// ---------- Graph predicates ----------

ghost predicate InRange(g: seq<seq<(int, int)>>)
{
  forall u, i :: 0 <= u < |g| && 0 <= i < |g[u]| ==> 0 <= g[u][i].0 < |g|
}

ghost predicate WB(g: seq<seq<(int, int)>>)
{
  forall u, i :: 0 <= u < |g| && 0 <= i < |g[u]| ==> -100000 <= g[u][i].1 <= 100000
}

lemma GraphWeights(g: seq<seq<(int, int)>>)
  requires weights_bounded(g)
  ensures WB(g)
{
  forall u, i | 0 <= u < |g| && 0 <= i < |g[u]|
    ensures -100000 <= g[u][i].1 <= 100000
  {
    assert has_edge(g, u, g[u][i].0, g[u][i].1);
  }
}

ghost predicate Closed(g: seq<seq<(int, int)>>, c: seq<int>, t: int)
{
  forall u, i :: 0 <= u < |g| && 0 <= i < |g[u]| && u < |c| && 0 <= g[u][i].0 < |c| && g[u][i].1 <= t
    ==> c[u] == c[g[u][i].0]
}

ghost predicate ClosedUpTo(g: seq<seq<(int, int)>>, c: seq<int>, t: int, u0: int, i0: int)
{
  forall u, i :: 0 <= u < |g| && 0 <= i < |g[u]| && u < |c| && 0 <= g[u][i].0 < |c| && g[u][i].1 == t
    && (u < u0 || (u == u0 && i < i0))
    ==> c[u] == c[g[u][i].0]
}

lemma ClosedRelabel(g: seq<seq<(int, int)>>, c: seq<int>, t: int, a: int, b: int)
  requires Closed(g, c, t)
  ensures Closed(g, Relabel(c, a, b), t)
{
  var c' := Relabel(c, a, b);
  forall u, i | 0 <= u < |g| && 0 <= i < |g[u]| && u < |c'| && 0 <= g[u][i].0 < |c'| && g[u][i].1 <= t
    ensures c'[u] == c'[g[u][i].0]
