  ensures ConnInv(Relabel(c, c[u], c[v]), T + [(u, v, w)])
{
  var e: Edge := (u, v, w);
  var T' := T + [e];
  var a, b := c[u], c[v];
  var c' := Relabel(c, a, b);
  assert T'[|T|] == e;
  EdgeConn(T', |T|);
  forall x, y | 0 <= x < |c'| && 0 <= y < |c'| && c'[x] == c'[y]
    ensures edges_connected(T', x, y)
  {
    if c[x] == c[y] {
      Mono(T, e, x, y);
    } else if c[x] == b {
      assert c[y] == a;
      assert c[x] == c[v];
      assert c[u] == c[y];
      Mono(T, e, x, v);
      Mono(T, e, u, y);
      Trans(T', x, v, u);
      Trans(T', x, u, y);
    } else {
      assert c[y] == b;
      assert c[x] == a;
      assert c[x] == c[u];
      assert c[v] == c[y];
      Mono(T, e, x, u);
      Mono(T, e, v, y);
      Trans(T', x, u, v);
      Trans(T', x, v, y);
    }
  }
}

lemma ValidAppend(g: seq<seq<(int, int)>>, S: seq<Edge>, e: Edge)
  requires are_valid_edges(g, S)
  requires has_edge(g, e.0, e.1, e.2)
  ensures are_valid_edges(g, S + [e])
{
  forall k | 0 <= k < |S + [e]|
    ensures has_edge(g, (S + [e])[k].0, (S + [e])[k].1, (S + [e])[k].2)
  {
    if k < |S| {
      assert (S + [e])[k] == S[k];
    } else {
      assert (S + [e])[k] == e;
    }
  }
}

