  ensures cntLe(S + [e], t) == cntLe(S, t) + (if e.2 <= t then 1 else 0)
  decreases |S|
{
  if |S| == 0 {
    assert S + [e] == [e];
    assert [e][1..] == [];
  } else {
    assert (S + [e])[1..] == S[1..] + [e];
    CntAppend(S[1..], e, t);
  }
}

