  requires forall k :: 0 <= k < |S| ==> S[k].2 <= t
  ensures cntLe(S, t) == |S|
  decreases |S|
{
  if |S| > 0 {
    assert forall k :: 0 <= k < |S[1..]| ==> S[1..][k] == S[k + 1];
    CntAll(S[1..], t);
  }
}

lemma TwStep(S: seq<Edge>, t: int)
  ensures tw(S, t + 1) == tw(S, t) + cntLe(S, t)
  decreases |S|
{
  if |S| > 0 {
    TwStep(S[1..], t);
  }
}

