lemma TwBottom(S: seq<Edge>)
  requires Bounded(S)
  ensures tw(S, -100000) == total_weight(S)
  decreases |S|
{
  if |S| > 0 {
    assert Bounded(S[1..]) by {
      forall k | 0 <= k < |S[1..]| ensures -100000 <= S[1..][k].2 <= 100000 {
        assert S[1..][k] == S[k + 1];
