lemma Telescope(T: seq<Edge>, O: seq<Edge>, t: int)
  requires -100000 <= t <= 100000
  requires tw(T, 100000) == tw(O, 100000)
  requires forall s :: t <= s < 100000 ==> cntLe(T, s) >= cntLe(O, s)
  ensures tw(T, t) <= tw(O, t)
  decreases 100000 - t
{
  if t < 100000 {
    Telescope(T, O, t + 1);
    TwStep(T, t);
    TwStep(O, t);
  }
}

lemma WeightsOf(g: seq<seq<(int, int)>>, S: seq<Edge>)
  requires weights_bounded(g)
  requires are_valid_edges(g, S)
  ensures Bounded(S)
{
  forall k | 0 <= k < |S| ensures -100000 <= S[k].2 <= 100000 {
    assert has_edge(g, S[k].0, S[k].1, S[k].2);
