{
  forall k | 0 <= k < |S| ensures 0 <= S[k].0 < |g| && 0 <= S[k].1 < |g| {
    assert has_edge(g, S[k].0, S[k].1, S[k].2);
    var i :| 0 <= S[k].0 < |g| && 0 <= i < |g[S[k].0]| && g[S[k].0][i].0 == S[k].1 && g[S[k].0][i].1 == S[k].2;
  }
}

ghost function Step(c: seq<int>, e: Edge, t: int): seq<int>
