        (edges[e_idx].0 == a && edges[e_idx].1 == b) ||
        (edges[e_idx].0 == b && edges[e_idx].1 == a)
    );
    var edges' := edges + [e];
    assert 0 <= e_idx < |edges'| && edges'[e_idx] == edges[e_idx];
}

lemma LemmaEdgesConnectedAppend(edges: seq<Edge>, e: Edge, u: int, v: int)
    requires edges_connected(edges, u, v)
    ensures edges_connected(edges + [e], u, v)
{
    var p: seq<int> :| |p| > 0 && p[0] == u && p[|p| - 1] == v && path_follows_edges(edges, p);
    var edges' := edges + [e];
    forall k: int | 0 <= k < |p| - 1
        ensures edge_in_set(edges', p[k], p[k + 1])
    {
        LemmaEdgeInSetAppend(edges, e, p[k], p[k + 1]);
    }
    assert path_follows_edges(edges', p);
}

lemma LemmaNewEdgeInSet(edges: seq<Edge>, e: Edge)
    ensures edge_in_set(edges + [e], e.0, e.1)
    ensures edge_in_set(edges + [e], e.1, e.0)
{
    var edges' := edges + [e];
    var idx := |edges|;
    assert 0 <= idx < |edges'| && edges'[idx] == e;
}

lemma LemmaPathStaysVisited(g: seq<seq<(int, int)>>, visited: seq<bool>, p: seq<int>, k: nat)
    requires |visited| == |g|
    requires forall u: int, i: int :: 0 <= u < |g| && 0 <= i < |g[u]| ==> 0 <= g[u][i].0 < |g|
    requires forall u: int, i: int :: 0 <= u < |g| && 0 <= i < |g[u]| && visited[u] ==> visited[g[u][i].0]
    requires |p| > 0 && 0 <= p[0] < |g| && visited[p[0]]
    requires path_follows_graph(g, p)
    requires k < |p|
    ensures 0 <= p[k] < |g| && visited[p[k]]
    decreases k
{
    if k == 0 {
    } else {
        LemmaPathStaysVisited(g, visited, p, k - 1);
        assert 0 <= k - 1 < |p| - 1;
        assert graph_has_any_edge(g, p[k - 1], p[k]);
        var i: int :| 0 <= i < |g[p[k - 1]]| && g[p[k - 1]][i].0 == p[k];
    }
}

lemma LemmaExtendSpanningTreeStep(
    g: seq<seq<(int, int)>>,
    visited: seq<bool>,
    tree_edges: seq<Edge>,
    best_u: int,
    best_v: int,
    best_w: int
)
    requires |visited| == |g| && |g| > 0
    requires 0 <= best_u < |g| && 0 <= best_v < |g|
    requires visited[0] && visited[best_u] && !visited[best_v]
    requires has_edge(g, best_u, best_v, best_w)
    requires are_valid_edges(g, tree_edges)
    requires forall u: int :: 0 <= u < |g| && visited[u] ==>
        edges_connected(tree_edges, 0, u) && edges_connected(tree_edges, u, 0)
    ensures are_valid_edges(g, tree_edges + [(best_u, best_v, best_w)])
    ensures forall u: int :: 0 <= u < |g| && visited[best_v := true][u] ==>
        edges_connected(tree_edges + [(best_u, best_v, best_w)], 0, u) &&
        edges_connected(tree_edges + [(best_u, best_v, best_w)], u, 0)
{
    var e: Edge := (best_u, best_v, best_w);
    var next_edges := tree_edges + [e];
    var next_vis := visited[best_v := true];
    forall k: int | 0 <= k < |next_edges|
        ensures has_edge(g, next_edges[k].0, next_edges[k].1, next_edges[k].2)
    {
        if k < |tree_edges| {
            assert next_edges[k] == tree_edges[k];
        } else {
            assert next_edges[k] == e;
        }
    }
    LemmaNewEdgeInSet(tree_edges, e);
    LemmaEdgesConnectedAppend(tree_edges, e, 0, best_u);
    LemmaEdgesConnectedAppend(tree_edges, e, best_u, 0);
    LemmaEdgesConnectedStep(next_edges, 0, best_u, best_v);
    LemmaEdgesConnectedRefl(next_edges, best_v);
    LemmaEdgesConnectedStep(next_edges, best_v, best_v, best_u);
    LemmaEdgesConnectedTrans(next_edges, best_v, best_u, 0);

    forall u: int | 0 <= u < |g| && next_vis[u]
        ensures edges_connected(next_edges, 0, u) && edges_connected(next_edges, u, 0)
    {
        if u == best_v {
        } else {
            assert visited[u];
            LemmaEdgesConnectedAppend(tree_edges, e, 0, u);
            LemmaEdgesConnectedAppend(tree_edges, e, u, 0);
        }
    }
}

method BuildSpanningTree(graph: WeightedGraph) returns (tree_edges: seq<Edge>)
    requires well_formed(graph)
    requires size(graph) > 0
    requires graph_is_connected(view(graph))
    ensures is_spanning_tree(view(graph), tree_edges)
{
    ghost var g := view(graph);
    var n := |graph.adj|;
    var visited: seq<bool> := [true];
    assert visited[..0] == [];
    while |visited| < n
        invariant 1 <= |visited| <= n
        invariant visited[0]
        invariant count_trues(visited) == 1
        decreases n - |visited|
    {
        var next_vis := visited + [false];
        assert next_vis[..|next_vis| - 1] == visited;
        visited := next_vis;
    }

    tree_edges := [];
    LemmaEdgesConnectedRefl(tree_edges, 0);

    while count_trues(visited) < n
        invariant |visited| == n
        invariant visited[0]
        invariant 1 <= count_trues(visited) <= n
        invariant |tree_edges| == count_trues(visited) - 1
        invariant are_valid_edges(g, tree_edges)
        invariant forall u: int :: 0 <= u < n && visited[u] ==>
            edges_connected(tree_edges, 0, u) && edges_connected(tree_edges, u, 0)
        decreases n - count_trues(visited)
    {
        var found := false;
        var best_u := 0;
        var best_v := 0;
        var best_w := 0;
        var u := 0;
        while u < n
            invariant 0 <= u <= n
            invariant found ==> 0 <= best_u < n && 0 <= best_v < n && visited[best_u] && !visited[best_v] && has_edge(g, best_u, best_v, best_w)
            invariant !found ==> forall u0: int, i0: int :: 0 <= u0 < u && 0 <= i0 < |graph.adj[u0]| && visited[u0] ==> visited[graph.adj[u0][i0].0]
            decreases n - u
        {
            if visited[u] {
                var row := graph.adj[u];
                var i := 0;
                while i < |row|
                    invariant 0 <= i <= |row|
                    invariant found ==> 0 <= best_u < n && 0 <= best_v < n && visited[best_u] && !visited[best_v] && has_edge(g, best_u, best_v, best_w)
                    invariant !found ==> forall u0: int, i0: int :: 0 <= u0 < u && 0 <= i0 < |graph.adj[u0]| && visited[u0] ==> visited[graph.adj[u0][i0].0]
                    invariant !found ==> forall i0: int :: 0 <= i0 < i ==> visited[row[i0].0]
                    decreases |row| - i
                {
                    var v := row[i].0;
                    var w := row[i].1;
                    if !visited[v] {
                        found := true;
                        best_u := u;
                        best_v := v;
                        best_w := w;
                        assert g[u][i].0 == v && g[u][i].1 == w;
                        assert has_edge(g, best_u, best_v, best_w);
                    }
                    i := i + 1;
                }
            }
            u := u + 1;
        }

        if !found {
            var v_unvis := LemmaFindFalse(visited);
            assert nodes_have_path(g, 0, v_unvis);
            var p: seq<int> :| |p| > 0 && p[0] == 0 && p[|p| - 1] == v_unvis && path_follows_graph(g, p);
            LemmaPathStaysVisited(g, visited, p, |p| - 1);
            assert false;
        }

        LemmaExtendSpanningTreeStep(g, visited, tree_edges, best_u, best_v, best_w);
        LemmaCountTruesSetTrue(visited, best_v);
        visited := visited[best_v := true];
        tree_edges := tree_edges + [(best_u, best_v, best_w)];
        LemmaCountTruesBound(visited);
    }

    LemmaCountTruesBound(visited);
    forall u: int, v: int | 0 <= u < n && 0 <= v < n
        ensures edges_connected(tree_edges, u, v)
    {
        assert visited[u] && visited[v];
        LemmaEdgesConnectedTrans(tree_edges, u, 0, v);
    }
    assert is_spanning(g, tree_edges);
}

lemma LemmaCandidateEdgeBounds(g: seq<seq<(int, int)>>, candidate: seq<Edge>, k: int)
    requires are_valid_edges(g, candidate)
    requires forall u: int, i: int :: 0 <= u < |g| && 0 <= i < |g[u]| ==> 0 <= g[u][i].0 < |g|
    requires 0 <= k < |candidate|
    ensures 0 <= candidate[k].0 < |g| && 0 <= candidate[k].1 < |g|
{
    assert has_edge(g, candidate[k].0, candidate[k].1, candidate[k].2);
    var i: int :| 0 <= candidate[k].0 < |g| && 0 <= i < |g[candidate[k].0]| && g[candidate[k].0][i].0 == candidate[k].1;
}

lemma LemmaCandidatePathStaysReached(
    g: seq<seq<(int, int)>>,
    candidate: seq<Edge>,
    reached: seq<bool>,
    p: seq<int>,
    idx: nat
)
    requires |reached| == |g|
    requires are_valid_edges(g, candidate)
    requires forall u0: int, i0: int :: 0 <= u0 < |g| && 0 <= i0 < |g[u0]| ==> 0 <= g[u0][i0].0 < |g|
    requires forall k: int :: 0 <= k < |candidate| ==>
        0 <= candidate[k].0 < |g| && 0 <= candidate[k].1 < |g| &&
        (reached[candidate[k].0] ==> reached[candidate[k].1]) &&
        (reached[candidate[k].1] ==> reached[candidate[k].0])
    requires |p| > 0 && 0 <= p[0] < |g| && reached[p[0]]
    requires path_follows_edges(candidate, p)
    requires idx < |p|
    ensures 0 <= p[idx] < |g| && reached[p[idx]]
    decreases idx
{
    if idx == 0 {
    } else {
        LemmaCandidatePathStaysReached(g, candidate, reached, p, idx - 1);
        assert 0 <= idx - 1 < |p| - 1;
        assert edge_in_set(candidate, p[idx - 1], p[idx]);
        var e_idx: int :| 0 <= e_idx < |candidate| && (
            (candidate[e_idx].0 == p[idx - 1] && candidate[e_idx].1 == p[idx]) ||
            (candidate[e_idx].0 == p[idx] && candidate[e_idx].1 == p[idx - 1])
        );
    }
}

method CheckConnectedFrom(g: ghost seq<seq<(int, int)>>, n: int, candidate: seq<Edge>, start: int) returns (all_reached: bool)
    requires n == |g| && n > 0
    requires 0 <= start < n
    requires are_valid_edges(g, candidate)
    requires forall u0: int, i0: int :: 0 <= u0 < |g| && 0 <= i0 < |g[u0]| ==> 0 <= g[u0][i0].0 < |g|
    ensures all_reached <==> (forall v: int :: 0 <= v < n ==> edges_connected(candidate, start, v))
{
    var reached: seq<bool> := [];
    var idx := 0;
    while idx < n
        invariant 0 <= idx <= n
        invariant |reached| == idx
        invariant forall j: int :: 0 <= j < idx ==> (reached[j] <==> j == start)
        decreases n - idx
    {
        reached := reached + [idx == start];
        idx := idx + 1;
    }
    LemmaEdgesConnectedRefl(candidate, start);
    LemmaCountTruesBound(reached);

    var changed := true;
    while changed
        invariant |reached| == n
        invariant count_trues(reached) <= n
        invariant reached[start]
        invariant forall v: int :: 0 <= v < n && reached[v] ==> edges_connected(candidate, start, v)
        invariant !changed ==> forall k: int :: 0 <= k < |candidate| ==>
            0 <= candidate[k].0 < n && 0 <= candidate[k].1 < n &&
            (reached[candidate[k].0] ==> reached[candidate[k].1]) &&
            (reached[candidate[k].1] ==> reached[candidate[k].0])
        decreases n - count_trues(reached), if changed then 1 else 0
    {
        ghost var old_count := count_trues(reached);
        changed := false;
        var k := 0;
        while k < |candidate|
            invariant 0 <= k <= |candidate|
            invariant |reached| == n
            invariant count_trues(reached) <= n
            invariant reached[start]
            invariant !changed ==> count_trues(reached) == old_count
            invariant changed ==> count_trues(reached) > old_count
            invariant forall v: int :: 0 <= v < n && reached[v] ==> edges_connected(candidate, start, v)
            invariant !changed ==> forall k0: int :: 0 <= k0 < k ==>
                0 <= candidate[k0].0 < n && 0 <= candidate[k0].1 < n &&
                (reached[candidate[k0].0] ==> reached[candidate[k0].1]) &&
                (reached[candidate[k0].1] ==> reached[candidate[k0].0])
            decreases |candidate| - k
        {
            LemmaCandidateEdgeBounds(g, candidate, k);
            var a := candidate[k].0;
            var b := candidate[k].1;
            if reached[a] && !reached[b] {
                assert (candidate[k].0 == a && candidate[k].1 == b) || (candidate[k].0 == b && candidate[k].1 == a);
                assert edge_in_set(candidate, a, b);
                LemmaEdgesConnectedStep(candidate, start, a, b);
                LemmaCountTruesSetTrue(reached, b);
                reached := reached[b := true];
                LemmaCountTruesBound(reached);
                changed := true;
            } else if reached[b] && !reached[a] {
                assert (candidate[k].0 == b && candidate[k].1 == a) || (candidate[k].0 == a && candidate[k].1 == b);
                assert edge_in_set(candidate, b, a);
                LemmaEdgesConnectedStep(candidate, start, b, a);
                LemmaCountTruesSetTrue(reached, a);
                reached := reached[a := true];
                LemmaCountTruesBound(reached);
                changed := true;
            }
            k := k + 1;
        }
    }

    forall v: int | 0 <= v < n
        ensures reached[v] <==> edges_connected(candidate, start, v)
    {
        if edges_connected(candidate, start, v) {
            var p: seq<int> :| |p| > 0 && p[0] == start && p[|p| - 1] == v && path_follows_edges(candidate, p);
            LemmaCandidatePathStaysReached(g, candidate, reached, p, |p| - 1);
        }
    }

    all_reached := true;
    var v := 0;
    while v < n
        invariant 0 <= v <= n
        invariant all_reached <==> (forall v0: int :: 0 <= v0 < v ==> reached[v0])
        decreases n - v
    {
        if !reached[v] {
            all_reached := false;
        }
        v := v + 1;
    }
}

method CheckIsSpanning(g: ghost seq<seq<(int, int)>>, n: int, candidate: seq<Edge>) returns (res: bool)
    requires n == |g| && n > 0
    requires are_valid_edges(g, candidate)
    requires forall u0: int, i0: int :: 0 <= u0 < |g| && 0 <= i0 < |g[u0]| ==> 0 <= g[u0][i0].0 < |g|
    ensures res <==> is_spanning(g, candidate)
{
    res := true;
    var u := 0;
    while u < n
        invariant 0 <= u <= n
        invariant res <==> (forall u0: int, v0: int :: 0 <= u0 < u && 0 <= v0 < n ==> edges_connected(candidate, u0, v0))
        decreases n - u
    {
        var ok := CheckConnectedFrom(g, n, candidate, u);
        if !ok {
            res := false;
        }
        u := u + 1;
    }
}

function TotalWeightExec(edges: seq<Edge>): int
    decreases |edges|
    ensures TotalWeightExec(edges) == total_weight(edges)
{
    if |edges| == 0 then 0
    else edges[0].2 + TotalWeightExec(edges[1..])
}

function RowEdges(u: int, row: seq<(int, int)>, start_i: nat): seq<Edge>
    requires start_i <= |row|
    decreases |row| - start_i
{
    if start_i == |row| then []
    else [(u, row[start_i].0, row[start_i].1)] + RowEdges(u, row, start_i + 1)
}

lemma LemmaRowEdgesValid(g: seq<seq<(int, int)>>, u: int, start_i: nat)
    requires 0 <= u < |g|
    requires start_i <= |g[u]|
    ensures forall e: Edge :: e in RowEdges(u, g[u], start_i) ==> has_edge(g, e.0, e.1, e.2)
    decreases |g[u]| - start_i
{
    if start_i == |g[u]| {
    } else {
        LemmaRowEdgesValid(g, u, start_i + 1);
        var head: Edge := (u, g[u][start_i].0, g[u][start_i].1);
        assert g[u][start_i].0 == head.1 && g[u][start_i].1 == head.2;
        assert has_edge(g, head.0, head.1, head.2);
    }
}

lemma LemmaRowEdgesComplete(u: int, row: seq<(int, int)>, start_i: nat, i: int)
    requires start_i <= i < |row|
    ensures (u, row[i].0, row[i].1) in RowEdges(u, row, start_i)
    decreases i - start_i
{
    if start_i == i {
    } else {
        LemmaRowEdgesComplete(u, row, start_i + 1, i);
    }
}

function AllGraphEdges(g: seq<seq<(int, int)>>, start_u: nat): seq<Edge>
    requires start_u <= |g|
    decreases |g| - start_u
{
    if start_u == |g| then []
    else RowEdges(start_u, g[start_u], 0) + AllGraphEdges(g, start_u + 1)
}

lemma LemmaAllGraphEdgesValid(g: seq<seq<(int, int)>>, start_u: nat)
    requires start_u <= |g|
    ensures forall e: Edge :: e in AllGraphEdges(g, start_u) ==> has_edge(g, e.0, e.1, e.2)
    decreases |g| - start_u
{
    if start_u == |g| {
    } else {
        LemmaRowEdgesValid(g, start_u, 0);
        LemmaAllGraphEdgesValid(g, start_u + 1);
    }
}

lemma LemmaAllGraphEdgesComplete(g: seq<seq<(int, int)>>, start_u: nat, u: int, v: int, w: int)
    requires start_u <= u < |g|
    requires has_edge(g, u, v, w)
    ensures (u, v, w) in AllGraphEdges(g, start_u)
    decreases u - start_u
{
    if start_u == u {
        var i: int :| 0 <= i < |g[u]| && g[u][i].0 == v && g[u][i].1 == w;
        LemmaRowEdgesComplete(u, g[u], 0, i);
    } else {
        LemmaAllGraphEdgesComplete(g, start_u + 1, u, v, w);
    }
}

function PrependToAll(e: Edge, seqs: seq<seq<Edge>>): seq<seq<Edge>>
    decreases |seqs|
{
    if |seqs| == 0 then []
    else [[e] + seqs[0]] + PrependToAll(e, seqs[1..])
}

lemma LemmaPrependToAllValid(g: seq<seq<(int, int)>>, e: Edge, seqs: seq<seq<Edge>>, m: nat)
    requires m > 0
    requires has_edge(g, e.0, e.1, e.2)
    requires forall s: seq<Edge> :: s in seqs ==> |s| == m - 1 && are_valid_edges(g, s)
    ensures forall t: seq<Edge> :: t in PrependToAll(e, seqs) ==> |t| == m && are_valid_edges(g, t)
    decreases |seqs|
{
    if |seqs| == 0 {
    } else {
        LemmaPrependToAllValid(g, e, seqs[1..], m);
        var head := [e] + seqs[0];
        assert seqs[0] in seqs;
        forall k: int | 0 <= k < |head|
            ensures has_edge(g, head[k].0, head[k].1, head[k].2)
        {
            if k == 0 {
                assert head[0] == e;
            } else {
                assert head[k] == seqs[0][k - 1];
            }
        }
        assert are_valid_edges(g, head);
    }
}

lemma LemmaPrependToAllComplete(e: Edge, seqs: seq<seq<Edge>>, s: seq<Edge>)
    requires s in seqs
    ensures ([e] + s) in PrependToAll(e, seqs)
    decreases |seqs|
{
    if s == seqs[0] {
    } else {
        assert s in seqs[1..];
        LemmaPrependToAllComplete(e, seqs[1..], s);
    }
}

function AllTuplesFromIndex(pool: seq<Edge>, start_idx: nat, sub_tuples: seq<seq<Edge>>): seq<seq<Edge>>
    requires start_idx <= |pool|
    decreases |pool| - start_idx
{
    if start_idx == |pool| then []
    else PrependToAll(pool[start_idx], sub_tuples) + AllTuplesFromIndex(pool, start_idx + 1, sub_tuples)
}

lemma LemmaAllTuplesFromIndexValid(
    g: seq<seq<(int, int)>>,
    pool: seq<Edge>,
    start_idx: nat,
    sub_tuples: seq<seq<Edge>>,
    m: nat
)
    requires m > 0
    requires start_idx <= |pool|
    requires forall e: Edge :: e in pool ==> has_edge(g, e.0, e.1, e.2)
    requires forall s: seq<Edge> :: s in sub_tuples ==> |s| == m - 1 && are_valid_edges(g, s)
    ensures forall t: seq<Edge> :: t in AllTuplesFromIndex(pool, start_idx, sub_tuples) ==> |t| == m && are_valid_edges(g, t)
    decreases |pool| - start_idx
{
    if start_idx == |pool| {
    } else {
        assert pool[start_idx] in pool;
        LemmaPrependToAllValid(g, pool[start_idx], sub_tuples, m);
        LemmaAllTuplesFromIndexValid(g, pool, start_idx + 1, sub_tuples, m);
    }
}

lemma LemmaAllTuplesFromIndexComplete(
    pool: seq<Edge>,
    start_idx: nat,
    sub_tuples: seq<seq<Edge>>,
    idx: int,
    s: seq<Edge>
)
    requires start_idx <= idx < |pool|
    requires s in sub_tuples
    ensures ([pool[idx]] + s) in AllTuplesFromIndex(pool, start_idx, sub_tuples)
    decreases idx - start_idx
{
    if start_idx == idx {
        LemmaPrependToAllComplete(pool[start_idx], sub_tuples, s);
    } else {
        LemmaAllTuplesFromIndexComplete(pool, start_idx + 1, sub_tuples, idx, s);
    }
}

function AllTuples(pool: seq<Edge>, m: nat): seq<seq<Edge>>
    decreases m
{
    if m == 0 then [[]]
    else AllTuplesFromIndex(pool, 0, AllTuples(pool, m - 1))
}

lemma LemmaAllTuplesValid(g: seq<seq<(int, int)>>, pool: seq<Edge>, m: nat)
    requires forall e: Edge :: e in pool ==> has_edge(g, e.0, e.1, e.2)
    ensures forall t: seq<Edge> :: t in AllTuples(pool, m) ==> |t| == m && are_valid_edges(g, t)
    decreases m
{
    if m == 0 {
        var empty: seq<Edge> := [];
        assert are_valid_edges(g, empty);
    } else {
        LemmaAllTuplesValid(g, pool, m - 1);
        LemmaAllTuplesFromIndexValid(g, pool, 0, AllTuples(pool, m - 1), m);
    }
}

lemma LemmaAllTuplesComplete(pool: seq<Edge>, m: nat, other: seq<Edge>)
    requires |other| == m
    requires forall k: int :: 0 <= k < |other| ==> other[k] in pool
    ensures other in AllTuples(pool, m)
    decreases m
{
    if m == 0 {
        assert other == [];
    } else {
        var head := other[0];
        var tail := other[1..];
        forall k: int | 0 <= k < |tail|
            ensures tail[k] in pool
        {
            assert tail[k] == other[k + 1];
        }
        LemmaAllTuplesComplete(pool, m - 1, tail);
        assert head == other[0];
        assert head in pool;
        var idx: int :| 0 <= idx < |pool| && pool[idx] == head;
        LemmaAllTuplesFromIndexComplete(pool, 0, AllTuples(pool, m - 1), idx, tail);
        assert [head] + tail == other;
    }
}

method kruskal_mst(graph: WeightedGraph) returns (edges: seq<Edge>)
    requires well_formed(graph)
    requires size(graph) > 0
    requires weights_bounded(view(graph))
    requires graph_is_connected(view(graph))
    ensures is_mst(view(graph), edges)
{
    ghost var g := view(graph);
    var n := |graph.adj|;
    var t0 := BuildSpanningTree(graph);
    var pool := AllGraphEdges(graph.adj, 0);
    LemmaAllGraphEdgesValid(g, 0);
    var candidates := AllTuples(pool, n - 1);
    LemmaAllTuplesValid(g, pool, n - 1);

    edges := t0;
    var best_weight := TotalWeightExec(edges);
    var idx := 0;
    while idx < |candidates|
        invariant 0 <= idx <= |candidates|
        invariant is_spanning_tree(g, edges)
        invariant best_weight == total_weight(edges)
        invariant forall j: int :: 0 <= j < idx && is_spanning_tree(g, candidates[j]) ==>
            total_weight(edges) <= total_weight(candidates[j])
        decreases |candidates| - idx
    {
        var cand := candidates[idx];
        assert cand in candidates;
        assert |cand| == n - 1 && are_valid_edges(g, cand);
        var spanning := CheckIsSpanning(g, n, cand);
        if spanning {
            assert is_spanning_tree(g, cand);
            var w := TotalWeightExec(cand);
            if w < best_weight {
                edges := cand;
                best_weight := w;
            }
        }
        idx := idx + 1;
    }

    forall other: seq<Edge> {:trigger is_spanning_tree(g, other)} | is_spanning_tree(g, other)
        ensures total_weight(edges) <= total_weight(other)
    {
        forall k: int | 0 <= k < |other|
            ensures other[k] in pool
        {
            assert has_edge(g, other[k].0, other[k].1, other[k].2);
            var i: int :| 0 <= other[k].0 < |g| && 0 <= i < |g[other[k].0]| && g[other[k].0][i].0 == other[k].1 && g[other[k].0][i].1 == other[k].2;
            LemmaAllGraphEdgesComplete(g, 0, other[k].0, other[k].1, other[k].2);
            assert (other[k].0, other[k].1, other[k].2) == other[k];
        }
        LemmaAllTuplesComplete(pool, n - 1, other);
        assert other in candidates;
        var j: int :| 0 <= j < |candidates| && candidates[j] == other;
    }
}
