method lca(t: Tree, p: int, q: int) returns (a: int)
  requires contains(t, p) && contains(t, q) && tree_distinct(t)
  ensures contains(t, a)
  ensures is_common_ancestor(t, a, p, q)
  ensures forall x: int :: is_common_ancestor(t, x, p, q) ==>
    spec_get_depth(t, x).Some? && spec_get_depth(t, a).Some? &&
    spec_get_depth(t, x).get <= spec_get_depth(t, a).get
  decreases t
{
  match t {
    case Nil =>
      assert false;
      a := 0;
    case Node(v, l, r) =>
      if v == p || v == q {
        a := v;
        assert spec_get_subtree(t, v) == t;
        forall x: int | is_common_ancestor(t, x, p, q)
          ensures spec_get_depth(t, x).Some? && spec_get_depth(t, a).Some? &&
                  spec_get_depth(t, x).get <= spec_get_depth(t, a).get
        {
          SubtreeProps(t, x);
          if x != v {
            NonRootAncestor(t, x, p, q);
            assert false;
          }
        }
      } else if has(l, p) && has(l, q) {
        a := lca(l, p, q);
        SubtreeProps(l, a);
        assert a != v;
        assert spec_get_subtree(t, a) == spec_get_subtree(l, a);
        assert spec_get_depth(t, a) == Some(spec_get_depth(l, a).get + 1);
        forall x: int | is_common_ancestor(t, x, p, q)
          ensures spec_get_depth(t, x).Some? && spec_get_depth(t, a).Some? &&
                  spec_get_depth(t, x).get <= spec_get_depth(t, a).get
        {
          SubtreeProps(t, x);
          if x != v {
            NonRootAncestor(t, x, p, q);
            if contains(l, p) && contains(l, q) && is_common_ancestor(l, x, p, q) {
              SubtreeProps(l, x);
              assert spec_get_depth(t, x) == Some(spec_get_depth(l, x).get + 1);
            } else {
              ContainsView(l, p);
              ContainsView(r, p);
              assert p in view(l) * view(r);
              assert false;
            }
          }
        }
      } else if has(r, p) && has(r, q) {
        a := lca(r, p, q);
        SubtreeProps(r, a);
        SubtreeProps(l, a);
        ContainsView(l, a);
        ContainsView(r, a);
        assert !contains(l, a) by {
          if contains(l, a) {
            assert a in view(l) * view(r);
          }
        }
        assert a != v;
        assert spec_get_subtree(t, a) == spec_get_subtree(r, a);
        assert spec_get_depth(t, a) == Some(spec_get_depth(r, a).get + 1);
        forall x: int | is_common_ancestor(t, x, p, q)
          ensures spec_get_depth(t, x).Some? && spec_get_depth(t, a).Some? &&
                  spec_get_depth(t, x).get <= spec_get_depth(t, a).get
        {
          SubtreeProps(t, x);
          if x != v {
            NonRootAncestor(t, x, p, q);
            if contains(r, p) && contains(r, q) && is_common_ancestor(r, x, p, q) {
