              ContainsView(l, x);
              ContainsView(r, x);
              assert !contains(l, x) by {
                if contains(l, x) {
                  assert x in view(l) * view(r);
                }
              }
              assert spec_get_depth(t, x) == Some(spec_get_depth(r, x).get + 1);
            } else {
              assert contains(l, p) && contains(l, q);
              assert false;
            }
          }
        }
      } else {
        a := v;
        assert spec_get_subtree(t, v) == t;
        forall x: int | is_common_ancestor(t, x, p, q)
          ensures spec_get_depth(t, x).Some? && spec_get_depth(t, a).Some? &&
                  spec_get_depth(t, x).get <= spec_get_depth(t, a).get
        {
          SubtreeProps(t, x);
          if x != v {
            NonRootAncestor(t, x, p, q);
            assert false;
          }
        }
      }
  }
}

