lemma JoinPaths(
    es: seq<Edge>, p: seq<int>, q: seq<int>)
  requires |p| > 0
  requires |q| > 0
  requires p[|p| - 1] == q[0]
  requires path_follows_edges(es, p)
  requires path_follows_edges(es, q)
  ensures |p + q[1..]| > 0
  ensures (p + q[1..])[0] == p[0]
  ensures (p + q[1..])[|p + q[1..]| - 1] == q[|q| - 1]
  ensures path_follows_edges(es, p + q[1..])
{
  var r := p + q[1..];

  forall k | 0 <= k < |r| - 1
    ensures edge_in_set(es, r[k], r[k + 1])
  {
    if k < |p| - 1 {
      assert r[k] == p[k];
      assert r[k + 1] == p[k + 1];
    } else if k == |p| - 1 {
      assert |q| > 1;
      assert r[k] == p[|p| - 1];
      assert r[k] == q[0];
      assert r[k + 1] == q[1];
    } else {
      var j := k - |p| + 1;
      assert 1 <= j < |q| - 1;
      assert r[k] == q[j];
      assert r[k + 1] == q[j + 1];
    }
  }

  if |q| == 1 {
    assert q[1..] == [];
    assert r == p;
    assert r[|r| - 1] == q[0];
  } else {
    assert r[|r| - 1] == q[|q| - 1];
