  ensures (p + q[1..])[0] == p[0]
  ensures (p + q[1..])[|p + q[1..]| - 1] == q[|q| - 1]
  ensures path_follows_edges(es, p + q[1..])
{
  var r := p + q[1..];

  forall k | 0 <= k < |r| - 1
    ensures edge_in_set(es, r[k], r[k + 1])
  {
    if k < |p| - 1 {
      assert r[k] == p[k];
      assert r[k + 1] == p[k + 1];
    } else if k == |p| - 1 {
      assert |q| > 1;
      assert r[k] == p[|p| - 1];
      assert r[k] == q[0];
      assert r[k + 1] == q[1];
    } else {
      var j := k - |p| + 1;
      assert 1 <= j < |q| - 1;
      assert r[k] == q[j];
      assert r[k + 1] == q[j + 1];
    }
  }

  if |q| == 1 {
    assert q[1..] == [];
    assert r == p;
    assert r[|r| - 1] == q[0];
  } else {
    assert r[|r| - 1] == q[|q| - 1];
  }
}

lemma ConnectedTransitive(
    es: seq<Edge>, u: int, m: int, v: int)
  requires edges_connected(es, u, m)
  requires edges_connected(es, m, v)
  ensures edges_connected(es, u, v)
{
  var p :| |p| > 0 &&
             p[0] == u &&
             p[|p| - 1] == m &&
             path_follows_edges(es, p);
  var q :| |q| > 0 &&
             q[0] == m &&
             q[|q| - 1] == v &&
             path_follows_edges(es, q);

  JoinPaths(es, p, q);
  var r := p + q[1..];
  assert r[0] == u;
  assert r[|r| - 1] == v;
}

lemma RootConnectivityImpliesSpanning(
    g: seq<seq<(int, int)>>,
    es: seq<Edge>,
    root: int)
  requires 0 <= root < |g|
  requires forall v: int ::
    0 <= v < |g| ==> edges_connected(es, root, v)
  ensures is_spanning(g, es)
{
  forall u: int, v: int |
      0 <= u < |g| && 0 <= v < |g|
    ensures edges_connected(es, u, v)
  {
    ConnectedSymmetry(es, root, u);
    ConnectedTransitive(es, u, root, v);
  }
}

lemma FindCrossingEdge(
    g: seq<seq<(int, int)>>,
    reached: set<int>,
    p: seq<int>)
    returns (u: int, v: int, w: int)
  requires vertices_well_formed(g)
  requires |p| > 0
  requires path_follows_graph(g, p)
  requires p[0] in reached
  requires p[|p| - 1] !in reached
  ensures u in reached
  ensures v !in reached
  ensures 0 <= u < |g|
  ensures 0 <= v < |g|
  ensures has_edge(g, u, v, w)
{
  assert |p| > 1;
  var j := 1;

  while p[j] in reached
    invariant 1 <= j < |p|
    invariant p[j - 1] in reached
    decreases |p| - j
  {
    assert j < |p| - 1;
    j := j + 1;
  }

  u := p[j - 1];
  v := p[j];

  assert graph_has_any_edge(g, u, v);
  var i :| 0 <= u < |g| &&
             0 <= i < |g[u]| &&
             g[u][i].0 == v;
  w := g[u][i].1;

  assert has_edge(g, u, v, w);
  assert 0 <= v < |g|;
}

lemma ValidityAfterAppend(
    g: seq<seq<(int, int)>>,
    es: seq<Edge>,
    u: int,
    v: int,
    w: int)
  requires are_valid_edges(g, es)
  requires has_edge(g, u, v, w)
  ensures are_valid_edges(g, es + [(u, v, w)])
{
  forall k | 0 <= k < |es + [(u, v, w)]|
    ensures has_edge(
      g,
      (es + [(u, v, w)])[k].0,
      (es + [(u, v, w)])[k].1,
      (es + [(u, v, w)])[k].2)
  {
    if k < |es| {
      assert (es + [(u, v, w)])[k] == es[k];
    } else {
      assert k == |es|;
      assert (es + [(u, v, w)])[k] == (u, v, w);
    }
  }
}

lemma SpanningTreeExists(g: seq<seq<(int, int)>>)
  requires |g| > 0
  requires vertices_well_formed(g)
  requires graph_is_connected(g)
  ensures exists es: seq<Edge> :: is_spanning_tree(g, es)
{
  NodesFacts(|g|);

  var reached: set<int> := {0};
  var tree: seq<Edge> := [];

  ConnectedReflexive(tree, 0);

  while |reached| < |g|
    invariant reached <= Nodes(|g|)
    invariant 0 in reached
    invariant |reached| > 0
    invariant |reached| <= |g|
    invariant |tree| == |reached| - 1
    invariant are_valid_edges(g, tree)
    invariant forall r: int ::
      r in reached ==> edges_connected(tree, 0, r)
    decreases |g| - |reached|
  {
    assert reached != Nodes(|g|);
    assert exists x: int :: x in Nodes(|g|) && x !in reached by {
      if !(exists x: int :: x in Nodes(|g|) && x !in reached) {
        assert forall x: int :: x in Nodes(|g|) ==> x in reached;
        assert Nodes(|g|) <= reached;
        assert reached == Nodes(|g|);
      }
    }

    var target :| target in Nodes(|g|) && target !in reached;
    assert 0 <= target < |g|;

    assert nodes_have_path(g, 0, target);
    var p :| |p| > 0 &&
               p[0] == 0 &&
               p[|p| - 1] == target &&
               path_follows_graph(g, p);

    var u, v, w := FindCrossingEdge(g, reached, p);
    var oldTree := tree;
    var oldReached := reached;

    assert edges_connected(oldTree, 0, u);
    ExtendPathByEdge(oldTree, u, v, w, 0);
    ValidityAfterAppend(g, oldTree, u, v, w);

    tree := oldTree + [(u, v, w)];
    reached := oldReached + {v};

    assert v !in oldReached;
    assert |reached| == |oldReached| + 1;
    assert |tree| == |oldTree| + 1;

    forall r | r in reached
      ensures edges_connected(tree, 0, r)
    {
      if r == v {
        assert edges_connected(tree, 0, v);
      } else {
        assert r in oldReached;
        assert edges_connected(oldTree, 0, r);
        ConnectedPreservedByAppend(oldTree, (u, v, w), 0, r);
      }
    }

    assert v in Nodes(|g|);
    assert reached <= Nodes(|g|);
  }

  assert |reached| == |g|;
  assert reached == Nodes(|g|) by {
    if reached != Nodes(|g|) {
      assert reached < Nodes(|g|);
      assert |reached| < |Nodes(|g|)|;
    }
  }

  forall r | 0 <= r < |g|
    ensures edges_connected(tree, 0, r)
  {
    assert r in Nodes(|g|);
    assert r in reached;
  }

  RootConnectivityImpliesSpanning(g, tree, 0);
  assert |tree| == |g| - 1;
  assert is_spanning_tree(g, tree);
}

lemma ValidEdgesWeightBounds(
    g: seq<seq<(int, int)>>,
    es: seq<Edge>)
  requires weights_bounded(g)
  requires are_valid_edges(g, es)
  ensures -100_000 * |es| <= total_weight(es)
  ensures total_weight(es) <= 100_000 * |es|
  decreases |es|
{
  if |es| != 0 {
    assert has_edge(g, es[0].0, es[0].1, es[0].2);
    assert -100_000 <= es[0].2 <= 100_000;

    assert are_valid_edges(g, es[1..]) by {
      forall k | 0 <= k < |es[1..]|
        ensures has_edge(
          g,
          es[1..][k].0,
          es[1..][k].1,
          es[1..][k].2)
      {
        assert es[1..][k] == es[k + 1];
      }
    }

    ValidEdgesWeightBounds(g, es[1..]);
    assert |es[1..]| == |es| - 1;
  }
}

ghost method FindMinimumTree(
