lemma CommonAtNode(
    v: int, l: Tree, r: Tree, ancestor: int, p: int, q: int)
    requires tree_distinct(Node(v, l, r))
    ensures is_common_ancestor(Node(v, l, r), ancestor, p, q) <==>
            (ancestor == v &&
             contains(Node(v, l, r), p) &&
             contains(Node(v, l, r), q)) ||
            is_common_ancestor(l, ancestor, p, q) ||
            is_common_ancestor(r, ancestor, p, q)
{
    SubtreeCharacterization(Node(v, l, r), ancestor);
    SubtreeCharacterization(l, ancestor);
    SubtreeCharacterization(r, ancestor);
    DistinctSides(v, l, r, ancestor);

    assert !contains(l, v);
    assert !contains(r, v);

    if ancestor == v {
        assert !contains(l, ancestor);
        assert !contains(r, ancestor);
        assert spec_get_subtree(l, ancestor).Nil?;
        assert spec_get_subtree(r, ancestor).Nil?;
        assert spec_get_subtree(Node(v, l, r), ancestor) ==
               Node(v, l, r);
        assert is_common_ancestor(Node(v, l, r), ancestor, p, q) <==>
               contains(Node(v, l, r), p) &&
               contains(Node(v, l, r), q);
        assert !is_common_ancestor(l, ancestor, p, q);
        assert !is_common_ancestor(r, ancestor, p, q);
    } else if contains(l, ancestor) {
        assert !contains(r, ancestor);
        SubtreeFromLeft(v, l, r, ancestor);
        assert spec_get_subtree(r, ancestor).Nil?;
        assert is_common_ancestor(Node(v, l, r), ancestor, p, q) <==>
               is_common_ancestor(l, ancestor, p, q);
        assert !is_common_ancestor(r, ancestor, p, q);
    } else if contains(r, ancestor) {
        assert !contains(l, ancestor);
        SubtreeFromRight(v, l, r, ancestor);
        assert spec_get_subtree(l, ancestor).Nil?;
        assert is_common_ancestor(Node(v, l, r), ancestor, p, q) <==>
               is_common_ancestor(r, ancestor, p, q);
        assert !is_common_ancestor(l, ancestor, p, q);
    } else {
        assert !contains(Node(v, l, r), ancestor);
        assert spec_get_subtree(Node(v, l, r), ancestor).Nil?;
        assert spec_get_subtree(l, ancestor).Nil?;
        assert spec_get_subtree(r, ancestor).Nil?;
        assert !is_common_ancestor(Node(v, l, r), ancestor, p, q);
        assert !is_common_ancestor(l, ancestor, p, q);
        assert !is_common_ancestor(r, ancestor, p, q);
    }
}

lemma RootIsOptimal(
    v: int, l: Tree, r: Tree, p: int, q: int)
    requires tree_distinct(Node(v, l, r))
    requires contains(Node(v, l, r), p)
    requires contains(Node(v, l, r), q)
    requires !(contains(l, p) && contains(l, q))
    requires !(contains(r, p) && contains(r, q))
    ensures is_common_ancestor(Node(v, l, r), v, p, q)
    ensures forall x: int ::
        is_common_ancestor(Node(v, l, r), x, p, q) ==>
        spec_get_depth(Node(v, l, r), x).Some? &&
        spec_get_depth(Node(v, l, r), v).Some? &&
        spec_get_depth(Node(v, l, r), x).get <=
        spec_get_depth(Node(v, l, r), v).get
{
    CommonAtNode(v, l, r, v, p, q);
    assert is_common_ancestor(Node(v, l, r), v, p, q);
    assert spec_get_depth(Node(v, l, r), v) == Some(0);

    forall x: int |
        is_common_ancestor(Node(v, l, r), x, p, q)
        ensures spec_get_depth(Node(v, l, r), x).Some? &&
                spec_get_depth(Node(v, l, r), v).Some? &&
                spec_get_depth(Node(v, l, r), x).get <=
                spec_get_depth(Node(v, l, r), v).get
    {
        CommonAtNode(v, l, r, x, p, q);

        if x != v {
            if is_common_ancestor(l, x, p, q) {
                CommonAncestorContained(l, x, p, q);
                assert contains(l, p) && contains(l, q);
                assert false;
            } else if is_common_ancestor(r, x, p, q) {
                CommonAncestorContained(r, x, p, q);
                assert contains(r, p) && contains(r, q);
                assert false;
            } else {
                assert false;
            }
        }

        assert x == v;
        assert spec_get_depth(Node(v, l, r), x) == Some(0);
    }
}

lemma LiftOptimalFromLeft(
    v: int, l: Tree, r: Tree, ancestor: int, p: int, q: int)
    requires tree_distinct(Node(v, l, r))
    requires contains(l, p)
    requires contains(l, q)
    requires is_common_ancestor(l, ancestor, p, q)
    requires forall x: int :: is_common_ancestor(l, x, p, q) ==>
        spec_get_depth(l, x).Some? &&
        spec_get_depth(l, ancestor).Some? &&
        spec_get_depth(l, x).get <= spec_get_depth(l, ancestor).get
    ensures is_common_ancestor(Node(v, l, r), ancestor, p, q)
    ensures forall x: int ::
        is_common_ancestor(Node(v, l, r), x, p, q) ==>
        spec_get_depth(Node(v, l, r), x).Some? &&
        spec_get_depth(Node(v, l, r), ancestor).Some? &&
        spec_get_depth(Node(v, l, r), x).get <=
        spec_get_depth(Node(v, l, r), ancestor).get
{
    DistinctSides(v, l, r, p);
    assert !contains(r, p);

    CommonAtNode(v, l, r, ancestor, p, q);
    assert is_common_ancestor(Node(v, l, r), ancestor, p, q);

    CommonAncestorPresent(l, ancestor, p, q);
    assert contains(l, ancestor);
    assert ancestor != v;
    DepthCharacterization(l, ancestor);
    assert spec_get_depth(l, ancestor).Some?;
    DepthFromLeft(v, l, r, ancestor);

    forall x: int |
        is_common_ancestor(Node(v, l, r), x, p, q)
        ensures spec_get_depth(Node(v, l, r), x).Some? &&
                spec_get_depth(Node(v, l, r), ancestor).Some? &&
                spec_get_depth(Node(v, l, r), x).get <=
                spec_get_depth(Node(v, l, r), ancestor).get
    {
        CommonAtNode(v, l, r, x, p, q);
        CommonAncestorPresent(Node(v, l, r), x, p, q);
        DepthCharacterization(Node(v, l, r), x);
        assert spec_get_depth(Node(v, l, r), x).Some?;

        if x == v {
            DepthNonnegative(l, ancestor);
            assert spec_get_depth(Node(v, l, r), x).get == 0;
            assert spec_get_depth(Node(v, l, r), ancestor).get ==
                   spec_get_depth(l, ancestor).get + 1;
        } else if is_common_ancestor(l, x, p, q) {
            CommonAncestorPresent(l, x, p, q);
            assert contains(l, x);
            assert x != v;
            DepthCharacterization(l, x);
            assert spec_get_depth(l, x).Some?;
            DepthFromLeft(v, l, r, x);

            assert spec_get_depth(l, ancestor).Some?;
            assert spec_get_depth(l, x).get <=
                   spec_get_depth(l, ancestor).get;
        } else {
            assert is_common_ancestor(r, x, p, q);
            CommonAncestorContained(r, x, p, q);
            assert contains(r, p);
            assert false;
        }
    }
}

lemma LiftOptimalFromRight(
