method lowest_common_ancestor(root: Tree, p: int, q: int)
    returns (res: Option<int>)
    requires p >= 0
    requires q >= 0
    requires contains(root, p)
    requires contains(root, q)
    requires tree_distinct(root)
    ensures res.Some?
    ensures is_common_ancestor(root, res.get, p, q)
    ensures forall x: int :: is_common_ancestor(root, x, p, q) ==>
        spec_get_depth(root, x).Some? &&
        spec_get_depth(root, res.get).Some? &&
        spec_get_depth(root, x).get <= spec_get_depth(root, res.get).get
    decreases root
{
    match root
    case Nil =>
        assert !contains(root, p);
        assert false;
        res := None;

    case Node(v, l, r) =>
        HasAgreesWithContains(l, p);
        HasAgreesWithContains(l, q);
        HasAgreesWithContains(r, p);
        HasAgreesWithContains(r, q);

        var lp := has(l, p);
        var lq := has(l, q);

        assert lp == contains(l, p);
        assert lq == contains(l, q);
        assert tree_distinct(l);
        assert tree_distinct(r);
        assert !contains(l, v);
        assert !contains(r, v);

        if v == p || v == q {
            if v == p {
                assert !contains(l, p);
                assert !contains(r, p);
            } else {
                assert v == q;
                assert !contains(l, q);
                assert !contains(r, q);
            }

            assert !(contains(l, p) && contains(l, q));
            assert !(contains(r, p) && contains(r, q));

            RootIsOptimal(v, l, r, p, q);
            res := Some(v);
        } else {
            assert v != p;
            assert v != q;
            assert contains(l, p) || contains(r, p);
            assert contains(l, q) || contains(r, q);

            DistinctSides(v, l, r, p);
            DistinctSides(v, l, r, q);

            if lp && lq {
                assert contains(l, p);
                assert contains(l, q);

                var sub := lowest_common_ancestor(l, p, q);
                assert sub.Some?;

                LiftOptimalFromLeft(v, l, r, sub.get, p, q);
                res := sub;
            } else if !lp && !lq {
                assert !contains(l, p);
                assert !contains(l, q);
                assert contains(r, p);
                assert contains(r, q);

                var sub := lowest_common_ancestor(r, p, q);
                assert sub.Some?;

                LiftOptimalFromRight(v, l, r, sub.get, p, q);
                res := sub;
            } else {
                assert !(contains(l, p) && contains(l, q));

                if lp {
                    assert contains(l, p);
                    assert !contains(r, p);
                } else {
                    assert contains(l, q);
                    assert !contains(r, q);
                }

                assert !(contains(r, p) && contains(r, q));
                RootIsOptimal(v, l, r, p, q);
                res := Some(v);
            }
        }
}
