method linear_search_lower_bound(s: seq<int>, target: int) returns (result: int)
    requires |s| <= 0x7FFFFFFF
    requires is_sorted(s)
    ensures result >= 0
    ensures result <= |s|
    ensures forall i {:trigger s[i]} :: 0 <= i < result ==> s[i] < target
    ensures forall i {:trigger s[i]} :: result <= i < |s| ==> s[i] >= target
{
    var i := 0;
    while i < |s| && s[i] < target
        invariant 0 <= i <= |s|
        invariant forall k {:trigger s[k]} :: 0 <= k < i ==> s[k] < target
        decreases |s| - i
    {
        i := i + 1;
    }
    if i < |s| {
        assert s[i] >= target;
        forall k | i <= k < |s|
            ensures s[k] >= target
        {
            assert s[i] <= s[k];
        }
    }
    result := i;
}

