method Search(matrix: seq<seq<int>>, b: seq<int>, prefix: seq<int>, n: int) returns (res: Option<seq<int>>)
    requires |prefix| <= n
    ensures res.Some? ==> is_solution(matrix, b, res.value)
    ensures res.None? ==>
        forall x: seq<int> ::
            (|x| == n && is_binary_vector(x) && x[..|prefix|] == prefix)
            ==> !is_solution(matrix, b, x)
    decreases n - |prefix|
{
    if |prefix| == n {
        if is_solution(matrix, b, prefix) {
            res := Some(prefix);
        } else {
            res := None;
            forall x: seq<int> | |x| == n && is_binary_vector(x) && x[..|prefix|] == prefix
                ensures !is_solution(matrix, b, x)
            {
                assert x == x[..n];
            }
        }
        return;
    }
    var r0 := Search(matrix, b, prefix + [0], n);
    if r0.Some? {
        res := r0;
        return;
    }
    var r1 := Search(matrix, b, prefix + [1], n);
    if r1.Some? {
        res := r1;
        return;
    }
    res := None;
    forall x: seq<int> | |x| == n && is_binary_vector(x) && x[..|prefix|] == prefix
        ensures !is_solution(matrix, b, x)
    {
        var k := |prefix|;
        assert x[..k+1] == x[..k] + [x[k]];
        if x[k] == 0 {
            assert x[..k+1] == prefix + [0];
            assert x[..|prefix + [0]|] == prefix + [0];
        } else {
            assert x[k] == 1;
            assert x[..k+1] == prefix + [1];
            assert x[..|prefix + [1]|] == prefix + [1];
        }
    }
}

