  requires graph_is_connected(g)
  ensures exists es: seq<Edge> :: is_mst(g, es)
{
  SpanningTreeExists(g);
  var candidate :| is_spanning_tree(g, candidate);

  var lower := -100_000 * (|g| - 1);

  ValidEdgesWeightBounds(g, candidate);
  assert |candidate| == |g| - 1;
  assert lower <= total_weight(candidate);

  forall t | is_spanning_tree(g, t)
    ensures lower <= total_weight(t)
  {
    ValidEdgesWeightBounds(g, t);
    assert |t| == |g| - 1;
  }

  var best := FindMinimumTree(g, candidate, lower);
  assert is_spanning_tree(g, best);
  assert forall other: seq<Edge> ::
    is_spanning_tree(g, other) ==>
      total_weight(best) <= total_weight(other);
  assert is_mst(g, best);
}

method kruskal_mst(graph: WeightedGraph) returns (edges: seq<Edge>)
    requires well_formed(graph)
    requires size(graph) > 0
    requires weights_bounded(view(graph))
    requires graph_is_connected(view(graph))
    ensures is_mst(view(graph), edges)
{
  WellFormedView(graph);
  MstExists(view(graph));
  edges :| is_mst(view(graph), edges);
}

