method CheckCandidate(
    a: seq<seq<int>>,
    b: seq<int>,
    x: seq<int>
) returns (ok: bool)
    requires |a| > 0
    requires |a| == |b|
    requires |x| == |a[0]|
    requires is_binary_vector(x)
    ensures ok <==> is_solution(a, b, x)
{
    var i := 0;
    ok := true;

    while i < |a|
        invariant 0 <= i <= |a|
        invariant ok ==>
            (forall j :: 0 <= j < i ==>
                spec_dot_product_gf2(a[j], x, |x| - 1) == b[j])
        invariant !ok ==>
            (exists j :: 0 <= j < i &&
                spec_dot_product_gf2(a[j], x, |x| - 1) != b[j])
        decreases |a| - i
    {
        var wasOk := ok;
        var equal :=
            spec_dot_product_gf2(a[i], x, |x| - 1) == b[i];

        if !equal {
            ok := false;
        }

        if ok {
            assert wasOk;
            assert equal;

            forall j | 0 <= j < i + 1
                ensures spec_dot_product_gf2(a[j], x, |x| - 1) == b[j]
            {
                if j < i {
                    assert spec_dot_product_gf2(a[j], x, |x| - 1) == b[j];
                } else {
                    assert j == i;
                }
            }
        } else {
            if !equal {
                assert 0 <= i < i + 1;
                assert spec_dot_product_gf2(a[i], x, |x| - 1) != b[i];
                assert exists j :: 0 <= j < i + 1 &&
                    spec_dot_product_gf2(a[j], x, |x| - 1) != b[j];
            } else {
                assert !wasOk;
                assert exists j :: 0 <= j < i &&
                    spec_dot_product_gf2(a[j], x, |x| - 1) != b[j];
                assert exists j :: 0 <= j < i + 1 &&
                    spec_dot_product_gf2(a[j], x, |x| - 1) != b[j];
            }
        }

        i := i + 1;
    }

    if ok {
        assert forall j :: 0 <= j < |a| ==>
            spec_dot_product_gf2(a[j], x, |x| - 1) == b[j];
    } else {
        assert exists j :: 0 <= j < |a| &&
            spec_dot_product_gf2(a[j], x, |x| - 1) != b[j];
        assert !(forall j :: 0 <= j < |a| ==>
            spec_dot_product_gf2(a[j], x, |x| - 1) == b[j]);
    }

    assert ok <==>
        (forall j :: 0 <= j < |a| ==>
            spec_dot_product_gf2(a[j], x, |x| - 1) == b[j]);
    assert ok <==> is_solution(a, b, x);
}

method SearchCompletions(
    a: seq<seq<int>>,
    b: seq<int>,
    prefix: seq<int>
) returns (res: Option<seq<int>>)
    requires |a| > 0
    requires |a| == |b|
    requires |prefix| <= |a[0]|
    requires is_binary_vector(prefix)
    ensures match res
        case Some(x) =>
            is_solution(a, b, x) && PrefixOf(prefix, x)
        case None =>
            forall x: seq<int> ::
                (|x| == |a[0]| &&
                 is_binary_vector(x) &&
                 PrefixOf(prefix, x))
                ==> !is_solution(a, b, x)
    decreases |a[0]| - |prefix|
{
    if |prefix| == |a[0]| {
        var ok := CheckCandidate(a, b, prefix);

        if ok {
            PrefixReflexive(prefix);
            res := Some(prefix);
        } else {
            res := None;

            forall x | |x| == |a[0]| &&
                       is_binary_vector(x) &&
                       PrefixOf(prefix, x)
