             p[0] == u &&
             p[|p| - 1] == v &&
             path_follows_edges(es, p);

  var q := seq(|p|, i requires 0 <= i < |p| =>
    p[|p| - 1 - i]);

  assert |q| == |p|;
  assert q[0] == v;
  assert q[|q| - 1] == u;

  forall k | 0 <= k < |q| - 1
    ensures edge_in_set(es, q[k], q[k + 1])
  {
    var j := |p| - 2 - k;
    assert 0 <= j < |p| - 1;
    assert q[k] == p[j + 1];
    assert q[k + 1] == p[j];
    assert edge_in_set(es, p[j], p[j + 1]);
    EdgeSymmetry(es, p[j], p[j + 1]);
  }
}

lemma JoinPaths(es: seq<Edge>, p: seq<int>, q: seq<int>)
  requires |p| > 0
  requires |q| > 0
  requires p[|p| - 1] == q[0]
  requires path_follows_edges(es, p)
  requires path_follows_edges(es, q)
  ensures |p + q[1..]| > 0
  ensures (p + q[1..])[0] == p[0]
  ensures (p + q[1..])[|p + q[1..]| - 1] == q[|q| - 1]
  ensures path_follows_edges(es, p + q[1..])
{
  var r := p + q[1..];

  forall k | 0 <= k < |r| - 1
    ensures edge_in_set(es, r[k], r[k + 1])
  {
    if k < |p| - 1 {
      assert r[k] == p[k];
      assert r[k + 1] == p[k + 1];
    } else if k == |p| - 1 {
      assert |q| > 1;
      assert r[k] == q[0];
      assert r[k + 1] == q[1];
    } else {
      var j := k - |p| + 1;
      assert 1 <= j < |q| - 1;
      assert r[k] == q[j];
      assert r[k + 1] == q[j + 1];
    }
  }

  if |q| == 1 {
    assert q[1..] == [];
    assert r == p;
  }
}

lemma ConnectedTransitive(
    es: seq<Edge>, u: int, m: int, v: int)
  requires edges_connected(es, u, m)
  requires edges_connected(es, m, v)
  ensures edges_connected(es, u, v)
{
  var p :| |p| > 0 &&
             p[0] == u &&
             p[|p| - 1] == m &&
             path_follows_edges(es, p);
  var q :| |q| > 0 &&
             q[0] == m &&
             q[|q| - 1] == v &&
             path_follows_edges(es, q);

  JoinPaths(es, p, q);
}

lemma ExtendByExistingEdge(
    es: seq<Edge>, root: int, u: int, v: int)
  requires edges_connected(es, root, u)
  requires edge_in_set(es, u, v)
  ensures edges_connected(es, root, v)
{
  var p :| |p| > 0 &&
             p[0] == root &&
             p[|p| - 1] == u &&
             path_follows_edges(es, p);

  var q := p + [v];

  forall k | 0 <= k < |q| - 1
    ensures edge_in_set(es, q[k], q[k + 1])
  {
    if k < |p| - 1 {
      assert q[k] == p[k];
      assert q[k + 1] == p[k + 1];
    } else {
      assert k == |p| - 1;
      assert q[k] == u;
      assert q[k + 1] == v;
    }
  }

  assert q[0] == root;
  assert q[|q| - 1] == v;
}

lemma RootConnectivityImpliesSpanning(
    g: seq<seq<(int, int)>>,
    es: seq<Edge>,
    root: int)
  requires 0 <= root < |g|
  requires forall v: int ::
    0 <= v < |g| ==> edges_connected(es, root, v)
  ensures is_spanning(g, es)
{
  forall u: int, v: int |
      0 <= u < |g| && 0 <= v < |g|
    ensures edges_connected(es, u, v)
  {
    ConnectedSymmetry(es, root, u);
    ConnectedTransitive(es, u, root, v);
  }
}

function RowEdges(u: int, row: seq<(int, int)>): seq<Edge>
  decreases |row|
{
  if |row| == 0 then []
  else [(u, row[0].0, row[0].1)] + RowEdges(u, row[1..])
}

function AllEdgesFrom(
    g: seq<seq<(int, int)>>,
    u: nat): seq<Edge>
  requires u <= |g|
  decreases |g| - u
{
  if u == |g| then []
  else RowEdges(u, g[u]) + AllEdgesFrom(g, u + 1)
}

function AllEdges(g: seq<seq<(int, int)>>): seq<Edge> {
  AllEdgesFrom(g, 0)
}

lemma RowEdgePresent(
    u: int,
    row: seq<(int, int)>,
    i: int)
  requires 0 <= i < |row|
  ensures (u, row[i].0, row[i].1) in RowEdges(u, row)
  decreases |row|
{
  if i == 0 {
  } else {
    RowEdgePresent(u, row[1..], i - 1);
    assert row[1..][i - 1] == row[i];
  }
}

lemma EdgePresentFrom(
    g: seq<seq<(int, int)>>,
    start: nat,
    u: int,
    i: int)
  requires start <= u < |g|
  requires 0 <= i < |g[u]|
  ensures (u, g[u][i].0, g[u][i].1) in
          AllEdgesFrom(g, start)
  decreases u - start
{
  if start == u {
    RowEdgePresent(u, g[u], i);
  } else {
    EdgePresentFrom(g, start + 1, u, i);
  }
}

lemma HasEdgeInAllEdges(
    g: seq<seq<(int, int)>>,
    u: int,
    v: int,
    w: int)
  requires has_edge(g, u, v, w)
  ensures (u, v, w) in AllEdges(g)
{
  var i :| 0 <= u < |g| &&
             0 <= i < |g[u]| &&
             g[u][i].0 == v &&
             g[u][i].1 == w;
  EdgePresentFrom(g, 0, u, i);
}

lemma RowEdgesValid(
    g: seq<seq<(int, int)>>,
    u: int,
    row: seq<(int, int)>,
    offset: int)
  requires 0 <= u < |g|
  requires 0 <= offset <= |g[u]|
  requires row == g[u][offset..]
  ensures forall e: Edge ::
    e in RowEdges(u, row) ==> has_edge(g, e.0, e.1, e.2)
  decreases |row|
{
  if |row| != 0 {
    assert offset < |g[u]|;
    assert row[0] == g[u][offset];

    RowEdgesValid(g, u, row[1..], offset + 1);

    forall e: Edge | e in RowEdges(u, row)
      ensures has_edge(g, e.0, e.1, e.2)
    {
      if e == (u, row[0].0, row[0].1) {
        assert has_edge(g, e.0, e.1, e.2);
      } else {
        assert e in RowEdges(u, row[1..]);
      }
    }
  }
}

lemma AllEdgesFromValid(
    g: seq<seq<(int, int)>>,
    start: nat)
  requires start <= |g|
  ensures forall e: Edge ::
    e in AllEdgesFrom(g, start) ==>
      has_edge(g, e.0, e.1, e.2)
  decreases |g| - start
{
  if start != |g| {
    RowEdgesValid(g, start, g[start], 0);
    AllEdgesFromValid(g, start + 1);

    forall e: Edge | e in AllEdgesFrom(g, start)
      ensures has_edge(g, e.0, e.1, e.2)
    {
      if e in RowEdges(start, g[start]) {
      } else {
        assert e in AllEdgesFrom(g, start + 1);
      }
    }
  }
}

lemma AllEdgesValid(g: seq<seq<(int, int)>>)
  ensures forall e: Edge ::
    e in AllEdges(g) ==> has_edge(g, e.0, e.1, e.2)
{
  AllEdgesFromValid(g, 0);
}

function PrependAll(
    e: Edge,
    candidates: seq<seq<Edge>>): seq<seq<Edge>>
  decreases |candidates|
{
  if |candidates| == 0 then []
  else [[e] + candidates[0]] +
       PrependAll(e, candidates[1..])
}

function ExtendCandidates(
    choices: seq<Edge>,
    tails: seq<seq<Edge>>): seq<seq<Edge>>
  decreases |choices|
{
  if |choices| == 0 then []
  else PrependAll(choices[0], tails) +
       ExtendCandidates(choices[1..], tails)
}

function Candidates(
    length: nat,
    choices: seq<Edge>): seq<seq<Edge>>
  decreases length
{
  if length == 0 then [[]]
  else ExtendCandidates(choices, Candidates(length - 1, choices))
}

lemma PrependAllContains(
    e: Edge,
    tails: seq<seq<Edge>>,
    tail: seq<Edge>)
  requires tail in tails
  ensures [e] + tail in PrependAll(e, tails)
  decreases |tails|
{
  if tail != tails[0] {
    assert tail in tails[1..];
    PrependAllContains(e, tails[1..], tail);
  }
}

lemma ExtendCandidatesContains(
    choices: seq<Edge>,
    tails: seq<seq<Edge>>,
    e: Edge,
    tail: seq<Edge>)
  requires e in choices
  requires tail in tails
  ensures [e] + tail in ExtendCandidates(choices, tails)
  decreases |choices|
{
  if e == choices[0] {
    PrependAllContains(e, tails, tail);
  } else {
    assert e in choices[1..];
    ExtendCandidatesContains(choices[1..], tails, e, tail);
  }
}

lemma CandidateIncluded(
    choices: seq<Edge>,
    candidate: seq<Edge>)
  requires forall k: int ::
    0 <= k < |candidate| ==> candidate[k] in choices
  ensures candidate in Candidates(|candidate|, choices)
  decreases |candidate|
{
  if |candidate| == 0 {
  } else {
    assert candidate == [candidate[0]] + candidate[1..];

    assert forall k: int ::
      0 <= k < |candidate[1..]| ==>
        candidate[1..][k] in choices by {
      forall k: int | 0 <= k < |candidate[1..]|
        ensures candidate[1..][k] in choices
      {
        assert candidate[1..][k] == candidate[k + 1];
      }
    }

    CandidateIncluded(choices, candidate[1..]);
    ExtendCandidatesContains(
      choices,
      Candidates(|candidate| - 1, choices),
      candidate[0],
      candidate[1..]);
  }
}

lemma PrependAllProperties(
    e: Edge,
    tails: seq<seq<Edge>>,
    candidate: seq<Edge>)
  requires candidate in PrependAll(e, tails)
  ensures |candidate| > 0
  ensures candidate[0] == e
  ensures candidate[1..] in tails
  decreases |tails|
{
  if candidate == [e] + tails[0] {
    assert candidate[1..] == tails[0];
  } else {
    assert candidate in PrependAll(e, tails[1..]);
    PrependAllProperties(e, tails[1..], candidate);
  }
}

lemma ExtendCandidatesProperties(
    choices: seq<Edge>,
    tails: seq<seq<Edge>>,
    candidate: seq<Edge>)
  requires candidate in ExtendCandidates(choices, tails)
  ensures |candidate| > 0
  ensures candidate[0] in choices
  ensures candidate[1..] in tails
  decreases |choices|
{
  if candidate in PrependAll(choices[0], tails) {
    PrependAllProperties(choices[0], tails, candidate);
  } else {
    assert candidate in ExtendCandidates(choices[1..], tails);
    ExtendCandidatesProperties(
      choices[1..], tails, candidate);
  }
}

lemma CandidateProperties(
    length: nat,
    choices: seq<Edge>,
    candidate: seq<Edge>)
  requires candidate in Candidates(length, choices)
  ensures |candidate| == length
  ensures forall k: int ::
    0 <= k < |candidate| ==> candidate[k] in choices
  decreases length
{
  if length == 0 {
    assert candidate == [];
  } else {
    ExtendCandidatesProperties(
      choices,
      Candidates(length - 1, choices),
      candidate);

    CandidateProperties(
      length - 1, choices, candidate[1..]);

    forall k: int | 0 <= k < |candidate|
      ensures candidate[k] in choices
    {
      if k != 0 {
        assert candidate[k] == candidate[1..][k - 1];
      }
    }
  }
}

function AddVertexToSets(
    v: int,
    sets: seq<set<int>>): seq<set<int>>
  decreases |sets|
{
  if |sets| == 0 then []
  else [sets[0] + {v}] +
       AddVertexToSets(v, sets[1..])
}

function Subsets(n: nat): seq<set<int>>
  decreases n
{
  if n == 0 then [{}]
  else
    Subsets(n - 1) +
    AddVertexToSets(n - 1, Subsets(n - 1))
}

lemma AddVertexContains(
    v: int,
    sets: seq<set<int>>,
    s: set<int>)
  requires s in sets
  ensures s + {v} in AddVertexToSets(v, sets)
  decreases |sets|
{
  if s != sets[0] {
    assert s in sets[1..];
    AddVertexContains(v, sets[1..], s);
  }
}

lemma AddVertexProperties(
    v: int,
    sets: seq<set<int>>,
    s: set<int>)
  requires s in AddVertexToSets(v, sets)
  ensures exists t: set<int> ::
    t in sets && s == t + {v}
  decreases |sets|
{
  if s == sets[0] + {v} {
  } else {
    assert s in AddVertexToSets(v, sets[1..]);
    AddVertexProperties(v, sets[1..], s);
  }
}

lemma SubsetsBounded(n: nat)
  ensures forall s: set<int> ::
    s in Subsets(n) ==> s <= Nodes(n)
  decreases n
{
  NodesFacts(n);

  if n != 0 {
    SubsetsBounded(n - 1);

    forall s: set<int> | s in Subsets(n)
      ensures s <= Nodes(n)
    {
      if s in Subsets(n - 1) {
        assert s <= Nodes(n - 1);
        assert Nodes(n - 1) <= Nodes(n);
      } else {
        assert s in
          AddVertexToSets(n - 1, Subsets(n - 1));
        AddVertexProperties(
          n - 1, Subsets(n - 1), s);
        var t :| t in Subsets(n - 1) &&
                  s == t + {n - 1};
        assert t <= Nodes(n - 1);
      }
    }
  }
}

lemma SubsetIncluded(n: nat, s: set<int>)
  requires s <= Nodes(n)
  ensures s in Subsets(n)
  decreases n
{
  if n == 0 {
    assert s == {};
  } else {
    NodesFacts(n);
    NodesFacts(n - 1);

    if n - 1 in s {
      var t := s - {n - 1};

      assert t <= Nodes(n - 1) by {
        forall x: int | x in t
          ensures x in Nodes(n - 1)
        {
          assert x in Nodes(n);
          assert 0 <= x < n;
          assert x != n - 1;
          assert 0 <= x < n - 1;
        }
      }

      SubsetIncluded(n - 1, t);
      AddVertexContains(
        n - 1, Subsets(n - 1), t);
      assert t + {n - 1} == s;
    } else {
      assert s <= Nodes(n - 1) by {
        forall x: int | x in s
          ensures x in Nodes(n - 1)
        {
          assert 0 <= x < n;
          assert x != n - 1;
          assert 0 <= x < n - 1;
        }
      }

      SubsetIncluded(n - 1, s);
    }
  }
}

predicate Crosses(e: Edge, s: set<int>) {
  (e.0 in s && e.1 !in s) ||
  (e.1 in s && e.0 !in s)
}

predicate CutConnected(n: nat, es: seq<Edge>) {
  forall i: int | 0 <= i < |Subsets(n)| ::
    0 in Subsets(n)[i] &&
    |Subsets(n)[i]| < n
    ==>
    exists k: int | 0 <= k < |es| ::
      Crosses(es[k], Subsets(n)[i])
}

lemma FindCrossingTreeEdge(
    es: seq<Edge>,
    s: set<int>,
    p: seq<int>)
    returns (edgeIndex: int)
  requires |p| > 0
  requires p[0] in s
  requires p[|p| - 1] !in s
  requires path_follows_edges(es, p)
  ensures 0 <= edgeIndex < |es|
  ensures Crosses(es[edgeIndex], s)
{
  assert |p| > 1;
  var j := 1;

  while p[j] in s
    invariant 1 <= j < |p|
    invariant p[j - 1] in s
    decreases |p| - j
  {
    assert j < |p| - 1;
    j := j + 1;
  }

  assert edge_in_set(es, p[j - 1], p[j]);

  edgeIndex :| 0 <= edgeIndex < |es| &&
    ((es[edgeIndex].0 == p[j - 1] &&
      es[edgeIndex].1 == p[j]) ||
     (es[edgeIndex].0 == p[j] &&
      es[edgeIndex].1 == p[j - 1]));

  assert Crosses(es[edgeIndex], s);
}

lemma SpanningImpliesCutConnected(
    n: nat,
    es: seq<Edge>)
  requires n > 0
  requires is_spanning(
    seq(n, i requires 0 <= i < n => []), es)
  ensures CutConnected(n, es)
{
  NodesFacts(n);
  SubsetsBounded(n);

  forall i: int | 0 <= i < |Subsets(n)|
    ensures
      0 in Subsets(n)[i] &&
      |Subsets(n)[i]| < n
      ==>
      exists k: int | 0 <= k < |es| ::
        Crosses(es[k], Subsets(n)[i])
  {
    var s := Subsets(n)[i];

    if 0 in s && |s| < n {
      assert s <= Nodes(n);
      assert |s| < |Nodes(n)|;

      assert exists target: int ::
        target in Nodes(n) && target !in s by {
        if !(exists target: int ::
              target in Nodes(n) && target !in s) {
          assert Nodes(n) <= s;
          assert s == Nodes(n);
        }
      }

      var target :| target in Nodes(n) &&
                      target !in s;
      assert 0 <= target < n;

      var emptyGraph :=
        seq(n, j requires 0 <= j < n => []);

      assert edges_connected(es, 0, target);
      var p :| |p| > 0 &&
                 p[0] == 0 &&
                 p[|p| - 1] == target &&
                 path_follows_edges(es, p);

      var k := FindCrossingTreeEdge(es, s, p);
    }
  }
}

lemma ValidEdgesBounded(
    g: seq<seq<(int, int)>>,
    es: seq<Edge>)
  requires vertices_well_formed(g)
  requires are_valid_edges(g, es)
  ensures forall k: int ::
    0 <= k < |es| ==>
      0 <= es[k].0 < |g| &&
      0 <= es[k].1 < |g|
{
  forall k: int | 0 <= k < |es|
    ensures 0 <= es[k].0 < |g| &&
            0 <= es[k].1 < |g|
  {
    assert has_edge(
      g, es[k].0, es[k].1, es[k].2);

    var i :| 0 <= es[k].0 < |g| &&
               0 <= i < |g[es[k].0]| &&
               g[es[k].0][i].0 == es[k].1 &&
               g[es[k].0][i].1 == es[k].2;

    assert 0 <= g[es[k].0][i].0 < |g|;
  }
}

lemma CutConnectedImpliesSpanning(
    g: seq<seq<(int, int)>>,
    es: seq<Edge>)
  requires |g| > 0
  requires CutConnected(|g|, es)
  requires forall k: int ::
    0 <= k < |es| ==>
      0 <= es[k].0 < |g| &&
      0 <= es[k].1 < |g|
  ensures is_spanning(g, es)
{
  NodesFacts(|g|);

  var reached: set<int> :=
    set x: int |
      x in Nodes(|g|) &&
      edges_connected(es, 0, x);

  ConnectedReflexive(es, 0);
  assert 0 in reached;

  if reached != Nodes(|g|) {
    assert reached < Nodes(|g|);
    assert |reached| < |Nodes(|g|)|;
    assert |reached| < |g|;

    SubsetIncluded(|g|, reached);
    assert reached in Subsets(|g|);

    var i :| 0 <= i < |Subsets(|g|)| &&
               Subsets(|g|)[i] == reached;

    assert exists k: int | 0 <= k < |es| ::
      Crosses(es[k], reached);

    var k :| 0 <= k < |es| &&
               Crosses(es[k], reached);

    var e := es[k];
    assert 0 <= e.0 < |g|;
    assert 0 <= e.1 < |g|;

    if e.0 in reached && e.1 !in reached {
      assert edges_connected(es, 0, e.0);
      assert edge_in_set(es, e.0, e.1) by {
        assert 0 <= k < |es|;
      }
      ExtendByExistingEdge(es, 0, e.0, e.1);
      assert e.1 in reached;
    } else {
      assert e.1 in reached && e.0 !in reached;
      assert edges_connected(es, 0, e.1);
      assert edge_in_set(es, e.1, e.0) by {
        assert 0 <= k < |es|;
      }
      ExtendByExistingEdge(es, 0, e.1, e.0);
      assert e.0 in reached;
    }

    assert false;
  }

  assert reached == Nodes(|g|);

  forall v: int | 0 <= v < |g|
    ensures edges_connected(es, 0, v)
  {
    assert v in Nodes(|g|);
    assert v in reached;
  }

  RootConnectivityImpliesSpanning(g, es, 0);
}

function Weight(es: seq<Edge>): int
  decreases |es|
{
  if |es| == 0 then 0
  else es[0].2 + Weight(es[1..])
}

lemma WeightEqualsTotalWeight(es: seq<Edge>)
  ensures Weight(es) == total_weight(es)
  decreases |es|
{
  if |es| != 0 {
    WeightEqualsTotalWeight(es[1..]);
  }
}

predicate Admissible(
    n: nat,
    choices: seq<Edge>,
    es: seq<Edge>)
{
  es in Candidates(n - 1, choices) &&
  CutConnected(n, es)
}

function HasAdmissible(
    n: nat,
    choices: seq<Edge>,
    candidates: seq<seq<Edge>>): bool
  decreases |candidates|
{
  if |candidates| == 0 then false
  else
    Admissible(n, choices, candidates[0]) ||
    HasAdmissible(n, choices, candidates[1..])
}

lemma HasAdmissibleFromMember(
    n: nat,
    choices: seq<Edge>,
    candidates: seq<seq<Edge>>,
    candidate: seq<Edge>)
  requires candidate in candidates
  requires Admissible(n, choices, candidate)
  ensures HasAdmissible(n, choices, candidates)
  decreases |candidates|
{
  if candidate != candidates[0] {
    assert candidate in candidates[1..];
    HasAdmissibleFromMember(
      n, choices, candidates[1..], candidate);
  }
}

lemma HasAdmissibleWitness(
    n: nat,
    choices: seq<Edge>,
    candidates: seq<seq<Edge>>)
  requires HasAdmissible(n, choices, candidates)
  ensures exists candidate: seq<Edge> ::
    candidate in candidates &&
    Admissible(n, choices, candidate)
  decreases |candidates|
{
  if !Admissible(n, choices, candidates[0]) {
    HasAdmissibleWitness(
      n, choices, candidates[1..]);
  }
}

method ChooseBest(
    n: nat,
    choices: seq<Edge>,
    candidates: seq<seq<Edge>>)
    returns (best: seq<Edge>)
  requires HasAdmissible(n, choices, candidates)
  ensures best in candidates
  ensures Admissible(n, choices, best)
  ensures forall candidate: seq<Edge> ::
    candidate in candidates &&
    Admissible(n, choices, candidate)
    ==> Weight(best) <= Weight(candidate)
  decreases |candidates|
{
  assert |candidates| > 0;

  if Admissible(n, choices, candidates[0]) {
    if HasAdmissible(n, choices, candidates[1..]) {
      var tailBest :=
        ChooseBest(n, choices, candidates[1..]);

      if Weight(candidates[0]) <= Weight(tailBest) {
        best := candidates[0];

        forall candidate: seq<Edge> |
          candidate in candidates &&
          Admissible(n, choices, candidate)
          ensures Weight(best) <= Weight(candidate)
        {
          if candidate != candidates[0] {
            assert candidate in candidates[1..];
            assert Weight(tailBest) <= Weight(candidate);
          }
        }
      } else {
        best := tailBest;

        forall candidate: seq<Edge> |
          candidate in candidates &&
          Admissible(n, choices, candidate)
          ensures Weight(best) <= Weight(candidate)
        {
          if candidate == candidates[0] {
            assert Weight(best) < Weight(candidate);
          } else {
            assert candidate in candidates[1..];
          }
        }
      }
    } else {
      best := candidates[0];

      forall candidate: seq<Edge> |
        candidate in candidates &&
        Admissible(n, choices, candidate)
        ensures Weight(best) <= Weight(candidate)
      {
        if candidate != candidates[0] {
          assert candidate in candidates[1..];
          HasAdmissibleFromMember(
            n, choices, candidates[1..], candidate);
          assert false;
        }
      }
    }
  } else {
    assert HasAdmissible(
      n, choices, candidates[1..]);

    best :=
      ChooseBest(n, choices, candidates[1..]);

    forall candidate: seq<Edge> |
      candidate in candidates &&
      Admissible(n, choices, candidate)
      ensures Weight(best) <= Weight(candidate)
    {
      assert candidate != candidates[0];
      assert candidate in candidates[1..];
    }
  }
}

lemma CandidateIsValid(
    g: seq<seq<(int, int)>>,
