lemma SpanningTreeIsCandidate(
    g: seq<seq<(int, int)>>,
    tree: seq<Edge>)
  requires is_spanning_tree(g, tree)
  ensures tree in Candidates(|g| - 1, AllEdges(g))
{
  assert |tree| == |g| - 1;

  forall k: int | 0 <= k < |tree|
    ensures tree[k] in AllEdges(g)
  {
    assert has_edge(
      g, tree[k].0, tree[k].1, tree[k].2);
    HasEdgeInAllEdges(
      g, tree[k].0, tree[k].1, tree[k].2);
