    tree: seq<Edge>)
  requires |g| > 0
  requires is_spanning_tree(g, tree)
  ensures Admissible(|g|, AllEdges(g), tree)
{
  SpanningTreeIsCandidate(g, tree);

  var emptyGraph :=
    seq(|g|, i requires 0 <= i < |g| => []);

  assert is_spanning(emptyGraph, tree);

  SpanningImpliesCutConnected(|g|, tree);
}

lemma AdmissibleIsSpanningTree(
    g: seq<seq<(int, int)>>,
    tree: seq<Edge>)
  requires |g| > 0
  requires vertices_well_formed(g)
  requires Admissible(|g|, AllEdges(g), tree)
  ensures is_spanning_tree(g, tree)
{
  CandidateIsValid(g, tree);
  ValidEdgesBounded(g, tree);
  CutConnectedImpliesSpanning(g, tree);

  assert are_valid_edges(g, tree);
  assert is_spanning(g, tree);
  assert |tree| == |g| - 1;
