lemma SomeSpanningTree(
    g: seq<seq<(int, int)>>)
  requires |g| > 0
  requires vertices_well_formed(g)
  requires graph_is_connected(g)
  ensures exists tree: seq<Edge> ::
    is_spanning_tree(g, tree)
{
  NodesFacts(|g|);

  var reached: set<int> := {0};
  var tree: seq<Edge> := [];

  ConnectedReflexive(tree, 0);

  while |reached| < |g|
    invariant reached <= Nodes(|g|)
    invariant 0 in reached
    invariant |tree| == |reached| - 1
    invariant are_valid_edges(g, tree)
    invariant forall r: int ::
      r in reached ==> edges_connected(tree, 0, r)
    decreases |g| - |reached|
  {
    assert exists target: int ::
      target in Nodes(|g|) && target !in reached by {
      if !(exists target: int ::
            target in Nodes(|g|) && target !in reached) {
        assert Nodes(|g|) <= reached;
        assert reached == Nodes(|g|);
        assert |reached| == |g|;
      }
    }

    var target :| target in Nodes(|g|) &&
                    target !in reached;
    assert 0 <= target < |g|;

    assert nodes_have_path(g, 0, target);
    var p :| |p| > 0 &&
               p[0] == 0 &&
               p[|p| - 1] == target &&
               path_follows_graph(g, p);

    var j := 1;
    assert |p| > 1;

    while p[j] in reached
      invariant 1 <= j < |p|
      invariant p[j - 1] in reached
      decreases |p| - j
    {
      assert j < |p| - 1;
      j := j + 1;
    }

    var u := p[j - 1];
    var v := p[j];

    assert graph_has_any_edge(g, u, v);
    var idx :| 0 <= u < |g| &&
                 0 <= idx < |g[u]| &&
                 g[u][idx].0 == v;
    var w := g[u][idx].1;
    assert has_edge(g, u, v, w);

    var oldTree := tree;
    var oldReached := reached;

    tree := oldTree + [(u, v, w)];
    reached := oldReached + {v};

    assert are_valid_edges(g, tree) by {
      forall k: int | 0 <= k < |tree|
        ensures has_edge(
          g, tree[k].0, tree[k].1, tree[k].2)
      {
        if k < |oldTree| {
          assert tree[k] == oldTree[k];
        } else {
          assert k == |oldTree|;
          assert tree[k] == (u, v, w);
        }
      }
    }

    assert edge_in_set(tree, u, v) by {
      assert tree[|oldTree|] == (u, v, w);
    }

    assert edges_connected(oldTree, 0, u);
    var upath :| |upath| > 0 &&
                   upath[0] == 0 &&
                   upath[|upath| - 1] == u &&
                   path_follows_edges(oldTree, upath);

    var vpath := upath + [v];

    forall k: int | 0 <= k < |vpath| - 1
      ensures edge_in_set(tree, vpath[k], vpath[k + 1])
    {
      if k < |upath| - 1 {
        assert edge_in_set(
          oldTree, upath[k], upath[k + 1]);
        var ei :| 0 <= ei < |oldTree| &&
          ((oldTree[ei].0 == upath[k] &&
            oldTree[ei].1 == upath[k + 1]) ||
           (oldTree[ei].0 == upath[k + 1] &&
            oldTree[ei].1 == upath[k]));
        assert tree[ei] == oldTree[ei];
      } else {
        assert k == |upath| - 1;
        assert vpath[k] == u;
        assert vpath[k + 1] == v;
      }
    }

    assert edges_connected(tree, 0, v);

    forall r: int | r in reached
      ensures edges_connected(tree, 0, r)
    {
      if r != v {
        assert r in oldReached;
        assert edges_connected(oldTree, 0, r);

        var rpath :| |rpath| > 0 &&
                       rpath[0] == 0 &&
                       rpath[|rpath| - 1] == r &&
                       path_follows_edges(oldTree, rpath);

        forall k: int | 0 <= k < |rpath| - 1
          ensures edge_in_set(
            tree, rpath[k], rpath[k + 1])
        {
          var ei :| 0 <= ei < |oldTree| &&
            ((oldTree[ei].0 == rpath[k] &&
              oldTree[ei].1 == rpath[k + 1]) ||
             (oldTree[ei].0 == rpath[k + 1] &&
              oldTree[ei].1 == rpath[k]));
          assert tree[ei] == oldTree[ei];
        }
      }
    }

    assert v in Nodes(|g|);
    assert reached <= Nodes(|g|);
    assert |reached| == |oldReached| + 1;
    assert |tree| == |oldTree| + 1;
  }

  assert reached == Nodes(|g|) by {
    assert reached <= Nodes(|g|);
    assert |reached| == |g|;
    assert |Nodes(|g|)| == |g|;
  }

  forall r: int | 0 <= r < |g|
    ensures edges_connected(tree, 0, r)
  {
    assert r in Nodes(|g|);
    assert r in reached;
  }

  RootConnectivityImpliesSpanning(g, tree, 0);
  assert |tree| == |g| - 1;
  assert is_spanning_tree(g, tree);
}

method kruskal_mst(graph: WeightedGraph) returns (edges: seq<Edge>)
    requires well_formed(graph)
    requires size(graph) > 0
    requires weights_bounded(view(graph))
    requires graph_is_connected(view(graph))
    ensures is_mst(view(graph), edges)
{
  var g := view(graph);
  var n: nat := |g|;
  var choices := AllEdges(g);
  var candidates := Candidates(n - 1, choices);

  WellFormedView(graph);
  SomeSpanningTree(g);

  ghost var witness :|
    is_spanning_tree(g, witness);

  SpanningTreeIsAdmissible(g, witness);
  assert witness in candidates;
  HasAdmissibleFromMember(
    n, choices, candidates, witness);

  edges := ChooseBest(n, choices, candidates);

  AdmissibleIsSpanningTree(g, edges);
  WeightEqualsTotalWeight(edges);

  forall other: seq<Edge> |
    is_spanning_tree(g, other)
    ensures total_weight(edges) <= total_weight(other)
  {
    SpanningTreeIsAdmissible(g, other);
    assert other in candidates;
    assert Weight(edges) <= Weight(other);
    WeightEqualsTotalWeight(other);
  }

  assert is_mst(g, edges);
}
