method ToSeqEx(t: Option<Node>, v: int) returns (s: seq<int>)
  requires t.Some? ==> t.value.is_bst()
  ensures sorted(s)
  ensures elems(s) == view_opt(t) - {v}
  decreases t
{
  match t {
    case None =>
      s := [];
      assert elems(s) == {};
    case Some(n) =>
      BstFacts(n);
      var a := ToSeqEx(n.left, v);
      var c := ToSeqEx(n.right, v);
      var m: seq<int> := if n.val == v then [] else [n.val];
      assert forall x :: x in a ==> x < n.val by {
        forall x | x in a ensures x < n.val { assert x in elems(a); }
      }
      assert forall x :: x in c ==> x > n.val by {
        forall x | x in c ensures x > n.val { assert x in elems(c); }
      }
      assert forall x :: x in m ==> x == n.val;
      assert sorted(m);
      SortedConcat(a, m);
      assert forall x, y :: x in a + m && y in c ==> x < y by {
        forall x, y | x in a + m && y in c ensures x < y {
          assert x in a || x in m;
        }
      }
      SortedConcat(a + m, c);
      s := a + m + c;
      ElemsConcat(a, m);
      ElemsConcat(a + m, c);
      assert elems(m) == (if n.val == v then {} else {n.val});
  }
}

method Build(s: seq<int>, b: nat) returns (t: Option<Node>)
  requires sorted(s)
  requires b >= 1
  requires minSize(b) <= |s| <= maxSize(b)
  ensures is_llrbt_opt(t)
  ensures view_opt(t) == elems(s)
  ensures bh_opt(t) == b
  ensures is_black_opt(t)
  decreases b
{
  if b == 1 {
    assert |s| == 0;
    assert elems(s) == {};
    t := None;
    return;
  }
  var L := minSize(b - 1);
  var U := maxSize(b - 1);
  SizeLemma(b - 1);
  assert minSize(b) == 2 * L + 1;
  assert maxSize(b) == 3 * U + 2;
  var n := |s|;
  if n <= 2 * U + 1 {
    var n1 := if L >= n - 1 - U then L else n - 1 - U;
    var A := s[0..n1];
    var C := s[n1+1..|s|];
    SortedSlice(s, 0, n1);
    SortedSlice(s, n1 + 1, |s|);
    var l := Build(A, b - 1);
    var r := Build(C, b - 1);
    SortedSplit(s, n1);
    ElemsSplit(s, n1);
    assert forall x :: x in view_opt(l) ==> x < s[n1];
    assert forall x :: x in view_opt(r) ==> x > s[n1];
    MkNode(s[n1], false, l, r);
    t := Some(Node(s[n1], false, l, r));
  } else {
    var m := n - 2;
    var n1 := if L >= m - 2 * U then L else m - 2 * U;
    var rest := m - n1;
    var n2 := if L >= rest - U then L else rest - U;
    var j := n1 + 1 + n2;
    assert L <= n1 <= U;
    assert L <= n2 <= U;
    assert L <= n - j - 1 <= U;
    var P := s[0..j];
    SortedSlice(s, 0, j);
    var A := P[0..n1];
    var B := P[n1+1..|P|];
    SortedSlice(P, 0, n1);
    SortedSlice(P, n1 + 1, |P|);
    var a := Build(A, b - 1);
    var bt := Build(B, b - 1);
    SortedSplit(P, n1);
    ElemsSplit(P, n1);
    assert forall x :: x in view_opt(a) ==> x < P[n1];
    assert forall x :: x in view_opt(bt) ==> x > P[n1];
    MkNode(P[n1], true, a, bt);
    var inner := Node(P[n1], true, a, bt);
    assert inner.view() == elems(P);
    var C := s[j+1..|s|];
    SortedSlice(s, j + 1, |s|);
    var c := Build(C, b - 1);
    SortedSplit(s, j);
    ElemsSplit(s, j);
    assert forall x :: x in view_opt(Some(inner)) ==> x < s[j];
    assert forall x :: x in view_opt(c) ==> x > s[j];
    MkNode(s[j], false, Some(inner), c);
    t := Some(Node(s[j], false, Some(inner), c));
  }
}

method delete(tree: Option<Node>, v: int) returns (res: Option<Node>)
    requires is_llrbt_opt(tree)
    ensures 
        // Functional Correctness
        view_opt(res) == view_opt(tree) - {v}
    ensures
        // Invariant Maintenance
        is_llrbt_opt(res)
{
  var s := ToSeqEx(tree, v);
  var b: nat := 1;
  while maxSize(b) < |s|
    invariant b >= 1
    invariant minSize(b) <= |s|
    decreases |s| - maxSize(b)
  {
    SizeLemma(b);
    assert maxSize(b + 1) == 3 * maxSize(b) + 2;
    assert minSize(b + 1) == 2 * minSize(b) + 1;
    b := b + 1;
  }
  res := Build(s, b);
}

response:
The approach is to rebuild the tree rather than delete in place:

1. **Flatten.** Walk the tree in order, skipping `v`. This gives a strictly sorted sequence of exactly `view_opt(tree) - {v}`.
2. **Pick a black height.** Choose a height `b` for that number of elements. A 2-3 tree of black height `b` can hold between `minSize(b)` and `maxSize(b)` elements, and these ranges cover every size.
3. **Rebuild.** Build a fresh LLRBT from the sorted sequence of 2-nodes and 3-nodes. Each 3-node is a black node with a red left child. All subtrees get equal black height and black roots, so the red-black rules hold by construction.

