    pivot_row: int, pivot_cols: seq<int>, col_to_row: seq<int>
)
    requires rows > 0 && cols > 0
    requires |matrix| == rows && |matrix[0]| == cols && |b| == rows
    requires is_binary_matrix(M, rows, cols)
    requires |B| == rows && is_binary_vector(B)
    requires 0 <= pivot_row <= rows
    requires |pivot_cols| == pivot_row
    requires |col_to_row| == cols
    requires forall r :: 0 <= r < pivot_row ==> 0 <= pivot_cols[r] < cols
    requires forall c :: 0 <= c < cols ==> -1 <= col_to_row[c] < pivot_row
    requires forall r :: 0 <= r < pivot_row ==> col_to_row[pivot_cols[r]] == r
    requires forall c :: 0 <= c < cols && col_to_row[c] >= 0 ==> pivot_cols[col_to_row[c]] == c
    requires forall r, i :: 0 <= r < pivot_row && 0 <= i < rows ==> M[i][pivot_cols[r]] == (if i == r then 1 else 0)
    requires forall i, c :: pivot_row <= i < rows && 0 <= c < cols ==> M[i][c] == 0
    requires forall i :: pivot_row <= i < rows ==> B[i] == 0
    requires forall x: seq<int> :: (|x| == cols && is_binary_vector(x)) ==> (is_solution(matrix, b, x) <==> is_solution(M, B, x))
    ensures is_solution(matrix, b, build_solution(B, col_to_row, cols))
{
    var x := build_solution(B, col_to_row, cols);
    assert |x| == cols;
    assert is_binary_vector(x);
    forall i | 0 <= i < rows
        ensures spec_dot_product_gf2(M[i], x, cols - 1) == B[i]
    {
        assert is_binary_vector(M[i]);
        if i < pivot_row {
            var p := pivot_cols[i];
            assert 0 <= p < cols;
            assert col_to_row[p] == i;
            assert x[p] == B[i];
            assert M[i][p] == 1;
            assert B[i] == 0 || B[i] == 1;
            forall c | 0 <= c < cols && c != p
                ensures M[i][c] == 0 || x[c] == 0
            {
                if col_to_row[c] >= 0 {
                    var r := col_to_row[c];
                    assert pivot_cols[r] == c;
                    assert r != i;
                    assert M[i][pivot_cols[r]] == 0;
                } else {
                    assert x[c] == 0;
                }
            }
            lemma_single_term_dot_product(M[i], x, p, B[i], cols - 1);
        } else {
            lemma_zero_row_dot_product(M[i], x, cols - 1);
            assert B[i] == 0;
        }
    }
    assert is_solution(M, B, x);
}

method eliminate_column(
    matrix: seq<seq<int>>, b: seq<int>,
    M0: seq<seq<int>>, B0: seq<int>,
    rows: int, cols: int,
    pivot_row: int, col: int, p: int
) returns (M: seq<seq<int>>, B: seq<int>)
    requires rows > 0 && cols > 0
    requires |matrix| == rows && |matrix[0]| == cols && |b| == rows
    requires is_binary_matrix(M0, rows, cols)
    requires |B0| == rows && is_binary_vector(B0)
    requires 0 <= pivot_row <= p < rows
    requires 0 <= col < cols
    requires M0[p][col] == 1
    requires forall i, c :: pivot_row <= i < rows && 0 <= c < col ==> M0[i][c] == 0
    requires forall x: seq<int> :: (|x| == cols && is_binary_vector(x)) ==> (is_solution(matrix, b, x) <==> is_solution(M0, B0, x))
    ensures is_binary_matrix(M, rows, cols)
    ensures |B| == rows && is_binary_vector(B)
    ensures forall x: seq<int> :: (|x| == cols && is_binary_vector(x)) ==> (is_solution(matrix, b, x) <==> is_solution(M, B, x))
    ensures forall i, c :: 0 <= i < rows && 0 <= c < col ==> M[i][c] == M0[i][c]
    ensures forall i :: 0 <= i < rows ==> M[i][col] == (if i == pivot_row then 1 else 0)
{
    lemma_swap_preserves(matrix, b, M0, B0, rows, cols, pivot_row, p);
    M := swap_seq(M0, pivot_row, p);
    B := swap_seq(B0, pivot_row, p);

    assert M[pivot_row] == M0[p];
    assert M[pivot_row][col] == 1;
    forall i, c | 0 <= i < rows && 0 <= c < col
        ensures M[i][c] == M0[i][c]
    {
        if i == pivot_row {
            assert M[i][c] == M0[p][c];
            assert M0[p][c] == 0;
            assert M0[pivot_row][c] == 0;
        } else if i == p {
            assert M[i][c] == M0[pivot_row][c];
            assert M0[pivot_row][c] == 0;
            assert M0[p][c] == 0;
        } else {
            assert M[i][c] == M0[i][c];
        }
    }

    var row_idx := 0;
    while row_idx < rows
        invariant 0 <= row_idx <= rows
        invariant is_binary_matrix(M, rows, cols)
        invariant |B| == rows && is_binary_vector(B)
        invariant forall x: seq<int> :: (|x| == cols && is_binary_vector(x)) ==> (is_solution(matrix, b, x) <==> is_solution(M, B, x))
        invariant forall i, c :: 0 <= i < rows && 0 <= c < col ==> M[i][c] == M0[i][c]
        invariant M[pivot_row][col] == 1
        invariant forall i :: 0 <= i < row_idx ==> M[i][col] == (if i == pivot_row then 1 else 0)
        decreases rows - row_idx
    {
        if row_idx != pivot_row && M[row_idx][col] == 1 {
            var old_M := M;
            var rx := row_xor(M[row_idx], M[pivot_row]);
            lemma_xor_row_preserves(matrix, b, M, B, rows, cols, row_idx, pivot_row);
            M := M[row_idx := rx];
            B := B[row_idx := add_gf2(B[row_idx], B[pivot_row])];

            assert M[row_idx][col] == add_gf2(old_M[row_idx][col], old_M[pivot_row][col]);
            assert M[row_idx][col] == 0;

            forall i, c | 0 <= i < rows && 0 <= c < col
                ensures M[i][c] == M0[i][c]
            {
                if i == row_idx {
                    assert M[i][c] == add_gf2(old_M[row_idx][c], old_M[pivot_row][c]);
                    assert old_M[pivot_row][c] == M0[pivot_row][c];
                    assert M0[pivot_row][c] == 0;
                    assert old_M[row_idx][c] == 0 || old_M[row_idx][c] == 1;
                    assert M[i][c] == old_M[row_idx][c];
                } else {
                    assert M[i][c] == old_M[i][c];
                }
            }
        } else {
            assert M[row_idx][col] == 0 || M[row_idx][col] == 1;
            assert M[row_idx][col] == (if row_idx == pivot_row then 1 else 0);
        }
        row_idx := row_idx + 1;
    }
}

method solve_linear_system_gf2(matrix: seq<seq<int>>, b: seq<int>) returns (res: Option<seq<int>>)
    requires |matrix| > 0
    requires |matrix[0]| > 0
    requires |matrix| == |b|
    requires |matrix| <= 100
    requires |matrix[0]| <= 100
    requires is_binary_matrix(matrix, |matrix|, |matrix[0]|)
    requires is_binary_vector(b)

    ensures match res
        case Some(x) => is_solution(matrix, b, x)
        case None => 
            forall x: seq<int> :: 
                (|x| == |matrix[0]| && is_binary_vector(x)) 
                ==> !is_solution(matrix, b, x)
{
    var rows := |matrix|;
    var cols := |matrix[0]|;
    var M := matrix;
    var B := b;
    var pivot_row := 0;
    var col := 0;
    var pivot_cols: seq<int> := [];
    var col_to_row: seq<int> := seq(cols, c => -1);

    while col < cols
        invariant 0 <= pivot_row <= rows
        invariant 0 <= col <= cols
        invariant is_binary_matrix(M, rows, cols)
        invariant |B| == rows && is_binary_vector(B)
        invariant |pivot_cols| == pivot_row
        invariant |col_to_row| == cols
        invariant forall r :: 0 <= r < pivot_row ==> 0 <= pivot_cols[r] < col
        invariant forall c :: col <= c < cols ==> col_to_row[c] == -1
        invariant forall c :: 0 <= c < cols ==> -1 <= col_to_row[c] < pivot_row
        invariant forall r :: 0 <= r < pivot_row ==> col_to_row[pivot_cols[r]] == r
        invariant forall c :: 0 <= c < cols && col_to_row[c] >= 0 ==> pivot_cols[col_to_row[c]] == c
        invariant forall r, i :: 0 <= r < pivot_row && 0 <= i < rows ==> M[i][pivot_cols[r]] == (if i == r then 1 else 0)
        invariant forall i, c :: pivot_row <= i < rows && 0 <= c < col ==> M[i][c] == 0
        invariant forall x: seq<int> :: (|x| == cols && is_binary_vector(x)) ==> (is_solution(matrix, b, x) <==> is_solution(M, B, x))
        decreases cols - col
    {
        var p := pivot_row;
        while p < rows && M[p][col] == 0
            invariant pivot_row <= p <= rows
            invariant forall i :: pivot_row <= i < p ==> M[i][col] == 0
            decreases rows - p
        {
            p := p + 1;
        }

        if p < rows {
            assert M[p][col] == 0 || M[p][col] == 1;
            assert M[p][col] == 1;
            var M0 := M;
            var B0 := B;
            M, B := eliminate_column(matrix, b, M0, B0, rows, cols, pivot_row, col, p);

            var old_pivot_cols := pivot_cols;
            var old_col_to_row := col_to_row;
            var old_pivot_row := pivot_row;

            pivot_cols := pivot_cols + [col];
            col_to_row := col_to_row[col := pivot_row];
            pivot_row := pivot_row + 1;

            forall r | 0 <= r < pivot_row
                ensures 0 <= pivot_cols[r] < col + 1
                ensures col_to_row[pivot_cols[r]] == r
            {
                if r < old_pivot_row {
                    assert pivot_cols[r] == old_pivot_cols[r];
                    assert old_pivot_cols[r] < col;
                } else {
                    assert pivot_cols[r] == col;
                }
            }

            forall r, i | 0 <= r < pivot_row && 0 <= i < rows
                ensures M[i][pivot_cols[r]] == (if i == r then 1 else 0)
            {
                if r < old_pivot_row {
                    assert pivot_cols[r] == old_pivot_cols[r];
                    assert 0 <= old_pivot_cols[r] < col;
                    assert M[i][old_pivot_cols[r]] == M0[i][old_pivot_cols[r]];
                } else {
                    assert r == old_pivot_row;
                    assert pivot_cols[r] == col;
                }
            }

            forall i, c | pivot_row <= i < rows && 0 <= c < col + 1
                ensures M[i][c] == 0
            {
                if c < col {
                    assert M[i][c] == M0[i][c];
                } else {
                    assert c == col;
                    assert i != old_pivot_row;
                }
            }
        }
        col := col + 1;
    }

    var chk := pivot_row;
    while chk < rows
        invariant pivot_row <= chk <= rows
        invariant forall i :: pivot_row <= i < chk ==> B[i] == 0
        decreases rows - chk
    {
        if B[chk] == 1 {
            lemma_inconsistent_row_no_solution(matrix, b, M, B, rows, cols, chk);
            return None;
        }
        assert B[chk] == 0 || B[chk] == 1;
        chk := chk + 1;
    }

    var x := build_solution(B, col_to_row, cols);
    lemma_build_solution_correct(matrix, b, M, B, rows, cols, pivot_row, pivot_cols, col_to_row);
    return Some(x);
}
