  SortedSlice(s, 0, n1);
  SortedSlice(s, n1 + 1, |s|);
  assert |s[0..n1]| == n1;
  assert |s[n1+1..|s|]| == |s| - n1 - 1;
  var l := Build(s[0..n1], b - 1);
  var r := Build(s[n1+1..|s|], b - 1);
  JoinLemma(s, n1, l, r, red);
  t := Some(Node(s[n1], red, l, r));
}

method Build(s: seq<int>, b: nat) returns (t: Option<Node>)
  requires sorted(s)
  requires b >= 1
  requires minSize(b) <= |s| <= maxSize(b)
  ensures is_llrbt_opt(t)
  ensures view_opt(t) == elems(s)
  ensures bh_opt(t) == b
  ensures is_black_opt(t)
  decreases b, 1
{
  if b == 1 {
    assert |s| == 0;
    assert elems(s) == {};
    t := None;
    return;
  }
  var L := minSize(b - 1);
  var U := maxSize(b - 1);
  SizeLemma(b - 1);
  assert minSize(b) == 2 * L + 1;
  assert maxSize(b) == 3 * U + 2;
  var n := |s|;
  if n <= 2 * U + 1 {
    var n1 := if L >= n - 1 - U then L else n - 1 - U;
    assert L <= n1 <= U;
    assert L <= n - n1 - 1 <= U;
    t := BuildPair(s, b, n1, false);
  } else {
    var m := n - 2;
    var n1 := if L >= m - 2 * U then L else m - 2 * U;
    var rest := m - n1;
    var n2 := if L >= rest - U then L else rest - U;
    var j := n1 + 1 + n2;
    assert L <= n1 <= U;
    assert L <= n2 <= U;
    assert L <= n - j - 1 <= U;
    assert j < n;
    SortedSlice(s, 0, j);
    assert |s[0..j]| == j;
    var inner := BuildPair(s[0..j], b, n1, true);
    SortedSlice(s, j + 1, |s|);
    assert |s[j+1..|s|]| == n - j - 1;
    var c := Build(s[j+1..|s|], b - 1);
    JoinLemma(s, j, inner, c, false);
    t := Some(Node(s[j], false, inner, c));
  }
}

method delete(tree: Option<Node>, v: int) returns (res: Option<Node>)
    requires is_llrbt_opt(tree)
    ensures 
        // Functional Correctness
        view_opt(res) == view_opt(tree) - {v}
    ensures
        // Invariant Maintenance
        is_llrbt_opt(res)
{
  var s := ToSeqEx(tree, v);
  var b: nat := 1;
  while maxSize(b) < |s|
    invariant b >= 1
    invariant minSize(b) <= |s|
    decreases |s| - maxSize(b)
  {
    SizeLemma(b);
    assert maxSize(b + 1) == 3 * maxSize(b) + 2;
    assert minSize(b + 1) == 2 * minSize(b) + 1;
    b := b + 1;
  }
  res := Build(s, b);
}

