    ensures RotateLeft(h).is_bst()
    ensures RotateLeft(h).view() == h.view()
{
    match h.right
    case None =>
    case Some(r) =>
        var q := Node(h.val, true, h.left, r.left);

        assert r.is_bst();
        assert forall x :: x in view_opt(h.left) ==> x < h.val;
        assert forall x :: x in r.view() ==> x > h.val;
        assert forall x :: x in view_opt(r.left) ==> x < r.val;
        assert forall x :: x in view_opt(r.left) ==> x > h.val;
        assert h.val < r.val;

        assert q.view() ==
            view_opt(h.left) + view_opt(r.left) + {h.val};
        assert forall x :: x in view_opt(h.left) ==> x < h.val;
        assert forall x :: x in view_opt(r.left) ==> x > h.val;
        assert q.is_bst();

        assert forall x :: x in q.view() ==> x < r.val;
        assert forall x :: x in view_opt(r.right) ==> x > r.val;
        assert RotateLeft(h) ==
            Node(r.val, h.is_red, Some(q), r.right);
}

lemma RotateRightBst(h: Node)
    requires h.is_bst()
