lemma {:vcs_split_on_every_assert} RawInsertCorrect(
    t: Option<Node>, x: int
)
    requires is_llrbt_opt(t)
    ensures is_llrbt_opt(RawInsert(t, x))
    ensures view_opt(RawInsert(t, x)) == view_opt(t) + {x}
    ensures
        BHOpt(RawInsert(t, x)) == BHOpt(t)
        ||
        (
            BHOpt(RawInsert(t, x)) == BHOpt(t) + 1
            && IsRedOpt(t)
            && IsRedOpt(LeftOpt(t))
        )
    ensures
        !IsRedOpt(t) && IsRedOpt(RawInsert(t, x)) ==>
            !IsRedOpt(LeftOpt(RawInsert(t, x))) &&
            !IsRedOpt(RightOpt(RawInsert(t, x)))
    decreases t
{
    match t
    case None =>
        assert view_opt(RawInsert(t, x)) == {x};
        assert BHOpt(RawInsert(t, x)) == BHOpt(t);

    case Some(n) =>
        assert n.is_bst();
        assert n.black_height() != -1;
        assert n.satisfies_red_props();

        if x < n.val {
            assert is_llrbt_opt(n.left);
            RawInsertCorrect(n.left, x);

            var q := RawInsert(n.left, x);

            if BHOpt(q) != BHOpt(n.left) {
                assert IsRedOpt(n.left);
                assert IsRedOpt(LeftOpt(n.left));
                assert false;
            }
            assert BHOpt(q) == BHOpt(n.left);

            var h := Node(n.val, n.is_red, q, n.right);

            assert forall y :: y in view_opt(q) ==> y < n.val;
            assert h.is_bst();
            assert h.black_height() != -1;
            assert RedPropsOpt(h.left);
            assert RedPropsOpt(h.right);
            assert !IsRedOpt(h.right);
            assert
                IsRedOpt(h.left) &&
                IsRedOpt(LeftOpt(h.left))
                ==> !IsRedOpt(h.right);

            BalanceCorrect(h);

            assert RawInsert(t, x) == Some(Balance(h));
            assert Balance(h).view() == n.view() + {x};

            if Balance(h).black_height() != h.black_height() {
                assert n.is_red;
                assert IsRedOpt(h.left);
                assert
                    IsRedOpt(LeftOpt(h.left)) ||
                    IsRedOpt(h.right);

                if !IsRedOpt(n.left) {
                    assert IsRedOpt(q);
                    assert !IsRedOpt(LeftOpt(q));
                    assert !IsRedOpt(RightOpt(q));
                    assert !IsRedOpt(h.right);
                    assert false;
                }
            }

        } else if x > n.val {
            assert is_llrbt_opt(n.right);
            RawInsertCorrect(n.right, x);

            var q := RawInsert(n.right, x);

            if BHOpt(q) != BHOpt(n.right) {
                assert IsRedOpt(n.right);
                assert false;
            }
            assert BHOpt(q) == BHOpt(n.right);

            var h := Node(n.val, n.is_red, n.left, q);

            assert forall y :: y in view_opt(q) ==> y > n.val;
            assert h.is_bst();
            assert h.black_height() != -1;
            assert RedPropsOpt(h.left);
            assert RedPropsOpt(h.right);

            if IsRedOpt(h.right) {
                assert !IsRedOpt(n.right);
                assert !IsRedOpt(LeftOpt(q));
                assert !IsRedOpt(RightOpt(q));
            }

            assert
                IsRedOpt(n.left)
                ==> !IsRedOpt(LeftOpt(n.left));
            assert
                !(IsRedOpt(h.left) &&
                  IsRedOpt(LeftOpt(h.left)));
            assert
                IsRedOpt(h.left) &&
                IsRedOpt(LeftOpt(h.left))
                ==> !IsRedOpt(h.right);

            BalanceCorrect(h);

            assert RawInsert(t, x) == Some(Balance(h));
            assert Balance(h).view() == n.view() + {x};

            if Balance(h).black_height() != h.black_height() {
                assert n.is_red;
                assert IsRedOpt(h.left);
                assert IsRedOpt(n.left);
            }

        } else {
            assert RawInsert(t, x) == t;
            assert x in n.view();
            assert n.view() + {x} == n.view();
        }
}

