method balance(h: Node) returns (r: Node)
    requires h.is_bst()
    requires is_llrbt_opt(h.left)
    requires is_llrbt_opt(h.right)
    requires opt_bh(h.left) == opt_bh(h.right)
    requires opt_bh(h.left) != -1
    requires root_safe(h.right)
    requires !opt_red(h.left) || root_safe(h.left) || !opt_red(h.right)
    ensures r.view() == h.view()
    ensures r.is_llrbt()
    ensures
        (!h.is_red ||
          (root_safe(h.left) &&
           !(opt_red(h.left) && opt_red(h.right))))
        ==> r.black_height() == h.black_height()
    ensures !h.is_red ==> root_safe(Some(r))
{
    if opt_red(h.right) && !opt_red(h.left) {
        var q := h.right.value;

        assert root_safe(Some(q));
        assert !opt_red(q.left);
        assert q.black_height() == opt_bh(q.left);
        assert opt_bh(q.left) == opt_bh(q.right);

        var a := Node(h.val, true, h.left, q.left);
        assert a.view() == view_opt(h.left) + view_opt(q.left) + {h.val};
        assert a.is_bst();
        assert a.black_height() == opt_bh(h.left);
        assert a.satisfies_red_props();
        assert a.is_llrbt();

        r := Node(q.val, h.is_red, Some(a), q.right);

        assert r.view() == h.view();
        assert r.is_bst();
        assert r.black_height() != -1;
        assert r.satisfies_red_props();
        assert r.is_llrbt();
        return;
    }

    if opt_red(h.left) &&
       h.left.value.left.Some? &&
       h.left.value.left.value.is_red
    {
        var q := h.left.value;
        var p := q.left.value;

        assert !opt_red(h.right);
        assert !opt_red(q.right);
        assert !opt_red(p.left);
        assert p.black_height() == opt_bh(p.left);
        assert opt_bh(p.left) == opt_bh(p.right);
        assert q.black_height() == p.black_height();
        assert q.black_height() == opt_bh(q.right);
        assert q.black_height() == opt_bh(h.right);

        var lp := Node(p.val, false, p.left, p.right);
        assert lp.view() == p.view();
        assert lp.is_bst();
        assert lp.black_height() == p.black_height() + 1;
        assert lp.satisfies_red_props();
        assert lp.is_llrbt();

        var rp := Node(h.val, false, q.right, h.right);
        assert rp.view() == view_opt(q.right) + view_opt(h.right) + {h.val};
        assert rp.is_bst();
        assert rp.black_height() == q.black_height() + 1;
        assert rp.satisfies_red_props();
        assert rp.is_llrbt();

        r := Node(q.val, !h.is_red, Some(lp), Some(rp));

        assert r.view() == h.view();
        assert r.is_bst();
        assert r.black_height() != -1;
        assert r.satisfies_red_props();
        assert r.is_llrbt();
        return;
    }

    if opt_red(h.left) && opt_red(h.right) {
        var l := h.left.value;
        var q := h.right.value;

        assert root_safe(Some(l));
        assert root_safe(Some(q));
        assert !opt_red(l.left);
        assert !opt_red(q.left);
        assert !opt_red(l.right);
        assert !opt_red(q.right);

        var lb := Node(l.val, false, l.left, l.right);
        var rb := Node(q.val, false, q.left, q.right);

        assert lb.view() == l.view();
        assert rb.view() == q.view();
        assert lb.is_llrbt();
        assert rb.is_llrbt();
        assert lb.black_height() == l.black_height() + 1;
        assert rb.black_height() == q.black_height() + 1;

        r := Node(h.val, !h.is_red, Some(lb), Some(rb));

        assert r.view() == h.view();
        assert r.is_bst();
        assert r.black_height() != -1;
        assert r.satisfies_red_props();
        assert r.is_llrbt();
        return;
    }

    r := h;

    assert !opt_red(h.right);
    assert !opt_red(h.left) || root_safe(h.left);
    assert h.black_height() != -1;
    assert h.satisfies_red_props();
    assert h.is_llrbt();
