method balance(h: Node) returns (r: Node)
    requires h.is_bst()
    requires is_llrbt_opt(h.left)
    requires is_llrbt_opt(h.right)
    requires opt_bh(h.left) == opt_bh(h.right)
    requires opt_bh(h.left) != -1
    requires root_safe(h.right)
    requires !opt_red(h.left) || root_safe(h.left) || !opt_red(h.right)
    ensures r.view() == h.view()
    ensures r.is_llrbt()
    ensures
        (!h.is_red ||
          (root_safe(h.left) &&
           !(opt_red(h.left) && opt_red(h.right))))
        ==> r.black_height() == h.black_height()
    ensures !h.is_red ==> root_safe(Some(r))
