        assert match q.right {
            case Some(qr) => qr.is_bst()
            case None => true
        };
        assert forall x :: x in a.view() ==> x < q.val;
        assert forall x :: x in view_opt(q.right) ==> x > q.val;
        assert r.is_bst();

