        assert !opt_red(a.left);
        assert r.satisfies_red_props();
        assert r.is_llrbt();

        assert h.black_height()
            == opt_bh(h.left) + (if h.is_red then 0 else 1);
        assert r.black_height() == h.black_height();

        if !h.is_red {
            assert !r.is_red;
            assert root_safe(Some(r));
