        assert lp.is_bst();
        assert lp.black_height() == p.black_height() + 1;
        assert lp.satisfies_red_props();
        assert lp.is_llrbt();

        var rp := Node(h.val, false, q.right, h.right);

        assert rp.view()
            == view_opt(q.right) + view_opt(h.right) + {h.val};
        assert rp.is_bst();
        assert rp.black_height() == q.black_height() + 1;
        assert rp.black_height() != -1;
        assert rp.satisfies_red_props();
        assert rp.is_llrbt();

