method insert_internal(tree: Option<Node>, v: int) returns (res: Node)
    requires is_llrbt_opt(tree)
    ensures res.view() == view_opt(tree) + {v}
    ensures res.is_llrbt()
    ensures root_safe(tree)
         ==> res.black_height() == opt_bh(tree)
    ensures !opt_red(tree)
         ==> root_safe(Some(res))
    decreases tree
{
    match tree
    case None =>
        res := Node(v, true, None, None);
        assert res.view() == {v};
        assert res.is_bst();
        assert res.black_height() == 1;
        assert res.satisfies_red_props();
        assert res.is_llrbt();
        assert root_safe(Some(res));

    case Some(n) =>
        llrbt_children(n);

        if v == n.val {
            res := n;
            assert n.view() + {v} == n.view();
            return;
        }

        if v < n.val {
            var nl := insert_internal(n.left, v);

            assert nl.view() == view_opt(n.left) + {v};
            assert nl.black_height() == opt_bh(n.left);

            forall x | x in nl.view()
                ensures x < n.val
            {
                if x == v {
                    assert v < n.val;
                } else {
                    assert x in view_opt(n.left);
                }
            }

            assert root_safe(n.right);
            assert opt_bh(Some(nl)) == opt_bh(n.right);

            var h := Node(n.val, n.is_red, Some(nl), n.right);

            assert h.view() == n.view() + {v};
            assert h.is_bst();
            assert is_llrbt_opt(h.left);
            assert is_llrbt_opt(h.right);
            assert opt_bh(h.left) == opt_bh(h.right);
            assert opt_bh(h.left) != -1;
            assert root_safe(h.right);
            assert
                !opt_red(h.left) ||
                root_safe(h.left) ||
                !opt_red(h.right);

            if root_safe(Some(n)) {
                if n.is_red {
                    assert !opt_red(n.left);
                    assert !opt_red(n.right);
                    assert root_safe(Some(nl));
                    assert
                        root_safe(h.left) &&
                        !(opt_red(h.left) && opt_red(h.right));
                }
            }

            res := balance(h);

            assert res.view() == n.view() + {v};

            if root_safe(Some(n)) {
                assert res.black_height() == h.black_height();
                assert h.black_height() == n.black_height();
            }

            if !n.is_red {
                assert !h.is_red;
                assert root_safe(Some(res));
            }
        } else {
            var nr := insert_internal(n.right, v);

            assert nr.view() == view_opt(n.right) + {v};
            assert nr.black_height() == opt_bh(n.right);
            assert root_safe(Some(nr));

            forall x | x in nr.view()
                ensures x > n.val
            {
                if x == v {
                    assert v > n.val;
                } else {
                    assert x in view_opt(n.right);
                }
            }

            assert opt_bh(n.left) == opt_bh(Some(nr));

            var h := Node(n.val, n.is_red, n.left, Some(nr));

            assert h.view() == n.view() + {v};
            assert h.is_bst();
            assert is_llrbt_opt(h.left);
            assert is_llrbt_opt(h.right);
            assert opt_bh(h.left) == opt_bh(h.right);
            assert opt_bh(h.left) != -1;
            assert root_safe(h.right);
            assert
