code:
function opt_red(t: Option<Node>): bool {
    match t
    case Some(n) => n.is_red
    case None => false
}

ghost function opt_bh(t: Option<Node>): int {
    match t
    case Some(n) => n.black_height()
    case None => 1
}

ghost predicate root_safe(t: Option<Node>) {
    match t
    case None => true
    case Some(n) => !n.is_red || !opt_red(n.left)
}

lemma bh_positive(n: Node)
    requires n.black_height() != -1
    ensures n.black_height() >= 1
    decreases n
{
    var lh := opt_bh(n.left);
    var rh := opt_bh(n.right);

    assert n.black_height() ==
        if lh != -1 && rh != -1 && lh == rh then
            if !n.is_red then lh + 1 else lh
        else
            -1;

    assert lh != -1 && rh != -1 && lh == rh;

    match n.left
    case None =>
        assert lh == 1;
    case Some(l) =>
        assert lh == l.black_height();
        bh_positive(l);
        assert lh >= 1;

    if n.is_red {
        assert n.black_height() == lh;
    } else {
        assert n.black_height() == lh + 1;
    }
}

lemma opt_bh_positive(t: Option<Node>)
    requires is_llrbt_opt(t)
    ensures opt_bh(t) >= 1
    decreases t
{
    match t
    case None =>
        assert opt_bh(t) == 1;
    case Some(n) =>
        assert n.black_height() != -1;
        bh_positive(n);
        assert opt_bh(t) == n.black_height();
}

lemma llrbt_children(n: Node)
    requires n.is_llrbt()
    ensures is_llrbt_opt(n.left)
    ensures is_llrbt_opt(n.right)
    ensures root_safe(n.left)
    ensures root_safe(n.right)
    ensures opt_bh(n.left) == opt_bh(n.right)
    ensures opt_bh(n.left) != -1
    ensures opt_bh(n.left) >= 1
    ensures opt_bh(n.right) >= 1
