    ensures forall x :: x in view_opt(n.left) ==> x < n.val
    ensures forall x :: x in view_opt(n.right) ==> x > n.val
{
    opt_bh_positive(n.left);
    opt_bh_positive(n.right);
    bh_positive(n);
}

lemma blacken_red(n: Node)
    requires n.is_llrbt()
    requires n.is_red
    ensures Node(n.val, false, n.left, n.right).view() == n.view()
    ensures Node(n.val, false, n.left, n.right).is_llrbt()
    ensures Node(n.val, false, n.left, n.right).black_height()
