method fixup_rotate_left(node: Node) returns (res: Node)
    requires node.is_bst()
    requires node.right.Some? && node.right.value.is_red
    ensures res.left.Some?
    ensures res.is_bst()
    ensures res.view() == node.view()
    ensures res.black_height() == node.black_height()
    ensures res.is_red == node.is_red
    ensures res.left.value.is_red
{
    var right := node.right.value;

    ghost var a := option_view(node.left);
    ghost var b := option_view(right.left);
    ghost var c := option_view(right.right);

    node_bst_form(node);
    assert option_is_bst(node.left);
    assert below(a, node.val);
    assert option_is_bst(node.right);
    assert above(right.view(), node.val);
    assert right.is_bst();

    node_bst_form(right);
    assert option_is_bst(right.left);
    assert below(b, right.val);
    assert option_is_bst(right.right);
    assert above(c, right.val);

    root_in_view(right);
    assert node.val < right.val;

    node_view_form(right);
    assert right.view() == b + c + {right.val};

    forall x | x in b
        ensures x > node.val
    {
        assert x in right.view();
    }
    assert above(b, node.val);

    forall x | x in a
        ensures x < right.val
    {
        assert x < node.val;
    }
    assert below(a, right.val);

    var new_left := Node(node.val, true, node.left, right.left);

    node_bst_form(new_left);
    assert option_is_bst(new_left.left);
    assert below(option_view(new_left.left), new_left.val);
    assert option_is_bst(new_left.right);
    assert above(option_view(new_left.right), new_left.val);
    assert new_left.is_bst();

    node_view_form(new_left);
    assert new_left.view() == a + b + {node.val};

    forall x | x in new_left.view()
        ensures x < right.val
    {
        if x in a {
            assert x < right.val;
        } else if x in b {
            assert x < right.val;
        } else {
            assert x == node.val;
        }
    }
    assert below(new_left.view(), right.val);

