        right.val,
        node.is_red,
        Some(new_left),
        right.right);

    node_bst_form(res);
    assert option_is_bst(res.left);
    assert below(option_view(res.left), res.val);
    assert option_is_bst(res.right);
    assert above(option_view(res.right), res.val);
    assert res.is_bst();

    node_view_form(res);
    assert res.view() == (a + b + {node.val}) + c + {right.val};

    node_view_form(node);
    assert node.view() == a + (b + c + {right.val}) + {node.val};

    rotation_set_identity(a, b, c, node.val, right.val);
    assert res.view() == node.view();

    ghost var ah := option_black_height(node.left);
    ghost var bh := option_black_height(right.left);
    ghost var ch := option_black_height(right.right);

    node_black_height_form(right);
    assert right.black_height()
        == combine_black_height(true, bh, ch);

    node_black_height_form(new_left);
    assert new_left.black_height()
        == combine_black_height(true, ah, bh);

    node_black_height_form(node);
    assert node.black_height()
        == combine_black_height(
            node.is_red,
            ah,
            combine_black_height(true, bh, ch));

    node_black_height_form(res);
    assert res.black_height()
        == combine_black_height(
            node.is_red,
            combine_black_height(true, ah, bh),
            ch);

    rotation_black_height_identity(node.is_red, ah, bh, ch);
    assert res.black_height() == node.black_height();

    assert res.left.Some?;
    assert res.is_red == node.is_red;
    assert res.left.value.is_red;
