lemma rr_expose(n: Node)
    ensures n.view() ==
        rr_view(n.left) + rr_view(n.right) + {n.val}
    ensures n.is_bst() ==
        ((forall x :: x in rr_view(n.left) ==> x < n.val) &&
         rr_bst(n.left) &&
         (forall x :: x in rr_view(n.right) ==> x > n.val) &&
         rr_bst(n.right))
    ensures n.black_height() ==
        (if rr_black_height(n.left) != -1 &&
            rr_black_height(n.right) != -1 &&
            rr_black_height(n.left) == rr_black_height(n.right)
         then
            if !n.is_red
            then rr_black_height(n.left) + 1
            else rr_black_height(n.left)
         else -1)
