lemma rr_rotation_black_height(node: Node)
    requires node.left.Some?
    requires node.left.value.is_red
    ensures
        Node(
            node.left.value.val,
            node.is_red,
            node.left.value.left,
            Some(Node(
                node.val,
                true,
                node.left.value.right,
                node.right))
        ).black_height() == node.black_height()
{
    var x := node.left.value;
    var newRight := Node(node.val, true, x.right, node.right);
    var rotated := Node(x.val, node.is_red, x.left, Some(newRight));

    assert node.left == Some(x);
    assert x.is_red;

    rr_expose(x);
    rr_expose(node);
    rr_expose(newRight);
    rr_expose(rotated);

    var a := rr_black_height(x.left);
    var b := rr_black_height(x.right);
    var d := rr_black_height(node.right);

    assert rr_black_height(node.left) == x.black_height();
    assert rr_black_height(newRight.left) == b;
    assert rr_black_height(newRight.right) == d;
    assert rr_black_height(rotated.left) == a;
    assert rr_black_height(rotated.right) == newRight.black_height();

    assert x.black_height() ==
        (if a != -1 && b != -1 && a == b then a else -1);

    assert newRight.black_height() ==
        (if b != -1 && d != -1 && b == d then b else -1);

    if a != -1 && b != -1 && d != -1 && a == b && b == d {
        assert x.black_height() == a;
        assert newRight.black_height() == a;

        assert node.black_height() ==
            (if !node.is_red then a + 1 else a);
        assert rotated.black_height() ==
            (if !node.is_red then a + 1 else a);
    } else {
        if node.black_height() != -1 {
            assert rr_black_height(node.left) != -1;
            assert d != -1;
            assert rr_black_height(node.left) == d;

            assert x.black_height() != -1;
            assert x.black_height() == d;

            assert a != -1;
            assert b != -1;
            assert a == b;
            assert b == d;
            assert false;
        }
        assert node.black_height() == -1;

        if rotated.black_height() != -1 {
            assert a != -1;
            assert newRight.black_height() != -1;
            assert a == newRight.black_height();

            assert b != -1;
            assert d != -1;
            assert b == d;
            assert a == b;
            assert false;
        }
        assert rotated.black_height() == -1;
    }
}

method fixup_rotate_right(node: Node) returns (res: Node)
    requires node.is_bst()
