    var newRight := Node(node.val, true, x.right, node.right);
    res := Node(x.val, node.is_red, x.left, Some(newRight));

    assert node.left == Some(x);
    assert res.right == Some(newRight);

    rr_expose(node);
    rr_expose(x);
    rr_expose(newRight);
    rr_expose(res);

    assert rr_view(node.left) == x.view();
    assert rr_view(res.right) == newRight.view();

    assert rr_bst(node.left);
    assert x.is_bst();

    assert forall z :: z in rr_view(node.left) ==> z < node.val;
    assert forall z :: z in rr_view(node.right) ==> z > node.val;

    assert x.val in x.view();
    assert x.val in rr_view(node.left);
    assert x.val < node.val;

    assert forall z :: z in rr_view(x.left) ==> z < x.val;
    assert forall z :: z in rr_view(x.right) ==> z > x.val;
    assert rr_bst(x.left);
    assert rr_bst(x.right);

    forall z | z in rr_view(x.right)
        ensures z < node.val
    {
        assert z in x.view();
        assert z in rr_view(node.left);
    }

    assert rr_bst(newRight.left);
    assert rr_bst(newRight.right);

    assert forall z :: z in rr_view(newRight.left) ==> z < newRight.val;
    assert forall z :: z in rr_view(newRight.right) ==> z > newRight.val;
    assert newRight.is_bst();

    assert rr_bst(res.left);
    assert rr_bst(res.right);

    assert forall z :: z in rr_view(res.left) ==> z < res.val;

    forall z | z in newRight.view()
        ensures z > x.val
    {
        if z in rr_view(newRight.left) {
            assert z in rr_view(x.right);
            assert z > x.val;
        } else if z == newRight.val {
            assert z == node.val;
            assert z > x.val;
        } else {
            assert z in rr_view(newRight.right);
            assert z in rr_view(node.right);
            assert z > node.val;
            assert node.val > x.val;
        }
    }

    assert forall z :: z in rr_view(res.right) ==> z > res.val;
    assert res.is_bst();

    rr_rearrange_sets(
        rr_view(x.left),
        rr_view(x.right),
        rr_view(node.right),
        x.val,
        node.val);

    assert newRight.view() ==
        rr_view(x.right) + rr_view(node.right) + {node.val};
    assert res.view() ==
        rr_view(x.left) + newRight.view() + {x.val};
    assert x.view() ==
        rr_view(x.left) + rr_view(x.right) + {x.val};
    assert node.view() ==
        x.view() + rr_view(node.right) + {node.val};
    assert res.view() == node.view();

    rr_rotation_black_height(node);
    assert res.black_height() == node.black_height();

    assert res.is_red == node.is_red;
    assert res.right.Some?;
    assert res.right.value == newRight;
    assert res.right.value.is_red;
}

