    assert forall k :: 0 <= k < |sub| ==> t[k] == sub[k];
    assert t[|t|-1] == i;
    forall k: int | 0 <= k < |t|
        ensures 0 <= t[k] < |s|
    {
    }
    forall k: int, m: int | 0 <= k < m < |t|
        ensures t[k] < t[m] && s[t[k]] < s[t[m]]
    {
        if m == |t| - 1 {
            if k < |sub| - 1 {
                assert sub[k] < sub[|sub|-1];
                assert s[sub[k]] < s[sub[|sub|-1]];
            }
        }
    }
