method longest_increasing_subsequence(s: seq<int>) returns (result: int)
    requires |s| <= 0x7FFFFFFFFFFFFFFF
    ensures result >= 0
    ensures
        forall sub: seq<int> :: is_valid_is(s, sub) && |sub| > 0 ==> |sub| <= result
    ensures
        exists sub: seq<int> :: is_valid_is(s, sub) && |sub| == result
{
    var n := |s|;
    var dp: seq<int> := [];
    ghost var wit: seq<seq<int>> := [];
    var i := 0;
    while i < n
        invariant 0 <= i <= n
        invariant |dp| == i
        invariant |wit| == i
        invariant forall j :: 0 <= j < i ==> dp[j] >= 1
        invariant forall j :: 0 <= j < i ==> ends_at(s, wit[j], j) && |wit[j]| == dp[j]
        invariant forall j: int, sub: seq<int> :: 0 <= j < i && ends_at(s, sub, j) ==> |sub| <= dp[j]
    {
        var best := 1;
        ghost var bw: seq<int> := [i];
        assert ends_at(s, bw, i);
        var j := 0;
        while j < i
            invariant 0 <= j <= i
            invariant best >= 1
            invariant ends_at(s, bw, i) && |bw| == best
            invariant forall k :: 0 <= k < j && s[k] < s[i] ==> dp[k] + 1 <= best
        {
            if s[j] < s[i] && dp[j] + 1 > best {
                best := dp[j] + 1;
                assert ends_at(s, wit[j], j);
                extend_valid(s, wit[j], i);
                bw := wit[j] + [i];
                assert ends_at(s, bw, i);
            }
            j := j + 1;
        }
        forall sub: seq<int> | ends_at(s, sub, i)
            ensures |sub| <= best
        {
            if |sub| > 1 {
                prefix_valid(s, sub);
                var p := sub[..|sub|-1];
                var jj := sub[|sub|-2];
                assert p[|p|-1] == jj;
                assert jj < sub[|sub|-1];
                assert s[jj] < s[sub[|sub|-1]];
                assert 0 <= jj < i;
                assert ends_at(s, p, jj);
                assert |p| <= dp[jj];
            }
        }
        dp := dp + [best];
        wit := wit + [bw];
        i := i + 1;
    }

    var r := 0;
    ghost var rw: seq<int> := [];
    assert is_valid_is(s, rw);
    var k := 0;
    while k < n
        invariant 0 <= k <= n
        invariant r >= 0
        invariant is_valid_is(s, rw) && |rw| == r
        invariant forall t :: 0 <= t < k ==> dp[t] <= r
    {
        if dp[k] > r {
            r := dp[k];
            assert ends_at(s, wit[k], k);
            rw := wit[k];
        }
        k := k + 1;
    }
    forall sub: seq<int> | is_valid_is(s, sub) && |sub| > 0
        ensures |sub| <= r
    {
        var j := sub[|sub|-1];
        assert 0 <= j < n;
        assert ends_at(s, sub, j);
        assert |sub| <= dp[j];
    }
    result := r;
    assert is_valid_is(s, rw) && |rw| == result;
}

