function LIS_Ending(s: seq<int>, i: int, n: int): seq<int>
    requires 0 <= n <= i < |s|
    decreases i, n
{
    if n == 0 then
        [i]
    else
        var old := LIS_Ending(s, i, n - 1);
        if s[n - 1] < s[i] then
            var candidate := LIS_Ending(s, n - 1, n - 1) + [i];
            if |candidate| > |old| then candidate else old
        else
            old
}

function LIS_Best(s: seq<int>, n: int): seq<int>
    requires 0 <= n <= |s|
    decreases n
{
    if n == 0 then
        []
    else
        var old := LIS_Best(s, n - 1);
        var candidate := LIS_Ending(s, n - 1, n - 1);
        if |candidate| > |old| then candidate else old
}

