method IsPal(s: seq<int>, lo: int, len: int) returns (b: bool)
    requires is_valid_subrange(s, lo, len)
    ensures b == is_palindrome(s[lo .. lo + len])
{
    var t := s[lo .. lo + len];
    assert |t| == len;
    assert forall k :: 0 <= k < len ==> t[k] == s[lo + k];
    var j := 0;
    while j < len
        invariant 0 <= j <= len
        invariant forall k :: 0 <= k < j ==> t[k] == t[len - 1 - k]
        decreases len - j
    {
        if s[lo + j] != s[lo + len - 1 - j] {
            assert t[j] == s[lo + j];
            assert t[len - 1 - j] == s[lo + len - 1 - j];
            assert t[j] != t[|t| - 1 - j];
            assert !is_palindrome(t);
            return false;
        }
        assert t[j] == t[len - 1 - j];
        j := j + 1;
    }
    assert is_palindrome(t);
    return true;
}

method longest_palindromic_substring(s: seq<int>) returns (res: (int, int))
    requires
        |s| <= 1000000
    ensures
        res.0 >= 0 && res.1 >= 0
    ensures
        is_valid_subrange(s, res.0, res.1)
    ensures
        is_palindrome(s[res.0 .. res.0 + res.1])
    ensures
        forall i, len :: 
            is_valid_subrange(s, i, len) && is_palindrome(s[i .. i + len])
            ==> len <= res.1
{
    var n := |s|;
    var bs := 0;
    var bl := 0;
    assert is_palindrome(s[0 .. 0]);
    var i := 0;
    while i < n
        invariant 0 <= i <= n
        invariant is_valid_subrange(s, bs, bl)
        invariant is_palindrome(s[bs .. bs + bl])
        invariant forall i', l' :: 0 <= i' < i && is_valid_subrange(s, i', l') && is_palindrome(s[i' .. i' + l']) ==> l' <= bl
        decreases n - i
    {
        var l := 0;
        while l <= n - i
            invariant 0 <= l <= n - i + 1
            invariant is_valid_subrange(s, bs, bl)
            invariant is_palindrome(s[bs .. bs + bl])
            invariant forall i', l' :: 0 <= i' < i && is_valid_subrange(s, i', l') && is_palindrome(s[i' .. i' + l']) ==> l' <= bl
            invariant forall l' :: 0 <= l' < l && is_valid_subrange(s, i, l') && is_palindrome(s[i .. i + l']) ==> l' <= bl
            decreases n - i - l + 1
        {
            var p := IsPal(s, i, l);
            if p && l > bl {
                bs := i;
                bl := l;
            }
            l := l + 1;
        }
        i := i + 1;
    }
    res := (bs, bl);
}

