method LpsCheckPalindrome(t: seq<int>) returns (ok: bool)
    ensures ok <==> is_palindrome(t)
{
    ok := true;
    var bad := 0;
    var i := 0;

    while i < |t|
        invariant 0 <= i <= |t|
        invariant ok ==> (forall k :: 0 <= k < i ==>
            t[k] == t[|t| - 1 - k])
        invariant !ok ==> 0 <= bad < i
        invariant !ok ==> t[bad] != t[|t| - 1 - bad]
        decreases |t| - i
    {
        if ok {
            if t[i] != t[|t| - 1 - i] {
                ok := false;
                bad := i;
            } else {
                forall k | 0 <= k < i + 1
                    ensures t[k] == t[|t| - 1 - k]
                {
                    if k < i {
                        assert t[k] == t[|t| - 1 - k];
                    } else {
                        assert k == i;
                    }
                }
            }
        }

        i := i + 1;
    }

    if ok {
        assert forall k :: 0 <= k < |t| ==>
            t[k] == t[|t| - 1 - k];
        assert is_palindrome(t);
    } else {
        assert 0 <= bad < |t|;
        assert is_palindrome(t) ==>
            t[bad] == t[|t| - 1 - bad];
        assert !is_palindrome(t);
    }
}

method longest_palindromic_substring(s: seq<int>) returns (res: (int, int))
    requires
        |s| <= 1000000
    ensures
        res.0 >= 0 && res.1 >= 0
    ensures
        is_valid_subrange(s, res.0, res.1)
    ensures
        is_palindrome(s[res.0 .. res.0 + res.1])
    ensures
        forall i, len ::
            is_valid_subrange(s, i, len) &&
            is_palindrome(s[i .. i + len])
            ==> len <= res.1
{
    var bestStart := 0;
    var bestLen := 0;

    assert is_valid_subrange(s, bestStart, bestLen);
    assert is_palindrome(s[bestStart .. bestStart + bestLen]);

    var start := 0;
    while start <= |s|
        invariant 0 <= start <= |s| + 1
        invariant is_valid_subrange(s, bestStart, bestLen)
        invariant is_palindrome(
            s[bestStart .. bestStart + bestLen])
        invariant forall a, k ::
            is_valid_subrange(s, a, k) &&
            0 <= a < start &&
            is_palindrome(s[a .. a + k])
            ==> k <= bestLen
        decreases |s| + 1 - start
    {
        var len := 0;

        while len <= |s| - start
            invariant 0 <= len <= |s| - start + 1
            invariant is_valid_subrange(s, bestStart, bestLen)
            invariant is_palindrome(
                s[bestStart .. bestStart + bestLen])
            invariant forall a, k ::
                is_valid_subrange(s, a, k) &&
                0 <= a < start &&
                is_palindrome(s[a .. a + k])
                ==> k <= bestLen
            invariant forall k ::
                0 <= k < len &&
                is_palindrome(s[start .. start + k])
                ==> k <= bestLen
            decreases |s| - start + 1 - len
        {
            var previousBest := bestLen;

            assert forall a, k ::
                is_valid_subrange(s, a, k) &&
                0 <= a < start &&
                is_palindrome(s[a .. a + k])
                ==> k <= previousBest;

            assert forall k ::
                0 <= k < len &&
                is_palindrome(s[start .. start + k])
                ==> k <= previousBest;

            assert 0 <= start;
            assert 0 <= len;
            assert start + len <= |s|;

            var ok := LpsCheckPalindrome(
                s[start .. start + len]);

            if ok && len > bestLen {
                bestStart := start;
                bestLen := len;

                assert is_valid_subrange(
                    s, bestStart, bestLen);
                assert is_palindrome(
                    s[bestStart .. bestStart + bestLen]);
            }

            assert previousBest <= bestLen;
            assert is_palindrome(s[start .. start + len])
                ==> len <= bestLen;

            forall a, k |
                is_valid_subrange(s, a, k) &&
                0 <= a < start &&
                is_palindrome(s[a .. a + k])
                ensures k <= bestLen
            {
                assert k <= previousBest;
            }

            forall k |
                0 <= k < len + 1 &&
                is_palindrome(s[start .. start + k])
                ensures k <= bestLen
            {
                if k < len {
                    assert k <= previousBest;
                } else {
                    assert k == len;
                }
            }

            len := len + 1;
        }

        assert len == |s| - start + 1;

        forall k |
            is_valid_subrange(s, start, k) &&
            is_palindrome(s[start .. start + k])
            ensures k <= bestLen
        {
            assert 0 <= k;
            assert start + k <= |s|;
            assert k <= |s| - start;
            assert k < len;
        }

        forall a, k |
            is_valid_subrange(s, a, k) &&
            0 <= a < start + 1 &&
            is_palindrome(s[a .. a + k])
            ensures k <= bestLen
        {
            if a < start {
                assert k <= bestLen;
            } else {
                assert a == start;
                assert k <= bestLen;
            }
        }

        start := start + 1;
    }

    assert start == |s| + 1;

    forall a, k |
        is_valid_subrange(s, a, k) &&
        is_palindrome(s[a .. a + k])
        ensures k <= bestLen
    {
        assert 0 <= a;
        assert 0 <= k;
        assert a + k <= |s|;
        assert a <= |s|;
        assert a < start;
    }

    res := (bestStart, bestLen);
}

