predicate LpsPalAt(s: seq<int>, start: int, len: int)
{
    is_valid_subrange(s, start, len) &&
    is_palindrome(s[start .. start + len])
}

lemma LpsZero(s: seq<int>)
    ensures LpsPalAt(s, 0, 0)
{
    assert is_valid_subrange(s, 0, 0);
    assert |s[0 .. 0]| == 0;
    assert is_palindrome(s[0 .. 0]);
}

lemma LpsWeakenStarts(
    s: seq<int>,
    limit: int,
    oldBound: int,
    newBound: int)
    requires oldBound <= newBound
    requires forall a, k {:trigger LpsPalAt(s, a, k)} ::
        0 <= a < limit && LpsPalAt(s, a, k)
        ==> k <= oldBound
    ensures forall a, k {:trigger LpsPalAt(s, a, k)} ::
        0 <= a < limit && LpsPalAt(s, a, k)
        ==> k <= newBound
{
    forall a, k {:trigger LpsPalAt(s, a, k)} |
        0 <= a < limit && LpsPalAt(s, a, k)
        ensures k <= newBound
    {
        assert k <= oldBound;
    }
}

lemma LpsWeakenLengths(
    s: seq<int>,
    start: int,
    limit: int,
    oldBound: int,
    newBound: int)
    requires oldBound <= newBound
    requires forall k {:trigger LpsPalAt(s, start, k)} ::
        0 <= k < limit && LpsPalAt(s, start, k)
        ==> k <= oldBound
    ensures forall k {:trigger LpsPalAt(s, start, k)} ::
        0 <= k < limit && LpsPalAt(s, start, k)
        ==> k <= newBound
{
    forall k {:trigger LpsPalAt(s, start, k)} |
        0 <= k < limit && LpsPalAt(s, start, k)
        ensures k <= newBound
    {
        assert k <= oldBound;
    }
}

lemma LpsCurrentBound(
    s: seq<int>,
    start: int,
    len: int,
    oldBound: int,
    newBound: int,
    ok: bool)
    requires is_valid_subrange(s, start, len)
    requires ok <==>
        is_palindrome(s[start .. start + len])
    requires oldBound <= newBound
    requires ok && len > oldBound ==> len <= newBound
    ensures LpsPalAt(s, start, len) ==> len <= newBound
{
    if LpsPalAt(s, start, len) {
        assert is_palindrome(s[start .. start + len]);
        assert ok;

        if len <= oldBound {
            assert len <= newBound;
        } else {
            assert len > oldBound;
            assert len <= newBound;
        }
    }
}

lemma LpsExtendLength(
    s: seq<int>,
    start: int,
    limit: int,
    bound: int)
    requires 0 <= limit
    requires forall k {:trigger LpsPalAt(s, start, k)} ::
