method LpsCheckPalindrome(t: seq<int>) returns (ok: bool)
    ensures ok <==> is_palindrome(t)
{
    ok := true;
    var bad := 0;
    var i := 0;

    while i < |t|
        invariant 0 <= i <= |t|
        invariant ok ==> (forall k {:trigger t[k]} ::
            0 <= k < i ==>
            t[k] == t[|t| - 1 - k])
        invariant !ok ==> 0 <= bad < i
        invariant !ok ==>
            t[bad] != t[|t| - 1 - bad]
        decreases |t| - i
    {
        if ok {
            if t[i] != t[|t| - 1 - i] {
                ok := false;
                bad := i;
            } else {
                forall k {:trigger t[k]} |
                    0 <= k < i + 1
                    ensures
                        t[k] == t[|t| - 1 - k]
                {
                    if k < i {
                        assert t[k] ==
                            t[|t| - 1 - k];
                    } else {
                        assert k == i;
                    }
                }
            }
        }

        i := i + 1;
    }

    if ok {
        assert forall k {:trigger t[k]} ::
            0 <= k < |t| ==>
            t[k] == t[|t| - 1 - k];
        assert is_palindrome(t);
    } else {
        assert 0 <= bad < |t|;
        assert is_palindrome(t) ==>
            t[bad] == t[|t| - 1 - bad];
        assert !is_palindrome(t);
    }
}

method longest_palindromic_substring(s: seq<int>) returns (res: (int, int))
    requires
        |s| <= 1000000
    ensures
        res.0 >= 0 && res.1 >= 0
    ensures
        is_valid_subrange(s, res.0, res.1)
    ensures
        is_palindrome(s[res.0 .. res.0 + res.1])
    ensures
        forall i, len ::
            is_valid_subrange(s, i, len) &&
            is_palindrome(s[i .. i + len])
            ==> len <= res.1
{
    var bestStart := 0;
    var bestLen := 0;

    LpsZero(s);
    assert LpsPalAt(s, bestStart, bestLen);
    assert is_valid_subrange(
        s, bestStart, bestLen);
    assert is_palindrome(
        s[bestStart .. bestStart + bestLen]);

    var start := 0;

    while start <= |s|
        invariant 0 <= start <= |s| + 1
        invariant LpsPalAt(s, bestStart, bestLen)
        invariant forall a, k
            {:trigger LpsPalAt(s, a, k)} ::
            0 <= a < start && LpsPalAt(s, a, k)
            ==> k <= bestLen
        decreases |s| + 1 - start
    {
        var len := 0;

        while len <= |s| - start
            invariant 0 <= len <= |s| - start + 1
            invariant LpsPalAt(
                s, bestStart, bestLen)
            invariant forall a, k
                {:trigger LpsPalAt(s, a, k)} ::
                0 <= a < start &&
                LpsPalAt(s, a, k)
                ==> k <= bestLen
            invariant forall k
                {:trigger LpsPalAt(s, start, k)} ::
                0 <= k < len &&
                LpsPalAt(s, start, k)
                ==> k <= bestLen
            decreases |s| - start + 1 - len
        {
            var previousBest := bestLen;

            assert forall a, k
                {:trigger LpsPalAt(s, a, k)} ::
                0 <= a < start &&
                LpsPalAt(s, a, k)
                ==> k <= previousBest;

            assert forall k
                {:trigger LpsPalAt(s, start, k)} ::
                0 <= k < len &&
                LpsPalAt(s, start, k)
                ==> k <= previousBest;

            assert is_valid_subrange(s, start, len);

            var ok := LpsCheckPalindrome(
                s[start .. start + len]);

            assert ok <==>
                is_palindrome(
                    s[start .. start + len]);

            if ok && len > bestLen {
                bestStart := start;
                bestLen := len;

                assert is_valid_subrange(
                    s, bestStart, bestLen);
                assert is_palindrome(
                    s[bestStart ..
                      bestStart + bestLen]);
                assert LpsPalAt(
                    s, bestStart, bestLen);
            }

            assert previousBest <= bestLen;
            assert ok && len > previousBest
                ==> len <= bestLen;

            LpsCurrentBound(
                s, start, len,
                previousBest, bestLen, ok);

            LpsWeakenStarts(
                s, start,
                previousBest, bestLen);

            LpsWeakenLengths(
                s, start, len,
                previousBest, bestLen);

            LpsExtendLength(
                s, start, len, bestLen);

            len := len + 1;
        }

        assert len == |s| - start + 1;

        LpsCompleteStart(
            s, start, len, bestLen);

        LpsExtendStart(
            s, start, bestLen);

        start := start + 1;
    }

    assert start == |s| + 1;

    LpsAllStartsComplete(
        s, start, bestLen);

    forall i, len
        {:trigger is_palindrome(
            s[i .. i + len])} |
        is_valid_subrange(s, i, len) &&
        is_palindrome(s[i .. i + len])
        ensures len <= bestLen
    {
        assert LpsPalAt(s, i, len);
        assert len <= bestLen;
    }

    assert is_valid_subrange(
        s, bestStart, bestLen);
    assert is_palindrome(
        s[bestStart .. bestStart + bestLen]);

    res := (bestStart, bestLen);
}

