method matrix_multiply(A: seq<seq<int>>, B: seq<seq<int>>) returns (C: seq<seq<int>>)
    requires |A| > 0 && |B| > 0
    requires |A[0]| == |B| // cols A == rows B
    requires |A| <= 10 
    requires |B| <= 10
    requires |B[0]| <= 10
    // A is a valid n x m matrix
    requires forall i :: 0 <= i < |A| ==> |A[i]| == |B|
    // B is a valid m x k matrix
    requires forall i :: 0 <= i < |B| ==> |B[i]| == |B[0]|
    // Value bounds
    requires forall i, j :: 0 <= i < |A| && 0 <= j < |A[i]| ==> 0 <= A[i][j] <= 100
    requires forall i, j :: 0 <= i < |B| && 0 <= j < |B[i]| ==> 0 <= B[i][j] <= 100

    ensures |C| == |A|
    ensures |C| > 0 ==> |C[0]| == |B[0]|
    // Result C is valid Size(A) x Size(B[0])
    ensures is_valid_matrix(C, |A|, |B[0]|)
    // Each element is the dot product
    ensures forall i, j :: 
        (0 <= i < |C| && 0 <= j < |C[0]| ==> C[i][j] == dot_product(A[i], B, j, |B|))
{
    C := [];
    var i := 0;
    while i < |A|
        invariant 0 <= i <= |A|
        invariant |C| == i
        invariant forall r :: 0 <= r < i ==> |C[r]| == |B[0]|
        invariant forall r, c :: 0 <= r < i && 0 <= c < |B[0]| ==> C[r][c] == dot_product(A[r], B, c, |B|)
    {
        var row: seq<int> := [];
        var j := 0;
        while j < |B[0]|
            invariant 0 <= j <= |B[0]|
            invariant |row| == j
            invariant forall c :: 0 <= c < j ==> row[c] == dot_product(A[i], B, c, |B|)
        {
            var s := 0;
            var k := 0;
            while k < |B|
                invariant 0 <= k <= |B|
                invariant s == dot_product(A[i], B, j, k)
            {
                s := s + A[i][k] * B[k][j];
                k := k + 1;
            }
            row := row + [s];
            j := j + 1;
        }
        C := C + [row];
        i := i + 1;
    }
}

