    requires 0 <= c < |B[0]|
    ensures forall t :: 0 <= t < m ==> 0 <= c < |B[t]|
    ensures s == dot_product(row, B, c, m)
{
    s := 0;
    var k := 0;
    while k < m
        invariant 0 <= k <= m
        invariant forall t :: 0 <= t < k ==> 0 <= c < |B[t]|
        invariant s == dot_product(row, B, c, k)
    {
        assert |B[k]| == |B[0]|;
        assert 0 <= c < |B[k]|;
        s := s + row[k] * B[k][c];
        k := k + 1;
    }
}

