method matrix_multiply_row(row_vals: seq<int>, B_vals: seq<seq<int>>)
    returns (R: seq<int>)
    requires |B_vals| > 0
    requires |row_vals| == |B_vals|
    requires forall r :: 0 <= r < |B_vals| ==> |B_vals[r]| == |B_vals[0]|
    ensures |R| == |B_vals[0]|
    ensures forall c :: 0 <= c < |R| ==>
        R[c] == dot_product(row_vals, B_vals, c, |B_vals|)
{
    R := [];
    var c := 0;

    while c < |B_vals[0]|
        invariant 0 <= c <= |B_vals[0]|
        invariant |R| == c
        invariant forall q :: 0 <= q < c ==>
            R[q] == dot_product(row_vals, B_vals, q, |B_vals|)
        decreases |B_vals[0]| - c
    {
        assert 0 <= |B_vals| <= |row_vals|;

        assert forall r {:trigger B_vals[r]} ::
            0 <= r < |B_vals| ==> 0 <= c < |B_vals[r]| by
        {
            forall r | 0 <= r < |B_vals|
                ensures 0 <= c < |B_vals[r]|
            {
                assert |B_vals[r]| == |B_vals[0]|;
            }
        }

        var x := dot_product(row_vals, B_vals, c, |B_vals|);
        var nextR := R + [x];

        assert |nextR| == c + 1;
        assert nextR[c] == x;

        forall q | 0 <= q < c + 1
            ensures nextR[q] ==
                dot_product(row_vals, B_vals, q, |B_vals|)
        {
            if q < c {
                assert nextR[q] == R[q];
            } else {
                assert q == c;
                assert nextR[q] == x;
            }
        }

        R := nextR;
        c := c + 1;
    }
}

