datatype Vtx = Lft(l: int) | Rgt(r: int)

function CountTrue(s: seq<bool>): nat
{
  if |s| == 0 then 0 else (if s[0] then 1 else 0) + CountTrue(s[1..])
}

lemma CountTrueLe(s: seq<bool>)
  ensures CountTrue(s) <= |s|
{
  if |s| > 0 { CountTrueLe(s[1..]); }
}

lemma CountTrueAppend(s: seq<bool>, b: bool)
  ensures CountTrue(s + [b]) == CountTrue(s) + (if b then 1 else 0)
{
  if |s| == 0 {
    assert s + [b] == [b];
    assert [b][1..] == [];
  } else {
    assert (s + [b])[0] == s[0];
    assert (s + [b])[1..] == s[1..] + [b];
    CountTrueAppend(s[1..], b);
  }
}

lemma CountTrueUpdate(s: seq<bool>, w: int)
  requires 0 <= w < |s| && !s[w]
  ensures CountTrue(s[w := true]) == CountTrue(s) + 1
{
  if w == 0 {
    assert s[w := true][1..] == s[1..];
  } else {
    assert s[w := true][0] == s[0];
    assert s[w := true][1..] == s[1..][w-1 := true];
    CountTrueUpdate(s[1..], w - 1);
  }
}

function FreeCount(s: seq<int>): nat
{
  if |s| == 0 then 0 else (if s[0] == -1 then 1 else 0) + FreeCount(s[1..])
}

lemma FreeCountLe(a: seq<int>, b: seq<int>)
  requires |a| == |b|
  requires forall i :: 0 <= i < |b| && b[i] == -1 ==> a[i] == -1
  ensures FreeCount(b) <= FreeCount(a)
{
  if |a| > 0 {
    forall i | 0 <= i < |b[1..]| && b[1..][i] == -1 ensures a[1..][i] == -1 {
      assert b[1..][i] == b[i+1];
      assert a[1..][i] == a[i+1];
    }
    FreeCountLe(a[1..], b[1..]);
  }
}

lemma FreeCountLess(a: seq<int>, b: seq<int>, j: int)
  requires |a| == |b|
  requires forall i :: 0 <= i < |b| && b[i] == -1 ==> a[i] == -1
  requires 0 <= j < |a| && a[j] == -1 && b[j] != -1
  ensures FreeCount(b) < FreeCount(a)
{
  forall i | 0 <= i < |b[1..]| && b[1..][i] == -1 ensures a[1..][i] == -1 {
    assert b[1..][i] == b[i+1];
    assert a[1..][i] == a[i+1];
  }
  if j == 0 {
    FreeCountLe(a[1..], b[1..]);
  } else {
    assert a[1..][j-1] == a[j];
    assert b[1..][j-1] == b[j];
    FreeCountLess(a[1..], b[1..], j - 1);
  }
}

lemma InjCard<T, U>(X: set<T>, Y: set<U>, f: T -> U)
  requires forall x :: x in X ==> f(x) in Y
  requires forall x1, x2 :: x1 in X && x2 in X && f(x1) == f(x2) ==> x1 == x2
  ensures |X| <= |Y|
  decreases X
{
  if X != {} {
    var x :| x in X;
    InjCard(X - {x}, Y - {f(x)}, f);
  }
}

ghost function MSetK(mL: seq<int>, k: int): set<(int, int)>
  requires 0 <= k <= |mL|
{
  set u | 0 <= u < k && mL[u] >= 0 :: (u, mL[u])
}

lemma MSetKZero(mL: seq<int>)
  ensures MSetK(mL, 0) == {}
{
  forall e | e in MSetK(mL, 0) ensures false {
    var u :| 0 <= u < 0 && mL[u] >= 0 && e == (u, mL[u]);
  }
}

lemma MSetKStep(mL: seq<int>, k: int)
  requires 0 <= k < |mL|
  ensures mL[k] >= 0 ==> (k, mL[k]) !in MSetK(mL, k) && MSetK(mL, k+1) == MSetK(mL, k) + {(k, mL[k])}
  ensures mL[k] < 0 ==> MSetK(mL, k+1) == MSetK(mL, k)
{
  var A := MSetK(mL, k);
  var B := MSetK(mL, k+1);
  forall e | e in A ensures e in B && e.0 < k {
    var u :| 0 <= u < k && mL[u] >= 0 && e == (u, mL[u]);
    assert 0 <= u < k + 1 && mL[u] >= 0;
  }
  forall e | e in B ensures e in A || (mL[k] >= 0 && e == (k, mL[k])) {
    var u :| 0 <= u < k + 1 && mL[u] >= 0 && e == (u, mL[u]);
    if u < k { assert e in A; }
  }
  if mL[k] >= 0 {
    assert (k, mL[k]) in B;
  }
}

ghost predicate MInv(g: BipartiteGraph, mL: seq<int>, mR: seq<int>)
{
  |g.adj| == g.left_size && |mL| == g.left_size && |mR| == g.right_size
  && (forall u :: 0 <= u < |mL| ==> -1 <= mL[u] < |mR|)
  && (forall v :: 0 <= v < |mR| ==> -1 <= mR[v] < |mL|)
  && (forall u :: 0 <= u < |mL| && mL[u] >= 0 ==> mR[mL[u]] == u && mL[u] in g.adj[u])
  && (forall v :: 0 <= v < |mR| && mR[v] >= 0 ==> mL[mR[v]] == v)
}

ghost predicate Struct(g: BipartiteGraph, mL: seq<int>, visL: seq<bool>, visR: seq<bool>,
                       par: seq<int>, dL: seq<int>, dR: seq<int>)
{
  |mL| == g.left_size && |g.adj| == g.left_size
  && |visL| == g.left_size && |dL| == g.left_size
  && |visR| == g.right_size && |par| == g.right_size && |dR| == g.right_size
  && (forall v :: 0 <= v < |visR| && visR[v] ==>
        0 <= par[v] < |visL| && visL[par[v]] && v in g.adj[par[v]]
        && dL[par[v]] == dR[v] && dR[v] >= 0)
  && (forall u :: 0 <= u < |visL| && visL[u] && mL[u] >= 0 ==>
        mL[u] < |visR| && visR[mL[u]] && dL[u] == dR[mL[u]] + 1)
}

ghost predicate Closure(g: BipartiteGraph, mL: seq<int>, mR: seq<int>, visL: seq<bool>, visR: seq<bool>)
{
  |mL| == g.left_size && |g.adj| == g.left_size && |mR| == g.right_size
  && |visL| == g.left_size && |visR| == g.right_size
  && (forall u :: 0 <= u < |visL| && mL[u] == -1 ==> visL[u])
  && (forall u, i :: 0 <= u < |visL| && visL[u] && 0 <= i < |g.adj[u]| && 0 <= g.adj[u][i] < |visR|
        ==> visR[g.adj[u][i]])
  && (forall v :: 0 <= v < |visR| && visR[v] ==> 0 <= mR[v] < |visL| && visL[mR[v]])
}

method BFS(g: BipartiteGraph, mL: seq<int>, mR: seq<int>)
  returns (found: bool, visL: seq<bool>, visR: seq<bool>, par: seq<int>, dL: seq<int>, dR: seq<int>, fv: int)
  requires well_formed(g)
  requires MInv(g, mL, mR)
  ensures Struct(g, mL, visL, visR, par, dL, dR)
  ensures found ==> 0 <= fv < |visR| && visR[fv] && 0 <= fv < |mR| && mR[fv] == -1
  ensures !found ==> Closure(g, mL, mR, visL, visR)
{
  var L := g.left_size;
  var R := g.right_size;
  visL := [];
  dL := [];
  var queue: seq<int> := [];
  var i := 0;
  while i < L
    invariant 0 <= i <= L
    invariant |visL| == i && |dL| == i
    invariant forall x :: 0 <= x < i ==> ((visL[x] <==> mL[x] == -1) && dL[x] == 0)
    invariant forall k :: 0 <= k < |queue| ==> 0 <= queue[k] < i && visL[queue[k]]
    invariant forall x :: 0 <= x < i && visL[x] ==> x in queue
    invariant |queue| == CountTrue(visL)
  {
    if mL[i] == -1 {
      CountTrueAppend(visL, true);
      visL := visL + [true];
      queue := queue + [i];
    } else {
      CountTrueAppend(visL, false);
      visL := visL + [false];
    }
    dL := dL + [0];
    i := i + 1;
  }
  visR := seq(R, _ => false);
  par := seq(R, _ => -1);
  dR := seq(R, _ => 0);
  found := false;
  fv := -1;
  var head := 0;
  CountTrueLe(visL);
  while head < |queue| && !found
    invariant 0 <= head <= |queue| <= L
    invariant |visL| == L && |dL| == L && |visR| == R && |par| == R && |dR| == R
    invariant |queue| == CountTrue(visL)
    invariant forall k :: 0 <= k < |queue| ==> 0 <= queue[k] < L && visL[queue[k]]
    invariant forall x :: 0 <= x < L && visL[x] ==> x in queue
    invariant forall x :: 0 <= x < L && mL[x] == -1 ==> visL[x]
    invariant forall x :: 0 <= x < L && visL[x] ==> dL[x] >= 0
    invariant Struct(g, mL, visL, visR, par, dL, dR)
    invariant !found ==> forall k, jj :: 0 <= k < head && 0 <= jj < |g.adj[queue[k]]| ==> visR[g.adj[queue[k]][jj]]
    invariant !found ==> forall y :: 0 <= y < R && visR[y] ==> 0 <= mR[y] < L && visL[mR[y]]
    invariant found ==> 0 <= fv < R && visR[fv] && mR[fv] == -1
    decreases L - head
  {
    var u := queue[head];
    var j := 0;
    while j < |g.adj[u]| && !found
      invariant 0 <= j <= |g.adj[u]|
      invariant 0 <= head < |queue| <= L
      invariant u == queue[head]
      invariant |visL| == L && |dL| == L && |visR| == R && |par| == R && |dR| == R
      invariant |queue| == CountTrue(visL)
      invariant forall k :: 0 <= k < |queue| ==> 0 <= queue[k] < L && visL[queue[k]]
      invariant forall x :: 0 <= x < L && visL[x] ==> x in queue
      invariant forall x :: 0 <= x < L && mL[x] == -1 ==> visL[x]
      invariant forall x :: 0 <= x < L && visL[x] ==> dL[x] >= 0
      invariant Struct(g, mL, visL, visR, par, dL, dR)
      invariant !found ==> forall k, jj :: 0 <= k < head && 0 <= jj < |g.adj[queue[k]]| ==> visR[g.adj[queue[k]][jj]]
      invariant !found ==> forall y :: 0 <= y < R && visR[y] ==> 0 <= mR[y] < L && visL[mR[y]]
      invariant found ==> 0 <= fv < R && visR[fv] && mR[fv] == -1
      invariant !found ==> forall jj :: 0 <= jj < j ==> visR[g.adj[u][jj]]
      decreases |g.adj[u]| - j
    {
      var v := g.adj[u][j];
      if !visR[v] {
        if mR[v] == -1 {
          visR := visR[v := true];
          par := par[v := u];
          dR := dR[v := dL[u]];
          found := true;
          fv := v;
        } else {
          var w := mR[v];
          assert mL[w] == v;
          assert !visL[w];
          visR := visR[v := true];
          par := par[v := u];
          dR := dR[v := dL[u]];
          CountTrueUpdate(visL, w);
          visL := visL[w := true];
          dL := dL[w := dR[v] + 1];
          queue := queue + [w];
          CountTrueLe(visL);
        }
      }
      j := j + 1;
    }
    head := head + 1;
  }
  if !found {
    forall uu, ii | 0 <= uu < |visL| && visL[uu] && 0 <= ii < |g.adj[uu]| && 0 <= g.adj[uu][ii] < |visR|
      ensures visR[g.adj[uu][ii]]
    {
      assert uu in queue;
      var k :| 0 <= k < |queue| && queue[k] == uu;
    }
  }
}

method Augment(g: BipartiteGraph, mL0: seq<int>, mR0: seq<int>, visL: seq<bool>, visR: seq<bool>,
               par: seq<int>, dL: seq<int>, dR: seq<int>, v0: int)
  returns (mL: seq<int>, mR: seq<int>)
  requires well_formed(g)
  requires MInv(g, mL0, mR0)
  requires Struct(g, mL0, visL, visR, par, dL, dR)
  requires 0 <= v0 < |visR| && visR[v0] && mR0[v0] == -1
  ensures MInv(g, mL, mR)
  ensures FreeCount(mL) < FreeCount(mL0)
{
  var L := |mL0|;
  var R := |mR0|;
  mL, mR := mL0, mR0;
  var v := v0;
  var done := false;
  ghost var root := -1;
  while !done
    invariant |mL| == L && |mR| == R
    invariant forall x :: 0 <= x < L ==> -1 <= mL[x] < R
    invariant forall y :: 0 <= y < R ==> -1 <= mR[y] < L
    invariant forall x :: 0 <= x < L && mL[x] >= 0 ==> mR[mL[x]] == x && mL[x] in g.adj[x]
    invariant forall x :: 0 <= x < L && mL[x] == -1 ==> mL0[x] == -1
    invariant !done ==> 0 <= v < R && visR[v]
    invariant !done ==> forall y :: 0 <= y < R && y != v && mR[y] >= 0 ==> mL[mR[y]] == y
    invariant !done ==> forall x :: 0 <= x < L ==> mL[x] != v
    invariant !done ==> forall x :: 0 <= x < L && mL[x] != mL0[x] ==> visL[x] && dL[x] > dR[v]
    invariant done ==> forall y :: 0 <= y < R && mR[y] >= 0 ==> mL[mR[y]] == y
    invariant done ==> 0 <= root < L && mL0[root] == -1 && mL[root] != -1
    decreases if done then 0 else dR[v] + 1
  {
    var u := par[v];
    assert 0 <= u < L && visL[u] && dL[u] == dR[v];
    assert mL[u] == mL0[u];
    var prev := mL[u];
    if prev >= 0 {
      assert visR[prev] && dL[u] == dR[prev] + 1;
    }
    ghost var mL1, mR1 := mL, mR;
    mL := mL[u := v];
    mR := mR[v := u];
    if prev == -1 {
      done := true;
      root := u;
      forall y | 0 <= y < R && mR[y] >= 0 ensures mL[mR[y]] == y {
        if y != v {
          assert mR[y] == mR1[y];
          assert mL1[mR1[y]] == y;
          assert mR1[y] != u;
        }
      }
    } else {
      forall y | 0 <= y < R && y != prev && mR[y] >= 0 ensures mL[mR[y]] == y {
        if y != v {
          assert mR[y] == mR1[y];
          assert mL1[mR1[y]] == y;
          assert mR1[y] != u;
        }
      }
      forall x | 0 <= x < L ensures mL[x] != prev {
        if x != u && mL1[x] == prev {
          assert mR1[prev] == x;
          assert mR1[prev] == u;
        }
      }
      v := prev;
    }
  }
  FreeCountLess(mL0, mL, root);
}

lemma MaxFromCover(g: BipartiteGraph, mL: seq<int>, mR: seq<int>, visL: seq<bool>, visR: seq<bool>)
  requires well_formed(g)
  requires MInv(g, mL, mR)
  requires Closure(g, mL, mR, visL, visR)
  ensures is_max_matching(g.adj, MSetK(mL, |mL|))
{
  var L := |mL|;
  var R := |mR|;
  var m := MSetK(mL, L);
  forall e | e in m
    ensures exists i: int :: 0 <= e.0 < |g.adj| && 0 <= i < |g.adj[e.0]| && g.adj[e.0][i] == e.1
  {
    var u :| 0 <= u < L && mL[u] >= 0 && e == (u, mL[u]);
    assert mL[u] in g.adj[u];
    var i :| 0 <= i < |g.adj[u]| && g.adj[u][i] == mL[u];
    assert 0 <= e.0 < |g.adj| && 0 <= i < |g.adj[e.0]| && g.adj[e.0][i] == e.1;
  }
  assert matching_valid_edges(g.adj, m);
  forall e1, e2 | e1 in m && e2 in m && e1 != e2
    ensures e1.0 != e2.0 && e1.1 != e2.1
  {
    var u1 :| 0 <= u1 < L && mL[u1] >= 0 && e1 == (u1, mL[u1]);
    var u2 :| 0 <= u2 < L && mL[u2] >= 0 && e2 == (u2, mL[u2]);
    if u1 == u2 { assert e1 == e2; }
    if mL[u1] == mL[u2] {
      assert mR[mL[u1]] == u1 && mR[mL[u2]] == u2;
    }
  }
  assert is_disjoint(m);
  assert is_matching(g.adj, m);

  var coverL := set u | 0 <= u < L && !visL[u] :: Lft(u);
  var coverR := set v | 0 <= v < R && visR[v] :: Rgt(v);
  var cover := coverL + coverR;
  var gf: Vtx -> (int, int) := (x: Vtx) =>
    if x.Lft? then (x.l, if 0 <= x.l < |mL| then mL[x.l] else 0)
    else (if 0 <= x.r < |mR| then mR[x.r] else 0, x.r);
  forall x | x in cover ensures gf(x) in m {
    if x in coverL {
      var u :| 0 <= u < L && !visL[u] && x == Lft(u);
      assert mL[u] != -1;
      assert mL[u] >= 0;
      assert gf(x) == (u, mL[u]);
    } else {
      var v :| 0 <= v < R && visR[v] && x == Rgt(v);
      var u := mR[v];
      assert 0 <= u < L && mL[u] == v;
      assert gf(x) == (u, mL[u]);
    }
  }
  forall x1, x2 | x1 in cover && x2 in cover && gf(x1) == gf(x2) ensures x1 == x2 {
    if x1 in coverL && x2 in coverL {
      var u1 :| 0 <= u1 < L && !visL[u1] && x1 == Lft(u1);
      var u2 :| 0 <= u2 < L && !visL[u2] && x2 == Lft(u2);
      assert gf(x1).0 == u1 && gf(x2).0 == u2;
    } else if x1 in coverR && x2 in coverR {
      var v1 :| 0 <= v1 < R && visR[v1] && x1 == Rgt(v1);
      var v2 :| 0 <= v2 < R && visR[v2] && x2 == Rgt(v2);
      assert gf(x1).1 == v1 && gf(x2).1 == v2;
    } else if x1 in coverL {
      assert x2 in coverR;
      var u :| 0 <= u < L && !visL[u] && x1 == Lft(u);
      var v :| 0 <= v < R && visR[v] && x2 == Rgt(v);
      assert gf(x1) == (u, mL[u]);
      assert gf(x2) == (mR[v], v);
      assert visL[mR[v]];
      assert false;
    } else {
      assert x1 in coverR && x2 in coverL;
      var u :| 0 <= u < L && !visL[u] && x2 == Lft(u);
      var v :| 0 <= v < R && visR[v] && x1 == Rgt(v);
      assert gf(x2) == (u, mL[u]);
      assert gf(x1) == (mR[v], v);
      assert visL[mR[v]];
      assert false;
    }
  }
  InjCard(cover, m, gf);

  forall other: Matching | is_matching(g.adj, other) ensures |m| >= |other| {
    var f: (int, int) -> Vtx := (e: (int, int)) =>
      if 0 <= e.0 < |visL| && visL[e.0] then Rgt(e.1) else Lft(e.0);
    forall e | e in other ensures f(e) in cover {
      var i :| 0 <= e.0 < |g.adj| && 0 <= i < |g.adj[e.0]| && g.adj[e.0][i] == e.1;
      assert 0 <= e.1 < R;
      if visL[e.0] {
        assert visR[g.adj[e.0][i]];
        assert visR[e.1];
        assert f(e) == Rgt(e.1);
        assert Rgt(e.1) in coverR;
      } else {
        assert f(e) == Lft(e.0);
        assert Lft(e.0) in coverL;
      }
    }
    forall e1, e2 | e1 in other && e2 in other && f(e1) == f(e2) ensures e1 == e2 {
      if e1 != e2 {
        assert e1.0 != e2.0 && e1.1 != e2.1;
        assert false;
      }
    }
    InjCard(other, cover, f);
  }
}

method max_bipartite_matching(graph: BipartiteGraph) returns (size: int)
    requires well_formed(graph)
    requires size_bounded(graph)
    ensures size >= 0
    ensures exists m: Matching :: 
            is_max_matching(graph.adj, m) 
            && |m| == size
{
  var L := graph.left_size;
  var R := graph.right_size;
  var mL: seq<int> := seq(L, _ => -1);
  var mR: seq<int> := seq(R, _ => -1);
  var found := true;
  var visL: seq<bool> := [];
  var visR: seq<bool> := [];
  while found
    invariant MInv(graph, mL, mR)
    invariant !found ==> Closure(graph, mL, mR, visL, visR)
    decreases if found then FreeCount(mL) + 1 else 0
  {
    var f, vL, vR, par, dL, dR, fv := BFS(graph, mL, mR);
    if f {
      mL, mR := Augment(graph, mL, mR, vL, vR, par, dL, dR, fv);
    } else {
      found := false;
      visL, visR := vL, vR;
    }
  }
  MaxFromCover(graph, mL, mR, visL, visR);
  size := 0;
  var i := 0;
  MSetKZero(mL);
  while i < L
    invariant 0 <= i <= L
    invariant |mL| == L
    invariant size == |MSetK(mL, i)|
  {
    MSetKStep(mL, i);
    if mL[i] >= 0 {
      size := size + 1;
    }
    i := i + 1;
  }
  ghost var mm := MSetK(mL, |mL|);
  assert is_max_matching(graph.adj, mm) && |mm| == size;
}

response:
The proof uses a vertex-cover certificate (König's theorem), so it never has to reason about alternating paths globally:

- **Augmenting phase.** Kuhn's algorithm runs repeatedly. Each round does a BFS from the free left vertices and augments along parent pointers. Ghost-style distance labels prove that the augmenting walk terminates and keeps the matching consistent. Each augmentation strictly reduces the number of free left vertices, which proves the outer loop terminates.
- **Stopping condition.** When a BFS finds no free right vertex, the visited set Z is closed:
  - every free left vertex is in Z;
  - every neighbour of a left vertex in Z is in Z;
  - every right vertex in Z is matched, and its partner is in Z.
- **Optimality.** The cover is C = (Left \ Z) ∪ (Right ∩ Z). One injection maps any matching into C, so |other| ≤ |C|. Another maps C into the found matching, so |C| ≤ |m|. Together these give maximality.

