function MBM_Compatible(e: (int, int), f: (int, int)): bool
{
    e.0 != f.0 && e.1 != f.1
}

function MBM_Filter(es: seq<(int, int)>, e: (int, int)): seq<(int, int)>
    decreases |es|
{
    if |es| == 0 then
        []
    else if MBM_Compatible(e, es[0]) then
        [es[0]] + MBM_Filter(es[1..], e)
    else
        MBM_Filter(es[1..], e)
}

function MBM_Max(es: seq<(int, int)>): int
    decreases |es|
{
    if |es| == 0 then
        0
    else
        var withoutFirst := MBM_Max(es[1..]);
        var withFirst := 1 + MBM_Max(MBM_Filter(es[1..], es[0]));
        if withoutFirst >= withFirst then withoutFirst else withFirst
}

function MBM_RowEdges(row: seq<int>, u: int): seq<(int, int)>
{
    seq(|row|, i => (u, row[i]))
}

function MBM_EdgesFrom(adj: seq<seq<int>>, u: int): seq<(int, int)>
    requires 0 <= u <= |adj|
    decreases |adj| - u
{
    if u == |adj| then
        []
    else
        MBM_RowEdges(adj[u], u) + MBM_EdgesFrom(adj, u + 1)
}

