lemma MBM_FilterCharacterization(
    es: seq<(int, int)>,
    chosen: (int, int),
    e: (int, int))
    ensures e in MBM_Filter(es, chosen)
        <==> e in es && MBM_Compatible(chosen, e)
    decreases |es|
{
    if |es| > 0 {
        MBM_FilterCharacterization(es[1..], chosen, e);
        MBM_HeadTail(es, e);

        if MBM_Compatible(chosen, es[0]) {
            MBM_ConcatMember(
                [es[0]],
