lemma MBM_RowCharacterization(
    row: seq<int>,
    u: int,
    e: (int, int))
    ensures e in MBM_RowEdges(row, u)
        <==> exists i: int ::
            0 <= i < |row| && e == (u, row[i])
{
    if e in MBM_RowEdges(row, u) {
        var i :| 0 <= i < |MBM_RowEdges(row, u)|
                     && MBM_RowEdges(row, u)[i] == e;
        assert |MBM_RowEdges(row, u)| == |row|;
        assert MBM_RowEdges(row, u)[i] == (u, row[i]);
    }

    if exists i: int ::
        0 <= i < |row| && e == (u, row[i])
    {
        var i :| 0 <= i < |row| && e == (u, row[i]);
        assert MBM_RowEdges(row, u)[i] == e;
        assert e in MBM_RowEdges(row, u);
