        if exists k: int, i: int ::
            u <= k < |adj|
            && 0 <= i < |adj[k]|
            && e == (k, adj[k][i])
        {
            var k, i :| u <= k < |adj|
                         && 0 <= i < |adj[k]|
                         && e == (k, adj[k][i]);

            if k == u {
                assert e in MBM_RowEdges(adj[u], u);
            } else {
                assert u + 1 <= k;
                assert e in MBM_EdgesFrom(adj, u + 1);
            }
        }
    }
}

lemma MBM_MaxWitness(es: seq<(int, int)>)
    returns (m: Matching)
    ensures is_disjoint(m)
    ensures MBM_DrawnFrom(es, m)
    ensures |m| == MBM_Max(es)
    decreases |es|
{
    if |es| == 0 {
        m := {};
    } else {
        ghost var withoutFirst := MBM_MaxWitness(es[1..]);
        ghost var withFirst :=
            MBM_MaxWitness(MBM_Filter(es[1..], es[0]));

        if MBM_Max(es[1..])
            >= 1 + MBM_Max(MBM_Filter(es[1..], es[0]))
        {
            m := withoutFirst;

            assert MBM_DrawnFrom(es, m) by {
                forall e: (int, int) | e in m
                    ensures e in es
                {
                    assert e in es[1..];
                    MBM_HeadTail(es, e);
                }
            }
        } else {
            var first := es[0];

            assert forall e: (int, int) ::
                e in withFirst ==> MBM_Compatible(first, e) by {
                forall e: (int, int) | e in withFirst
                    ensures MBM_Compatible(first, e)
                {
                    assert e in MBM_Filter(es[1..], first);
                    MBM_FilterCharacterization(es[1..], first, e);
                }
            }

            assert first !in withFirst;
            m := withFirst + {first};
            assert |m| == |withFirst| + 1;

            assert is_disjoint(m) by {
                forall e1: (int, int), e2: (int, int)
                    | e1 in m && e2 in m && e1 != e2
                    ensures e1.0 != e2.0 && e1.1 != e2.1
                {
                    if e1 == first {
                        assert e2 in withFirst;
                        assert MBM_Compatible(first, e2);
                    } else if e2 == first {
                        assert e1 in withFirst;
                        assert MBM_Compatible(first, e1);
                    } else {
                        assert e1 in withFirst;
                        assert e2 in withFirst;
                    }
                }
            }

            assert MBM_DrawnFrom(es, m) by {
                forall e: (int, int) | e in m
                    ensures e in es
                {
                    if e != first {
                        assert e in withFirst;
                        assert e in MBM_Filter(es[1..], first);
                        MBM_FilterCharacterization(es[1..], first, e);
                        assert e in es[1..];
                        MBM_HeadTail(es, e);
                    }
                }
            }
        }
    }
}

lemma MBM_MaxUpper(es: seq<(int, int)>, m: Matching)
    requires is_disjoint(m)
    requires MBM_DrawnFrom(es, m)
    ensures |m| <= MBM_Max(es)
    decreases |es|
{
    if |es| == 0 {
        assert forall e: (int, int) :: e !in m by {
            forall e: (int, int)
                ensures e !in m
            {
                if e in m {
                    assert e in es;
                    assert false;
                }
            }
        }
        assert m == {};
    } else {
        var first := es[0];

        if first in m {
            ghost var rest := m - {first};

            assert first !in rest;
            assert |m| == |rest| + 1;
            assert is_disjoint(rest);

            assert MBM_DrawnFrom(
                MBM_Filter(es[1..], first), rest) by {
                forall e: (int, int) | e in rest
                    ensures e in MBM_Filter(es[1..], first)
                {
                    assert e in m;
                    assert e != first;
                    assert e in es;
                    MBM_HeadTail(es, e);
                    assert e in es[1..];

                    assert first.0 != e.0 && first.1 != e.1;
                    assert MBM_Compatible(first, e);
                    MBM_FilterCharacterization(es[1..], first, e);
                }
            }

            MBM_MaxUpper(
                MBM_Filter(es[1..], first),
                rest);

            assert |m|
                <= 1 + MBM_Max(MBM_Filter(es[1..], first));
        } else {
            assert MBM_DrawnFrom(es[1..], m) by {
                forall e: (int, int) | e in m
                    ensures e in es[1..]
                {
                    assert e in es;
                    MBM_HeadTail(es, e);
                    assert e != first;
                }
            }

            MBM_MaxUpper(es[1..], m);
        }
    }
}

method max_bipartite_matching(graph: BipartiteGraph) returns (size: int)
    requires well_formed(graph)
    requires size_bounded(graph)
    ensures size >= 0
    ensures exists m: Matching ::
            is_max_matching(graph.adj, m)
            && |m| == size
{
    var edges := MBM_EdgesFrom(graph.adj, 0);
    ghost var maximum := MBM_MaxWitness(edges);

    size := MBM_Max(edges);
    assert size == |maximum|;
    assert size >= 0;

    assert matching_valid_edges(graph.adj, maximum) by {
        forall edge: (int, int) | edge in maximum
            ensures exists i: int ::
                0 <= edge.0 < |graph.adj|
                && 0 <= i < |graph.adj[edge.0]|
                && graph.adj[edge.0][i] == edge.1
        {
            assert edge in edges;
            MBM_EdgeCharacterization(graph.adj, 0, edge);

            var k, i :| 0 <= k < |graph.adj|
                         && 0 <= i < |graph.adj[k]|
                         && edge == (k, graph.adj[k][i]);

            assert edge.0 == k;
            assert edge.1 == graph.adj[k][i];
        }
    }

    assert is_matching(graph.adj, maximum);

    assert forall other: Matching ::
        is_matching(graph.adj, other) ==> |maximum| >= |other| by {
        forall other: Matching | is_matching(graph.adj, other)
            ensures |maximum| >= |other|
        {
            assert MBM_DrawnFrom(edges, other) by {
                forall edge: (int, int) | edge in other
                    ensures edge in edges
                {
                    assert matching_valid_edges(graph.adj, other);

                    var i :| 0 <= edge.0 < |graph.adj|
                               && 0 <= i < |graph.adj[edge.0]|
                               && graph.adj[edge.0][i] == edge.1;

                    MBM_EdgeCharacterization(graph.adj, 0, edge);
                    assert edge == (
                        edge.0,
                        graph.adj[edge.0][i]);
                    assert edge in edges;
                }
            }

            assert is_disjoint(other);
            MBM_MaxUpper(edges, other);
            assert |other| <= MBM_Max(edges);
            assert MBM_Max(edges) == |maximum|;
        }
    }

    assert is_max_matching(graph.adj, maximum);
    assert exists m: Matching ::
        is_max_matching(graph.adj, m) && |m| == size;
}
