lemma ConcatPerm(pl: seq<int>, pr: seq<int>, m: nat, n: nat) returns (c: seq<int>)
  requires m <= n
  requires is_valid_index_permutation(pl, m)
  requires is_valid_index_permutation(pr, n - m)
  ensures is_valid_index_permutation(c, n)
  ensures forall k :: 0 <= k < m ==> c[k] == pl[k]
  ensures forall k :: m <= k < n ==> c[k] == pr[k-m] + m
{
  c := pl + seq(n - m, k requires 0 <= k < n - m => pr[k] + m);
  assert |c| == n;
  forall k | 0 <= k < m ensures c[k] == pl[k] {
  }
  forall k | m <= k < n ensures c[k] == pr[k-m] + m {
  }
  forall i | 0 <= i < n ensures 0 <= c[i] < n {
    if i < m {
      assert c[i] == pl[i];
    } else {
      assert c[i] == pr[i-m] + m;
    }
  }
  forall i, j | 0 <= i < j < n ensures c[i] != c[j] {
    if j < m {
      assert pl[i] != pl[j];
    } else if i >= m {
      assert pr[i-m] != pr[j-m];
    } else {
      assert c[i] == pl[i];
      assert c[j] == pr[j-m] + m;
    }
  }
}

lemma ComposePerm(q: seq<int>, c: seq<int>, n: nat) returns (p: seq<int>)
  requires is_valid_index_permutation(q, n)
  requires is_valid_index_permutation(c, n)
  ensures is_valid_index_permutation(p, n)
  ensures forall i :: 0 <= i < n ==> 0 <= q[i] < n && p[i] == c[q[i]]
{
  p := seq(n, i requires 0 <= i < n && 0 <= q[i] < |c| => c[q[i]]);
  forall i | 0 <= i < n ensures 0 <= p[i] < n {
    assert 0 <= q[i] < n;
  }
  forall i, j | 0 <= i < j < n ensures p[i] != p[j] {
    assert q[i] != q[j];
    if q[i] < q[j] {
      assert c[q[i]] != c[q[j]];
    } else {
      assert c[q[j]] != c[q[i]];
    }
  }
}

method merge(a: seq<int>, b: seq<int>) returns (out: seq<int>, ghost q: seq<int>)
  requires is_sorted(a) && is_sorted(b)
  ensures is_sorted(out)
  ensures |out| == |a| + |b|
  ensures is_valid_index_permutation(q, |a| + |b|)
  ensures forall k :: 0 <= k < |out| ==> out[k] == (a + b)[q[k]]
{
  var i := 0;
  var j := 0;
  out := [];
  q := [];
  while i < |a| || j < |b|
    invariant 0 <= i <= |a| && 0 <= j <= |b|
    invariant |out| == i + j == |q|
    invariant is_sorted(out)
    invariant forall k :: 0 <= k < |out| ==> (i < |a| ==> out[k] <= a[i]) && (j < |b| ==> out[k] <= b[j])
