             && |a| == |b|
             && (forall i {:trigger p[i]} ::
                   0 <= i < |a| ==> b[i] == a[p[i]]);

    var q :| is_valid_index_permutation(q, |b|)
             && |b| == |c|
             && (forall i {:trigger q[i]} ::
                   0 <= i < |b| ==> c[i] == b[q[i]]);

    assert |a| == |b|;
    assert |b| == |c|;

    var r := seq(|c|, i => p[q[i]]);

    assert |r| == |a|;

    forall i | 0 <= i < |a|
        ensures 0 <= r[i] < |a|
    {
        assert i < |b|;
        assert 0 <= q[i] < |b|;
        assert 0 <= q[i] < |a|;
        assert 0 <= p[q[i]] < |a|;
    }

    forall i, j | 0 <= i < j < |a|
        ensures r[i] != r[j]
    {
        assert i < |b|;
        assert j < |b|;
        assert 0 <= q[i] < |b|;
        assert 0 <= q[j] < |b|;
        assert q[i] != q[j];
        ValidPermutationInjective(p, |a|, q[i], q[j]);
    }

    assert is_valid_index_permutation(r, |a|);

    forall i | 0 <= i < |a|
        ensures c[i] == a[r[i]]
    {
        assert i < |b|;
        assert c[i] == b[q[i]];
        assert 0 <= q[i] < |b|;
        assert 0 <= q[i] < |a|;
        assert b[q[i]] == a[p[q[i]]];
        assert r[i] == p[q[i]];
    }

    assert |a| == |c|;

    assert exists z: seq<int> ::
        z == r
        && is_valid_index_permutation(z, |a|)
        && |a| == |c|
        && (forall i {:trigger z[i]} ::
              0 <= i < |a| ==> c[i] == a[z[i]]);

