             && |a| == |b|
             && (forall i {:trigger p[i]} ::
                   0 <= i < |a| ==> b[i] == a[p[i]]);

    var n := |a|;
    assert |b| == n;

    var r := seq(n + 1, i =>
        if i == 0 then 0 else p[i - 1] + 1);

    PrependFacts(x, a);
    PrependFacts(x, b);

    assert |r| == n + 1;
    assert |[x] + a| == n + 1;
    assert |[x] + b| == n + 1;

    forall i | 0 <= i < n + 1
        ensures 0 <= r[i] < n + 1
    {
        if i == 0 {
            assert r[i] == 0;
        } else {
            assert 0 <= i - 1 < n;
            assert 0 <= p[i - 1] < n;
            assert r[i] == p[i - 1] + 1;
        }
    }

    forall i, j | 0 <= i < j < n + 1
        ensures r[i] != r[j]
    {
        if i == 0 {
            assert r[i] == 0;
            assert 0 <= j - 1 < n;
            assert 0 <= p[j - 1] < n;
            assert r[j] == p[j - 1] + 1;
            assert 0 < r[j];
        } else {
            assert 0 <= i - 1 < j - 1 < n;
            assert p[i - 1] != p[j - 1];
            assert r[i] == p[i - 1] + 1;
            assert r[j] == p[j - 1] + 1;
