            assert 0 <= p[i - 1] < n;
            assert ([x] + b)[i] == b[i - 1];
            assert b[i - 1] == a[p[i - 1]];
            assert r[i] == p[i - 1] + 1;
            assert ([x] + a)[r[i]] == a[p[i - 1]];
        }
    }

    assert exists z: seq<int> ::
        z == r
        && is_valid_index_permutation(z, |[x] + a|)
        && |[x] + a| == |[x] + b|
        && (forall i {:trigger z[i]} ::
