method poly_multiply(a: seq<int>, b: seq<int>) returns (res: seq<int>)
    requires |a| > 0
    requires |b| > 0
    requires |a| + |b| <= 1000
    // Safety Precondition: Coefficients are bounded
    requires coeffs_bounded(a)
    requires coeffs_bounded(b)

    ensures |res| == |a| + |b| - 1
    // Functional Correctness
    ensures forall k :: 0 <= k < |res| ==> res[k] == spec_poly_mul_coeff(a, b, k)
{
    var n := |a| + |b| - 1;
    res := [];
    var k := 0;
    while k < n
        invariant 0 <= k <= n
        invariant |res| == k
        invariant forall j :: 0 <= j < k ==> res[j] == spec_poly_mul_coeff(a, b, j)
    {
        var s := 0;
        var i := 0;
        while i <= k
            invariant 0 <= i <= k + 1
            invariant s == spec_convolution_sum(a, b, k, i - 1)
        {
            var term := if i < |a| && k - i < |b| && k - i >= 0 then a[i] * b[k - i] else 0;
            s := term + s;
            i := i + 1;
        }
        assert s == spec_convolution_sum(a, b, k, k);
        assert s == spec_poly_mul_coeff(a, b, k);
        var old_res := res;
        res := res + [s];
        assert forall j :: 0 <= j < k ==> res[j] == old_res[j];
        assert res[k] == s;
        k := k + 1;
    }
}

