ghost predicate good_ext(g: seq<seq<(int, int)>>, F: seq<Edge>, T: seq<Edge>, T2: seq<Edge>) {
  is_spanning_tree(g, T2) && |F| <= |T2| && T2[..|F|] == F && total_weight(T2) <= total_weight(T)
}

ghost predicate promising(g: seq<seq<(int, int)>>, F: seq<Edge>) {
  forall T {:trigger is_spanning_tree(g, T)} :: is_spanning_tree(g, T) ==>
    exists T2 {:trigger good_ext(g, F, T, T2)} :: good_ext(g, F, T, T2)
}

lemma tw_concat(A: seq<Edge>, B: seq<Edge>)
  ensures total_weight(A + B) == total_weight(A) + total_weight(B)
  decreases |A|
{
  if |A| == 0 {
    assert A + B == B;
  } else {
    assert (A + B)[1..] == A[1..] + B;
    tw_concat(A[1..], B);
  }
}

lemma tw_single(x: Edge)
  ensures total_weight([x]) == x.2
{
  assert [x][1..] == [];
  assert total_weight([x][1..]) == 0;
}

lemma range_card(X: set<int>, n: int)
  requires n >= 0
  requires forall v :: v in X <==> 0 <= v < n
  ensures |X| == n
  decreases n
{
  if n == 0 {
    assert X == {};
  } else {
    var Y := X - {n - 1};
    range_card(Y, n - 1);
    assert X == Y + {n - 1};
    assert Y * {n - 1} == {};
  }
}

lemma edge_sym(E: seq<Edge>, x: int, y: int)
  requires edge_in_set(E, x, y)
  ensures edge_in_set(E, y, x)
{
  var i :| 0 <= i < |E| && ((E[i].0 == x && E[i].1 == y) || (E[i].0 == y && E[i].1 == x));
}

lemma edge_via(E: seq<Edge>, t: Edge, u: int, v: int)
  requires t in E
  requires (t.0 == u && t.1 == v) || (t.0 == v && t.1 == u)
  ensures edge_in_set(E, u, v)
{
  var idx :| 0 <= idx < |E| && E[idx] == t;
}

lemma conn_refl(E: seq<Edge>, x: int)
  ensures edges_connected(E, x, x)
{
  var p := [x];
  assert p[0] == x && p[|p| - 1] == x;
  assert path_follows_edges(E, p);
}

lemma conn_edge(E: seq<Edge>, x: int, y: int)
  requires edge_in_set(E, x, y)
  ensures edges_connected(E, x, y)
{
  var p := [x, y];
  assert p[0] == x && p[1] == y && p[|p| - 1] == y;
  forall k | 0 <= k < |p| - 1 ensures edge_in_set(E, p[k], p[k+1]) {
    assert k == 0;
  }
  assert path_follows_edges(E, p);
}

lemma conn_sym(E: seq<Edge>, u: int, v: int)
  requires edges_connected(E, u, v)
  ensures edges_connected(E, v, u)
{
  var p :| |p| > 0 && p[0] == u && p[|p| - 1] == v && path_follows_edges(E, p);
  var q := seq(|p|, k requires 0 <= k < |p| => p[|p| - 1 - k]);
  forall k | 0 <= k < |q| - 1 ensures edge_in_set(E, q[k], q[k+1]) {
    var m := |p| - 2 - k;
    assert q[k] == p[m + 1];
    assert q[k + 1] == p[m];
    assert edge_in_set(E, p[m], p[m + 1]);
    edge_sym(E, p[m], p[m + 1]);
  }
  assert q[0] == v && q[|q| - 1] == u;
  assert path_follows_edges(E, q);
}

lemma conn_trans(E: seq<Edge>, u: int, v: int, w: int)
  requires edges_connected(E, u, v)
  requires edges_connected(E, v, w)
  ensures edges_connected(E, u, w)
{
  var p :| |p| > 0 && p[0] == u && p[|p| - 1] == v && path_follows_edges(E, p);
  var q :| |q| > 0 && q[0] == v && q[|q| - 1] == w && path_follows_edges(E, q);
  var r := p + q[1..];
  assert |r| == |p| + |q| - 1;
  assert r[0] == u;
  if |q| == 1 {
    assert r[|r| - 1] == p[|p| - 1];
  } else {
    assert r[|r| - 1] == q[|q| - 1];
  }
  forall k | 0 <= k < |r| - 1 ensures edge_in_set(E, r[k], r[k+1]) {
    if k < |p| - 1 {
      assert r[k] == p[k] && r[k+1] == p[k+1];
      assert edge_in_set(E, p[k], p[k+1]);
    } else {
      var m := k - |p| + 1;
      assert r[k] == q[m] && r[k+1] == q[m+1];
      assert edge_in_set(E, q[m], q[m+1]);
    }
  }
  assert path_follows_edges(E, r);
}

lemma edge_sub(E: seq<Edge>, E2: seq<Edge>, x: int, y: int)
  requires forall idx :: 0 <= idx < |E| ==> E[idx] in E2
  requires edge_in_set(E, x, y)
  ensures edge_in_set(E2, x, y)
{
  var idx :| 0 <= idx < |E| && ((E[idx].0 == x && E[idx].1 == y) || (E[idx].0 == y && E[idx].1 == x));
  edge_via(E2, E[idx], x, y);
}

lemma conn_sub(E: seq<Edge>, E2: seq<Edge>, u: int, v: int)
  requires forall idx :: 0 <= idx < |E| ==> E[idx] in E2
  requires edges_connected(E, u, v)
  ensures edges_connected(E2, u, v)
{
  var p :| |p| > 0 && p[0] == u && p[|p| - 1] == v && path_follows_edges(E, p);
  forall k | 0 <= k < |p| - 1 ensures edge_in_set(E2, p[k], p[k+1]) {
    assert edge_in_set(E, p[k], p[k+1]);
    edge_sub(E, E2, p[k], p[k+1]);
  }
  assert path_follows_edges(E2, p);
}

lemma path_lift(E: seq<Edge>, E2: seq<Edge>, p: seq<int>)
  requires forall u, v :: edge_in_set(E, u, v) ==> edges_connected(E2, u, v)
  requires |p| > 0 && path_follows_edges(E, p)
  ensures edges_connected(E2, p[0], p[|p| - 1])
  decreases |p|
{
  if |p| == 1 {
    conn_refl(E2, p[0]);
  } else {
    var q := p[1..];
    forall k | 0 <= k < |q| - 1 ensures edge_in_set(E, q[k], q[k+1]) {
      assert q[k] == p[k+1] && q[k+1] == p[k+1+1];
      assert edge_in_set(E, p[k+1], p[k+1+1]);
    }
    assert path_follows_edges(E, q);
    path_lift(E, E2, q);
    assert q[0] == p[1] && q[|q| - 1] == p[|p| - 1];
    assert edge_in_set(E, p[0], p[1]);
    assert edges_connected(E2, p[0], p[1]);
    conn_trans(E2, p[0], p[1], p[|p| - 1]);
  }
}

lemma last_in(p: seq<int>, S: set<int>) returns (i: int)
  requires |p| > 0 && p[0] in S && p[|p| - 1] !in S
  ensures 0 <= i < |p| - 1 && p[i] in S && p[i + 1] !in S
  ensures forall k :: i < k < |p| ==> p[k] !in S
{
  assert |p| >= 2;
  i := |p| - 2;
  while p[i] !in S
    invariant 0 <= i <= |p| - 2
    invariant forall k :: i < k < |p| ==> p[k] !in S
    decreases i
  {
    assert i != 0;
    i := i - 1;
  }
}

lemma all_reached(g: seq<seq<(int, int)>>, S: set<int>, r: int)
  requires graph_is_connected(g)
  requires 0 <= r < |g| && r in S
  requires forall u, i :: 0 <= u < |g| && 0 <= i < |g[u]| ==> ((u in S) == (g[u][i].0 in S))
  ensures forall v :: 0 <= v < |g| ==> v in S
{
  forall v | 0 <= v < |g| ensures v in S {
    if v !in S {
      assert nodes_have_path(g, r, v);
      var p :| |p| > 0 && p[0] == r && p[|p| - 1] == v && path_follows_graph(g, p);
      var i := last_in(p, S);
      assert graph_has_any_edge(g, p[i], p[i + 1]);
      var ii :| 0 <= p[i] < |g| && 0 <= ii < |g[p[i]]| && g[p[i]][ii].0 == p[i + 1];
      assert (p[i] in S) == (g[p[i]][ii].0 in S);
      assert false;
    }
  }
}

lemma exchange(g: seq<seq<(int, int)>>, F: seq<Edge>, S: set<int>, r: int, e: Edge, T: seq<Edge>) returns (T2: seq<Edge>)
  requires is_spanning_tree(g, T)
  requires |F| <= |T| && T[..|F|] == F
  requires forall k :: 0 <= k < |F| ==> F[k].0 in S && F[k].1 in S
  requires r in S
  requires forall s :: s in S ==> edges_connected(F, r, s)
  requires has_edge(g, e.0, e.1, e.2)
  requires 0 <= e.0 < |g| && 0 <= e.1 < |g|
  requires (e.0 in S) != (e.1 in S)
  requires forall u, i :: 0 <= u < |g| && 0 <= i < |g[u]| && ((u in S) != (g[u][i].0 in S)) ==> e.2 <= g[u][i].1
  ensures is_spanning_tree(g, T2)
  ensures |F| + 1 <= |T2| && T2[..|F| + 1] == F + [e]
  ensures total_weight(T2) <= total_weight(T)
{
  var a := if e.0 in S then e.0 else e.1;
  var b := if e.0 in S then e.1 else e.0;
  assert a in S && b !in S;
  assert 0 <= a < |g| && 0 <= b < |g|;
  assert edges_connected(T, a, b);
  var p :| |p| > 0 && p[0] == a && p[|p| - 1] == b && path_follows_edges(T, p);
  var i := last_in(p, S);
  var x := p[i];
  var y := p[i + 1];
  assert x in S;
  assert y !in S;
  assert edge_in_set(T, x, y);
  var j :| 0 <= j < |T| && ((T[j].0 == x && T[j].1 == y) || (T[j].0 == y && T[j].1 == x));
  if j < |F| {
    assert T[j] == F[j];
    assert F[j].0 in S && F[j].1 in S;
    assert false;
  }
  var A := T[..|F|];
  var B := T[|F|..j];
  var C := T[j + 1..];
  T2 := A + [e] + B + C;
  assert |T2| == |T|;

  forall k | 0 <= k < |F| ensures T2[k] == T[k] && T[k] == F[k] {
    assert T2[k] == A[k];
    assert A[k] == T[k];
  }
  assert T2[|F|] == e;
  forall k | |F| < k <= j ensures T2[k] == T[k - 1] {
    assert T2[k] == B[k - |F| - 1];
  }
  forall k | j < k < |T| ensures T2[k] == T[k] {
    assert T2[k] == C[k - j - 1];
  }

  // prefix
  forall k | 0 <= k < |F| + 1 ensures T2[k] == (F + [e])[k] {
    if k < |F| {
      assert (F + [e])[k] == F[k];
    } else {
      assert (F + [e])[k] == e;
    }
  }
  assert T2[..|F| + 1] == F + [e];

  // valid edges
  forall k | 0 <= k < |T2| ensures has_edge(g, T2[k].0, T2[k].1, T2[k].2) {
    if k < |F| {
      assert has_edge(g, T[k].0, T[k].1, T[k].2);
    } else if k == |F| {
      assert T2[k] == e;
    } else if k <= j {
      assert has_edge(g, T[k-1].0, T[k-1].1, T[k-1].2);
    } else {
      assert has_edge(g, T[k].0, T[k].1, T[k].2);
    }
  }
  assert are_valid_edges(g, T2);

  // weights
  assert T[..j] == A + B;
  assert T == T[..j] + [T[j]] + C;
  tw_concat(A + B + [T[j]], C);
  tw_concat(A + B, [T[j]]);
  tw_concat(A, B);
  tw_single(T[j]);
  tw_concat(A + [e] + B, C);
  tw_concat(A + [e], B);
  tw_concat(A, [e]);
  tw_single(e);
  assert has_edge(g, T[j].0, T[j].1, T[j].2);
  var ii :| 0 <= T[j].0 < |g| && 0 <= ii < |g[T[j].0]| && g[T[j].0][ii].0 == T[j].1 && g[T[j].0][ii].1 == T[j].2;
  assert (T[j].0 in S) != (g[T[j].0][ii].0 in S);
  assert e.2 <= g[T[j].0][ii].1;
  assert e.2 <= T[j].2;
  assert total_weight(T2) <= total_weight(T);

  // spanning
  forall idx | 0 <= idx < |F| ensures F[idx] in T2 {
    assert T2[idx] == F[idx];
  }
  forall idx | 0 <= idx < |T| && idx != j ensures T[idx] in T2 {
    if idx < |F| {
      assert T2[idx] == T[idx];
    } else if idx < j {
      assert T2[idx + 1] == T[idx];
    } else {
      assert T2[idx] == T[idx];
    }
  }
  assert edges_connected(F, r, x);
  assert edges_connected(F, r, a);
  conn_sym(F, r, x);
  conn_trans(F, x, r, a);
  conn_sub(F, T2, x, a);
  assert e in T2;
  edge_via(T2, e, a, b);
  conn_edge(T2, a, b);

  var q := p[i + 1..];
  assert |q| == |p| - i - 1;
  assert q[0] == y;
  assert q[|q| - 1] == b;
  forall k | 0 <= k < |q| - 1 ensures edge_in_set(T2, q[k], q[k+1]) {
    assert q[k] == p[i + 1 + k] && q[k + 1] == p[i + 1 + k + 1];
    assert edge_in_set(T, p[i + 1 + k], p[i + 1 + k + 1]);
    assert p[i + 1 + k] !in S && p[i + 1 + k + 1] !in S;
    var idx :| 0 <= idx < |T| && ((T[idx].0 == q[k] && T[idx].1 == q[k+1]) || (T[idx].0 == q[k+1] && T[idx].1 == q[k]));
    if idx == j {
      assert x == T[j].0 || x == T[j].1;
      assert false;
    }
    assert T[idx] in T2;
    edge_via(T2, T[idx], q[k], q[k+1]);
  }
  assert path_follows_edges(T2, q);
  assert edges_connected(T2, y, b);
  conn_trans(T2, x, a, b);
  conn_sym(T2, y, b);
  conn_trans(T2, x, b, y);
  conn_sym(T2, x, y);

  forall u, v | edge_in_set(T, u, v) ensures edges_connected(T2, u, v) {
    var idx :| 0 <= idx < |T| && ((T[idx].0 == u && T[idx].1 == v) || (T[idx].0 == v && T[idx].1 == u));
    if idx == j {
      if u == x && v == y {
      } else {
        assert u == y && v == x;
      }
    } else {
      assert T[idx] in T2;
      edge_via(T2, T[idx], u, v);
      conn_edge(T2, u, v);
    }
  }
  forall u, v | 0 <= u < |g| && 0 <= v < |g| ensures edges_connected(T2, u, v) {
    assert edges_connected(T, u, v);
    var pp :| |pp| > 0 && pp[0] == u && pp[|pp| - 1] == v && path_follows_edges(T, pp);
    path_lift(T, T2, pp);
  }
  assert is_spanning(g, T2);
}

method prim_mst(graph: WeightedGraph) returns (edges: seq<Edge>)
    requires well_formed(graph)
    requires size(graph) > 0
    requires weights_bounded(view(graph))
    requires graph_is_connected(view(graph))
    ensures is_mst(view(graph), edges)
{
  var g := graph.adj;
  var n := |g|;
  assert g == view(graph);
  assert n > 0;
  assert forall uu, ii :: 0 <= uu < n && 0 <= ii < |g[uu]| ==> 0 <= g[uu][ii].0 < n;
  var inTree: seq<bool> := seq(n, v => v == 0);
  ghost var S: set<int> := {0};
  ghost var R: set<int> := set v | 0 <= v < n;
  edges := [];
  conn_refl(edges, 0);
  forall T | is_spanning_tree(g, T) ensures exists T2 :: good_ext(g, edges, T, T2) {
    assert T[..0] == [];
    assert good_ext(g, edges, T, T);
  }
  assert promising(g, edges);

  while true
    invariant |inTree| == n
    invariant 0 in S
    invariant forall s :: s in S ==> 0 <= s < n
    invariant forall v :: 0 <= v < n ==> (inTree[v] <==> v in S)
    invariant |S| == |edges| + 1
    invariant forall k :: 0 <= k < |edges| ==> edges[k].0 in S && edges[k].1 in S
    invariant are_valid_edges(g, edges)
    invariant forall s :: s in S ==> edges_connected(edges, 0, s)
    invariant promising(g, edges)
    decreases R - S
  {
    var found := false;
    var bu := 0;
    var bi := 0;
    var u := 0;
    while u < n
      invariant 0 <= u <= n
      invariant found ==> 0 <= bu < n && 0 <= bi < |g[bu]| && inTree[bu] != inTree[g[bu][bi].0]
      invariant forall uu, ii :: 0 <= uu < u && 0 <= ii < |g[uu]| && inTree[uu] != inTree[g[uu][ii].0] ==> found && g[bu][bi].1 <= g[uu][ii].1
    {
      var i := 0;
      while i < |g[u]|
        invariant 0 <= i <= |g[u]|
        invariant found ==> 0 <= bu < n && 0 <= bi < |g[bu]| && inTree[bu] != inTree[g[bu][bi].0]
        invariant forall uu, ii :: 0 <= uu < u && 0 <= ii < |g[uu]| && inTree[uu] != inTree[g[uu][ii].0] ==> found && g[bu][bi].1 <= g[uu][ii].1
        invariant forall ii :: 0 <= ii < i && inTree[u] != inTree[g[u][ii].0] ==> found && g[bu][bi].1 <= g[u][ii].1
      {
        var v := g[u][i].0;
        if inTree[u] != inTree[v] {
          if !found || g[u][i].1 < g[bu][bi].1 {
            found := true;
            bu := u;
            bi := i;
          }
        }
        i := i + 1;
      }
      u := u + 1;
    }

    if !found {
      forall uu, ii | 0 <= uu < n && 0 <= ii < |g[uu]| ensures (uu in S) == (g[uu][ii].0 in S) {
        assert 0 <= g[uu][ii].0 < n;
        assert inTree[uu] == inTree[g[uu][ii].0];
      }
      all_reached(g, S, 0);
      break;
    }

    var u0 := bu;
    var v0 := g[bu][bi].0;
    var w0 := g[bu][bi].1;
    var e: Edge := (u0, v0, w0);
    assert 0 <= v0 < n;
    assert has_edge(g, u0, v0, w0);
    assert (u0 in S) != (v0 in S);
    forall uu, ii | 0 <= uu < n && 0 <= ii < |g[uu]| && ((uu in S) != (g[uu][ii].0 in S))
      ensures w0 <= g[uu][ii].1
    {
      assert 0 <= g[uu][ii].0 < n;
      assert inTree[uu] != inTree[g[uu][ii].0];
    }
    var b := if inTree[u0] then v0 else u0;
    ghost var a := if inTree[u0] then u0 else v0;
    assert a in S && b !in S && 0 <= a < n && 0 <= b < n;
    var newEdges := edges + [e];

    forall T | is_spanning_tree(g, T) ensures exists T2 :: good_ext(g, newEdges, T, T2) {
      var T1 :| good_ext(g, edges, T, T1);
      var T2 := exchange(g, edges, S, 0, e, T1);
      assert good_ext(g, newEdges, T, T2);
    }
    assert promising(g, newEdges);

    forall idx | 0 <= idx < |edges| ensures edges[idx] in newEdges {
      assert newEdges[idx] == edges[idx];
    }
    assert newEdges[|edges|] == e;
    assert e in newEdges;
    forall s | s in S + {b} ensures edges_connected(newEdges, 0, s) {
      if s in S {
        conn_sub(edges, newEdges, 0, s);
      } else {
        conn_sub(edges, newEdges, 0, a);
        edge_via(newEdges, e, a, b);
        conn_edge(newEdges, a, b);
        conn_trans(newEdges, 0, a, b);
      }
    }
    forall k | 0 <= k < |newEdges| ensures has_edge(g, newEdges[k].0, newEdges[k].1, newEdges[k].2) {
      if k < |edges| {
        assert newEdges[k] == edges[k];
        assert has_edge(g, edges[k].0, edges[k].1, edges[k].2);
      } else {
        assert newEdges[k] == e;
      }
    }
    assert are_valid_edges(g, newEdges);
    assert S * {b} == {};
    assert b in R - S;
    assert b !in R - (S + {b});
    edges := newEdges;
    inTree := inTree[b := true];
    S := S + {b};
  }

  assert forall v :: v in S <==> 0 <= v < n;
  range_card(S, n);
  assert |edges| == n - 1;
  forall u, v | 0 <= u < n && 0 <= v < n ensures edges_connected(edges, u, v) {
    assert u in S && v in S;
    assert edges_connected(edges, 0, u);
    assert edges_connected(edges, 0, v);
    conn_sym(edges, 0, u);
    conn_trans(edges, u, 0, v);
  }
  assert is_spanning(g, edges);
  assert is_spanning_tree(g, edges);
  forall other | is_spanning_tree(g, other) ensures total_weight(edges) <= total_weight(other) {
    var T2 :| good_ext(g, edges, other, T2);
    assert |T2| == |edges|;
    assert T2[..|T2|] == T2;
    assert T2 == edges;
  }
  assert is_mst(g, edges);
}

response:
Prim's algorithm below scans every adjacency entry each round. It picks the lightest edge with exactly one endpoint in the tree, in either direction, because the graph may be asymmetric. I have not run Dafny on this code, so it is not yet confirmed to verify with no errors under 4.11.0.

The optimality proof rests on a loop invariant called `promising`. It says that for every spanning tree `T` there is another spanning tree `T2` that starts with the current edges and weighs no more than `T`. The `exchange` lemma carries this invariant from one round to the next. It takes the path in `T2` between the new edge's endpoints and finds the last crossing edge on that path. It swaps that edge for the new one and shows the result is still spanning: the tree edges built so far connect the in-tree side, and the rest of the path stays outside the tree. When the loop ends, `T2` has the same length as `edges`, so `T2 == edges`.

```dafny
ghost predicate good_ext(g: seq<seq<(int, int)>>, F: seq<Edge>, T: seq<Edge>, T2: seq<Edge>) {
  is_spanning_tree(g, T2) && |F| <= |T2| && T2[..|F|] == F && total_weight(T2) <= total_weight(T)
}

ghost predicate promising(g: seq<seq<(int, int)>>, F: seq<Edge>) {
  forall T {:trigger is_spanning_tree(g, T)} :: is_spanning_tree(g, T) ==>
    exists T2 {:trigger good_ext(g, F, T, T2)} :: good_ext(g, F, T, T2)
}

lemma tw_concat(A: seq<Edge>, B: seq<Edge>)
  ensures total_weight(A + B) == total_weight(A) + total_weight(B)
  decreases |A|
{
  if |A| == 0 {
    assert A + B == B;
  } else {
    assert (A + B)[1..] == A[1..] + B;
    tw_concat(A[1..], B);
  }
}

lemma tw_single(x: Edge)
  ensures total_weight([x]) == x.2
{
  assert [x][1..] == [];
  assert total_weight([x][1..]) == 0;
}

lemma range_card(X: set<int>, n: int)
  requires n >= 0
  requires forall v :: v in X <==> 0 <= v < n
  ensures |X| == n
  decreases n
{
  if n == 0 {
    assert X == {};
  } else {
    var Y := X - {n - 1};
    range_card(Y, n - 1);
    assert X == Y + {n - 1};
    assert Y * {n - 1} == {};
  }
}

lemma edge_sym(E: seq<Edge>, x: int, y: int)
  requires edge_in_set(E, x, y)
  ensures edge_in_set(E, y, x)
{
  var i :| 0 <= i < |E| && ((E[i].0 == x && E[i].1 == y) || (E[i].0 == y && E[i].1 == x));
}

lemma edge_via(E: seq<Edge>, t: Edge, u: int, v: int)
  requires t in E
  requires (t.0 == u && t.1 == v) || (t.0 == v && t.1 == u)
  ensures edge_in_set(E, u, v)
{
  var idx :| 0 <= idx < |E| && E[idx] == t;
}

lemma conn_refl(E: seq<Edge>, x: int)
  ensures edges_connected(E, x, x)
{
  var p := [x];
  assert p[0] == x && p[|p| - 1] == x;
  assert path_follows_edges(E, p);
}

lemma conn_edge(E: seq<Edge>, x: int, y: int)
  requires edge_in_set(E, x, y)
  ensures edges_connected(E, x, y)
{
  var p := [x, y];
  assert p[0] == x && p[1] == y && p[|p| - 1] == y;
  forall k | 0 <= k < |p| - 1 ensures edge_in_set(E, p[k], p[k+1]) {
    assert k == 0;
  }
  assert path_follows_edges(E, p);
}

lemma conn_sym(E: seq<Edge>, u: int, v: int)
  requires edges_connected(E, u, v)
  ensures edges_connected(E, v, u)
{
  var p :| |p| > 0 && p[0] == u && p[|p| - 1] == v && path_follows_edges(E, p);
  var q := seq(|p|, k requires 0 <= k < |p| => p[|p| - 1 - k]);
  forall k | 0 <= k < |q| - 1 ensures edge_in_set(E, q[k], q[k+1]) {
    var m := |p| - 2 - k;
    assert q[k] == p[m + 1];
    assert q[k + 1] == p[m];
    assert edge_in_set(E, p[m], p[m + 1]);
    edge_sym(E, p[m], p[m + 1]);
  }
  assert q[0] == v && q[|q| - 1] == u;
  assert path_follows_edges(E, q);
}

lemma conn_trans(E: seq<Edge>, u: int, v: int, w: int)
  requires edges_connected(E, u, v)
  requires edges_connected(E, v, w)
  ensures edges_connected(E, u, w)
{
  var p :| |p| > 0 && p[0] == u && p[|p| - 1] == v && path_follows_edges(E, p);
  var q :| |q| > 0 && q[0] == v && q[|q| - 1] == w && path_follows_edges(E, q);
  var r := p + q[1..];
  assert |r| == |p| + |q| - 1;
  assert r[0] == u;
  if |q| == 1 {
    assert r[|r| - 1] == p[|p| - 1];
  } else {
    assert r[|r| - 1] == q[|q| - 1];
  }
  forall k | 0 <= k < |r| - 1 ensures edge_in_set(E, r[k], r[k+1]) {
    if k < |p| - 1 {
      assert r[k] == p[k] && r[k+1] == p[k+1];
      assert edge_in_set(E, p[k], p[k+1]);
    } else {
      var m := k - |p| + 1;
      assert r[k] == q[m] && r[k+1] == q[m+1];
      assert edge_in_set(E, q[m], q[m+1]);
    }
  }
  assert path_follows_edges(E, r);
}

lemma edge_sub(E: seq<Edge>, E2: seq<Edge>, x: int, y: int)
  requires forall idx :: 0 <= idx < |E| ==> E[idx] in E2
  requires edge_in_set(E, x, y)
  ensures edge_in_set(E2, x, y)
{
  var idx :| 0 <= idx < |E| && ((E[idx].0 == x && E[idx].1 == y) || (E[idx].0 == y && E[idx].1 == x));
  edge_via(E2, E[idx], x, y);
}

lemma conn_sub(E: seq<Edge>, E2: seq<Edge>, u: int, v: int)
  requires forall idx :: 0 <= idx < |E| ==> E[idx] in E2
  requires edges_connected(E, u, v)
  ensures edges_connected(E2, u, v)
{
  var p :| |p| > 0 && p[0] == u && p[|p| - 1] == v && path_follows_edges(E, p);
  forall k | 0 <= k < |p| - 1 ensures edge_in_set(E2, p[k], p[k+1]) {
    assert edge_in_set(E, p[k], p[k+1]);
    edge_sub(E, E2, p[k], p[k+1]);
  }
  assert path_follows_edges(E2, p);
}

lemma path_lift(E: seq<Edge>, E2: seq<Edge>, p: seq<int>)
  requires forall u, v :: edge_in_set(E, u, v) ==> edges_connected(E2, u, v)
  requires |p| > 0 && path_follows_edges(E, p)
  ensures edges_connected(E2, p[0], p[|p| - 1])
  decreases |p|
{
  if |p| == 1 {
    conn_refl(E2, p[0]);
  } else {
    var q := p[1..];
    forall k | 0 <= k < |q| - 1 ensures edge_in_set(E, q[k], q[k+1]) {
      assert q[k] == p[k+1] && q[k+1] == p[k+1+1];
      assert edge_in_set(E, p[k+1], p[k+1+1]);
    }
    assert path_follows_edges(E, q);
    path_lift(E, E2, q);
    assert q[0] == p[1] && q[|q| - 1] == p[|p| - 1];
    assert edge_in_set(E, p[0], p[1]);
    assert edges_connected(E2, p[0], p[1]);
    conn_trans(E2, p[0], p[1], p[|p| - 1]);
  }
}

lemma last_in(p: seq<int>, S: set<int>) returns (i: int)
  requires |p| > 0 && p[0] in S && p[|p| - 1] !in S
  ensures 0 <= i < |p| - 1 && p[i] in S && p[i + 1] !in S
  ensures forall k :: i < k < |p| ==> p[k] !in S
{
  assert |p| >= 2;
  i := |p| - 2;
  while p[i] !in S
    invariant 0 <= i <= |p| - 2
    invariant forall k :: i < k < |p| ==> p[k] !in S
    decreases i
  {
    assert i != 0;
    i := i - 1;
  }
}

lemma all_reached(g: seq<seq<(int, int)>>, S: set<int>, r: int)
  requires graph_is_connected(g)
  requires 0 <= r < |g| && r in S
  requires forall u, i :: 0 <= u < |g| && 0 <= i < |g[u]| ==> ((u in S) == (g[u][i].0 in S))
  ensures forall v :: 0 <= v < |g| ==> v in S
{
  forall v | 0 <= v < |g| ensures v in S {
    if v !in S {
      assert nodes_have_path(g, r, v);
      var p :| |p| > 0 && p[0] == r && p[|p| - 1] == v && path_follows_graph(g, p);
      var i := last_in(p, S);
      assert graph_has_any_edge(g, p[i], p[i + 1]);
      var ii :| 0 <= p[i] < |g| && 0 <= ii < |g[p[i]]| && g[p[i]][ii].0 == p[i + 1];
      assert (p[i] in S) == (g[p[i]][ii].0 in S);
      assert false;
    }
  }
}

lemma exchange(g: seq<seq<(int, int)>>, F: seq<Edge>, S: set<int>, r: int, e: Edge, T: seq<Edge>) returns (T2: seq<Edge>)
  requires is_spanning_tree(g, T)
  requires |F| <= |T| && T[..|F|] == F
  requires forall k :: 0 <= k < |F| ==> F[k].0 in S && F[k].1 in S
  requires r in S
  requires forall s :: s in S ==> edges_connected(F, r, s)
  requires has_edge(g, e.0, e.1, e.2)
  requires 0 <= e.0 < |g| && 0 <= e.1 < |g|
  requires (e.0 in S) != (e.1 in S)
  requires forall u, i :: 0 <= u < |g| && 0 <= i < |g[u]| && ((u in S) != (g[u][i].0 in S)) ==> e.2 <= g[u][i].1
  ensures is_spanning_tree(g, T2)
  ensures |F| + 1 <= |T2| && T2[..|F| + 1] == F + [e]
  ensures total_weight(T2) <= total_weight(T)
{
  var a := if e.0 in S then e.0 else e.1;
  var b := if e.0 in S then e.1 else e.0;
  assert a in S && b !in S;
  assert 0 <= a < |g| && 0 <= b < |g|;
  assert edges_connected(T, a, b);
  var p :| |p| > 0 && p[0] == a && p[|p| - 1] == b && path_follows_edges(T, p);
  var i := last_in(p, S);
  var x := p[i];
  var y := p[i + 1];
  assert x in S;
  assert y !in S;
  assert edge_in_set(T, x, y);
  var j :| 0 <= j < |T| && ((T[j].0 == x && T[j].1 == y) || (T[j].0 == y && T[j].1 == x));
  if j < |F| {
    assert T[j] == F[j];
    assert F[j].0 in S && F[j].1 in S;
    assert false;
  }
  var A := T[..|F|];
  var B := T[|F|..j];
  var C := T[j + 1..];
  T2 := A + [e] + B + C;
  assert |T2| == |T|;

  forall k | 0 <= k < |F| ensures T2[k] == T[k] && T[k] == F[k] {
    assert T2[k] == A[k];
    assert A[k] == T[k];
  }
  assert T2[|F|] == e;
  forall k | |F| < k <= j ensures T2[k] == T[k - 1] {
    assert T2[k] == B[k - |F| - 1];
  }
  forall k | j < k < |T| ensures T2[k] == T[k] {
    assert T2[k] == C[k - j - 1];
  }

  // prefix
  forall k | 0 <= k < |F| + 1 ensures T2[k] == (F + [e])[k] {
    if k < |F| {
      assert (F + [e])[k] == F[k];
    } else {
      assert (F + [e])[k] == e;
    }
  }
  assert T2[..|F| + 1] == F + [e];

  // valid edges
  forall k | 0 <= k < |T2| ensures has_edge(g, T2[k].0, T2[k].1, T2[k].2) {
    if k < |F| {
      assert has_edge(g, T[k].0, T[k].1, T[k].2);
    } else if k == |F| {
      assert T2[k] == e;
    } else if k <= j {
      assert has_edge(g, T[k-1].0, T[k-1].1, T[k-1].2);
    } else {
      assert has_edge(g, T[k].0, T[k].1, T[k].2);
    }
  }
  assert are_valid_edges(g, T2);

  // weights
  assert T[..j] == A + B;
  assert T == T[..j] + [T[j]] + C;
  tw_concat(A + B + [T[j]], C);
  tw_concat(A + B, [T[j]]);
  tw_concat(A, B);
  tw_single(T[j]);
  tw_concat(A + [e] + B, C);
  tw_concat(A + [e], B);
  tw_concat(A, [e]);
  tw_single(e);
  assert has_edge(g, T[j].0, T[j].1, T[j].2);
  var ii :| 0 <= T[j].0 < |g| && 0 <= ii < |g[T[j].0]| && g[T[j].0][ii].0 == T[j].1 && g[T[j].0][ii].1 == T[j].2;
  assert (T[j].0 in S) != (g[T[j].0][ii].0 in S);
  assert e.2 <= g[T[j].0][ii].1;
  assert e.2 <= T[j].2;
  assert total_weight(T2) <= total_weight(T);

  // spanning
  forall idx | 0 <= idx < |F| ensures F[idx] in T2 {
    assert T2[idx] == F[idx];
  }
  forall idx | 0 <= idx < |T| && idx != j ensures T[idx] in T2 {
    if idx < |F| {
      assert T2[idx] == T[idx];
    } else if idx < j {
      assert T2[idx + 1] == T[idx];
    } else {
      assert T2[idx] == T[idx];
    }
  }
