lemma crossing_edge_exists(
    g: seq<seq<(int, int)>>,
    visited: set<int>)
    requires |g| > 0
    requires graph_is_connected(g)
    requires 0 in visited
    requires visited < vertex_range(|g|)
    ensures exists u: int, v: int, w: int ::
        u in visited &&
        v in vertex_range(|g|) - visited &&
        has_edge(g, u, v, w)
{
    vertex_range_properties(|g|);

    assert exists z: int :: z in vertex_range(|g|) && z !in visited by {
        if !(exists z: int :: z in vertex_range(|g|) && z !in visited) {
            assert forall z: int :: z in vertex_range(|g|) ==> z in visited;
            assert visited == vertex_range(|g|);
        }
    }

    var z :| z in vertex_range(|g|) && z !in visited;
    assert 0 <= z < |g|;

    assert nodes_have_path(g, 0, z);
    var p :| |p| > 0 &&
        p[0] == 0 &&
        p[|p| - 1] == z &&
        path_follows_graph(g, p);

    var j := 0;
    while p[j] in visited
        invariant 0 <= j < |p|
        invariant forall k: int :: 0 <= k <= j ==> p[k] in visited
        invariant p[|p| - 1] == z
        invariant z !in visited
        decreases |p| - 1 - j
    {
        assert j < |p| - 1;
        j := j + 1;
    }

    assert j > 0;
    assert p[j - 1] in visited;
    assert p[j] !in visited;
    assert graph_has_any_edge(g, p[j - 1], p[j]);

    var i :| 0 <= p[j - 1] < |g| &&
        0 <= i < |g[p[j - 1]]| &&
        g[p[j - 1]][i].0 == p[j];

    var u := p[j - 1];
    var v := p[j];
    var w := g[u][i].1;

    assert has_edge(g, u, v, w);
    assert 0 <= v < |g|;
    assert v in vertex_range(|g|);
}

