    es: seq<Edge>,
    e: Edge)
    requires are_valid_edges(g, es)
    requires has_edge(g, e.0, e.1, e.2)
    ensures are_valid_edges(g, es + [e])
{
    forall k: int | 0 <= k < |es + [e]|
        ensures has_edge(
            g,
            (es + [e])[k].0,
            (es + [e])[k].1,
            (es + [e])[k].2)
    {
        if k < |es| {
            assert (es + [e])[k] == es[k];
        } else {
            assert k == |es|;
            assert (es + [e])[k] == e;
        }
    }
}

lemma spanning_tree_exists(
    g: seq<seq<(int, int)>>)
    requires |g| > 0
    requires graph_is_connected(g)
    ensures exists es: seq<Edge> :: is_spanning_tree(g, es)
{
    vertex_range_properties(|g|);

    var visited: set<int> := {0};
    var es: seq<Edge> := [];

    connected_reflexive(es, 0);

    while visited != vertex_range(|g|)
        invariant visited <= vertex_range(|g|)
        invariant 0 in visited
        invariant |visited| == |es| + 1
        invariant are_valid_edges(g, es)
        invariant forall x: int :: x in visited ==>
            edges_connected(es, 0, x)
        decreases |g| - |visited|
    {
        assert visited < vertex_range(|g|);
        crossing_edge_exists(g, visited);

        var u, v, w :|
            u in visited &&
            v in vertex_range(|g|) - visited &&
            has_edge(g, u, v, w);

        var e: Edge := (u, v, w);
        var oldEs := es;

        append_preserves_validity(g, es, e);
        es := es + [e];

        forall x: int | x in visited
            ensures edges_connected(es, 0, x)
        {
            connection_preserved(oldEs, e, 0, x);
        }

        new_vertex_connected(oldEs, e, 0, u, v);

        visited := visited + {v};
        assert v !in old(visited);
    }

    assert visited == vertex_range(|g|);
    assert |visited| == |g|;
    assert |es| == |g| - 1;

    assert is_spanning(g, es) by {
        forall u: int, v: int |
            0 <= u < |g| && 0 <= v < |g|
            ensures edges_connected(es, u, v)
        {
            assert u in vertex_range(|g|);
            assert v in vertex_range(|g|);
            assert edges_connected(es, 0, u);
            assert edges_connected(es, 0, v);
            connected_symmetric(es, 0, u);
            connected_transitive(es, u, 0, v);
        }
    }

    assert is_spanning_tree(g, es);
}

lemma total_weight_lower_bound(
    g: seq<seq<(int, int)>>,
    es: seq<Edge>)
    requires weights_bounded(g)
    requires are_valid_edges(g, es)
    ensures total_weight(es) >= -100_000 * |es|
    decreases |es|
{
    if |es| > 0 {
        assert has_edge(g, es[0].0, es[0].1, es[0].2);
        assert es[0].2 >= -100_000;

        assert are_valid_edges(g, es[1..]) by {
            forall k: int | 0 <= k < |es[1..]|
                ensures has_edge(
                    g,
                    es[1..][k].0,
                    es[1..][k].1,
                    es[1..][k].2)
            {
                assert es[1..][k] == es[k + 1];
            }
        }

        total_weight_lower_bound(g, es[1..]);
    }
}

lemma mst_exists(
    g: seq<seq<(int, int)>>)
    requires |g| > 0
    requires graph_is_connected(g)
    requires weights_bounded(g)
    ensures exists es: seq<Edge> :: is_mst(g, es)
{
    spanning_tree_exists(g);
    var initial :| is_spanning_tree(g, initial);

    var lower := -100_000 * (|g| - 1);
    total_weight_lower_bound(g, initial);
    assert total_weight(initial) >= lower;

    var candidateWeight := lower;

    while !(exists es: seq<Edge> ::
        is_spanning_tree(g, es) &&
        total_weight(es) == candidateWeight)
        invariant lower <= candidateWeight <= total_weight(initial)
        invariant forall es: seq<Edge> ::
            is_spanning_tree(g, es) ==>
            total_weight(es) >= candidateWeight
        decreases total_weight(initial) - candidateWeight
    {
        assert candidateWeight < total_weight(initial);

        assert forall es: seq<Edge> ::
            is_spanning_tree(g, es) ==>
            total_weight(es) >= candidateWeight + 1 by {
            forall es: seq<Edge> | is_spanning_tree(g, es)
                ensures total_weight(es) >= candidateWeight + 1
            {
                assert total_weight(es) >= candidateWeight;
                assert total_weight(es) != candidateWeight;
            }
        }

        candidateWeight := candidateWeight + 1;
    }

    var best :|
        is_spanning_tree(g, best) &&
        total_weight(best) == candidateWeight;

    assert forall other: seq<Edge> ::
        is_spanning_tree(g, other) ==>
        total_weight(best) <= total_weight(other);

    assert is_mst(g, best);
}

