lemma path_preserved_by_extension(
    es: seq<Edge>, e: Edge, p: seq<int>)
    requires path_follows_edges(es, p)
    ensures path_follows_edges(es + [e], p)
{
    forall k: int | 0 <= k < |p| - 1
        ensures edge_in_set(es + [e], p[k], p[k + 1])
