}

lemma path_append_vertex(
    es: seq<Edge>, p: seq<int>, v: int)
    requires |p| > 0
    requires path_follows_edges(es, p)
    requires edge_in_set(es, p[|p| - 1], v)
    ensures path_follows_edges(es, p + [v])
{
    forall k: int | 0 <= k < |p + [v]| - 1
        ensures edge_in_set(es, (p + [v])[k], (p + [v])[k + 1])
    {
        if k < |p| - 1 {
            assert (p + [v])[k] == p[k];
            assert (p + [v])[k + 1] == p[k + 1];
        } else {
            assert k == |p| - 1;
            assert (p + [v])[k] == p[|p| - 1];
            assert (p + [v])[k + 1] == v;
        }
    }
}

