    forall k: int | 0 <= k < |newEdges| ensures has_edge(g, newEdges[k].0, newEdges[k].1, newEdges[k].2) {
      if k < |edges| {
        assert newEdges[k] == edges[k];
        assert has_edge(g, edges[k].0, edges[k].1, edges[k].2);
      } else {
        assert newEdges[k] == e;
      }
    }
    assert are_valid_edges(g, newEdges);
    assert S * {b} == {};
    assert b in R - S;
    assert b !in R - (S + {b});
    edges := newEdges;
    inTree := inTree[b := true];
    S := S + {b};
  }

  assert forall v: int :: v in S <==> 0 <= v < n;
  range_card(S, n);
  assert |edges| == n - 1;
  forall u: int, v: int | 0 <= u < n && 0 <= v < n ensures edges_connected(edges, u, v) {
    assert u in S && v in S;
    assert edges_connected(edges, 0, u);
    assert edges_connected(edges, 0, v);
    conn_sym(edges, 0, u);
    conn_trans(edges, u, 0, v);
  }
  assert is_spanning(g, edges);
  assert is_spanning_tree(g, edges);
  forall other: seq<Edge> | is_spanning_tree(g, other) ensures total_weight(edges) <= total_weight(other) {
    var T2: seq<Edge> :| good_ext(g, edges, other, T2);
    assert |T2| == |edges|;
    assert T2[..|T2|] == T2;
    assert T2 == edges;
  }
  assert is_mst(g, edges);
}

