lemma tw_concat(A: seq<Edge>, B: seq<Edge>)
  ensures total_weight(A + B) == total_weight(A) + total_weight(B)
  decreases |A|
{
  if |A| == 0 {
    assert A + B == B;
  } else {
    assert (A + B)[1..] == A[1..] + B;
    tw_concat(A[1..], B);
  }
}

lemma tw_single(x: Edge)
  ensures total_weight([x]) == x.2
{
  assert [x][1..] == [];
  assert total_weight([x][1..]) == 0;
}

lemma range_card(X: set<int>, n: int)
  requires n >= 0
  requires forall v: int :: v in X <==> 0 <= v < n
  ensures |X| == n
  decreases n
{
  if n == 0 {
    assert X == {};
  } else {
    var Y := X - {n - 1};
    range_card(Y, n - 1);
    assert X == Y + {n - 1};
    assert Y * {n - 1} == {};
  }
}

lemma edge_sym(E: seq<Edge>, x: int, y: int)
