lemma path_lift(E: seq<Edge>, E2: seq<Edge>, p: seq<int>)
  requires forall u: int, v: int :: edge_in_set(E, u, v) ==> edges_connected(E2, u, v)
  requires |p| > 0 && path_follows_edges(E, p)
  ensures edges_connected(E2, p[0], p[|p| - 1])
  decreases |p|
{
  if |p| == 1 {
    conn_refl(E2, p[0]);
  } else {
    var q := p[1..];
    forall k: int | 0 <= k < |q| - 1 ensures edge_in_set(E, q[k], q[k+1]) {
      assert q[k] == p[k+1] && q[k+1] == p[k+1+1];
      assert edge_in_set(E, p[k+1], p[k+1+1]);
    }
    assert path_follows_edges(E, q);
    path_lift(E, E2, q);
    assert q[0] == p[1] && q[|q| - 1] == p[|p| - 1];
    assert edge_in_set(E, p[0], p[1]);
    assert edges_connected(E2, p[0], p[1]);
    conn_trans(E2, p[0], p[1], p[|p| - 1]);
  }
}

lemma last_in(p: seq<int>, S: set<int>) returns (i: int)
  requires |p| > 0 && p[0] in S && p[|p| - 1] !in S
