lemma reverse_path_properties(p: seq<int>)
    ensures |reverse_path(p)| == |p|
    ensures |p| > 0 ==> reverse_path(p)[0] == p[|p| - 1]
    ensures |p| > 0 ==> reverse_path(p)[|p| - 1] == p[0]
    decreases |p|
{
