lemma connected_symmetric(es: seq<Edge>, u: int, v: int)
    requires edges_connected(es, u, v)
    ensures edges_connected(es, v, u)
{
    var p :| |p| > 0 &&
        p[0] == u &&
        p[|p| - 1] == v &&
        path_follows_edges(es, p);

    reverse_path_properties(p);
    reverse_path_follows(es, p);
}

lemma concatenate_paths(
    es: seq<Edge>, p: seq<int>, q: seq<int>)
    requires |p| > 0
    requires |q| > 0
    requires p[|p| - 1] == q[0]
    requires path_follows_edges(es, p)
    requires path_follows_edges(es, q)
    ensures path_follows_edges(es, p + q[1..])
{
    forall k: int | 0 <= k < |p + q[1..]| - 1
        ensures edge_in_set(
            es,
            (p + q[1..])[k],
            (p + q[1..])[k + 1])
    {
        if k < |p| - 1 {
            assert (p + q[1..])[k] == p[k];
            assert (p + q[1..])[k + 1] == p[k + 1];
        } else {
            var j := k - |p| + 1;
            assert 0 <= j < |q| - 1;
            assert (p + q[1..])[k] == q[j];
            assert (p + q[1..])[k + 1] == q[j + 1];
        }
    }
}

lemma connected_transitive(
    es: seq<Edge>, u: int, v: int, w: int)
    requires edges_connected(es, u, v)
    requires edges_connected(es, v, w)
    ensures edges_connected(es, u, w)
{
    var p :| |p| > 0 &&
        p[0] == u &&
        p[|p| - 1] == v &&
        path_follows_edges(es, p);

    var q :| |q| > 0 &&
        q[0] == v &&
        q[|q| - 1] == w &&
        path_follows_edges(es, q);

    concatenate_paths(es, p, q);

    var r := p + q[1..];
    assert |r| > 0;
    assert r[0] == u;
    assert r[|r| - 1] == w;
}

lemma connected_reflexive(es: seq<Edge>, u: int)
    ensures edges_connected(es, u, u)
{
    var p := [u];
    assert path_follows_edges(es, p);
}

lemma connection_preserved(
    es: seq<Edge>, e: Edge, u: int, v: int)
    requires edges_connected(es, u, v)
    ensures edges_connected(es + [e], u, v)
{
    var p :| |p| > 0 &&
        p[0] == u &&
        p[|p| - 1] == v &&
        path_follows_edges(es, p);

    path_preserved_by_extension(es, e, p);
}

lemma new_vertex_connected(
    es: seq<Edge>, e: Edge, root: int, u: int, v: int)
    requires edges_connected(es, root, u)
    requires (e.0 == u && e.1 == v) || (e.0 == v && e.1 == u)
    ensures edges_connected(es + [e], root, v)
{
    var p :| |p| > 0 &&
        p[0] == root &&
        p[|p| - 1] == u &&
        path_follows_edges(es, p);

    path_preserved_by_extension(es, e, p);
    appended_edge_is_present(es, e);
    path_append_vertex(es + [e], p, v);
}

lemma crossing_edge_exists(
    g: seq<seq<(int, int)>>,
    visited: set<int>)
    requires |g| > 0
    requires graph_is_connected(g)
    requires 0 in visited
    requires visited < vertex_range(|g|)
    ensures exists u: int, v: int, w: int ::
        u in visited &&
        v in vertex_range(|g|) - visited &&
        has_edge(g, u, v, w)
{
    vertex_range_properties(|g|);

    assert exists z: int ::
        z in vertex_range(|g|) && z !in visited by
    {
        if !(exists z: int ::
            z in vertex_range(|g|) && z !in visited)
        {
            assert forall z: int ::
                z in vertex_range(|g|) ==> z in visited;
            assert visited == vertex_range(|g|);
        }
    }

    var z :| z in vertex_range(|g|) && z !in visited;
    assert nodes_have_path(g, 0, z);

    var p :| |p| > 0 &&
        p[0] == 0 &&
        p[|p| - 1] == z &&
        path_follows_graph(g, p);

    var j := 0;
    while p[j] in visited
        invariant 0 <= j < |p|
        invariant forall k: int ::
            0 <= k <= j ==> p[k] in visited
        invariant p[|p| - 1] == z
        invariant z !in visited
        decreases |p| - 1 - j
    {
        assert j < |p| - 1;
        j := j + 1;
    }

    assert j > 0;
    assert p[j - 1] in visited;
    assert p[j] !in visited;
    assert graph_has_any_edge(g, p[j - 1], p[j]);

    var i :| 0 <= p[j - 1] < |g| &&
        0 <= i < |g[p[j - 1]]| &&
        g[p[j - 1]][i].0 == p[j];

    var u := p[j - 1];
    var v := p[j];
    var w := g[u][i].1;

    assert has_edge(g, u, v, w);
    assert 0 <= v < |g|;
    assert v in vertex_range(|g|);
}

lemma append_preserves_validity(
    g: seq<seq<(int, int)>>,
    es: seq<Edge>,
    e: Edge)
    requires are_valid_edges(g, es)
    requires has_edge(g, e.0, e.1, e.2)
    ensures are_valid_edges(g, es + [e])
{
    forall k: int | 0 <= k < |es + [e]|
        ensures has_edge(
            g,
            (es + [e])[k].0,
            (es + [e])[k].1,
            (es + [e])[k].2)
    {
        if k < |es| {
            assert (es + [e])[k] == es[k];
        } else {
            assert k == |es|;
            assert (es + [e])[k] == e;
        }
    }
}

lemma spanning_tree_exists(g: seq<seq<(int, int)>>)
    requires |g| > 0
    requires graph_is_connected(g)
    ensures exists es: seq<Edge> :: is_spanning_tree(g, es)
{
    vertex_range_properties(|g|);

    var visited: set<int> := {0};
    var es: seq<Edge> := [];

    connected_reflexive(es, 0);

    while visited != vertex_range(|g|)
        invariant visited <= vertex_range(|g|)
        invariant 0 in visited
        invariant |visited| == |es| + 1
        invariant are_valid_edges(g, es)
        invariant forall x: int :: x in visited ==>
            edges_connected(es, 0, x)
        decreases |g| - |visited|
    {
        assert visited < vertex_range(|g|);
        crossing_edge_exists(g, visited);

        var u, v, w :|
            u in visited &&
            v in vertex_range(|g|) - visited &&
            has_edge(g, u, v, w);

        var e: Edge := (u, v, w);
        var oldVisited := visited;
        var oldEs := es;

        append_preserves_validity(g, es, e);
        es := es + [e];

        forall x: int | x in oldVisited
            ensures edges_connected(es, 0, x)
        {
            connection_preserved(oldEs, e, 0, x);
        }

        new_vertex_connected(oldEs, e, 0, u, v);

        visited := oldVisited + {v};
        assert v !in oldVisited;
        assert |visited| == |oldVisited| + 1;
    }

    assert |visited| == |g|;
    assert |es| == |g| - 1;

    assert is_spanning(g, es) by
    {
        forall u: int, v: int |
            0 <= u < |g| && 0 <= v < |g|
            ensures edges_connected(es, u, v)
        {
            assert u in vertex_range(|g|);
            assert v in vertex_range(|g|);
            assert edges_connected(es, 0, u);
            assert edges_connected(es, 0, v);
            connected_symmetric(es, 0, u);
            connected_transitive(es, u, 0, v);
        }
    }
}

function concrete_has_edge(
    g: seq<seq<(int, int)>>,
    u: int,
    v: int,
    w: int): bool
{
    0 <= u < |g| &&
    exists i: int | 0 <= i < |g[u]| ::
        g[u][i].0 == v && g[u][i].1 == w
}

lemma concrete_has_edge_equivalent(
    g: seq<seq<(int, int)>>,
    u: int,
    v: int,
    w: int)
    ensures concrete_has_edge(g, u, v, w)
        <==> has_edge(g, u, v, w)
{
}

function concrete_valid_edges(
    g: seq<seq<(int, int)>>,
    es: seq<Edge>): bool
{
    forall k: int | 0 <= k < |es| ::
        concrete_has_edge(g, es[k].0, es[k].1, es[k].2)
}

lemma concrete_valid_edges_equivalent(
    g: seq<seq<(int, int)>>,
    es: seq<Edge>)
    ensures concrete_valid_edges(g, es)
        <==> are_valid_edges(g, es)
{
    forall k: int | 0 <= k < |es|
        ensures concrete_has_edge(
            g, es[k].0, es[k].1, es[k].2)
            <==>
            has_edge(g, es[k].0, es[k].1, es[k].2)
    {
        concrete_has_edge_equivalent(
            g, es[k].0, es[k].1, es[k].2);
    }
}

function concrete_connected(
    es: seq<Edge>,
    u: int,
    v: int): bool
    decreases |es|
{
    if |es| == 0 then
        u == v
    else
        var prefix := es[..|es| - 1];
        var e := es[|es| - 1];
        concrete_connected(prefix, u, v) ||
        (concrete_connected(prefix, u, e.0) &&
         concrete_connected(prefix, e.1, v)) ||
        (concrete_connected(prefix, u, e.1) &&
         concrete_connected(prefix, e.0, v))
}

lemma concrete_connected_reflexive(es: seq<Edge>, u: int)
    ensures concrete_connected(es, u, u)
    decreases |es|
{
    if |es| > 0 {
        concrete_connected_reflexive(es[..|es| - 1], u);
    }
}

lemma concrete_connected_symmetric(
    es: seq<Edge>, u: int, v: int)
    requires concrete_connected(es, u, v)
    ensures concrete_connected(es, v, u)
    decreases |es|
{
    if |es| > 0 {
        var prefix := es[..|es| - 1];
        var e := es[|es| - 1];

        if concrete_connected(prefix, u, v) {
            concrete_connected_symmetric(prefix, u, v);
        } else if concrete_connected(prefix, u, e.0) &&
                  concrete_connected(prefix, e.1, v) {
            concrete_connected_symmetric(prefix, u, e.0);
            concrete_connected_symmetric(prefix, e.1, v);
        } else {
            assert concrete_connected(prefix, u, e.1);
            assert concrete_connected(prefix, e.0, v);
            concrete_connected_symmetric(prefix, u, e.1);
            concrete_connected_symmetric(prefix, e.0, v);
        }
    }
}

lemma concrete_connected_transitive(
    es: seq<Edge>, a: int, b: int, c: int)
    requires concrete_connected(es, a, b)
    requires concrete_connected(es, b, c)
    ensures concrete_connected(es, a, c)
    decreases |es|
{
    if |es| == 0 {
        assert a == b == c;
    } else {
        var prefix := es[..|es| - 1];
        var e := es[|es| - 1];
        var x := e.0;
        var y := e.1;

        if concrete_connected(prefix, a, b) {
            if concrete_connected(prefix, b, c) {
                concrete_connected_transitive(prefix, a, b, c);
            } else if concrete_connected(prefix, b, x) &&
                      concrete_connected(prefix, y, c) {
                concrete_connected_transitive(prefix, a, b, x);
            } else {
                assert concrete_connected(prefix, b, y);
                assert concrete_connected(prefix, x, c);
                concrete_connected_transitive(prefix, a, b, y);
            }
        } else if concrete_connected(prefix, a, x) &&
                  concrete_connected(prefix, y, b) {
            if concrete_connected(prefix, b, c) {
                concrete_connected_transitive(prefix, y, b, c);
            } else if concrete_connected(prefix, b, x) &&
                      concrete_connected(prefix, y, c) {
                concrete_connected_transitive(prefix, y, b, x);
                concrete_connected_transitive(prefix, a, x, y);
                concrete_connected_transitive(prefix, a, y, c);
            } else {
                assert concrete_connected(prefix, b, y);
                assert concrete_connected(prefix, x, c);
                concrete_connected_transitive(prefix, a, x, c);
            }
        } else {
            assert concrete_connected(prefix, a, y);
            assert concrete_connected(prefix, x, b);

            if concrete_connected(prefix, b, c) {
                concrete_connected_transitive(prefix, x, b, c);
            } else if concrete_connected(prefix, b, x) &&
                      concrete_connected(prefix, y, c) {
                concrete_connected_transitive(prefix, a, y, c);
            } else {
                assert concrete_connected(prefix, b, y);
                assert concrete_connected(prefix, x, c);
                concrete_connected_transitive(prefix, x, b, y);
                concrete_connected_transitive(prefix, a, y, x);
                concrete_connected_transitive(prefix, a, x, c);
            }
        }
    }
}

lemma concrete_connection_preserved(
    es: seq<Edge>, e: Edge, u: int, v: int)
    requires concrete_connected(es, u, v)
    ensures concrete_connected(es + [e], u, v)
{
    assert (es + [e])[..|es + [e]| - 1] == es;
    assert (es + [e])[|es + [e]| - 1] == e;
}

lemma concrete_appended_endpoints_connected(
    es: seq<Edge>, e: Edge)
    ensures concrete_connected(es + [e], e.0, e.1)
{
    concrete_connected_reflexive(es, e.0);
    concrete_connected_reflexive(es, e.1);
}

lemma concrete_edge_is_connected(
    es: seq<Edge>, u: int, v: int)
    requires edge_in_set(es, u, v)
    ensures concrete_connected(es, u, v)
    decreases |es|
{
    if |es| > 0 {
        var prefix := es[..|es| - 1];
        var e := es[|es| - 1];

        if (e.0 == u && e.1 == v) ||
           (e.0 == v && e.1 == u) {
            concrete_appended_endpoints_connected(prefix, e);
            if e.0 == v && e.1 == u {
                concrete_connected_symmetric(es, v, u);
            }
        } else {
            assert edge_in_set(prefix, u, v) by
            {
                var i :| 0 <= i < |es| &&
                    ((es[i].0 == u && es[i].1 == v) ||
                     (es[i].0 == v && es[i].1 == u));
                assert i < |prefix|;
                assert prefix[i] == es[i];
            }
            concrete_edge_is_connected(prefix, u, v);
            concrete_connection_preserved(prefix, e, u, v);
        }
    }
}

lemma path_implies_concrete_connection(
    es: seq<Edge>, p: seq<int>)
    requires |p| > 0
    requires path_follows_edges(es, p)
    ensures concrete_connected(es, p[0], p[|p| - 1])
    decreases |p|
{
    if |p| == 1 {
        concrete_connected_reflexive(es, p[0]);
    } else {
        assert edge_in_set(es, p[0], p[1]);
        concrete_edge_is_connected(es, p[0], p[1]);

        assert path_follows_edges(es, p[1..]) by
        {
            forall k: int | 0 <= k < |p[1..]| - 1
                ensures edge_in_set(
                    es, p[1..][k], p[1..][k + 1])
            {
                assert p[1..][k] == p[k + 1];
                assert p[1..][k + 1] == p[k + 2];
            }
        }

        path_implies_concrete_connection(es, p[1..]);
        concrete_connected_transitive(
            es, p[0], p[1], p[|p| - 1]);
    }
}

lemma edges_connected_implies_concrete(
    es: seq<Edge>, u: int, v: int)
    requires edges_connected(es, u, v)
    ensures concrete_connected(es, u, v)
{
    var p :| |p| > 0 &&
        p[0] == u &&
        p[|p| - 1] == v &&
        path_follows_edges(es, p);

    path_implies_concrete_connection(es, p);
}

lemma concrete_implies_edges_connected(
    es: seq<Edge>, u: int, v: int)
    requires concrete_connected(es, u, v)
    ensures edges_connected(es, u, v)
    decreases |es|
{
    if |es| == 0 {
        assert u == v;
        connected_reflexive(es, u);
    } else {
        var prefix := es[..|es| - 1];
        var e := es[|es| - 1];

        if concrete_connected(prefix, u, v) {
            concrete_implies_edges_connected(prefix, u, v);
            connection_preserved(prefix, e, u, v);
        } else if concrete_connected(prefix, u, e.0) &&
                  concrete_connected(prefix, e.1, v) {
            concrete_implies_edges_connected(prefix, u, e.0);
            concrete_implies_edges_connected(prefix, e.1, v);

            connection_preserved(prefix, e, u, e.0);
            connection_preserved(prefix, e, e.1, v);

            concrete_appended_endpoints_connected(prefix, e);
            concrete_implies_edges_connected(
                prefix + [e], e.0, e.1);

            connected_transitive(
                prefix + [e], u, e.0, e.1);
            connected_transitive(
                prefix + [e], u, e.1, v);
        } else {
            assert concrete_connected(prefix, u, e.1);
            assert concrete_connected(prefix, e.0, v);

            concrete_implies_edges_connected(prefix, u, e.1);
            concrete_implies_edges_connected(prefix, e.0, v);

            connection_preserved(prefix, e, u, e.1);
            connection_preserved(prefix, e, e.0, v);

            concrete_appended_endpoints_connected(prefix, e);
            concrete_implies_edges_connected(
                prefix + [e], e.0, e.1);
            connected_symmetric(
                prefix + [e], e.0, e.1);

            connected_transitive(
                prefix + [e], u, e.1, e.0);
            connected_transitive(
                prefix + [e], u, e.0, v);
        }
    }
}

lemma concrete_connected_equivalent(
    es: seq<Edge>, u: int, v: int)
    ensures concrete_connected(es, u, v)
        <==> edges_connected(es, u, v)
{
    if concrete_connected(es, u, v) {
        concrete_implies_edges_connected(es, u, v);
    }
    if edges_connected(es, u, v) {
        edges_connected_implies_concrete(es, u, v);
    }
}

function concrete_spanning_tree(
    g: seq<seq<(int, int)>>,
    es: seq<Edge>): bool
{
    |g| > 0 &&
    concrete_valid_edges(g, es) &&
    |es| == |g| - 1 &&
    forall v: int | 0 <= v < |g| ::
        concrete_connected(es, 0, v)
}

lemma concrete_spanning_tree_equivalent(
    g: seq<seq<(int, int)>>,
    es: seq<Edge>)
    requires |g| > 0
    ensures concrete_spanning_tree(g, es)
        <==> is_spanning_tree(g, es)
{
    concrete_valid_edges_equivalent(g, es);

    if concrete_spanning_tree(g, es) {
        assert is_spanning(g, es) by
        {
            forall u: int, v: int |
                0 <= u < |g| && 0 <= v < |g|
                ensures edges_connected(es, u, v)
            {
                concrete_implies_edges_connected(es, 0, u);
                concrete_implies_edges_connected(es, 0, v);
                connected_symmetric(es, 0, u);
                connected_transitive(es, u, 0, v);
            }
        }
    }

    if is_spanning_tree(g, es) {
        forall v: int | 0 <= v < |g|
            ensures concrete_connected(es, 0, v)
        {
            assert edges_connected(es, 0, v);
            edges_connected_implies_concrete(es, 0, v);
        }
    }
}

function concrete_weight(es: seq<Edge>): int
    decreases |es|
{
    if |es| == 0 then 0
    else es[0].2 + concrete_weight(es[1..])
}

lemma concrete_weight_equivalent(es: seq<Edge>)
    ensures concrete_weight(es) == total_weight(es)
    decreases |es|
{
    if |es| > 0 {
        concrete_weight_equivalent(es[1..]);
    }
}

function row_edges(
    row: seq<(int, int)>,
    u: int): seq<Edge>
    decreases |row|
{
    if |row| == 0 then []
    else [(u, row[0].0, row[0].1)] + row_edges(row[1..], u)
}

function graph_edges(
    g: seq<seq<(int, int)>>,
    start: nat): seq<Edge>
    requires start <= |g|
    decreases |g| - start
{
    if start == |g| then []
    else row_edges(g[start], start) + graph_edges(g, start + 1)
}

lemma row_edge_is_listed(
    row: seq<(int, int)>,
    u: int,
    i: int)
    requires 0 <= i < |row|
    ensures (u, row[i].0, row[i].1) in row_edges(row, u)
    decreases |row|
{
    if i > 0 {
        row_edge_is_listed(row[1..], u, i - 1);
        assert row[1..][i - 1] == row[i];
    }
}

lemma graph_row_edge_is_listed(
    g: seq<seq<(int, int)>>,
    start: nat,
    u: int,
    e: Edge)
    requires start <= u < |g|
    requires e in row_edges(g[u], u)
    ensures e in graph_edges(g, start)
    decreases u - start
{
    if start < u {
        graph_row_edge_is_listed(g, start + 1, u, e);
    }
}

lemma every_graph_edge_is_listed(
    g: seq<seq<(int, int)>>,
    e: Edge)
    requires has_edge(g, e.0, e.1, e.2)
    ensures e in graph_edges(g, 0)
{
    var i :| 0 <= e.0 < |g| &&
        0 <= i < |g[e.0]| &&
        g[e.0][i].0 == e.1 &&
        g[e.0][i].1 == e.2;

    row_edge_is_listed(g[e.0], e.0, i);
    graph_row_edge_is_listed(g, 0, e.0, e);
}

function add_head(
    e: Edge,
    sequences: seq<seq<Edge>>): seq<seq<Edge>>
    decreases |sequences|
{
    if |sequences| == 0 then []
    else [[e] + sequences[0]] +
        add_head(e, sequences[1..])
}

function prepend_each(
    choices: seq<Edge>,
    sequences: seq<seq<Edge>>): seq<seq<Edge>>
    decreases |choices|
{
    if |choices| == 0 then []
    else add_head(choices[0], sequences) +
        prepend_each(choices[1..], sequences)
}

function all_edge_sequences(
    choices: seq<Edge>,
    length: nat): seq<seq<Edge>>
    decreases length
{
    if length == 0 then
        [[]]
    else
        prepend_each(
            choices,
            all_edge_sequences(choices, length - 1))
}

lemma add_head_contains(
    e: Edge,
    sequences: seq<seq<Edge>>,
    s: seq<Edge>)
    requires s in sequences
    ensures [e] + s in add_head(e, sequences)
    decreases |sequences|
{
    if s != sequences[0] {
        assert s in sequences[1..];
        add_head_contains(e, sequences[1..], s);
    }
}

lemma prepend_each_contains(
    choices: seq<Edge>,
    sequences: seq<seq<Edge>>,
    e: Edge,
    s: seq<Edge>)
    requires e in choices
    requires s in sequences
    ensures [e] + s in prepend_each(choices, sequences)
    decreases |choices|
{
    if e == choices[0] {
        add_head_contains(e, sequences, s);
    } else {
        assert e in choices[1..];
        prepend_each_contains(
            choices[1..], sequences, e, s);
    }
}

lemma all_edge_sequences_contains(
    choices: seq<Edge>,
    s: seq<Edge>)
    requires forall i: int ::
        0 <= i < |s| ==> s[i] in choices
    ensures s in all_edge_sequences(choices, |s|)
    decreases |s|
{
    if |s| == 0 {
        assert s == [];
    } else {
        assert forall i: int ::
            0 <= i < |s[1..]| ==> s[1..][i] in choices by
        {
            forall i: int | 0 <= i < |s[1..]|
                ensures s[1..][i] in choices
            {
                assert s[1..][i] == s[i + 1];
            }
        }

        all_edge_sequences_contains(choices, s[1..]);
        prepend_each_contains(
            choices,
            all_edge_sequences(choices, |s| - 1),
            s[0],
            s[1..]);

        assert [s[0]] + s[1..] == s;
    }
}

datatype TreeSearchResult =
    TreeNotFound
  | TreeFound(value: seq<Edge>)

function find_tree(
    g: seq<seq<(int, int)>>,
    candidates: seq<seq<Edge>>): TreeSearchResult
    decreases |candidates|
{
    if |candidates| == 0 then
        TreeNotFound
    else if concrete_spanning_tree(g, candidates[0]) then
        TreeFound(candidates[0])
