lemma vertex_range_properties(n: nat)
    ensures |vertex_range(n)| == n
    ensures forall x: int :: x in vertex_range(n) <==> 0 <= x < n
    decreases n
{
    if n > 0 {
        vertex_range_properties(n - 1);
        assert n - 1 !in vertex_range(n - 1);
    }
