lemma SwapPerm(p: seq<int>, n: int, i: int, m: int)
    requires is_valid_index_permutation(p, n)
    requires 0 <= i < n && 0 <= m < n
    ensures is_valid_index_permutation(p[i := p[m]][m := p[i]], n)
{
    var q := p[i := p[m]][m := p[i]];
    assert |q| == n;
    forall x | 0 <= x < n
        ensures 0 <= q[x] < n
    {
        var fx := if x == i then m else if x == m then i else x;
        assert q[x] == p[fx];
    }
    forall x, y | 0 <= x < y < n
        ensures q[x] != q[y]
    {
        var fx := if x == i then m else if x == m then i else x;
        var fy := if y == i then m else if y == m then i else y;
        assert q[x] == p[fx];
        assert q[y] == p[fy];
        assert fx != fy;
        if fx < fy {
            assert p[fx] != p[fy];
        } else {
            assert p[fy] != p[fx];
        }
    }
}

