method quick_sort(v: seq<int>) returns (v_new: seq<int>)
    ensures is_sorted(v_new)
    ensures is_permutation(v, v_new)
{
    var n := |v|;
    var a := v;
    ghost var p := seq(n, k => k);
    var i := 0;
    while i < n
        invariant 0 <= i <= n
        invariant |a| == n
        invariant is_valid_index_permutation(p, n)
        invariant forall k :: 0 <= k < n ==> a[k] == v[p[k]]
        invariant forall x, y :: 0 <= x < y < i ==> a[x] <= a[y]
        invariant forall x, y :: 0 <= x < i <= y < n ==> a[x] <= a[y]
    {
        var m := i;
        var j := i + 1;
        while j < n
            invariant i <= m < n
            invariant i + 1 <= j <= n
            invariant forall k :: i <= k < j ==> a[m] <= a[k]
        {
            if a[j] < a[m] {
                m := j;
            }
            j := j + 1;
        }
        SwapPerm(p, n, i, m);
        var ai := a[i];
        a := a[i := a[m]][m := ai];
        p := p[i := p[m]][m := p[i]];
        i := i + 1;
    }
    v_new := a;
    PermWitness(v, v_new, p);
}

