  ensures T2[..|F| + 1] == F + [e]
  ensures forall k: int :: 0 <= k < |T| && k != j ==> T[k] in T2
  ensures forall k: int :: 0 <= k < |T2| ==> T2[k] == e || T2[k] in T
  ensures e in T2
  ensures total_weight(T2) == total_weight(T) - T[j].2 + e.2
{
  var B := T[|F|..j];
  var C := T[j + 1..];
  var L := F + B + [T[j]] + C;
  assert |L| == |T|;
  forall k: int | 0 <= k < |T| ensures L[k] == T[k] {
    if k < |F| {
      assert T[..|F|][k] == T[k];
    } else if k < j {
      assert B[k - |F|] == T[k];
    } else if k > j {
      assert C[k - j - 1] == T[k];
    }
  }
  assert L == T;
  T2 := F + [e] + B + C;
  assert |T2| == |T|;
  forall k: int | 0 <= k < |F| ensures T2[k] == T[k] {
    assert T[..|F|][k] == T[k];
  }
  assert T2[|F|] == e;
  forall k: int | |F| < k <= j ensures T2[k] == T[k - 1] {
    assert B[k - |F| - 1] == T[k - 1];
  }
  forall k: int | j < k < |T| ensures T2[k] == T[k] {
    assert C[k - j - 1] == T[k];
  }
  forall k: int | 0 <= k < |T| && k != j ensures T[k] in T2 {
    if k < |F| {
      assert T2[k] == T[k];
    } else if k < j {
      assert T2[k + 1] == T[k];
    } else {
      assert T2[k] == T[k];
    }
  }
  forall k: int | 0 <= k < |T2| ensures T2[k] == e || T2[k] in T {
    if k < |F| {
      assert T2[k] == T[k];
    } else if k == |F| {
    } else if k <= j {
      assert T2[k] == T[k - 1];
    } else {
      assert T2[k] == T[k];
    }
  }
  forall k: int | 0 <= k < |F| + 1 ensures T2[..|F| + 1][k] == (F + [e])[k] {
    if k < |F| {
      assert T2[k] == F[k];
    } else {
      assert T2[k] == e;
    }
  }
  assert T2[..|F| + 1] == F + [e];
  tw_concat(F + B + [T[j]], C);
  tw_concat(F + B, [T[j]]);
  tw_concat(F, B);
  tw_single(T[j]);
  tw_concat(F + [e] + B, C);
  tw_concat(F + [e], B);
  tw_concat(F, [e]);
  tw_single(e);
}

