I restructured the proof to fix the timeout by splitting it into small lemmas, so each one checks against a small context. I haven't run Dafny on this version.

- **Hiding large definitions.** Graph connectivity, the main loop invariant (`prim_inv`) and the "can still become an MST" property (`promising`) are now `opaque`. Each is revealed only inside the lemma that needs it.
- **Splitting the exchange step.** It is now a set of focused lemmas:
  - `splice` builds the swapped tree and proves its index and weight facts.
  - `valid_from` proves every edge of the new tree is a graph edge.
  - `tail_conn` proves the rest of the old path still connects in the new tree.
  - `spanning_from` proves the new tree still reaches every node.
- **Isolating the main method.** `prim_mst` only extracts the facts it needs and calls `prim_core`. This keeps the three-variable "no duplicate edges" quantifier from `well_formed` out of the loop proofs.

```dafny
ghost predicate bounded_targets(g: seq<seq<(int, int)>>) {
  forall u: int, i: int :: 0 <= u < |g| && 0 <= i < |g[u]| ==> 0 <= g[u][i].0 < |g|
}

opaque ghost predicate connected_g(g: seq<seq<(int, int)>>) {
  graph_is_connected(g)
}

ghost predicate min_cross(g: seq<seq<(int, int)>>, S: set<int>, w: int) {
  forall u: int, i: int :: 0 <= u < |g| && 0 <= i < |g[u]| && ((u in S) != (g[u][i].0 in S)) ==> w <= g[u][i].1
}

ghost predicate good_ext(g: seq<seq<(int, int)>>, F: seq<Edge>, T: seq<Edge>, T2: seq<Edge>) {
  is_spanning_tree(g, T2) && |F| <= |T2| && T2[..|F|] == F && total_weight(T2) <= total_weight(T)
}

opaque ghost predicate promising(g: seq<seq<(int, int)>>, F: seq<Edge>) {
  forall T: seq<Edge> {:trigger is_spanning_tree(g, T)} :: is_spanning_tree(g, T) ==>
    exists T2: seq<Edge> {:trigger good_ext(g, F, T, T2)} :: good_ext(g, F, T, T2)
}

opaque ghost predicate prim_inv(g: seq<seq<(int, int)>>, F: seq<Edge>, S: set<int>) {
  && 0 in S
  && (forall k: int :: 0 <= k < |F| ==> F[k].0 in S && F[k].1 in S)
  && are_valid_edges(g, F)
  && (forall s: int :: s in S ==> edges_connected(F, 0, s))
  && promising(g, F)
}

lemma tw_concat(A: seq<Edge>, B: seq<Edge>)
  ensures total_weight(A + B) == total_weight(A) + total_weight(B)
  decreases |A|
{
  if |A| == 0 {
    assert A + B == B;
  } else {
    assert (A + B)[1..] == A[1..] + B;
    tw_concat(A[1..], B);
  }
}

lemma tw_single(x: Edge)
  ensures total_weight([x]) == x.2
{
  assert [x][1..] == [];
  assert total_weight([x][1..]) == 0;
}

lemma range_card(X: set<int>, n: int)
  requires n >= 0
  requires forall v: int :: v in X <==> 0 <= v < n
  ensures |X| == n
  decreases n
{
  if n == 0 {
    assert X == {};
  } else {
    var Y := X - {n - 1};
    range_card(Y, n - 1);
    assert X == Y + {n - 1};
    assert Y * {n - 1} == {};
  }
}

lemma card_add(S: set<int>, b: int)
  requires b !in S
  ensures |S + {b}| == |S| + 1
{
  assert S * {b} == {};
  assert |{b}| == 1;
}

lemma edge_sym(E: seq<Edge>, x: int, y: int)
  requires edge_in_set(E, x, y)
  ensures edge_in_set(E, y, x)
{
  var i: int :| 0 <= i < |E| && ((E[i].0 == x && E[i].1 == y) || (E[i].0 == y && E[i].1 == x));
}

lemma edge_via(E: seq<Edge>, t: Edge, u: int, v: int)
  requires t in E
  requires (t.0 == u && t.1 == v) || (t.0 == v && t.1 == u)
  ensures edge_in_set(E, u, v)
{
  var idx: int :| 0 <= idx < |E| && E[idx] == t;
}

lemma conn_refl(E: seq<Edge>, x: int)
  ensures edges_connected(E, x, x)
{
  var p: seq<int> := [x];
  assert p[0] == x && p[|p| - 1] == x;
  assert path_follows_edges(E, p);
}

lemma conn_edge(E: seq<Edge>, x: int, y: int)
  requires edge_in_set(E, x, y)
  ensures edges_connected(E, x, y)
{
  var p: seq<int> := [x, y];
  assert p[0] == x && p[1] == y && p[|p| - 1] == y;
  forall k: int | 0 <= k < |p| - 1 ensures edge_in_set(E, p[k], p[k+1]) {
    assert k == 0;
  }
  assert path_follows_edges(E, p);
