  requires forall idx: int :: 0 <= idx < |E| ==> E[idx] in E2
  requires edges_connected(E, u, v)
  ensures edges_connected(E2, u, v)
{
  var p: seq<int> :| |p| > 0 && p[0] == u && p[|p| - 1] == v && path_follows_edges(E, p);
  forall k: int | 0 <= k < |p| - 1 ensures edge_in_set(E2, p[k], p[k+1]) {
    assert edge_in_set(E, p[k], p[k+1]);
    edge_sub(E, E2, p[k], p[k+1]);
  }
  assert path_follows_edges(E2, p);
}

lemma path_lift(E: seq<Edge>, E2: seq<Edge>, p: seq<int>)
  requires forall u: int, v: int :: edge_in_set(E, u, v) ==> edges_connected(E2, u, v)
  requires |p| > 0 && path_follows_edges(E, p)
  ensures edges_connected(E2, p[0], p[|p| - 1])
  decreases |p|
{
  if |p| == 1 {
    conn_refl(E2, p[0]);
  } else {
    var q := p[1..];
    forall k: int | 0 <= k < |q| - 1 ensures edge_in_set(E, q[k], q[k+1]) {
      assert q[k] == p[k+1] && q[k+1] == p[k+1+1];
      assert edge_in_set(E, p[k+1], p[k+1+1]);
