  assert q[0] == p[i + 1] && q[|q| - 1] == p[|p| - 1];
}

lemma spanning_from(g: seq<seq<(int, int)>>, T: seq<Edge>, T2: seq<Edge>, j: int, x: int, y: int)
  requires is_spanning(g, T)
  requires 0 <= j < |T|
  requires (T[j].0 == x && T[j].1 == y) || (T[j].0 == y && T[j].1 == x)
  requires forall k: int :: 0 <= k < |T| && k != j ==> T[k] in T2
  requires edges_connected(T2, x, y)
  ensures is_spanning(g, T2)
{
  conn_sym(T2, x, y);
  forall u: int, v: int | edge_in_set(T, u, v) ensures edges_connected(T2, u, v) {
    var idx: int :| 0 <= idx < |T| && ((T[idx].0 == u && T[idx].1 == v) || (T[idx].0 == v && T[idx].1 == u));
    if idx == j {
      if u == x && v == y {
      } else {
        assert u == y && v == x;
      }
    } else {
      assert T[idx] in T2;
      edge_via(T2, T[idx], u, v);
      conn_edge(T2, u, v);
    }
  }
  forall u: int, v: int | 0 <= u < |g| && 0 <= v < |g| ensures edges_connected(T2, u, v) {
    assert edges_connected(T, u, v);
    var pp: seq<int> :| |pp| > 0 && pp[0] == u && pp[|pp| - 1] == v && path_follows_edges(T, pp);
    path_lift(T, T2, pp);
  }
}

lemma exchange(g: seq<seq<(int, int)>>, F: seq<Edge>, S: set<int>, r: int, e: Edge, T: seq<Edge>) returns (T2: seq<Edge>)
  requires is_spanning_tree(g, T)
  requires |F| <= |T| && T[..|F|] == F
  requires forall k: int :: 0 <= k < |F| ==> F[k].0 in S && F[k].1 in S
  requires r in S
  requires forall s: int :: s in S ==> edges_connected(F, r, s)
  requires has_edge(g, e.0, e.1, e.2)
  requires 0 <= e.0 < |g| && 0 <= e.1 < |g|
  requires (e.0 in S) != (e.1 in S)
  requires min_cross(g, S, e.2)
  ensures is_spanning_tree(g, T2)
  ensures |F| + 1 <= |T2| && T2[..|F| + 1] == F + [e]
  ensures total_weight(T2) <= total_weight(T)
{
  var a: int := if e.0 in S then e.0 else e.1;
  var b: int := if e.0 in S then e.1 else e.0;
  assert a in S && b !in S;
  assert 0 <= a < |g| && 0 <= b < |g|;
  assert edges_connected(T, a, b);
  var p: seq<int> :| |p| > 0 && p[0] == a && p[|p| - 1] == b && path_follows_edges(T, p);
  var i := last_in(p, S);
  var x := p[i];
  var y := p[i + 1];
  assert x in S && y !in S;
  assert edge_in_set(T, x, y);
  var j: int :| 0 <= j < |T| && ((T[j].0 == x && T[j].1 == y) || (T[j].0 == y && T[j].1 == x));
  if j < |F| {
    assert T[..|F|][j] == T[j];
    assert T[j] == F[j];
    assert false;
  }
  T2 := splice(F, T, e, j);
  valid_from(g, T, T2, e);

  assert has_edge(g, T[j].0, T[j].1, T[j].2);
  var ii: int :| 0 <= T[j].0 < |g| && 0 <= ii < |g[T[j].0]| && g[T[j].0][ii].0 == T[j].1 && g[T[j].0][ii].1 == T[j].2;
  assert (T[j].0 in S) != (T[j].1 in S);
  assert (T[j].0 in S) != (g[T[j].0][ii].0 in S);
  assert e.2 <= T[j].2;

  forall idx: int | 0 <= idx < |F| ensures F[idx] in T2 {
    assert T[..|F|][idx] == T[idx];
    assert T[idx] in T2;
  }
  assert edges_connected(F, r, x);
  assert edges_connected(F, r, a);
  conn_sym(F, r, x);
  conn_trans(F, x, r, a);
  conn_sub(F, T2, x, a);
  edge_via(T2, e, a, b);
  conn_edge(T2, a, b);
  tail_conn(T, T2, j, S, p, i);
  assert edges_connected(T2, y, b);
  conn_trans(T2, x, a, b);
  conn_sym(T2, y, b);
  conn_trans(T2, x, b, y);
  spanning_from(g, T, T2, j, x, y);
  assert |T2| == |g| - 1;
}

lemma promising_step(g: seq<seq<(int, int)>>, F: seq<Edge>, S: set<int>, r: int, e: Edge)
  requires promising(g, F)
  requires forall k: int :: 0 <= k < |F| ==> F[k].0 in S && F[k].1 in S
  requires r in S
  requires forall s: int :: s in S ==> edges_connected(F, r, s)
  requires has_edge(g, e.0, e.1, e.2)
  requires 0 <= e.0 < |g| && 0 <= e.1 < |g|
  requires (e.0 in S) != (e.1 in S)
  requires min_cross(g, S, e.2)
  ensures promising(g, F + [e])
{
  reveal promising();
  forall T: seq<Edge> | is_spanning_tree(g, T) ensures exists T2: seq<Edge> :: good_ext(g, F + [e], T, T2) {
    var T1: seq<Edge> :| good_ext(g, F, T, T1);
    var T2 := exchange(g, F, S, r, e, T1);
    assert good_ext(g, F + [e], T, T2);
  }
}

lemma inv_init(g: seq<seq<(int, int)>>)
  requires |g| > 0
  ensures prim_inv(g, [], {0})
{
  reveal prim_inv();
  reveal promising();
  var E: seq<Edge> := [];
  conn_refl(E, 0);
  forall T: seq<Edge> | is_spanning_tree(g, T) ensures exists T2: seq<Edge> :: good_ext(g, E, T, T2) {
    assert T[..0] == [];
    assert good_ext(g, E, T, T);
  }
  assert promising(g, E);
}

lemma inv_step(g: seq<seq<(int, int)>>, F: seq<Edge>, S: set<int>, e: Edge, b: int)
  requires prim_inv(g, F, S)
  requires has_edge(g, e.0, e.1, e.2)
  requires 0 <= e.0 < |g| && 0 <= e.1 < |g|
  requires (e.0 in S) != (e.1 in S)
  requires min_cross(g, S, e.2)
  requires b == (if e.0 in S then e.1 else e.0)
  ensures prim_inv(g, F + [e], S + {b})
{
  reveal prim_inv();
  var a: int := if e.0 in S then e.0 else e.1;
  assert a in S;
  var NF := F + [e];
  promising_step(g, F, S, 0, e);
  forall idx: int | 0 <= idx < |F| ensures F[idx] in NF {
    assert NF[idx] == F[idx];
  }
  assert NF[|F|] == e;
  assert e in NF;
  forall s: int | s in S + {b} ensures edges_connected(NF, 0, s) {
    if s in S {
      conn_sub(F, NF, 0, s);
    } else {
      conn_sub(F, NF, 0, a);
      edge_via(NF, e, a, b);
      conn_edge(NF, a, b);
      conn_trans(NF, 0, a, b);
    }
  }
  forall k: int | 0 <= k < |NF| ensures NF[k].0 in S + {b} && NF[k].1 in S + {b} {
    if k < |F| {
      assert NF[k] == F[k];
    } else {
      assert NF[k] == e;
    }
  }
  forall k: int | 0 <= k < |NF| ensures has_edge(g, NF[k].0, NF[k].1, NF[k].2) {
    if k < |F| {
      assert NF[k] == F[k];
      assert has_edge(g, F[k].0, F[k].1, F[k].2);
    } else {
      assert NF[k] == e;
    }
  }
  assert are_valid_edges(g, NF);
}

lemma inv_final(g: seq<seq<(int, int)>>, F: seq<Edge>, S: set<int>)
  requires prim_inv(g, F, S)
  requires forall v: int :: v in S <==> 0 <= v < |g|
  requires |F| == |g| - 1
  ensures is_mst(g, F)
{
  reveal prim_inv();
  forall u: int, v: int | 0 <= u < |g| && 0 <= v < |g| ensures edges_connected(F, u, v) {
    assert u in S && v in S;
    assert edges_connected(F, 0, u);
    assert edges_connected(F, 0, v);
    conn_sym(F, 0, u);
    conn_trans(F, u, 0, v);
  }
  assert is_spanning(g, F);
  assert is_spanning_tree(g, F);
  reveal promising();
  forall other: seq<Edge> | is_spanning_tree(g, other) ensures total_weight(F) <= total_weight(other) {
    var T2: seq<Edge> :| good_ext(g, F, other, T2);
    assert |T2| == |F|;
    assert T2[..|T2|] == T2;
    assert T2 == F;
  }
}

method prim_core(g: seq<seq<(int, int)>>) returns (edges: seq<Edge>)
  requires |g| > 0
  requires bounded_targets(g)
  requires connected_g(g)
  ensures is_mst(g, edges)
{
  var n: int := |g|;
  var inTree: seq<bool> := seq(n, (v: int) => v == 0);
  ghost var S: set<int> := {0};
  ghost var R: set<int> := set v: int | 0 <= v < n;
  edges := [];
  inv_init(g);

  while true
    invariant |inTree| == n
    invariant 0 in S
    invariant forall s: int :: s in S ==> 0 <= s < n
    invariant forall v: int :: 0 <= v < n ==> (inTree[v] <==> v in S)
    invariant |S| == |edges| + 1
    invariant prim_inv(g, edges, S)
    decreases R - S
  {
    var found: bool := false;
    var bu: int := 0;
    var bi: int := 0;
    var u: int := 0;
    while u < n
      invariant 0 <= u <= n
      invariant found ==> 0 <= bu < n && 0 <= bi < |g[bu]| && inTree[bu] != inTree[g[bu][bi].0]
      invariant forall uu: int, ii: int :: 0 <= uu < u && 0 <= ii < |g[uu]| && inTree[uu] != inTree[g[uu][ii].0] ==> found && g[bu][bi].1 <= g[uu][ii].1
    {
      var i: int := 0;
      while i < |g[u]|
        invariant 0 <= i <= |g[u]|
        invariant found ==> 0 <= bu < n && 0 <= bi < |g[bu]| && inTree[bu] != inTree[g[bu][bi].0]
        invariant forall uu: int, ii: int :: 0 <= uu < u && 0 <= ii < |g[uu]| && inTree[uu] != inTree[g[uu][ii].0] ==> found && g[bu][bi].1 <= g[uu][ii].1
        invariant forall ii: int :: 0 <= ii < i && inTree[u] != inTree[g[u][ii].0] ==> found && g[bu][bi].1 <= g[u][ii].1
      {
        var v: int := g[u][i].0;
        if inTree[u] != inTree[v] {
          if !found || g[u][i].1 < g[bu][bi].1 {
            found := true;
            bu := u;
            bi := i;
          }
        }
        i := i + 1;
      }
      u := u + 1;
    }

    if !found {
      forall uu: int, ii: int | 0 <= uu < n && 0 <= ii < |g[uu]| ensures (uu in S) == (g[uu][ii].0 in S) {
        assert 0 <= g[uu][ii].0 < n;
        assert inTree[uu] == inTree[g[uu][ii].0];
      }
      all_reached(g, S, 0);
      break;
    }

    var u0: int := bu;
    var v0: int := g[bu][bi].0;
    var w0: int := g[bu][bi].1;
    var e: Edge := (u0, v0, w0);
    assert 0 <= v0 < n;
    assert g[u0][bi].0 == v0 && g[u0][bi].1 == w0;
    assert has_edge(g, u0, v0, w0);
    assert (u0 in S) != (v0 in S);
    forall uu: int, ii: int | 0 <= uu < n && 0 <= ii < |g[uu]| && ((uu in S) != (g[uu][ii].0 in S))
      ensures w0 <= g[uu][ii].1
    {
      assert 0 <= g[uu][ii].0 < n;
      assert inTree[uu] != inTree[g[uu][ii].0];
    }
    assert min_cross(g, S, w0);
    var b: int := if inTree[u0] then v0 else u0;
    assert b == (if e.0 in S then e.1 else e.0);
    inv_step(g, edges, S, e, b);
    assert b !in S && 0 <= b < n;
    card_add(S, b);
    assert b in R - S;
    assert b !in R - (S + {b});
    edges := edges + [e];
    inTree := inTree[b := true];
    S := S + {b};
  }

  assert forall v: int :: v in S <==> 0 <= v < n;
  range_card(S, n);
  assert |edges| == n - 1;
  inv_final(g, edges, S);
}

method prim_mst(graph: WeightedGraph) returns (edges: seq<Edge>)
    requires well_formed(graph)
    requires size(graph) > 0
    requires weights_bounded(view(graph))
    requires graph_is_connected(view(graph))
    ensures is_mst(view(graph), edges)
{
  assert view(graph) == graph.adj;
  assert |graph.adj| > 0;
  assert bounded_targets(graph.adj);
  reveal connected_g();
  assert connected_g(graph.adj);
  edges := prim_core(graph.adj);
}
