lemma empty_flow_is_valid(
    g: seq<seq<(int, int)>>,
    s: int,
    t: int)
    requires 0 <= s < |g|
    ensures is_valid_flow(g, map[], s, t)
    ensures flow_val(g, map[], s) == 0
{
