lemma get_flow_nonnegative(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int,
    u: int,
    v: int)
    requires is_valid_flow(g, f, s, t)
    ensures get_flow(f, u, v) >= 0
{
    if (u, v) in f {
        assert f[(u, v)] >= 0;
    } else {
        assert get_flow(f, u, v) == 0;
    }
}

lemma get_flow_bounded(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int,
    u: int,
    v: int)
    requires capacities_bounded(g)
    requires is_valid_flow(g, f, s, t)
    ensures 0 <= get_flow(f, u, v) <= 100_000
{
    get_flow_nonnegative(g, f, s, t, u, v);

    if (u, v) in f {
        assert f[(u, v)] >= 0;

        if f[(u, v)] > 0 {
            assert respects_capacity(g, f);
            assert exists c: int ::
                has_capacity(g, u, v, c) && f[(u, v)] <= c;

            var c: int :|
                has_capacity(g, u, v, c) && f[(u, v)] <= c;

            assert 0 <= c <= 100_000;
            assert f[(u, v)] <= 100_000;
        } else {
            assert f[(u, v)] == 0;
        }
    } else {
        assert get_flow(f, u, v) == 0;
    }
}

lemma sum_flow_out_bounded(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int,
    u: int,
    idx: int)
    requires capacities_bounded(g)
    requires is_valid_flow(g, f, s, t)
    requires 0 <= u < |g|
    requires 0 <= idx <= |g[u]|
    ensures 0 <= sum_flow_out_recursive(g, f, u, idx)
    ensures sum_flow_out_recursive(g, f, u, idx)
         <= idx * 100_000
    decreases idx
{
    if idx > 0 {
        sum_flow_out_bounded(g, f, s, t, u, idx - 1);
        get_flow_bounded(
            g, f, s, t, u, g[u][idx - 1].0);

        assert sum_flow_out_recursive(g, f, u, idx)
            == sum_flow_out_recursive(g, f, u, idx - 1)
             + get_flow(f, u, g[u][idx - 1].0);
    }
}

lemma sum_flow_in_nonnegative(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int,
    u: int,
    idx: int)
    requires is_valid_flow(g, f, s, t)
    requires 0 <= idx <= |g|
    ensures 0 <= sum_flow_in_recursive(g, f, u, idx)
    decreases idx
{
    if idx > 0 {
        sum_flow_in_nonnegative(g, f, s, t, u, idx - 1);
        get_flow_nonnegative(g, f, s, t, idx - 1, u);

        assert sum_flow_in_recursive(g, f, u, idx)
            == sum_flow_in_recursive(g, f, u, idx - 1)
             + get_flow(f, idx - 1, u);
    }
}

lemma valid_flow_upper_bound(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int)
    requires capacities_bounded(g)
    requires is_valid_flow(g, f, s, t)
    requires 0 <= s < |g|
    ensures flow_val(g, f, s) <= |g[s]| * 100_000
{
    sum_flow_out_bounded(g, f, s, t, s, |g[s]|);
    sum_flow_in_nonnegative(g, f, s, t, s, |g|);

    assert total_flow_out(g, f, s)
        == sum_flow_out_recursive(g, f, s, |g[s]|);
    assert total_flow_in(g, f, s)
        == sum_flow_in_recursive(g, f, s, |g|);
}

lemma find_max_flow_value_up_to(
    g: seq<seq<(int, int)>>,
    s: int,
    t: int,
    bound: int)
    returns (m: int, fm: FlowMap)
    requires 0 <= s < |g|
    requires 0 <= bound
    ensures is_valid_flow(g, fm, s, t)
    ensures flow_val(g, fm, s) == m
    ensures 0 <= m <= bound
    ensures forall f: FlowMap
        {:trigger is_valid_flow(g, f, s, t)} ::
        is_valid_flow(g, f, s, t)
        && 0 <= flow_val(g, f, s) <= bound
        ==> flow_val(g, f, s) <= m
    decreases bound
{
    if bound == 0 {
        empty_flow_is_valid(g, s, t);
        m := 0;
        fm := map[];
    } else {
        var previousM, previousFlow :=
            find_max_flow_value_up_to(g, s, t, bound - 1);

        if (exists f: FlowMap ::
                is_valid_flow(g, f, s, t)
                && flow_val(g, f, s) == bound)
        {
            var chosen: FlowMap :|
                is_valid_flow(g, chosen, s, t)
                && flow_val(g, chosen, s) == bound;

            m := bound;
            fm := chosen;
        } else {
            m := previousM;
            fm := previousFlow;

            forall f: FlowMap
                | is_valid_flow(g, f, s, t)
                  && 0 <= flow_val(g, f, s) <= bound
                ensures flow_val(g, f, s) <= m
            {
                if flow_val(g, f, s) == bound {
                    assert exists chosen: FlowMap ::
                        is_valid_flow(g, chosen, s, t)
                        && flow_val(g, chosen, s) == bound;
                    assert false;
                } else {
                    assert flow_val(g, f, s) <= bound - 1;
                    assert flow_val(g, f, s) <= previousM;
                }
            }
        }
    }
}

lemma max_flow_exists(
    g: seq<seq<(int, int)>>,
    s: int,
    t: int)
    requires capacities_bounded(g)
    requires 0 <= s < |g|
    ensures exists m: int, f: FlowMap ::
        is_max_flow(g, f, s, t)
        && flow_val(g, f, s) == m
{
    var bound := |g[s]| * 100_000;
    var m, fm := find_max_flow_value_up_to(g, s, t, bound);

    forall other: FlowMap
        | is_valid_flow(g, other, s, t)
        ensures flow_val(g, other, s) <= flow_val(g, fm, s)
    {
        valid_flow_upper_bound(g, other, s, t);

        if flow_val(g, other, s) < 0 {
            assert 0 <= m;
        } else {
            assert 0 <= flow_val(g, other, s) <= bound;
            assert flow_val(g, other, s) <= m;
        }
    }

    assert is_max_flow(g, fm, s, t);
    assert exists value: int, f: FlowMap ::
        is_max_flow(g, f, s, t)
        && flow_val(g, f, s) == value;
}

method max_flow_value(graph: CapacityGraph, s: int, t: int)
    returns (max_val: int)
    requires well_formed(graph)
    requires capacities_bounded(view(graph))
    requires 0 <= s < size(graph)
    requires 0 <= t < size(graph)
    requires s != t
    ensures exists f: FlowMap ::
            is_max_flow(view(graph), f, s, t)
            && flow_val(view(graph), f, s) == max_val
{
    max_flow_exists(view(graph), s, t);

    max_val :| exists f: FlowMap ::
        is_max_flow(view(graph), f, s, t)
        && flow_val(view(graph), f, s) == max_val;
}

