      var source := SwapIndex(b, k, m);

      if b == m {
        assert source == k;
      } else {
        assert b != k;
        assert source == b;
      }

      assert k <= source < n;
      assert p[b] == before[source];

      if a < k {
        assert SwapIndex(a, k, m) == a;
        assert p[a] == before[a];
        assert v[before[a]] <= v[before[source]];
      } else {
        assert a == k;
        assert SwapIndex(a, k, m) == m;
        assert p[a] == before[m];
        assert v[before[m]] <= v[before[source]];
      }
    }

    k := k + 1;
  }

  v_new := seq(n, i => v[p[i]]);
  assert |v_new| == n;

  forall i, j | 0 <= i < j < |v_new|
    ensures v_new[i] <= v_new[j]
  {
    assert v_new[i] == v[p[i]];
    assert v_new[j] == v[p[j]];
    assert v[p[i]] <= v[p[j]];
  }
  assert is_sorted(v_new);

  assert forall i {:trigger p[i]} ::
    0 <= i < |v| ==> v_new[i] == v[p[i]];

  IndexWitness(v, v_new, p);
}
