        assert SwapIndex(a, k, m) == m;
        assert p[a] == before[m];
        assert v[before[m]] <= v[before[source]];
      }
    }

    k := k + 1;
  }

  assert |p| == n;

  v_new := seq(n, i =>
    if 0 <= i < |p| then
      if 0 <= p[i] < |v| then v[p[i]] else 0
    else
      0);

  assert |v_new| == n;

  forall i | 0 <= i < n
    ensures v_new[i] == v[p[i]]
  {
    assert |p| == n;
    assert 0 <= i < |p|;
    assert 0 <= p[i] < n;
    assert n == |v|;
    assert 0 <= p[i] < |v|;
  }

  forall i, j | 0 <= i < j < |v_new|
    ensures v_new[i] <= v_new[j]
  {
    assert v_new[i] == v[p[i]];
    assert v_new[j] == v[p[j]];
    assert v[p[i]] <= v[p[j]];
  }
  assert is_sorted(v_new);

  assert forall i {:trigger p[i]} ::
    0 <= i < |v| ==> v_new[i] == v[p[i]];

  IndexWitness(v, v_new, p);
}
