  && (forall x, y :: 0 <= x < n && 0 <= y < n && C[x][y] > 0 ==> has_capacity(g, x, y, C[x][y]))
}

ghost predicate FInv(f: FlowMap, C: seq<seq<int>>) {
  forall u: int, v: int :: (u, v) in f ==>
    0 <= u < |C| && 0 <= v < |C[u]| && 0 <= f[(u, v)] <= C[u][v]
}

function FindCap(row: seq<(int, int)>, y: int): int
  decreases |row|
{
  if |row| == 0 then 0
  else if row[|row| - 1].0 == y then row[|row| - 1].1
  else FindCap(row[..|row| - 1], y)
}

lemma FindCapProps(row: seq<(int, int)>, y: int)
  requires forall i, j :: 0 <= i < |row| && 0 <= j < |row| && i != j ==> row[i].0 != row[j].0
  ensures forall i :: 0 <= i < |row| && row[i].0 == y ==> FindCap(row, y) == row[i].1
  ensures (forall i :: 0 <= i < |row| ==> row[i].0 != y) ==> FindCap(row, y) == 0
  decreases |row|
{
  if |row| > 0 {
    var pre := row[..|row| - 1];
    assert forall i :: 0 <= i < |pre| ==> pre[i] == row[i];
    FindCapProps(pre, y);
  }
}

method BuildCap(adj: seq<seq<(int, int)>>) returns (C: seq<seq<int>>)
  requires WF(adj)
  requires capacities_bounded(adj)
  ensures CapProps(adj, C, |adj|)
{
  var n := |adj|;
  C := seq(n, x requires 0 <= x < n => seq(n, y => FindCap(adj[x], y)));
  assert |C| == n;
  forall x | 0 <= x < n
    ensures |C[x]| == n && forall y :: 0 <= y < n ==> C[x][y] == FindCap(adj[x], y)
  {
  }
  forall x, y | 0 <= x < n && 0 <= y < n
    ensures C[x][y] >= 0 && (C[x][y] > 0 ==> has_capacity(adj, x, y, C[x][y]))
  {
    FindCapProps(adj[x], y);
    if exists i :: 0 <= i < |adj[x]| && adj[x][i].0 == y {
      var i :| 0 <= i < |adj[x]| && adj[x][i].0 == y;
      assert C[x][y] == adj[x][i].1;
      assert has_capacity(adj, x, y, adj[x][i].1);
    } else {
      assert C[x][y] == 0;
    }
  }
  forall x, y, c | has_capacity(adj, x, y, c)
    ensures 0 <= x < n && 0 <= y < n && C[x][y] == c
  {
    var i :| 0 <= x < |adj| && 0 <= i < |adj[x]| && adj[x][i].0 == y && adj[x][i].1 == c;
    FindCapProps(adj[x], y);
  }
}

function Get(f: FlowMap, u: int, v: int): int
  ensures Get(f, u, v) == get_flow(f, u, v)
{
  if (u, v) in f then f[(u, v)] else 0
}

function Res(C: seq<seq<int>>, f: FlowMap, u: int, v: int): int
  requires 0 <= u < |C| && 0 <= v < |C[u]|
{
  C[u][v] - Get(f, u, v) + Get(f, v, u)
}

lemma FInvBounds(g: seq<seq<(int, int)>>, C: seq<seq<int>>, n: int, f: FlowMap, x: int, y: int)
  requires CapProps(g, C, n) && FInv(f, C) && 0 <= x < n && 0 <= y < n
  ensures 0 <= get_flow(f, x, y) <= C[x][y]
{
}

lemma FInvUpdate(C: seq<seq<int>>, f: FlowMap, a: int, b: int, val: int)
  requires FInv(f, C)
  requires 0 <= a < |C| && 0 <= b < |C[a]| && 0 <= val <= C[a][b]
  ensures FInv(f[(a, b) := val], C)
{
  forall x, y | (x, y) in f[(a, b) := val]
    ensures 0 <= x < |C| && 0 <= y < |C[x]| && 0 <= f[(a, b) := val][(x, y)] <= C[x][y]
  {
    if (x, y) != (a, b) { assert (x, y) in f; }
  }
}

lemma FlowLeCap(g: seq<seq<(int, int)>>, C: seq<seq<int>>, n: int, f: FlowMap, x: int, y: int)
  requires CapProps(g, C, n)
  requires respects_capacity(g, f)
  requires forall a: int, b: int :: (a, b) in f ==> f[(a, b)] >= 0
  requires 0 <= x < n && 0 <= y < n
  ensures 0 <= get_flow(f, x, y) <= C[x][y]
{
  if (x, y) in f && f[(x, y)] > 0 {
    var c :| has_capacity(g, x, y, c) && f[(x, y)] <= c;
  }
}

ghost function CRow(C: seq<seq<int>>, x: int): int -> int {
  y => if 0 <= x < |C| && 0 <= y < |C[x]| then C[x][y] else 0
}

lemma NetBound(g: seq<seq<(int, int)>>, C: seq<seq<int>>, n: int, f: FlowMap, s: int)
  requires CapProps(g, C, n) && FInv(f, C) && 0 <= s < n
  ensures Net(f, n, s) <= Sum(n, CRow(C, s))
{
  forall y | 0 <= y < n ensures FRow(f, s)(y) <= CRow(C, s)(y) && FCol(f, s)(y) >= 0 {
    FInvBounds(g, C, n, f, s, y);
    FInvBounds(g, C, n, f, y, s);
  }
  SumLe(n, FRow(f, s), CRow(C, s));
  SumNonneg(n, FCol(f, s));
}

lemma NetEmpty(f: FlowMap, n: int)
  requires f == map[]
  ensures forall x :: Net(f, n, x) == 0
{
  forall x ensures Net(f, n, x) == 0 {
    SumZero(n, FRow(f, x));
    SumZero(n, FCol(f, x));
  }
}

lemma PushNet(f: FlowMap, nf: FlowMap, n: int, a: int, b: int, d: int)
  requires nf == f[(a, b) := get_flow(f, a, b) + d]
  ensures forall x :: 0 <= x < n ==>
    Net(nf, n, x) == Net(f, n, x) + (if x == a && 0 <= b < n then d else 0)
                                  - (if x == b && 0 <= a < n then d else 0)
{
  forall x | 0 <= x < n
    ensures Net(nf, n, x) == Net(f, n, x) + (if x == a && 0 <= b < n then d else 0)
                                         - (if x == b && 0 <= a < n then d else 0)
  {
    forall y | 0 <= y < n
      ensures FRow(nf, x)(y) == FRow(f, x)(y) + (if y == b then (if x == a then d else 0) else 0)
    {
    }
    SumBump(n, FRow(f, x), FRow(nf, x), b, if x == a then d else 0);
    forall y | 0 <= y < n
      ensures FCol(nf, x)(y) == FCol(f, x)(y) + (if y == a then (if x == b then d else 0) else 0)
    {
    }
    SumBump(n, FCol(f, x), FCol(nf, x), a, if x == b then d else 0);
  }
}

lemma MakeValid(g: seq<seq<(int, int)>>, C: seq<seq<int>>, n: int, f: FlowMap, s: int, t: int)
  requires WF(g) && CapProps(g, C, n) && FInv(f, C)
  requires 0 <= s < n && 0 <= t < n
  requires forall x :: 0 <= x < n && x != s && x != t ==> Net(f, n, x) == 0
  ensures is_valid_flow(g, f, s, t)
  ensures flow_val(g, f, s) == Net(f, n, s)
{
  assert respects_capacity(g, f) by {
    forall u, v | (u, v) in f
      ensures (f[(u, v)] > 0 ==> exists c :: has_capacity(g, u, v, c) && f[(u, v)] <= c)
    {
      if f[(u, v)] > 0 {
        assert C[u][v] >= f[(u, v)];
        assert has_capacity(g, u, v, C[u][v]);
      }
    }
  }
  OutEq(g, f, s);
  InEq(g, f, s, n);
  forall x | 0 <= x < n && x != s && x != t
    ensures total_flow_in(g, f, x) == total_flow_out(g, f, x)
  {
    OutEq(g, f, x);
    InEq(g, f, x, n);
  }
}

// ---------- Cuts ----------

ghost function G1(f: FlowMap, S: set<int>): (int, int) -> int {
  (x, y) => if x in S then get_flow(f, x, y) else 0
}

ghost function H1(f: FlowMap, S: set<int>): (int, int) -> int {
  (x, y) => if y in S then get_flow(f, x, y) else 0
}

ghost function KF(f: FlowMap, S: set<int>): (int, int) -> int {
  (x, y) => (if x in S then get_flow(f, x, y) else 0) - (if y in S then get_flow(f, x, y) else 0)
}

ghost function CapCut(C: seq<seq<int>>, S: set<int>): (int, int) -> int {
  (x, y) => if x in S && y !in S && 0 <= x < |C| && 0 <= y < |C[x]| then C[x][y] else 0
}

lemma NetIdentity(f: FlowMap, n: int, S: set<int>, s: int, t: int)
  requires 0 <= s < n && s in S && t !in S
  requires forall x :: 0 <= x < n && x != s && x != t ==> Net(f, n, x) == 0
  ensures Net(f, n, s) == Sum(n, RowSums(KF(f, S), n))
{
  var SN: int -> int := x => if x in S then Net(f, n, x) else 0;
  SumSingle(n, SN, s);
  var A: int -> int := x => if x in S then Sum(n, FRow(f, x)) else 0;
  var B: int -> int := x => if x in S then Sum(n, FCol(f, x)) else 0;
  SumSub(n, A, B, SN);
  forall x | 0 <= x < n ensures A(x) == RowSums(G1(f, S), n)(x) {
    assert RowSums(G1(f, S), n)(x) == Sum(n, Row(G1(f, S), x));
    if x in S {
      SumExt(n, FRow(f, x), Row(G1(f, S), x));
    } else {
      SumZero(n, Row(G1(f, S), x));
    }
  }
  SumExt(n, A, RowSums(G1(f, S), n));
  forall x | 0 <= x < n ensures B(x) == ColSums(H1(f, S), n)(x) {
    assert ColSums(H1(f, S), n)(x) == Sum(n, Col(H1(f, S), x));
    if x in S {
      SumExt(n, FCol(f, x), Col(H1(f, S), x));
    } else {
      SumZero(n, Col(H1(f, S), x));
    }
  }
  SumExt(n, B, ColSums(H1(f, S), n));
  Swap(n, n, H1(f, S));
  forall x | 0 <= x < n
    ensures RowSums(KF(f, S), n)(x) == RowSums(G1(f, S), n)(x) - RowSums(H1(f, S), n)(x)
  {
    SumSub(n, Row(G1(f, S), x), Row(H1(f, S), x), Row(KF(f, S), x));
  }
  SumSub(n, RowSums(G1(f, S), n), RowSums(H1(f, S), n), RowSums(KF(f, S), n));
}

lemma CutLe(g: seq<seq<(int, int)>>, C: seq<seq<int>>, n: int, f: FlowMap, S: set<int>, s: int, t: int)
  requires CapProps(g, C, n)
  requires is_valid_flow(g, f, s, t)
  ensures Sum(n, RowSums(KF(f, S), n)) <= Sum(n, RowSums(CapCut(C, S), n))
{
  forall x | 0 <= x < n ensures RowSums(KF(f, S), n)(x) <= RowSums(CapCut(C, S), n)(x) {
    forall y | 0 <= y < n ensures Row(KF(f, S), x)(y) <= Row(CapCut(C, S), x)(y) {
      FlowLeCap(g, C, n, f, x, y);
    }
    SumLe(n, Row(KF(f, S), x), Row(CapCut(C, S), x));
  }
  SumLe(n, RowSums(KF(f, S), n), RowSums(CapCut(C, S), n));
}

lemma CutEq(g: seq<seq<(int, int)>>, C: seq<seq<int>>, n: int, f: FlowMap, S: set<int>)
  requires CapProps(g, C, n) && FInv(f, C)
  requires forall x, y :: 0 <= x < n && 0 <= y < n && x in S && y !in S ==> Res(C, f, x, y) < 1
  ensures Sum(n, RowSums(KF(f, S), n)) == Sum(n, RowSums(CapCut(C, S), n))
{
  forall x | 0 <= x < n ensures RowSums(KF(f, S), n)(x) == RowSums(CapCut(C, S), n)(x) {
    forall y | 0 <= y < n ensures Row(KF(f, S), x)(y) == Row(CapCut(C, S), x)(y) {
      FInvBounds(g, C, n, f, x, y);
      FInvBounds(g, C, n, f, y, x);
      if x in S && y !in S {
        assert Res(C, f, x, y) < 1;
      } else if x !in S && y in S {
        assert Res(C, f, y, x) < 1;
      }
    }
    SumExt(n, Row(KF(f, S), x), Row(CapCut(C, S), x));
  }
  SumExt(n, RowSums(KF(f, S), n), RowSums(CapCut(C, S), n));
}

lemma FinalCut(g: seq<seq<(int, int)>>, C: seq<seq<int>>, n: int, f: FlowMap, s: int, t: int, reached: seq<bool>)
  requires WF(g) && CapProps(g, C, n) && FInv(f, C)
  requires 0 <= s < n && 0 <= t < n && s != t
  requires |reached| == n && reached[s] && !reached[t]
  requires forall x, w :: 0 <= x < n && 0 <= w < n && reached[x] && !reached[w] ==> Res(C, f, x, w) < 1
  requires forall x :: 0 <= x < n && x != s && x != t ==> Net(f, n, x) == 0
  ensures is_max_flow(g, f, s, t) && flow_val(g, f, s) == Net(f, n, s)
{
  var S := set x | 0 <= x < n && reached[x];
  assert s in S;
  assert t !in S;
  forall x, y | 0 <= x < n && 0 <= y < n && x in S && y !in S ensures Res(C, f, x, y) < 1 {
    assert reached[x] && !reached[y];
  }
  CutEq(g, C, n, f, S);
  NetIdentity(f, n, S, s, t);
  MakeValid(g, C, n, f, s, t);
  forall other: FlowMap | is_valid_flow(g, other, s, t)
    ensures flow_val(g, f, s) >= flow_val(g, other, s)
  {
    FlowValNet(g, other, s, t);
    NetIdentity(other, n, S, s, t);
    CutLe(g, C, n, other, S, s, t);
  }
}

// ---------- Search in the residual graph ----------

ghost function CountFalse(r: seq<bool>): int
  ensures 0 <= CountFalse(r) <= |r|
  decreases |r|
{
  if |r| == 0 then 0 else CountFalse(r[..|r| - 1]) + (if r[|r| - 1] then 0 else 1)
}

lemma CountFalseAll(r: seq<bool>)
  requires forall i :: 0 <= i < |r| ==> !r[i]
  ensures CountFalse(r) == |r|
  decreases |r|
{
  if |r| > 0 { CountFalseAll(r[..|r| - 1]); }
}

lemma CountFalseUpdate(r: seq<bool>, w: int)
  requires 0 <= w < |r| && !r[w]
  ensures CountFalse(r[w := true]) == CountFalse(r) - 1
  decreases |r|
{
  var r2 := r[w := true];
  if w == |r| - 1 {
    assert r2[..|r2| - 1] == r[..|r| - 1];
  } else {
    assert r2[..|r2| - 1] == r[..|r| - 1][w := true];
    CountFalseUpdate(r[..|r| - 1], w);
  }
}

method Search(C: seq<seq<int>>, f: FlowMap, n: int, s: int)
  returns (reached: seq<bool>, parent: seq<int>, order: seq<int>)
  requires n == |C| && (forall x :: 0 <= x < n ==> |C[x]| == n)
  requires 0 <= s < n
  ensures |reached| == n && |parent| == n && |order| == n
  ensures reached[s]
  ensures forall w :: 0 <= w < n && reached[w] ==> 0 <= order[w]
  ensures forall w :: 0 <= w < n && reached[w] && w != s ==>
            0 <= parent[w] < n && reached[parent[w]] && order[parent[w]] < order[w]
            && Res(C, f, parent[w], w) >= 1
  ensures forall x, w :: 0 <= x < n && 0 <= w < n && reached[x] && !reached[w] ==> Res(C, f, x, w) < 1
{
  reached := seq(n, j => false);
  CountFalseAll(reached);
  CountFalseUpdate(reached, s);
  reached := reached[s := true];
  parent := seq(n, j => 0);
  order := seq(n, j => 0);
  var q: seq<int> := [s];
  var i := 0;
  while i < |q|
    invariant |reached| == n && |parent| == n && |order| == n
    invariant 0 <= i <= |q| <= n
    invariant |q| + CountFalse(reached) == n
    invariant reached[s]
    invariant forall k :: 0 <= k < |q| ==> 0 <= q[k] < n && reached[q[k]] && order[q[k]] == k
    invariant forall w :: 0 <= w < n && reached[w] ==> 0 <= order[w] < |q| && q[order[w]] == w
    invariant forall w :: 0 <= w < n && reached[w] && w != s ==>
            0 <= parent[w] < n && reached[parent[w]] && order[parent[w]] < order[w]
            && Res(C, f, parent[w], w) >= 1
    invariant forall k, w :: 0 <= k < i && 0 <= w < n && 0 <= q[k] < n && Res(C, f, q[k], w) >= 1 ==> reached[w]
    decreases n - i
  {
    var u := q[i];
    var w := 0;
    while w < n
      invariant 0 <= w <= n
      invariant |reached| == n && |parent| == n && |order| == n
      invariant 0 <= i < |q| <= n
      invariant q[i] == u && 0 <= u < n
      invariant |q| + CountFalse(reached) == n
      invariant reached[s]
      invariant forall k :: 0 <= k < |q| ==> 0 <= q[k] < n && reached[q[k]] && order[q[k]] == k
      invariant forall w' :: 0 <= w' < n && reached[w'] ==> 0 <= order[w'] < |q| && q[order[w']] == w'
      invariant forall w' :: 0 <= w' < n && reached[w'] && w' != s ==>
            0 <= parent[w'] < n && reached[parent[w']] && order[parent[w']] < order[w']
            && Res(C, f, parent[w'], w') >= 1
      invariant forall k, w' :: 0 <= k < i && 0 <= w' < n && 0 <= q[k] < n && Res(C, f, q[k], w') >= 1 ==> reached[w']
      invariant forall w' :: 0 <= w' < w && Res(C, f, u, w') >= 1 ==> reached[w']
      decreases n - w
    {
      if !reached[w] && Res(C, f, u, w) >= 1 {
        CountFalseUpdate(reached, w);
        reached := reached[w := true];
        parent := parent[w := u];
        order := order[w := |q|];
        q := q + [w];
      }
      w := w + 1;
    }
    i := i + 1;
  }
  forall x, w | 0 <= x < n && 0 <= w < n && reached[x] && !reached[w]
    ensures Res(C, f, x, w) < 1
  {
    var k := order[x];
    assert q[k] == x;
    if Res(C, f, x, w) >= 1 {
      assert Res(C, f, q[k], w) >= 1;
      assert reached[w];
    }
  }
}

ghost predicate Touched(x: int, y: int, v: int, reached: seq<bool>, parent: seq<int>, order: seq<int>, n: int, s: int)
{
  |reached| == n && |parent| == n && |order| == n && 0 <= v < n &&
  exists w :: 0 <= w < n && reached[w] && w != s && order[w] > order[v] &&
              ((x == parent[w] && y == w) || (x == w && y == parent[w]))
}

// ---------- Main ----------

method max_flow_value(graph: CapacityGraph, s: int, t: int) returns (max_val: int)
    requires well_formed(graph)
    requires capacities_bounded(view(graph))
    requires 0 <= s < size(graph)
    requires 0 <= t < size(graph)
    requires s != t
    ensures exists f: FlowMap :: 
            is_max_flow(view(graph), f, s, t) 
            && flow_val(view(graph), f, s) == max_val
{
  var n := |graph.adj|;
  ghost var g := graph.adj;
  assert view(graph) == g;
  assert size(graph) == n;
  assert WF(g);
  var C := BuildCap(graph.adj);
  var f: FlowMap := map[];
  NetEmpty(f, n);
  var val := 0;
  ghost var Bound := Sum(n, CRow(C, s));
  NetBound(g, C, n, f, s);
  while true
    invariant CapProps(g, C, n)
    invariant FInv(f, C)
    invariant forall x :: 0 <= x < n && x != s && x != t ==> Net(f, n, x) == 0
    invariant val == Net(f, n, s)
    invariant val <= Bound
    decreases Bound - val
  {
    var reached, parent, order := Search(C, f, n, s);
    if !reached[t] {
      FinalCut(g, C, n, f, s, t, reached);
      max_val := val;
      assert is_max_flow(view(graph), f, s, t) && flow_val(view(graph), f, s) == max_val;
      return;
    }
    ghost var f0 := f;
    var v := t;
    while v != s
      invariant 0 <= v < n && reached[v]
      invariant FInv(f, C)
      invariant forall w :: 0 <= w < n && reached[w] ==> 0 <= order[w]
      invariant forall w :: 0 <= w < n && reached[w] && w != s ==>
            0 <= parent[w] < n && reached[parent[w]] && order[parent[w]] < order[w]
            && Res(C, f0, parent[w], w) >= 1
      invariant forall x :: 0 <= x < n ==>
            Net(f, n, x) == Net(f0, n, x) + (if x == v then 1 else 0) - (if x == t then 1 else 0)
      invariant forall x, y :: get_flow(f, x, y) != get_flow(f0, x, y) ==>
            Touched(x, y, v, reached, parent, order, n, s)
      decreases order[v]
    {
      var u := parent[v];
      assert 0 <= u < n && reached[u] && order[u] < order[v];
      assert get_flow(f, u, v) == get_flow(f0, u, v) by {
        if get_flow(f, u, v) != get_flow(f0, u, v) {
          assert Touched(u, v, v, reached, parent, order, n, s);
          var w :| 0 <= w < n && reached[w] && w != s && order[w] > order[v] &&
                   ((u == parent[w] && v == w) || (u == w && v == parent[w]));
          if u == parent[w] && v == w {
            assert order[w] == order[v];
          } else {
            assert w == u;
          }
        }
      }
      assert get_flow(f, v, u) == get_flow(f0, v, u) by {
        if get_flow(f, v, u) != get_flow(f0, v, u) {
          assert Touched(v, u, v, reached, parent, order, n, s);
          var w :| 0 <= w < n && reached[w] && w != s && order[w] > order[v] &&
                   ((v == parent[w] && u == w) || (v == w && u == parent[w]));
          if v == parent[w] && u == w {
            assert w == u;
          } else {
            assert order[w] == order[v];
          }
        }
      }
      assert Res(C, f, u, v) == Res(C, f0, u, v);
      assert Res(C, f, u, v) >= 1;
      FInvBounds(g, C, n, f, u, v);
      FInvBounds(g, C, n, f, v, u);
      var r := Get(f, v, u);
      var nf: FlowMap;
      if r > 0 {
        nf := f[(v, u) := r - 1];
        FInvUpdate(C, f, v, u, r - 1);
        PushNet(f, nf, n, v, u, -1);
      } else {
        nf := f[(u, v) := Get(f, u, v) + 1];
