    requires forall i: int :: 0 <= i < |prices| ==> 0 <= prices[i] <= 10000
    ensures result >= 0
    // 1. Upper Bound
    ensures forall cuts: seq<int> :: (is_valid_strategy(cuts, n, prices) 
            ==> calculate_revenue(cuts, prices) <= result)
    // 2. Existence
    ensures exists cuts: seq<int> :: (is_valid_strategy(cuts, n, prices) 
            && calculate_revenue(cuts, prices) == result)
{
    if n < 0 {
        // No valid strategy exists for negative n, so the existence
        // postcondition is unprovable here (see note above).
        result := 0;
        return;
    }
    var dp: seq<int> := [0];
    ghost var wit: seq<seq<int>> := [[]];
    var i := 1;
    while i <= n
        invariant 1 <= i <= n + 1
        invariant |dp| == i && |wit| == i
        invariant dp[0] == 0
        invariant forall j: int :: 0 <= j < i ==> dp[j] >= 0
        invariant forall j: int, k: int :: 0 <= j < i && 1 <= k <= j ==> prices[k - 1] + dp[j - k] <= dp[j]
        invariant forall j: int :: 0 <= j < i ==>
            is_valid_strategy(wit[j], j, prices) && calculate_revenue(wit[j], prices) == dp[j]
    {
        var best := prices[0] + dp[i - 1];
        ghost var bk := 1;
        var k := 2;
        while k <= i
            invariant 2 <= k <= i + 1
            invariant 1 <= bk < k
            invariant best == prices[bk - 1] + dp[i - bk]
            invariant best >= 0
            invariant forall kk: int :: 1 <= kk < k ==> prices[kk - 1] + dp[i - kk] <= best
        {
            var v := prices[k - 1] + dp[i - k];
            if v > best {
                best := v;
                bk := k;
            }
            k := k + 1;
        }
        Prepend(bk, wit[i - bk], i - bk, prices);
        dp := dp + [best];
        wit := wit + [[bk] + wit[i - bk]];
        i := i + 1;
    }
    result := dp[n];
    forall cuts: seq<int> | is_valid_strategy(cuts, n, prices)
        ensures calculate_revenue(cuts, prices) <= result
    {
        UpperBound(cuts, n, prices, dp);
    }
