ghost function CountFalse(r: seq<bool>): int
  ensures 0 <= CountFalse(r) <= |r|
  decreases |r|
{
  if |r| == 0 then 0 else CountFalse(r[..|r| - 1]) + (if r[|r| - 1] then 0 else 1)
}

lemma CountFalseAll(r: seq<bool>)
  requires forall i :: 0 <= i < |r| ==> !r[i]
  ensures CountFalse(r) == |r|
  decreases |r|
{
  if |r| > 0 { CountFalseAll(r[..|r| - 1]); }
}

lemma CountFalseUpdate(r: seq<bool>, w: int)
  requires 0 <= w < |r| && !r[w]
  ensures CountFalse(r[w := true]) == CountFalse(r) - 1
  decreases |r|
{
  var r2 := r[w := true];
  if w == |r| - 1 {
    assert r2[..|r2| - 1] == r[..|r| - 1];
  } else {
    assert r2[..|r2| - 1] == r[..|r| - 1][w := true];
    CountFalseUpdate(r[..|r| - 1], w);
  }
}

method Search(C: seq<seq<int>>, f: FlowMap, n: int, s: int)
  returns (reached: seq<bool>, parent: seq<int>, order: seq<int>)
  requires n == |C| && (forall x :: 0 <= x < n ==> |C[x]| == n)
  requires 0 <= s < n
  ensures |reached| == n && |parent| == n && |order| == n
  ensures reached[s]
  ensures forall w :: 0 <= w < n && reached[w] ==> 0 <= order[w]
  ensures forall w :: 0 <= w < n && reached[w] && w != s ==>
            0 <= parent[w] < n && reached[parent[w]] && order[parent[w]] < order[w]
            && Res(C, f, parent[w], w) >= 1
  ensures forall x, w :: 0 <= x < n && 0 <= w < n && reached[x] && !reached[w] ==> Res(C, f, x, w) < 1
{
  reached := seq(n, j => false);
  CountFalseAll(reached);
  CountFalseUpdate(reached, s);
  reached := reached[s := true];
  parent := seq(n, j => 0);
  order := seq(n, j => 0);
  var q: seq<int> := [s];
  var i := 0;
  while i < |q|
    invariant |reached| == n && |parent| == n && |order| == n
    invariant 0 <= i <= |q| <= n
    invariant |q| + CountFalse(reached) == n
    invariant reached[s]
    invariant forall k :: 0 <= k < |q| ==> 0 <= q[k] < n && reached[q[k]] && order[q[k]] == k
    invariant forall w :: 0 <= w < n && reached[w] ==> 0 <= order[w] < |q| && q[order[w]] == w
    invariant forall w :: 0 <= w < n && reached[w] && w != s ==>
            0 <= parent[w] < n && reached[parent[w]] && order[parent[w]] < order[w]
            && Res(C, f, parent[w], w) >= 1
    invariant forall k, w :: 0 <= k < i && 0 <= w < n && 0 <= q[k] < n && Res(C, f, q[k], w) >= 1 ==> reached[w]
    decreases n - i
  {
    var u := q[i];
    var w := 0;
    while w < n
      invariant 0 <= w <= n
      invariant |reached| == n && |parent| == n && |order| == n
      invariant 0 <= i < |q| <= n
      invariant q[i] == u && 0 <= u < n
      invariant |q| + CountFalse(reached) == n
      invariant reached[s]
      invariant forall k :: 0 <= k < |q| ==> 0 <= q[k] < n && reached[q[k]] && order[q[k]] == k
      invariant forall w' :: 0 <= w' < n && reached[w'] ==> 0 <= order[w'] < |q| && q[order[w']] == w'
      invariant forall w' :: 0 <= w' < n && reached[w'] && w' != s ==>
            0 <= parent[w'] < n && reached[parent[w']] && order[parent[w']] < order[w']
            && Res(C, f, parent[w'], w') >= 1
      invariant forall k, w' :: 0 <= k < i && 0 <= w' < n && 0 <= q[k] < n && Res(C, f, q[k], w') >= 1 ==> reached[w']
      invariant forall w' :: 0 <= w' < w && Res(C, f, u, w') >= 1 ==> reached[w']
      decreases n - w
    {
      if !reached[w] && Res(C, f, u, w) >= 1 {
        CountFalseUpdate(reached, w);
        reached := reached[w := true];
        parent := parent[w := u];
        order := order[w := |q|];
        q := q + [w];
      }
      w := w + 1;
    }
    i := i + 1;
  }
  forall x, w | 0 <= x < n && 0 <= w < n && reached[x] && !reached[w]
    ensures Res(C, f, x, w) < 1
  {
    var k := order[x];
    assert q[k] == x;
    if Res(C, f, x, w) >= 1 {
      assert Res(C, f, q[k], w) >= 1;
      assert reached[w];
    }
  }
}

ghost predicate Touched(x: int, y: int, v: int, reached: seq<bool>, parent: seq<int>, order: seq<int>, n: int, s: int)
{
  |reached| == n && |parent| == n && |order| == n && 0 <= v < n &&
  exists w :: 0 <= w < n && reached[w] && w != s && order[w] > order[v] &&
              ((x == parent[w] && y == w) || (x == w && y == parent[w]))
}

