method max_flow_value(graph: CapacityGraph, s: int, t: int) returns (max_val: int)
    requires well_formed(graph)
    requires capacities_bounded(view(graph))
    requires 0 <= s < size(graph)
    requires 0 <= t < size(graph)
    requires s != t
    ensures exists f: FlowMap :: 
            is_max_flow(view(graph), f, s, t) 
            && flow_val(view(graph), f, s) == max_val
{
  var n := |graph.adj|;
  ghost var g := graph.adj;
  assert view(graph) == g;
  assert size(graph) == n;
  assert WF(g);
  var C := BuildCap(graph.adj);
  var f: FlowMap := map[];
  NetEmpty(f, n);
  var val := 0;
  ghost var Bound := Sum(n, CRow(C, s));
  NetBound(g, C, n, f, s);
  while true
    invariant CapProps(g, C, n)
    invariant FInv(f, C)
    invariant forall x :: 0 <= x < n && x != s && x != t ==> Net(f, n, x) == 0
    invariant val == Net(f, n, s)
    invariant val <= Bound
    decreases Bound - val
  {
    var reached, parent, order := Search(C, f, n, s);
    if !reached[t] {
      FinalCut(g, C, n, f, s, t, reached);
      max_val := val;
      assert is_max_flow(view(graph), f, s, t) && flow_val(view(graph), f, s) == max_val;
      return;
    }
    ghost var f0 := f;
    var v := t;
    while v != s
      invariant 0 <= v < n && reached[v]
      invariant FInv(f, C)
      invariant forall w :: 0 <= w < n && reached[w] ==> 0 <= order[w]
      invariant forall w :: 0 <= w < n && reached[w] && w != s ==>
            0 <= parent[w] < n && reached[parent[w]] && order[parent[w]] < order[w]
            && Res(C, f0, parent[w], w) >= 1
      invariant forall x :: 0 <= x < n ==>
            Net(f, n, x) == Net(f0, n, x) + (if x == v then 1 else 0) - (if x == t then 1 else 0)
      invariant forall x, y :: get_flow(f, x, y) != get_flow(f0, x, y) ==>
            Touched(x, y, v, reached, parent, order, n, s)
      decreases order[v]
    {
      var u := parent[v];
      assert 0 <= u < n && reached[u] && order[u] < order[v];
      assert get_flow(f, u, v) == get_flow(f0, u, v) by {
        if get_flow(f, u, v) != get_flow(f0, u, v) {
          assert Touched(u, v, v, reached, parent, order, n, s);
          var w :| 0 <= w < n && reached[w] && w != s && order[w] > order[v] &&
                   ((u == parent[w] && v == w) || (u == w && v == parent[w]));
          if u == parent[w] && v == w {
            assert order[w] == order[v];
          } else {
            assert w == u;
          }
        }
      }
      assert get_flow(f, v, u) == get_flow(f0, v, u) by {
        if get_flow(f, v, u) != get_flow(f0, v, u) {
          assert Touched(v, u, v, reached, parent, order, n, s);
          var w :| 0 <= w < n && reached[w] && w != s && order[w] > order[v] &&
                   ((v == parent[w] && u == w) || (v == w && u == parent[w]));
          if v == parent[w] && u == w {
            assert w == u;
          } else {
            assert order[w] == order[v];
          }
        }
      }
      assert Res(C, f, u, v) == Res(C, f0, u, v);
      assert Res(C, f, u, v) >= 1;
      FInvBounds(g, C, n, f, u, v);
      FInvBounds(g, C, n, f, v, u);
      var r := Get(f, v, u);
      var nf: FlowMap;
      if r > 0 {
        nf := f[(v, u) := r - 1];
        FInvUpdate(C, f, v, u, r - 1);
        PushNet(f, nf, n, v, u, -1);
      } else {
        nf := f[(u, v) := Get(f, u, v) + 1];
        FInvUpdate(C, f, u, v, Get(f, u, v) + 1);
        PushNet(f, nf, n, u, v, 1);
      }
      forall x | 0 <= x < n
        ensures Net(nf, n, x) == Net(f0, n, x) + (if x == u then 1 else 0) - (if x == t then 1 else 0)
      {
      }
      forall x, y | get_flow(nf, x, y) != get_flow(f0, x, y)
        ensures Touched(x, y, u, reached, parent, order, n, s)
      {
        if (x == u && y == v) || (x == v && y == u) {
          assert 0 <= v < n && reached[v] && v != s && order[v] > order[u] &&
                 ((x == parent[v] && y == v) || (x == v && y == parent[v]));
        } else {
          assert get_flow(nf, x, y) == get_flow(f, x, y);
          assert Touched(x, y, v, reached, parent, order, n, s);
          var w :| 0 <= w < n && reached[w] && w != s && order[w] > order[v] &&
                   ((x == parent[w] && y == w) || (x == w && y == parent[w]));
          assert order[w] > order[u];
        }
      }
      f := nf;
      v := u;
    }
    val := val + 1;
    NetBound(g, C, n, f, s);
  }
}
