    g: seq<seq<(int, int)>>,
    u: int,
    idx: int)
    requires idx >= 0
    ensures sum_flow_out_recursive(g, map[], u, idx) == 0
    decreases idx
{
    if idx > 0 {
        empty_sum_flow_out_local(g, u, idx - 1);
    }
}

lemma empty_sum_flow_in_local(
    g: seq<seq<(int, int)>>,
    u: int,
    idx: int)
    requires idx >= 0
    ensures sum_flow_in_recursive(g, map[], u, idx) == 0
    decreases idx
{
