}

lemma empty_flow_is_valid_local(
    g: seq<seq<(int, int)>>,
    s: int,
    t: int)
    requires 0 <= s < |g|
    ensures is_valid_flow(g, map[], s, t)
    ensures flow_val(g, map[], s) == 0
{
    var empty: FlowMap := map[];

    assert respects_capacity(g, empty);

    forall u: int
        | 0 <= u < |g| && u != s && u != t
        ensures total_flow_in(g, empty, u) ==
                total_flow_out(g, empty, u)
    {
        empty_sum_flow_in_local(g, u, |g|);
        empty_sum_flow_out_local(g, u, |g[u]|);
