    assert is_conserved(g, empty, s, t);
    assert forall u: int, v: int ::
        (u, v) in empty ==> empty[(u, v)] >= 0;
    assert is_valid_flow(g, empty, s, t);

    empty_sum_flow_in_local(g, s, |g|);
    empty_sum_flow_out_local(g, s, |g[s]|);
