lemma get_flow_nonnegative_local(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int,
    u: int,
    v: int)
    requires is_valid_flow(g, f, s, t)
    ensures get_flow(f, u, v) >= 0
{
    if (u, v) in f {
        assert f[(u, v)] >= 0;
    }
}

lemma get_flow_bounded_local(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int,
    u: int,
    v: int)
    requires capacities_bounded(g)
    requires is_valid_flow(g, f, s, t)
    ensures 0 <= get_flow(f, u, v) <= 100_000
{
    get_flow_nonnegative_local(g, f, s, t, u, v);

    if (u, v) in f && f[(u, v)] > 0 {
        assert respects_capacity(g, f);
        var c: int :|
            has_capacity(g, u, v, c) &&
            f[(u, v)] <= c;
        assert 0 <= c <= 100_000;
    } else if (u, v) in f {
        assert f[(u, v)] == 0;
    }
}

