    var dp: seq<int> := [0];
    ghost var wit: seq<seq<int>> := [[]];
    var i := 1;
    while i <= n
        invariant 1 <= i <= n + 1
        invariant |dp| == i && |wit| == i
        invariant dp[0] == 0
        invariant forall j: int :: 0 <= j < i ==> dp[j] >= 0
        invariant forall j: int, k: int :: 0 <= j < i && 1 <= k <= j ==> prices[k - 1] + dp[j - k] <= dp[j]
