        invariant forall j: int :: 0 <= j < i ==>
            is_valid_strategy(wit[j], j, prices) && calculate_revenue(wit[j], prices) == dp[j]
    {
        var best := prices[0] + dp[i - 1];
        ghost var bk := 1;
        var k := 2;
        assert prices[i - (i - 1) - 1] + dp[i - 1] <= best;
        while k <= i
            invariant 2 <= k <= i + 1
            invariant 1 <= bk < k
            invariant best == prices[bk - 1] + dp[i - bk]
            invariant best >= 0
            invariant forall m: int {:trigger dp[m]} :: i - k < m < i ==> prices[i - m - 1] + dp[m] <= best
        {
            var v := prices[k - 1] + dp[i - k];
            assert prices[i - (i - k) - 1] + dp[i - k] == v;
            if v > best {
                best := v;
                bk := k;
            }
            k := k + 1;
        }
        Prepend(bk, wit[i - bk], i - bk, prices);
        var ndp := dp + [best];
        forall j: int, m: int | 0 <= m < j < |ndp| && j - m - 1 < |prices|
            ensures prices[j - m - 1] + ndp[m] <= ndp[j]
        {
            assert ndp[m] == dp[m];
            if j < i {
                assert ndp[j] == dp[j];
                assert prices[j - m - 1] + dp[m] <= dp[j];
            } else {
                assert ndp[j] == best;
                assert prices[i - m - 1] + dp[m] <= best;
            }
        }
        assert DPOk(ndp, prices);
        dp := ndp;
        wit := wit + [[bk] + wit[i - bk]];
        i := i + 1;
    }
    result := dp[n];
    forall cuts: seq<int> | is_valid_strategy(cuts, n, prices)
        ensures calculate_revenue(cuts, prices) <= result
    {
        UpperBound(cuts, n, prices, dp);
    }
    assert is_valid_strategy(wit[n], n, prices) && calculate_revenue(wit[n], prices) == result;
}
