lemma mf_vectors_characterization(k: nat, q: seq<int>)
    ensures q in mf_vectors(k) <==>
        |q| == k &&
        (forall i: int :: 0 <= i < |q| ==> 0 <= q[i] <= 100000)
    decreases k
{
    if k == 0 {
    } else {
        mf_vectors_characterization(k - 1, q[..|q| - 1])
            if |q| == k;
        if q in mf_vectors(k) {
            var r: seq<int>, x: int :|
                r in mf_vectors(k - 1) &&
                0 <= x <= 100000 &&
                q == r + [x];
            mf_vectors_characterization(k - 1, r);
        } else if
            |q| == k &&
            (forall i: int :: 0 <= i < |q| ==> 0 <= q[i] <= 100000)
        {
            var r := q[..k - 1];
