lemma mf_canonical_bounded(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    n: nat,
    s: int,
    t: int)
    requires n == |g|
    requires n > 0
    requires well_formed(CapacityGraph(g))
    requires capacities_bounded(g)
    requires is_valid_flow(g, f, s, t)
    ensures mf_canonical(f, n) in mf_vectors(n * n)
{
    var q := mf_canonical(f, n);

    forall k: int |
        0 <= k < |q|
        ensures 0 <= q[k] <= 100000
    {
        var u := k / n;
        var v := k % n;
        assert 0 <= u < n;
        assert 0 <= v < n;

        if (u, v) in f {
            assert q[k] == f[(u, v)];
            if f[(u, v)] > 0 {
                var c: int :|
                    has_capacity(g, u, v, c) &&
                    f[(u, v)] <= c;
                assert 0 <= c <= 100000;
            }
        } else {
            assert q[k] == 0;
        }
    }

    assert |q| == n * n;
    mf_vectors_characterization(n * n, q);
}

