    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int)
    requires mf_valid(g, f, s, t)
    ensures is_valid_flow(g, f, s, t)
{
    forall u: int, v: int |
        (u, v) in f
        ensures f[(u, v)] >= 0
        ensures f[(u, v)] > 0 ==>
            exists c: int ::
                has_capacity(g, u, v, c) && f[(u, v)] <= c
    {
        assert (u, v) in f.Keys;
        if f[(u, v)] > 0 {
            assert mf_edge_allows(g, u, v, f[(u, v)]);
            var i: int :|
                0 <= i < |g[u]| &&
                g[u][i].0 == v &&
                f[(u, v)] <= g[u][i].1;
            assert has_capacity(g, u, v, g[u][i].1);
        }
    }

    forall u: int |
        0 <= u < |g| && u != s && u != t
        ensures total_flow_in(g, f, u) == total_flow_out(g, f, u)
    {
        mf_totals_agree(g, f, u);
    }
}

lemma mf_valid_complete(
    g: seq<seq<(int, int)>>,
    f: FlowMap,
    s: int,
    t: int)
    requires is_valid_flow(g, f, s, t)
    ensures mf_valid(g, f, s, t)
{
    forall p: (int, int) |
        p in f.Keys
        ensures f[p] >= 0 &&
            (f[p] > 0 ==> mf_edge_allows(g, p.0, p.1, f[p]))
    {
        assert p in f;
        if f[p] > 0 {
            var c: int :|
                has_capacity(g, p.0, p.1, c) && f[p] <= c;
            var i: int :|
                0 <= p.0 < |g| &&
                0 <= i < |g[p.0]| &&
                g[p.0][i].0 == p.1 &&
                g[p.0][i].1 == c;
            assert mf_edge_allows(g, p.0, p.1, f[p]);
        }
    }

    forall u: int |
        0 <= u < |g| && u != s && u != t
        ensures mf_in(g, f, u) == mf_out(g, f, u)
    {
        mf_totals_agree(g, f, u);
    }
}

