method max_flow_value(graph: CapacityGraph, s: int, t: int) returns (max_val: int)
    requires well_formed(graph)
    requires capacities_bounded(view(graph))
    requires 0 <= s < size(graph)
    requires 0 <= t < size(graph)
    requires s != t
    ensures exists f: FlowMap ::
            is_max_flow(view(graph), f, s, t)
            && flow_val(view(graph), f, s) == max_val
{
    var g := graph.adj;
    var n: nat := |g|;
    assert n > 0;

    var remaining := mf_vectors(n * n);
    var best: FlowMap := map[];
    var bestVal := 0;

    mf_empty_valid(g, s, t);
    mf_value_agrees(g, best, s);

    while remaining != {}
        invariant remaining <= mf_vectors(n * n)
        invariant mf_valid(g, best, s, t)
        invariant bestVal == mf_value(g, best, s)
        invariant forall q: seq<int> ::
            q in mf_vectors(n * n) - remaining &&
            mf_valid(g, mf_matrix(n, q), s, t)
            ==> mf_value(g, mf_matrix(n, q), s) <= bestVal
        decreases |remaining|
    {
        var oldRemaining := remaining;
        var q: seq<int> :| q in remaining;
        remaining := remaining - {q};

        var candidate := mf_matrix(n, q);
        if mf_valid(g, candidate, s, t) {
            var candidateVal := mf_value(g, candidate, s);
            if candidateVal > bestVal {
                best := candidate;
                bestVal := candidateVal;
            }
        }

        forall r: seq<int> |
            r in mf_vectors(n * n) - remaining &&
            mf_valid(g, mf_matrix(n, r), s, t)
            ensures mf_value(g, mf_matrix(n, r), s) <= bestVal
        {
            if r != q {
                assert r in mf_vectors(n * n) - oldRemaining;
            }
        }
    }

    max_val := bestVal;
    mf_valid_sound(g, best, s, t);
    mf_value_agrees(g, best, s);

    forall other: FlowMap |
        is_valid_flow(g, other, s, t)
        ensures flow_val(g, best, s) >= flow_val(g, other, s)
    {
        var q := mf_canonical(other, n);
        var canonical := mf_matrix(n, q);

        mf_canonical_bounded(g, other, n, s, t);
        mf_canonical_equivalent(g, other, n, s, t);
        mf_valid_complete(g, canonical, s, t);
        mf_value_agrees(g, canonical, s);

        assert q in mf_vectors(n * n);
        assert q in mf_vectors(n * n) - remaining;
        assert mf_value(g, canonical, s) <= bestVal;
        assert flow_val(g, other, s) == flow_val(g, canonical, s);
    }

    assert is_max_flow(g, best, s, t);
    assert flow_val(g, best, s) == max_val;
}
