ghost predicate WF(g: seq<seq<int>>) {
    forall u: int, i: int :: 0 <= u < |g| && 0 <= i < |g[u]| ==> 0 <= g[u][i] < |g|
}

ghost predicate Mutual(g: seq<seq<int>>, a: int, b: int) {
    has_path(g, a, b) && has_path(g, b, a)
}

ghost predicate InRoots(g: seq<seq<int>>, roots: seq<int>, v: int) {
    exists k: int :: 0 <= k < |roots| && Mutual(g, roots[k], v)
}

ghost predicate Closed(g: seq<seq<int>>, vis: seq<bool>)
    requires |vis| == |g|
{
    forall x: int, i: int :: 0 <= x < |g| && vis[x] && 0 <= i < |g[x]| ==> 0 <= g[x][i] < |g| && vis[g[x][i]]
}

lemma PathRefl(g: seq<seq<int>>, u: int)
    ensures has_path(g, u, u)
{
    var p := [u];
    assert path_valid(g, p);
}

lemma EdgePath(g: seq<seq<int>>, u: int, v: int)
    requires has_edge(g, u, v)
    ensures has_path(g, u, v)
{
    var p := [u, v];
    assert path_valid(g, p) by {
        forall k | 0 <= k < |p| - 1 ensures has_edge(g, p[k], p[k+1]) {
            assert k == 0;
            assert p[0] == u && p[1] == v;
        }
    }
}

lemma PathTrans(g: seq<seq<int>>, a: int, b: int, c: int)
    requires has_path(g, a, b) && has_path(g, b, c)
    ensures has_path(g, a, c)
{
    var p :| |p| > 0 && p[0] == a && p[|p| - 1] == b && path_valid(g, p);
    var q :| |q| > 0 && q[0] == b && q[|q| - 1] == c && path_valid(g, q);
    var r := p + q[1..];
    assert path_valid(g, r) by {
        forall k | 0 <= k < |r| - 1 ensures has_edge(g, r[k], r[k+1]) {
            if k < |p| - 1 {
                assert r[k] == p[k] && r[k+1] == p[k+1];
                assert has_edge(g, p[k], p[k+1]);
            } else {
                var j := k - (|p| - 1);
                if k == |p| - 1 {
                    assert r[k] == p[|p| - 1];
                }
                assert r[k] == q[j];
                assert r[k+1] == q[j+1];
                assert has_edge(g, q[j], q[j+1]);
            }
        }
    }
    assert r[0] == a;
    if |q| == 1 {
        assert r == p;
    } else {
        assert r[|r| - 1] == q[|q| - 1];
    }
}

lemma SetRemove(A: set<int>, w: int)
    requires w in A
    ensures |A - {w}| == |A| - 1
{
    var B := A - {w};
    assert A * {w} == {w};
    assert A == B + {w};
    assert w !in B;
}

lemma PathClosed(g: seq<seq<int>>, vis: seq<bool>, p: seq<int>)
    requires |vis| == |g|
    requires Closed(g, vis)
    requires |p| > 0 && 0 <= p[0] < |g| && vis[p[0]]
    requires path_valid(g, p)
    ensures 0 <= p[|p| - 1] < |g| && vis[p[|p| - 1]]
    decreases |p|
{
    if |p| > 1 {
        var q := p[..|p| - 1];
        assert path_valid(g, q) by {
            forall k | 0 <= k < |q| - 1 ensures has_edge(g, q[k], q[k+1]) {
                assert q[k] == p[k] && q[k+1] == p[k+1];
                assert has_edge(g, p[k], p[k+1]);
            }
        }
        PathClosed(g, vis, q);
        var k := |p| - 2;
        var x := p[k];
        assert q[|q| - 1] == x;
        assert has_edge(g, p[k], p[k+1]);
        assert p[k+1] == p[|p| - 1];
        var i :| 0 <= x < |g| && 0 <= i < |g[x]| && g[x][i] == p[|p| - 1];
    }
}

lemma ClosedReach(g: seq<seq<int>>, vis: seq<bool>, s: int, t: int)
    requires |vis| == |g|
    requires Closed(g, vis)
    requires 0 <= s < |g| && vis[s]
    requires has_path(g, s, t)
    ensures 0 <= t < |g| && vis[t]
{
    var p :| |p| > 0 && p[0] == s && p[|p| - 1] == t && path_valid(g, p);
    PathClosed(g, vis, p);
}

lemma ContainsAppend(s: seq<int>, v: int)
    ensures forall x :: seq_contains(s + [v], x) <==> (seq_contains(s, x) || x == v)
{
    forall x ensures seq_contains(s + [v], x) <==> (seq_contains(s, x) || x == v) {
        if seq_contains(s, x) {
            var i :| 0 <= i < |s| && s[i] == x;
            assert (s + [v])[i] == x;
        }
        if x == v {
            assert (s + [v])[|s|] == v;
        }
        if seq_contains(s + [v], x) {
            var i :| 0 <= i < |s + [v]| && (s + [v])[i] == x;
            if i < |s| {
                assert s[i] == x;
            }
        }
    }
}

lemma InRootsAppend(g: seq<seq<int>>, roots: seq<int>, u: int)
    ensures forall v :: InRoots(g, roots + [u], v) <==> (InRoots(g, roots, v) || Mutual(g, u, v))
{
    forall v ensures InRoots(g, roots + [u], v) <==> (InRoots(g, roots, v) || Mutual(g, u, v)) {
        var r := roots + [u];
        if InRoots(g, roots, v) {
            var k :| 0 <= k < |roots| && Mutual(g, roots[k], v);
            assert r[k] == roots[k];
            assert Mutual(g, r[k], v);
        }
        if Mutual(g, u, v) {
            assert r[|roots|] == u;
            assert Mutual(g, r[|roots|], v);
        }
        if InRoots(g, r, v) {
            var k :| 0 <= k < |r| && Mutual(g, r[k], v);
            if k < |roots| {
                assert r[k] == roots[k];
            }
        }
    }
}

method Reach(g: seq<seq<int>>, s: int) returns (vis: seq<bool>)
    requires WF(g)
    requires 0 <= s < |g|
    ensures |vis| == |g|
    ensures forall t :: 0 <= t < |g| ==> (vis[t] <==> has_path(g, s, t))
{
    var n := |g|;
    var visited := new bool[n](_ => false);
    visited[s] := true;
    var stack: seq<int> := [s];
    ghost var unvisited: set<int> := set v | 0 <= v < n && v != s;
    PathRefl(g, s);
    while |stack| > 0
        invariant visited.Length == n
        invariant visited[s]
        invariant forall v :: v in unvisited <==> (0 <= v < n && !visited[v])
        invariant forall x :: x in stack ==> 0 <= x < n && visited[x]
        invariant forall v :: 0 <= v < n && visited[v] ==> has_path(g, s, v)
        invariant forall x :: 0 <= x < n && visited[x] && x !in stack ==>
                    (forall i :: 0 <= i < |g[x]| ==> visited[g[x][i]])
        decreases |unvisited|, |stack|
    {
        ghost var oldStack := stack;
        var v := stack[|stack| - 1];
        stack := stack[..|stack| - 1];
        assert oldStack == stack + [v];
        ghost var u0 := |unvisited|;
        ghost var s0 := |stack|;
        var i := 0;
        while i < |g[v]|
            invariant visited.Length == n
            invariant 0 <= i <= |g[v]|
            invariant 0 <= v < n && visited[v]
            invariant visited[s]
            invariant forall v' :: v' in unvisited <==> (0 <= v' < n && !visited[v'])
            invariant forall x :: x in stack ==> 0 <= x < n && visited[x]
            invariant forall v' :: 0 <= v' < n && visited[v'] ==> has_path(g, s, v')
            invariant forall x :: 0 <= x < n && visited[x] && x !in stack && x != v ==>
                        (forall j :: 0 <= j < |g[x]| ==> visited[g[x][j]])
            invariant forall j :: 0 <= j < i ==> visited[g[v][j]]
            invariant |unvisited| <= u0
            invariant |unvisited| == u0 ==> |stack| == s0
        {
            var w := g[v][i];
            if !visited[w] {
                assert 0 <= v < |g| && g[v][i] == w;
                assert has_edge(g, v, w);
                EdgePath(g, v, w);
                PathTrans(g, s, v, w);
                SetRemove(unvisited, w);
                unvisited := unvisited - {w};
                visited[w] := true;
                stack := stack + [w];
            }
            i := i + 1;
        }
    }
    vis := visited[..];
    assert Closed(g, vis) by {
        forall x, i | 0 <= x < |g| && vis[x] && 0 <= i < |g[x]|
            ensures 0 <= g[x][i] < |g| && vis[g[x][i]]
        {
            assert visited[x];
            assert x !in stack;
        }
    }
    forall t | 0 <= t < n && has_path(g, s, t) ensures vis[t] {
        ClosedReach(g, vis, s, t);
    }
}

lemma FinalProof(g: seq<seq<int>>, sccs: seq<seq<int>>, roots: seq<int>)
    requires |sccs| == |roots|
    requires forall k :: 0 <= k < |roots| ==> 0 <= roots[k] < |g|
    requires forall k, x :: 0 <= k < |roots| ==> (seq_contains(sccs[k], x) <==> (0 <= x < |g| && Mutual(g, roots[k], x)))
    requires forall v :: 0 <= v < |g| ==> InRoots(g, roots, v)
    requires forall k1, k2 :: 0 <= k1 < |roots| && 0 <= k2 < |roots| && k1 != k2 ==> !Mutual(g, roots[k1], roots[k2])
    ensures is_valid_scc_result(g, sccs)
{
    forall i, j, x | 0 <= i < |sccs| && 0 <= j < |sccs| && i != j
        ensures !(seq_contains(sccs[i], x) && seq_contains(sccs[j], x))
    {
        if seq_contains(sccs[i], x) && seq_contains(sccs[j], x) {
            PathTrans(g, roots[i], x, roots[j]);
            PathTrans(g, roots[j], x, roots[i]);
            assert Mutual(g, roots[i], roots[j]);
        }
    }
    assert are_disjoint(sccs);
    forall v | 0 <= v < |g| ensures is_covered(sccs, v) {
        var k :| 0 <= k < |roots| && Mutual(g, roots[k], v);
        assert seq_contains(sccs[k], v);
    }
    assert is_partition(g, sccs);
    forall k | 0 <= k < |sccs| ensures is_strongly_connected(g, sccs[k]) {
        PathRefl(g, roots[k]);
        assert seq_contains(sccs[k], roots[k]);
        forall i | 0 <= i < |sccs[k]| ensures 0 <= sccs[k][i] < |g| {
            assert seq_contains(sccs[k], sccs[k][i]);
        }
        forall a, b | seq_contains(sccs[k], a) && seq_contains(sccs[k], b)
            ensures has_path(g, a, b) && has_path(g, b, a)
        {
            PathTrans(g, a, roots[k], b);
            PathTrans(g, b, roots[k], a);
        }
    }
    forall i, j | 0 <= i < |sccs| && 0 <= j < |sccs| && i != j
        ensures scc_has_path(g, sccs, i, j) ==> !scc_has_path(g, sccs, j, i)
    {
        if scc_has_path(g, sccs, i, j) && scc_has_path(g, sccs, j, i) {
            var a, b :| seq_contains(sccs[i], a) && seq_contains(sccs[j], b) && has_path(g, a, b);
            var c, d :| seq_contains(sccs[j], c) && seq_contains(sccs[i], d) && has_path(g, c, d);
            var ri, rj := roots[i], roots[j];
            PathTrans(g, ri, a, b);
            PathTrans(g, ri, b, rj);
            PathTrans(g, rj, c, d);
            PathTrans(g, rj, d, ri);
            assert Mutual(g, ri, rj);
            assert false;
        }
    }
}

method find_sccs(graph: Graph) returns (sccs: seq<seq<int>>)
    requires well_formed(graph)
    requires size_bounded(view(graph))
    ensures is_valid_scc_result(view(graph), sccs)
{
    var g := graph.adj;
    var n := |g|;
    assert WF(g);
    var R: seq<seq<bool>> := [];
    var u := 0;
    while u < n
        invariant 0 <= u <= n
        invariant |R| == u
        invariant forall a :: 0 <= a < u ==> |R[a]| == n
        invariant forall a, b :: 0 <= a < u && 0 <= b < n ==> (R[a][b] <==> has_path(g, a, b))
    {
        var row := Reach(g, u);
        R := R + [row];
        u := u + 1;
    }
    var assigned := new bool[n](_ => false);
    sccs := [];
    ghost var roots: seq<int> := [];
    u := 0;
    while u < n
        invariant 0 <= u <= n
        invariant assigned.Length == n
        invariant |sccs| == |roots|
        invariant forall k :: 0 <= k < |roots| ==> 0 <= roots[k] < n
        invariant forall k, x :: 0 <= k < |roots| ==> (seq_contains(sccs[k], x) <==> (0 <= x < n && Mutual(g, roots[k], x)))
        invariant forall v :: 0 <= v < n ==> (assigned[v] <==> InRoots(g, roots, v))
        invariant forall w :: 0 <= w < u ==> assigned[w]
        invariant forall k1, k2 :: 0 <= k1 < |roots| && 0 <= k2 < |roots| && k1 != k2 ==> !Mutual(g, roots[k1], roots[k2])
    {
        if !assigned[u] {
            assert !InRoots(g, roots, u);
            forall k | 0 <= k < |roots|
                ensures !Mutual(g, u, roots[k]) && !Mutual(g, roots[k], u)
            {
                if Mutual(g, roots[k], u) {
                    assert InRoots(g, roots, u);
                }
            }
            var comp: seq<int> := [];
            var v := 0;
            while v < n
                invariant 0 <= v <= n
                invariant assigned.Length == n
                invariant forall x :: seq_contains(comp, x) <==> (0 <= x < v && Mutual(g, u, x))
                invariant forall x :: 0 <= x < n ==> (assigned[x] <==> (InRoots(g, roots, x) || (x < v && Mutual(g, u, x))))
                invariant forall w :: 0 <= w < u ==> assigned[w]
            {
                if R[u][v] && R[v][u] {
                    ContainsAppend(comp, v);
                    comp := comp + [v];
                    assigned[v] := true;
                }
                v := v + 1;
            }
            PathRefl(g, u);
            InRootsAppend(g, roots, u);
            sccs := sccs + [comp];
            roots := roots + [u];
        }
        u := u + 1;
    }
    FinalProof(g, sccs, roots);
}

response:
Approach: rather than Tarjan's algorithm, which would be very hard to verify, this uses a simpler method that meets the same contract.

1. **Reachability.** For each node, a stack-based DFS computes the set of nodes it can reach.
   - Soundness: every visited node has a path from the source.
   - Completeness: once the stack is empty, the visited set is closed under edges, so every path from the source stays inside it.
2. **Grouping.** Nodes are scanned in order. Each unassigned node `u` becomes the root of a new component containing every `v` that is mutually reachable with `u`.
3. **Final lemma.** Path transitivity, plus the fact that no two roots are mutually reachable, gives the partition, strong connectivity and maximality properties.

```dafny
ghost predicate WF(g: seq<seq<int>>) {
    forall u: int, i: int :: 0 <= u < |g| && 0 <= i < |g[u]| ==> 0 <= g[u][i] < |g|
}

ghost predicate Mutual(g: seq<seq<int>>, a: int, b: int) {
    has_path(g, a, b) && has_path(g, b, a)
}

ghost predicate InRoots(g: seq<seq<int>>, roots: seq<int>, v: int) {
    exists k: int :: 0 <= k < |roots| && Mutual(g, roots[k], v)
}

ghost predicate Closed(g: seq<seq<int>>, vis: seq<bool>)
    requires |vis| == |g|
{
    forall x: int, i: int :: 0 <= x < |g| && vis[x] && 0 <= i < |g[x]| ==> 0 <= g[x][i] < |g| && vis[g[x][i]]
}

lemma PathRefl(g: seq<seq<int>>, u: int)
    ensures has_path(g, u, u)
{
    var p := [u];
    assert path_valid(g, p);
}

lemma EdgePath(g: seq<seq<int>>, u: int, v: int)
    requires has_edge(g, u, v)
    ensures has_path(g, u, v)
{
    var p := [u, v];
    assert path_valid(g, p) by {
        forall k | 0 <= k < |p| - 1 ensures has_edge(g, p[k], p[k+1]) {
            assert k == 0;
            assert p[0] == u && p[1] == v;
        }
    }
}

lemma PathTrans(g: seq<seq<int>>, a: int, b: int, c: int)
    requires has_path(g, a, b) && has_path(g, b, c)
    ensures has_path(g, a, c)
{
    var p :| |p| > 0 && p[0] == a && p[|p| - 1] == b && path_valid(g, p);
    var q :| |q| > 0 && q[0] == b && q[|q| - 1] == c && path_valid(g, q);
    var r := p + q[1..];
    assert path_valid(g, r) by {
        forall k | 0 <= k < |r| - 1 ensures has_edge(g, r[k], r[k+1]) {
            if k < |p| - 1 {
                assert r[k] == p[k] && r[k+1] == p[k+1];
                assert has_edge(g, p[k], p[k+1]);
            } else {
                var j := k - (|p| - 1);
                if k == |p| - 1 {
                    assert r[k] == p[|p| - 1];
                }
                assert r[k] == q[j];
                assert r[k+1] == q[j+1];
                assert has_edge(g, q[j], q[j+1]);
            }
        }
    }
    assert r[0] == a;
    if |q| == 1 {
        assert r == p;
    } else {
        assert r[|r| - 1] == q[|q| - 1];
    }
}

lemma SetRemove(A: set<int>, w: int)
    requires w in A
    ensures |A - {w}| == |A| - 1
{
    var B := A - {w};
    assert A * {w} == {w};
    assert A == B + {w};
    assert w !in B;
}

lemma PathClosed(g: seq<seq<int>>, vis: seq<bool>, p: seq<int>)
    requires |vis| == |g|
    requires Closed(g, vis)
    requires |p| > 0 && 0 <= p[0] < |g| && vis[p[0]]
    requires path_valid(g, p)
    ensures 0 <= p[|p| - 1] < |g| && vis[p[|p| - 1]]
    decreases |p|
{
    if |p| > 1 {
        var q := p[..|p| - 1];
        assert path_valid(g, q) by {
            forall k | 0 <= k < |q| - 1 ensures has_edge(g, q[k], q[k+1]) {
                assert q[k] == p[k] && q[k+1] == p[k+1];
                assert has_edge(g, p[k], p[k+1]);
            }
        }
        PathClosed(g, vis, q);
        var k := |p| - 2;
        var x := p[k];
        assert q[|q| - 1] == x;
        assert has_edge(g, p[k], p[k+1]);
        assert p[k+1] == p[|p| - 1];
        var i :| 0 <= x < |g| && 0 <= i < |g[x]| && g[x][i] == p[|p| - 1];
    }
}

lemma ClosedReach(g: seq<seq<int>>, vis: seq<bool>, s: int, t: int)
    requires |vis| == |g|
    requires Closed(g, vis)
    requires 0 <= s < |g| && vis[s]
    requires has_path(g, s, t)
    ensures 0 <= t < |g| && vis[t]
{
    var p :| |p| > 0 && p[0] == s && p[|p| - 1] == t && path_valid(g, p);
    PathClosed(g, vis, p);
}

lemma ContainsAppend(s: seq<int>, v: int)
    ensures forall x :: seq_contains(s + [v], x) <==> (seq_contains(s, x) || x == v)
{
    forall x ensures seq_contains(s + [v], x) <==> (seq_contains(s, x) || x == v) {
        if seq_contains(s, x) {
            var i :| 0 <= i < |s| && s[i] == x;
            assert (s + [v])[i] == x;
        }
        if x == v {
            assert (s + [v])[|s|] == v;
        }
        if seq_contains(s + [v], x) {
            var i :| 0 <= i < |s + [v]| && (s + [v])[i] == x;
            if i < |s| {
                assert s[i] == x;
            }
        }
    }
}

lemma InRootsAppend(g: seq<seq<int>>, roots: seq<int>, u: int)
    ensures forall v :: InRoots(g, roots + [u], v) <==> (InRoots(g, roots, v) || Mutual(g, u, v))
{
    forall v ensures InRoots(g, roots + [u], v) <==> (InRoots(g, roots, v) || Mutual(g, u, v)) {
        var r := roots + [u];
        if InRoots(g, roots, v) {
            var k :| 0 <= k < |roots| && Mutual(g, roots[k], v);
            assert r[k] == roots[k];
            assert Mutual(g, r[k], v);
        }
        if Mutual(g, u, v) {
            assert r[|roots|] == u;
            assert Mutual(g, r[|roots|], v);
        }
        if InRoots(g, r, v) {
            var k :| 0 <= k < |r| && Mutual(g, r[k], v);
            if k < |roots| {
                assert r[k] == roots[k];
            }
        }
    }
}

method Reach(g: seq<seq<int>>, s: int) returns (vis: seq<bool>)
    requires WF(g)
    requires 0 <= s < |g|
    ensures |vis| == |g|
    ensures forall t :: 0 <= t < |g| ==> (vis[t] <==> has_path(g, s, t))
{
    var n := |g|;
    var visited := new bool[n](_ => false);
    visited[s] := true;
    var stack: seq<int> := [s];
    ghost var unvisited: set<int> := set v | 0 <= v < n && v != s;
    PathRefl(g, s);
    while |stack| > 0
        invariant visited.Length == n
        invariant visited[s]
        invariant forall v :: v in unvisited <==> (0 <= v < n && !visited[v])
        invariant forall x :: x in stack ==> 0 <= x < n && visited[x]
        invariant forall v :: 0 <= v < n && visited[v] ==> has_path(g, s, v)
        invariant forall x :: 0 <= x < n && visited[x] && x !in stack ==>
                    (forall i :: 0 <= i < |g[x]| ==> visited[g[x][i]])
        decreases |unvisited|, |stack|
    {
        ghost var oldStack := stack;
        var v := stack[|stack| - 1];
        stack := stack[..|stack| - 1];
        assert oldStack == stack + [v];
        ghost var u0 := |unvisited|;
        ghost var s0 := |stack|;
        var i := 0;
        while i < |g[v]|
            invariant visited.Length == n
            invariant 0 <= i <= |g[v]|
            invariant 0 <= v < n && visited[v]
            invariant visited[s]
            invariant forall v' :: v' in unvisited <==> (0 <= v' < n && !visited[v'])
            invariant forall x :: x in stack ==> 0 <= x < n && visited[x]
            invariant forall v' :: 0 <= v' < n && visited[v'] ==> has_path(g, s, v')
            invariant forall x :: 0 <= x < n && visited[x] && x !in stack && x != v ==>
                        (forall j :: 0 <= j < |g[x]| ==> visited[g[x][j]])
            invariant forall j :: 0 <= j < i ==> visited[g[v][j]]
            invariant |unvisited| <= u0
            invariant |unvisited| == u0 ==> |stack| == s0
        {
            var w := g[v][i];
            if !visited[w] {
                assert 0 <= v < |g| && g[v][i] == w;
                assert has_edge(g, v, w);
                EdgePath(g, v, w);
                PathTrans(g, s, v, w);
                SetRemove(unvisited, w);
                unvisited := unvisited - {w};
                visited[w] := true;
                stack := stack + [w];
            }
            i := i + 1;
        }
    }
    vis := visited[..];
    assert Closed(g, vis) by {
        forall x, i | 0 <= x < |g| && vis[x] && 0 <= i < |g[x]|
            ensures 0 <= g[x][i] < |g| && vis[g[x][i]]
        {
            assert visited[x];
            assert x !in stack;
        }
    }
    forall t | 0 <= t < n && has_path(g, s, t) ensures vis[t] {
        ClosedReach(g, vis, s, t);
    }
}

lemma FinalProof(g: seq<seq<int>>, sccs: seq<seq<int>>, roots: seq<int>)
    requires |sccs| == |roots|
    requires forall k :: 0 <= k < |roots| ==> 0 <= roots[k] < |g|
    requires forall k, x :: 0 <= k < |roots| ==> (seq_contains(sccs[k], x) <==> (0 <= x < |g| && Mutual(g, roots[k], x)))
    requires forall v :: 0 <= v < |g| ==> InRoots(g, roots, v)
    requires forall k1, k2 :: 0 <= k1 < |roots| && 0 <= k2 < |roots| && k1 != k2 ==> !Mutual(g, roots[k1], roots[k2])
    ensures is_valid_scc_result(g, sccs)
{
    forall i, j, x | 0 <= i < |sccs| && 0 <= j < |sccs| && i != j
        ensures !(seq_contains(sccs[i], x) && seq_contains(sccs[j], x))
    {
        if seq_contains(sccs[i], x) && seq_contains(sccs[j], x) {
            PathTrans(g, roots[i], x, roots[j]);
            PathTrans(g, roots[j], x, roots[i]);
            assert Mutual(g, roots[i], roots[j]);
        }
    }
    assert are_disjoint(sccs);
    forall v | 0 <= v < |g| ensures is_covered(sccs, v) {
        var k :| 0 <= k < |roots| && Mutual(g, roots[k], v);
        assert seq_contains(sccs[k], v);
    }
    assert is_partition(g, sccs);
    forall k | 0 <= k < |sccs| ensures is_strongly_connected(g, sccs[k]) {
        PathRefl(g, roots[k]);
        assert seq_contains(sccs[k], roots[k]);
        forall i | 0 <= i < |sccs[k]| ensures 0 <= sccs[k][i] < |g| {
            assert seq_contains(sccs[k], sccs[k][i]);
        }
        forall a, b | seq_contains(sccs[k], a) && seq_contains(sccs[k], b)
            ensures has_path(g, a, b) && has_path(g, b, a)
        {
            PathTrans(g, a, roots[k], b);
            PathTrans(g, b, roots[k], a);
        }
    }
    forall i, j | 0 <= i < |sccs| && 0 <= j < |sccs| && i != j
        ensures scc_has_path(g, sccs, i, j) ==> !scc_has_path(g, sccs, j, i)
    {
        if scc_has_path(g, sccs, i, j) && scc_has_path(g, sccs, j, i) {
            var a, b :| seq_contains(sccs[i], a) && seq_contains(sccs[j], b) && has_path(g, a, b);
            var c, d :| seq_contains(sccs[j], c) && seq_contains(sccs[i], d) && has_path(g, c, d);
            var ri, rj := roots[i], roots[j];
            PathTrans(g, ri, a, b);
            PathTrans(g, ri, b, rj);
            PathTrans(g, rj, c, d);
            PathTrans(g, rj, d, ri);
            assert Mutual(g, ri, rj);
            assert false;
        }
    }
}

