            var k :| 0 <= k < |roots| && Mutual(g, roots[k], v);
            assert r[k] == roots[k];
            assert Mutual(g, r[k], v);
        }
        if Mutual(g, u, v) {
            assert r[|roots|] == u;
            assert Mutual(g, r[|roots|], v);
        }
        if InRoots(g, r, v) {
            var k :| 0 <= k < |r| && Mutual(g, r[k], v);
            if k < |roots| {
                assert r[k] == roots[k];
            }
        }
    }
}

method Reach(g: seq<seq<int>>, s: int) returns (vis: seq<bool>)
    requires WF(g)
    requires 0 <= s < |g|
    ensures |vis| == |g|
    ensures forall t :: 0 <= t < |g| ==> (vis[t] <==> has_path(g, s, t))
{
    var n := |g|;
    var visited := new bool[n](_ => false);
    visited[s] := true;
    var stack: seq<int> := [s];
    ghost var unvisited: set<int> := set v | 0 <= v < n && v != s;
    PathRefl(g, s);
    while |stack| > 0
        invariant visited.Length == n
        invariant visited[s]
        invariant forall v :: v in unvisited <==> (0 <= v < n && !visited[v])
        invariant forall x :: x in stack ==> 0 <= x < n && visited[x]
        invariant forall v :: 0 <= v < n && visited[v] ==> has_path(g, s, v)
        invariant forall x :: 0 <= x < n && visited[x] && x !in stack ==>
                    (forall i :: 0 <= i < |g[x]| ==> visited[g[x][i]])
        decreases |unvisited|, |stack|
    {
        ghost var oldStack := stack;
        var v := stack[|stack| - 1];
        assert v in oldStack;
        assert 0 <= v < n && visited[v];
        stack := stack[..|stack| - 1];
        assert oldStack == stack + [v];
        assert forall x :: x in stack ==> x in oldStack;
        assert forall x :: x in oldStack ==> x in stack || x == v;
        ghost var u0 := |unvisited|;
        ghost var s0 := |stack|;
        var i := 0;
        while i < |g[v]|
            invariant visited.Length == n
            invariant 0 <= v < n && visited[v]
            invariant 0 <= i <= |g[v]|
            invariant visited[s]
            invariant forall v' :: v' in unvisited <==> (0 <= v' < n && !visited[v'])
            invariant forall x :: x in stack ==> 0 <= x < n && visited[x]
            invariant forall v' :: 0 <= v' < n && visited[v'] ==> has_path(g, s, v')
            invariant forall x :: 0 <= x < n && visited[x] && x !in stack && x != v ==>
                        (forall j :: 0 <= j < |g[x]| ==> visited[g[x][j]])
            invariant forall j :: 0 <= j < i ==> visited[g[v][j]]
            invariant |unvisited| <= u0
            invariant |unvisited| == u0 ==> |stack| == s0
        {
            var w := g[v][i];
            if !visited[w] {
                assert 0 <= v < |g| && g[v][i] == w;
                assert has_edge(g, v, w);
                EdgePath(g, v, w);
                PathTrans(g, s, v, w);
                SetRemove(unvisited, w);
                unvisited := unvisited - {w};
                visited[w] := true;
                stack := stack + [w];
            }
            i := i + 1;
        }
    }
    vis := visited[..];
    assert Closed(g, vis) by {
        forall x, i | 0 <= x < |g| && vis[x] && 0 <= i < |g[x]|
            ensures 0 <= g[x][i] < |g| && vis[g[x][i]]
        {
            assert visited[x];
            assert x !in stack;
        }
    }
    forall t | 0 <= t < n && has_path(g, s, t) ensures vis[t] {
        ClosedReach(g, vis, s, t);
    }
}

lemma FinalProof(g: seq<seq<int>>, sccs: seq<seq<int>>, roots: seq<int>)
    requires |sccs| == |roots|
    requires forall k :: 0 <= k < |roots| ==> 0 <= roots[k] < |g|
    requires forall k, x :: 0 <= k < |roots| ==> (seq_contains(sccs[k], x) <==> (0 <= x < |g| && Mutual(g, roots[k], x)))
    requires forall v :: 0 <= v < |g| ==> InRoots(g, roots, v)
    requires forall k1, k2 :: 0 <= k1 < |roots| && 0 <= k2 < |roots| && k1 != k2 ==> !Mutual(g, roots[k1], roots[k2])
    ensures is_valid_scc_result(g, sccs)
{
    forall i, j, x | 0 <= i < |sccs| && 0 <= j < |sccs| && i != j
        ensures !(seq_contains(sccs[i], x) && seq_contains(sccs[j], x))
    {
        if seq_contains(sccs[i], x) && seq_contains(sccs[j], x) {
            PathTrans(g, roots[i], x, roots[j]);
            PathTrans(g, roots[j], x, roots[i]);
            assert Mutual(g, roots[i], roots[j]);
        }
    }
    assert are_disjoint(sccs);
    forall v | 0 <= v < |g| ensures is_covered(sccs, v) {
        assert InRoots(g, roots, v);
        var k :| 0 <= k < |roots| && Mutual(g, roots[k], v);
        assert seq_contains(sccs[k], v);
    }
    assert is_partition(g, sccs);
    forall k | 0 <= k < |sccs| ensures is_strongly_connected(g, sccs[k]) {
        PathRefl(g, roots[k]);
        assert seq_contains(sccs[k], roots[k]);
        forall i | 0 <= i < |sccs[k]| ensures 0 <= sccs[k][i] < |g| {
            assert seq_contains(sccs[k], sccs[k][i]);
        }
        forall a, b | seq_contains(sccs[k], a) && seq_contains(sccs[k], b)
            ensures has_path(g, a, b) && has_path(g, b, a)
        {
            PathTrans(g, a, roots[k], b);
            PathTrans(g, b, roots[k], a);
        }
    }
    forall i, j | 0 <= i < |sccs| && 0 <= j < |sccs| && i != j
        ensures scc_has_path(g, sccs, i, j) ==> !scc_has_path(g, sccs, j, i)
    {
        if scc_has_path(g, sccs, i, j) && scc_has_path(g, sccs, j, i) {
            var a, b :| seq_contains(sccs[i], a) && seq_contains(sccs[j], b) && has_path(g, a, b);
            var c, d :| seq_contains(sccs[j], c) && seq_contains(sccs[i], d) && has_path(g, c, d);
            var ri, rj := roots[i], roots[j];
            PathTrans(g, ri, a, b);
            PathTrans(g, ri, b, rj);
            PathTrans(g, rj, c, d);
            PathTrans(g, rj, d, ri);
            assert Mutual(g, ri, rj);
            assert false;
        }
    }
}

method find_sccs(graph: Graph) returns (sccs: seq<seq<int>>)
    requires well_formed(graph)
    requires size_bounded(view(graph))
    ensures is_valid_scc_result(view(graph), sccs)
{
    var g := graph.adj;
    var n := |g|;
    assert WF(g);
    var R: seq<seq<bool>> := [];
    var u := 0;
    while u < n
        invariant 0 <= u <= n
        invariant |R| == u
        invariant forall a :: 0 <= a < u ==> |R[a]| == n
        invariant forall a, b :: 0 <= a < u && 0 <= b < n ==> (R[a][b] <==> has_path(g, a, b))
    {
        var row := Reach(g, u);
        R := R + [row];
        u := u + 1;
    }
    var asg := new bool[n](_ => false);
    sccs := [];
    ghost var roots: seq<int> := [];
    u := 0;
    while u < n
        invariant 0 <= u <= n
        invariant asg.Length == n
        invariant |sccs| == |roots|
        invariant forall k :: 0 <= k < |roots| ==> 0 <= roots[k] < n
        invariant forall k, x :: 0 <= k < |roots| ==> (seq_contains(sccs[k], x) <==> (0 <= x < n && Mutual(g, roots[k], x)))
        invariant forall v :: 0 <= v < n ==> (asg[v] <==> InRoots(g, roots, v))
        invariant forall w :: 0 <= w < u ==> asg[w]
        invariant forall k1, k2 :: 0 <= k1 < |roots| && 0 <= k2 < |roots| && k1 != k2 ==> !Mutual(g, roots[k1], roots[k2])
    {
        if !asg[u] {
            assert !InRoots(g, roots, u);
            forall k | 0 <= k < |roots|
                ensures !Mutual(g, u, roots[k]) && !Mutual(g, roots[k], u)
            {
                if Mutual(g, roots[k], u) {
                    assert InRoots(g, roots, u);
                }
            }
            var comp: seq<int> := [];
            var v := 0;
            while v < n
                invariant 0 <= v <= n
                invariant asg.Length == n
                invariant forall x :: seq_contains(comp, x) <==> (0 <= x < v && Mutual(g, u, x))
                invariant forall x :: 0 <= x < n ==> (asg[x] <==> (InRoots(g, roots, x) || (x < v && Mutual(g, u, x))))
                invariant forall w :: 0 <= w < u ==> asg[w]
            {
                if R[u][v] && R[v][u] {
                    ContainsAppend(comp, v);
                    comp := comp + [v];
                    asg[v] := true;
                }
                v := v + 1;
            }
            PathRefl(g, u);
            InRootsAppend(g, roots, u);
            sccs := sccs + [comp];
            roots := roots + [u];
        }
        u := u + 1;
    }
    FinalProof(g, sccs, roots);
}
