/*
 * mf_maps(n,u,v) contains all maps whose keys are:
 *
 *   every (a,b) with 0 <= a < u and 0 <= b < n,
 *   followed by (u,b) with 0 <= b < v.
 *
 * Every stored value is between zero and 100000.
 */
function mf_maps(
    n: nat,
    u: nat,
    v: nat): set<FlowMap>
    requires u <= n
    requires v <= n
    requires u < n || v == 0
    decreases u, v
{
    if v == 0 then
        if u == 0 then
            {map[]}
        else
            mf_maps(n, u - 1, n)
    else
        set m: FlowMap, x: int |
            m in mf_maps(n, u, v - 1) &&
            0 <= x <= 100000
        :: m[(u, v - 1) := x]
}

