method {:vcs_split_on_every_assert} max_flow_value(
    graph: CapacityGraph,
    s: int,
    t: int) returns (max_val: int)
    requires well_formed(graph)
    requires capacities_bounded(view(graph))
    requires 0 <= s < size(graph)
    requires 0 <= t < size(graph)
    requires s != t
    ensures exists f: FlowMap ::
        is_max_flow(view(graph), f, s, t) &&
        flow_val(view(graph), f, s) == max_val
{
    var g := graph.adj;
    var n: nat := |g|;
    assert n > 0;

    var universe := mf_maps(n, n, 0);
    var remaining := universe;
    var best: FlowMap := map[];
    var bestVal := 0;

    mf_empty_valid(g, s, t);
    mf_empty_in(g, s, |g|);
    mf_empty_out(g, s, |g[s]|);

    assert mf_in(g, best, s) == 0;
    assert mf_out(g, best, s) == 0;
    assert mf_value(g, best, s) == 0;

    while remaining != {}
        invariant remaining <= universe
        invariant mf_valid(g, best, s, t)
        invariant bestVal == mf_value(g, best, s)
        invariant forall h: FlowMap ::
            h in universe - remaining &&
            mf_valid(g, h, s, t) ==>
                mf_value(g, h, s) <= bestVal
        decreases |remaining|
    {
        var oldRemaining := remaining;
        var candidate: FlowMap :| candidate in remaining;
        remaining := remaining - {candidate};

        if mf_valid(g, candidate, s, t) {
            var candidateVal := mf_value(g, candidate, s);

            if candidateVal > bestVal {
                best := candidate;
                bestVal := candidateVal;
            }

            assert mf_value(g, candidate, s) <= bestVal;
        }

        forall h: FlowMap |
            h in universe - remaining &&
            mf_valid(g, h, s, t)
            ensures mf_value(g, h, s) <= bestVal
        {
            if h == candidate {
                assert mf_value(g, candidate, s) <= bestVal;
            } else {
                assert h in universe - oldRemaining;
            }
        }
    }

    max_val := bestVal;
    mf_valid_sound(g, best, s, t);
    mf_value_agrees(g, best, s);

    forall other: FlowMap |
        is_valid_flow(g, other, s, t)
        ensures flow_val(g, other, s) <= flow_val(g, best, s)
