        mf_valid_complete(g, canonical, s, t);
        mf_value_agrees(g, canonical, s);

        assert canonical in universe;
        assert remaining == {};
        assert canonical in universe - remaining;
        assert mf_value(g, canonical, s) <= bestVal;
        assert flow_val(g, other, s) ==
            flow_val(g, canonical, s);
        assert bestVal == flow_val(g, best, s);
    }

    assert is_max_flow(g, best, s, t);
    assert flow_val(g, best, s) == max_val;
    assert exists f: FlowMap ::
        f == best &&
        is_max_flow(g, f, s, t) &&
        flow_val(g, f, s) == max_val;
