function rch(g: seq<seq<int>>, u: int, v: int, fuel: int): bool
    decreases fuel
{
    0 <= u < |g| &&
    0 <= v < |g| &&
    (u == v ||
     (fuel > 0 &&
      exists i: int |
          0 <= i < |g[u]| && 0 <= g[u][i] < |g|
        :: rch(g, g[u][i], v, fuel - 1)))
}

function equivalent(g: seq<seq<int>>, u: int, v: int): bool {
    rch(g, u, v, |g|) && rch(g, v, u, |g|)
}

function component(g: seq<seq<int>>, representative: int, k: int): seq<int>
    requires 0 <= representative < |g|
    requires 0 <= k <= |g|
    decreases |g| - k
{
    if k == |g| then []
    else if equivalent(g, representative, k) then
        [k] + component(g, representative, k + 1)
    else
        component(g, representative, k + 1)
}

function is_representative(g: seq<seq<int>>, u: int): bool
    requires 0 <= u < |g|
{
    forall v: int | 0 <= v < u :: !equivalent(g, v, u)
}

function all_components(g: seq<seq<int>>, k: int): seq<seq<int>>
    requires 0 <= k <= |g|
    decreases |g| - k
{
    if k == |g| then []
    else if is_representative(g, k) then
        [component(g, k, 0)] + all_components(g, k + 1)
    else
        all_components(g, k + 1)
}

ghost predicate wf_view(g: seq<seq<int>>) {
    forall u: int, i: int ::
        0 <= u < |g| && 0 <= i < |g[u]| ==>
        0 <= g[u][i] < |g|
}

ghost function elements(s: seq<int>): set<int>
    decreases |s|
{
    if |s| == 0 then {}
    else {s[0]} + elements(s[1..])
}

ghost function int_range(n: int): set<int>
    decreases n
{
    if n <= 0 then {}
    else int_range(n - 1) + {n - 1}
}

lemma ElementsMembership(s: seq<int>, x: int)
    ensures x in elements(s) <==> seq_contains(s, x)
    decreases |s|
{
    if |s| != 0 {
        ElementsMembership(s[1..], x);
        if x in elements(s[1..]) {
            var i :| 0 <= i < |s[1..]| && s[1..][i] == x;
            assert s[i + 1] == x;
        }
        if seq_contains(s, x) && s[0] != x {
            var i :| 0 <= i < |s| && s[i] == x;
            assert 0 < i;
            assert s[1..][i - 1] == x;
        }
    }
}

lemma RangeMembership(n: int, x: int)
    ensures x in int_range(n) <==> 0 <= x < n
    decreases n
{
    if n > 0 {
        RangeMembership(n - 1, x);
    }
}

lemma RangeCardinality(n: int)
    requires 0 <= n
    ensures |int_range(n)| == n
    decreases n
{
    if n > 0 {
        RangeCardinality(n - 1);
        RangeMembership(n - 1, n - 1);
    }
}

lemma DistinctElementsCardinality(s: seq<int>)
    requires forall i: int, j: int ::
        0 <= i < j < |s| ==> s[i] != s[j]
    ensures |elements(s)| == |s|
    decreases |s|
{
    if |s| != 0 {
        DistinctElementsCardinality(s[1..]);

        assert s[0] !in elements(s[1..]) by {
            if s[0] in elements(s[1..]) {
                ElementsMembership(s[1..], s[0]);
                var i :| 0 <= i < |s[1..]| && s[1..][i] == s[0];
                assert s[i + 1] == s[0];
                assert false;
            }
        }
    }
}

lemma BoundedSequenceHasDuplicate(s: seq<int>, n: int)
    requires 0 <= n
    requires |s| > n
    requires forall i: int :: 0 <= i < |s| ==> 0 <= s[i] < n
    ensures exists i: int, j: int ::
        0 <= i < j < |s| && s[i] == s[j]
{
    if !(exists i: int, j: int ::
            0 <= i < j < |s| && s[i] == s[j])
    {
        assert forall i: int, j: int ::
            0 <= i < j < |s| ==> s[i] != s[j];

        DistinctElementsCardinality(s);
        RangeCardinality(n);

        assert elements(s) <= int_range(n) by {
            forall x | x in elements(s)
                ensures x in int_range(n)
            {
                ElementsMembership(s, x);
                var i :| 0 <= i < |s| && s[i] == x;
                RangeMembership(n, x);
            }
        }

        assert |elements(s)| <= |int_range(n)|;
        assert false;
    }
}

lemma PathNodesBounded(g: seq<seq<int>>, p: seq<int>)
    requires wf_view(g)
    requires |p| > 0
