        var i, j :| 0 <= i < j < |p| && p[i] == p[j];

        var q := p[..i + 1] + p[j + 1..];
        RemoveCycleIsPath(g, p, i, j);

        assert |q| > 0;
        assert |q| < |p|;
        assert q[0] == p[0];

        if j == |p| - 1 {
            assert q[|q| - 1] == p[i];
            assert p[i] == p[j];
            assert q[|q| - 1] == p[|p| - 1];
        } else {
            assert q[|q| - 1] == p[|p| - 1];
        }

        PathGivesReach(g, q);
    }
