function equivalent(g: seq<seq<int>>, u: int, v: int): bool {
    rch(g, u, v, |g|) && rch(g, v, u, |g|)
}

function component(g: seq<seq<int>>, representative: int, k: int): seq<int>
    requires 0 <= representative < |g|
    requires 0 <= k <= |g|
    decreases |g| - k
{
    if k == |g| then []
    else if equivalent(g, representative, k) then
        [k] + component(g, representative, k + 1)
    else
        component(g, representative, k + 1)
