function is_representative(g: seq<seq<int>>, u: int): bool
    requires 0 <= u < |g|
{
    forall v: int | 0 <= v < u :: !equivalent(g, v, u)
}

function all_components(g: seq<seq<int>>, k: int): seq<seq<int>>
    requires 0 <= k <= |g|
    decreases |g| - k
{
    if k == |g| then []
    else if is_representative(g, k) then
        [component(g, k, 0)] + all_components(g, k + 1)
    else
        all_components(g, k + 1)
