    requires has_path(g, v, w)
    ensures has_path(g, u, w)
{
    var p :| |p| > 0 &&
             p[0] == u &&
             p[|p| - 1] == v &&
             path_valid(g, p);

    var q :| |q| > 0 &&
             q[0] == v &&
             q[|q| - 1] == w &&
             path_valid(g, q);

    JoinPaths(g, p, q);
    var r := p + q[1..];

    assert |r| > 0;
    assert r[0] == u;
    assert r[|r| - 1] == w;
