        ComponentStrong(g, r);
    }
}

method find_sccs(graph: Graph) returns (sccs: seq<seq<int>>)
    requires well_formed(graph)
    requires size_bounded(view(graph))
    ensures is_valid_scc_result(view(graph), sccs)
{
    sccs := all_components(graph.adj, 0);

    assert graph.adj == view(graph);
    assert wf_view(graph.adj);

    ComponentsAreDisjoint(graph.adj);
    ComponentsCover(graph.adj);
    AllComponentsStrong(graph.adj);
    ComponentsMaximal(graph.adj);

    assert is_partition(graph.adj, sccs);
    assert is_valid_scc_result(graph.adj, sccs);
}
