function rch(g: seq<seq<int>>, u: int, v: int, fuel: int): bool
    decreases fuel
{
    0 <= u < |g| &&
    0 <= v < |g| &&
    (u == v ||
     (fuel > 0 &&
      exists i: int |
          0 <= i < |g[u]| && 0 <= g[u][i] < |g|
        :: rch(g, g[u][i], v, fuel - 1)))
}

function equivalent(g: seq<seq<int>>, u: int, v: int): bool {
    rch(g, u, v, |g|) && rch(g, v, u, |g|)
}

function component(g: seq<seq<int>>, representative: int, k: int): seq<int>
    requires 0 <= representative < |g|
    requires 0 <= k <= |g|
    decreases |g| - k
{
    if k == |g| then []
    else if equivalent(g, representative, k) then
        [k] + component(g, representative, k + 1)
    else
        component(g, representative, k + 1)
}

function is_representative(g: seq<seq<int>>, u: int): bool
    requires 0 <= u < |g|
{
    forall v: int | 0 <= v < u :: !equivalent(g, v, u)
}

function all_components(g: seq<seq<int>>, k: int): seq<seq<int>>
    requires 0 <= k <= |g|
    decreases |g| - k
{
    if k == |g| then []
    else if is_representative(g, k) then
        [component(g, k, 0)] + all_components(g, k + 1)
    else
        all_components(g, k + 1)
}

ghost predicate wf_view(g: seq<seq<int>>) {
    forall u: int, i: int ::
        0 <= u < |g| && 0 <= i < |g[u]| ==>
        0 <= g[u][i] < |g|
}

ghost function elements(s: seq<int>): set<int>
