    decreases |s|
{
    if |s| != 0 {
        ElementsMembership(s[1..], x);
        if x in elements(s[1..]) {
            var i :| 0 <= i < |s[1..]| && s[1..][i] == x;
            assert s[i + 1] == x;
        }
        if seq_contains(s, x) && s[0] != x {
            var i :| 0 <= i < |s| && s[i] == x;
            assert 0 < i;
