lemma IntSetCardinalityMonotone(a: set<int>, b: set<int>)
    requires a <= b
    ensures |a| <= |b|
    decreases |a|
{
    if a != {} {
        var x :| x in a;
        assert x in b;
        assert a - {x} <= b - {x};

        IntSetCardinalityMonotone(a - {x}, b - {x});

        assert x !in a - {x};
        assert x !in b - {x};
        assert a == (a - {x}) + {x};
        assert b == (b - {x}) + {x};
        assert |a| == |a - {x}| + 1;
        assert |b| == |b - {x}| + 1;
    }
}

lemma DistinctElementsCardinality(s: seq<int>)
    requires forall i: int, j: int ::
        0 <= i < j < |s| ==> s[i] != s[j]
    ensures |elements(s)| == |s|
    decreases |s|
{
    if |s| != 0 {
        DistinctElementsCardinality(s[1..]);

        assert s[0] !in elements(s[1..]) by {
            if s[0] in elements(s[1..]) {
                ElementsMembership(s[1..], s[0]);
                var i :| 0 <= i < |s[1..]| && s[1..][i] == s[0];
                assert s[i + 1] == s[0];
                assert false;
            }
        }
    }
}

lemma BoundedSequenceHasDuplicate(s: seq<int>, n: int)
    requires 0 <= n
    requires |s| > n
    requires forall i: int :: 0 <= i < |s| ==> 0 <= s[i] < n
    ensures exists i: int, j: int ::
        0 <= i < j < |s| && s[i] == s[j]
{
    if !(exists i: int, j: int ::
            0 <= i < j < |s| && s[i] == s[j])
    {
        assert forall i: int, j: int ::
            0 <= i < j < |s| ==> s[i] != s[j];

        DistinctElementsCardinality(s);
        RangeCardinality(n);

        assert elements(s) <= int_range(n) by {
            forall x | x in elements(s)
                ensures x in int_range(n)
            {
                ElementsMembership(s, x);
                var i :| 0 <= i < |s| && s[i] == x;
                RangeMembership(n, x);
            }
        }

        IntSetCardinalityMonotone(elements(s), int_range(n));
        assert |elements(s)| <= |int_range(n)|;
        assert |s| <= n;
        assert false;
    }
}

lemma PathNodesBounded(g: seq<seq<int>>, p: seq<int>)
    requires wf_view(g)
    requires |p| > 0
    requires 0 <= p[0] < |g|
    requires path_valid(g, p)
    ensures forall i: int :: 0 <= i < |p| ==> 0 <= p[i] < |g|
{
    forall i | 0 <= i < |p|
        ensures 0 <= p[i] < |g|
    {
        if i == 0 {
        } else {
            assert has_edge(g, p[i - 1], p[i]);
            var e :| 0 <= p[i - 1] < |g| &&
                      0 <= e < |g[p[i - 1]]| &&
                      g[p[i - 1]][e] == p[i];
        }
    }
}

lemma PrependPath(g: seq<seq<int>>, u: int, p: seq<int>)
    requires |p| > 0
    requires has_edge(g, u, p[0])
    requires path_valid(g, p)
    ensures path_valid(g, [u] + p)
{
    forall k | 0 <= k < |[u] + p| - 1
        ensures has_edge(g, ([u] + p)[k], ([u] + p)[k + 1])
    {
        if k == 0 {
        } else {
            assert ([u] + p)[k] == p[k - 1];
            assert ([u] + p)[k + 1] == p[k];
        }
    }
}

lemma JoinPaths(g: seq<seq<int>>, p: seq<int>, q: seq<int>)
    requires |p| > 0
    requires |q| > 0
    requires p[|p| - 1] == q[0]
    requires path_valid(g, p)
    requires path_valid(g, q)
    ensures path_valid(g, p + q[1..])
{
    forall k | 0 <= k < |p + q[1..]| - 1
        ensures has_edge(g, (p + q[1..])[k],
                            (p + q[1..])[k + 1])
    {
        if k < |p| - 1 {
            assert (p + q[1..])[k] == p[k];
            assert (p + q[1..])[k + 1] == p[k + 1];
        } else if k == |p| - 1 {
            assert |q| > 1;
            assert (p + q[1..])[k] == q[0];
            assert (p + q[1..])[k + 1] == q[1];
        } else {
            var j := k - |p| + 1;
            assert 0 <= j < |q| - 1;
            assert (p + q[1..])[k] == q[j];
            assert (p + q[1..])[k + 1] == q[j + 1];
        }
    }
}

lemma HasPathTransitive(g: seq<seq<int>>, u: int, v: int, w: int)
    requires has_path(g, u, v)
    requires has_path(g, v, w)
    ensures has_path(g, u, w)
{
    var p :| |p| > 0 &&
             p[0] == u &&
             p[|p| - 1] == v &&
             path_valid(g, p);

    var q :| |q| > 0 &&
             q[0] == v &&
             q[|q| - 1] == w &&
             path_valid(g, q);

    JoinPaths(g, p, q);
    var r := p + q[1..];

    assert |r| > 0;
    assert r[0] == u;
    assert r[|r| - 1] == w;
}

lemma ReachMonotoneOne(g: seq<seq<int>>, u: int, v: int, fuel: int)
    requires 0 <= fuel
    requires rch(g, u, v, fuel)
    ensures rch(g, u, v, fuel + 1)
    decreases fuel
{
    if u != v {
        var i :| 0 <= i < |g[u]| &&
                  0 <= g[u][i] < |g| &&
                  rch(g, g[u][i], v, fuel - 1);

        ReachMonotoneOne(g, g[u][i], v, fuel - 1);
    }
}

lemma ReachMonotone(g: seq<seq<int>>, u: int, v: int,
                    small: int, large: int)
    requires 0 <= small <= large
    requires rch(g, u, v, small)
    ensures rch(g, u, v, large)
    decreases large - small
{
    if small < large {
        ReachMonotoneOne(g, u, v, small);
        ReachMonotone(g, u, v, small + 1, large);
    }
}

lemma ReachGivesPath(g: seq<seq<int>>, u: int, v: int, fuel: int)
    requires 0 <= fuel
    requires rch(g, u, v, fuel)
    ensures has_path(g, u, v)
    decreases fuel
{
    if u == v {
        var p := [u];
        assert path_valid(g, p);
    } else {
        var i :| 0 <= i < |g[u]| &&
                  0 <= g[u][i] < |g| &&
                  rch(g, g[u][i], v, fuel - 1);

        ReachGivesPath(g, g[u][i], v, fuel - 1);

        var p :| |p| > 0 &&
                 p[0] == g[u][i] &&
                 p[|p| - 1] == v &&
                 path_valid(g, p);

        assert has_edge(g, u, g[u][i]);
        PrependPath(g, u, p);

        var q := [u] + p;
        assert q[0] == u;
        assert q[|q| - 1] == v;
    }
}

lemma PathUsesFuel(g: seq<seq<int>>, p: seq<int>)
    requires |p| > 0
    requires path_valid(g, p)
    requires forall i: int :: 0 <= i < |p| ==> 0 <= p[i] < |g|
    ensures rch(g, p[0], p[|p| - 1], |p| - 1)
    decreases |p|
{
    if |p| > 1 {
        var tail := p[1..];
        PathUsesFuel(g, tail);

        assert has_edge(g, p[0], p[1]);
        var e :| 0 <= p[0] < |g| &&
                  0 <= e < |g[p[0]]| &&
                  g[p[0]][e] == p[1];

        assert rch(g, g[p[0]][e], p[|p| - 1], |p| - 2);
    }
}

lemma RemoveCycleIsPath(g: seq<seq<int>>, p: seq<int>, i: int, j: int)
    requires |p| > 0
    requires path_valid(g, p)
    requires 0 <= i < j < |p|
    requires p[i] == p[j]
    ensures path_valid(g, p[..i + 1] + p[j + 1..])
{
    var q := p[..i + 1] + p[j + 1..];

    forall k | 0 <= k < |q| - 1
        ensures has_edge(g, q[k], q[k + 1])
    {
        if k < i {
            assert q[k] == p[k];
            assert q[k + 1] == p[k + 1];
        } else if k == i {
            assert j + 1 < |p|;
            assert q[k] == p[i];
            assert q[k + 1] == p[j + 1];
            assert p[i] == p[j];
        } else {
            var t := j + (k - i);
            assert 0 <= t < |p| - 1;
            assert q[k] == p[t];
            assert q[k + 1] == p[t + 1];
        }
    }
}

lemma PathGivesReach(g: seq<seq<int>>, p: seq<int>)
    requires wf_view(g)
    requires |p| > 0
    requires path_valid(g, p)
    requires 0 <= p[0] < |g|
    ensures rch(g, p[0], p[|p| - 1], |g|)
    decreases |p|
{
    PathNodesBounded(g, p);

    if |p| <= |g| + 1 {
        PathUsesFuel(g, p);
        ReachMonotone(g, p[0], p[|p| - 1], |p| - 1, |g|);
    } else {
        BoundedSequenceHasDuplicate(p, |g|);
        var i, j :| 0 <= i < j < |p| && p[i] == p[j];

        var q := p[..i + 1] + p[j + 1..];
        RemoveCycleIsPath(g, p, i, j);

        assert |q| > 0;
        assert |q| < |p|;
        assert q[0] == p[0];

        if j == |p| - 1 {
            assert q[|q| - 1] == p[i];
            assert p[i] == p[j];
            assert q[|q| - 1] == p[|p| - 1];
        } else {
            assert q[|q| - 1] == p[|p| - 1];
        }

        PathGivesReach(g, q);
    }
}

lemma HasPathGivesReach(g: seq<seq<int>>, u: int, v: int)
    requires wf_view(g)
    requires 0 <= u < |g|
    requires has_path(g, u, v)
    ensures rch(g, u, v, |g|)
{
    var p :| |p| > 0 &&
             p[0] == u &&
             p[|p| - 1] == v &&
             path_valid(g, p);

    PathGivesReach(g, p);
}

lemma EquivalentReflexive(g: seq<seq<int>>, u: int)
    requires 0 <= u < |g|
    ensures equivalent(g, u, u)
{
}

lemma EquivalentSymmetric(g: seq<seq<int>>, u: int, v: int)
    requires equivalent(g, u, v)
    ensures equivalent(g, v, u)
{
}

lemma EquivalentTransitive(g: seq<seq<int>>, a: int, b: int, c: int)
    requires wf_view(g)
    requires equivalent(g, a, b)
    requires equivalent(g, b, c)
    ensures equivalent(g, a, c)
{
    ReachGivesPath(g, a, b, |g|);
    ReachGivesPath(g, b, c, |g|);
    HasPathTransitive(g, a, b, c);
    HasPathGivesReach(g, a, c);

    ReachGivesPath(g, c, b, |g|);
    ReachGivesPath(g, b, a, |g|);
    HasPathTransitive(g, c, b, a);
    HasPathGivesReach(g, c, a);
}

lemma SeqContainsPrepend(head: int, tail: seq<int>, x: int)
    ensures seq_contains([head] + tail, x)
         <==> x == head || seq_contains(tail, x)
{
    if seq_contains([head] + tail, x) {
        var i :| 0 <= i < |[head] + tail| &&
                  ([head] + tail)[i] == x;
        if i == 0 {
            assert x == head;
        } else {
            assert 0 <= i - 1 < |tail|;
            assert tail[i - 1] == x;
            assert seq_contains(tail, x);
        }
    }

    if x == head {
        assert 0 < |[head] + tail|;
        assert ([head] + tail)[0] == x;
        assert seq_contains([head] + tail, x);
    } else if seq_contains(tail, x) {
        var i :| 0 <= i < |tail| && tail[i] == x;
        assert 0 <= i + 1 < |[head] + tail|;
        assert ([head] + tail)[i + 1] == x;
        assert seq_contains([head] + tail, x);
    }
}

lemma ComponentMembership(g: seq<seq<int>>,
                          representative: int, k: int, x: int)
    requires 0 <= representative < |g|
    requires 0 <= k <= |g|
    ensures seq_contains(component(g, representative, k), x)
         <==> k <= x < |g| &&
               equivalent(g, representative, x)
    decreases |g| - k
{
    if k == |g| {
        assert component(g, representative, k) == [];
        assert !seq_contains(component(g, representative, k), x);
        assert !(k <= x < |g|);
    } else {
        var tail := component(g, representative, k + 1);
        ComponentMembership(g, representative, k + 1, x);
        assert seq_contains(tail, x)
            <==> k + 1 <= x < |g| &&
                  equivalent(g, representative, x);

        if equivalent(g, representative, k) {
            assert component(g, representative, k) == [k] + tail;
            SeqContainsPrepend(k, tail, x);

            if seq_contains(component(g, representative, k), x) {
                assert x == k || seq_contains(tail, x);
                if x == k {
                    assert k <= x < |g|;
                    assert equivalent(g, representative, x);
                } else {
                    assert k + 1 <= x < |g|;
                    assert equivalent(g, representative, x);
                    assert k <= x < |g|;
                }
            }

            if k <= x < |g| &&
               equivalent(g, representative, x)
            {
                if x == k {
                    assert x == k || seq_contains(tail, x);
                } else {
                    assert k + 1 <= x < |g|;
                    assert seq_contains(tail, x);
                    assert x == k || seq_contains(tail, x);
                }
                assert seq_contains([k] + tail, x);
                assert seq_contains(component(g, representative, k), x);
            }
        } else {
            assert component(g, representative, k) == tail;

            if seq_contains(component(g, representative, k), x) {
                assert seq_contains(tail, x);
                assert k + 1 <= x < |g|;
                assert equivalent(g, representative, x);
                assert k <= x < |g|;
            }

            if k <= x < |g| &&
               equivalent(g, representative, x)
            {
                assert x != k;
                assert k + 1 <= x < |g|;
                assert seq_contains(tail, x);
                assert seq_contains(component(g, representative, k), x);
            }
        }
    }
}

lemma RepresentativeExists(g: seq<seq<int>>, u: int)
    requires wf_view(g)
    requires 0 <= u < |g|
    ensures exists r: int ::
        0 <= r <= u &&
        is_representative(g, r) &&
        equivalent(g, r, u)
    decreases u
{
    EquivalentReflexive(g, u);

    if is_representative(g, u) {
    } else {
        assert exists v: int ::
            0 <= v < u && equivalent(g, v, u);

        var v :| 0 <= v < u && equivalent(g, v, u);
        RepresentativeExists(g, v);

        var r :| 0 <= r <= v &&
                  is_representative(g, r) &&
                  equivalent(g, r, v);

        EquivalentTransitive(g, r, v, u);
    }
}

lemma ComponentsContainRepresentative(g: seq<seq<int>>, k: int, r: int)
    requires 0 <= k <= r < |g|
    requires is_representative(g, r)
    ensures exists i: int ::
        0 <= i < |all_components(g, k)| &&
        all_components(g, k)[i] == component(g, r, 0)
    decreases |g| - k
{
    if k < r {
        ComponentsContainRepresentative(g, k + 1, r);

        var i :| 0 <= i < |all_components(g, k + 1)| &&
                  all_components(g, k + 1)[i] ==
                    component(g, r, 0);

        if is_representative(g, k) {
            assert all_components(g, k) ==
                [component(g, k, 0)] + all_components(g, k + 1);
            assert 0 <= i + 1 < |all_components(g, k)|;
            assert all_components(g, k)[i + 1] ==
                component(g, r, 0);
        } else {
            assert all_components(g, k) == all_components(g, k + 1);
        }
    } else {
        assert k == r;
        assert is_representative(g, k);
        assert all_components(g, k) ==
            [component(g, k, 0)] + all_components(g, k + 1);
        assert 0 < |all_components(g, k)|;
        assert all_components(g, k)[0] == component(g, r, 0);
    }
}

lemma ComponentIndexRepresentative(g: seq<seq<int>>, k: int, i: int)
    requires 0 <= k <= |g|
    requires 0 <= i < |all_components(g, k)|
    ensures exists r: int ::
        k <= r < |g| &&
        is_representative(g, r) &&
        all_components(g, k)[i] == component(g, r, 0)
    decreases |g| - k
{
    if is_representative(g, k) {
        if i == 0 {
        } else {
            ComponentIndexRepresentative(g, k + 1, i - 1);
        }
    } else {
        ComponentIndexRepresentative(g, k + 1, i);
    }
}

lemma ComponentIndexPair(g: seq<seq<int>>, k: int, i: int, j: int)
    requires 0 <= k <= |g|
    requires 0 <= i < |all_components(g, k)|
    requires 0 <= j < |all_components(g, k)|
    ensures exists r: int, t: int ::
        k <= r < |g| &&
        k <= t < |g| &&
        is_representative(g, r) &&
        is_representative(g, t) &&
        all_components(g, k)[i] == component(g, r, 0) &&
        all_components(g, k)[j] == component(g, t, 0) &&
        (i < j ==> r < t) &&
        (j < i ==> t < r) &&
        (i == j ==> r == t)
    decreases |g| - k
{
    if is_representative(g, k) {
        if i == 0 {
            if j == 0 {
            } else {
                ComponentIndexRepresentative(g, k + 1, j - 1);
                var t :| k + 1 <= t < |g| &&
                          is_representative(g, t) &&
                          all_components(g, k + 1)[j - 1] ==
                            component(g, t, 0);
            }
        } else if j == 0 {
            ComponentIndexRepresentative(g, k + 1, i - 1);
            var r :| k + 1 <= r < |g| &&
                      is_representative(g, r) &&
                      all_components(g, k + 1)[i - 1] ==
                        component(g, r, 0);
        } else {
            ComponentIndexPair(g, k + 1, i - 1, j - 1);
        }
    } else {
        ComponentIndexPair(g, k + 1, i, j);
    }
}

lemma DistinctRepresentativesNotEquivalent(
    g: seq<seq<int>>, r: int, t: int)
    requires 0 <= r < |g|
    requires 0 <= t < |g|
    requires is_representative(g, r)
    requires is_representative(g, t)
    requires r != t
    ensures !equivalent(g, r, t)
{
    if r < t {
        if equivalent(g, r, t) {
            assert false;
        }
    } else {
        if equivalent(g, r, t) {
            EquivalentSymmetric(g, r, t);
            assert false;
        }
    }
}

lemma ComponentStrong(g: seq<seq<int>>, r: int)
    requires wf_view(g)
    requires 0 <= r < |g|
    ensures is_strongly_connected(g, component(g, r, 0))
{
    EquivalentReflexive(g, r);
    ComponentMembership(g, r, 0, r);

    assert |component(g, r, 0)| > 0;

    forall i | 0 <= i < |component(g, r, 0)|
        ensures 0 <= component(g, r, 0)[i] < |g|
    {
        var x := component(g, r, 0)[i];
        assert seq_contains(component(g, r, 0), x);
        ComponentMembership(g, r, 0, x);
    }

    forall u, v |
        seq_contains(component(g, r, 0), u) &&
        seq_contains(component(g, r, 0), v)
        ensures has_path(g, u, v) && has_path(g, v, u)
    {
        ComponentMembership(g, r, 0, u);
        ComponentMembership(g, r, 0, v);

        EquivalentSymmetric(g, r, u);
        EquivalentTransitive(g, u, r, v);

        ReachGivesPath(g, u, v, |g|);
        ReachGivesPath(g, v, u, |g|);
    }
}

lemma ComponentsAreDisjoint(g: seq<seq<int>>)
    requires wf_view(g)
    ensures are_disjoint(all_components(g, 0))
{
    forall i, j, u |
        0 <= i < |all_components(g, 0)| &&
        0 <= j < |all_components(g, 0)| &&
        i != j
        ensures
        !(seq_contains(all_components(g, 0)[i], u) &&
          seq_contains(all_components(g, 0)[j], u))
    {
        ComponentIndexPair(g, 0, i, j);

        var r, t :| 0 <= r < |g| &&
                       0 <= t < |g| &&
                       is_representative(g, r) &&
                       is_representative(g, t) &&
                       all_components(g, 0)[i] ==
                         component(g, r, 0) &&
                       all_components(g, 0)[j] ==
                         component(g, t, 0) &&
                       (i < j ==> r < t) &&
                       (j < i ==> t < r) &&
                       (i == j ==> r == t);

        assert r != t;
        DistinctRepresentativesNotEquivalent(g, r, t);

        if seq_contains(all_components(g, 0)[i], u) &&
           seq_contains(all_components(g, 0)[j], u)
        {
            ComponentMembership(g, r, 0, u);
            ComponentMembership(g, t, 0, u);
            EquivalentSymmetric(g, t, u);
            EquivalentTransitive(g, r, u, t);
            assert false;
        }
    }
}

lemma ComponentsCover(g: seq<seq<int>>)
    requires wf_view(g)
    ensures forall u: int ::
        0 <= u < |g| ==> is_covered(all_components(g, 0), u)
{
    forall u | 0 <= u < |g|
        ensures is_covered(all_components(g, 0), u)
    {
        RepresentativeExists(g, u);
        var r :| 0 <= r <= u &&
                  is_representative(g, r) &&
                  equivalent(g, r, u);

        ComponentsContainRepresentative(g, 0, r);
        var i :| 0 <= i < |all_components(g, 0)| &&
                  all_components(g, 0)[i] == component(g, r, 0);

        ComponentMembership(g, r, 0, u);
    }
}

lemma PathBetweenRepresentatives(
    g: seq<seq<int>>, r: int, t: int, u: int, v: int)
    requires wf_view(g)
    requires 0 <= r < |g|
    requires 0 <= t < |g|
    requires seq_contains(component(g, r, 0), u)
    requires seq_contains(component(g, t, 0), v)
    requires has_path(g, u, v)
    ensures has_path(g, r, t)
{
    ComponentMembership(g, r, 0, u);
    ComponentMembership(g, t, 0, v);

    ReachGivesPath(g, r, u, |g|);
    ReachGivesPath(g, v, t, |g|);

    HasPathTransitive(g, r, u, v);
    HasPathTransitive(g, r, v, t);
}

lemma ComponentsMaximal(g: seq<seq<int>>)
    requires wf_view(g)
    ensures is_maximal_scc_structure(g, all_components(g, 0))
{
    forall i, j |
        0 <= i < |all_components(g, 0)| &&
        0 <= j < |all_components(g, 0)| &&
        i != j
        ensures
        scc_has_path(g, all_components(g, 0), i, j) ==>
        !scc_has_path(g, all_components(g, 0), j, i)
    {
        ComponentIndexPair(g, 0, i, j);

        var r, t :| 0 <= r < |g| &&
                       0 <= t < |g| &&
                       is_representative(g, r) &&
                       is_representative(g, t) &&
                       all_components(g, 0)[i] ==
                         component(g, r, 0) &&
                       all_components(g, 0)[j] ==
                         component(g, t, 0) &&
                       (i < j ==> r < t) &&
                       (j < i ==> t < r) &&
                       (i == j ==> r == t);

        assert r != t;
        DistinctRepresentativesNotEquivalent(g, r, t);

