            }
            if l <= k < r {
                assert k == l;
            }
        }

        forall k | l <= k < r
            ensures k in res.view() && res.view()[k] == 0
        {
            assert k == l;
        }

        forall k | k in res.view()
            ensures res.view()[k] <= res.val
        {
            assert k == l;
        }

        assert res.is_segment_tree();
    } else {
        assert l + 2 <= r;
        midpoint_bounds(l, r);
        var mid := (l + r) / 2;
        assert l < mid < r;

