lemma ViewDom(n: Node)
    requires n.is_segment_tree()
    ensures forall k :: k in n.view() <==> n.low <= k < n.high
    ensures forall k :: k in n.view() ==> n.view()[k] <= n.val
{
}

method query(node: Node, ql: int, qr: int) returns (res: int)
    requires node.is_segment_tree()
    requires ql < qr
    requires node.low <= ql
    requires qr <= node.high
    ensures res >= 0
    // Correctness: result is >= everything in the query range
    ensures forall k :: ql <= k < qr ==> node.view()[k] <= res
    // Tightness: result actually exists in the query range
    ensures exists k :: ql <= k < qr && node.view()[k] == res
    decreases node
{
    ViewDom(node);
    match (node.left, node.right) {
        case (Some(l), Some(r)) =>
            var mid := (node.low + node.high) / 2;
            assert l.is_segment_tree() && r.is_segment_tree();
            assert l.low == node.low && l.high == mid && r.low == mid && r.high == node.high;
            ViewDom(l);
            ViewDom(r);
            assert node.view() == l.view() + r.view();
            assert forall k :: node.low <= k < mid ==> k in node.view() && k in l.view() && node.view()[k] == l.view()[k];
            assert forall k :: mid <= k < node.high ==> k in node.view() && k in r.view() && node.view()[k] == r.view()[k];
            if qr <= mid {
                res := query(l, ql, qr);
                var w :| ql <= w < qr && l.view()[w] == res;
                assert node.view()[w] == res;
            } else if ql >= mid {
                res := query(r, ql, qr);
                var w :| ql <= w < qr && r.view()[w] == res;
                assert node.view()[w] == res;
            } else {
                var a := query(l, ql, mid);
                var b := query(r, mid, qr);
                var wa :| ql <= wa < mid && l.view()[wa] == a;
                var wb :| mid <= wb < qr && r.view()[wb] == b;
                assert node.view()[wa] == a;
                assert node.view()[wb] == b;
                if a >= b {
                    res := a;
                } else {
                    res := b;
                }
            }
        case _ =>
            assert node.left.None? && node.right.None?;
            assert node.high == node.low + 1;
            assert node.view() == map[node.low := node.val];
            assert ql == node.low && qr == node.low + 1;
            res := node.val;
            assert node.view()[ql] == res;
    }
}

