lemma child_views(node: Node, l: Node, r: Node)
    requires node.is_segment_tree()
    requires node.left == Some(l)
    requires node.right == Some(r)
    ensures forall k :: l.low <= k < l.high ==>
        node.view()[k] == l.view()[k]
    ensures forall k :: r.low <= k < r.high ==>
        node.view()[k] == r.view()[k]
{
    assert l.is_segment_tree();
    assert r.is_segment_tree();
    assert l.high == r.low;
    assert node.view() == l.view() + r.view();

    forall k | l.low <= k < l.high
        ensures node.view()[k] == l.view()[k]
    {
        assert k in l.view();
        assert k !in r.view();
        assert k in (l.view() + r.view());
        assert (l.view() + r.view())[k] == l.view()[k];
    }

    forall k | r.low <= k < r.high
        ensures node.view()[k] == r.view()[k]
    {
        assert k in r.view();
        assert k in (l.view() + r.view());
        assert (l.view() + r.view())[k] == r.view()[k];
    }
}

