    // Tightness: result actually exists in the query range
    ensures exists k :: ql <= k < qr && node.view()[k] == res
    decreases node
{
    assert (node.left.None? && node.right.None?) ||
           (node.left.Some? && node.right.Some?);

    if node.left.None? {
        assert node.right.None?;
        assert node.high == node.low + 1;
        assert ql == node.low;
        assert qr == node.high;
        assert node.view() == map[node.low := node.val];

        res := node.val;

        assert res >= 0;
        assert node.low in node.view();
        assert node.view()[node.low] == res;

        forall k | ql <= k < qr
            ensures node.view()[k] <= res
        {
            assert k == node.low;
            assert node.view()[k] == res;
        }

        assert ql <= node.low < qr;
        assert exists k :: ql <= k < qr && node.view()[k] == res;
