lemma MulMono(a: int, b: int, p: int)
  requires a <= b && p >= 0
  ensures a * p <= b * p
  decreases b - a
{
  if a < b {
    MulMono(a, b - 1, p);
    assert b * p == (b - 1) * p + p;
  }
}

lemma ModMultiple(k: int, p: int)
  requires p > 0
  ensures (k * p) % p == 0
{
  var x := k * p;
  var q := x / p;
  var r := x % p;
  assert x == q * p + r;
  assert 0 <= r < p;
  if q < k {
    MulMono(q + 1, k, p);
    assert (q + 1) * p == q * p + p;
    assert false;
  } else if q > k {
    MulMono(k + 1, q, p);
    assert (k + 1) * p == k * p + p;
    assert false;
  }
  assert q == k;
  assert r == 0;
}

lemma NotMultipleBetween(k: int, p: int, i: int)
  requires p > 0
  requires k * p < i < k * p + p
  ensures i % p != 0
{
  var q := i / p;
  var r := i % p;
  assert i == q * p + r;
  if r == 0 {
    if q <= k {
      MulMono(q, k, p);
      assert false;
    } else {
      MulMono(k + 1, q, p);
      assert (k + 1) * p == k * p + p;
      assert false;
    }
  }
}

