method splay(tree: Tree, v: int) returns (res: Tree)
    // tree is Box<Node>, so it cannot be Empty
    requires tree.Node?
    requires is_bst(tree)
    // res is Box<Node>, so it cannot be Empty
    ensures res.Node?
    ensures is_bst(res)
    ensures view(res) == view(tree)
    // Postcondition: If v was in the tree, it is now at the root.
    ensures v in view(tree) ==> res.val == v
    // Postcondition: If v was NOT in the tree, the new root is 
    // the last node accessed (implicitly true if res.Node?, but kept for fidelity)
    ensures v !in view(tree) ==> res.val in view(res)
    decreases tree
{
    if v == tree.val {
        res := tree;
    } else if v < tree.val {
        if tree.left.Empty? {
            res := tree;
            assert view(res) == view(tree.left) + view(tree.right) + {tree.val};
        } else {
            assert is_bst(tree.left);
            var l := splay(tree.left, v);
            assert view(l) == view(l.left) + view(l.right) + {l.val};
            assert is_bst(l.left) && is_bst(l.right);
            assert l.val in view(tree.left);
            assert l.val < tree.val;
            assert forall x :: x in view(l.right) ==> x in view(tree.left);
            assert forall x :: x in view(l.right) ==> x < tree.val;
            assert forall x :: x in view(l.right) ==> x > l.val;
            assert forall x :: x in view(l.left) ==> x < l.val;
            var r := Node(tree.val, l.right, tree.right);
            assert is_bst(r);
            assert view(r) == view(l.right) + view(tree.right) + {tree.val};
            assert forall x :: x in view(r) ==> x > l.val;
            res := Node(l.val, l.left, r);
            assert is_bst(res);
