lemma RotateRightPreserves(x: int, y: int, a: Tree, b: Tree, c: Tree)
    requires is_bst(Node(x, Node(y, a, b), c))
    ensures is_bst(Node(y, a, Node(x, b, c)))
    ensures view(Node(y, a, Node(x, b, c))) ==
            view(Node(x, Node(y, a, b), c))
{
    assert is_bst(Node(y, a, b));
    assert is_bst(a);
    assert is_bst(b);
    assert is_bst(c);

    assert y in view(Node(y, a, b));
    assert y < x;

    forall z | z in view(b)
        ensures z < x
    {
        assert z in view(Node(y, a, b));
    }

    assert is_bst(Node(x, b, c));

    forall z | z in view(Node(x, b, c))
        ensures z > y
    {
        assert z in view(b) || z in view(c) || z == x;
        if z in view(b) {
            assert z > y;
        } else if z in view(c) {
            assert z > x;
        } else {
            assert z == x;
        }
    }

    assert is_bst(Node(y, a, Node(x, b, c)));

    calc {
        view(Node(y, a, Node(x, b, c)));
        == view(a) + view(b) + view(c) + {x} + {y};
        == view(Node(x, Node(y, a, b), c));
    }
}

