                    assert s in previous.view();
                    assert
                        previous.well_formed()
                        && !previous.is_empty()
                        && (forall t | t in previous.view()
                            :: |t| > 0 && t[0] > n.val);
                case None =>
                    assert s in iset{};
                    assert false;
            }
        }
    }

    assert Node(n.val, n.is_end, n.left, n.mid, Some(child)).well_formed();
}

lemma middle_well_formed(n: Node, child: Node)
    requires n.well_formed()
    requires child.well_formed()
    requires !child.is_empty()
    ensures Node(n.val, n.is_end, n.left, Some(child), n.right).well_formed()
{
    assert Node(n.val, n.is_end, n.left, Some(child), n.right).well_formed();
}

lemma endpoint_well_formed(n: Node)
    requires n.well_formed()
    ensures Node(n.val, true, n.left, n.mid, n.right).well_formed()
{
    assert Node(n.val, true, n.left, n.mid, n.right).well_formed();
}

method insert(tree: Option<Node>, key: seq<int>) returns (res: Node)
    requires opt_well_formed(tree)
    requires forall k :: k in key ==> 0 <= k < 256
    requires |key| > 0
    ensures
        && res.well_formed()
        && !res.is_empty()
        && res.view() == opt_view(tree) + iset{key}
    decreases |key|, tree
{
    var c := key[0];
    assert 0 <= 0 < |key|;
    assert key[0] in key;
    assert c in key;
    assert 0 <= c < 256;

    match tree {
        case None =>
            var base := Node(c, false, None, None, None);
            assert base.well_formed();
            empty_node_view(c);
            assert base.view() == iset{};

            if |key| == 1 {
                assert key == [key[0]];
                assert key == [c];

                res := Node(c, true, None, None, None);
                endpoint_well_formed(base);
                endpoint_view_update(base);

                assert res.well_formed();
                assert !res.is_empty();
                assert res.view() == iset{key};
                assert opt_view(tree) == iset{};
            } else {
                assert |key[1..]| > 0;
                tail_preserves_byte_constraint(key);
                assert forall k :: k in key[1..] ==> 0 <= k < 256;

                var child := insert(None, key[1..]);

                assert child.well_formed();
                assert !child.is_empty();
                assert child.view()
                    == opt_view(None) + iset{key[1..]};

                res := Node(c, false, None, Some(child), None);

                middle_well_formed(base, child);
                middle_view_update(base, child, key);

                assert res.well_formed();
                assert !res.is_empty();
                assert res.view() == iset{key};
                assert opt_view(tree) == iset{};
            }

        case Some(n) =>
            assert n.well_formed();
            assert !n.is_empty();

            if c < n.val {
                var child := insert(n.left, key);

                left_well_formed(n, child, key);
                left_view_update(n, child, key);

                res := Node(
                    n.val,
                    n.is_end,
                    Some(child),
                    n.mid,
                    n.right
                );

                assert res.well_formed();
                assert !res.is_empty();
                assert res.view() == n.view() + iset{key};
                assert opt_view(tree) == n.view();
            } else if c > n.val {
                var child := insert(n.right, key);

                right_well_formed(n, child, key);
                right_view_update(n, child, key);

                res := Node(
                    n.val,
                    n.is_end,
                    n.left,
                    n.mid,
                    Some(child)
                );

                assert res.well_formed();
                assert !res.is_empty();
                assert res.view() == n.view() + iset{key};
                assert opt_view(tree) == n.view();
            } else if |key| == 1 {
                assert key == [key[0]];
                assert key == [n.val];

                res := Node(
                    n.val,
                    true,
                    n.left,
                    n.mid,
                    n.right
                );

                endpoint_well_formed(n);
                endpoint_view_update(n);

                assert res.well_formed();
                assert !res.is_empty();
                assert res.view() == n.view() + iset{key};
                assert opt_view(tree) == n.view();
            } else {
                assert |key[1..]| > 0;
                tail_preserves_byte_constraint(key);
                assert forall k :: k in key[1..] ==> 0 <= k < 256;

                var child := insert(n.mid, key[1..]);

                middle_well_formed(n, child);
                middle_view_update(n, child, key);

                res := Node(
                    n.val,
                    n.is_end,
                    n.left,
                    Some(child),
                    n.right
                );

                assert res.well_formed();
                assert !res.is_empty();
                assert res.view() == n.view() + iset{key};
                assert opt_view(tree) == n.view();
            }
    }
}
