ghost function Range(n: int): set<int>
{
  set u: int | 0 <= u < n
}

lemma RangeCard(n: nat)
  ensures |Range(n)| == n
{
  if n > 0 {
    RangeCard(n - 1);
    assert Range(n - 1) * {n - 1} == {};
    assert Range(n) == Range(n - 1) + {n - 1};
  }
}

lemma RemoveOneCard(A: set<int>, x: int)
  requires x in A
  ensures |A - {x}| == |A| - 1
{
  assert A * {x} == {x};
  assert (A - {x}) + {x} == A;
}

ghost function Elems(p: seq<int>): set<int>
{
  set x | x in p
}

ghost function IndexOf(s: seq<int>, x: int): int
  requires x in s
  ensures 0 <= IndexOf(s, x) < |s| && s[IndexOf(s, x)] == x
  decreases |s|
{
  if s[0] == x then 0 else 1 + IndexOf(s[1..], x)
}

lemma FindCycle(g: Graph, R: set<int>, p: seq<int>)
  requires is_path(g, p)
  requires forall i :: 0 <= i < |p| ==> p[i] in R
  requires forall v :: v in R ==> exists x :: x in R && has_edge(g, x, v)
  ensures graph_has_cycle(g)
  decreases |R - Elems(p)|
{
  assert p[0] in R;
  var x :| x in R && has_edge(g, x, p[0]);
  if x in p {
    var k :| 0 <= k < |p| && p[k] == x;
    var c := [x] + p[..k+1];
    assert |c| == k + 2;
    forall i | 0 <= i < |c| - 1 ensures has_edge(g, c[i], c[i+1]) {
      if i == 0 {
        assert c[0] == x && c[1] == p[0];
      } else {
        var j := i - 1;
        assert 0 <= j < |p| - 1;
        assert has_edge(g, p[j], p[j+1]);
        assert c[i] == p[j] && c[i+1] == p[j+1];
      }
    }
    assert is_path(g, c);
    assert c[|c|-1] == p[k];
    assert is_cycle(g, c);
  } else {
    var q := [x] + p;
    forall i | 0 <= i < |q| - 1 ensures has_edge(g, q[i], q[i+1]) {
      if i == 0 {
        assert q[0] == x && q[1] == p[0];
      } else {
        var j := i - 1;
        assert 0 <= j < |p| - 1;
        assert has_edge(g, p[j], p[j+1]);
        assert q[i] == p[j] && q[i+1] == p[j+1];
      }
    }
    assert is_path(g, q);
    forall i | 0 <= i < |q| ensures q[i] in R {
      if i > 0 { assert q[i] == p[i-1]; }
    }
    assert x !in Elems(p);
    assert x in R - Elems(p);
    RemoveOneCard(R - Elems(p), x);
    assert Elems(q) == Elems(p) + {x};
    assert R - Elems(q) == (R - Elems(p)) - {x};
    FindCycle(g, R, q);
  }
}

lemma AcyclicFromOrder(g: Graph, order: seq<int>)
  requires forall x :: 0 <= x < |g.adj| ==> x in order
  requires forall i, j :: 0 <= j <= i < |order| ==> !has_edge(g, order[i], order[j])
  ensures !graph_has_cycle(g)
{
  if graph_has_cycle(g) {
    var p :| is_cycle(g, p);
    forall k | 0 <= k < |p| ensures p[k] in order {
      if k < |p| - 1 {
        assert has_edge(g, p[k], p[k+1]);
      } else {
        assert has_edge(g, p[0], p[1]);
        assert p[k] == p[0];
      }
    }
    var k := 0;
    while k < |p| - 1
      invariant 0 <= k <= |p| - 1
      invariant forall k' :: 0 <= k' < |p| ==> p[k'] in order
      invariant IndexOf(order, p[0]) + k <= IndexOf(order, p[k])
    {
      var a := IndexOf(order, p[k]);
      var b := IndexOf(order, p[k+1]);
      assert has_edge(g, p[k], p[k+1]);
      if b <= a {
        assert !has_edge(g, order[a], order[b]);
        assert false;
      }
      k := k + 1;
    }
    assert p[|p|-1] == p[0];
    assert false;
  }
}

method IsSource(graph: Graph, placed: seq<bool>, v: int) returns (b: bool)
  requires well_formed(graph)
  requires |placed| == |graph.adj|
  ensures b <==> (forall x :: 0 <= x < |graph.adj| && !placed[x] ==> !has_edge(graph, x, v))
{
  var x := 0;
  while x < |graph.adj|
    invariant 0 <= x <= |graph.adj|
    invariant forall y :: 0 <= y < x && !placed[y] ==> !has_edge(graph, y, v)
  {
    if !placed[x] {
      var k := 0;
      while k < |graph.adj[x]|
        invariant 0 <= k <= |graph.adj[x]|
        invariant forall k' :: 0 <= k' < k ==> graph.adj[x][k'] != v
      {
        if graph.adj[x][k] == v {
          assert has_edge(graph, x, v);
          return false;
        }
        k := k + 1;
      }
      assert !has_edge(graph, x, v);
    }
    x := x + 1;
  }
  return true;
}

method FindSource(graph: Graph, placed: seq<bool>) returns (found: bool, v: int)
  requires well_formed(graph)
  requires |placed| == |graph.adj|
  ensures found ==> 0 <= v < |graph.adj| && !placed[v]
                    && (forall x :: 0 <= x < |graph.adj| && !placed[x] ==> !has_edge(graph, x, v))
  ensures !found ==> forall u :: 0 <= u < |graph.adj| && !placed[u] ==>
                      exists x :: 0 <= x < |graph.adj| && !placed[x] && has_edge(graph, x, u)
{
  var u := 0;
  while u < |graph.adj|
    invariant 0 <= u <= |graph.adj|
    invariant forall w :: 0 <= w < u && !placed[w] ==>
                exists x :: 0 <= x < |graph.adj| && !placed[x] && has_edge(graph, x, w)
  {
    if !placed[u] {
      var b := IsSource(graph, placed, u);
      if b {
        return true, u;
      }
    }
    u := u + 1;
  }
  return false, 0;
}

method FindUnplaced(placed: seq<bool>) returns (u: int)
  ensures u >= 0 ==> u < |placed| && !placed[u]
  ensures u < 0 ==> forall w :: 0 <= w < |placed| ==> placed[w]
{
  var i := 0;
  while i < |placed|
    invariant 0 <= i <= |placed|
    invariant forall w :: 0 <= w < i ==> placed[w]
  {
    if !placed[i] {
      return i;
    }
    i := i + 1;
  }
  return -1;
}

method topological_sort(graph: Graph) returns (res: Option<seq<int>>)
  requires well_formed(graph)
  ensures match res {
    case Some(order) => 
      // 1. The graph must be acyclic
      !graph_has_cycle(graph) 
      // 2. The returned vector is a valid ordering
      && is_topological_ordering(graph, order)
    case None => 
      // Must contain a cycle if sort is impossible
      graph_has_cycle(graph)
  }
{
  var n := |graph.adj|;
  var order: seq<int> := [];
  var placed := seq(n, _ => false);
  ghost var S: set<int> := {};
  ghost var Full := Range(n);
  RangeCard(n);
  while true
    invariant |placed| == n
    invariant |Full| == n
    invariant forall u :: u in Full <==> 0 <= u < n
    invariant forall u :: 0 <= u < n ==> (placed[u] <==> u in S)
    invariant forall u :: u in S <==> u in order
    invariant forall i :: 0 <= i < |order| ==> 0 <= order[i] < n
    invariant forall i, j :: 0 <= i < j < |order| ==> order[i] != order[j]
    invariant |S| == |order|
    invariant S <= Full
    invariant forall i, j :: 0 <= j <= i < |order| ==> !has_edge(graph, order[i], order[j])
    invariant forall j, x :: 0 <= j < |order| && 0 <= x < n && !placed[x] ==> !has_edge(graph, x, order[j])
    decreases |Full - S|
  {
    var u0 := FindUnplaced(placed);
    if u0 < 0 {
      break;
