  assert (A - {x}) + {x} == A;
}

ghost function Elems(p: seq<int>): set<int>
{
  set x | x in p
}

ghost function IndexOf(s: seq<int>, x: int): int
  requires x in s
  ensures 0 <= IndexOf(s, x) < |s| && s[IndexOf(s, x)] == x
  decreases |s|
{
  if s[0] == x then 0 else 1 + IndexOf(s[1..], x)
}

ghost predicate HasPred(g: Graph, R: set<int>, v: int)
{
  exists x :: x in R && has_edge(g, x, v)
}

ghost predicate HasUnplacedPred(g: Graph, placed: seq<bool>, u: int)
{
  exists x :: 0 <= x < |placed| && !placed[x] && has_edge(g, x, u)
}

lemma PrependPath(g: Graph, x: int, p: seq<int>)
  requires is_path(g, p)
  requires has_edge(g, x, p[0])
  ensures is_path(g, [x] + p)
{
  var q := [x] + p;
  forall i | 0 <= i < |q| - 1 ensures has_edge(g, q[i], q[i+1]) {
    if i == 0 {
      assert q[0] == x && q[1] == p[0];
    } else {
      var j := i - 1;
      assert 0 <= j < |p| - 1;
      assert has_edge(g, p[j], p[j+1]);
      assert q[i] == p[j] && q[i+1] == p[j+1];
    }
  }
}

lemma PrefixPath(g: Graph, p: seq<int>, k: int)
  requires is_path(g, p)
  requires 0 <= k < |p|
  ensures is_path(g, p[..k+1])
{
  var q := p[..k+1];
  forall i | 0 <= i < |q| - 1 ensures has_edge(g, q[i], q[i+1]) {
    assert q[i] == p[i] && q[i+1] == p[i+1];
    assert has_edge(g, p[i], p[i+1]);
  }
}

lemma FindCycle(g: Graph, R: set<int>, p: seq<int>)
  requires is_path(g, p)
  requires forall i :: 0 <= i < |p| ==> p[i] in R
  requires forall v {:trigger HasPred(g, R, v)} :: v in R ==> HasPred(g, R, v)
  ensures graph_has_cycle(g)
  decreases |R - Elems(p)|
{
  assert p[0] in R;
  assert HasPred(g, R, p[0]);
  var x :| x in R && has_edge(g, x, p[0]);
  if x in p {
    var k := IndexOf(p, x);
    PrefixPath(g, p, k);
    var pre := p[..k+1];
    assert pre[0] == p[0];
    PrependPath(g, x, pre);
    var c := [x] + pre;
    assert |c| == k + 2;
    assert c[0] == x;
    assert c[|c|-1] == pre[k] == p[k];
    assert is_cycle(g, c);
  } else {
    var q := [x] + p;
    PrependPath(g, x, p);
    forall i | 0 <= i < |q| ensures q[i] in R {
      if i > 0 { assert q[i] == p[i-1]; }
    }
    assert x !in Elems(p);
    assert x in R - Elems(p);
    RemoveOneCard(R - Elems(p), x);
    assert Elems(q) == Elems(p) + {x};
    assert R - Elems(q) == (R - Elems(p)) - {x};
    FindCycle(g, R, q);
  }
}

lemma AcyclicFromOrder(g: Graph, order: seq<int>)
  requires forall x :: 0 <= x < |g.adj| ==> x in order
  requires forall i, j :: 0 <= j <= i < |order| ==> !has_edge(g, order[i], order[j])
  ensures !graph_has_cycle(g)
{
  if graph_has_cycle(g) {
    var p :| is_cycle(g, p);
    forall k | 0 <= k < |p| ensures p[k] in order {
      if k < |p| - 1 {
        assert has_edge(g, p[k], p[k+1]);
      } else {
        assert has_edge(g, p[0], p[1]);
        assert p[k] == p[0];
      }
    }
    var k := 0;
    while k < |p| - 1
      invariant 0 <= k <= |p| - 1
      invariant forall k' :: 0 <= k' < |p| ==> p[k'] in order
      invariant IndexOf(order, p[0]) + k <= IndexOf(order, p[k])
    {
      var a := IndexOf(order, p[k]);
      var b := IndexOf(order, p[k+1]);
      assert has_edge(g, p[k], p[k+1]);
      if b <= a {
        assert !has_edge(g, order[a], order[b]);
        assert false;
      }
      k := k + 1;
    }
    assert p[|p|-1] == p[0];
    assert false;
  }
}

method IsSource(graph: Graph, placed: seq<bool>, v: int) returns (b: bool)
  requires well_formed(graph)
  requires |placed| == |graph.adj|
  ensures b <==> !HasUnplacedPred(graph, placed, v)
{
  var x := 0;
  while x < |graph.adj|
    invariant 0 <= x <= |graph.adj|
    invariant forall y :: 0 <= y < x && !placed[y] ==> !has_edge(graph, y, v)
  {
    if !placed[x] {
      var k := 0;
      while k < |graph.adj[x]|
        invariant 0 <= k <= |graph.adj[x]|
        invariant forall k' :: 0 <= k' < k ==> graph.adj[x][k'] != v
      {
        if graph.adj[x][k] == v {
          assert has_edge(graph, x, v);
          assert 0 <= x < |placed| && !placed[x];
          assert HasUnplacedPred(graph, placed, v);
          return false;
        }
        k := k + 1;
      }
      assert !has_edge(graph, x, v);
    }
    x := x + 1;
  }
  return true;
}

method FindSource(graph: Graph, placed: seq<bool>) returns (found: bool, v: int)
  requires well_formed(graph)
  requires |placed| == |graph.adj|
  ensures found ==> 0 <= v < |graph.adj| && !placed[v]
                    && !HasUnplacedPred(graph, placed, v)
  ensures !found ==> forall u {:trigger HasUnplacedPred(graph, placed, u)} ::
                      0 <= u < |graph.adj| && !placed[u] ==> HasUnplacedPred(graph, placed, u)
{
  var u := 0;
  while u < |graph.adj|
    invariant 0 <= u <= |graph.adj|
    invariant forall w {:trigger HasUnplacedPred(graph, placed, w)} ::
                0 <= w < u && !placed[w] ==> HasUnplacedPred(graph, placed, w)
  {
    if !placed[u] {
      var b := IsSource(graph, placed, u);
      if b {
        return true, u;
      }
    }
    u := u + 1;
  }
  return false, 0;
}

method FindUnplaced(placed: seq<bool>) returns (u: int)
  ensures u >= 0 ==> u < |placed| && !placed[u]
  ensures u < 0 ==> forall w :: 0 <= w < |placed| ==> placed[w]
{
  var i := 0;
  while i < |placed|
    invariant 0 <= i <= |placed|
    invariant forall w :: 0 <= w < i ==> placed[w]
  {
    if !placed[i] {
      return i;
    }
    i := i + 1;
  }
  return -1;
}

method topological_sort(graph: Graph) returns (res: Option<seq<int>>)
  requires well_formed(graph)
  ensures match res {
    case Some(order) => 
      // 1. The graph must be acyclic
      !graph_has_cycle(graph) 
      // 2. The returned vector is a valid ordering
      && is_topological_ordering(graph, order)
    case None => 
      // Must contain a cycle if sort is impossible
      graph_has_cycle(graph)
  }
{
  var n := |graph.adj|;
  var order: seq<int> := [];
  var placed := seq(n, _ => false);
  ghost var S: set<int> := {};
  ghost var Full := Range(n);
  RangeCard(n);
  while true
    invariant |placed| == n
    invariant |Full| == n
    invariant forall u :: u in Full <==> 0 <= u < n
    invariant forall u :: 0 <= u < n ==> (placed[u] <==> u in S)
    invariant forall u :: u in S <==> u in order
    invariant forall i :: 0 <= i < |order| ==> 0 <= order[i] < n
    invariant forall i, j :: 0 <= i < j < |order| ==> order[i] != order[j]
    invariant |S| == |order|
    invariant S <= Full
    invariant forall i, j :: 0 <= j <= i < |order| ==> !has_edge(graph, order[i], order[j])
    invariant forall j, x :: 0 <= j < |order| && 0 <= x < n && !placed[x] ==> !has_edge(graph, x, order[j])
    decreases |Full - S|
  {
    var u0 := FindUnplaced(placed);
    if u0 < 0 {
      break;
    }
    var found, v := FindSource(graph, placed);
    if !found {
      ghost var R := set u | 0 <= u < n && !placed[u];
      forall w | w in R ensures HasPred(graph, R, w) {
        assert HasUnplacedPred(graph, placed, w);
        var x :| 0 <= x < |placed| && !placed[x] && has_edge(graph, x, w);
        assert x in R;
      }
      assert u0 in R;
      assert is_path(graph, [u0]);
      FindCycle(graph, R, [u0]);
      return None;
    }
    assert v !in S;
    assert v !in order;
    assert v in Full - S;
    RemoveOneCard(Full - S, v);
    assert Full - (S + {v}) == (Full - S) - {v};
    assert S * {v} == {};

    var newOrder := order + [v];
    forall i, j | 0 <= j <= i < |newOrder| ensures !has_edge(graph, newOrder[i], newOrder[j]) {
      if i < |order| {
        assert newOrder[i] == order[i] && newOrder[j] == order[j];
      } else if j < |order| {
        assert newOrder[i] == v && newOrder[j] == order[j];
        assert !has_edge(graph, v, order[j]);
      } else {
        assert newOrder[i] == v && newOrder[j] == v;
        assert !has_edge(graph, v, v);
      }
    }
    var newPlaced := placed[v := true];
    forall j, x | 0 <= j < |newOrder| && 0 <= x < n && !newPlaced[x]
      ensures !has_edge(graph, x, newOrder[j])
    {
      assert !placed[x];
      if j < |order| {
        assert newOrder[j] == order[j];
      } else {
        assert newOrder[j] == v;
        assert !has_edge(graph, x, v);
      }
    }
    order := newOrder;
    placed := newPlaced;
    S := S + {v};
  }
  assert forall u :: 0 <= u < n ==> u in S;
  assert S == Full;
  assert |order| == n;
  AcyclicFromOrder(graph, order);
  return Some(order);
}
