lemma EdgeIff(g: Graph, u: int, v: int)
  requires 0 <= u < |g.adj|
  ensures Edge(g, u, v) <==> has_edge(g, u, v)
{
  if Edge(g, u, v) {
    var i :| 0 <= i < |g.adj[u]| && g.adj[u][i] == v;
  }
  if has_edge(g, u, v) {
    var i :| 0 <= i < |g.adj[u]| && g.adj[u][i] == v;
    assert v in g.adj[u];
  }
}

function IncomingFrom(
    g: Graph, remaining: set<int>, v: int, first: nat): bool
  requires first <= |g.adj|
  decreases |g.adj| - first
{
  if first == |g.adj| then
    false
  else if first in remaining && Edge(g, first, v) then
    true
  else
    IncomingFrom(g, remaining, v, first + 1)
}

function Incoming(g: Graph, remaining: set<int>, v: int): bool
{
  IncomingFrom(g, remaining, v, 0)
}

lemma IncomingFromSpec(
    g: Graph, remaining: set<int>, v: int, first: nat)
  requires first <= |g.adj|
  ensures
    IncomingFrom(g, remaining, v, first)
    <==>
    (exists u: int ::
      first <= u < |g.adj| &&
      u in remaining &&
      has_edge(g, u, v))
  decreases |g.adj| - first
{
  if first < |g.adj| {
    EdgeIff(g, first, v);
    IncomingFromSpec(g, remaining, v, first + 1);
  }
}

lemma IncomingSpec(g: Graph, remaining: set<int>, v: int)
  ensures
    Incoming(g, remaining, v)
    <==>
    (exists u: int ::
      0 <= u < |g.adj| &&
      u in remaining &&
      has_edge(g, u, v))
{
  IncomingFromSpec(g, remaining, v, 0);
}

function SearchSource(
    g: Graph, remaining: set<int>, first: nat): Option<int>
  requires first <= |g.adj|
  decreases |g.adj| - first
{
  if first == |g.adj| then
    None
  else if first in remaining && !Incoming(g, remaining, first) then
    Some(first)
  else
    SearchSource(g, remaining, first + 1)
}

lemma SearchSourceSpec(
    g: Graph, remaining: set<int>, first: nat)
  requires first <= |g.adj|
  ensures
    match SearchSource(g, remaining, first)
    case Some(v) =>
      first <= v < |g.adj| &&
      v in remaining &&
      !Incoming(g, remaining, v)
    case None =>
      forall v: int ::
        first <= v < |g.adj| && v in remaining
        ==> Incoming(g, remaining, v)
  decreases |g.adj| - first
{
  if first < |g.adj| {
    if !(first in remaining && !Incoming(g, remaining, first)) {
      SearchSourceSpec(g, remaining, first + 1);
    }
  }
}

ghost function Nodes(n: nat): set<int>
{
  set i: int | 0 <= i < n
}

lemma NodesCardinality(n: nat)
  ensures |Nodes(n)| == n
{
  if n > 0 {
    NodesCardinality(n - 1);

    assert Nodes(n) == Nodes(n - 1) + {n - 1} by {
      assert forall x: int ::
        x in Nodes(n)
        <==> x in Nodes(n - 1) + {n - 1};
    }

    assert n - 1 !in Nodes(n - 1);
  }
}

ghost function SeqSet(s: seq<int>): set<int>
{
  set x: int | x in s
}

lemma SeqSetAppend(s: seq<int>, x: int)
  ensures SeqSet(s + [x]) == SeqSet(s) + {x}
{
  assert forall y: int ::
    y in SeqSet(s + [x])
    <==> y in SeqSet(s) + {x};
}

lemma DistinctSeqCardinality(s: seq<int>)
  requires forall i: int, j: int ::
    0 <= i < j < |s| ==> s[i] != s[j]
  ensures |SeqSet(s)| == |s|
  decreases |s|
{
  if |s| > 0 {
    var prefix := s[..|s| - 1];
    var last := s[|s| - 1];

    assert forall i: int, j: int ::
      0 <= i < j < |prefix| ==> prefix[i] != prefix[j];

    DistinctSeqCardinality(prefix);

    assert last !in prefix by {
      if last in prefix {
        var i :| 0 <= i < |prefix| && prefix[i] == last;
        assert s[i] == s[|s| - 1];
      }
    }

    assert last !in SeqSet(prefix);
    SeqSetAppend(prefix, last);
    assert s == prefix + [last];
  }
}

lemma DuplicateBound(s: seq<int>, n: nat)
  requires |s| > n
  requires forall i: int :: 0 <= i < |s| ==> 0 <= s[i] < n
  ensures exists i: int, j: int ::
    0 <= i < j < |s| && s[i] == s[j]
{
  if !(exists i: int, j: int ::
        0 <= i < j < |s| && s[i] == s[j]) {
    assert forall i: int, j: int ::
      0 <= i < j < |s| ==> s[i] != s[j];

    DistinctSeqCardinality(s);
    NodesCardinality(n);

    assert SeqSet(s) <= Nodes(n) by {
      forall x: int | x in SeqSet(s)
        ensures x in Nodes(n)
      {
        assert x in s;
        var i :| 0 <= i < |s| && s[i] == x;
      }
    }

    assert |SeqSet(s)| <= |Nodes(n)|;
    assert false;
  }
}

lemma PrependPath(g: Graph, u: int, p: seq<int>)
  requires is_path(g, p)
  requires has_edge(g, u, p[0])
  ensures is_path(g, [u] + p)
{
  forall i: int | 0 <= i < |[u] + p| - 1
    ensures has_edge(g, ([u] + p)[i], ([u] + p)[i + 1])
  {
    if i == 0 {
      assert ([u] + p)[0] == u;
      assert ([u] + p)[1] == p[0];
    } else {
      assert ([u] + p)[i] == p[i - 1];
      assert ([u] + p)[i + 1] == p[i];
