ghost function SeqSet(s: seq<int>): set<int>
{
  set x: int | x in s
}

lemma SeqSetAppend(s: seq<int>, x: int)
  ensures SeqSet(s + [x]) == SeqSet(s) + {x}
{
  assert forall y: int ::
    y in SeqSet(s + [x])
    <==> y in SeqSet(s) + {x};
}

lemma DistinctSeqCardinality(s: seq<int>)
  requires forall i: int, j: int ::
    0 <= i < j < |s| ==> s[i] != s[j]
  ensures |SeqSet(s)| == |s|
  decreases |s|
{
  if |s| > 0 {
    var prefix := s[..|s| - 1];
    var last := s[|s| - 1];

    assert forall i: int, j: int ::
      0 <= i < j < |prefix| ==> prefix[i] != prefix[j];

    DistinctSeqCardinality(prefix);

    assert last !in prefix by {
      if last in prefix {
        var i :| 0 <= i < |prefix| && prefix[i] == last;
        assert s[i] == s[|s| - 1];
      }
    }

    assert last !in SeqSet(prefix);
    SeqSetAppend(prefix, last);
    assert s == prefix + [last];
  }
}

lemma SetCardinalityMonotone(a: set<int>, b: set<int>)
  requires a <= b
  ensures |a| <= |b|
  decreases |a|
{
  if a != {} {
    var x :| x in a;
    assert x in b;

    assert a - {x} <= b - {x} by {
      forall y: int | y in a - {x}
        ensures y in b - {x}
      {
        assert y in a;
        assert y in b;
        assert y != x;
      }
    }

    assert |a - {x}| < |a|;
    SetCardinalityMonotone(a - {x}, b - {x});

    assert a == (a - {x}) + {x} by {
      assert forall y: int ::
        y in a <==> y in (a - {x}) + {x};
    }
    assert b == (b - {x}) + {x} by {
      assert forall y: int ::
        y in b <==> y in (b - {x}) + {x};
    }

    assert x !in a - {x};
    assert x !in b - {x};
    assert |a| == |a - {x}| + 1;
    assert |b| == |b - {x}| + 1;
  }
}

lemma {:vcs_split_on_every_assert} DuplicateBound(s: seq<int>, n: nat)
  requires |s| > n
  requires forall i: int :: 0 <= i < |s| ==> 0 <= s[i] < n
  ensures exists i: int, j: int ::
    0 <= i < j < |s| && s[i] == s[j]
{
  if !(exists i: int, j: int ::
        0 <= i < j < |s| && s[i] == s[j]) {
    assert forall i: int, j: int ::
      0 <= i < j < |s| ==> s[i] != s[j];

    DistinctSeqCardinality(s);
    NodesCardinality(n);

    assert SeqSet(s) <= Nodes(n) by {
      forall x: int | x in SeqSet(s)
        ensures x in Nodes(n)
      {
        assert x in s;
        var i :| 0 <= i < |s| && s[i] == x;
        assert 0 <= x < n;
        NodesMembership(n, x);
      }
    }

    SetCardinalityMonotone(SeqSet(s), Nodes(n));
    assert |SeqSet(s)| <= |Nodes(n)|;
    assert |s| <= n;
    assert false;
  }
}

lemma PrependPath(g: Graph, u: int, p: seq<int>)
  requires is_path(g, p)
  requires has_edge(g, u, p[0])
  ensures is_path(g, [u] + p)
{
  forall i: int | 0 <= i < |[u] + p| - 1
    ensures has_edge(g, ([u] + p)[i], ([u] + p)[i + 1])
  {
    if i == 0 {
      assert ([u] + p)[0] == u;
      assert ([u] + p)[1] == p[0];
    } else {
      assert ([u] + p)[i] == p[i - 1];
      assert ([u] + p)[i + 1] == p[i];
    }
  }
}

lemma PathSlice(g: Graph, p: seq<int>, first: int, last: int)
  requires is_path(g, p)
  requires 0 <= first < last < |p|
  ensures is_path(g, p[first..last + 1])
{
  var q := p[first..last + 1];

  forall i: int | 0 <= i < |q| - 1
    ensures has_edge(g, q[i], q[i + 1])
  {
    assert q[i] == p[first + i];
    assert q[i + 1] == p[first + i + 1];
    assert 0 <= first + i < |p| - 1;
  }
}

lemma EdgeEndpoints(g: Graph, u: int, v: int)
  requires well_formed(g)
  requires has_edge(g, u, v)
  ensures 0 <= u < |g.adj|
  ensures 0 <= v < |g.adj|
{
  var i :|
    0 <= u < |g.adj| &&
    0 <= i < |g.adj[u]| &&
    g.adj[u][i] == v;

  assert 0 <= g.adj[u][i] < |g.adj|;
}

lemma PathNodesBounded(g: Graph, p: seq<int>)
  requires well_formed(g)
  requires is_path(g, p)
  requires 0 <= p[0] < |g.adj|
  ensures forall i: int ::
    0 <= i < |p| ==> 0 <= p[i] < |g.adj|
{
  forall i: int | 0 <= i < |p|
    ensures 0 <= p[i] < |g.adj|
  {
    if i == 0 {
    } else {
      assert 0 <= i - 1 < |p| - 1;
      assert has_edge(g, p[i - 1], p[i]);
      EdgeEndpoints(g, p[i - 1], p[i]);
    }
  }
}

lemma RepeatedPathSegmentIsCycle(
    g: Graph, p: seq<int>, first: int, last: int)
  requires is_path(g, p)
  requires 0 <= first < last < |p|
  requires p[first] == p[last]
  ensures is_cycle(g, p[first..last + 1])
{
  PathSlice(g, p, first, last);
  var q := p[first..last + 1];

  assert |q| == last - first + 1;
  assert |q| > 1;
  assert q[0] == p[first];
  assert |q| - 1 == last - first;
  assert q[|q| - 1] == p[first + (|q| - 1)];
  assert first + (|q| - 1) == last;
  assert q[|q| - 1] == p[last];
  assert q[0] == q[|q| - 1];
}

lemma RemainingContainsCycle(
    g: Graph, remaining: set<int>)
  requires well_formed(g)
  requires remaining != {}
  requires forall x: int ::
    x in remaining ==> 0 <= x < |g.adj|
  requires forall v: int ::
    v in remaining ==>
      exists u: int :: u in remaining && has_edge(g, u, v)
  ensures graph_has_cycle(g)
{
  var start :| start in remaining;
  var p := [start];
  var k: nat := 0;

  assert 0 <= start < |g.adj|;
  assert is_path(g, p);
  assert p[0] in remaining;

  while k < |g.adj|
    invariant 0 <= k <= |g.adj|
    invariant |p| == k + 1
    invariant is_path(g, p)
    invariant p[0] in remaining
    decreases |g.adj| - k
  {
    var u :| u in remaining && has_edge(g, u, p[0]);
    PrependPath(g, u, p);
    p := [u] + p;
    k := k + 1;
    assert p[0] == u;
  }

  assert |p| == |g.adj| + 1;
  assert |p| > |g.adj|;
  assert 0 <= p[0] < |g.adj|;

  PathNodesBounded(g, p);
  DuplicateBound(p, |g.adj|);

  var first, last :|
    0 <= first < last < |p| && p[first] == p[last];

  RepeatedPathSegmentIsCycle(g, p, first, last);
  var cycle := p[first..last + 1];

  assert is_cycle(g, cycle);
  assert exists q: seq<int> :: is_cycle(g, q) by {
    assert is_cycle(g, cycle);
  }
}

ghost predicate SortState(
    g: Graph, order: seq<int>, remaining: set<int>)
{
  && |order| + |remaining| == |g.adj|

  && (forall i: int ::
        0 <= i < |order| ==> 0 <= order[i] < |g.adj|)

  && (forall x: int ::
        x in remaining ==> 0 <= x < |g.adj|)

  && (forall x: int ::
        0 <= x < |g.adj| ==>
          (x in remaining <==> x !in order))

  && (forall i: int, j: int ::
        0 <= i < j < |order| ==> order[i] != order[j])

  && (forall i: int, j: int ::
        0 <= i < |order| &&
        0 <= j < |order| &&
        has_edge(g, order[i], order[j])
        ==> i < j)

  && (forall u: int, j: int ::
        u in remaining &&
        0 <= j < |order|
        ==> !has_edge(g, u, order[j]))
}

lemma ExtendSortState(
    g: Graph, order: seq<int>, remaining: set<int>, v: int)
  requires SortState(g, order, remaining)
  requires v in remaining
  requires forall u: int ::
    u in remaining ==> !has_edge(g, u, v)
  ensures SortState(g, order + [v], remaining - {v})
{
  var nextOrder := order + [v];
  var nextRemaining := remaining - {v};

  assert v !in order;
  assert |nextRemaining| + 1 == |remaining|;

  assert forall i: int ::
    0 <= i < |nextOrder| ==> 0 <= nextOrder[i] < |g.adj| by {
    forall i: int | 0 <= i < |nextOrder|
      ensures 0 <= nextOrder[i] < |g.adj|
    {
      if i == |order| {
        assert nextOrder[i] == v;
      } else {
        assert nextOrder[i] == order[i];
      }
    }
  }

  assert forall x: int ::
    x in nextRemaining ==> 0 <= x < |g.adj|;

  assert forall x: int ::
    0 <= x < |g.adj| ==>
      (x in nextRemaining <==> x !in nextOrder) by {
    forall x: int | 0 <= x < |g.adj|
      ensures x in nextRemaining <==> x !in nextOrder
    {
      if x == v {
        assert x in nextOrder;
      } else {
        assert x in nextRemaining <==> x in remaining;
        assert x in nextOrder <==> x in order;
      }
    }
  }

  assert forall i: int, j: int ::
    0 <= i < j < |nextOrder| ==> nextOrder[i] != nextOrder[j] by {
    forall i: int, j: int |
      0 <= i < j < |nextOrder|
      ensures nextOrder[i] != nextOrder[j]
    {
      if j == |order| {
        assert nextOrder[j] == v;
        assert nextOrder[i] == order[i];
        assert order[i] in order;
      } else {
        assert nextOrder[i] == order[i];
        assert nextOrder[j] == order[j];
      }
    }
  }

  assert forall i: int, j: int ::
    0 <= i < |nextOrder| &&
    0 <= j < |nextOrder| &&
    has_edge(g, nextOrder[i], nextOrder[j])
    ==> i < j by {
    forall i: int, j: int |
      0 <= i < |nextOrder| &&
      0 <= j < |nextOrder| &&
      has_edge(g, nextOrder[i], nextOrder[j])
      ensures i < j
    {
      if j == |order| {
        if i == |order| {
          assert nextOrder[i] == v;
          assert has_edge(g, v, v);
          assert !has_edge(g, v, v);
        }
      } else if i == |order| {
        assert nextOrder[i] == v;
        assert nextOrder[j] == order[j];
        assert !has_edge(g, v, order[j]);
      } else {
        assert nextOrder[i] == order[i];
        assert nextOrder[j] == order[j];
      }
    }
  }

  assert forall u: int, j: int ::
    u in nextRemaining &&
    0 <= j < |nextOrder|
    ==> !has_edge(g, u, nextOrder[j]) by {
    forall u: int, j: int |
      u in nextRemaining && 0 <= j < |nextOrder|
      ensures !has_edge(g, u, nextOrder[j])
    {
      assert u in remaining;
      if j == |order| {
        assert nextOrder[j] == v;
      } else {
        assert nextOrder[j] == order[j];
      }
    }
  }
}

ghost predicate StrictOrdering(g: Graph, order: seq<int>)
{
  && |order| == size(g)

  && (forall i: int ::
        0 <= i < |order| ==> 0 <= order[i] < size(g))

  && (forall n: int ::
        0 <= n < size(g) ==> n in order)

  && (forall i: int, j: int ::
        0 <= i < j < |order| ==> order[i] != order[j])

  && (forall i: int, j: int ::
        0 <= i < |order| &&
        0 <= j < |order| &&
        has_edge(g, order[i], order[j])
        ==> i < j)
}

lemma FinishedStateIsStrict(g: Graph, order: seq<int>)
  requires SortState(g, order, {})
  ensures StrictOrdering(g, order)
{
  assert |order| == |g.adj|;

  forall n: int | 0 <= n < |g.adj|
    ensures n in order
  {
    assert n !in {};
  }
}

lemma StrictOrderingIsTopological(g: Graph, order: seq<int>)
  requires StrictOrdering(g, order)
  ensures is_topological_ordering(g, order)
{
  forall i: int, j: int |
    0 <= j < i < |order|
    ensures !has_edge(g, order[i], order[j])
  {
    if has_edge(g, order[i], order[j]) {
      assert i < j;
    }
  }
}

ghost function Position(order: seq<int>, value: int): nat
  requires value in order
  decreases |order|
{
  if order[0] == value then
    0
  else
    1 + Position(order[1..], value)
}

lemma PositionSpec(order: seq<int>, value: int)
  requires value in order
  ensures Position(order, value) < |order|
  ensures order[Position(order, value)] == value
  decreases |order|
{
  if order[0] != value {
    assert value in order[1..];
    PositionSpec(order[1..], value);
  }
}

lemma StrictOrderingHasNoCycle(g: Graph, order: seq<int>)
  requires well_formed(g)
  requires StrictOrdering(g, order)
  ensures !graph_has_cycle(g)
{
  if graph_has_cycle(g) {
    var p :| is_cycle(g, p);

    assert |p| > 1;

    forall k: int | 0 <= k < |p|
      ensures p[k] in order
    {
      if k < |p| - 1 {
        assert has_edge(g, p[k], p[k + 1]);
        EdgeEndpoints(g, p[k], p[k + 1]);
      } else {
        assert k > 0;
        assert has_edge(g, p[k - 1], p[k]);
        EdgeEndpoints(g, p[k - 1], p[k]);
      }
    }

    forall k: int | 0 <= k < |p|
      ensures Position(order, p[k]) < |order| &&
              order[Position(order, p[k])] == p[k]
    {
      PositionSpec(order, p[k]);
    }

    var k: nat := 0;
    while k < |p| - 1
      invariant 0 <= k <= |p| - 1
      invariant k > 0 ==>
        Position(order, p[0]) < Position(order, p[k])
      decreases |p| - 1 - k
    {
      assert has_edge(g, p[k], p[k + 1]);

      assert has_edge(
        g,
        order[Position(order, p[k])],
        order[Position(order, p[k + 1])]);

      assert Position(order, p[k]) <
             Position(order, p[k + 1]);

      k := k + 1;
    }

    assert Position(order, p[0]) <
           Position(order, p[|p| - 1]);
    assert p[0] == p[|p| - 1];
    assert false;
  }
}

method topological_sort(graph: Graph) returns (res: Option<seq<int>>)
  requires well_formed(graph)
  ensures match res {
    case Some(order) =>
      !graph_has_cycle(graph)
      && is_topological_ordering(graph, order)
    case None =>
      graph_has_cycle(graph)
  }
{
  var order: seq<int> := [];
  var remaining: set<int> := {};
  var i: nat := 0;

  while i < |graph.adj|
    invariant 0 <= i <= |graph.adj|
    invariant remaining == Nodes(i)
    decreases |graph.adj| - i
  {
    remaining := remaining + {i};
    i := i + 1;

    assert i > 0;
    assert Nodes(i) == Nodes(i - 1) + {i - 1};
    assert remaining == Nodes(i);
  }

  NodesCardinality(|graph.adj|);
  assert remaining == Nodes(|graph.adj|);

  assert forall x: int ::
    x in remaining ==> 0 <= x < |graph.adj| by {
    forall x: int | x in remaining
      ensures 0 <= x < |graph.adj|
    {
      NodesMembership(|graph.adj|, x);
    }
  }

  assert forall x: int ::
    0 <= x < |graph.adj| ==>
      (x in remaining <==> x !in order) by {
    forall x: int | 0 <= x < |graph.adj|
      ensures x in remaining <==> x !in order
    {
      NodesMembership(|graph.adj|, x);
      assert x in remaining;
      assert x !in order;
    }
  }

  assert SortState(graph, order, remaining);

  while remaining != {}
    invariant SortState(graph, order, remaining)
    decreases |remaining|
  {
    SearchSourceSpec(graph, remaining, 0);
    var source := SearchSource(graph, remaining, 0);

    match source
    case None =>
      assert forall v: int ::
        v in remaining ==> Incoming(graph, remaining, v) by {
        forall v: int | v in remaining
          ensures Incoming(graph, remaining, v)
        {
          assert 0 <= v < |graph.adj|;
        }
      }

      assert forall v: int ::
        v in remaining ==>
          exists u: int :: u in remaining && has_edge(graph, u, v) by {
        forall v: int | v in remaining
          ensures exists u: int ::
            u in remaining && has_edge(graph, u, v)
        {
          IncomingSpec(graph, remaining, v);
          var u :|
            0 <= u < |graph.adj| &&
            u in remaining &&
            has_edge(graph, u, v);
        }
      }

      RemainingContainsCycle(graph, remaining);
      res := None;
      return;

    case Some(v) =>
      assert v in remaining;
      assert !Incoming(graph, remaining, v);
      IncomingSpec(graph, remaining, v);

      assert forall u: int ::
        u in remaining ==> !has_edge(graph, u, v) by {
        forall u: int | u in remaining
          ensures !has_edge(graph, u, v)
        {
          assert 0 <= u < |graph.adj|;
          if has_edge(graph, u, v) {
            assert exists w: int ::
              0 <= w < |graph.adj| &&
              w in remaining &&
              has_edge(graph, w, v) by {
              assert 0 <= u < |graph.adj|;
            }
            assert Incoming(graph, remaining, v);
          }
        }
      }

      ExtendSortState(graph, order, remaining, v);
      order := order + [v];
      remaining := remaining - {v};
  }

  FinishedStateIsStrict(graph, order);
  StrictOrderingHasNoCycle(graph, order);
  StrictOrderingIsTopological(graph, order);

  res := Some(order);
}
