method check_prime(n: int) returns (res: bool)
  // Simulate u64: input is non-negative
  requires n >= 0
  ensures res == is_prime(n)
{
  if n < 2 {
    return false;
  }
  var i := 2;
  while i < n
    invariant 2 <= i <= n
    invariant forall d :: 1 < d < i ==> !divides(d, n)
    decreases n - i
  {
    if n % i == 0 {
      assert 1 < i < n && divides(i, n);
      return false;
    }
    i := i + 1;
  }
  return true;
}

