method check_prime(n: int) returns (res: bool)
  // Simulate u64: input is non-negative
  requires n >= 0
  ensures res == is_prime(n)
{
  if n <= 1 {
    assert !is_prime(n);
    return false;
  }

  var d := 2;
  while d < n
    invariant 2 <= d <= n
    invariant forall k: int :: 1 < k < d ==> !divides(k, n)
    decreases n - d
  {
    if n % d == 0 {
      assert divides(d, n);
      assert 1 < d < n;
      assert !is_prime(n) by {
        if is_prime(n) {
          assert !divides(d, n);
        }
      }
      return false;
    }

    assert !divides(d, n);
    d := d + 1;
  }

  assert d == n;
  assert forall k: int :: 1 < k < n ==> !divides(k, n);
  assert is_prime(n);
  return true;
}

