                var char_idx := key[0];
                assert key[0] in key;
                assert 0 <= char_idx < 256;
                assert 0 <= char_idx < |n.children|;

                match n.children[char_idx] {
                    case None =>
                        res := false;
                        assert !n.contains(key);
                        assert (key in n.view()) <==> n.contains(key);
                        assert opt_view(Some(n)) == n.view();

                    case Some(child) =>
                        assert child.well_formed();
                        assert |child.children| == 256;
                        assert !child.is_empty();
                        assert opt_well_formed(Some(child));

                        res := search(Some(child), key[1..]);

                        assert opt_view(Some(child)) == child.view();
                        assert (key[1..] in child.view())
                            <==> child.contains(key[1..]);
                        assert n.contains(key)
                            == child.contains(key[1..]);
                        assert (key in n.view()) <==> n.contains(key);
                        assert opt_view(Some(n)) == n.view();
                }
            }
    }
}
